/** §correctif retour QA du 27/08/2026 (point 2) : table de correspondance préfixe de sourceKey ->
 * module requis, remontée ici depuis tests/module-gating.test.js (qui la dupliquait en local, "elle
 * n'existe nulle part dans l'application") — génération (syncNotifications), purge
 * (pruneUnsubscribedModuleNotifications) et affichage (getVisibleNotificationsForCurrentUser)
 * partagent désormais la même source de vérité, au lieu que le test ne certifie que la moitié
 * corrigée (la génération) pendant qu'une fuite survivait dans ce qui restait en base et dans
 * l'affichage. Ordre important : 'entretien-pro-' doit être vérifié AVANT 'entretien-' (préfixe plus
 * spécifique), sinon un rappel de bilan professionnel (module rh) serait confondu avec un entretien
 * planifié (module entretiens) — les deux sourceKeys commencent par "entretien-". */
const SOURCE_KEY_MODULE_RULES = [
  { prefix: 'leave-', module: 'conges' },
  { prefix: 'telework-', module: 'planning' },
  { prefix: 'expense-', module: 'frais' },
  { prefix: 'cloture-perte-', module: 'conges' },
  { prefix: 'relance-', module: null }, // dépend de la demande d'origine (leave/telework/expense), déjà couverte par son propre filtre en amont
  { prefix: 'escalade-', module: null },
  { prefix: 'entretien-pro-', module: 'rh' },
  { prefix: 'bilan-six-ans-', module: 'rh' },
  { prefix: 'birthday-', module: 'rh' },
  { prefix: 'seniority-', module: 'rh' },
  { prefix: 'contract-end-', module: 'rh' },
  { prefix: 'probation-end-', module: 'rh' },
  { prefix: 'visite-medicale-', module: 'rh' },
  { prefix: 'document-expiry-', module: 'rh' },
  { prefix: 'entretien-', module: 'entretiens' },
  { prefix: 'ticket-status-', module: null }, // support : fonctionnalité de base, jamais liée à un module à la carte
  { prefix: 'licence-liberee-', module: null }, // §point 8 : concerne la gestion de l'abonnement elle-même, pas le module libéré
];

/** module requis pour un sourceKey donné, ou null si aucun (notification de base). Lève une erreur
 * explicite pour un sourceKey sans règle connue plutôt que de laisser fuiter silencieusement une
 * notification jamais vérifiée — voir SOURCE_KEY_MODULE_RULES ci-dessus. */
function requiredModuleForSourceKey(sourceKey) {
  const rule = SOURCE_KEY_MODULE_RULES.find(r => sourceKey.startsWith(r.prefix));
  if (!rule) throw new Error(`sourceKey sans règle connue : "${sourceKey}" — ajouter une entrée à SOURCE_KEY_MODULE_RULES (app.js)`);
  return rule.module;
}

/** true si l'entreprise a accès à ce module (voir LANDING_ALACARTE_MODULES) — toujours vrai pour un
 * abonnement classique (essai/essentiel/professionnel/premium : toujours tout inclus, aucune
 * migration forcée vers l'à la carte, voir upsertSubscriptionFromStripeSubscription dans
 * billing/index.ts), seulement si présent dans abonnement.modules pour un abonnement à la carte. */
function hasModule(moduleKey) {
  const company = companyRepository.getCurrent();
  const abo = company && company.abonnement;
  if (!abo || abo.offre !== 'a_la_carte') return true;
  return (abo.modules || []).some(m => m.key === moduleKey);
}

/** §correctif audit du 23/08/2026 (§4, brique 2) : hasModule() n'était appelé qu'à 4 endroits avant
 * cet audit — tout raccourci/bouton/carte qui pointe vers un module non souscrit (offre à la
 * carte) restait affiché normalement, menant vers un écran bloqué seulement une fois cliqué
 * (isViewBlockedForCurrentUser, §2.9). ifModule() encapsule le garde pour un fragment HTML inline
 * (raccourcis de tableau de bord, cartes KPI ponctuelles...) sans dupliquer le if/else à chaque
 * appel — retourne '' si le module n'est pas souscrit, le HTML sinon. */
function ifModule(moduleKey, html) {
  return hasModule(moduleKey) ? html : '';
}

/** Modules réellement verrouillés par has_module_license() côté serveur (0059) : seuls
 * leave_requests/telework_requests/expenses ont une policy d'INSERT qui vérifie une licence
 * nominative. Étendre cette liste suppose d'abord d'ajouter la policy SQL correspondante,
 * sinon l'UI promettrait un verrou que le serveur ne tient pas. */
const LICENSED_MODULE_KEYS = ['conges', 'planning', 'frais'];

/** §retour Betty du 18/09/2026 (point 8, "les licences par module") : hasModule() ci-dessus ne
 * vérifie que la présence du module dans l'abonnement de l'entreprise, jamais QUI a un siège
 * attribué parmi les places achetées (subscription_modules ne contient que la quantité, écrite par
 * Stripe/le service-role, voir 0023) — d'où module_licenses (0059), l'attribution nominative, et
 * has_module_license() côté SQL (le vrai verrou, appliqué aux policies d'INSERT). Ce miroir client
 * sert seulement à guider l'affichage AVANT l'envoi (bouton bloqué, message clair) : la policy
 * serveur reste la seule vérité, jamais contournable depuis ici. Reprend exactement la même logique :
 * hors offre à la carte → toujours vrai ; Propriétaire/RH exemptés (administrer un module payé ne
 * consomme pas un siège personnel) ; sinon, présence dans company.moduleLicenses[moduleKey]. */
function hasModuleLicense(employee, moduleKey) {
  if (!employee) return false;
  const company = companyRepository.getCurrent();
  const abo = company && company.abonnement;
  if (!abo || abo.offre !== 'a_la_carte') return true;
  if (!hasModule(moduleKey)) return false;
  if (employee.role === 'rh' || employee.role === 'proprietaire') return true;
  const beneficiaires = (company.moduleLicenses && company.moduleLicenses[moduleKey]) || [];
  return beneficiaires.includes(employee.id);
}

/** Employés RH/Propriétaire exclus : exemptés (voir hasModuleLicense), jamais comptés dans le
 * quota ni proposés dans "Gérer les accès" — leur accès administratif n'a jamais consommé de siège. */
function licenseAssignableEmployees() {
  return employeeRepository.getAll().filter(e => !e.archive && e.role !== 'rh' && e.role !== 'proprietaire');
}

function licenseSummaryForModule(moduleKey, quantite) {
  const company = companyRepository.getCurrent();
  if (!company) return { assigned: 0, quantite, beneficiaires: [], employees: [] };
  const beneficiaires = (company.moduleLicenses && company.moduleLicenses[moduleKey]) || [];
  const employees = licenseAssignableEmployees();
  const assigned = beneficiaires.filter(id => employees.some(e => e.id === id)).length;
  return { assigned, quantite, beneficiaires, employees };
}

/** §retour Betty du 18/09/2026 : la seule action possible ici est cocher/décocher un salarié — pas
 * de bouton "Enregistrer" séparé, chaque case appelle directement grant/revokeModuleLicense et
 * remet à jour la modale, pour que le compteur X/Y ne mente jamais entre deux clics. */
function openGererLicencesModal(moduleKey) {
  const moduleDef = LANDING_ALACARTE_MODULES.find(m => m.key === moduleKey);
  const abo = companyRepository.getCurrent().abonnement;
  const aboModule = (abo.modules || []).find(m => m.key === moduleKey);
  const quantite = aboModule ? aboModule.quantite : 0;

  function renderBody() {
    const { assigned, employees, beneficiaires } = licenseSummaryForModule(moduleKey, quantite);
    const atCapacite = assigned >= quantite;
    return `
      <p>
        <span class="badge badge-${atCapacite ? 'warning' : 'muted'}">${assigned}/${quantite} attribuées</span>
        ${atCapacite ? ' Capacité atteinte : décochez un bénéficiaire pour en ajouter un autre, ou ajustez la quantité souscrite.' : ''}
      </p>
      ${atCapacite ? `<button type="button" class="btn-link" id="btn-ajuster-abonnement-licence">Ajuster l'abonnement</button>` : ''}
      <table class="table" style="margin-top: 12px;">
        <thead><tr><th>Salarié</th><th>Rôle</th><th>Accès</th></tr></thead>
        <tbody>
          ${employees.map(e => {
            const licencie = beneficiaires.includes(e.id);
            const disabled = !licencie && atCapacite;
            return `
              <tr>
                <td>${personNameHtml(e)}</td>
                <td>${escapeHtml(ROLE_LABELS[e.role] || e.role)}</td>
                <td>
                  <label style="display:inline-flex; align-items:center; gap:6px;">
                    <input type="checkbox" data-licence-employee="${e.id}" ${licencie ? 'checked' : ''} ${disabled ? 'disabled' : ''}>
                    ${licencie ? 'Accès accordé' : (disabled ? 'Capacité atteinte' : 'Accorder l\'accès')}
                  </label>
                </td>
              </tr>
            `;
          }).join('') || '<tr><td colspan="3" class="text-muted">Aucun salarié éligible.</td></tr>'}
        </tbody>
      </table>
    `;
  }

  const html = `
    <div class="modal modal-large">
      <div class="modal-header">
        <h2>Accès au module « ${escapeHtml(moduleDef ? moduleDef.label : moduleKey)} »</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <div class="modal-body" id="licences-modal-body">${renderBody()}</div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Fermer</button>
      </div>
    </div>
  `;
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');
  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);

  function bindBody() {
    const ajusterBtn = document.getElementById('btn-ajuster-abonnement-licence');
    if (ajusterBtn) ajusterBtn.addEventListener('click', () => {
      closeModal();
      state.abonnementEditingModules = true;
      render();
    });
    document.querySelectorAll('[data-licence-employee]').forEach(cb => {
      cb.addEventListener('change', async () => {
        const employeeId = cb.dataset.licenceEmployee;
        const company = companyRepository.getCurrent();
        cb.disabled = true;
        try {
          if (cb.checked) {
            await window.SupabaseSync.grantModuleLicense(company.id, moduleKey, employeeId, authRepository.getCurrentUser().id);
          } else {
            await window.SupabaseSync.revokeModuleLicense(company.id, moduleKey, employeeId);
          }
          const refreshed = await window.SupabaseSync.hydrateCurrentCompany();
          if (refreshed) DB._companiesCache = [refreshed];
        } catch (err) {
          showToast('Impossible de mettre à jour cet accès : ' + (err.message || err), 'error');
        }
        document.getElementById('licences-modal-body').innerHTML = renderBody();
        bindBody();
      });
    });
  }
  bindBody();
}

/** §retour Betty du 18/09/2026 (point 8) : "employé archivé/parti : libération automatique + me
 * notifier" — appelé au moment de l'archivage et au moment où une date de départ est enregistrée
 * (voir les deux points d'appel dans bindEmployeeDetailEvents/submitEmployeeForm). Le siège redevient
 * disponible pour quelqu'un d'autre ; les données déjà produites (congés, notes de frais...) ne sont
 * pas concernées, ceci ne retire QUE l'accès personnel nominatif. Best-effort : une erreur réseau ne
 * doit jamais bloquer l'archivage/le départ lui-même, déjà enregistrés au moment de l'appel. */
async function releaseModuleLicensesForDeparture(employee) {
  const company = companyRepository.getCurrent();
  const liberees = [];
  for (const key of LICENSED_MODULE_KEYS) {
    const beneficiaires = (company.moduleLicenses && company.moduleLicenses[key]) || [];
    if (!beneficiaires.includes(employee.id)) continue;
    try {
      await window.SupabaseSync.revokeModuleLicense(company.id, key, employee.id);
      liberees.push(key);
    } catch (err) { /* best-effort : ne bloque jamais l'archivage/le départ */ }
  }
  if (!liberees.length) return;
  try {
    const refreshed = await window.SupabaseSync.hydrateCurrentCompany();
    if (refreshed) DB._companiesCache = [refreshed];
  } catch (err) { /* la libération elle-même a réussi, seul le rafraîchissement du cache a échoué */ }
  const labels = liberees.map(key => (LANDING_ALACARTE_MODULES.find(m => m.key === key) || {}).label || key);
  notificationRepository.addNotificationsIfNew([
    makeNotification(`licence-liberee-${employee.id}-${Date.now()}`, ICONS.card, 'Licence(s) libérée(s)',
      `${employee.prenom} ${employee.nom} a quitté l'entreprise : accès retiré pour ${labels.join(', ')}. Le siège reste disponible pour un autre salarié.`,
      'parametres', { parametresTab: 'abonnement' }, employee.id)
  ]);
  updateNotifBadge();
  render();
}

/** true immédiatement si la nouvelle quantité couvre déjà les accès attribués ; sinon ouvre la
 * modale de choix et ne se résout qu'une fois assez d'accès retirés (true) ou l'opération annulée
 * (false) — jamais un choix automatique, voir openReduireLicencesModal. nouvelleQuantite à 0
 * couvre le cas d'un module entièrement décoché dans le composeur (revient à retirer tous les accès). */
function ensureLicenseCapacity(moduleKey, nouvelleQuantite) {
  if (!LICENSED_MODULE_KEYS.includes(moduleKey)) return Promise.resolve(true);
  const { assigned } = licenseSummaryForModule(moduleKey, nouvelleQuantite);
  if (assigned <= nouvelleQuantite) return Promise.resolve(true);
  return new Promise((resolve) => openReduireLicencesModal(moduleKey, nouvelleQuantite, assigned, resolve));
}

function openReduireLicencesModal(moduleKey, nouvelleQuantite, assigned, resolve) {
  const moduleDef = LANDING_ALACARTE_MODULES.find(m => m.key === moduleKey);
  const aRetirer = assigned - nouvelleQuantite;
  const { beneficiaires, employees } = licenseSummaryForModule(moduleKey, nouvelleQuantite);
  const licencies = employees.filter(e => beneficiaires.includes(e.id));
  let annule = false;

  function renderBody() {
    const cochees = document.querySelectorAll('[data-a-retirer]:checked').length;
    return `
      <p>Cette quantité (${nouvelleQuantite}) ne couvre plus les ${assigned} accès actuellement attribués au module « ${escapeHtml(moduleDef ? moduleDef.label : moduleKey)} ». Choisissez ${aRetirer} salarié${aRetirer > 1 ? 's' : ''} à qui retirer l'accès pour continuer${nouvelleQuantite === 0 ? ' (module retiré de l\'abonnement)' : ''}.</p>
      <table class="table" style="margin-top: 12px;">
        <thead><tr><th>Salarié</th><th>Retirer l'accès</th></tr></thead>
        <tbody>
          ${licencies.map(e => `
            <tr>
              <td>${personNameHtml(e)}</td>
              <td><input type="checkbox" data-a-retirer="${e.id}"></td>
            </tr>
          `).join('')}
        </tbody>
      </table>
      <p class="form-hint" id="retrait-licence-compteur">${cochees}/${aRetirer} sélectionné${aRetirer > 1 ? 's' : ''}.</p>
    `;
  }

  const html = `
    <div class="modal modal-large">
      <div class="modal-header">
        <h2>Quantité insuffisante pour les accès attribués</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <div class="modal-body" id="retrait-licence-body">${renderBody()}</div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
        <button type="button" class="btn btn-primary" id="btn-confirm-retrait-licence" disabled>Confirmer le retrait</button>
      </div>
    </div>
  `;
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');

  function finish(result) {
    if (annule) return;
    annule = true;
    closeModal();
    resolve(result);
  }
  document.getElementById('btn-close-modal').addEventListener('click', () => finish(false));
  document.getElementById('btn-cancel-modal').addEventListener('click', () => finish(false));

  function bindBody() {
    document.querySelectorAll('[data-a-retirer]').forEach(cb => {
      cb.addEventListener('change', () => {
        const cochees = document.querySelectorAll('[data-a-retirer]:checked').length;
        document.getElementById('retrait-licence-compteur').textContent = `${cochees}/${aRetirer} sélectionné${aRetirer > 1 ? 's' : ''}.`;
        document.getElementById('btn-confirm-retrait-licence').disabled = cochees < aRetirer;
      });
    });
  }
  bindBody();

  document.getElementById('btn-confirm-retrait-licence').addEventListener('click', async () => {
    const btn = document.getElementById('btn-confirm-retrait-licence');
    btn.disabled = true;
    btn.textContent = 'Retrait...';
    const company = companyRepository.getCurrent();
    const aRetirerIds = Array.from(document.querySelectorAll('[data-a-retirer]:checked')).map(cb => cb.dataset.aRetirer);
    try {
      for (const employeeId of aRetirerIds) {
        await window.SupabaseSync.revokeModuleLicense(company.id, moduleKey, employeeId);
      }
      const refreshed = await window.SupabaseSync.hydrateCurrentCompany();
      if (refreshed) DB._companiesCache = [refreshed];
    } catch (err) {
      showToast('Impossible de retirer ces accès : ' + (err.message || err), 'error');
      finish(false);
      return;
    }
    finish(true);
  });
}

/** user : l'objet salarié complet (pas juste son rôle), pour pouvoir consulter ses éventuelles
 * surcharges de permissions individuelles (§8) en plus du défaut de son rôle. */
/** Ce que ce rôle/ces permissions/les modules souscrits par l'entreprise autoriseraient
 * normalement, AVANT toute restriction manuelle par salarié (menusDesactives) — sert à la fois de
 * base à navItemsForRole ci-dessous et de liste de cases à cocher dans renderMenusAutorisesCard. */
function baseNavItemsForRole(user) {
  return NAV_ITEMS.filter(item => {
    if (item.module && !hasModule(item.module)) return false;
    if (item.permissions) return item.permissions.some(p => hasPermission(user, p));
    return item.roles.includes(user.role);
  });
}

/** §retour du 21/08/2026 "pouvoir enlever l'accès à tous les menus" : au-delà du rôle/des
 * permissions/des modules souscrits (baseNavItemsForRole), un administrateur peut retirer
 * individuellement des menus à CE salarié (voir renderMenusAutorisesCard) — sauf "Accueil",
 * toujours conservé comme page de repli (voir navigateTo, qui y redirige quand une vue demandée
 * n'est plus autorisée). */
function navItemsForRole(user) {
  const desactives = new Set(user.menusDesactives || []);
  return baseNavItemsForRole(user).filter(item => item.key === 'dashboard' || !desactives.has(item.key));
}

// ---------------------------------------------------------------------------
// Page publique de candidature (QR code "Embauche", voir renderEmbauche)
// ---------------------------------------------------------------------------

/** Écran entièrement autonome : ni DB.init(), ni SupabaseSync côté rendu initial. L'en-tête affiche
 * par défaut la marque Nexus (repli immédiat, formulaire utilisable sans attendre le réseau), puis
 * bascule sur le nom + logo de l'entreprise ciblée dès que get_company_public_info répond (voir
 * populateCandidatureCompanyHeader) — seule lecture publique de toute l'app limitée à ces deux
 * champs (0025_company_logo.sql), jamais le reste de `companies`. */
function renderCandidatureForm(companyId) {
  const root = document.getElementById('candidature-root');
  document.getElementById('login-root').style.display = 'none';
  document.getElementById('landing-root').style.display = 'none';
  root.style.display = 'flex';
  root.innerHTML = `
    <div class="login-card">
      <div class="login-logo" id="candidature-company-header">${NEXUS_LOGO_MARK} Nexus</div>
      <h1>Déposer ma candidature</h1>
      <p class="text-muted">Renseignez vos coordonnées et joignez votre CV, l'entreprise recevra votre candidature directement.</p>
      <p class="login-error" id="candidature-error" role="alert" style="display: none;"></p>
      <form id="candidature-form">
        <!-- D16 (audit fiabilité du 19/08/2026) : honeypot anti-robot, jamais visible ni atteignable
             au clavier pour un vrai visiteur (position hors-écran, pas display:none — certains
             robots ignorent justement display:none) — voir candidature-submit/index.ts, qui rejette
             silencieusement toute soumission où ce champ n'est pas vide. -->
        <div style="position: absolute; left: -9999px; top: -9999px; opacity: 0; height: 0; width: 0; overflow: hidden;" aria-hidden="true">
          <label for="cand-honeypot">Ne pas remplir ce champ</label>
          <input type="text" id="cand-honeypot" name="site_web" tabindex="-1" autocomplete="off">
        </div>
        <div class="form-grid">
          <div class="form-field"><label>Prénom</label><input type="text" class="input" id="cand-prenom"></div>
          <div class="form-field"><label>Nom *</label><input type="text" class="input" id="cand-nom" required></div>
        </div>
        <div class="form-field"><label>Email *</label><input type="email" class="input" id="cand-email" required></div>
        <div class="form-field"><label>Téléphone</label><input type="tel" class="input" id="cand-telephone"></div>
        <div id="candidature-postes-field"></div>
        <div class="form-field"><label>CV (PDF, PNG ou JPEG) *</label><input type="file" class="input" id="cand-cv" accept=".pdf,.png,.jpg,.jpeg" required></div>
        <div class="form-field"><label>Lettre de motivation (fichier, optionnel)</label><input type="file" class="input" id="cand-lettre-fichier" accept=".pdf,.png,.jpg,.jpeg"></div>
        <div class="form-field"><label>Ou votre message (optionnel)</label><textarea class="input" id="cand-lettre-texte" rows="4" placeholder="Quelques mots sur votre candidature..."></textarea></div>
        <button type="submit" class="btn btn-primary" style="width: 100%; margin-top: 4px;" id="btn-submit-candidature">Envoyer ma candidature</button>
      </form>
    </div>
  `;
  bindCandidatureFormEvents(companyId);
  populateCandidatureCompanyHeader(companyId);
}

async function populateCandidatureCompanyHeader(companyId) {
  if (!window.SupabaseSync) return;
  try {
    const info = await window.SupabaseSync.getCompanyPublicInfo(companyId);
    const header = document.getElementById('candidature-company-header');
    if (header && info && info.raisonSociale) {
      header.innerHTML = `
        ${info.logo ? `<img src="${escapeHtml(info.logo)}" alt="${escapeHtml(info.raisonSociale)}" style="max-width: 40px; max-height: 40px; border-radius: var(--radius-sm);">` : ''}
        <span>${escapeHtml(info.raisonSociale)}</span>
      `;
    }
    // Postes ouverts (gérés depuis l'écran Embauche) : champ entièrement absent si l'entreprise n'a
    // rien renseigné, plutôt qu'une case vide sans intérêt pour le candidat. §demande 18/08/2026 :
    // panneau déroulant (comme le menu mobile) plutôt qu'une liste de cases toujours dépliée — un
    // candidat voit d'abord un simple bouton, la liste ne prend de place qu'une fois ouverte.
    const postesField = document.getElementById('candidature-postes-field');
    if (postesField && info && Array.isArray(info.postesOuverts) && info.postesOuverts.length > 0) {
      const postes = info.postesOuverts.map(normalizePoste);
      // §retour Betty du 14/09/2026 (Embauche point 2) : venu de la page carrière avec un poste
      // précis (?poste=...), le candidat n'a pas à le resélectionner — jamais imposé pour autant
      // (un candidat arrivant directement par le lien de candidature général reste libre de tout
      // choisir lui-même).
      const posteParam = new URLSearchParams(window.location.search).get('poste');
      postesField.innerHTML = `
        <div class="form-field">
          <label>Poste(s) souhaité(s)</label>
          <div class="poste-dropdown">
            <button type="button" class="input poste-dropdown-toggle" id="btn-poste-dropdown" aria-expanded="false">
              <span id="poste-dropdown-label">Sélectionner un ou plusieurs postes</span>
              <span class="poste-dropdown-arrow">▾</span>
            </button>
            <div class="poste-dropdown-panel" id="poste-dropdown-panel">
              ${postes.map((poste, i) => `
                <label class="poste-dropdown-option">
                  <input type="checkbox" class="cand-poste-checkbox" value="${escapeHtml(poste.nom)}" ${posteParam === poste.nom ? 'checked' : ''}>
                  <span>${escapeHtml(poste.nom)}</span>
                  <span class="text-muted" style="font-size: 12px;">${poste.quantite} poste${poste.quantite > 1 ? 's' : ''} dispo.</span>
                </label>
              `).join('')}
            </div>
          </div>
        </div>
      `;
      bindPosteDropdownEvents();
    }
  } catch {
    // Repli silencieux sur la marque Nexus déjà affichée — jamais bloquer le formulaire pour ça.
  }
}

/** Page carrière publique (§retour Betty du 14/09/2026, Embauche point 2) : liste les postes
 * ouverts un par un, chacun renvoyant vers le formulaire de candidature déjà existant avec le poste
 * présélectionné — même écran autonome que renderCandidatureForm (pas de DB.init(), pas de compte),
 * réutilise get_company_public_info (déjà public, 0027_candidature_postes.sql), aucun nouvel accès
 * serveur nécessaire. */
async function renderCarrierePage(companyId) {
  const root = document.getElementById('candidature-root');
  document.getElementById('login-root').style.display = 'none';
  document.getElementById('landing-root').style.display = 'none';
  root.style.display = 'flex';
  root.innerHTML = `
    <div class="login-card">
      <div class="login-logo" id="carriere-company-header">${NEXUS_LOGO_MARK} Nexus</div>
      <h1>Nos postes ouverts</h1>
      <p class="text-muted" id="carriere-postes-intro">Chargement des offres...</p>
      <div id="carriere-postes-list"></div>
    </div>
  `;
  if (!window.SupabaseSync) {
    document.getElementById('carriere-postes-intro').textContent = 'Impossible de charger les offres (problème réseau). Rechargez la page.';
    return;
  }
  try {
    const info = await window.SupabaseSync.getCompanyPublicInfo(companyId);
    const header = document.getElementById('carriere-company-header');
    if (header && info && info.raisonSociale) {
      header.innerHTML = `
        ${info.logo ? `<img src="${escapeHtml(info.logo)}" alt="${escapeHtml(info.raisonSociale)}" style="max-width: 40px; max-height: 40px; border-radius: var(--radius-sm);">` : ''}
        <span>${escapeHtml(info.raisonSociale)}</span>
      `;
    }
    const postes = (info && Array.isArray(info.postesOuverts) ? info.postesOuverts : []).map(normalizePoste);
    const introEl = document.getElementById('carriere-postes-intro');
    const listEl = document.getElementById('carriere-postes-list');
    if (!postes.length) {
      introEl.textContent = 'Aucun poste ouvert au recrutement pour le moment.';
      return;
    }
    introEl.textContent = `${postes.length} poste${postes.length > 1 ? 's' : ''} à pourvoir actuellement.`;
    listEl.innerHTML = postes.map(poste => `
      <div class="card" style="text-align: left; margin-top: 12px; display: flex; justify-content: space-between; align-items: center; gap: 12px;">
        <div>
          <strong>${escapeHtml(poste.nom)}</strong><br>
          <span class="text-muted" style="font-size: 12px;">${poste.quantite} poste${poste.quantite > 1 ? 's' : ''} disponible${poste.quantite > 1 ? 's' : ''}</span>
        </div>
        <a class="btn btn-primary btn-sm" href="?candidature=${encodeURIComponent(companyId)}&poste=${encodeURIComponent(poste.nom)}">Postuler</a>
      </div>
    `).join('');
  } catch {
    document.getElementById('carriere-postes-intro').textContent = 'Impossible de charger les offres pour le moment.';
  }
}

/** Chaque poste vient soit d'une ancienne liste de simples chaînes (avant le 18/08/2026), soit du
 * nouveau format {nom, quantite} (voir renderPostesOuvertsCard) — get_company_public_info renvoie
 * le JSON brut de settings.postesOuverts tel quel, sans jamais migrer les données existantes. */
function normalizePoste(p) {
  if (typeof p === 'string') return { nom: p, quantite: 1 };
  const quantite = Number(p.quantite);
  return { nom: p.nom || '', quantite: quantite > 0 ? quantite : 1 };
}

/** Ouverture/fermeture du panneau de sélection de poste (public, formulaire de candidature) — même
 * patron que .notif-wrapper/le menu mobile : bouton statique lié une seule fois, fermeture au clic
 * extérieur. Le libellé du bouton reflète la sélection courante pour que le candidat sache ce qu'il
 * a choisi une fois le panneau refermé. */
function bindPosteDropdownEvents() {
  const toggle = document.getElementById('btn-poste-dropdown');
  const panel = document.getElementById('poste-dropdown-panel');
  const label = document.getElementById('poste-dropdown-label');
  if (!toggle || !panel) return;

  const updateLabel = () => {
    const checked = Array.from(panel.querySelectorAll('.cand-poste-checkbox:checked'));
    label.textContent = checked.length === 0
      ? 'Sélectionner un ou plusieurs postes'
      : checked.length === 1 ? checked[0].value : `${checked.length} postes sélectionnés`;
  };

  toggle.addEventListener('click', (e) => {
    e.stopPropagation();
    const open = panel.classList.toggle('open');
    toggle.setAttribute('aria-expanded', String(open));
  });
  panel.querySelectorAll('.cand-poste-checkbox').forEach(cb => cb.addEventListener('change', updateLabel));
  // §correctif visuel du 14/09/2026 : arrivé depuis la page carrière avec un poste présélectionné
  // (?poste=..., voir populateCandidatureCompanyHeader), la case était bien cochée mais le bouton
  // affichait quand même "Sélectionner un ou plusieurs postes" tant que personne n'y touchait — le
  // libellé ne se mettait à jour que sur un événement "change", jamais à l'affichage initial.
  updateLabel();
  document.addEventListener('click', (e) => {
    if (!e.target.closest('.poste-dropdown')) {
      panel.classList.remove('open');
      toggle.setAttribute('aria-expanded', 'false');
    }
  });
}

function bindCandidatureFormEvents(companyId) {
  const form = document.getElementById('candidature-form');
  const errorEl = document.getElementById('candidature-error');
  form.addEventListener('submit', async (evt) => {
    evt.preventDefault();
    errorEl.style.display = 'none';
    if (!window.SupabaseSync) {
      errorEl.textContent = 'Impossible de charger le formulaire (problème réseau). Rechargez la page.';
      errorEl.style.display = 'block';
      return;
    }
    const submitBtn = document.getElementById('btn-submit-candidature');
    submitBtn.disabled = true;
    submitBtn.textContent = 'Envoi en cours...';

    const formData = new FormData();
    formData.set('company_id', companyId);
    formData.set('site_web', document.getElementById('cand-honeypot').value);
    // §retour Betty du 17/09/2026 ("pour que le candidat converti en salarié arrive déjà propre") :
    // même mise en forme que DB.addEmployee/updateEmployee (data.js), appliquée ici aussi puisque
    // cette candidature est envoyée directement à submitCandidature, jamais via employeeRepository.
    formData.set('nom', formatNomFamille(document.getElementById('cand-nom').value));
    formData.set('prenom', formatPrenom(document.getElementById('cand-prenom').value));
    formData.set('email', document.getElementById('cand-email').value.trim());
    formData.set('telephone', document.getElementById('cand-telephone').value.trim());
    formData.set('lettre_texte', document.getElementById('cand-lettre-texte').value.trim());
    const postesChoisis = Array.from(document.querySelectorAll('.cand-poste-checkbox:checked')).map(cb => cb.value);
    formData.set('postes', JSON.stringify(postesChoisis));
    const cvFile = document.getElementById('cand-cv').files[0];
    const lettreFile = document.getElementById('cand-lettre-fichier').files[0];
    if (cvFile) formData.set('cv', cvFile);
    if (lettreFile) formData.set('lettre', lettreFile);

    const result = await window.SupabaseSync.submitCandidature(formData);
    if (!result.success) {
      errorEl.textContent = result.error || 'Impossible d\'envoyer la candidature.';
      errorEl.style.display = 'block';
      submitBtn.disabled = false;
      submitBtn.textContent = 'Envoyer ma candidature';
      return;
    }

    // Réutilise le contenu déjà affiché du bandeau entreprise (logo + nom, voir
    // populateCandidatureCompanyHeader) plutôt que de tout écraser en revenant à la marque Nexus —
    // le candidat doit voir la même entreprise du début à la fin, jamais "Nexus" réapparaître.
    const headerHtml = document.getElementById('candidature-company-header').innerHTML;
    document.getElementById('candidature-root').innerHTML = `
      <div class="login-card">
        <div class="login-logo">${headerHtml}</div>
        <h1>Candidature envoyée ${icon(ICONS.checkCircle, 22)}</h1>
        <p class="text-muted">Merci ! Votre candidature a bien été transmise à l'entreprise.</p>
      </div>
    `;
  });
}

// ---------------------------------------------------------------------------
// Initialisation
// ---------------------------------------------------------------------------

document.addEventListener('DOMContentLoaded', async () => {
  // Page de candidature publique (QR code "Embauche", voir renderEmbauche) — avant TOUT le reste :
  // ni compte, ni entreprise locale, ni SupabaseSync (le dépôt de candidature passe par un simple
  // fetch() vers l'Edge Function, jamais par le client Supabase authentifié). Sortie immédiate pour
  // ne jamais laisser DB.init()/le routage normal s'exécuter sur cette page sans rapport.
  // Page carrière publique (?carriere=<companyId>, voir renderCarrierePage) : même routage précoce
  // que la candidature ci-dessous, testée EN PREMIER (une URL ne porte jamais les deux paramètres à
  // la fois, mais autant garder un ordre explicite).
  const carriereCompanyId = new URLSearchParams(window.location.search).get('carriere');
  if (carriereCompanyId) {
    renderCarrierePage(carriereCompanyId);
    return;
  }
  const candidatureCompanyId = new URLSearchParams(window.location.search).get('candidature');
  if (candidatureCompanyId) {
    renderCandidatureForm(candidatureCompanyId);
    return;
  }

  DB.onSaveError = (message) => { showToast(message, 'error'); renderSyncFailureBanner(); };
  DB.onSaveSuccess = () => renderSyncFailureBanner();
  // D3 (audit fiabilité du 19/08/2026) : avertissement natif du navigateur si des écritures
  // restent en attente — depuis le point 2.6, ce n'est plus la seule protection (une vraie file
  // persistée les rejoue automatiquement au prochain chargement/à la reconnexion, voir
  // retryPendingSyncNow ci-dessous et dans showApp) mais fermer volontairement l'onglet reste
  // évitable, donc toujours signalé.
  window.addEventListener('beforeunload', (evt) => {
    const companyId = DB.getCurrentCompanyId();
    if (companyId && DB.getPendingSyncCount(companyId) > 0) {
      evt.preventDefault();
      evt.returnValue = '';
    }
  });

  // §retour QA du 26/08/2026 (point 2.6) : reconnexion réseau — la file d'attente n'a pas besoin
  // d'attendre le prochain chargement de page pour se rattraper, un retour de connexion suffit.
  window.addEventListener('online', () => {
    const companyId = DB.getCurrentCompanyId();
    if (companyId) DB.retryPendingSyncNow(companyId).then(() => renderSyncFailureBanner());
  });

  // §correctif retour QA du 26/08/2026 (point A.1/E.3) : "il n'y a ni window.onerror ni gestionnaire
  // de promesse non traitée dans toute l'application" — une seule exception dans une fonction
  // d'affichage laissait #view-root vide, silencieusement. render() lui-même est désormais protégé
  // (voir sa définition), mais une exception dans un GESTIONNAIRE D'ÉVÉNEMENT (un clic, un .then()
  // sans .catch()) ne passe jamais par render() — ces deux gestionnaires globaux sont le filet pour
  // ces cas-là : jamais bloquants, juste une trace (console + journal d'audit).
  window.addEventListener('error', (evt) => {
    console.error('Erreur JS non interceptée :', evt.error || evt.message);
    reportClientError(evt.error || new Error(String(evt.message)), 'window.onerror');
  });
  window.addEventListener('unhandledrejection', (evt) => {
    console.error('Promesse rejetée non interceptée :', evt.reason);
    reportClientError(evt.reason instanceof Error ? evt.reason : new Error(String(evt.reason)), 'unhandledrejection');
  });

  await DB.init();
  bindGlobalEvents();
  bindGlobalSearchEvents();
  bindNotificationEvents();
  bindUserMenuEvents();
  // §sprint refonte UX §12 : re-filtre la barre de nav au franchissement du seuil mobile (ex.
  // rotation d'un tablette, redimensionnement de fenêtre) — un seul listener posé une fois, jamais
  // par render() lui-même (qui tourne bien trop souvent pour ça).
  MOBILE_NAV_QUERY.addEventListener('change', renderSidebar);
  // §correctif retour QA du 27/08/2026 (point 4) : re-mesure le débordement des onglets Paramètres
  // au redimensionnement (rotation d'écran, fenêtre agrandie/réduite) — un seul listener posé une
  // fois, jamais par render() (voir le commentaire de checkParametresTabsOverflow ci-dessus).
  window.addEventListener('resize', () => { if (state.view === 'parametres') checkParametresTabsOverflow(); });

  // La console BERTOLIS (super-admin multi-entreprise) est un système entièrement séparé, basé sur
  // localStorage, qui n'a besoin d'aucune donnée Supabase — une session BERTOLIS déjà active ne doit
  // pas rester bloquée par un souci réseau/extension qui empêcherait supabase-client.js de charger.
  if (DB.isBertolisLoggedIn()) {
    showBertolisConsole();
    return;
  }

  // Le module supabase-client.js charge son propre import réseau (CDN) avant de poser
  // window.SupabaseSync — si ça échoue (réseau lent, extension de navigateur, etc.), mieux vaut un
  // message d'erreur clair qu'un écran de connexion silencieusement figé (aucun bouton ne répond).
  if (!window.SupabaseSync) {
    document.getElementById('login-root').style.display = 'flex';
    document.getElementById('login-root').innerHTML = `
      <div class="login-card">
        <div class="login-logo">${NEXUS_LOGO_MARK} Nexus</div>
        <p class="login-error" role="alert">Impossible de charger le module de connexion (problème réseau ou extension de navigateur). Rechargez la page ; si le problème persiste, essayez sans bloqueur de publicité/traqueurs.</p>
        <button type="button" class="btn btn-primary" style="width: 100%;" onclick="location.reload()">Recharger la page</button>
      </div>
    `;
    return;
  }

  window.SupabaseSync.onPasswordRecovery(() => {
    state.authView = 'reset';
    state.authError = '';
    // Persisté : si l'onglet recharge pendant qu'on est sur l'écran "nouveau mot de passe" (avant
    // validation), la session de récupération reste valide mais state.authView (en mémoire) serait
    // perdu — sans ce flag, restoreSession() plus bas verrait une session valide et enverrait
    // directement dans l'appli, sautant le vrai changement de mot de passe.
    sessionStorage.setItem('sevenrh_password_recovery_pending', '1');
    renderLoginScreen();
  });

  window.SupabaseSync.onSessionRefreshed((session) => DB._touchSavedAccountToken(session));

  const restored = await DB.restoreSession();
  const lastAuthError = DB.getLastAuthError();
  // Une session de récupération de mot de passe est une session valide comme une autre : si
  // PASSWORD_RECOVERY a été détecté (maintenant ou lors d'un chargement précédent, via le flag
  // persisté), il ne faut jamais laisser restoreSession() envoyer directement dans l'appli.
  if (restored && !window.SupabaseSync.wasPasswordRecoveryDetected() && !sessionStorage.getItem('sevenrh_password_recovery_pending')) {
    showApp();
  } else if (lastAuthError) {
    // Retour d'une connexion Google/Microsoft (ou toute session authentifiée) sans fiche salarié
    // correspondante — jamais retomber muettement sur la page d'accueil publique dans ce cas
    // précis (voir DB.restoreSession) : direct sur l'écran de connexion avec le message clair.
    showLogin();
    state.authError = lastAuthError;
    renderLoginScreen();
  } else if (
    getPendingSignup()
    || sessionStorage.getItem('sevenrh_password_recovery_pending')
    || sessionStorage.getItem('sevenrh_pending_reset_email')
    || new URLSearchParams(window.location.search).get('signup') === '1'
    || new URLSearchParams(window.location.search).get('editeur') === '1'
    || isInstalledApp()
  ) {
    // Un flux d'authentification est déjà en cours (confirmation d'email, récupération de mot de
    // passe, lien "Créer mon entreprise" partagé), ou on est dans l'application de bureau (qui a
    // déjà "vu" la page d'accueil publique au moment de l'installer) — aller droit à l'écran de
    // connexion plutôt que de repasser par la page d'accueil publique.
    showLogin();
  } else {
    showLanding();
  }
});

function showLogin(defaultView) {
  document.getElementById('app-shell').style.display = 'none';
  document.getElementById('bertolis-root').style.display = 'none';
  document.getElementById('landing-root').style.display = 'none';
  document.getElementById('login-root').style.display = 'flex';
  state.authError = '';
  state.loginDraft = { email: '', password: '' };
  // Si un rechargement survient pendant l'attente de confirmation d'email (typiquement parce que
  // l'utilisateur a changé d'appli pour consulter ses emails, ce qui peut faire recharger l'onglet
  // en arrière-plan sur mobile), on retrouve cet état au lieu de silencieusement revenir au simple
  // écran de connexion — voir le formulaire de signup dans bindLoginScreenEvents.
  const pendingSignup = getPendingSignup();
  const pendingResetEmail = sessionStorage.getItem('sevenrh_pending_reset_email');
  const recoveryPending = sessionStorage.getItem('sevenrh_password_recovery_pending');
  if (pendingSignup) {
    state.authView = pendingSignup.view;
    state.pendingSignupConfirmation = pendingSignup.email;
  } else if (recoveryPending) {
    // Priorité sur pendingResetEmail : cliquer le lien reçu par email fait progresser l'utilisateur
    // de "en attente de l'email" à "en train de choisir un nouveau mot de passe".
    state.authView = 'reset';
    state.authError = '';
  } else if (pendingResetEmail) {
    state.authView = 'forgot';
    state.pendingReset = { email: pendingResetEmail };
  } else if (new URLSearchParams(window.location.search).get('signup') === '1') {
    // Lien "Créer mon entreprise" partagé (ex. campagne email) pointant directement vers le signup.
    history.replaceState({}, '', window.location.pathname);
    state.authView = 'signup-company';
  } else if (new URLSearchParams(window.location.search).get('editeur') === '1') {
    // Accès éditeur BERTOLIS (§9.6) — plus de bouton visible sur l'écran de connexion public (retiré
    // lors de la refonte identité, pas professionnel pour un client) : seule cette URL, jamais liée
    // nulle part dans l'app, y mène désormais. Voir aussi la condition équivalente dans
    // DOMContentLoaded (sinon un visiteur non authentifié tomberait sur la landing page avant même
    // d'atteindre ce bloc).
    history.replaceState({}, '', window.location.pathname);
    state.authView = 'bertolis';
  } else {
    state.authView = defaultView || 'login';
  }
  renderLoginScreen();
}

/** "Ajouter un compte" (bascule multi-entreprise, menu utilisateur) — contrairement à showLogin(),
 * ignore volontairement tout flux d'authentification en attente (inscription/récupération d'un
 * AUTRE compte) : on part toujours de l'écran de connexion propre, et le compte actuel reste
 * intact en mémoire (DB._companiesCache) tant que ce nouveau formulaire n'a pas été validé — voir
 * btn-cancel-add-account (bindLoginScreenEvents) pour l'annulation, qui se contente de rappeler
 * showApp() sans rien à restaurer. */
function openAddAccountFlow() {
  state.authContext = 'add-account';
  document.getElementById('app-shell').style.display = 'none';
  document.getElementById('bertolis-root').style.display = 'none';
  document.getElementById('landing-root').style.display = 'none';
  document.getElementById('login-root').style.display = 'flex';
  state.authView = 'login';
  state.authError = '';
  renderLoginScreen();
}

/** Page d'accueil publique — atterrissage par défaut sur nexus-rh.com pour un visiteur sans session
 * (voir DOMContentLoaded) : présentation du produit, tarifs réels et installation, avec un accès
 * direct à la connexion/création de compte. Ne remplace jamais l'écran de connexion pour un flux
 * d'authentification déjà en cours (voir les conditions dans DOMContentLoaded). */
