// ---------------------------------------------------------------------------
// Vue : Boîte à idées (§14 modules futurs, construit)
// ---------------------------------------------------------------------------

// §"Vitrine Idées" (roadmap différenciation du 31/08/2026) : 'retenue' (état terminal flou — accepté
// mais jamais dit si c'est réellement fait) devient 'en_cours' + 'livree', deux étapes qui montrent
// un vrai suivi jusqu'à la livraison — voir 0043_idees_vitrine_statuts.sql pour la migration des
// idées déjà en 'retenue'. L'ORDRE de cet objet fixe l'ordre des colonnes du board (voir renderIdees).
const IDEE_STATUT_LABELS = { nouvelle: 'Nouvelle', etudiee: 'À l\'étude', en_cours: 'En cours', livree: 'Livrée', refusee: 'Non retenue' };
const IDEE_STATUT_BADGE_CLASS = { nouvelle: 'info', etudiee: 'warning', en_cours: 'warning', livree: 'success', refusee: 'muted' };

// §"Vitrine Idées" (roadmap différenciation du 31/08/2026) : petite carte de board, plus la ligne
// pleine largeur d'avant (renderIdeeRow) — le statut n'a plus besoin d'être répété en badge sur
// chaque carte, il est déjà porté par la colonne (voir renderIdees ci-dessous).
function renderIdeeCard(idee, userId) {
  const author = employeeRepository.getById(idee.employeeId);
  const votes = idee.votes || [];
  const aVote = votes.includes(userId);
  return `
    <div class="idee-card" data-open-idee="${idee.id}">
      <div class="idee-card-title">${escapeHtml(idee.titre)}</div>
      <div class="idee-card-meta">
        <span class="text-muted">${author ? personNameHtml(author) : '—'}</span>
        <button type="button" class="btn btn-sm ${aVote ? 'btn-primary' : 'btn-secondary'} idee-vote-btn" data-vote-idee="${idee.id}" title="${aVote ? 'Retirer mon vote' : 'Voter pour cette idée'}">
          ${icon(ICONS.thumbsUp, 13)} ${votes.length}
        </button>
      </div>
    </div>
  `;
}

// §"Vitrine Idées" (roadmap différenciation du 31/08/2026) : "répond directement au silence actuel
// [...] aucun des concurrents comparés n'affiche de roadmap publique votée" — la liste plate d'avant
// ne montrait jamais ce qu'il advenait d'une idée une fois "retenue". Un board par statut (une colonne
// par valeur de IDEE_STATUT_LABELS, dans son ordre de déclaration) rend le suivi visible d'un coup
// d'œil, de la proposition à la livraison. Le tri par votes décroissant (déjà fait par DB.getIdees())
// est préservé À L'INTÉRIEUR de chaque colonne par le simple filter ci-dessous, qui ne réordonne rien.
function renderIdees() {
  const user = authRepository.getCurrentUser();
  const idees = ideeRepository.getAll();

  const columns = Object.keys(IDEE_STATUT_LABELS).map(statut => ({
    statut,
    label: IDEE_STATUT_LABELS[statut],
    items: idees.filter(i => i.statut === statut)
  }));

  return `
    <div class="view-header view-header-row">
      <div>
        <h1>Boîte à idées</h1>
        <p class="view-subtitle">${idees.length} idée${idees.length > 1 ? 's' : ''} proposée${idees.length > 1 ? 's' : ''} par toute l'entreprise</p>
      </div>
      <div class="detail-header-actions">
        <button class="btn btn-primary" id="btn-proposer-idee">+ Proposer une idée</button>
      </div>
    </div>
    ${idees.length === 0 ? `
      <div class="card"><p class="text-muted">Aucune idée pour le moment, soyez le premier à en proposer une !</p></div>
    ` : `
      <div class="idees-board">
        ${columns.map(col => `
          <div class="idees-column">
            <div class="idees-column-header">
              <span>${escapeHtml(col.label)}</span>
              <span class="badge badge-${IDEE_STATUT_BADGE_CLASS[col.statut] || 'muted'}">${col.items.length}</span>
            </div>
            ${col.items.length === 0 ? '<p class="text-muted" style="font-size:13px; margin:0;">Aucune idée</p>' : col.items.map(i => renderIdeeCard(i, user.id)).join('')}
          </div>
        `).join('')}
      </div>
    `}
  `;
}

/** Le vote est géré directement depuis la liste (pas besoin d'ouvrir le détail pour un simple 👍) —
 * seul le clic sur le titre/badge ouvre le détail, le bouton de vote est un stopPropagation implicite
 * (élément séparé, pas imbriqué dans un lien cliquable). */
function bindIdeesEvents() {
  const proposeBtn = document.getElementById('btn-proposer-idee');
  if (proposeBtn) proposeBtn.addEventListener('click', () => openProposeIdeeModal());
  document.querySelectorAll('[data-vote-idee]').forEach(btn => {
    btn.addEventListener('click', async (evt) => {
      evt.stopPropagation();
      const result = await ideeRepository.toggleVote(btn.dataset.voteIdee);
      if (!result.success) { showToast(result.error || 'Erreur lors du vote.', 'error'); return; }
      render();
    });
  });
  document.querySelectorAll('[data-open-idee]').forEach(el => {
    el.addEventListener('click', (evt) => {
      if (evt.target.closest('[data-vote-idee]')) return;
      navigateTo('idee-detail', { currentIdeeId: el.dataset.openIdee });
    });
  });
}

function openProposeIdeeModal() {
  const html = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>Proposer une idée</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="propose-idee-form">
        <div class="modal-body">
          <div class="form-field">
            <label for="f-idee-titre">Titre *</label>
            <input class="input" type="text" id="f-idee-titre" placeholder="Résumez votre idée en quelques mots" required>
          </div>
          <div class="form-field" style="margin-top:12px;">
            <label for="f-idee-description">Description (optionnel)</label>
            <textarea class="input" id="f-idee-description" rows="4" placeholder="Détaillez votre idée, en quoi elle aiderait l'équipe..."></textarea>
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="submit" class="btn btn-primary">Proposer</button>
        </div>
      </form>
    </div>
  `;
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');
  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('propose-idee-form').addEventListener('submit', (evt) => {
    evt.preventDefault();
    const titre = document.getElementById('f-idee-titre').value.trim();
    if (!titre) return;
    const user = authRepository.getCurrentUser();
    ideeRepository.create({ employeeId: user.id, titre, description: document.getElementById('f-idee-description').value.trim() });
    closeModal();
    showToast('Idée proposée, merci !');
    if (state.view === 'idees') render();
  });
}

function renderIdeeDetail(id) {
  const idee = ideeRepository.getById(id);
  if (!idee) return `<button class="btn-link" id="btn-back-to-idees">← Retour</button><div class="empty-state"><p>Idée introuvable.</p></div>`;

  const user = authRepository.getCurrentUser();
  const canManage = hasPermission(user, PERMISSIONS.GERER_IDEES);
  const author = employeeRepository.getById(idee.employeeId);
  const votes = idee.votes || [];
  const aVote = votes.includes(user.id);

  const statutControls = canManage
    ? `<select class="input" id="f-idee-statut" style="width:auto;">
        ${Object.keys(IDEE_STATUT_LABELS).map(s => `<option value="${s}" ${s === idee.statut ? 'selected' : ''}>${IDEE_STATUT_LABELS[s]}</option>`).join('')}
      </select>`
    : '';

  return `
    <button class="btn-link" id="btn-back-to-idees">← Retour à la boîte à idées</button>
    <div class="view-header view-header-row">
      <div>
        <h1>${escapeHtml(idee.titre)}</h1>
        <p class="view-subtitle">
          <span class="badge badge-${IDEE_STATUT_BADGE_CLASS[idee.statut] || 'muted'}">${escapeHtml(IDEE_STATUT_LABELS[idee.statut] || idee.statut)}</span>
          ${author ? ` · ${escapeHtml(author.prenom + ' ' + author.nom)}` : ''}
          · ${formatDateTime(idee.dateCreation)}
        </p>
      </div>
      <div class="detail-header-actions">
        ${statutControls}
        <button type="button" class="btn btn-sm ${aVote ? 'btn-primary' : 'btn-secondary'}" id="btn-vote-idee">${icon(ICONS.thumbsUp, 13)} ${votes.length}</button>
      </div>
    </div>
    ${idee.description ? `<div class="card"><p style="margin:0;">${escapeHtml(idee.description).replace(/\n/g, '<br>')}</p></div>` : ''}
    ${renderTicketHistoryTimeline(idee.historique)}
  `;
}

function bindIdeeDetailEvents() {
  const backBtn = document.getElementById('btn-back-to-idees');
  if (backBtn) backBtn.addEventListener('click', () => navigateTo('idees'));
  if (!ideeRepository.getById(state.currentIdeeId)) return;

  const voteBtn = document.getElementById('btn-vote-idee');
  if (voteBtn) {
    voteBtn.addEventListener('click', async () => {
      const result = await ideeRepository.toggleVote(state.currentIdeeId);
      if (!result.success) { showToast(result.error || 'Erreur lors du vote.', 'error'); return; }
      render();
    });
  }

  const statutSelect = document.getElementById('f-idee-statut');
  if (statutSelect) {
    statutSelect.addEventListener('change', async () => {
      const result = await ideeRepository.setStatut(state.currentIdeeId, statutSelect.value);
      if (!result.success) { showToast(result.error || 'Erreur lors du changement de statut.', 'error'); return; }
      render();
    });
  }
}

// ---------------------------------------------------------------------------
// Vue : Boussole (roadmap différenciation #2, 01/09/2026) — assistant en langage naturel scopé
// strictement aux données de l'entreprise (voir supabase/functions/ask-boussole/index.ts pour le
// raisonnement de sécurité complet : aucun accès direct à la base côté IA, un instantané préparé ici
// avec les mêmes fonctions de calcul que le reste de l'app, jamais une réimplémentation côté serveur).
// ---------------------------------------------------------------------------

/** Instantané des données RH de l'entreprise envoyé à la Boussole — volontairement compact (ni
 * numéro de sécurité sociale, ni adresse, ni salaire : seulement ce qui sert à répondre aux questions
 * types de ce pilote, congés et notes de frais) plutôt qu'un export complet de chaque salarié. */
function buildBoussoleContext() {
  const employees = employeeRepository.getAll().filter(e => !e.archive && e.statut === 'Actif');
  const allLeaveTypes = leaveTypeRepository.getLeaveTypes();
  const leaveTypesConge = allLeaveTypes.filter(t => t.categorie === 'conge' && t.actif);
  const allRequests = leaveRepository.getAll();
  const now = new Date();
  const monthStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;

  const notesFraisParService = {};
  expenseRepository.getAll()
    .filter(n => String(n.dateCreation || '').startsWith(monthStr))
    .forEach(n => {
      const employee = employeeRepository.getById(n.employeeId);
      const service = (employee && employee.service) || 'Non renseigné';
      notesFraisParService[service] = round2((notesFraisParService[service] || 0) + (n.montantTTC || 0));
    });

  return {
    dateDuJour: toISODate(now),
    salaries: employees.map(e => ({
      nom: `${e.prenom} ${e.nom}`,
      service: e.service || null,
      typeContrat: e.typeContrat,
      dateEmbauche: e.dateEmbauche,
      soldesConges: leaveTypesConge.map(t => {
        const balance = getLeaveBalance(e, t, allRequests, allLeaveTypes);
        return { type: t.nom, joursDisponibles: balance.disponible === Infinity ? 'illimité' : balance.disponible };
      })
    })),
    notesDeFraisMoisEnCours: { mois: monthStr, montantTTCParService: notesFraisParService }
  };
}

function renderBoussole() {
  const messages = state.boussoleMessages || [];
  return `
    <div class="view-header">
      <h1>${icon(ICONS.compass, 20)} Boussole</h1>
      <p class="view-subtitle">Posez une question sur les données RH de votre entreprise (congés, notes de frais...) — la Boussole ne répond qu'à partir de vos propres données, jamais d'internet.</p>
    </div>
    <div class="card">
      <div id="boussole-messages" class="boussole-messages">
        ${messages.length === 0 ? `<p class="text-muted">Exemples : « Qui a plus de 20 jours de congés payés disponibles ? », « Coût des notes de frais ce mois-ci par service ». </p>` : messages.map(m => `
          <div class="boussole-message boussole-message-${m.role}">
            <div class="boussole-message-bubble">${escapeHtml(m.text).replace(/\n/g, '<br>')}</div>
          </div>
        `).join('')}
        ${state.boussoleLoading ? `<div class="boussole-message boussole-message-assistant"><div class="boussole-message-bubble text-muted">La Boussole réfléchit...</div></div>` : ''}
      </div>
      <form id="boussole-form" class="boussole-form">
        <input type="text" id="f-boussole-question" class="input" placeholder="Posez votre question..." autocomplete="off" ${state.boussoleLoading ? 'disabled' : ''}>
        <button type="submit" class="btn btn-primary" ${state.boussoleLoading ? 'disabled' : ''}>Envoyer</button>
      </form>
      <p class="form-hint" style="margin-top:8px;">Réponses générées par IA à partir des données déjà présentes dans Nexus : à vérifier avant toute décision importante, comme n'importe quel calcul automatisé.</p>
    </div>
  `;
}

function bindBoussoleEvents() {
  const form = document.getElementById('boussole-form');
  if (!form) return;
  const input = document.getElementById('f-boussole-question');
  if (input) input.focus();

  const messagesEl = document.getElementById('boussole-messages');
  if (messagesEl) messagesEl.scrollTop = messagesEl.scrollHeight;

  form.addEventListener('submit', async (evt) => {
    evt.preventDefault();
    const question = input.value.trim();
    if (!question || state.boussoleLoading) return;
    state.boussoleMessages = [...(state.boussoleMessages || []), { role: 'user', text: question }];
    state.boussoleLoading = true;
    render();

    // §correctif audit du 31/08/2026 : askBoussole() ne rejette normalement jamais (erreurs HTTP/API
    // déjà ramenées en {success:false}, voir askBoussole), mais un échec du réseau/DNS/CORS AVANT
    // même la réponse fait rejeter la promesse de supabase.functions.invoke() elle-même (même limite
    // que analyzeTicket/invokeBertolisTickets ailleurs dans ce fichier) — sans ce try/catch,
    // state.boussoleLoading restait bloqué à `true` pour toujours (aucun code ne le remet à false),
    // laissant "La Boussole réfléchit..." affiché et le formulaire désactivé en permanence.
    let result;
    try {
      const context = buildBoussoleContext();
      result = await window.SupabaseSync.askBoussole(question, context);
    } catch (err) {
      result = { success: false, error: 'Erreur de connexion, réessayez.' };
    }
    state.boussoleLoading = false;
    state.boussoleMessages = [...state.boussoleMessages, {
      role: 'assistant',
      text: result.success ? result.answer : (result.error || 'Erreur, réessayez.')
    }];
    render();
  });
}

// ---------------------------------------------------------------------------
// Vue : Fiche salarié (détail)
// ---------------------------------------------------------------------------

/** §correctif retour QA du 27/08/2026 ("la RH ne peut pas modifier sa propre fiche il faut changer
 * ça") : la restriction §9.3 ("seul le Propriétaire modifie sa propre fiche") bloquait aussi RH,
 * alors que RH a par défaut la permission MODIFIER_SALARIE pour tout le monde SAUF elle-même — sans
 * bénéfice de sécurité réel (le journal d'audit trace de toute façon chaque modification, y compris
 * une auto-modification), juste un blocage gênant au quotidien. Quiconque a MODIFIER_SALARIE peut
 * désormais modifier sa propre fiche comme celle de n'importe qui d'autre. */
function canEditEmployeeRecord(employee) {
  const user = authRepository.getCurrentUser();
  if (!user) return false;
  if (hasPermission(user, PERMISSIONS.MODIFIER_SALARIE)) return true;
  if (user.role === ROLES.MANAGER) return isManagerOfEmployee(user.id, employee.id);
  return false;
}

/** Même règle que canEditEmployeeRecord, mais pour l'archivage (permission distincte au §8). */
function canArchiveEmployeeRecord(employee) {
  const user = authRepository.getCurrentUser();
  if (!user) return false;
  if (hasPermission(user, PERMISSIONS.ARCHIVER_SALARIE)) {
    if (user.role !== ROLES.PROPRIETAIRE && user.id === employee.id) return false;
    return true;
  }
  return false;
}

/** §retour Betty du 18/09/2026 (point 9) : "rien n'empêche actuellement un Propriétaire de
 * supprimer sa propre fiche" — contrairement à canArchiveEmployeeRecord ci-dessus, AUCUNE exception
 * pour le Propriétaire ici : une suppression est définitive (contrairement à un archivage), et se
 * supprimer soi-même laisserait l'entreprise sans Propriétaire. */
function canDeleteEmployeeRecord(employee) {
  const user = authRepository.getCurrentUser();
  if (!user) return false;
  if (user.id === employee.id) return false;
  return hasPermission(user, PERMISSIONS.SUPPRIMER_SALARIE);
}

// ---------------------------------------------------------------------------
// Checklists d'intégration / de départ (§demande 18/08/2026)
// ---------------------------------------------------------------------------

/** Un salarié créé avant l'ajout de cette fonctionnalité a onboardingChecklist = [] (défaut de
 * makeEmptyEmployee) — on la peuple à la volée, au premier affichage, plutôt que de forcer une
 * migration de toutes les fiches existantes ou de laisser la carte vide pour toujours. Persistée
 * immédiatement pour ne pas re-générer une nouvelle checklist à chaque rendu. */
function ensureOnboardingChecklist(employee) {
  if (employee.onboardingChecklist && employee.onboardingChecklist.length) return employee.onboardingChecklist;
  const template = settingsRepository.getSettings().onboardingChecklistTemplate || [];
  if (!template.length) return [];
  const checklist = template.map(label => ({ label, fait: false, dateFait: '' }));
  employeeRepository.update(employee.id, { onboardingChecklist: checklist });
  employee.onboardingChecklist = checklist;
  return checklist;
}

/** Générique pour les deux checklists (onboarding toujours présente, offboarding seulement une
 * fois démarrée) — une seule mise en page, un seul jeu d'événements (voir bindChecklistEvents). */
function renderChecklistCard(title, checklistKey, checklist) {
  const total = checklist.length;
  const done = checklist.filter(item => item.fait).length;
  return `
    <div class="card">
      <h2>${escapeHtml(title)}${total ? ` <span class="text-muted" style="font-size: 13px; font-weight: 400;">(${done}/${total})</span>` : ''}</h2>
      <div class="checklist">
        ${checklist.map((item, i) => `
          <label class="checklist-item">
            <input type="checkbox" class="checklist-checkbox" data-checklist-key="${checklistKey}" data-index="${i}" ${item.fait ? 'checked' : ''}>
            <span class="${item.fait ? 'checklist-label-done' : ''}">${escapeHtml(item.label)}</span>
            ${item.fait && item.dateFait ? `<span class="text-muted" style="font-size: 12px; margin-left: auto;">${formatDate(item.dateFait)}</span>` : ''}
          </label>
        `).join('')}
      </div>
    </div>
  `;
}

function bindChecklistEvents(employeeId) {
  document.querySelectorAll('.checklist-checkbox').forEach(cb => {
    cb.addEventListener('change', () => {
      const key = cb.dataset.checklistKey;
      const index = Number(cb.dataset.index);
      const employee = employeeRepository.getById(employeeId);
      if (!employee) return;
      const checklist = (employee[key] || []).slice();
      checklist[index] = { ...checklist[index], fait: cb.checked, dateFait: cb.checked ? toISODate(new Date()) : '' };
      employeeRepository.update(employeeId, { [key]: checklist });
      render();
    });
  });

  const startOffboardingBtn = document.getElementById('btn-demarrer-offboarding');
  if (startOffboardingBtn) startOffboardingBtn.addEventListener('click', () => {
    const template = settingsRepository.getSettings().offboardingChecklistTemplate || [];
    if (!template.length) { showToast('Ajoutez d\'abord des étapes dans Paramètres → Référentiels.', 'error'); return; }
    employeeRepository.update(employeeId, { offboardingChecklist: template.map(label => ({ label, fait: false, dateFait: '' })) });
    showToast('Checklist de départ démarrée.');
    render();
  });
}

const AVENANT_TYPES = ['Poste', 'Rémunération', 'Temps de travail', 'Établissement / Service', 'Autre'];

/** §retour Betty du 17/09/2026 : remplace l'ancien champ unique dateDerniereVisiteMedicale (écrasé
 * à chaque visite, sans historique) par une vraie liste, comme renderAvenantsCard juste en dessous
 * — le plus récent en premier. */
function visiteMedicaleConclusionBadgeClass(conclusion) {
  if (!conclusion) return 'badge-muted';
  if (/inapte/i.test(conclusion)) return 'badge-danger';
  // "aucune orientation nécessaire" est la conclusion FAVORABLE de la VIP (suivi simple/adapté) —
  // seule une orientation explicitement RECOMMANDÉE (ou une réserve/aménagement) doit ressortir en
  // avertissement, jamais sa négation.
  if (/réserve|orientation (vers|recommandée)/i.test(conclusion)) return 'badge-warning';
  return 'badge-success';
}

function renderVisitesMedicalesCard(employee, canEdit) {
  const rules = SUIVI_MEDICAL_RULES[employee.suiviMedicalType] || SUIVI_MEDICAL_RULES.simple;
  const visites = (employee.visitesMedicales || []).slice().sort((a, b) => (b.date || '').localeCompare(a.date || ''));
  const echeance = computeNextVisiteMedicale(employee);
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  return `
    <div class="card">
      <h2>Suivi médical</h2>
      <p class="text-muted" style="margin: 0 0 10px;">${escapeHtml(rules.label)}</p>
      ${echeance ? (() => {
        const overdue = echeance.next < today;
        const kindLabel = echeance.kind === 'embauche' ? ' (visite d\'embauche)' : echeance.kind === 'intermediaire' ? ' (rendez-vous intermédiaire par un professionnel de santé)' : '';
        const autre = echeance.autreEcheance ? `<br>Visite périodique suivante (sauf nouvel enregistrement d'ici là) : ${formatDate(toISODate(echeance.autreEcheance))}` : '';
        return `<p class="text-muted${overdue ? ' text-danger' : ''}" style="margin: 0 0 10px;">Prochaine échéance : ${formatDate(toISODate(echeance.next))}${kindLabel}${overdue ? ' — en retard' : ''}${autre}</p>`;
      })() : ''}
      ${visites.length === 0 ? `<p class="text-muted" style="margin-bottom: 10px;">Aucune visite enregistrée.</p>` : `
        <div class="mini-list" style="margin-bottom: 10px;">
          ${visites.map(v => `
            <div class="mini-list-item" style="align-items: flex-start;">
              <span>
                <span class="badge ${visiteMedicaleConclusionBadgeClass(v.conclusion)}">${escapeHtml(v.conclusion || 'Sans conclusion')}</span>
                ${escapeHtml(VISITE_MEDICALE_TYPE_LABELS[v.type] || v.type)}
                ${v.contreVisite ? '<span class="badge badge-info">Contre-visite/examen complémentaire</span>' : ''}
                ${v.amenagements ? `<br><span class="text-muted">Aménagements préconisés : ${escapeHtml(v.amenagements)}</span>` : ''}
                ${v.pieceJointe ? `<br><a href="${v.pieceJointe.dataUrl}" download="${escapeHtml(v.pieceJointe.nom)}" class="btn-link">${icon(ICONS.paperclip, 12)} ${escapeHtml(v.pieceJointe.nom)}</a>` : ''}
              </span>
              <span style="text-align: right; white-space: nowrap;">
                <span class="text-muted">${formatDate(v.date)}</span>
                ${canEdit ? `<br><button type="button" class="btn-link" data-edit-visite-medicale="${v.id}">Modifier</button> · <button type="button" class="btn-link text-danger" data-delete-visite-medicale="${v.id}">Supprimer</button>` : ''}
              </span>
            </div>
          `).join('')}
        </div>
      `}
      ${canEdit ? `<button type="button" class="btn btn-secondary btn-sm" id="btn-ajouter-visite-medicale">Enregistrer une visite médicale</button>` : ''}
    </div>
  `;
}

/** Trace manuelle des avenants (voir data.js, employee.avenants) — le plus récent en premier,
 * comme les autres historiques de l'app (buildRequestTimeline, entretien.historique...). */
function renderAvenantsCard(avenants, canEdit) {
  const sorted = avenants.slice().sort((a, b) => (b.date || '').localeCompare(a.date || ''));
  return `
    <div class="card">
      <h2>Historique des avenants</h2>
      ${sorted.length === 0 ? `<p class="text-muted" style="margin-bottom: 10px;">Aucun avenant enregistré.</p>` : `
        <div class="mini-list" style="margin-bottom: 10px;">
          ${sorted.map(a => `
            <div class="mini-list-item" style="align-items: flex-start;">
              <span>
                <span class="badge badge-info">${escapeHtml(a.type)}</span>
                ${escapeHtml(a.description)}
              </span>
              <span class="text-muted">${formatDate(a.date)}</span>
            </div>
          `).join('')}
        </div>
      `}
      ${canEdit ? `<button type="button" class="btn btn-secondary btn-sm" id="btn-ajouter-avenant">Enregistrer un avenant</button>` : ''}
    </div>
  `;
}

function openAjouterAvenantModal(employeeId) {
  const employeeForCheck = employeeRepository.getById(employeeId);
  if (!employeeForCheck || !canEditEmployeeRecord(employeeForCheck)) {
    showToast('Vous n\'avez pas le droit de modifier cette fiche.', 'error');
    return;
  }
  const html = `
    <div class="modal">
      <div class="modal-header">
        <h2>Enregistrer un avenant</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="avenant-form">
        <div class="modal-body">
          <div class="form-field">
            <label for="f-avenant-type">Type de changement</label>
            <select class="input" id="f-avenant-type">
              ${AVENANT_TYPES.map(t => `<option value="${t}">${t}</option>`).join('')}
            </select>
          </div>
          <div class="form-field">
            <label for="f-avenant-date">Date d'effet *</label>
            <input class="input" type="date" id="f-avenant-date" required>
          </div>
          <div class="form-field">
            <label for="f-avenant-description">Description</label>
            <textarea class="input" id="f-avenant-description" rows="3" placeholder="Ex. Passage de Technicien à Responsable technique, salaire porté à 2 800 € brut/mois"></textarea>
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="submit" class="btn btn-primary">Enregistrer</button>
        </div>
      </form>
    </div>
  `;
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');
  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('avenant-form').addEventListener('submit', (evt) => {
    evt.preventDefault();
    const date = document.getElementById('f-avenant-date').value;
    if (!date) return;
    const employee = employeeRepository.getById(employeeId);
    if (!employee) { showToast('Ce salarié n\'est plus disponible.', 'error'); closeModal(); return; }
    const avenant = {
      id: generateId('aven'),
      type: document.getElementById('f-avenant-type').value,
      date,
      description: document.getElementById('f-avenant-description').value.trim(),
      dateEnregistrement: new Date().toISOString()
    };
    employeeRepository.update(employeeId, { avenants: [...(employee.avenants || []), avenant] });
    closeModal();
    showToast('Avenant enregistré.');
    render();
  });
}

/** §retour Betty du 17/09/2026 ("le suivi médical, à faire complètement ou pas du tout") : remplace
 * l'ancien bouton qui écrivait la date du jour au premier clic, sans confirmation ni possibilité de
 * choisir la date — sert à la fois pour ajouter (visiteId absent) et pour modifier (visiteId fourni)
 * une visite, même formulaire dans les deux cas. Les options de conclusion dépendent du type de
 * suivi du salarié (SUIVI_MEDICAL_RULES) : seul le suivi renforcé propose un avis d'aptitude. */
function openVisiteMedicaleModal(employeeId, visiteId) {
  const employee = employeeRepository.getById(employeeId);
  if (!employee || !canEditEmployeeRecord(employee)) {
    showToast('Vous n\'avez pas le droit de modifier cette fiche.', 'error');
    return;
  }
  const existing = visiteId ? (employee.visitesMedicales || []).find(v => v.id === visiteId) : null;
  const rules = SUIVI_MEDICAL_RULES[employee.suiviMedicalType] || SUIVI_MEDICAL_RULES.simple;
  const html = `
    <div class="modal modal-large">
      <div class="modal-header">
        <h2>${existing ? 'Modifier' : 'Enregistrer'} une visite médicale</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="visite-medicale-form">
        <div class="modal-body">
          <p class="text-muted" style="margin-top: 0;">${escapeHtml(rules.label)} — les options de conclusion ci-dessous en tiennent compte.</p>
          <div class="form-field">
            <label for="f-visite-type">Type de visite</label>
            <select class="input" id="f-visite-type">
              ${Object.entries(VISITE_MEDICALE_TYPE_LABELS).map(([key, label]) => `<option value="${key}" ${existing && existing.type === key ? 'selected' : ''}>${escapeHtml(label)}</option>`).join('')}
            </select>
          </div>
          <div class="form-field">
            <label for="f-visite-date">Date de la visite *</label>
            <input class="input" type="date" id="f-visite-date" value="${escapeHtml(existing ? existing.date : toISODate(new Date()))}" required>
          </div>
          <div class="form-field">
            <label for="f-visite-conclusion">Conclusion</label>
            <select class="input" id="f-visite-conclusion">
              <option value="">— Non renseignée —</option>
              ${rules.conclusionOptions.map(c => `<option value="${escapeHtml(c)}" ${existing && existing.conclusion === c ? 'selected' : ''}>${escapeHtml(c)}</option>`).join('')}
            </select>
          </div>
          <div class="form-field">
            <label for="f-visite-echeance">Date de la prochaine échéance</label>
            <input class="input" type="date" id="f-visite-echeance" value="${escapeHtml(existing ? existing.dateProchaineEcheance : '')}">
            <p class="form-hint">Laissez vide pour vous baser sur la périodicité par défaut du type de suivi (Paramètres).</p>
          </div>
          <div class="form-field">
            <label><input type="checkbox" id="f-visite-contre-visite" ${existing && existing.contreVisite ? 'checked' : ''}> Contre-visite ou examen complémentaire prévu</label>
          </div>
          <div class="form-field">
            <label for="f-visite-amenagements">Aménagements de poste préconisés</label>
            <textarea class="input" id="f-visite-amenagements" rows="2">${escapeHtml(existing ? existing.amenagements : '')}</textarea>
          </div>
          <div class="form-field">
            <label for="f-visite-commentaire">Commentaire</label>
            <textarea class="input" id="f-visite-commentaire" rows="2">${escapeHtml(existing ? existing.commentaire : '')}</textarea>
            <p class="form-hint text-danger">Ne jamais y indiquer un diagnostic ou le motif médical d'une inaptitude : l'employeur n'a le droit de connaître que la conclusion et les aménagements préconisés, jamais l'information médicale elle-même.</p>
          </div>
          <div class="form-field">
            <label for="f-visite-piece-jointe">Document remis par le médecin (optionnel)</label>
            <input class="input" type="file" id="f-visite-piece-jointe">
            ${existing && existing.pieceJointe ? `<p class="text-muted">Document actuel : ${escapeHtml(existing.pieceJointe.nom)} (choisissez un nouveau fichier pour le remplacer)</p>` : ''}
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="submit" class="btn btn-primary">Enregistrer</button>
        </div>
      </form>
    </div>
  `;
  const modalRoot = document.getElementById('modal-root');
  state.pendingAttachment = existing ? existing.pieceJointe : null;
  state.pendingAttachmentFile = null;
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');
  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('f-visite-piece-jointe').addEventListener('change', handleAttachmentChange);
  document.getElementById('visite-medicale-form').addEventListener('submit', (evt) => {
    evt.preventDefault();
    const date = document.getElementById('f-visite-date').value;
    if (!date) return;
    const current = employeeRepository.getById(employeeId);
    if (!current) { showToast('Ce salarié n\'est plus disponible.', 'error'); closeModal(); return; }
    const now = new Date().toISOString();
    const visite = {
      id: existing ? existing.id : generateId('visite'),
      type: document.getElementById('f-visite-type').value,
      date,
      conclusion: document.getElementById('f-visite-conclusion').value,
      dateProchaineEcheance: document.getElementById('f-visite-echeance').value,
      contreVisite: document.getElementById('f-visite-contre-visite').checked,
      amenagements: document.getElementById('f-visite-amenagements').value.trim(),
      commentaire: document.getElementById('f-visite-commentaire').value.trim(),
      pieceJointe: state.pendingAttachment,
      dateCreation: existing ? existing.dateCreation : now,
      dateModification: now,
      auteurId: authRepository.getCurrentUser().id
    };
    const visites = existing
      ? (current.visitesMedicales || []).map(v => v.id === existing.id ? visite : v)
      : [...(current.visitesMedicales || []), visite];
    employeeRepository.update(employeeId, { visitesMedicales: visites });
    auditLogRepository.logAudit(existing ? 'Modification' : 'Création', 'Visite médicale', `${current.prenom} ${current.nom}`, `${VISITE_MEDICALE_TYPE_LABELS[visite.type] || visite.type} du ${formatDate(visite.date)}`);
    state.pendingAttachment = null;
    state.pendingAttachmentFile = null;
    closeModal();
    showToast(existing ? 'Visite médicale modifiée.' : 'Visite médicale enregistrée.');
    render();
  });
}

function deleteVisiteMedicale(employeeId, visiteId) {
  const employee = employeeRepository.getById(employeeId);
  if (!employee || !canEditEmployeeRecord(employee)) {
    showToast('Vous n\'avez pas le droit de modifier cette fiche.', 'error');
    return;
  }
  const visite = (employee.visitesMedicales || []).find(v => v.id === visiteId);
  if (!visite) return;
  openConfirm({
    title: 'Supprimer cette visite médicale ?',
    message: `Visite du ${formatDate(visite.date)} (${VISITE_MEDICALE_TYPE_LABELS[visite.type] || visite.type}). Cette action est définitive.`,
    confirmLabel: 'Supprimer',
    danger: true,
    onConfirm: () => {
      const current = employeeRepository.getById(employeeId);
      if (!current) return;
      employeeRepository.update(employeeId, { visitesMedicales: (current.visitesMedicales || []).filter(v => v.id !== visiteId) });
      auditLogRepository.logAudit('Suppression', 'Visite médicale', `${current.prenom} ${current.nom}`, `${VISITE_MEDICALE_TYPE_LABELS[visite.type] || visite.type} du ${formatDate(visite.date)}`);
      showToast('Visite médicale supprimée.');
      render();
    }
  });
}

/** §refonte "fil d'Ariane" du 01/09/2026 : items = [{label, nav?, params?}, ...], le dernier élément
 * est la page courante (texte simple, jamais un lien). Réutilise le mécanisme data-nav existant
 * (délégation globale sur [data-nav], voir plus bas dans le fichier) — un <button>, jamais un <a>,
 * pour rester cohérent avec toutes les navigations déjà en place dans l'appli. */
/** §refonte "chargement unifié" du 01/09/2026 : remplace un "Chargement..." en texte brut par
 * quelques barres animées de largeurs variées (plus crédible qu'une seule ligne uniforme) — même
 * effet partout (voir .skeleton-line, style.css), jamais une variante par écran. */
function renderSkeletonLines(count = 3) {
  const widths = ['100%', '85%', '60%', '92%', '70%'];
  return `<div class="skeleton-lines">${Array.from({ length: count }, (_, i) => `<div class="skeleton-line" style="width:${widths[i % widths.length]}"></div>`).join('')}</div>`;
}

/** §retour Betty du 18/09/2026 (point 6, "le fil d'Ariane cliquable, plus visible plutôt qu'un
 * bouton en double") : le premier élément (le "retour" vers la liste d'origine) porte désormais une
 * flèche explicite en plus du style déjà renforcé (voir .breadcrumb, style.css) — jusqu'ici un texte
 * gris discret, facile à ne jamais remarquer comme cliquable. */
function renderBreadcrumb(items) {
  return `<div class="breadcrumb">${items.map((it, i) => {
    const sep = i > 0 ? '<span class="breadcrumb-sep">/</span>' : '';
    const isLast = i === items.length - 1;
    const crumb = (isLast || !it.nav)
      ? `<span>${escapeHtml(it.label)}</span>`
      : `<button type="button" class="btn-link" data-nav="${escapeHtml(it.nav)}"${it.params ? ` data-nav-params='${escapeHtml(JSON.stringify(it.params))}'` : ''}>${i === 0 ? '← ' : ''}${escapeHtml(it.label)}</button>`;
    return sep + crumb;
  }).join('')}</div>`;
}

/** §refonte "historique d'activité par fiche" du 01/09/2026 : le journal d'audit (Paramètres) existe
 * déjà, mais rien ne le rend visible directement sur la fiche concernée. cible (voir logAudit) est
 * un texte libre, pas une référence par id — filtre par correspondance de nom, comme la recherche
 * globale (performGlobalSearch) : accepté ici, une fiche reste consultable même sans cet historique
 * si jamais deux salariés partagent exactement le même nom complet.
 * §correctif audit du 01/09/2026 : un simple .includes() faisait fuiter l'activité d'un AUTRE salarié
 * dès que son nom complet contenait celui-ci comme préfixe — ex. "Léa Dubois" retrouvait aussi les
 * entrées de "Léa Dubois-Martin" (nom composé), un vrai risque de confidentialité dans une fiche RH
 * (arrêts maladie, ajustements de compteurs, notes de frais...). Exige désormais une frontière de mot
 * de part et d'autre du nom (jamais suivi/précédé d'une lettre ou d'un tiret) plutôt qu'une simple
 * sous-chaîne. */
function getEmployeeActivityHistory(employee, limit = 8) {
  const fullName = `${employee.prenom} ${employee.nom}`;
  const escaped = fullName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const boundaryPattern = new RegExp(`(^|[^\\p{L}-])${escaped}([^\\p{L}-]|$)`, 'u');
  return auditLogRepository.getAuditLog().filter(entry => entry.cible && boundaryPattern.test(entry.cible)).slice(0, limit);
}

function renderEmployeeActivityCard(employee) {
  const history = getEmployeeActivityHistory(employee);
  if (!history.length) return '';
  return `
    <div class="card">
      <h2>Historique d'activité</h2>
      <div class="mini-list">
        ${history.map(entry => `
          <div class="mini-list-item">
            <span>${auditActionBadge(entry.action)} ${escapeHtml(entry.entite)}${entry.details ? ` · ${escapeHtml(entry.details)}` : ''}</span>
            <span class="text-muted">${formatDate(entry.date)}${entry.auteur ? ` · ${escapeHtml(entry.auteur)}` : ''}</span>
          </div>
        `).join('')}
      </div>
    </div>
  `;
}

function renderEmployeeDetail(id) {
  const e = employeeRepository.getById(id);
  if (!e) return `<button class="btn-link" id="btn-back-to-list">← Retour à la liste</button><div class="empty-state"><p>Salarié introuvable.</p></div>`;

  const visibleIds = getVisibleEmployeeIdsForCurrentUser();
  if (visibleIds !== null && !visibleIds.includes(id)) {
    return `<button class="btn-link" id="btn-back-to-list">← Retour à la liste</button><div class="empty-state"><p>Vous n'avez pas accès à la fiche de ce salarié.</p></div>`;
  }

  const age = calculateAge(e.dateNaissance);
  const settings = settingsRepository.getSettings();
  const user = authRepository.getCurrentUser();
  const canEdit = canEditEmployeeRecord(e);
  const canDelete = canDeleteEmployeeRecord(e);
  const selfRhBlocked = user.role === ROLES.RH && user.id === e.id;
  // Auto-service limité (téléphone/adresse uniquement) pour qui n'a pas déjà l'édition complète sur
  // sa propre fiche — sinon le bouton "Modifier" fait déjà tout, pas besoin d'un second bouton.
  const canEditCoordonnees = !canEdit && user.id === e.id && hasPermission(user, PERMISSIONS.MODIFIER_PROPRES_COORDONNEES);
  // § VOIR_INFOS_CONTRACTUELLES : scope restreint à convention collective/statut pro/dates de fin
  // de contrat et de période d'essai — PAS type de contrat/date d'embauche/ancienneté, que
  // exportEmployeesExcel (cf. son commentaire) déclare déjà explicitement non confidentiels.
  const canSeeContractuel = user.id === e.id || hasPermission(user, PERMISSIONS.VOIR_INFOS_CONTRACTUELLES);

  // §retour Betty du 18/09/2026 (point 6) : 16 cartes empilées sur un seul écran, remplacées par 6
  // onglets (Fiche / Congés et absences / Notes de frais / Accès et droits / Documents / Parcours).
  // Chaque onglet disparaît de lui-même s'il n'a rien à montrer (module non souscrit, permission
  // absente...) : le contenu est calculé UNE FOIS ci-dessous, la présence de l'onglet en découle,
  // au lieu de dupliquer la même condition à deux endroits (le bouton d'onglet ET son contenu).
  const tabContents = {
    fiche: renderEmployeeFicheTab(e, user, settings, age, canSeeContractuel, canEdit),
    conges: renderEmployeeCongesTab(e, user),
    frais: renderEmployeeFraisCard(e, user),
    acces: renderEmployeeAccesTab(e, user),
    documents: renderEmployeeDocumentsTab(e, canEdit),
    parcours: renderEmployeeParcoursTab(e, user, canEdit)
  };
  const visibleTabs = EMPLOYEE_DETAIL_TABS.filter(t => (tabContents[t.key] || '').trim() !== '');
  const activeTab = visibleTabs.some(t => t.key === state.employeeDetailTab) ? state.employeeDetailTab : (visibleTabs[0] ? visibleTabs[0].key : 'fiche');

  return `
    ${renderBreadcrumb([{ label: 'Salariés', nav: 'employees' }, { label: `${e.prenom} ${e.nom}` }])}
    ${renderEmployeeDetailPrevNext(e)}

    <div class="detail-header card">
      ${renderAvatar(e)}
      <div class="detail-header-info">
        <h1>${personNameHtml(e)}</h1>
        <p class="view-subtitle">${escapeHtml(getPosteAccorde(e, settings) || '—')} · ${escapeHtml(e.service || '—')}</p>
        <div class="badge-row">
          ${renderContratBadge(e.typeContrat)}
          ${renderStatutBadge(e.statut)}
          ${canSeeContractuel ? `<span class="badge badge-info">${escapeHtml(e.statutPro)}</span>` : ''}
          ${e.anonymise ? '<span class="badge badge-muted" title="Données personnelles retirées automatiquement après le départ (durée de conservation, voir Paramètres > Listes)">Anonymisé</span>' : ''}
        </div>
        ${e.anonymise ? `<p class="text-muted" style="margin-top: 6px;">Fiche anonymisée le ${formatDate(e.dateAnonymisation)} (durée de conservation dépassée) : coordonnées et informations personnelles retirées (email, téléphone, adresse, numéro de sécurité sociale...). Nom, prénom, sexe, date de naissance, nationalité et dates d'entrée/sortie sont volontairement conservés : le registre unique du personnel doit pouvoir les présenter à un contrôle même après ce délai.</p>` : ''}
        ${selfRhBlocked ? '<p class="text-muted" style="margin-top: 6px;">Seul un Propriétaire peut modifier votre propre fiche.</p>' : ''}
      </div>
      <div class="detail-header-actions">
        <button class="btn btn-secondary" id="btn-toggle-favorite">${favoriteRepository.isFavoriteEmployee(e.id) ? `<span style="color: var(--color-gold);">${icon(ICONS.starFilled, 13)}</span> Favori` : icon(ICONS.star, 13) + ' Favori'}</button>
        <button class="btn btn-secondary" id="btn-print-employee-fiche">${icon(ICONS.printer, 14)} Fiche PDF</button>
        <!-- §retour Betty du 18/09/2026 (point 7) : les deux boutons s'excluaient jamais l'un
             l'autre jusqu'ici, laissant générer un certificat de travail (qui certifie une période
             d'emploi ACHEVÉE) pour un salarié toujours en poste. dateDepart (jamais dateFinContrat,
             propre aux seuls CDD/intérim) tranche : departure effective -> certificat de travail,
             encore en poste -> attestation employeur. -->
        ${canEdit && !e.dateDepart ? '<button class="btn btn-secondary" id="btn-print-attestation">Attestation employeur</button>' : ''}
        ${canEdit && e.dateDepart ? '<button class="btn btn-secondary" id="btn-print-certificat-travail">Certificat de travail</button>' : ''}
        ${canEditCoordonnees ? '<button class="btn btn-secondary" id="btn-edit-coordonnees">Modifier mes coordonnées</button>' : ''}
        ${canEdit ? '<button class="btn btn-secondary" id="btn-edit-employee">Modifier</button>' : ''}
        ${canArchiveEmployeeRecord(e) ? `<button class="btn btn-secondary" id="btn-archive-employee">${e.archive ? 'Réactiver' : 'Archiver'}</button>` : ''}
        ${canDelete ? '<button class="btn btn-danger" id="btn-delete-employee">Supprimer</button>' : ''}
      </div>
    </div>

    <div class="tabs">
      ${visibleTabs.map(t => `<button type="button" class="tab ${t.key === activeTab ? 'active' : ''}" data-employee-detail-tab="${t.key}">${escapeHtml(t.label)}</button>`).join('')}
    </div>
    ${tabContents[activeTab] || ''}
  `;
}

const EMPLOYEE_DETAIL_TABS = [
  { key: 'fiche', label: 'Fiche' },
  { key: 'conges', label: 'Congés et absences' },
  { key: 'frais', label: 'Notes de frais' },
  { key: 'acces', label: 'Accès et droits' },
  { key: 'documents', label: 'Documents' },
  { key: 'parcours', label: 'Parcours' }
];

/** §retour Betty du 18/09/2026 (point 6, "flèches précédent/suivant qui respectent le filtre/tri de
 * la liste d'origine") : réutilise exactement getFilteredSortedEmployees() (état de filtre/tri déjà
 * conservé dans `state` entre deux écrans, jamais réinitialisé en arrivant ici) — la même liste que
 * l'écran "Salariés" affiche, dans le même ordre. Rien ne s'affiche si ce salarié n'y figure pas
 * (filtré par la recherche/le filtre en cours, ou archivé) : la position n'aurait alors aucun sens. */
function renderEmployeeDetailPrevNext(e) {
  const { list } = getFilteredSortedEmployees();
  const visible = list.filter(x => !x.archive);
  const position = visible.findIndex(x => x.id === e.id);
  if (position === -1) return '';
  const prev = position > 0 ? visible[position - 1] : null;
  const next = position < visible.length - 1 ? visible[position + 1] : null;
  return `
    <div class="employee-detail-prev-next">
      <button type="button" class="btn-icon" id="btn-employee-prev" data-employee-id="${prev ? prev.id : ''}" ${prev ? '' : 'disabled'} title="${prev ? escapeHtml(`${prev.prenom} ${prev.nom}`) : 'Premier de la liste'}" aria-label="Salarié précédent">‹</button>
      <span class="text-muted" style="font-size: 13px;">${position + 1} sur ${visible.length}</span>
      <button type="button" class="btn-icon" id="btn-employee-next" data-employee-id="${next ? next.id : ''}" ${next ? '' : 'disabled'} title="${next ? escapeHtml(`${next.prenom} ${next.nom}`) : 'Dernier de la liste'}" aria-label="Salarié suivant">›</button>
    </div>
  `;
}

function renderEmployeeFicheTab(e, user, settings, age, canSeeContractuel, canEdit) {
  return `
    <div class="detail-grid-cards">
      <div class="card">
        <h2>Identité</h2>
        ${infoRow('Matricule', e.matricule)}
        ${infoRow('Email', e.email)}
        ${infoRow('Téléphone', e.telephone)}
        ${infoRow('Adresse', [e.adresse.rue, e.adresse.codePostal, e.adresse.ville].filter(Boolean).join(', '))}
        ${infoRow('Date de naissance', `${formatDate(e.dateNaissance)}${age !== null ? ' (' + age + ' ans)' : ''}`)}
        ${infoRow('Lieu de naissance', e.lieuNaissance)}
        ${infoRow('Nationalité', e.nationalite)}
        ${infoRow('N° sécurité sociale', e.numeroSecu)}
      </div>

      <div class="card">
        <h2>Contrat &amp; poste</h2>
        ${infoRow('Service', e.service)}
        ${infoRow('Équipe', e.equipe)}
        ${infoRow('Poste', getPosteAccorde(e, settings))}
        ${infoRow('Manager(s)', managerNames(e.managerIds))}
        ${canSeeContractuel ? infoRow('Convention collective', e.conventionCollective) : ''}
        ${canSeeContractuel ? infoRow('Catégorie de salarié', e.statutPro) : ''}
        ${infoRow('Type de contrat', e.typeContrat)}
        ${infoRow('Date d\'embauche', formatDate(e.dateEmbauche))}
        ${infoRow('Ancienneté', calculateAnciennete(e.dateEmbauche))}
        ${canSeeContractuel && (e.typeContrat === 'CDD' || e.typeContrat === 'Intérim') ? infoRow('Date de fin de contrat', formatDate(e.dateFinContrat)) : ''}
        ${canSeeContractuel && e.dateFinPeriodeEssai ? infoRow('Fin de période d\'essai', formatDate(e.dateFinPeriodeEssai)) : ''}
        ${(() => {
          if (!canSeeContractuel || !e.dateFinPeriodeEssai) return '';
          const delai = getDelaiPrevenanceFinEssai(e);
          if (!delai) return '';
          const enRetard = delai.dateLimitePrevenance < toISODate(new Date());
          return infoRow('Délai de prévenance', `${enRetard ? 'Dépassé' : `Prévenir avant le ${formatDate(delai.dateLimitePrevenance)}`} (préavis ${delai.delaiLabel})`);
        })()}
        ${canSeeContractuel && e.dateFinPeriodeEssai ? `<p class="form-hint">Délai de prévenance estimé (article L1221-25 du Code du travail) — à confirmer avec votre expert-comptable/juriste avant toute rupture de période d'essai.</p>` : ''}
        ${canSeeContractuel && e.dateDernierEntretienProfessionnel ? infoRow('Dernier entretien professionnel', formatDate(e.dateDernierEntretienProfessionnel)) : ''}
      </div>

      ${ifModule('rh', renderVisitesMedicalesCard(e, canEdit))}

      ${canSeeContractuel ? renderAvenantsCard(e.avenants || [], canEdit) : ''}

      <div class="card">
        <h2>Temps de travail</h2>
        ${infoRow('Temps de travail', e.tempsTravail)}
        ${infoRow('Pourcentage d\'activité', formatPercentFR(e.pourcentageActivite))}
        ${infoRow('Heures hebdomadaires', formatNumberFR(e.horairesHebdo) + ' h')}
        ${infoRow('Forfait', e.forfait)}
        ${infoRow('Jours travaillés', (e.joursTravailles || []).join(', '))}
        ${infoRow('Régime RTT', e.regimeRTT || '—')}
        ${(() => {
          const year = new Date().getFullYear();
          const contingent = settingsRepository.getSettings().contingentAnnuelHeuresSup;
          const cumul = getHeuresSupAnnee(e, year);
          if (!cumul) return '';
          const depasse = cumul >= contingent;
          return `
            <div class="info-row">
              <span class="info-label">Heures sup. cumulées en ${year}</span>
              <span class="info-value${depasse ? ' text-danger' : ''}">${formatNumberFR(cumul)} h / ${formatNumberFR(contingent)} h (contingent annuel)</span>
            </div>
            ${depasse ? `<p class="text-muted text-danger" style="margin-top: 4px;">Contingent annuel dépassé : un repos compensateur obligatoire s'applique (taux selon effectif/accord de branche, à vérifier avec votre gestionnaire de paie).</p>` : ''}
          `;
        })()}
        ${(() => {
          const repos = getReposCompensateurSolde(e);
          if (!repos.credit && !repos.pris) return '';
          return `
            <div class="info-row">
              <span class="info-label">Solde de repos compensateur</span>
              <span class="info-value${repos.solde < 0 ? ' text-danger' : ''}">${formatNumberFR(repos.solde)} h</span>
            </div>
            <p class="form-hint" style="margin-top: -2px;">${formatNumberFR(repos.credit)} h acquises (taux de majoration ${formatNumberFR(settingsRepository.getSettings().tauxReposCompensateur)} %) − ${formatNumberFR(repos.pris)} h prises.</p>
          `;
        })()}
      </div>

      ${renderConfidentialEmployeeCard(e, user)}
    </div>
  `;
}

function renderEmployeeCongesTab(e, user) {
  return `
    <div class="detail-grid-cards">
      ${hasModule('conges') ? `
      <div class="card">
        <!-- §retour QA du 27/08/2026 ("fais un panneau déroulant pour compteurs de congés") : cette
             carte peut afficher un très grand nombre de types (chacun avec son détail acquis/pris/
             en cours), au point de dominer toute la fiche à elle seule. <details>/<summary> natifs
             (repliable au clic, sans JS, accessible par défaut) plutôt qu'un composant maison — les
             boutons "Demander" restent TOUJOURS visibles, en dehors du panneau repliable, pour rester
             utilisables sans avoir à déplier le détail des compteurs. -->
        <div class="view-header-row">
          <h2>Compteurs de congés</h2>
          <div class="detail-header-actions">
            <button class="btn btn-secondary btn-sm" id="btn-request-leave">Demander un congé</button>
            <!-- §retour Betty du 17/09/2026 (audit "millimètre par millimètre") : le télétravail
                 dépend du module "planning", pas "congés" (voir le commentaire de PARAMETRES_TABS/
                 NAV_ITEMS sur ce point) — bouton retiré ici quand seul "congés" est souscrit. -->
            ${hasModule('planning') ? '<button class="btn btn-secondary btn-sm" id="btn-request-telework">Demander du télétravail</button>' : ''}
          </div>
        </div>
        <details class="collapsible-panel">
          <summary>Voir le détail des compteurs</summary>
          ${user.id === e.id || hasPermission(user, PERMISSIONS.VOIR_COMPTEURS)
            ? renderEmployeeBalances(e, user.id !== e.id && hasPermission(user, PERMISSIONS.MODIFIER_COMPTEURS))
            : '<p class="text-muted">Vous n\'avez pas accès aux compteurs de ce salarié.</p>'}
        </details>
      </div>
      ` : ''}

      ${renderTypesAbsenceCard(e, user)}
    </div>
  `;
}

function renderEmployeeAccesTab(e, user) {
  return `
    <div class="detail-grid-cards">
      ${renderCompteCard(e, user)}
      ${renderPermissionsCard(e, user)}
      ${renderMenusAutorisesCard(e, user)}
    </div>
  `;
}

function renderEmployeeDocumentsTab(e, canEdit) {
  return `
    <div class="detail-grid-cards">
      ${renderEmployeeDocumentsCard(e)}
      ${renderGenererDocumentCard(e, canEdit)}
    </div>
  `;
}

function renderEmployeeParcoursTab(e, user, canEdit) {
  return `
    <div class="detail-grid-cards">
      ${canEdit ? renderChecklistCard('Checklist d\'intégration', 'onboardingChecklist', ensureOnboardingChecklist(e)) : ''}

      ${canEdit ? (e.offboardingChecklist && e.offboardingChecklist.length
        ? renderChecklistCard('Checklist de départ', 'offboardingChecklist', e.offboardingChecklist)
        : `<div class="card"><h2>Checklist de départ</h2><p class="text-muted" style="margin-bottom: 10px;">À démarrer quand ce salarié quitte l'entreprise (récupération du matériel, désactivation des accès, solde de tout compte...).</p><button type="button" class="btn btn-secondary btn-sm" id="btn-demarrer-offboarding">Démarrer le offboarding</button></div>`
      ) : ''}

      ${hasPermission(user, PERMISSIONS.VOIR_JOURNAL_AUDIT) ? renderEmployeeActivityCard(e) : ''}
    </div>
  `;
}

/** §demande Betty du 04/09/2026 : la fiche salarié affichait déjà "Compteurs de congés" mais rien sur
 * les notes de frais de ce salarié — même emplacement, même logique d'accès (soi-même ou
 * VOIR_COMPTEURS, comme les compteurs de congés juste au-dessus — pas de permission dédiée "voir les
 * notes de frais d'un tiers" dans le catalogue, VOIR_COMPTEURS joue déjà ce rôle pour ce type
 * d'information personnelle/financière). Masquée entièrement (pas de carte vide) si l'entreprise n'a
 * pas souscrit au module frais, ou si l'utilisateur n'a pas accès. */
/** §retour Betty du 11/09/2026 (point 1, étape 2) : hydrateCurrentCompany ne rapatrie plus qu'une
 * fenêtre glissante de notes de frais (~40 mois, voir HYDRATION_WINDOW_MONTHS, supabase-client.js) —
 * un simple .reduce() sur le cache local sous-évaluerait silencieusement ce total pour un salarié
 * dont l'historique dépasse la fenêtre. Le vrai total vient du serveur (get_expense_totals_for_employee,
 * RLS-scopée), chargé une fois par salarié consulté (même patron que loadBertolisTickets) ; en
 * attendant la réponse (ou si elle échoue), on affiche les chiffres locaux comme valeur immédiate —
 * jamais un total inférieur au vrai n'est affiché plus d'un instant. */
function ensureFraisTotalsLoaded(employeeId) {
  state.fraisTotalsCache = state.fraisTotalsCache || {};
  if (state.fraisTotalsCache[employeeId]) return;
  state.fraisTotalsCache[employeeId] = { loading: true };
  window.SupabaseSync.getExpenseTotalsForEmployee(employeeId).then((result) => {
    state.fraisTotalsCache[employeeId] = result;
    if (state.view === 'employeeDetail') render();
  });
}

/** §retour Betty du 14/09/2026 (Module RH point 1, "modèles de documents avec fusion automatique") :
 * un modèle par bouton plutôt qu'une liste déroulante — cohérent avec le reste de la fiche salarié
 * (boutons "Attestation employeur"/"Certificat de travail" juste au-dessus), et jamais plus de
 * quelques modèles en pratique. Même portée que ces boutons existants (canEdit, jamais ouvert au
 * salarié lui-même : ce sont des documents officiels, pas une auto-consultation). */
function renderGenererDocumentCard(e, canEdit) {
  if (!canEdit) return '';
  // §retour Betty du 17/09/2026 (audit "millimètre par millimètre") : la génération de documents fait
  // partie du même coffre-fort RH que renderEmployeeDocumentsCard ci-dessus — même correctif, même
  // raison (la fiche salarié reste accessible sans le module RH, voir NAV_ITEMS 'employees').
  if (!hasModule('rh')) return '';
  const templates = documentTemplateRepository.getAll();
  // §retour Betty du 18/09/2026 (point 9) : sans aucun modèle configuré, cette carte n'affichait
  // qu'un message d'administration ("créez-en un dans Paramètres...") à TOUT le monde ayant canEdit,
  // pas seulement à qui gère les modèles, une friction permanente pour une fonctionnalité que la
  // plupart des entreprises ne configureront jamais. Masquée entièrement plutôt qu'un message vide.
  if (!templates.length) return '';
  return `
    <div class="card">
      <h2>Documents à générer</h2>
      <div class="badge-row" style="gap: 10px;">
        ${templates.map(t => `<button type="button" class="btn btn-secondary btn-sm" data-generer-document="${t.id}">${icon(ICONS.document, 13)} ${escapeHtml(t.nom)}</button>`).join('')}
      </div>
    </div>
  `;
}

/** Fusionne le modèle avec les données RÉELLES de ce salarié (fusionnerModeleDocument/
 * construireValeursFusionModele, data.js) et affiche le résultat dans une .print-area, même patron
 * que openAttestationSalaireModal : un document généré n'est jamais enregistré tel quel (recalculé à
 * chaque ouverture), pour ne jamais figer une donnée salarié devenue fausse depuis. escapeHtml
 * appliqué à CHAQUE valeur avant fusion : un champ salarié (ex. un poste saisi librement) ne doit
 * jamais pouvoir injecter du HTML dans le document final. */
function openGenererDocumentModal(templateId, employeeId) {
  const template = documentTemplateRepository.getById(templateId);
  const employee = employeeRepository.getById(employeeId);
  if (!template || !employee) { showToast('Modèle ou salarié introuvable.', 'error'); return; }
  const company = DB.getCurrentCompany();
  const valeursBrutes = construireValeursFusionModele(employee, company);
  const valeursEchappees = {};
  Object.keys(valeursBrutes).forEach(champ => { valeursEchappees[champ] = escapeHtml(String(valeursBrutes[champ] ?? '')); });
  // Le corps du modèle est échappé AVANT la fusion (jamais après, ce qui doublerait l'échappement
  // des valeurs déjà échappées ci-dessus) : "{{", "}}" et les noms de champs (lettres/chiffres/_)
  // traversent escapeHtml sans y être touchés, donc les espaces réservés restent reconnaissables.
  const corpsFusionne = fusionnerModeleDocument(escapeHtml(template.corps), valeursEchappees);

  const html = `
    <div class="modal">
      <div class="modal-header">
        <h2>${escapeHtml(template.nom)}</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <div class="modal-body">
        <div class="print-area" id="genere-document-print-area" style="white-space: pre-wrap;">${corpsFusionne}</div>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Fermer</button>
        <button type="button" class="btn btn-primary" id="btn-print-genere-document">Imprimer / Export PDF</button>
      </div>
    </div>
  `;
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');
  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('btn-print-genere-document').addEventListener('click', () => {
    auditLogRepository.logAudit('Export', 'Document généré', `${template.nom} · ${employee.prenom} ${employee.nom}`);
    window.print();
  });
}

function bindGenererDocumentEvents(employeeId) {
  document.querySelectorAll('[data-generer-document]').forEach(btn => {
    btn.addEventListener('click', () => openGenererDocumentModal(btn.dataset.genererDocument, employeeId));
  });
}

function renderEmployeeFraisCard(e, user) {
  if (!hasModule('frais')) return '';
  if (user.id !== e.id && !hasPermission(user, PERMISSIONS.VOIR_COMPTEURS)) return '';
  const expenses = expenseRepository.getAll().filter(n => n.employeeId === e.id).sort((a, b) => b.date.localeCompare(a.date));
  ensureFraisTotalsLoaded(e.id);
  const serverTotals = state.fraisTotalsCache[e.id];
  const hasServerTotals = serverTotals && serverTotals.success;
  const total = hasServerTotals ? serverTotals.totalMontant : expenses.reduce((sum, n) => sum + n.montantTTC, 0);
  const enAttente = hasServerTotals ? serverTotals.enAttenteCount : expenses.filter(n => n.statut === 'En attente').length;
  const nombreNotes = hasServerTotals ? serverTotals.totalCount : expenses.length;
  return `
    <div class="card">
      <h2>Notes de frais</h2>
      <p class="view-subtitle">${nombreNotes} note${nombreNotes > 1 ? 's' : ''} · ${formatCurrencyFR(total)} TTC${enAttente ? ` · ${enAttente} en attente` : ''}</p>
      ${nombreNotes === 0 ? '<p class="text-muted">Aucune note de frais enregistrée.</p>' : expenses.length === 0 ? '<p class="text-muted">Notes existantes, toutes antérieures à 40 mois (hors du cache local) : contactez BERTOLIS si vous avez besoin d\'en consulter le détail.</p>' : `
        <details class="collapsible-panel">
          <summary>Voir les notes de frais</summary>
          <div style="overflow-x: auto;">
            <table class="table">
              <thead><tr><th>Date</th><th>Catégorie</th><th>Libellé</th><th class="cell-numeric">Montant</th><th>Statut</th></tr></thead>
              <tbody>
                ${expenses.slice(0, 20).map(n => `
                  <tr>
                    <td>${formatDate(n.date)}</td>
                    <td>${escapeHtml(n.categorie)}</td>
                    <td>${escapeHtml(n.libelle)}</td>
                    <td class="cell-numeric">${formatCurrencyFR(n.montantTTC)}</td>
                    <td>${renderRequestStatutBadge(n)}</td>
                  </tr>
                `).join('')}
              </tbody>
            </table>
          </div>
          ${expenses.length > 20 ? `<p class="text-muted" style="margin-top: 8px;">${expenses.length - 20} note(s) supplémentaire(s), voir l'écran Notes de frais pour l'historique complet.</p>` : ''}
        </details>
      `}
    </div>
  `;
}

/** Sprint SIRH premium §1 : liste blanche par salarié des types d'absence actifs/visibles au
 * niveau entreprise — décocher un type ici l'empêche de le demander lui-même, même si l'entreprise
 * l'autorise en général (ex. "Télétravail" ou "Congé sans solde" désactivés pour un salarié précis).
 * Réutilise canEditEmployeeRecord (MODIFIER_SALARIE) plutôt que d'inventer une nouvelle permission —
 * le catalogue des 31 du §8 reste fermé. */
function renderTypesAbsenceCard(e, user) {
  // §retour Betty du 17/09/2026 (audit "millimètre par millimètre") : les types d'absence vivent sous
  // le module congés (NAV_ITEMS 'absences', module: 'conges') — cette carte n'avait jamais vérifié le
  // module, alors que la fiche salarié reste accessible sans lui (registre de base).
  if (!hasModule('conges')) return '';
  if (!canEditEmployeeRecord(e)) return '';
  const types = leaveTypeRepository.getLeaveTypes().filter(t => t.actif && t.visibleSalarie);
  if (types.length === 0) return '';
  const desactives = new Set(e.typesAbsenceDesactives || []);
  return `
    <div class="card">
      <h2>Types d'absences autorisés</h2>
      <p class="text-muted">Décochez un type pour empêcher ce salarié de le demander lui-même, même si l'entreprise l'autorise en général.</p>
      <div class="form-grid checkbox-grid">
        ${types.map(t => `
          <div class="form-field form-field-checkbox">
            <label>
              <input type="checkbox" data-type-absence-autorise="${t.id}" ${desactives.has(t.id) ? '' : 'checked'}>
              ${escapeHtml(t.icone)} ${escapeHtml(t.nom)}
            </label>
          </div>
        `).join('')}
      </div>
    </div>
  `;
}

function bindTypesAbsenceCardEvents(employeeId) {
  document.querySelectorAll('[data-type-absence-autorise]').forEach(checkbox => {
    checkbox.addEventListener('change', (evt) => {
      const typeId = evt.target.dataset.typeAbsenceAutorise;
      const employee = employeeRepository.getById(employeeId);
      const desactives = new Set(employee.typesAbsenceDesactives || []);
      if (evt.target.checked) desactives.delete(typeId); else desactives.add(typeId);
      employeeRepository.update(employeeId, { typesAbsenceDesactives: [...desactives] });
      const type = leaveTypeRepository.getLeaveTypeById(typeId);
      auditLogRepository.logAudit('Modification', 'Types d\'absence autorisés', `${employee.prenom} ${employee.nom} · ${type.nom} ${evt.target.checked ? 'autorisé' : 'désactivé'}`);
      showToast('Mis à jour.');
    });
  });
}

/** § GERER_UTILISATEURS : déverrouillage de compte et réinitialisation de mot de passe par un
 * administrateur — jamais sur sa propre fiche (on gère son propre mot de passe via le menu
 * utilisateur, DB.changePassword, qui exige de connaître l'ancien). */
function renderCompteCard(e, user) {
  if (!hasPermission(user, PERMISSIONS.GERER_UTILISATEURS) || user.id === e.id) return '';
  return `
    <div class="card">
      <h2>Compte</h2>
      <div class="badge-row" style="margin-bottom: 10px;">
        <span class="badge badge-${e.authUserId ? 'success' : 'warning'}">${e.authUserId ? 'Compte actif' : 'Pas de compte de connexion'}</span>
      </div>
      <p class="text-muted" style="margin-bottom: 10px;">Rôle actuel : <strong>${escapeHtml(ROLE_LABELS[e.role] || e.role)}</strong></p>
      <div class="detail-header-actions">
        ${e.authUserId
          ? '<button class="btn btn-secondary btn-sm" id="btn-forcer-mot-de-passe">Réinitialiser le mot de passe</button>'
          : '<button class="btn btn-primary btn-sm" id="btn-creer-compte-connexion">Créer les identifiants de connexion</button>'}
        ${e.role !== ROLES.PROPRIETAIRE ? '<button class="btn btn-secondary btn-sm" id="btn-changer-role">Changer le rôle</button>' : ''}
      </div>
      ${e.role === ROLES.PROPRIETAIRE ? '<p class="text-muted" style="margin-top: 10px;">Le rôle Propriétaire se transfère depuis le menu du Propriétaire lui-même (haut à droite), pas depuis cette fiche.</p>' : ''}
    </div>
  `;
}

/** Le rôle Propriétaire n'apparaît jamais dans les options : il ne se change jamais par une
 * simple mise à jour de rôle (le trigger Postgres guard_employee_role_change, migration 0033,
 * refuse toute tentative hors du flux dédié transfer_proprietaire — voir "Transférer la
 * propriété" dans le menu du Propriétaire). Ce bouton n'est de toute façon jamais proposé sur
 * la fiche du Propriétaire lui-même (renderCompteCard). */
function openChangeRoleModal(employeeId) {
  const employee = employeeRepository.getById(employeeId);
  if (!employee) { showToast('Ce salarié n\'est plus disponible.', 'error'); return; }
  const actingUser = authRepository.getCurrentUser();
  const roleOptions = Object.values(ROLES).filter(r => r !== employee.role && r !== ROLES.PROPRIETAIRE);

  const html = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>Changer le rôle</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="changer-role-form">
        <div class="modal-body">
          <p class="text-muted">${personNameHtml(employee)} — rôle actuel : <strong>${escapeHtml(ROLE_LABELS[employee.role] || employee.role)}</strong>.</p>
          <div class="form-field">
            <label for="f-nouveau-role">Nouveau rôle *</label>
            <select class="input" id="f-nouveau-role" name="nouveauRole" required>
              <option value="">—</option>
              ${roleOptions.map(r => `<option value="${r}">${escapeHtml(ROLE_LABELS[r])}</option>`).join('')}
            </select>
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="submit" class="btn btn-primary">Changer le rôle</button>
        </div>
      </form>
    </div>
  `;

  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');

  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('changer-role-form').addEventListener('submit', (evt) => {
    evt.preventDefault();
    const newRole = document.getElementById('f-nouveau-role').value;
    const result = employeeRepository.changerRole(employeeId, newRole, actingUser.id);
    if (!result.success) { showToast(result.error, 'error'); return; }
    showToast('Rôle mis à jour.');
    closeModal();
    render();
  });
}

/** Transfert de propriété (§5 de l'audit) : réservé au Propriétaire actuel, sur lui-même — jamais
 * depuis la fiche de quelqu'un d'autre (voir renderUserMenuPanel, seul point d'entrée). La liste
 * ne propose que des salariés actifs AVEC déjà un compte de connexion réel (authUserId) : on ne
 * transfère jamais la propriété à quelqu'un qui ne pourrait pas se connecter pour l'exercer. Le
 * Propriétaire actuel choisit explicitement son propre rôle de repli — jamais un "Directeur"
 * décoratif implicite (écarté par le client). Toute la vraie logique de garde (unicité, dernier
 * Propriétaire, self-service) vit côté serveur (transfer_proprietaire, migration 0033) : cette
 * modale ne fait qu'aider à ne pas soumettre un choix évidemment invalide. */
function openTransferProprietaireModal() {
  const user = authRepository.getCurrentUser();
  const candidats = employeeRepository.getAll().filter(e => !e.archive && e.id !== user.id && e.authUserId);
  const rolesRepli = [ROLES.RH, ROLES.MANAGER, ROLES.COMPTABILITE, ROLES.SALARIE];

  const html = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>Transférer la propriété</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="transfer-proprietaire-form">
        <div class="modal-body">
          <p class="text-muted">Vous êtes actuellement le Propriétaire de ${escapeHtml((DB.getCurrentCompany() || {}).raisonSociale || 'votre entreprise')}. Ce transfert est immédiat et irréversible depuis cet écran (le nouveau Propriétaire pourra vous transférer la propriété en retour s'il le souhaite).</p>
          ${!candidats.length ? `<p class="login-error" role="alert">Aucun salarié éligible : la personne visée doit déjà avoir un compte de connexion actif (voir sa fiche → "Créer les identifiants de connexion").</p>` : `
            <div class="form-field">
              <label for="f-nouveau-proprietaire">Nouveau Propriétaire *</label>
              <select class="input" id="f-nouveau-proprietaire" name="nouveauProprietaire" required>
                <option value="">—</option>
                ${candidats.map(c => `<option value="${escapeHtml(c.id)}">${personNameHtml(c)} (${escapeHtml(ROLE_LABELS[c.role] || c.role)})</option>`).join('')}
              </select>
            </div>
            <div class="form-field" style="margin-top: 12px;">
              <label for="f-nouveau-role-perso">Votre nouveau rôle après transfert *</label>
              <select class="input" id="f-nouveau-role-perso" name="nouveauRolePerso" required>
                <option value="">—</option>
                ${rolesRepli.map(r => `<option value="${r}">${escapeHtml(ROLE_LABELS[r])}</option>`).join('')}
              </select>
            </div>
          `}
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          ${candidats.length ? '<button type="submit" class="btn btn-primary">Transférer la propriété</button>' : ''}
        </div>
      </form>
    </div>
  `;

  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');

  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  const form = document.getElementById('transfer-proprietaire-form');
  if (form && candidats.length) {
    form.addEventListener('submit', async (evt) => {
      evt.preventDefault();
      const newProprietaireId = document.getElementById('f-nouveau-proprietaire').value;
      const nouveauRolePerso = document.getElementById('f-nouveau-role-perso').value;
      const submitBtn = form.querySelector('button[type="submit"]');
      submitBtn.disabled = true;
      submitBtn.textContent = 'Transfert en cours...';
      const result = await employeeRepository.transferProprietaire(newProprietaireId, nouveauRolePerso);
      if (!result.success) {
        showToast(result.error, 'error');
        submitBtn.disabled = false;
        submitBtn.textContent = 'Transférer la propriété';
        return;
      }
      showToast('Propriété transférée.');
      closeModal();
      render();
    });
  }
}

function openForcerMotDePasseModal(employeeId) {
  const employee = employeeRepository.getById(employeeId);
  if (!employee) { showToast('Ce salarié n\'est plus disponible.', 'error'); return; }
  const html = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>Réinitialiser le mot de passe</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="forcer-mdp-form">
        <div class="modal-body">
          <p class="text-muted">${personNameHtml(employee)} — communiquez ce nouveau mot de passe au salarié par un autre moyen que cette application.</p>
          <div class="form-field">
            <label for="f-nouveau-mdp">Nouveau mot de passe (6 caractères minimum) *</label>
            <input class="input" type="text" id="f-nouveau-mdp" name="nouveauMotDePasse" minlength="6" required>
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="submit" class="btn btn-primary">Réinitialiser</button>
        </div>
      </form>
    </div>
  `;

  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');

  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('forcer-mdp-form').addEventListener('submit', async (evt) => {
    evt.preventDefault();
    const submitBtn = evt.target.querySelector('button[type="submit"]');
    submitBtn.disabled = true;
    submitBtn.textContent = 'Réinitialisation...';
    const result = await employeeRepository.forcerMotDePasse(employeeId, document.getElementById('f-nouveau-mdp').value);
    if (!result.success) { showToast(result.error, 'error'); submitBtn.disabled = false; submitBtn.textContent = 'Réinitialiser'; return; }
    showToast('Mot de passe réinitialisé.');
    closeModal();
    render();
  });
}

/** § GERER_UTILISATEURS : crée le compte de connexion d'un salarié qui n'en a pas encore (voir
 * DB.creerCompteConnexion / manage-employee-account) — remplace l'ancien parcours d'auto-inscription
 * "Créer un compte" (retiré). Mot de passe généré côté serveur, affiché une seule fois ensuite via
 * showGeneratedPasswordModal. */
function openCreerCompteConnexionModal(employeeId) {
  const employee = employeeRepository.getById(employeeId);
  if (!employee) { showToast('Ce salarié n\'est plus disponible.', 'error'); return; }
  const html = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>Créer les identifiants de connexion</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <div class="modal-body">
        <p class="text-muted">
          Un compte de connexion sera créé pour <strong>${personNameHtml(employee)}</strong>
          (${escapeHtml(employee.email)}), avec un mot de passe temporaire généré automatiquement.
          Vous devrez le transmettre vous-même au salarié (oral, SMS...) ; il devra le changer dès sa première connexion.
        </p>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
        <button type="button" class="btn btn-primary" id="btn-confirm-creer-compte">Créer le compte</button>
      </div>
    </div>
  `;

  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');

  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('btn-confirm-creer-compte').addEventListener('click', async () => {
    const btn = document.getElementById('btn-confirm-creer-compte');
    btn.disabled = true;
    btn.textContent = 'Création...';
    const result = await employeeRepository.creerCompteConnexion(employeeId);
    if (!result.success) { showToast(result.error, 'error'); closeModal(); return; }
    showGeneratedPasswordModal(employee, result.password);
    render();
  });
}

/** Affiche une seule fois le mot de passe temporaire généré par creerCompteConnexion/
 * forcerNouveauMotDePasse — Supabase ne le renvoie plus jamais ensuite (par sécurité). */
function showGeneratedPasswordModal(employee, password) {
  const html = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>Compte créé</h2>
      </div>
      <div class="modal-body">
        <p class="text-muted">Communiquez ces identifiants à <strong>${personNameHtml(employee)}</strong> par un autre moyen que cette application. Ce mot de passe ne sera plus jamais affiché.</p>
        <div class="form-field">
          <label for="f-generated-email">Email</label>
          <input class="input" type="text" id="f-generated-email" readonly value="${escapeHtml(employee.email)}">
        </div>
        <div class="form-field">
          <label for="f-generated-password">Mot de passe temporaire</label>
          <input class="input" type="text" id="f-generated-password" readonly value="${escapeHtml(password)}">
        </div>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-primary" id="btn-close-password-modal">J'ai noté le mot de passe</button>
      </div>
    </div>
  `;
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');
  document.getElementById('btn-close-password-modal').addEventListener('click', closeModal);
}

/** Surcharges individuelles (§8) pour les permissions déjà réellement câblées dans l'app — voir
 * hasPermission() dans data.js. Réservé à qui a la permission GERER_PERMISSIONS (Propriétaire par
 * défaut, §9.3) ; personne ne modifie ses propres permissions, pour éviter un auto-verrouillage. */
function renderPermissionsCard(e, user) {
  if (!hasPermission(user, PERMISSIONS.GERER_PERMISSIONS)) return '';
  if (user.id === e.id) {
    return `
      <div class="card">
        <h2>Permissions individuelles</h2>
        <p class="text-muted">Vous ne pouvez pas modifier vos propres permissions.</p>
      </div>
    `;
  }

  const wired = [
    { key: PERMISSIONS.MODIFIER_PROPRES_COORDONNEES, label: 'Modifier ses propres coordonnées (téléphone/adresse)' },
    { key: PERMISSIONS.VOIR_SALARIES, label: 'Voir les salariés' },
    { key: PERMISSIONS.VOIR_EQUIPE, label: 'Voir son équipe' },
    { key: PERMISSIONS.VOIR_COMPTEURS, label: 'Voir les compteurs de congés d\'un autre salarié' },
    { key: PERMISSIONS.MODIFIER_COMPTEURS, label: 'Ajuster manuellement un compteur de congés' },
    { key: PERMISSIONS.VALIDER_ABSENCE, label: 'Valider une absence' },
    { key: PERMISSIONS.REFUSER_ABSENCE, label: 'Refuser une absence (congé ou télétravail)' },
    { key: PERMISSIONS.ANNULER_ABSENCE, label: 'Annuler une absence' },
    { key: PERMISSIONS.VALIDER_NOTE_FRAIS, label: 'Valider une note de frais (RH/Propriétaire)' },
    { key: PERMISSIONS.CONTROLER_NOTE_FRAIS, label: 'Contrôler une note de frais (étape non finale du circuit)' },
    { key: PERMISSIONS.MARQUER_NOTE_REMBOURSEE, label: 'Marquer une note de frais remboursée (étape finale du circuit)' },
    { key: PERMISSIONS.VOIR_INFOS_FINANCIERES, label: 'Voir les informations financières (salaire)' },
    { key: PERMISSIONS.VOIR_INFOS_CONTRACTUELLES, label: 'Voir la convention collective/statut pro/dates de fin de contrat et d\'essai' },
    { key: PERMISSIONS.GERER_PARAMETRES, label: 'Gérer les paramètres' },
    { key: PERMISSIONS.GERER_ABONNEMENTS, label: 'Voir/gérer l\'abonnement de l\'entreprise' },
    { key: PERMISSIONS.GERER_UTILISATEURS, label: 'Déverrouiller un compte / réinitialiser un mot de passe' },
    { key: PERMISSIONS.EXPORTER_PAIE, label: 'Exporter la paie' },
    { key: PERMISSIONS.CALCULER_TICKETS_RESTAURANT, label: 'Accéder aux tickets restaurant' },
    { key: PERMISSIONS.CORRIGER_TICKETS_RESTAURANT, label: 'Corriger manuellement les tickets restaurant' },
    { key: PERMISSIONS.CREER_SALARIE, label: 'Créer un salarié' },
    { key: PERMISSIONS.MODIFIER_SALARIE, label: 'Modifier un salarié' },
    { key: PERMISSIONS.ARCHIVER_SALARIE, label: 'Archiver un salarié' },
    // §retour Betty du 18/09/2026 (point 9) : SUPPRIMER_SALARIE volontairement absent de cette
    // liste, jamais accordable en exception individuelle (déjà réservée au rôle Propriétaire par
    // défaut, vérifiée côté serveur, voir DEFAULT_ROLE_PERMISSIONS) : une suppression définitive n'a
    // pas sa place parmi des surcharges au cas par cas.
    { key: PERMISSIONS.VOIR_JOURNAL_AUDIT, label: 'Voir le journal d\'audit' }
  ];
  const overrides = e.permissionsOverrides || {};
  const roleDefaults = DEFAULT_ROLE_PERMISSIONS[e.role] || [];
  // §retour Betty du 18/09/2026 (point 6) : "24 menus déroulants" (23 aujourd'hui, voir le retrait
  // de SUPPRIMER_SALARIE au point 9) affichés systématiquement, alors que la quasi-totalité des
  // salariés suivent exactement le défaut de leur rôle sans aucune exception — repliée derrière le
  // rappel du défaut du rôle + un bouton "Ajouter une exception", seules les exceptions RÉELLEMENT
  // posées restent visibles sans avoir à déplier quoi que ce soit.
  const exceptions = wired.filter(p => Object.prototype.hasOwnProperty.call(overrides, p.key));

  return `
    <div class="card">
      <h2>Permissions individuelles</h2>
      <p class="text-muted">Permissions par défaut du rôle « ${escapeHtml(ROLE_LABELS[e.role] || e.role)} ».</p>
      ${exceptions.length ? `
        <div class="mini-list" style="margin: 10px 0;">
          ${exceptions.map(p => `
            <div class="mini-list-item">
              <span>${escapeHtml(p.label)} : <strong>${overrides[p.key] ? 'toujours autorisé' : 'toujours refusé'}</strong></span>
              <button type="button" class="btn-link" data-remove-permission-exception="${p.key}">Retirer l'exception</button>
            </div>
          `).join('')}
        </div>
      ` : `<p class="text-muted" style="font-size: 13px; margin: 10px 0;">Aucune exception : ce salarié suit exactement les permissions par défaut de son rôle.</p>`}
      <details class="collapsible-panel">
        <summary>Ajouter ou modifier une exception</summary>
        <div class="form-grid" style="margin-top: 12px;">
          ${wired.map(p => {
            const current = Object.prototype.hasOwnProperty.call(overrides, p.key) ? String(overrides[p.key]) : '';
            const defaultLabel = roleDefaults.includes(p.key) ? 'autorisé' : 'refusé';
            return `
              <div class="form-field">
                <label for="perm-${p.key}">${escapeHtml(p.label)}</label>
                <select class="input" id="perm-${p.key}" data-permission-key="${p.key}">
                  <option value="" ${current === '' ? 'selected' : ''}>Par défaut du rôle (${defaultLabel})</option>
                  <option value="true" ${current === 'true' ? 'selected' : ''}>Toujours autorisé</option>
                  <option value="false" ${current === 'false' ? 'selected' : ''}>Toujours refusé</option>
                </select>
              </div>
            `;
          }).join('')}
        </div>
      </details>
    </div>
  `;
}

function bindPermissionsCardEvents(employeeId) {
  document.querySelectorAll('[data-permission-key]').forEach(select => {
    select.addEventListener('change', (evt) => {
      const key = evt.target.dataset.permissionKey;
      const employee = employeeRepository.getById(employeeId);
      const overrides = Object.assign({}, employee.permissionsOverrides);
      if (evt.target.value === '') delete overrides[key];
      else overrides[key] = evt.target.value === 'true';
      employeeRepository.update(employeeId, { permissionsOverrides: overrides });
      auditLogRepository.logAudit('Modification', 'Permissions', `${employee.prenom} ${employee.nom} · ${key} = ${evt.target.value || 'défaut du rôle'}`);
      showToast('Permission mise à jour.');
      navigateTo('employee-detail', { currentEmployeeId: employeeId, employeeDetailTab: state.employeeDetailTab });
    });
  });

  document.querySelectorAll('[data-remove-permission-exception]').forEach(btn => {
    btn.addEventListener('click', () => {
      const key = btn.dataset.removePermissionException;
      const employee = employeeRepository.getById(employeeId);
      const overrides = Object.assign({}, employee.permissionsOverrides);
      delete overrides[key];
      employeeRepository.update(employeeId, { permissionsOverrides: overrides });
      auditLogRepository.logAudit('Modification', 'Permissions', `${employee.prenom} ${employee.nom} · ${key} = défaut du rôle`);
      showToast('Exception retirée.');
      navigateTo('employee-detail', { currentEmployeeId: employeeId, employeeDetailTab: state.employeeDetailTab });
    });
  });
}

/** §retour du 21/08/2026 "pouvoir enlever l'accès à tous les menus [...] un pavé pour choisir les
 * modules que les salariés ont le droit d'utiliser" : décocher un menu ici le retire de la
 * navigation de CE salarié uniquement (voir navItemsForRole) — au-delà de ce que son rôle/ses
 * permissions/les modules souscrits par l'entreprise autorisent déjà (baseNavItemsForRole), jamais
 * en plus. "Accueil" n'est volontairement pas proposé : toujours conservé comme page de repli.
 * Même garde-fou que Permissions individuelles : jamais sur sa propre fiche. */
function renderMenusAutorisesCard(e, user) {
  if (!hasPermission(user, PERMISSIONS.GERER_PERMISSIONS) || user.id === e.id) return '';
  const seen = new Set();
  const items = baseNavItemsForRole(e).filter(item => {
    if (item.key === 'dashboard' || seen.has(item.key)) return false;
    seen.add(item.key);
    return true;
  });
  if (items.length === 0) return '';
  const desactives = new Set(e.menusDesactives || []);
  return `
    <div class="card">
      <h2>Menus autorisés</h2>
      <p class="text-muted">Décochez un menu pour le retirer de la navigation de ce salarié, sans effet sur les autres salariés.</p>
      <div class="form-grid checkbox-grid">
        ${items.map(item => `
          <div class="form-field form-field-checkbox">
            <label>
              <input type="checkbox" data-menu-autorise="${item.key}" ${desactives.has(item.key) ? '' : 'checked'}>
              ${icon(item.icon, 14)} ${escapeHtml(item.label)}
            </label>
          </div>
        `).join('')}
      </div>
    </div>
  `;
}

function bindMenusAutorisesCardEvents(employeeId) {
  document.querySelectorAll('[data-menu-autorise]').forEach(checkbox => {
    checkbox.addEventListener('change', (evt) => {
      const key = evt.target.dataset.menuAutorise;
      const employee = employeeRepository.getById(employeeId);
      const desactives = new Set(employee.menusDesactives || []);
      if (evt.target.checked) desactives.delete(key); else desactives.add(key);
      employeeRepository.update(employeeId, { menusDesactives: [...desactives] });
      const navItem = NAV_ITEMS.find(i => i.key === key);
      auditLogRepository.logAudit('Modification', 'Menus autorisés', `${employee.prenom} ${employee.nom} · ${navItem ? navItem.label : key} ${evt.target.checked ? 'autorisé' : 'retiré'}`);
      showToast('Mis à jour.');
    });
  });
}

/** Salaire : donnée sensible, réservée au Propriétaire, et seulement si l'entreprise a activé le
 * suivi correspondant. Sexe/civilité (§retour Betty du 18/09/2026, point 5) ne sont plus considérés
 * "confidentiels" ici (obligatoires/toujours visibles, affichés sur la carte Identité elle-même). */
function renderConfidentialEmployeeCard(e, user) {
  if (!hasPermission(user, PERMISSIONS.VOIR_INFOS_FINANCIERES)) return '';
  const settings = settingsRepository.getSettings();
  if (!settings.masseSalarialeActivee) return '';
  // §retour Betty du 14/09/2026 (Rémunération point 1, "historique des salaires") : les 5 derniers
  // changements, les plus récents en premier — alimenté automatiquement par updateEmployee, jamais
  // saisi à la main ici (voir DB.updateEmployee, data.js).
  const historique = (e.historiqueSalaire || []).slice().reverse().slice(0, 5);
  return `
    <div class="card">
      <h2>Confidentiel</h2>
      ${infoRow('Salaire brut mensuel', formatCurrencyFR(e.salaireBrutMensuel || 0))}
      ${e.salaireBrutMensuel ? infoRow('Coût employeur complet (estimé)', formatCurrencyFR(calculerCoutEmployeurComplet(e.salaireBrutMensuel, settings.tauxChargesPatronalesEstime))) : ''}
      ${historique.length ? `
        <div class="search-section-label" style="padding-left:0; margin-top:12px;">Historique des salaires</div>
        <div class="mini-list">
          ${historique.map(h => `
            <div class="mini-list-item">
              <span>${formatDate(h.date.slice(0, 10))} · ${formatCurrencyFR(h.ancienMontant)} → ${formatCurrencyFR(h.nouveauMontant)}${h.motif ? ` · ${escapeHtml(h.motif)}` : ''}</span>
            </div>
          `).join('')}
        </div>
      ` : ''}
    </div>
  `;
}

function renderEmployeeBalances(employee, canAdjust = false) {
  // Liste complète (pas seulement les types actifs/visibles ci-dessous) : getLeaveBalance en a besoin
  // pour retrouver les types "deduireRTT/CP" même désactivés depuis, sans re-fetch à chaque type.
  const allLeaveTypes = leaveTypeRepository.getLeaveTypes();
  const types = allLeaveTypes.filter(t => t.actif && t.visibleSalarie);
  if (types.length === 0) return `<p class="text-muted">Aucun type de congé actif.</p>`;

  const requests = leaveRepository.getAll();
  return `
    <div class="balance-grid">
      ${types.map(t => {
        const balance = getLeaveBalance(employee, t, requests, allLeaveTypes);
        const disponibleLabel = balance.disponible === Infinity ? 'Illimité' : formatDurationFR(balance.disponible);
        // §correctif retour QA du 27/08/2026 (point 1) : "disponible" et "en cours d'acquisition"
        // sont deux compteurs vivants distincts (voir getLeaveBalance) — jamais mélangés, chacun
        // avec sa période écrite en toutes lettres, pour qu'on sache toujours ce que le nombre affiché
        // représente.
        const periodeLabel = balance.periodeDisponible ? ` (${formatDate(balance.periodeDisponible.debut)} au ${formatDate(balance.periodeDisponible.fin)})` : '';
        return `
          <div class="balance-card" style="--type-color:${escapeHtml(t.couleur)}">
            ${canAdjust ? `<button type="button" class="btn-link balance-adjust-btn" data-adjust-compteur="${t.id}" title="Ajuster ce compteur">${icon(ICONS.pencil, 13)}</button>` : ''}
            <div class="balance-icon">${escapeHtml(t.icone)}</div>
            <div class="balance-name">${escapeHtml(t.nom)}</div>
            <div class="balance-value">${disponibleLabel}</div>
            <div class="balance-sub">disponible${periodeLabel}${balance.enAttente ? ` · ${formatDurationFR(balance.enAttente)} en attente` : ''}${balance.ajustement ? ` · ajustement ${balance.ajustement >= 0 ? '+' : ''}${formatDurationFR(balance.ajustement)}` : ''}</div>
            ${balance.enCoursAcquisition ? `<div class="balance-sub">${formatDurationFR(balance.enCoursAcquisition.acquis)} en cours d'acquisition (${formatDate(balance.enCoursAcquisition.periode.debut)} au ${formatDate(balance.enCoursAcquisition.periode.fin)}), disponible à partir du ${formatDate(toISODate(addDays(parseISODateLocal(balance.enCoursAcquisition.periode.fin), 1)))}</div>` : ''}
            ${balance.reportPerdu ? `<div class="balance-sub text-danger">${formatDurationFR(balance.reportPerdu)} de report perdu (échéance dépassée)</div>` : ''}
          </div>
        `;
      }).join('')}
    </div>
  `;
}

function openAjusterCompteurModal(employeeId, typeId) {
  const employee = employeeRepository.getById(employeeId);
  const type = leaveTypeRepository.getLeaveTypeById(typeId);
  if (!employee || !type) { showToast('Ce salarié ou ce type n\'est plus disponible.', 'error'); return; }
  const current = (employee.compteurs && employee.compteurs[typeId]) || 0;

  const html = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>Ajuster le compteur — ${escapeHtml(type.nom)}</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="adjust-compteur-form">
        <div class="modal-body">
          <p class="text-muted">${personNameHtml(employee)} — cet ajustement s'ajoute (ou se retranche, si négatif) au solde calculé automatiquement. Il remplace l'ajustement précédent pour ce type de congé.</p>
          <div class="form-field">
            <label for="f-montant">Ajustement (jours, + ou -) *</label>
            <input class="input" type="number" id="f-montant" name="montant" step="0.5" value="${current}" required>
          </div>
          <div class="form-field" style="margin-top: 12px;">
            <label for="f-motif">Motif</label>
            <input class="input" type="text" id="f-motif" name="motif" placeholder="Ex. reliquat repris de l'ancien SIRH">
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="submit" class="btn btn-primary">Enregistrer</button>
        </div>
      </form>
    </div>
  `;

  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');

  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('adjust-compteur-form').addEventListener('submit', (evt) => {
    evt.preventDefault();
    const montant = document.getElementById('f-montant').value;
    const motif = document.getElementById('f-motif').value;
    const result = employeeRepository.ajusterCompteur(employeeId, typeId, montant, motif);
    if (!result.success) { showToast(result.error, 'error'); return; }
    showToast('Compteur ajusté.');
    closeModal();
    render();
  });
}

function infoRow(label, value) {
  return `
    <div class="info-row">
      <span class="info-label">${escapeHtml(label)}</span>
      <span class="info-value">${escapeHtml(value || '—')}</span>
    </div>
  `;
}

function managerNames(managerIds) {
  const names = (managerIds || [])
    .map(id => employeeRepository.getById(id))
    .filter(Boolean)
    .map(m => `${m.prenom} ${m.nom}`);
  return names.length ? names.join(', ') : '—';
}

/** Auto-service limité (§ MODIFIER_PROPRES_COORDONNEES) : seulement téléphone/adresse, jamais le
 * reste de la fiche (poste, contrat, salaire...) qui reste réservé à MODIFIER_SALARIE/manager. */
function openCoordonneesModal(employeeId) {
  const employee = employeeRepository.getById(employeeId);
  if (!employee) { showToast('Ce salarié n\'est plus disponible.', 'error'); return; }

  const html = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>Modifier mes coordonnées</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="coordonnees-form">
        <div class="modal-body">
          <div class="form-grid">
            ${textField('telephone', 'Téléphone', employee.telephone)}
            ${addressAutocompleteField('adresse.rue', 'Adresse', employee.adresse.rue, 'adresse.codePostal', 'adresse.ville')}
            ${textField('adresse.codePostal', 'Code postal', employee.adresse.codePostal)}
            ${textField('adresse.ville', 'Ville', employee.adresse.ville)}
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="submit" class="btn btn-primary">Enregistrer</button>
        </div>
      </form>
    </div>
  `;

  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');

  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('coordonnees-form').addEventListener('submit', (evt) => {
    evt.preventDefault();
    const result = employeeRepository.majCoordonnees(employeeId, {
      telephone: document.getElementById('f-telephone').value,
      rue: document.getElementById('f-adresse.rue').value,
      codePostal: document.getElementById('f-adresse.codePostal').value,
      ville: document.getElementById('f-adresse.ville').value
    });
    if (!result.success) { showToast(result.error, 'error'); return; }
    showToast('Coordonnées mises à jour.');
    closeModal();
    render();
  });
}

// ---- Modale : Fiche salarié imprimable / export PDF ----

function openEmployeePrintModal(id) {
  const e = employeeRepository.getById(id);
  if (!e) { showToast('Ce salarié n\'est plus disponible.', 'error'); return; }
  const age = calculateAge(e.dateNaissance);
  const settings = settingsRepository.getSettings();
  const user = authRepository.getCurrentUser();
  const canSeeContractuel = user.id === e.id || hasPermission(user, PERMISSIONS.VOIR_INFOS_CONTRACTUELLES);

  const html = `
    <div class="modal modal-large">
      <div class="modal-header">
        <h2>Fiche salarié</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <div class="modal-body">
        <div class="print-area print-document">
          ${renderPrintDocumentHeader(companyRepository.getProfile(), `${e.prenom} ${e.nom}`, `Matricule ${e.matricule} · Fiche générée le ${formatDate(toISODate(new Date()))}`)}

          <h3>Identité</h3>
          ${infoRow('Email', e.email)}
          ${infoRow('Téléphone', e.telephone)}
          ${infoRow('Adresse', [e.adresse.rue, e.adresse.codePostal, e.adresse.ville].filter(Boolean).join(', '))}
          ${infoRow('Date de naissance', `${formatDate(e.dateNaissance)}${age !== null ? ' (' + age + ' ans)' : ''}`)}
          ${infoRow('Lieu de naissance', e.lieuNaissance)}
          ${infoRow('Nationalité', e.nationalite)}
          ${infoRow('N° sécurité sociale', e.numeroSecu)}

          <h3>Contrat &amp; poste</h3>
          ${infoRow('Service', e.service)}
          ${infoRow('Équipe', e.equipe)}
          ${infoRow('Poste', getPosteAccorde(e, settings))}
          ${infoRow('Manager(s)', managerNames(e.managerIds))}
          ${canSeeContractuel ? infoRow('Convention collective', e.conventionCollective) : ''}
          ${canSeeContractuel ? infoRow('Catégorie de salarié', e.statutPro) : ''}
          ${infoRow('Type de contrat', e.typeContrat)}
          ${infoRow('Date d\'embauche', formatDate(e.dateEmbauche))}
          ${infoRow('Ancienneté', calculateAnciennete(e.dateEmbauche))}

          <h3>Temps de travail</h3>
          ${infoRow('Temps de travail', e.tempsTravail)}
          ${infoRow('Pourcentage d\'activité', formatPercentFR(e.pourcentageActivite))}
          ${infoRow('Heures hebdomadaires', formatNumberFR(e.horairesHebdo) + ' h')}
          ${infoRow('Forfait', e.forfait)}
          ${infoRow('Jours travaillés', (e.joursTravailles || []).join(', '))}
        </div>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Fermer</button>
        <button type="button" class="btn btn-primary" id="btn-print-employee">Imprimer / Export PDF</button>
      </div>
    </div>
  `;

  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');

  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('btn-print-employee').addEventListener('click', () => {
    auditLogRepository.logAudit('Export', 'Fiche salarié', `${e.prenom} ${e.nom}`);
    window.print();
  });
}

/** §retour Betty du 18/09/2026 (point 7) : en-tête commun aux documents officiels imprimables
 * (attestation employeur, certificat de travail, attestation de salaire, registre du personnel),
 * repris sur le modèle du registre (déjà le mieux structuré des quatre) : logo + identité de
 * l'entreprise, une ligne "Fait à ..., le ..." séparée (lieu et date ensemble, jamais mélangés avec
 * autre chose), puis un TITRE DÉTACHÉ (jamais coincé dans le même bloc que l'en-tête). `subtitle` est
 * un texte libre optionnel affiché sous le titre (ex. "Document généré le ..."). */
function renderPrintDocumentHeader(profile, title, subtitle) {
  return `
    <div class="print-header">
      <div class="print-header-identity">
        ${profile.logo ? `<img src="${escapeHtml(profile.logo)}" alt="Logo" class="print-logo">` : ''}
        <div>
          <strong>${escapeHtml(profile.raisonSociale || 'Entreprise')}</strong>
          ${profile.siret ? `<div class="text-muted" style="font-size:12px;">SIRET ${escapeHtml(profile.siret)}</div>` : ''}
        </div>
      </div>
      <p class="print-lieu-date">Fait ${profile.adresse ? `à ${escapeHtml(profile.adresse)}, ` : ''}le ${formatDate(toISODate(new Date()))}</p>
    </div>
    <h1 class="print-title">${escapeHtml(title)}</h1>
    ${subtitle ? `<p class="text-muted" style="margin-top: -8px; margin-bottom: 20px;">${escapeHtml(subtitle)}</p>` : ''}
  `;
}

/** Générateurs de documents RH (attestation employeur, certificat de travail) — même mécanique
 * d'impression que openEmployeePrintModal ci-dessus (.print-area + window.print(), pas de .docx :
 * aucune dépendance externe fiable pour ça dans ce projet 100% vanilla JS, et le risque vécu — "un
 * .docx généré peut être accepté par la lib mais refusé par Word" — n'existe pas avec Imprimer/PDF
 * natif du navigateur). Toujours une AIDE À LA PRÉPARATION : texte type à relire avant remise, un
 * humain reste responsable du contenu final et de la signature. */
function openAttestationEmployeurModal(id) {
  const e = employeeRepository.getById(id);
  if (!e) { showToast('Ce salarié n\'est plus disponible.', 'error'); return; }
  const profile = companyRepository.getProfile();
  const settings = settingsRepository.getSettings();
  const today = toISODate(new Date());

  const html = `
    <div class="modal modal-large">
      <div class="modal-header">
        <h2>Attestation employeur</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <div class="modal-body">
        <p class="text-muted">Modèle type à relire avant remise : complétez/ajustez si besoin avant impression.</p>
        <div class="print-area print-document">
          ${renderPrintDocumentHeader(profile, 'Attestation employeur')}
          <p class="print-attestation-text">
            Je soussigné(e), représentant de la société ${escapeHtml(profile.raisonSociale || '____________________')}${profile.siret ? ' (SIRET ' + escapeHtml(profile.siret) + ')' : ''},
            atteste que ${getCiviliteAffichee(e) ? escapeHtml(getCiviliteAffichee(e)) + ' ' : ''}${personNameHtml(e)}, né(e) le ${formatDate(e.dateNaissance) || '____________________'},
            est employé(e) au sein de notre entreprise depuis le ${formatDate(e.dateEmbauche)}, en qualité de ${escapeHtml(getPosteAccorde(e, settings) || '____________________')},
            sous contrat ${escapeHtml(e.typeContrat)}${e.tempsTravail ? ', à ' + escapeHtml(e.tempsTravail).toLowerCase() : ''}.
          </p>
          <p class="print-attestation-text">Cette attestation est délivrée à la demande de l'intéressé(e) pour servir et valoir ce que de droit.</p>
          <div class="print-signature">
            <span>Cachet de l'entreprise</span>
            <span class="print-signature-line">Signature</span>
          </div>
        </div>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Fermer</button>
        <button type="button" class="btn btn-primary" id="btn-print-document">Imprimer / Export PDF</button>
      </div>
    </div>
  `;
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');
  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('btn-print-document').addEventListener('click', () => {
    auditLogRepository.logAudit('Export', 'Attestation employeur', `${e.prenom} ${e.nom}`);
    window.print();
  });
}

/** Registre unique du personnel (Code du travail, art. L1221-13) : obligatoire dès le 1er salarié,
 * amende jusqu'à 3 750 € si absent ou incomplet lors d'un contrôle. Toutes les entrées, y compris
 * les salariés archivés (partis), classées par ordre chronologique d'embauche — jamais filtrées
 * par équipe visible (c'est un document légal de l'entreprise entière, pas un rapport managérial).
 * "Sexe" (état civil, obligatoire depuis le 18/09/2026) via getSexe (data.js), qui retombe sur
 * l'ancien champ "genre" pour une fiche créée avant ce champ. */
function openRegistreUniquePersonnelModal() {
  if (getVisibleEmployeeIdsForCurrentUser() !== null) {
    showToast('Vous n\'avez pas le droit d\'accéder au registre du personnel.', 'error');
    return;
  }
  // §retour Betty du 17/09/2026 : même module que l'onglet Paramètres équivalent (voir le commentaire
  // du bouton qui ouvre cette modale, écran Salariés) — vérifié ici aussi, pas seulement à l'affichage
  // du bouton, au cas où cette fonction soit un jour appelée d'un autre endroit.
  if (!hasModule('rh')) {
    showToast('Le registre du personnel fait partie du module RH, non souscrit par votre entreprise.', 'error');
    return;
  }
  const profile = companyRepository.getProfile();
  const settings = settingsRepository.getSettings();
  const employees = employeeRepository.getAll().slice()
    .sort((a, b) => (a.dateEmbauche || '').localeCompare(b.dateEmbauche || ''));

  const html = `
    <div class="modal modal-large">
      <div class="modal-header">
        <h2>Registre unique du personnel</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <div class="modal-body">
        <p class="text-muted" style="margin-bottom: 14px;">Document obligatoire (Code du travail, art. L1221-13), à présenter sur demande de l'inspection du travail. Classé par ordre chronologique d'embauche, salariés partis compris.</p>
        <div class="print-area print-document">
          ${renderPrintDocumentHeader(profile, 'Registre unique du personnel')}
          <div style="overflow-x: auto;">
            <table class="table">
              <thead>
                <tr>
                  <th>Nom</th><th>Prénom</th><th>Sexe</th><th>Nationalité</th><th>Date de naissance</th>
                  <th>Poste</th><th>Type de contrat</th><th>Date d'entrée</th><th>Date de sortie</th>
                </tr>
              </thead>
              <tbody>
                ${employees.map(e => `
                  <tr>
                    <td>${escapeHtml(e.nom)}</td>
                    <td>${escapeHtml(e.prenom)}</td>
                    <td>${escapeHtml(getSexe(e) || '—')}</td>
                    <td>${escapeHtml(e.nationalite || '—')}</td>
                    <td>${formatDate(e.dateNaissance)}</td>
                    <td>${escapeHtml(getPosteAccorde(e, settings) || '—')}</td>
                    <td>${escapeHtml(e.typeContrat)}</td>
                    <td>${formatDate(e.dateEmbauche)}</td>
                    <!-- §correctif audit du 16/09/2026 : affichait dateFinContrat (n'a de sens que
                         pour un CDD/Intérim) au lieu de dateDepart (la vraie date de sortie, quel
                         que soit le type de contrat) — incohérent avec renderParametresRegistrePersonnel
                         (Paramètres > Référentiels), qui utilise déjà dateDepart pour cette même colonne. -->
                    <td>${e.dateDepart ? formatDate(e.dateDepart) : '—'}</td>
                  </tr>
                `).join('')}
              </tbody>
            </table>
          </div>
          <p class="text-muted" style="margin-top: 20px; font-size: 12px;">${employees.length} salarié${employees.length > 1 ? 's' : ''} au total (actifs et partis confondus) · Document tenu à disposition de l'inspection du travail conformément à l'article L1221-13 du Code du travail.</p>
        </div>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Fermer</button>
        <button type="button" class="btn btn-primary" id="btn-print-document">Imprimer / Export PDF</button>
      </div>
    </div>
  `;
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');
  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('btn-print-document').addEventListener('click', () => {
    auditLogRepository.logAudit('Export', 'Registre unique du personnel', profile.raisonSociale || 'Entreprise');
    window.print();
  });
}

/** L'obligation légale porte sur l'effectif de l'ANNÉE CONCERNÉE (celle qui doit être déclarée),
 * pas sur l'effectif d'aujourd'hui — une entreprise qui vient de franchir 50 salariés n'était pas
 * concernée l'année dernière, et une entreprise qui vient de descendre sous 50 peut encore devoir
 * une déclaration en retard pour une année où elle l'était. Utilise l'historique d'emploi réel
 * (dateEmbauche/dateDepart, comme isEmployedDuringPeriod) au 31 décembre de l'année donnée, plutôt
 * que e.statut === 'Actif' qui ne reflète que l'instant présent. */
function isConcerneParIndexEgalite(year) {
  const finAnnee = `${year}-12-31`;
  return employeeRepository.getAll().filter(e => !e.archive && isEmployedDuringPeriod(e, finAnnee, finAnnee)).length >= 50;
}

/** Index de l'égalité professionnelle femmes-hommes (Code du travail, art. L1142-8) : obligatoire
 * chaque année (publication au plus tard le 1er mars, portant sur l'année précédente) pour toute
 * entreprise d'au moins 50 salariés, amende jusqu'à 1% de la masse salariale en cas de manquement.
 * Volontairement PAS un calculateur : les 4-5 indicateurs officiels nécessitent des données de
 * rémunération par bande d'âge/catégorie que cette app ne modélise pas — calculez la note sur
 * index-egapro.travail.gouv.fr, ce module se contente de la tracer par année et de rappeler
 * l'échéance pour ne plus l'oublier. */
function openIndexEgaliteModal() {
  if (getVisibleEmployeeIdsForCurrentUser() !== null) {
    showToast('Vous n\'avez pas le droit d\'accéder à cet écran.', 'error');
    return;
  }
  const settings = settingsRepository.getSettings();
  const records = settings.indexEgaliteProfessionnelle || {};
  const currentYear = new Date().getFullYear();
  const anneesDeclarees = Object.keys(records).map(Number).sort((a, b) => b - a);
  const anneePrecedente = currentYear - 1;
  // C'est l'obligation de l'année précédente qui est en jeu ici (celle qui doit être déclarée au
  // 1er mars) — pas l'effectif d'aujourd'hui, voir isConcerneParIndexEgalite.
  const concerne = isConcerneParIndexEgalite(anneePrecedente);
  const effectifAnneePrecedente = employeeRepository.getAll().filter(e => !e.archive && isEmployedDuringPeriod(e, `${anneePrecedente}-12-31`, `${anneePrecedente}-12-31`)).length;
  const echeance = new Date(currentYear, 2, 1); // 1er mars
  const now = new Date();
  const anneePrecedenteDeclaree = Boolean(records[anneePrecedente]);
  const retard = now >= echeance;

  const html = `
    <div class="modal modal-large">
      <div class="modal-header">
        <h2>Index de l'égalité professionnelle</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <div class="modal-body">
        <p class="text-muted">Obligatoire pour toute entreprise d'au moins 50 salariés, publié chaque année au plus tard le 1er mars (porte sur l'année précédente). Le calcul des indicateurs se fait sur l'outil officiel <a href="https://index-egapro.travail.gouv.fr" target="_blank" rel="noopener">index-egapro.travail.gouv.fr</a> ; cet écran trace seulement la note obtenue, pour ne plus oublier l'échéance.</p>
        ${!concerne ? `<p class="text-muted" style="margin-top: 8px;">Non obligatoire pour ${anneePrecedente} : effectif sous 50 salariés au 31 décembre ${anneePrecedente} (${effectifAnneePrecedente}).</p>` : ''}
        ${concerne && !anneePrecedenteDeclaree ? `<p class="${retard ? 'text-danger' : 'text-muted'}" style="margin-top: 8px; font-weight: 600;">${retard ? icon(ICONS.warningTriangle, 14) + ' En retard : ' : ''}Index ${anneePrecedente} pas encore déclaré (échéance légale le 1er mars ${currentYear}${retard ? ', dépassée' : ''}).</p>` : ''}
        <div class="mini-list" style="margin-top: 12px;">
          ${anneesDeclarees.length === 0 ? `<p class="text-muted">Aucune année déclarée.</p>` : anneesDeclarees.map(year => {
            const r = records[year];
            return `
              <div class="mini-list-item" style="align-items: flex-start;">
                <span>
                  <strong>${year}</strong> — <span class="${r.note < 75 ? 'text-danger' : ''}">${r.note}/100</span>
                  ${r.datePublication ? ` · publié le ${formatDate(r.datePublication)}` : ''}
                  ${r.note < 75 && r.mesuresCorrectives ? `<br><span class="text-muted">Mesures correctives : ${escapeHtml(r.mesuresCorrectives)}</span>` : ''}
                </span>
                <button type="button" class="btn-link" data-edit-index-egalite="${year}">Modifier</button>
              </div>
            `;
          }).join('')}
        </div>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Fermer</button>
        <button type="button" class="btn btn-primary" id="btn-ajouter-index-egalite">Ajouter une année</button>
      </div>
    </div>
  `;
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');
  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('btn-ajouter-index-egalite').addEventListener('click', () => openAjouterIndexEgaliteModal(anneePrecedenteDeclaree ? currentYear : anneePrecedente));
  document.querySelectorAll('[data-edit-index-egalite]').forEach(btn => {
    btn.addEventListener('click', () => openAjouterIndexEgaliteModal(Number(btn.dataset.editIndexEgalite)));
  });
}

function openAjouterIndexEgaliteModal(defaultYear) {
  if (getVisibleEmployeeIdsForCurrentUser() !== null) {
    showToast('Vous n\'avez pas le droit d\'accéder à cet écran.', 'error');
    return;
  }
  const settings = settingsRepository.getSettings();
  const existing = (settings.indexEgaliteProfessionnelle || {})[defaultYear];

  const html = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>Index égalité pro — ${defaultYear}</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="index-egalite-form">
        <div class="modal-body">
          <div class="form-field">
            <label for="f-index-annee">Année</label>
            <input class="input" type="number" id="f-index-annee" value="${defaultYear}" ${existing ? 'readonly' : ''} required>
            ${existing ? `<p class="text-muted" style="margin-top: 4px;">L'année ne peut pas être changée ici : modifiez plutôt l'entrée de l'année correspondante.</p>` : ''}
          </div>
          <div class="form-field" style="margin-top: 12px;">
            <label for="f-index-note">Note obtenue (/100) *</label>
            <input class="input" type="number" min="0" max="100" id="f-index-note" value="${existing ? existing.note : ''}" required>
          </div>
          <div class="form-field" style="margin-top: 12px;">
            <label for="f-index-date">Date de publication</label>
            <input class="input" type="date" id="f-index-date" value="${existing ? existing.datePublication : ''}">
          </div>
          <div class="form-field" style="margin-top: 12px;">
            <label for="f-index-mesures">Mesures correctives (si note &lt; 75)</label>
            <textarea class="input" id="f-index-mesures" rows="3">${existing ? escapeHtml(existing.mesuresCorrectives) : ''}</textarea>
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="submit" class="btn btn-primary">Enregistrer</button>
        </div>
      </form>
    </div>
  `;
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');
  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('index-egalite-form').addEventListener('submit', (evt) => {
    evt.preventDefault();
    const year = document.getElementById('f-index-annee').value;
    const note = document.getElementById('f-index-note').value;
    const datePublication = document.getElementById('f-index-date').value;
    const mesuresCorrectives = document.getElementById('f-index-mesures').value.trim();
    const result = settingsRepository.enregistrerIndexEgalite(year, note, datePublication, mesuresCorrectives);
    if (!result.success) { showToast(result.error, 'error'); return; }
    showToast('Index égalité professionnelle enregistré.');
    closeModal();
    openIndexEgaliteModal();
  });
}

function openCertificatTravailModal(id) {
  const e = employeeRepository.getById(id);
  if (!e) { showToast('Ce salarié n\'est plus disponible.', 'error'); return; }
  const profile = companyRepository.getProfile();
  const settings = settingsRepository.getSettings();
  // §retour Betty du 18/09/2026 (point 7) : utilisait dateFinContrat (propre aux CDD/intérim, voir
  // employee.dateFinContrat) comme repli pour deviner une date de sortie — un CDI en cours n'a
  // jamais ce champ renseigné, mais rien n'empêchait alors de générer un certificat de travail pour
  // un salarié toujours en poste. dateDepart est LA vraie date de sortie, quel que soit le type de
  // contrat (voir aussi le bouton conditionnel sur la fiche salarié, qui ne propose ce document QUE
  // si dateDepart est renseignée — l'avertissement ci-dessous ne devrait donc plus jamais s'afficher
  // en pratique, gardé par sécurité si la modale était un jour ouverte par un autre chemin).
  const dateSortie = e.dateDepart;

  const html = `
    <div class="modal modal-large">
      <div class="modal-header">
        <h2>Certificat de travail</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <div class="modal-body">
        ${!dateSortie ? `<p class="field-warning visible">${icon(ICONS.warningTriangle, 13)} Aucune date de départ renseignée sur cette fiche : ce salarié semble toujours en poste. Le certificat de travail est réservé à une sortie effective (Code du travail, art. L1234-19) ; une attestation employeur convient tant qu'il est encore en poste.</p>` : ''}
        <p class="text-muted">Modèle type à relire avant remise : complétez/ajustez si besoin avant impression.</p>
        <div class="print-area print-document">
          ${renderPrintDocumentHeader(profile, 'Certificat de travail')}
          <p class="print-attestation-text">
            Je soussigné(e), représentant de la société ${escapeHtml(profile.raisonSociale || '____________________')}${profile.siret ? ' (SIRET ' + escapeHtml(profile.siret) + ')' : ''},
            certifie que ${getCiviliteAffichee(e) ? escapeHtml(getCiviliteAffichee(e)) + ' ' : ''}${personNameHtml(e)} a été employé(e) au sein de notre entreprise
            du ${formatDate(e.dateEmbauche)} au ${dateSortie ? formatDate(dateSortie) : '____________________'},
            en qualité de ${escapeHtml(getPosteAccorde(e, settings) || '____________________')}${e.service ? ' au sein du service ' + escapeHtml(e.service) : ''}.
          </p>
          <p class="print-attestation-text">Le salarié est libre de tout engagement à l'issue de cette période.</p>
          <div class="print-signature">
            <span>Cachet de l'entreprise</span>
            <span class="print-signature-line">Signature</span>
          </div>
        </div>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Fermer</button>
        <button type="button" class="btn btn-primary" id="btn-print-document">Imprimer / Export PDF</button>
      </div>
    </div>
  `;
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');
  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('btn-print-document').addEventListener('click', () => {
    auditLogRepository.logAudit('Export', 'Certificat de travail', `${e.prenom} ${e.nom}`);
    window.print();
  });
}

function bindEmployeeDetailEvents() {
  // §refonte "fil d'Ariane" du 01/09/2026 : la fiche trouvée/accessible n'a plus ce bouton — le
  // retour vers la liste se fait désormais via le premier maillon du fil d'Ariane (data-nav, géré
  // par la délégation globale). L'id ne subsiste que sur les 2 écrans d'erreur (introuvable/accès
  // refusé, voir renderEmployeeDetail), d'où le garde-fou plutôt qu'un accès direct.
  const backBtn = document.getElementById('btn-back-to-list');
  if (backBtn) backBtn.addEventListener('click', () => navigateTo('employees'));

  document.querySelectorAll('[data-employee-detail-tab]').forEach(btn => {
    btn.addEventListener('click', () => {
      state.employeeDetailTab = btn.dataset.employeeDetailTab;
      render();
    });
  });
  const prevBtn = document.getElementById('btn-employee-prev');
  if (prevBtn && prevBtn.dataset.employeeId) prevBtn.addEventListener('click', () => navigateTo('employee-detail', { currentEmployeeId: prevBtn.dataset.employeeId, employeeDetailTab: state.employeeDetailTab }));
  const nextBtn = document.getElementById('btn-employee-next');
  if (nextBtn && nextBtn.dataset.employeeId) nextBtn.addEventListener('click', () => navigateTo('employee-detail', { currentEmployeeId: nextBtn.dataset.employeeId, employeeDetailTab: state.employeeDetailTab }));

  const favoriteBtn = document.getElementById('btn-toggle-favorite');
  if (!favoriteBtn) return; // fiche introuvable ou accès non autorisé : seul le lien de retour existe sur cet état
  favoriteBtn.addEventListener('click', () => {
    favoriteRepository.toggleFavoriteEmployee(state.currentEmployeeId);
    render();
  });
  document.getElementById('btn-print-employee-fiche').addEventListener('click', () => openEmployeePrintModal(state.currentEmployeeId));
  const attestationBtn = document.getElementById('btn-print-attestation');
  if (attestationBtn) attestationBtn.addEventListener('click', () => openAttestationEmployeurModal(state.currentEmployeeId));
  const certificatBtn = document.getElementById('btn-print-certificat-travail');
  if (certificatBtn) certificatBtn.addEventListener('click', () => openCertificatTravailModal(state.currentEmployeeId));
  bindEmployeeDocumentsEvents(state.currentEmployeeId);
  bindGenererDocumentEvents(state.currentEmployeeId);
  bindPermissionsCardEvents(state.currentEmployeeId);
  bindMenusAutorisesCardEvents(state.currentEmployeeId);
  bindTypesAbsenceCardEvents(state.currentEmployeeId);
  bindChecklistEvents(state.currentEmployeeId);

  const forcerMdpBtn = document.getElementById('btn-forcer-mot-de-passe');
  if (forcerMdpBtn) forcerMdpBtn.addEventListener('click', () => openForcerMotDePasseModal(state.currentEmployeeId));

  const creerCompteBtn = document.getElementById('btn-creer-compte-connexion');
  if (creerCompteBtn) creerCompteBtn.addEventListener('click', () => openCreerCompteConnexionModal(state.currentEmployeeId));

  const changerRoleBtn = document.getElementById('btn-changer-role');
  if (changerRoleBtn) changerRoleBtn.addEventListener('click', () => openChangeRoleModal(state.currentEmployeeId));

  const editBtn = document.getElementById('btn-edit-employee');
  if (editBtn) editBtn.addEventListener('click', () => openEmployeeModal(state.currentEmployeeId));

  const ajouterVisiteMedicaleBtn = document.getElementById('btn-ajouter-visite-medicale');
  if (ajouterVisiteMedicaleBtn) ajouterVisiteMedicaleBtn.addEventListener('click', () => openVisiteMedicaleModal(state.currentEmployeeId));
  document.querySelectorAll('[data-edit-visite-medicale]').forEach(btn => {
    btn.addEventListener('click', () => openVisiteMedicaleModal(state.currentEmployeeId, btn.dataset.editVisiteMedicale));
  });
  document.querySelectorAll('[data-delete-visite-medicale]').forEach(btn => {
    btn.addEventListener('click', () => deleteVisiteMedicale(state.currentEmployeeId, btn.dataset.deleteVisiteMedicale));
  });

  const avenantBtn = document.getElementById('btn-ajouter-avenant');
  if (avenantBtn) avenantBtn.addEventListener('click', () => openAjouterAvenantModal(state.currentEmployeeId));

  const editCoordonneesBtn = document.getElementById('btn-edit-coordonnees');
  if (editCoordonneesBtn) editCoordonneesBtn.addEventListener('click', () => openCoordonneesModal(state.currentEmployeeId));

  // §retour Betty du 17/09/2026 (audit "millimètre par millimètre") : ces deux boutons n'existent plus
  // dans le DOM quand le module correspondant (congés/planning) n'est pas souscrit (voir la carte
  // "Compteurs de congés" ci-dessus, renderEmployeeDetail) — un .addEventListener sans garde plantait
  // toute la suite de cette fonction de liaison dès qu'un de ces boutons manquait.
  const requestLeaveBtn = document.getElementById('btn-request-leave');
  if (requestLeaveBtn) requestLeaveBtn.addEventListener('click', () => openLeaveRequestModal(state.currentEmployeeId, 'conge'));
  const requestTeleworkBtn = document.getElementById('btn-request-telework');
  if (requestTeleworkBtn) requestTeleworkBtn.addEventListener('click', () => openTeleworkRequestModal(state.currentEmployeeId));

  document.querySelectorAll('[data-adjust-compteur]').forEach(btn => {
    btn.addEventListener('click', () => openAjusterCompteurModal(state.currentEmployeeId, btn.dataset.adjustCompteur));
  });

  const archiveBtn = document.getElementById('btn-archive-employee');
  if (archiveBtn) archiveBtn.addEventListener('click', () => {
    const e = employeeRepository.getById(state.currentEmployeeId);
    if (!e) { showToast('Ce salarié n\'est plus disponible.', 'error'); return; }
    const willArchive = !e.archive;
    openConfirm({
      title: willArchive ? 'Archiver ce salarié ?' : 'Réactiver ce salarié ?',
      message: willArchive
        ? `${e.prenom} ${e.nom} sera marqué comme inactif et archivé. Ses données restent conservées.`
        : `${e.prenom} ${e.nom} sera réactivé et repassera au statut actif.`,
      confirmLabel: willArchive ? 'Archiver' : 'Réactiver',
      onConfirm: () => {
        employeeRepository.archive(e.id, willArchive);
        if (willArchive) releaseModuleLicensesForDeparture(e);
        showToast(willArchive ? 'Salarié archivé.' : 'Salarié réactivé.');
        render();
      }
    });
  });

  const deleteBtn = document.getElementById('btn-delete-employee');
  if (deleteBtn) deleteBtn.addEventListener('click', () => {
    const e = employeeRepository.getById(state.currentEmployeeId);
    if (!e) { showToast('Ce salarié n\'est plus disponible.', 'error'); return; }
    openConfirmerSuppressionSalarieModal(e, () => {
      employeeRepository.delete(e.id);
      showToast('Salarié supprimé.');
      navigateTo('employees');
    });
  });
}

// ---------------------------------------------------------------------------
// Vue : Congés (demandes + types paramétrables)
// ---------------------------------------------------------------------------

/** §sprint refonte UX §7+8 : fusion Congés/Absences/Télétravail (nav "absences") — un seul écran à
 * 3 onglets de premier niveau, chacun réutilisant tel quel son moteur existant (renderCongesDemandes/
 * renderTeletravail*). L'onglet "Types" disparaît ici : la gestion des types reste UNIQUEMENT dans
 * Paramètres > Types d'absences (renderParametresTypesAbsences, déjà en place) — une seule source de
 * vérité, comme demandé (§8). Télétravail garde son propre sous-onglet Demandes/Planning en 2ᵉ niveau
 * (pas un doublon : le Planning hebdomadaire n'existe pas pour Congés/Absences). */
function renderAbsencesHub() {
  const user = authRepository.getCurrentUser();
  // §tour de bugs du 07/09/2026 : même défaut que celui corrigé sur Notes de frais (point 8) —
  // liste de rôles codée en dur, une permission validerAbsence/refuserAbsence/annulerAbsence
  // accordée individuellement à un salarié/comptabilité n'affichait jamais ce bouton. 'manager' reste
  // un test de RÔLE (pas hasPermission) : un manager valide via son étape de workflow nommée par
  // salarié (isCurrentWorkflowStepFor), jamais via une permission globale — voir canActOnRequestFor
  // et son commentaire sur DEFAULT_ROLE_PERMISSIONS ("VALIDER_ABSENCE n'est pas accordée au manager
  // par défaut"). Ce bouton reste un raccourci général (pas lié à UNE demande précise), donc "tout
  // manager" reste la meilleure approximation possible ici, comme avant ce correctif.
  const canValider = user.role === ROLES.MANAGER
    || hasPermission(user, PERMISSIONS.VALIDER_ABSENCE)
    || hasPermission(user, PERMISSIONS.REFUSER_ABSENCE)
    || hasPermission(user, PERMISSIONS.ANNULER_ABSENCE);
  const TABS = {
    conges: { label: 'Congés', subtitle: 'Demandes de congés payés, RTT, ancienneté...', btnId: 'btn-conges-a-valider' },
    autres: { label: 'Absences', subtitle: 'Maladie, événements familiaux et autres absences paramétrables', btnId: 'btn-autres-absences-a-valider' },
    // Le télétravail dépend du module "planning" (voir LANDING_ALACARTE_MODULES) même si l'onglet
    // vit dans cet écran fusionné "conges" — retiré ici plutôt que dans NAV_ITEMS, qui ne connaît
    // que l'écran entier, pas ses onglets internes.
    ...(hasModule('planning') ? { teletravail: { label: 'Télétravail', subtitle: 'Demandes, validations et planning hebdomadaire', btnId: 'btn-teletravail-a-valider' } } : {})
  };
  const tab = TABS[state.absencesHubTab] ? state.absencesHubTab : 'conges';

  return `
    <div class="view-header view-header-row">
      <div>
        <h1>Congés & absences</h1>
        <p class="view-subtitle">${TABS[tab].subtitle}</p>
      </div>
      ${canValider ? `<div class="detail-header-actions"><button type="button" class="btn btn-secondary btn-sm" id="${TABS[tab].btnId}">Voir les demandes à valider</button></div>` : ''}
    </div>
    <div class="tabs">
      ${Object.keys(TABS).map(key => `<button class="tab ${tab === key ? 'active' : ''}" data-absences-hub-tab="${key}">${TABS[key].label}</button>`).join('')}
    </div>
    <div id="absences-hub-tab-content">
      ${tab === 'conges' ? renderCongesDemandes('conge') : tab === 'autres' ? renderCongesDemandes('autre') : renderAbsencesHubTeletravail()}
    </div>
  `;
}

function renderAbsencesHubTeletravail() {
  return `
    <div class="tabs tabs-sub" style="margin-bottom: 14px;">
      <button class="tab ${state.teletravailTab === 'demandes' ? 'active' : ''}" data-teletravail-tab="demandes">Demandes</button>
      <button class="tab ${state.teletravailTab === 'planning' ? 'active' : ''}" data-teletravail-tab="planning">Planning</button>
    </div>
    ${state.teletravailTab === 'planning' ? renderTeletravailPlanning() : renderTeletravailDemandes()}
  `;
}

function bindAbsencesHubEvents() {
  // §tour de bugs du 07/09/2026 : bug préexistant repéré en testant le télétravail — ce calcul ne
  // reproduisait pas le repli sur 'conges' de renderAbsencesHub quand l'onglet demandé n'existe pas
  // (télétravail sans module planning souscrit). Le contenu réellement affiché tombait alors sur
  // Congés, mais ce binder tentait quand même de brancher les événements du télétravail sur des
  // éléments DOM qui n'existaient pas — plantage total de l'écran (filet de sécurité render()).
  const tab = (state.absencesHubTab === 'teletravail' && !hasModule('planning')) ? 'conges' : (state.absencesHubTab || 'conges');

  document.querySelectorAll('[data-absences-hub-tab]').forEach(btn => {
    btn.addEventListener('click', () => {
      state.absencesHubTab = btn.dataset.absencesHubTab;
      render();
    });
  });

  const btnAValider = document.getElementById('btn-conges-a-valider') || document.getElementById('btn-autres-absences-a-valider') || document.getElementById('btn-teletravail-a-valider');
  if (btnAValider) {
    btnAValider.addEventListener('click', () => {
      // navigateTo (pas Object.assign + render() seul) : depuis l'ajout de "Congés à valider" côté
      // Équipe (retour du 21/08/2026), l'état de surbrillance de la barre latérale dépend de
      // congesFilters — sans renderSidebar(), ce bouton laissait "Congés & absences" surligné au
      // lieu de "Congés à valider" après avoir pourtant bien appliqué le même filtre.
      navigateTo('absences', tab === 'teletravail' ? NAVPARAMS_TELETRAVAIL_A_VALIDER : NAVPARAMS_CONGES_A_VALIDER);
    });
  }

  if (tab === 'conges') bindCongesDemandesEvents('conge');
  else if (tab === 'autres') bindCongesDemandesEvents('autre');
  else {
    document.querySelectorAll('[data-teletravail-tab]').forEach(btn => {
      btn.addEventListener('click', () => { state.teletravailTab = btn.dataset.teletravailTab; render(); });
    });
    if (state.teletravailTab === 'planning') bindTeletravailPlanningEvents();
    else bindTeletravailDemandesEvents();
  }
}

// ---- Sous-vue : Demandes ----

// §correctif audit du 31/08/2026 (reuse) : getFilteredLeaveRequests/getFilteredTeleworkRequests/
// getFilteredExpenses réimplémentaient chacune le même pipeline (portée de visibilité, puis filtres
// depuis state.*Filters) — un futur correctif sur getVisibleEmployeeIdsForCurrentUser (règle
// sensible, déjà corrigée plusieurs fois dans ce fichier) n'a désormais qu'un seul endroit à
// toucher au lieu de 3. Comportement strictement inchangé : même ordre (portée, puis chaque filtre).
function scopeToVisibleEmployees(list) {
  const visibleIds = getVisibleEmployeeIdsForCurrentUser();
  return visibleIds === null ? list : list.filter(item => visibleIds.includes(item.employeeId));
}

function applyStateFilters(list, filters, fieldMap) {
  return fieldMap.reduce((result, [filterKey, itemKey]) =>
    filters[filterKey] ? result.filter(item => item[itemKey] === filters[filterKey]) : result, list);
}

function getFilteredLeaveRequests(categorie = 'conge') {
  const filters = categorie === 'conge' ? state.congesFilters : state.autresAbsencesFilters;
  const list = leaveRepository.getAll().filter(r => {
    const type = leaveTypeRepository.getLeaveTypeById(r.typeId);
    return type && type.categorie === categorie;
  });
  const filtered = applyStateFilters(scopeToVisibleEmployees(list), filters, [['employeeId', 'employeeId'], ['typeId', 'typeId'], ['statut', 'statut']]);
  // §retour Betty du 19/09/2026 (blocage 5.3, puis socle commun point 6) : matchesPeriodeFilter
  // gère elle-même le CHEVAUCHEMENT d'une plage [dateDebut, dateFin] — une demande est une plage,
  // contrairement à une note de frais (une seule date, voir getFilteredExpenses) : une demande du
  // 28/08 au 03/09 doit apparaître si on filtre sur septembre, même commencée en août.
  return filtered.filter(r => matchesPeriodeFilter([r.dateDebut, r.dateFin], filters.periode));
}

// §correctif audit du 23/08/2026 (§7.14) : sélection de validation en masse, séparée par catégorie
// (congés / autres absences partagent la même fonction de rendu mais jamais la même sélection —
// cocher une ligne "congé" ne doit rien présélectionner en revenant sur l'onglet "autres absences").
const bulkSelection = { conge: new Set(), autre: new Set(), frais: new Set() };

function renderCongesDemandes(categorie = 'conge') {
  const filters = categorie === 'conge' ? state.congesFilters : state.autresAbsencesFilters;
  const pageKey = categorie === 'conge' ? 'congesPage' : 'autresAbsencesPage';
  const employees = getScopedEmployeesForFilters();
  const types = leaveTypeRepository.getLeaveTypes().filter(t => t.categorie === categorie);
  const requests = getFilteredLeaveRequests(categorie);
  const { pageItems, totalPages, page, pageStart } = paginate(requests, pageKey);
  const selection = bulkSelection[categorie];
  // Seules les demandes EN ATTENTE que l'utilisateur courant peut effectivement valider comptent
  // pour la case "tout sélectionner" — cocher des lignes qu'aucun bouton "Valider" n'accompagne
  // déjà (statut différent, ou hors de portée de canActOnRequestFor) n'aurait aucun effet au clic.
  const selectablePageItems = pageItems.filter(r => r.statut === 'En attente' && canActOnRequestFor(r));
  const selectedCount = selection.size;
  // §amélioration du 09/09/2026 (empty states plus utiles, inspiré des pratiques d'onboarding SaaS) :
  // "aucune demande ne correspond à ces filtres" induisait en erreur quand il n'y avait tout
  // simplement AUCUNE demande créée pour l'instant (pas un souci de filtre à ajuster) — un cas
  // fréquent pour une entreprise qui démarre sur ce module.
  const emptyStateMessage = Object.values(filters).some(Boolean)
    ? 'Aucune demande ne correspond à ces filtres.'
    : `Aucune demande ${categorie === 'conge' ? 'de congé' : 'd\'absence'} pour l'instant. Utilisez le bouton "+ Nouvelle demande" ci-dessus pour créer la première.`;

  return `
    <div class="view-header-row">
      <p class="view-subtitle">${requests.length} demande${requests.length > 1 ? 's' : ''}</p>
      <div class="detail-header-actions">
        <button class="btn btn-secondary" id="btn-export-conges">Exporter CSV</button>
        <!-- §retour Betty du 18/09/2026 (point 5) : "Importer l'historique" déplacé vers Paramètres
             > Types d'absences (voir renderCongesTypes) — une opération de mise en service, pas un
             usage quotidien, qui n'a plus sa place ici (risque de double import à portée de clic). -->
        <!-- §refonte "hiérarchie de boutons" du 01/09/2026 : jamais 2 boutons pleins en même temps sur
             cet écran — "Valider la sélection" (ci-dessous) prend le relais dès qu'une sélection est
             active, plus urgent à ce moment que créer une nouvelle demande. -->
        <button class="btn ${selectedCount > 0 ? 'btn-secondary' : 'btn-primary'}" id="btn-new-leave-request">+ Nouvelle demande</button>
      </div>
    </div>

    ${renderDraftsCard(categorie === 'conge' ? 'conge' : 'autre-absence')}

    ${renderFilterToggleBar('conges-filters', [filters.employeeId, filters.typeId, filters.statut, filters.periode].filter(Boolean).length, categorie === 'conge' ? 'conges' : 'autres-absences')}
    <div class="toolbar card toolbar-collapsible" id="conges-filters">
      <select id="conges-filter-employee" class="input">
        <option value="">Tous les salariés</option>
        ${employees.map(e => `<option value="${e.id}" ${filters.employeeId === e.id ? 'selected' : ''}>${personNameHtml(e)}</option>`).join('')}
      </select>
      <select id="conges-filter-type" class="input">
        <option value="">Tous les types</option>
        ${types.map(t => `<option value="${t.id}" ${filters.typeId === t.id ? 'selected' : ''}>${escapeHtml(t.nom)}</option>`).join('')}
      </select>
      <select id="conges-filter-statut" class="input">
        <option value="">Tous les statuts</option>
        ${['En attente', 'Validé', 'Refusé', 'Annulé'].map(s => `<option value="${s}" ${filters.statut === s ? 'selected' : ''}>${s}</option>`).join('')}
      </select>
      <!-- §retour Betty du 19/09/2026 (blocage 5.3, "aucun filtre par période dans les congés... deux
           écrans jumeaux, deux comportements différents") : même champ que Notes de frais
           (frais-filter-periode), pour que les deux écrans se comportent enfin pareil. -->
      <input class="input" type="month" id="conges-filter-periode" value="${escapeHtml(filters.periode)}" title="Filtrer par mois (demandes qui chevauchent ce mois)">
    </div>

    ${selectedCount > 0 ? `
      <div class="toolbar card" style="align-items:center;">
        <span>${selectedCount} demande${selectedCount > 1 ? 's' : ''} sélectionnée${selectedCount > 1 ? 's' : ''}</span>
        <button type="button" class="btn btn-primary btn-sm" id="btn-bulk-approve">Valider la sélection</button>
        <button type="button" class="btn btn-secondary btn-sm" id="btn-bulk-clear">Annuler la sélection</button>
      </div>
    ` : ''}

    <div class="card table-card">
      ${requests.length === 0 ? `<div class="empty-state"><div class="empty-icon">${ICONS.sun}</div><p>${escapeHtml(emptyStateMessage)}</p></div>` : `
        <table class="table mobile-cards">
          <thead>
            <tr>
              <th>${selectablePageItems.length ? `<input type="checkbox" id="conges-select-all" ${selectablePageItems.every(r => selection.has(r.id)) ? 'checked' : ''} aria-label="Tout sélectionner">` : ''}</th>
              <th>Salarié</th>
              <th>Type</th>
              <th>Période</th>
              <th>Jours</th>
              <th>Statut</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            ${pageItems.map(r => renderLeaveRequestRow(r, selection)).join('')}
          </tbody>
        </table>
        ${renderPaginationControls(page, totalPages, pageStart, pageItems.length, requests.length)}
      `}
    </div>
  `;
}

function renderLeaveRequestRow(r, selection) {
  const employee = employeeRepository.getById(r.employeeId);
  const type = leaveTypeRepository.getLeaveTypeById(r.typeId);
  if (!employee || !type) return '';

  const periode = r.dateDebut === r.dateFin
    ? formatDate(r.dateDebut) + (r.demiJournee ? ` (${r.demiJournee === 'matin' ? 'matin' : 'après-midi'})` : '')
    // §7.12 : précise la demi-journée de début/fin quand elle s'applique, plutôt que de laisser
    // deviner à partir du seul nombre de jours (souvent non entier, ex. 4,5).
    : `${formatDate(r.dateDebut)}${r.demiJourneeDebut === 'apres-midi' ? ' après-midi' : ''} → ${formatDate(r.dateFin)}${r.demiJourneeFin === 'matin' ? ' matin' : ''}`;
  const selectable = selection && r.statut === 'En attente' && canActOnRequestFor(r);

  return `
    <tr data-request-id="${r.id}">
      <td class="table-select-cell">${selectable ? `<input type="checkbox" class="conges-select-row" data-select-request="${r.id}" ${selection.has(r.id) ? 'checked' : ''} aria-label="Sélectionner cette demande">` : ''}</td>
      <td class="row-title" data-label="Salarié">${personNameHtml(employee)}</td>
      <td data-label="Type"><span class="badge badge-muted"><span class="type-swatch" style="background:${escapeHtml(type.couleur)}"></span>${escapeHtml(type.icone)} ${escapeHtml(type.nom)}</span></td>
      <td data-label="Période">${periode}</td>
      <td data-label="Jours">${formatDurationFR(r.nbJours)}</td>
      <td data-label="Statut">${renderRequestStatutBadge(r)}</td>
      <td class="table-actions">${renderRequestActions(r, type)}</td>
    </tr>
  `;
}

/** Badge de statut générique, réutilisé par Congés, Télétravail et Notes de frais (même moteur de workflow).
 * §correctif audit du 23/08/2026 (§7.7) : le motif de refus (désormais obligatoire à la saisie,
 * voir openRefuseModal) s'affiche directement sous le badge plutôt que de forcer à rouvrir
 * l'historique — c'est l'information que le salarié cherche en premier sur un refus. */
function renderRequestStatutBadge(r) {
  const map = { 'En attente': 'warning', 'Validé': 'success', 'Remboursé': 'success', 'Refusé': 'muted', 'Annulé': 'muted' };
  const currentRole = r.statut === 'En attente' && r.workflow && r.workflow[r.etapeIndex];
  const suffix = currentRole ? ` (${ROLE_LABELS[currentRole] || currentRole})` : '';
  const motif = r.statut === 'Refusé' && r.motifRefus
    ? `<div class="text-muted" style="font-size: 12px; margin-top: 4px;">${escapeHtml(r.motifRefus)}</div>` : '';
  return `<span class="badge badge-${map[r.statut] || 'muted'}">${escapeHtml(r.statut)}${suffix}</span>${motif}`;
}

/**
 * Un salarié ne peut jamais valider de demande. Un manager ne peut agir que sur
 * les demandes de membres de son équipe. RH et Propriétaire peuvent toujours agir.
 * `allowComptabilite` ouvre l'action à la Comptabilité (utilisé pour les notes de frais).
 */
/**
 * Un utilisateur ne peut valider une demande que si c'est actuellement le tour de son rôle
 * dans la chaîne de validation de la demande (`request.workflow[request.etapeIndex]`).
 * RH et Propriétaire peuvent toujours agir (accès complet) ; un manager uniquement sur son équipe.
 *
 * domain: 'absence' (congés/télétravail, défaut) consulte hasPermission(VALIDER_ABSENCE) ;
 * 'frais' (notes de frais) consulte hasPermission(VALIDER_NOTE_FRAIS) — dans les deux cas
 * surchargeable individuellement (§8). Le bypass ne concerne que RH/Propriétaire par défaut :
 * Comptabilité n'a pas VALIDER_NOTE_FRAIS et continue de ne passer qu'à son étage du workflow
 * (`requiredRole === 'comptabilite'`), exactement comme avant.
 *
 * Pour 'frais' spécifiquement, une fois l'étape de workflow confirmée (rôle + équipe le cas échéant),
 * une seconde permission plus fine s'applique SANS élargir l'accès à d'autres étapes : CONTROLER_NOTE_FRAIS
 * pour toute étape non finale (vérification), MARQUER_NOTE_REMBOURSEE pour la dernière étape (paiement).
 * Contrairement à VALIDER_NOTE_FRAIS ci-dessus, ces deux permissions ne sont PAS vérifiées avant le
 * rôle/l'équipe : elles ne font que restreindre davantage un accès déjà accordé par l'étape du workflow,
 * jamais l'élargir à une autre étape — sinon on recrée le même bypass company-wide déjà corrigé pour
 * VALIDER_ABSENCE/VALIDER_NOTE_FRAIS chez le manager.
 */
/** Étape de workflow en cours (rôle courant + équipe le cas échéant + granularité frais), SANS bypass —
 * factorisé entre canActOnRequestFor (Valider) et canRefuserRequestFor (Refuser) ci-dessous, qui ne
 * diffèrent que par la permission de bypass consultée avant d'en arriver là. */
function isCurrentWorkflowStepFor(request, user, domain) {
  const requiredRole = request.workflow[request.etapeIndex];
  // §retour QA du 26/08/2026 (point 6.7) : un valideur nommé REMPLACE la vérification de rôle pour
  // cette étape précise (undefined pour télétravail/frais, jamais concernés par ce point — voir
  // makeEmptyLeaveRequest) — l'appartenance à la liste nommée prime, quel que soit le rôle réel de
  // l'utilisateur, c'est exactement le but : pouvoir désigner quelqu'un hors du schéma de rôles.
  const overrideIds = (request.workflowValidatorOverrides || {})[String(request.etapeIndex)];
  if (Array.isArray(overrideIds) && overrideIds.length > 0) return overrideIds.includes(user.id);
  if (user.role !== requiredRole) return false;
  if (domain === 'frais') {
    const derniereEtape = request.etapeIndex === request.workflow.length - 1;
    if (!hasPermission(user, derniereEtape ? PERMISSIONS.MARQUER_NOTE_REMBOURSEE : PERMISSIONS.CONTROLER_NOTE_FRAIS)) return false;
  }
  if (requiredRole === ROLES.MANAGER) {
    return isManagerOfEmployee(user.id, request.employeeId);
  }
  return true;
}

/** Le Propriétaire n'a personne au-dessus de lui dans la hiérarchie pour valider ses propres congés —
 * seul cas où la séparation des tâches est levée, et seulement pour les congés/absences/télétravail
 * (domain 'absence'), jamais pour les notes de frais : le circuit financier reste séparé même pour lui. */
function canSelfServiceAsProprietaire(user, domain) {
  return domain === 'absence' && user.role === ROLES.PROPRIETAIRE;
}

function canActOnRequestFor(request, domain = 'absence') {
  const user = authRepository.getCurrentUser();
  if (!user || !request.workflow || request.etapeIndex < 0 || request.etapeIndex >= request.workflow.length) return false;
  // séparation des tâches : personne ne valide sa propre demande, même RH — sauf le Propriétaire (§ci-dessus).
  if (request.employeeId === user.id && !canSelfServiceAsProprietaire(user, domain)) return false;
  if (hasPermission(user, domain === 'frais' ? PERMISSIONS.VALIDER_NOTE_FRAIS : PERMISSIONS.VALIDER_ABSENCE)) return true;
  return isCurrentWorkflowStepFor(request, user, domain);
}

/** Refuser une demande (§8) : REFUSER_ABSENCE est une permission distincte de VALIDER_ABSENCE pour
 * congés/télétravail — un Propriétaire peut ainsi accorder (ou retirer) le droit de refuser
 * indépendamment de celui de valider. Pas de permission "refuser une note de frais" distincte au
 * catalogue : même règle que Valider pour le domaine 'frais'. */
function canRefuserRequestFor(request, domain = 'absence') {
  const user = authRepository.getCurrentUser();
  if (!user || !request.workflow || request.etapeIndex < 0 || request.etapeIndex >= request.workflow.length) return false;
  if (request.employeeId === user.id && !canSelfServiceAsProprietaire(user, domain)) return false;
  if (hasPermission(user, domain === 'frais' ? PERMISSIONS.VALIDER_NOTE_FRAIS : PERMISSIONS.REFUSER_ABSENCE)) return true;
  return isCurrentWorkflowStepFor(request, user, domain);
}

/** Pour les actions post-validation (ex. Annuler) qui ne dépendent plus de l'étape de workflow.
 * Même logique de domain que canActOnRequestFor ci-dessus. */
function canManageRequestFor(employeeId, domain = 'absence') {
  const user = authRepository.getCurrentUser();
  if (!user) return false;
  // séparation des tâches : personne ne gère sa propre demande, même RH — sauf le Propriétaire (congés/absences).
  if (employeeId === user.id && !canSelfServiceAsProprietaire(user, domain)) return false;
  if (hasPermission(user, domain === 'frais' ? PERMISSIONS.VALIDER_NOTE_FRAIS : PERMISSIONS.ANNULER_ABSENCE)) return true;
  if (user.role === ROLES.MANAGER) {
    return isManagerOfEmployee(user.id, employeeId);
  }
  return false;
}

/** §tour de bugs du 07/09/2026 : même correctif que canSelfManagePendingExpense (Notes de frais,
 * point 5 du retour Betty) — un demandeur peut annuler SA PROPRE demande (congé ou télétravail,
 * même forme de requête) tant qu'AUCUNE étape de validation n'a encore été franchie (etapeIndex
 * === 0), jamais après. Générique aux deux domaines car ils partagent exactement la même forme
 * (employeeId/statut/etapeIndex) — contrairement aux notes de frais, la correction de contenu
 * (dates/type) n'est pas ajoutée ici pour les congés (formulaire nettement plus complexe : type,
 * demi-journée simple/multi, justificatif) — seule l'ANNULATION est couverte pour l'instant. */
function canSelfCancelPendingRequest(request, user) {
  return Boolean(user) && request.employeeId === user.id && request.statut === 'En attente' && request.etapeIndex === 0;
}

function renderRequestActions(r, type) {
  const user = authRepository.getCurrentUser();
  const historyBtn = `<button class="btn-link" data-history="${r.id}">Historique</button>`;
  if (r.statut === 'En attente') {
    return `
      ${historyBtn}
      ${canSelfCancelPendingRequest(r, user) ? `<button class="btn-link btn-link-danger" data-self-cancel="${r.id}">Annuler</button>` : ''}
      ${canActOnRequestFor(r) ? `<button class="btn-link" data-approve="${r.id}">Valider</button>` : ''}
      ${canRefuserRequestFor(r) ? `<button class="btn-link btn-link-danger" data-refuse="${r.id}">Refuser</button>` : ''}
    `;
  }
  if (r.statut === 'Validé') {
    // §24 : "Prolonger l'arrêt" — réservé aux types "saisie réservée RH" (maladie et assimilés,
    // voir SS15) et à qui a la permission PROLONGER_MALADIE.
    const canProlonger = !type.saisiParSalarie && hasPermission(authRepository.getCurrentUser(), PERMISSIONS.PROLONGER_MALADIE);
    return `
      ${historyBtn}
      <button class="btn-link" data-attestation="${r.id}">Attestation</button>
      ${r.arretTravail && canProlonger ? `<button class="btn-link" data-attestation-salaire="${r.id}">Attestation de salaire</button>` : ''}
      ${canProlonger ? `<button class="btn-link" data-prolonger="${r.id}">Prolonger</button>` : ''}
      ${canManageRequestFor(r.employeeId) ? `<button class="btn-link" data-regulariser="${r.id}">Régulariser</button>` : ''}
      ${canManageRequestFor(r.employeeId) ? `<button class="btn-link btn-link-danger" data-cancel="${r.id}">Annuler</button>` : ''}
    `;
  }
  return historyBtn;
}

/** Sprint SIRH premium §11 : Historique — fusionne `historique` (création/étapes de validation du
 * workflow/refus/annulation, déjà alimenté à chaque action) et `regularisations` (rectifications
 * après validation, § régularisation) en une seule timeline chronologique, lecture seule. Le
 * télétravail et les notes de frais n'ont pas de mécanisme de régularisation — `regularisations` y
 * est simplement absent/vide, la fusion le gère nativement sans code spécifique par type. */
function buildRequestTimeline(request) {
  const entries = [
    ...(request.historique || []).map(h => ({ date: h.date, label: h.action })),
    ...(request.regularisations || []).map(r => ({
      date: r.date,
      label: `Rectifiée : ${r.ancienType} du ${formatDate(r.ancienneDateDebut)}${r.ancienneDateDebut !== r.ancienneDateFin ? ' au ' + formatDate(r.ancienneDateFin) : ''}${r.motif ? ' : ' + r.motif : ''}`
    }))
  ];
  return entries.sort((a, b) => new Date(a.date) - new Date(b.date));
}

function openRequestHistoryModal(request) {
  if (!request) { showToast('Cette demande n\'est plus disponible.', 'error'); return; }
  const timeline = buildRequestTimeline(request);
  const html = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>Historique de la demande</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <div class="modal-body">
        ${timeline.length === 0 ? '<p class="text-muted">Aucun historique disponible.</p>' : `
          <div class="timeline">
            ${timeline.map(e => `
              <div class="timeline-item">
                <div class="timeline-date text-muted">${formatDateTime(e.date)}</div>
                <div class="timeline-label">${escapeHtml(e.label)}</div>
              </div>
            `).join('')}
          </div>
        `}
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Fermer</button>
      </div>
    </div>
  `;
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');
  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
}

/** Bouton "Historique" réutilisé identiquement par Congés/Autres absences, Télétravail et Notes de
 * frais (un seul `data-history`, un seul point de câblage — les 3 écrans ne rendent jamais leurs
 * lignes en même temps, donc aucun risque de collision d'attribut entre eux). `repo` est le
 * repository dont dépendent les lignes affichées (leaveRepository/teleworkRepository/
 * expenseRepository), pour retrouver la bonne demande par id. */
function bindHistoryButtons(repo) {
  document.querySelectorAll('[data-history]').forEach(btn => {
    btn.addEventListener('click', () => openRequestHistoryModal(repo.getById(btn.dataset.history)));
  });
}

// ---- Modale : Prolonger un arrêt (§24) ----

function openProlongerModal(requestId) {
  const request = leaveRepository.getById(requestId);
  if (!request) { showToast('Cette demande n\'est plus disponible.', 'error'); return; }
  const employee = employeeRepository.getById(request.employeeId);
  const type = leaveTypeRepository.getLeaveTypeById(request.typeId);
  if (!employee || !type) { showToast('Salarié ou type de congé introuvable.', 'error'); return; }
  // §correctif audit du 31/08/2026 : défense en profondeur — le bouton "Prolonger" n'est déjà rendu
  // que si canProlonger (renderRequestActions) est vrai, mais cette fonction reste appelable
  // directement (devtools/console), contrairement à ses sœurs handleApproveRequest/handleCancelRequest
  // qui revérifient déjà. La vraie barrière reste côté serveur (RLS), mais éviter d'ouvrir la modale
  // pour une action qui échouerait de toute façon reste plus honnête pour l'UI.
  if (type.saisiParSalarie || !hasPermission(authRepository.getCurrentUser(), PERMISSIONS.PROLONGER_MALADIE)) {
    showToast('Action non autorisée.', 'error'); return;
  }

  const html = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>Prolonger l'arrêt</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="prolonger-form">
        <div class="modal-body">
          <p class="text-muted">${personNameHtml(employee)} · ${escapeHtml(type.nom)} · actuellement jusqu'au ${formatDate(request.dateFin)}</p>
          ${textField('nouvelleDateFin', 'Nouvelle date de fin', '', true, 'date')}
          <div class="form-field" style="margin-top: 12px;">
            <label for="f-prolongation-justificatif">Nouveau justificatif (optionnel)</label>
            <input class="input" type="file" id="f-prolongation-justificatif">
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="submit" class="btn btn-primary">Prolonger</button>
        </div>
      </form>
    </div>
  `;

  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');
  state.pendingAttachment = null;

  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('f-prolongation-justificatif').addEventListener('change', handleAttachmentChange);
  document.getElementById('prolonger-form').addEventListener('submit', (evt) => {
    evt.preventDefault();
    const nouvelleDateFin = document.getElementById('f-nouvelleDateFin').value;
    const result = leaveRepository.prolonger(requestId, nouvelleDateFin, state.pendingAttachment);
    if (!result.success) { showToast(result.error, 'error'); return; }
    showToast('Arrêt prolongé.');
    closeModal();
    render();
  });
}

/** Régularisation (§ demandée en cours de session) d'une demande déjà validée : corrige le type
 * et/ou les dates après coup (erreur de saisie, ou pour formaliser ce qui s'est réellement passé),
 * réservée à qui peut déjà gérer la demande (même contrôle que "Annuler"). Le type proposé reste
 * dans la MÊME catégorie (congé ou autre absence) que le type actuel — changer de catégorie via
 * une régularisation mélangerait des règles de saisie différentes (§15) sans raison claire. */
function openRegulariserModal(requestId) {
  const request = leaveRepository.getById(requestId);
  if (!request) { showToast('Cette demande n\'est plus disponible.', 'error'); return; }
  // §correctif audit du 31/08/2026 : défense en profondeur, même contrôle que le bouton "Régulariser"
  // (renderRequestActions) et que handleCancelRequest pour la même permission "gérer cette demande" —
  // manquait ici alors que la doc de cette fonction dit explicitement "réservée à qui peut déjà gérer
  // la demande (même contrôle que Annuler)".
  if (!canManageRequestFor(request.employeeId)) { showToast('Action non autorisée.', 'error'); return; }
  const employee = employeeRepository.getById(request.employeeId);
  const currentType = leaveTypeRepository.getLeaveTypeById(request.typeId);
  if (!employee || !currentType) { showToast('Salarié ou type de congé introuvable.', 'error'); return; }
  // Inclut le type ACTUEL même s'il a été désactivé depuis (sinon le select retombe sur le fallback
  // générique de selectField, qui affiche l'id brut plutôt qu'un nom lisible — même bug déjà corrigé
  // pour les établissements désactivés).
  const typesMemeCategorie = leaveTypeRepository.getLeaveTypes().filter(t =>
    t.categorie === currentType.categorie && (t.actif || t.id === currentType.id));

  const html = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>Régulariser la demande</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="regulariser-form">
        <div class="modal-body">
          <p class="text-muted">${personNameHtml(employee)} — actuellement ${escapeHtml(currentType.nom)}, du ${formatDate(request.dateDebut)} au ${formatDate(request.dateFin)}.</p>
          ${selectField('typeId', 'Type', null, request.typeId, typesMemeCategorie.map(t => ({ value: t.id, label: t.actif ? t.nom : `${t.nom} (désactivé)` })))}
          <div class="form-grid" style="margin-top: 12px;">
            ${textField('dateDebut', 'Date de début', request.dateDebut, true, 'date')}
            ${textField('dateFin', 'Date de fin', request.dateFin, true, 'date')}
          </div>
          <div class="form-field" id="field-demi-journee-regul" style="margin-top: 12px; display:none;">
            <label for="f-demiJournee">Demi-journée</label>
            <select class="input" id="f-demiJournee" name="demiJournee">
              <option value="">Journée entière</option>
              <option value="matin" ${request.demiJournee === 'matin' ? 'selected' : ''}>Matin</option>
              <option value="apres-midi" ${request.demiJournee === 'apres-midi' ? 'selected' : ''}>Après-midi</option>
            </select>
          </div>
          <div class="form-field" style="margin-top: 12px;">
            <label for="f-motif">Motif de la régularisation</label>
            <input class="input" type="text" id="f-motif" name="motif" placeholder="Ex. erreur de saisie initiale, absence reclassée">
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="submit" class="btn btn-primary">Régulariser</button>
        </div>
      </form>
    </div>
  `;

  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');

  // Même condition que updateLeaveRequestHints (création) : la demi-journée n'a de sens que sur
  // une seule journée ET si le type la permet — évite de la proposer puis de l'ignorer en silence.
  const updateDemiJourneeVisibility = () => {
    const type = leaveTypeRepository.getLeaveTypeById(document.getElementById('f-typeId').value);
    const dateDebut = document.getElementById('f-dateDebut').value;
    const dateFin = document.getElementById('f-dateFin').value;
    document.getElementById('field-demi-journee-regul').style.display =
      type && type.autoriserDemiJournee && dateDebut && dateDebut === dateFin ? 'block' : 'none';
  };
  updateDemiJourneeVisibility();
  ['f-typeId', 'f-dateDebut', 'f-dateFin'].forEach(fieldId => {
    document.getElementById(fieldId).addEventListener('change', updateDemiJourneeVisibility);
  });

  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('regulariser-form').addEventListener('submit', (evt) => {
    evt.preventDefault();
    const typeId = document.getElementById('f-typeId').value;
    const dateDebut = document.getElementById('f-dateDebut').value;
    const dateFin = document.getElementById('f-dateFin').value;
    const demiJournee = document.getElementById('field-demi-journee-regul').style.display === 'block' ? (document.getElementById('f-demiJournee').value || null) : null;
    const motif = document.getElementById('f-motif').value;
    const result = leaveRepository.regulariser(requestId, { typeId, dateDebut, dateFin, demiJournee, motif });
    if (!result.success) { showToast(result.error, 'error'); return; }
    showToast('Demande régularisée.');
    closeModal();
    render();
  });
}

function exportLeaveRequestsCSV(categorie = 'conge') {
  const requests = getFilteredLeaveRequests(categorie);
  const headers = ['Salarié', 'Type', 'Début', 'Fin', 'Jours', 'Payé', 'Statut'];
  const rows = requests.map(r => {
    const employee = employeeRepository.getById(r.employeeId);
    const type = leaveTypeRepository.getLeaveTypeById(r.typeId);
    return [
      employee ? `${employee.prenom} ${employee.nom}` : '—',
      type ? type.nom : '—',
      // §retour Betty du 18/09/2026 (point 7) : dates au format français, jours en vrai nombre (pas
      // formatNumberFR, qui produirait un texte aligné à gauche) — voir excelXmlCell/exportRowsToCSV.
      formatDate(r.dateDebut), formatDate(r.dateFin), r.nbJours,
      type && type.paye ? 'Oui' : 'Non',
      r.statut
    ];
  });
  exportRowsToCSV(headers, rows, categorie === 'conge' ? 'conges.csv' : 'autres-absences.csv');
  auditLogRepository.logAudit('Export', categorie === 'conge' ? 'Demandes de congé' : 'Demandes d\'autre absence', `${requests.length} ligne${requests.length > 1 ? 's' : ''}`);
}

function bindCongesDemandesEvents(categorie = 'conge') {
  const filters = categorie === 'conge' ? state.congesFilters : state.autresAbsencesFilters;
  const pageKey = categorie === 'conge' ? 'congesPage' : 'autresAbsencesPage';

  bindFilterToggleButtons();
  document.getElementById('btn-new-leave-request').addEventListener('click', () => openLeaveRequestModal(undefined, categorie));
  document.getElementById('btn-export-conges').addEventListener('click', () => exportLeaveRequestsCSV(categorie));
  bindDraftsCardEvents((draft) => openLeaveRequestModal(undefined, categorie, draft));

  document.getElementById('conges-filter-employee').addEventListener('change', (e) => {
    filters.employeeId = e.target.value;
    state[pageKey] = 1;
    render();
  });
  document.getElementById('conges-filter-type').addEventListener('change', (e) => {
    filters.typeId = e.target.value;
    state[pageKey] = 1;
    render();
  });
  document.getElementById('conges-filter-statut').addEventListener('change', (e) => {
    filters.statut = e.target.value;
    state[pageKey] = 1;
    render();
  });
  document.getElementById('conges-filter-periode').addEventListener('change', (e) => {
    filters.periode = e.target.value;
    state[pageKey] = 1;
    render();
  });

  const congesPrevBtn = document.getElementById('btn-page-prev');
  if (congesPrevBtn) congesPrevBtn.addEventListener('click', () => { state[pageKey] -= 1; render(); });
  const congesNextBtn = document.getElementById('btn-page-next');
  if (congesNextBtn) congesNextBtn.addEventListener('click', () => { state[pageKey] += 1; render(); });

  document.querySelectorAll('[data-approve]').forEach(btn => {
    btn.addEventListener('click', () => handleApproveRequest(btn.dataset.approve));
  });
  document.querySelectorAll('[data-refuse]').forEach(btn => {
    btn.addEventListener('click', () => handleRefuseRequest(btn.dataset.refuse));
  });
  document.querySelectorAll('[data-cancel]').forEach(btn => {
    btn.addEventListener('click', () => handleCancelRequest(btn.dataset.cancel));
  });
  document.querySelectorAll('[data-self-cancel]').forEach(btn => {
    btn.addEventListener('click', () => handleSelfCancelLeaveRequest(btn.dataset.selfCancel));
  });
  document.querySelectorAll('[data-attestation]').forEach(btn => {
    btn.addEventListener('click', () => openLeaveAttestationModal(btn.dataset.attestation));
  });
  document.querySelectorAll('[data-attestation-salaire]').forEach(btn => {
    btn.addEventListener('click', () => openAttestationSalaireModal(btn.dataset.attestationSalaire));
  });

  document.querySelectorAll('[data-prolonger]').forEach(btn => {
    btn.addEventListener('click', () => openProlongerModal(btn.dataset.prolonger));
  });
  document.querySelectorAll('[data-regulariser]').forEach(btn => {
    btn.addEventListener('click', () => openRegulariserModal(btn.dataset.regulariser));
  });
  bindHistoryButtons(leaveRepository);

  // §correctif audit du 23/08/2026 (§7.14) : validation en masse — même moteur (advanceWorkflow)
  // que la validation ligne par ligne (handleApproveRequest), juste répété sur toute la sélection
  // avec UN SEUL toast/rendu à la fin plutôt que vingt.
  const selection = bulkSelection[categorie];
  const selectAll = document.getElementById('conges-select-all');
  if (selectAll) {
    selectAll.addEventListener('change', () => {
      document.querySelectorAll('.conges-select-row').forEach(cb => {
        const id = cb.dataset.selectRequest;
        if (selectAll.checked) selection.add(id); else selection.delete(id);
      });
      render();
    });
  }
  document.querySelectorAll('[data-select-request]').forEach(cb => {
    cb.addEventListener('change', () => {
      if (cb.checked) selection.add(cb.dataset.selectRequest); else selection.delete(cb.dataset.selectRequest);
      render();
    });
  });
  const bulkApproveBtn = document.getElementById('btn-bulk-approve');
  if (bulkApproveBtn) bulkApproveBtn.addEventListener('click', () => handleBulkApproveRequests(categorie));
  const bulkClearBtn = document.getElementById('btn-bulk-clear');
  if (bulkClearBtn) bulkClearBtn.addEventListener('click', () => { selection.clear(); render(); });
}

function handleBulkApproveRequests(categorie) {
  const selection = bulkSelection[categorie];
  let approved = 0, skipped = 0;
  selection.forEach(id => {
    const request = leaveRepository.getById(id);
    if (!request || !canActOnRequestFor(request)) { skipped++; return; }
    const patch = advanceWorkflow(request, 'Validé', currentActorRoleLabel());
    leaveRepository.update(id, patch);
    auditLogRepository.logAudit('Validation', 'Demande de congé', auditLabelForEmployee(request.employeeId), auditDetailsForActor());
    if (patch.statut !== 'En attente') {
      notifyRequesterEmail(request.id, 'conge', 'validee');
    }
    approved++;
  });
  selection.clear();
  showToast(`${approved} demande${approved > 1 ? 's' : ''} validée${approved > 1 ? 's' : ''}${skipped ? ` (${skipped} ignorée${skipped > 1 ? 's' : ''}, plus à jour)` : ''}.`);
  render();
}

// ---- Modale : Attestation de congé (imprimable / export PDF) ----

function openLeaveAttestationModal(requestId) {
  const r = leaveRepository.getById(requestId);
  if (!r) { showToast('Cette demande n\'est plus disponible.', 'error'); return; }
  const employee = employeeRepository.getById(r.employeeId);
  const type = leaveTypeRepository.getLeaveTypeById(r.typeId);
  if (!employee || !type) { showToast('Salarié ou type de congé introuvable.', 'error'); return; }
  const profile = companyRepository.getProfile();
  const settings = settingsRepository.getSettings();
  const posteFallback = getSexe(employee) === 'Homme' ? 'salarié' : getSexe(employee) === 'Femme' ? 'salariée' : 'salarié·e';
  const periode = r.dateDebut === r.dateFin
    ? formatDate(r.dateDebut) + (r.demiJournee ? ` (${r.demiJournee === 'matin' ? 'matin' : 'après-midi'})` : '')
    : `du ${formatDate(r.dateDebut)} au ${formatDate(r.dateFin)}`;

  const html = `
    <div class="modal">
      <div class="modal-header">
        <h2>Attestation de congé</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <div class="modal-body">
        <div class="print-area print-document">
          ${renderPrintDocumentHeader(profile, 'Attestation de congés')}
          <p class="print-attestation-text">
            ${escapeHtml(profile.raisonSociale || 'Nexus')} atteste que <strong>${personNameHtml(employee)}</strong>
            (matricule ${escapeHtml(employee.matricule)}), ${escapeHtml(getPosteAccorde(employee, settings) || posteFallback)},
            a bénéficié d'un congé de type <strong>${escapeHtml(type.nom)}</strong> ${periode},
            soit ${formatNumberFR(r.nbJours)} jour${r.nbJours > 1 ? 's' : ''}.
          </p>
          <div class="print-signature">
            <span>Fait pour valoir ce que de droit.</span>
            <span class="print-signature-line">Signature RH</span>
          </div>
        </div>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Fermer</button>
        <button type="button" class="btn btn-primary" id="btn-print-attestation">Imprimer / Export PDF</button>
      </div>
    </div>
  `;

  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');

  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('btn-print-attestation').addEventListener('click', () => {
    auditLogRepository.logAudit('Export', 'Attestation de congé', `${employee.prenom} ${employee.nom}`);
    window.print();
  });
}

/** §retour Betty du 11/09/2026 (point 4.1, "arrêts de travail") : "un prospect nous posera la
 * question dans les 10 premières minutes" — jusqu'ici rien n'existait pour préparer l'attestation
 * de salaire (le document transmis à la CPAM pour déclencher les indemnités journalières), au-delà
 * de l'attestation de congé générique ci-dessus (juste "il/elle était absent·e", sans salaire).
 *
 * SCOPE VOLONTAIREMENT LIMITÉ (v1, chiffrage séparé pour la suite selon Betty elle-même) : regroupe
 * les données déjà disponibles dans l'app (identité, dates de l'arrêt, type, subrogation, salaire
 * brut mensuel SI le suivi de masse salariale est activé) dans un document imprimable à
 * relire/compléter avant transmission. AUCUN calcul d'indemnités journalières, de carence ou de
 * salaire de référence (moyenne des 3 derniers mois, plafond sécu...) : une erreur sur ce calcul a
 * un impact financier réel pour le salarié, contrairement à un document mal mis en page — à ne
 * jamais automatiser sans validation par quelqu'un de compétent en paie. Nexus alimente la paie, il
 * ne la fait pas (position de Betty, cf. le reste de ce sujet). */
/** §retour Betty du 13/09/2026 (point 4.1 v2a, chiffrage validé) : estimation IJ/carence/maintien
 * calculée à la volée (calculerEstimationIndemnitesArret, data.js) — jamais persistée, jamais
 * présentée sans l'avertissement "estimation indicative" (voir sa raison d'être : basée sur le seul
 * salaireBrutMensuel, pas la moyenne réelle des 3 derniers mois). Rendu séparé de l'attestation
 * elle-même pour rester lisible même si l'estimation est indisponible (pas de salaire renseigné). */
function renderEstimationIndemnitesArret(r, employee) {
  if (!employee.salaireBrutMensuel) {
    return `<h2>Estimation des indemnités</h2><p class="text-muted">Non calculable : aucun salaire brut mensuel renseigné sur la fiche salarié.</p>`;
  }
  const allRequestsEmployee = leaveRepository.getForEmployee(employee.id);
  const estimation = calculerEstimationIndemnitesArret(r, employee, allRequestsEmployee);
  if (!estimation) return '';
  const m = estimation.maintien;
  return `
    <h2>Estimation des indemnités <span class="badge badge-warning">Indicatif, non contractuel</span></h2>
    <p class="text-muted">${icon(ICONS.warningTriangle, 12)} Estimation calculée à partir du seul salaire brut mensuel de la fiche salarié (${formatCurrencyFR(employee.salaireBrutMensuel)}), pas de la moyenne réelle des 3 derniers mois (primes, heures supplémentaires...) que retient la CPAM. Ne remplace jamais le décompte officiel de la CPAM ni le calcul de votre gestionnaire de paie.</p>
    <p>Carence : <strong>${estimation.joursCarence} jour(s)</strong> · Jours indemnisables : <strong>${estimation.joursIndemnisables}</strong> sur ${estimation.nbJoursCalendaires} jours calendaires</p>
    <p>IJ sécurité sociale estimée : <strong>${formatCurrencyFR(estimation.ijSecuEstimee)}</strong></p>
    ${m.ancienneteInsuffisante
      ? `<p>Maintien de salaire employeur : <strong>aucun</strong> (ancienneté inférieure à 1 an, minimum légal L1226-1, une convention collective peut prévoir mieux, non appliqué ici).</p>`
      : `<p>Maintien de salaire employeur (ancienneté retenue : ${estimation.ancienneteAnneesEntieres} an(s)) : <strong>${m.joursPlein}</strong> jour(s) à 90% + <strong>${m.joursDemi}</strong> jour(s) à 66,66%${m.joursNonCouverts > 0 ? ` · <strong>${m.joursNonCouverts}</strong> jour(s) hors capacité 12 mois glissants` : ''} — maintien total estimé <strong>${formatCurrencyFR(m.montant)}</strong>, dont complément employeur (au-delà de l'IJ sécu) estimé à <strong>${formatCurrencyFR(estimation.complementEmployeurEstime)}</strong>.</p>`}
  `;
}

function openAttestationSalaireModal(requestId) {
  const r = leaveRepository.getById(requestId);
  if (!r) { showToast('Cette demande n\'est plus disponible.', 'error'); return; }
  const employee = employeeRepository.getById(r.employeeId);
  const type = leaveTypeRepository.getLeaveTypeById(r.typeId);
  if (!employee || !type || !r.arretTravail) { showToast('Informations d\'arrêt introuvables pour cette demande.', 'error'); return; }
  const profile = companyRepository.getProfile();
  const settings = settingsRepository.getSettings();
  const arret = r.arretTravail;
  const prolongations = r.prolongations || [];
  const derniereProlongation = prolongations[prolongations.length - 1];

  const html = `
    <div class="modal">
      <div class="modal-header">
        <h2>Attestation de salaire</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <div class="modal-body">
        <p class="text-muted">${icon(ICONS.warningTriangle, 12)} Document préparatoire, à relire et compléter (salaire de référence, dates) avant transmission à la CPAM. Aucune indemnité n'est calculée par Nexus.</p>
        <div class="print-area print-document">
          ${renderPrintDocumentHeader(profile, 'Attestation de salaire')}
          <h2>Employeur</h2>
          <p>${escapeHtml(profile.raisonSociale || '____________________')}${profile.siret ? ' · SIRET ' + escapeHtml(profile.siret) : ''}</p>
          <p>${escapeHtml(profile.adresse || '____________________')}</p>
          <h2>Salarié</h2>
          <p>${personNameHtml(employee)} (matricule ${escapeHtml(employee.matricule || '—')})${employee.numeroSecu ? ' · N° sécurité sociale ' + escapeHtml(employee.numeroSecu) : ' · N° sécurité sociale non renseigné dans la fiche'}</p>
          <p>Poste : ${escapeHtml(getPosteAccorde(employee, settings) || '—')} · Dernier jour travaillé avant l'arrêt : ${formatDate(r.dateDebut)}</p>
          <h2>Arrêt de travail</h2>
          <p>Type : <strong>${escapeHtml(TYPE_ARRET_LABELS[arret.typeArret] || arret.typeArret)}</strong></p>
          <p>Période : du ${formatDate(r.dateDebut)} au ${formatDate(r.dateFin)}${derniereProlongation ? ` (dernière prolongation déclarée le ${formatDate(derniereProlongation.date)})` : ''}</p>
          <p>Subrogation employeur : <strong>${arret.subrogation ? 'Oui (l\'entreprise perçoit les IJ et maintient le salaire)' : 'Non'}</strong></p>
          <h2>Salaire de référence</h2>
          ${settings.masseSalarialeActivee && employee.salaireBrutMensuel
            ? `<p>Salaire brut mensuel actuel (fiche salarié) : ${formatCurrencyFR(employee.salaireBrutMensuel)} — à vérifier sur les 3 derniers mois réels avant transmission (primes, heures supplémentaires, changement de taux...), Nexus n'alimentant pas votre historique de paie détaillé.</p>`
            : `<p class="text-muted">Non renseigné dans Nexus (suivi de la masse salariale désactivé, ou champ vide sur la fiche salarié) — à compléter manuellement avec votre gestionnaire de paie.</p>`}
          ${settings.masseSalarialeActivee ? renderEstimationIndemnitesArret(r, employee) : ''}
          <div class="print-signature">
            <span>Fait pour servir et valoir ce que de droit.</span>
            <span class="print-signature-line">Signature et cachet de l'entreprise</span>
          </div>
        </div>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Fermer</button>
        <button type="button" class="btn btn-primary" id="btn-print-attestation-salaire">Imprimer / Export PDF</button>
      </div>
    </div>
  `;
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');
  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('btn-print-attestation-salaire').addEventListener('click', () => {
    auditLogRepository.logAudit('Export', 'Attestation de salaire', `${employee.prenom} ${employee.nom}`);
    window.print();
  });
}

function auditLabelForEmployee(employeeId) {
  const employee = employeeRepository.getById(employeeId);
  return employee ? `${employee.prenom} ${employee.nom}` : '—';
}

/** §correctif QA du 26/08/2026 : jusqu'ici, valider/refuser une demande de congé/télétravail/note
 * de frais ne journalisait QUE le salarié concerné (cible), jamais qui avait réellement cliqué —
 * aucune trace de l'auteur d'une validation/refus dans le journal d'audit. Réutilisé comme 4e
 * paramètre `details` de logAudit à ces 4 endroits, et comme rôle réel passé à advanceWorkflow
 * (qui l'utilise pour l'historique affiché au salarié, à la place du rôle programmé de l'étape). */
function currentActorRoleLabel() {
  const user = authRepository.getCurrentUser();
  return user ? (ROLE_LABELS[user.role] || user.role) : '—';
}

function auditDetailsForActor() {
  const user = authRepository.getCurrentUser();
  if (!user) return '';
  return `Par ${user.prenom} ${user.nom} (${currentActorRoleLabel()})`;
}

/** §correctif audit du 23/08/2026 (§7.4) : notifie le SALARIÉ par email seulement à l'issue finale
 * (validé/refusé) — jamais à chaque étape intermédiaire d'une chaîne à plusieurs niveaux, qui
 * reste "En attente" (voir advanceWorkflow, data.js : etapeIndex repasse à -1 seulement à la
 * toute dernière étape). Fire-and-forget, comme toutes les notifications de ce fichier.
 *
 * §correctif retour QA du 26/08/2026 (point 5.2) : ne fournit plus le contenu de l'email — la
 * fonction Edge relit désormais la VRAIE demande (requestId + domain) et vérifie que l'appelant
 * (qui vient de valider/refuser) est bien un validateur éligible avant tout envoi. */
function notifyRequesterEmail(requestId, domain, template, motif) {
  window.SupabaseSync.notifyRequestEmail(requestId, domain, template, motif).catch(() => {});
}

function requestPeriodeLabel(request) {
  return request.dateDebut === request.dateFin ? formatDate(request.dateDebut) : `${formatDate(request.dateDebut)} → ${formatDate(request.dateFin)}`;
}

function handleApproveRequest(id) {
  const request = leaveRepository.getById(id);
  // Défense en profondeur : le bouton n'est déjà rendu que si canActOnRequestFor(request) est vrai,
  // mais cette fonction reste appelable directement (devtools/console) — revérifie ici. La vraie
  // barrière est de toute façon côté serveur (policies RLS Supabase), mais éviter une mise à jour
  // optimiste locale trompeuse (que Supabase rejetterait silencieusement) reste plus honnête pour l'UI.
  if (!request || !canActOnRequestFor(request)) { showToast('Action non autorisée.', 'error'); return; }
  const patch = advanceWorkflow(request, 'Validé', currentActorRoleLabel());
  leaveRepository.update(id, patch);
  auditLogRepository.logAudit('Validation', 'Demande de congé', auditLabelForEmployee(request.employeeId), auditDetailsForActor());
  if (patch.statut !== 'En attente') {
    notifyRequesterEmail(request.id, 'conge', 'validee');
  }
  showToast('Demande validée.');
  render();
}

function handleRefuseRequest(id) {
  const request = leaveRepository.getById(id);
  if (!request || !canRefuserRequestFor(request)) { showToast('Action non autorisée.', 'error'); return; }
  openRefuseModal({
    title: 'Refuser cette demande ?',
    message: 'Le salarié sera informé du refus. Ses jours ne seront pas décomptés.',
    onConfirm: (motif) => {
      leaveRepository.update(id, refuseRequest(request, motif));
      auditLogRepository.logAudit('Refus', 'Demande de congé', `${auditLabelForEmployee(request.employeeId)} : ${motif}`, auditDetailsForActor());
      notifyRequesterEmail(request.id, 'conge', 'refusee', motif);
      showToast('Demande refusée.');
      render();
    }
  });
}

function handleCancelRequest(id) {
  const request = leaveRepository.getById(id);
  if (!request || !canManageRequestFor(request.employeeId)) { showToast('Action non autorisée.', 'error'); return; }
  openConfirm({
    title: 'Annuler cette demande ?',
    message: 'Les jours seront recrédités sur le compteur du salarié.',
    confirmLabel: 'Annuler la demande',
    danger: true,
    onConfirm: () => {
      leaveRepository.update(id, cancelRequest(request));
      auditLogRepository.logAudit('Annulation', 'Demande de congé', auditLabelForEmployee(request.employeeId), auditDetailsForActor());
      showToast('Demande annulée.');
      render();
    }
  });
}

/** §tour de bugs du 07/09/2026 (point 5, même famille que Notes de frais) : le demandeur annule
 * SA PROPRE demande encore en attente, avant toute validation — jamais besoin d'attendre un refus
 * pour une simple erreur, mais protégé dès qu'une étape a été franchie (canSelfCancelPendingRequest). */
function handleSelfCancelLeaveRequest(id) {
  const request = leaveRepository.getById(id);
  const user = authRepository.getCurrentUser();
  if (!request || !canSelfCancelPendingRequest(request, user)) { showToast('Action non autorisée.', 'error'); return; }
  openConfirm({
    title: 'Annuler votre demande ?',
    message: 'Cette demande n\'a encore été validée par personne : elle sera annulée sans repasser par un refus.',
    confirmLabel: 'Annuler la demande',
    danger: true,
    onConfirm: () => {
      leaveRepository.update(id, cancelRequest(request));
      auditLogRepository.logAudit('Annulation', 'Demande de congé', auditLabelForEmployee(request.employeeId), auditDetailsForActor());
      showToast('Demande annulée.');
      render();
    }
  });
}

/** Sprint SIRH premium §10 : les 3 modales de demande (congé/absence, télétravail, note de frais)
 * peuvent s'ouvrir sur un brouillon repris — beginDraftEdit()/finalizeDraftEdit() portent les 2
 * lignes autrement copiées-collées dans chacune des 3 modales (au open) et chacun des 3 submit
 * handlers (au succès), pour que "reprendre un brouillon" reste un seul mécanisme à faire évoluer. */
function beginDraftEdit(draft) {
  state.editingDraftId = draft ? draft.id : null;
}

function finalizeDraftEdit() {
  if (state.editingDraftId) { draftRepository.delete(state.editingDraftId); state.editingDraftId = null; }
}

/** Sprint SIRH premium §10 : enregistre l'état ACTUEL du formulaire comme brouillon, sans aucune
 * validation (un brouillon peut être incomplet par définition — c'est tout l'intérêt). `extra`
 * porte les champs qui ne sont pas de simples <input name="…"> (catégorie congé/absence, pièce
 * jointe déjà lue en dataURL via state.pendingAttachment). Un brouillon en cours de reprise
 * (state.editingDraftId) est écrasé plutôt que dupliqué. */
function saveDraftFromForm(form, type, extra) {
  const formData = new FormData(form);
  const champs = {};
  for (const [key, value] of formData.entries()) champs[key] = value;
  Object.assign(champs, extra || {});
  finalizeDraftEdit();
  draftRepository.create({ ownerId: authRepository.getCurrentUser().id, type, champs });
  closeModal();
  showToast('Brouillon enregistré.');
  render();
}

/** Sprint SIRH premium §10 : carte "Mes brouillons", réutilisée par Congés/Autres absences,
 * Télétravail et Notes de frais — ne montre que les brouillons de L'UTILISATEUR COURANT (peu
 * importe pour qui la demande est destinée, cf. saveDraftFromForm) et du type demandé. Pas de carte
 * du tout si la liste est vide, pour ne jamais ajouter de bruit à un écran qui n'en a pas besoin. */
function renderDraftsCard(type) {
  const drafts = draftRepository.getForOwner(authRepository.getCurrentUser().id, type);
  if (!drafts.length) return '';
  return `
    <div class="card">
      <h2>Mes brouillons</h2>
      <div class="mini-list">
        ${drafts.map(d => `
          <div class="mini-list-item">
            <span>${draftSummaryLabel(d)} <span class="text-muted">· modifié le ${formatDate(d.dateModification)}</span></span>
            <span class="table-actions">
              <button type="button" class="btn btn-secondary btn-sm" data-draft-resume="${d.id}">Reprendre</button>
              <button type="button" class="btn btn-secondary btn-sm" data-draft-delete="${d.id}">Supprimer</button>
            </span>
          </div>
        `).join('')}
      </div>
    </div>
  `;
}

function draftSummaryLabel(draft) {
  const c = draft.champs || {};
  if (draft.type === 'conge' || draft.type === 'autre-absence') {
    const type = c.typeId ? leaveTypeRepository.getLeaveTypeById(c.typeId) : null;
    return `${type ? escapeHtml(type.icone) + ' ' + escapeHtml(type.nom) : 'Type non choisi'}${c.dateDebut ? ' · ' + formatDate(c.dateDebut) : ''}`;
  }
  if (draft.type === 'teletravail') {
    return `${icon(ICONS.laptop, 13)} Télétravail${c.dateDebut ? ' · ' + formatDate(c.dateDebut) : ''}`;
  }
  if (draft.type === 'frais') {
    return `${icon(ICONS.receipt, 13)} ${escapeHtml(c.libelle || c.categorie || 'Note de frais')}${c.montantTTC ? ' · ' + formatCurrencyFR(Number(c.montantTTC)) : ''}`;
  }
  return 'Brouillon';
}

function bindDraftsCardEvents(resumeHandler) {
  document.querySelectorAll('[data-draft-resume]').forEach(btn => {
    btn.addEventListener('click', () => resumeHandler(draftRepository.getById(btn.dataset.draftResume)));
  });
  document.querySelectorAll('[data-draft-delete]').forEach(btn => {
    btn.addEventListener('click', () => {
      const draftId = btn.dataset.draftDelete;
      openConfirm({
        title: 'Supprimer ce brouillon ?',
        message: 'Cette action est irréversible.',
        confirmLabel: 'Supprimer',
        danger: true,
        onConfirm: () => { draftRepository.delete(draftId); showToast('Brouillon supprimé.'); render(); }
      });
    });
  });
}

// ---- Modale : Nouvelle demande de congé ----

/**
 * Champ "Salarié" des modales de demande : qui n'a le droit de saisir que pour lui-même voit un
 * champ verrouillé, les autres gardent le sélecteur, restreint aux salariés pour lesquels ils
 * peuvent réellement écrire (voir requestTargetIdsForCurrentUser juste en dessous).
 */
/** Qui peut déposer une demande POUR UN AUTRE salarié — doit rester le strict miroir des policies
 * RLS d'insertion (0032_demandes_pour_autrui.sql) : tout écart ici recrée exactement le bug corrigé
 * par cette migration (une demande acceptée à l'écran, refusée par Postgres, perdue au rechargement
 * sans autre trace qu'un toast). `getVisibleEmployeeIdsForCurrentUser` ne convient PAS comme
 * critère : il donne à la Comptabilité une visibilité entreprise entière au titre de son rôle,
 * alors qu'elle n'a aucune permission de gestion des absences et ne peut donc écrire que pour
 * elle-même. */
function requestTargetIdsForCurrentUser(kind) {
  const user = authRepository.getCurrentUser();
  if (!user) return [];
  const canActForAll = kind === 'frais'
    ? hasPermission(user, PERMISSIONS.VALIDER_NOTE_FRAIS)
    : hasPermission(user, PERMISSIONS.VALIDER_ABSENCE) || hasPermission(user, PERMISSIONS.SAISIR_MALADIE);
  if (canActForAll) return null; // toute l'entreprise

  // Le champ "Manager(s)" d'une fiche accepte N'IMPORTE QUEL salarié non archivé, sans condition de
  // rôle (voir openEmployeeModal). Sans ce test sur le rôle, un salarié désigné comme manager de
  // quelqu'un se verrait donc proposer un sélecteur pour déposer des demandes à la place de ses
  // collègues : un droit qu'il n'avait pas auparavant, et qu'il ne pourrait de toute façon pas
  // exercer jusqu'au bout, isCurrentWorkflowStepFor exigeant le rôle manager pour valider l'étape.
  // On s'aligne donc sur la validation : seul le rôle manager ouvre le périmètre équipe.
  if (user.role !== ROLES.MANAGER) return [user.id];

  const managedIds = employeeRepository.getAll()
    .filter(e => isManagerOfEmployee(user.id, e.id))
    .map(e => e.id);
  // Un manager ne dépose une note de frais pour son équipe que s'il la contrôle (même nuance que
  // expenses_insert : controlerNoteFrais côté manager, validerNoteFrais côté RH).
  const canActForTeam = kind !== 'frais' || hasPermission(user, PERMISSIONS.CONTROLER_NOTE_FRAIS);
  return canActForTeam ? [user.id, ...managedIds] : [user.id];
}

function employeeFieldForRequest(presetEmployeeId, employees, kind = 'absence') {
  const user = authRepository.getCurrentUser();
  const targetIds = requestTargetIdsForCurrentUser(kind);
  // Un seul destinataire possible (soi-même) : champ verrouillé plutôt qu'un sélecteur à une entrée
  // — cas du rôle Salarié, et de tout rôle sans droit de saisie pour autrui.
  if (targetIds !== null && targetIds.length === 1) {
    return `
      <input type="hidden" id="f-employeeId" name="employeeId" value="${escapeHtml(user.id)}">
      <div class="form-field">
        <label>Salarié</label>
        <input class="input" type="text" value="${personNameHtml(user)}" disabled>
      </div>
    `;
  }
  const scoped = targetIds === null ? employees : employees.filter(e => targetIds.includes(e.id));
  // §retour Betty du 18/09/2026 (point 6) : sans presetEmployeeId (ouvert depuis l'écran de liste,
  // pas depuis la fiche de quelqu'un d'autre), préselectionne l'utilisateur connecté plutôt qu'un
  // tiret vide — user.id fait toujours partie de `scoped` (requestTargetIdsForCurrentUser inclut
  // toujours soi-même), donc jamais une valeur hors liste. Vaut pour les 4 formulaires qui passent
  // par cette fonction (congés, autres absences, télétravail, notes de frais).
  return selectField('employeeId', 'Salarié', null, presetEmployeeId || user.id || '', scoped.map(e => ({ value: e.id, label: `${e.prenom} ${e.nom}` })));
}

/** Sprint SIRH premium §10 : `draft` (optionnel) = brouillon repris via "Reprendre" dans la liste
 * "Mes brouillons" — préremplit le formulaire et fait passer le futur submit en mode "convertir le
 * brouillon" (state.editingDraftId) plutôt que "créer depuis zéro" ; supprimé automatiquement une
 * fois la demande réellement envoyée. */
/** presetDate : préremplit début ET fin (clic sur une case du calendrier, §sprint calendrier
 * interactif) — ignoré si un brouillon fournit déjà ses propres dates. */
function openLeaveRequestModal(presetEmployeeId, categorie, draft, presetDate) {
  const employees = employeeRepository.getAll().filter(e => !e.archive);
  // §15/§24 : un type marqué "saisie réservée aux RH" (ex. Maladie) ne doit pas être proposé à qui
  // n'a pas SAISIR_MALADIE — sinon un salarié pourrait se déclarer lui-même en arrêt maladie alors
  // que le cahier des charges l'attribue exclusivement au service RH.
  const canSaisirRestreint = hasPermission(authRepository.getCurrentUser(), PERMISSIONS.SAISIR_MALADIE);
  const currentUser = authRepository.getCurrentUser();
  // Sprint SIRH premium §1 : un salarié (uniquement en libre-service sur SA PROPRE fiche — jamais
  // un manager/RH créant une demande pour le compte d'un tiers, qui agit à titre administratif, cf.
  // le même principe que le contournement SAISIR_MALADIE ci-dessus) ne peut demander que les types
  // que l'entreprise ET sa propre fiche autorisent (cf. renderTypesAbsenceCard).
  const typesDesactivesPourSoi = currentUser.role === ROLES.SALARIE
    ? new Set(currentUser.typesAbsenceDesactives || [])
    : new Set();
  // §3 sprint amélioration : si on connaît déjà le salarié cible (cas le plus courant, libre-
  // service), on ne lui propose même pas un type pour lequel il n'est pas éligible — le contrôle à
  // la soumission (submitLeaveRequestForm) reste le filet de sécurité pour le cas où un RH/manager
  // choisit le salarié dans un menu déroulant du formulaire, pas encore connu ici.
  const presetEmployee = presetEmployeeId ? employeeRepository.getById(presetEmployeeId) : null;
  const categoriesSalarie = categorieSalarieRepository.getAll();
  const types = leaveTypeRepository.getLeaveTypes().filter(t =>
    t.actif && t.visibleSalarie && (!categorie || t.categorie === categorie) &&
    (t.saisiParSalarie || canSaisirRestreint) && !typesDesactivesPourSoi.has(t.id) &&
    (!presetEmployee || isLeaveTypeEligibleForEmployee(presetEmployee, t, categoriesSalarie)));
  const champs = (draft && draft.champs) || {};
  if (!draft && presetDate) {
    champs.dateDebut = presetDate;
    champs.dateFin = presetDate;
  }
  state.pendingAttachment = champs.justificatif || null;
  beginDraftEdit(draft);

  // Bandeau informatif si le jour préselectionné est férié/en vacances scolaires — pour ne pas
  // perdre cette information en passant du calendrier (où elle est visible) à ce formulaire.
  let contextBanner = '';
  if (presetDate) {
    const settings = settingsRepository.getSettings();
    const ferie = getAllPublicHolidays(Number(presetDate.slice(0, 4)), settings).find(h => h.date === presetDate);
    const schoolHolidays = schoolHolidayRepository.getSchoolHolidays();
    const vacances = schoolHolidays ? findSchoolHolidayPeriod(presetDate, settings.schoolZone, schoolHolidays) : null;
    if (ferie) contextBanner = `<p class="text-muted" style="margin-top:0;">${icon(ICONS.calendar, 14)} ${escapeHtml(formatDate(presetDate))} est un jour férié (${escapeHtml(ferie.label)}).</p>`;
    else if (vacances) contextBanner = `<p class="text-muted" style="margin-top:0;">${icon(ICONS.backpack, 14)} ${escapeHtml(formatDate(presetDate))} est en période de vacances scolaires (${escapeHtml(vacances.nom)}).</p>`;
  }

  const html = `
    <div class="modal modal-large">
      <div class="modal-header">
        <h2>${categorie === 'autre' ? 'Nouvelle demande d\'absence' : categorie === 'conge' ? 'Nouvelle demande de congé' : 'Nouvelle demande'}</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="leave-request-form">
        <div class="modal-body">
          ${contextBanner}
          <div class="form-grid">
            ${employeeFieldForRequest(presetEmployeeId || champs.employeeId, employees)}
            ${selectField('typeId', categorie === 'autre' ? 'Type d\'absence' : 'Type de congé', null, champs.typeId || '', types.map(t => ({ value: t.id, label: `${t.icone} ${t.nom}` })))}
            ${textField('dateDebut', 'Date de début', champs.dateDebut || '', true, 'date')}
            ${textField('dateFin', 'Date de fin', champs.dateFin || '', true, 'date')}
          </div>
          <div class="form-field" id="field-demi-journee" style="margin-top:14px; display:none;">
            <label>Demi-journée</label>
            <select class="input" id="f-demiJournee" name="demiJournee">
              <option value="" ${!champs.demiJournee ? 'selected' : ''}>Journée complète</option>
              <option value="matin" ${champs.demiJournee === 'matin' ? 'selected' : ''}>Matin</option>
              <option value="apres-midi" ${champs.demiJournee === 'apres-midi' ? 'selected' : ''}>Après-midi</option>
            </select>
          </div>
          <!-- §correctif audit du 23/08/2026 (§7.12) : computeWorkingDays n'acceptait une demi-
               journée que si dateDebut === dateFin — impossible de poser du vendredi après-midi au
               mercredi matin sans découper en trois demandes. Deux champs distincts (début/fin),
               visibles seulement sur une période de PLUSIEURS jours (le champ ci-dessus couvre déjà
               le cas mono-jour). -->
          <div class="form-grid" id="field-demi-journee-multi" style="margin-top:14px; display:none;">
            <div class="form-field">
              <label for="f-demiJourneeDebut">Premier jour</label>
              <select class="input" id="f-demiJourneeDebut" name="demiJourneeDebut">
                <option value="" ${!champs.demiJourneeDebut ? 'selected' : ''}>Journée complète</option>
                <option value="apres-midi" ${champs.demiJourneeDebut === 'apres-midi' ? 'selected' : ''}>Après-midi seulement</option>
              </select>
            </div>
            <div class="form-field">
              <label for="f-demiJourneeFin">Dernier jour</label>
              <select class="input" id="f-demiJourneeFin" name="demiJourneeFin">
                <option value="" ${!champs.demiJourneeFin ? 'selected' : ''}>Journée complète</option>
                <option value="matin" ${champs.demiJourneeFin === 'matin' ? 'selected' : ''}>Matin seulement</option>
              </select>
            </div>
          </div>
          <!-- §retour Betty du 11/09/2026 (point 4.1, "arrêts de travail") : visible seulement pour
               un type "Maladie" (voir isArretTravailType), togglé par updateLeaveRequestHints comme
               les champs demi-journée ci-dessus. Purement déclaratif, aucun calcul d'indemnités
               journalières ici (chantier à part). -->
          <div class="form-grid" id="field-arret-travail" style="margin-top:14px; display:none;">
            <div class="form-field">
              <label for="f-typeArret">Type d'arrêt</label>
              <select class="input" id="f-typeArret" name="typeArret">
                ${Object.keys(TYPE_ARRET_LABELS).map(k => `<option value="${k}" ${(champs.typeArret || 'maladie') === k ? 'selected' : ''}>${TYPE_ARRET_LABELS[k]}</option>`).join('')}
              </select>
            </div>
            <div class="form-field form-field-checkbox" style="align-items: flex-end;">
              <label><input type="checkbox" id="f-subrogation" ${champs.subrogation ? 'checked' : ''}> Subrogation (l'entreprise perçoit les IJ et maintient le salaire)</label>
            </div>
          </div>
          <div class="form-field" style="margin-top:14px;">
            <label for="f-commentaire">Commentaire</label>
            <textarea class="input" id="f-commentaire" name="commentaire" rows="2">${escapeHtml(champs.commentaire || '')}</textarea>
          </div>
          <div class="form-field" style="margin-top:14px;">
            <label for="f-justificatif">Pièce justificative (optionnel)</label>
            <input class="input" type="file" id="f-justificatif">
            ${champs.justificatif ? `<p class="text-muted" style="margin-top:4px;">Fichier repris du brouillon : ${escapeHtml(champs.justificatif.nom)}</p>` : ''}
          </div>
          <p class="text-muted" id="leave-balance-hint" style="margin-top:12px;"></p>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="button" class="btn btn-secondary" id="btn-save-draft">Enregistrer comme brouillon</button>
          <button type="submit" class="btn btn-primary">Envoyer la demande</button>
        </div>
      </form>
    </div>
  `;

  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');

  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('f-justificatif').addEventListener('change', handleAttachmentChange);
  document.getElementById('leave-request-form').addEventListener('submit', submitLeaveRequestForm);
  document.getElementById('btn-save-draft').addEventListener('click', () => {
    saveDraftFromForm(document.getElementById('leave-request-form'), categorie === 'autre' ? 'autre-absence' : 'conge', { categorie: categorie || 'conge', justificatif: state.pendingAttachment });
  });

  ['f-employeeId', 'f-typeId', 'f-dateDebut', 'f-dateFin'].forEach(fieldId => {
    const el = document.getElementById(fieldId);
    if (el) el.addEventListener('change', updateLeaveRequestHints);
  });
  updateLeaveRequestHints();
}

const MAX_ATTACHMENT_SIZE_BYTES = 2 * 1024 * 1024; // 2 Mo — plafond conservé même avec Storage réel (taille raisonnable pour un justificatif/document RH)

/** state.pendingAttachmentFile (le File brut) n'est JAMAIS placé dans un enregistrement persisté —
 * il ne sert qu'à uploadJustificatifBestEffort juste après la création (voir plus bas), tant que le
 * File existe encore en mémoire. state.pendingAttachment ({nom, dataUrl}) reste la donnée locale
 * immédiate et le repli si l'upload Storage échoue ou n'a pas encore eu lieu. */
function handleAttachmentChange(e) {
  const file = e.target.files[0];
  if (!file) { state.pendingAttachment = null; state.pendingAttachmentFile = null; return; }
  if (file.size > MAX_ATTACHMENT_SIZE_BYTES) {
    showToast(`Fichier trop volumineux (${formatNumberFR(file.size / (1024 * 1024), 1)} Mo) : 2 Mo maximum.`, 'error');
    e.target.value = '';
    state.pendingAttachment = null;
    state.pendingAttachmentFile = null;
    return;
  }
  state.pendingAttachmentFile = file;
  const reader = new FileReader();
  reader.onload = () => { state.pendingAttachment = { nom: file.name, dataUrl: reader.result }; };
  reader.readAsDataURL(file);
}

/** D1+D9 (audit fiabilité 19/08/2026) : upload Storage best-effort après création d'un document/
 * congé/note de frais avec justificatif. Ne bloque jamais la création (déjà faite avec le dataUrl
 * local) et n'affiche aucune erreur à l'utilisateur en cas d'échec — le dataUrl local reste
 * disponible comme source de vérité, seul l'accès "signé" futur ne bénéficiera pas encore du
 * fichier réel avant un nouvel essai. `uploader`/`patcher` sont injectés pour rester générique entre
 * document/congé/note de frais (chacun a son propre repository.update et sa propre fonction Storage). */
function uploadJustificatifBestEffort({ uploader, employeeId, recordId, file, patcher }) {
  if (!file) return;
  const company = companyRepository.getCurrent();
  // `file` est capturé ici, dans la valeur passée à l'appel — jamais relu depuis
  // state.pendingAttachmentFile une fois la promesse résolue (qui a pu changer d'ici là si
  // l'utilisateur a rouvert une autre modale d'upload).
  uploader(company.id, employeeId, recordId, file)
    .then(path => patcher({ nom: file.name, path }))
    .catch(err => {
      // §correctif revue de code du 23/08/2026 : l'échec était totalement muet. Le salarié joignait
      // son arrêt de travail, l'envoi échouait (réseau, refus RLS, fichier illisible), la demande
      // partait sans pièce et PERSONNE n'était prévenu — ni lui, ni le valideur, qui voyait
      // seulement "justificatif manquant" et refusait. Une demande sans justificatif reste
      // volontairement créée (la perdre serait pire), mais l'utilisateur doit savoir quoi refaire.
      console.error('Échec de l\'envoi du justificatif :', err);
      showToast('La demande est enregistrée, mais le justificatif n\'a pas pu être envoyé. Rouvrez la demande pour le joindre à nouveau.', 'error');
    });
}

function updateLeaveRequestHints() {
  const typeId = document.getElementById('f-typeId').value;
  const employeeId = document.getElementById('f-employeeId').value;
  const dateDebut = document.getElementById('f-dateDebut').value;
  const dateFin = document.getElementById('f-dateFin').value;
  const demiField = document.getElementById('field-demi-journee');
  const demiFieldMulti = document.getElementById('field-demi-journee-multi');
  const hint = document.getElementById('leave-balance-hint');

  const type = typeId ? leaveTypeRepository.getLeaveTypeById(typeId) : null;
  const monoJour = Boolean(dateDebut && dateDebut === dateFin);
  const multiJours = Boolean(dateDebut && dateFin && dateDebut !== dateFin);
  demiField.style.display = type && type.autoriserDemiJournee && monoJour ? 'block' : 'none';
  // §7.12 : le champ mono-jour ci-dessus et les deux champs début/fin ci-dessous sont mutuellement
  // exclusifs (une période ne peut pas être à la fois "un seul jour" et "plusieurs jours").
  demiFieldMulti.style.display = type && type.autoriserDemiJournee && multiJours ? 'grid' : 'none';
  const arretField = document.getElementById('field-arret-travail');
  if (arretField) arretField.style.display = isArretTravailType(type) ? 'grid' : 'none';

  if (!type || !employeeId) { hint.textContent = ''; return; }
  const employee = employeeRepository.getById(employeeId);
  const balance = getLeaveBalance(employee, type, leaveRepository.getAll());
  const disponibleLabel = balance.disponible === Infinity ? 'illimité' : formatDurationFR(balance.disponible);

  // §correctif audit du 23/08/2026 (§7.11) : l'aide à la saisie n'affichait que le solde DU JOUR,
  // alors que l'acquisition continue jusqu'à la date de départ demandée — un salarié qui pose un
  // congé dans 2 mois voit un solde qui sous-estime ce qu'il aura RÉELLEMENT ce jour-là. Affiché
  // seulement si la date de début est dans le futur (sinon identique au solde du jour, aucune
  // valeur ajoutée à le répéter).
  let projeteLabel = '';
  if (dateDebut && dateDebut > toISODate(new Date()) && balance.disponible !== Infinity) {
    const balanceProjetee = getLeaveBalance(employee, type, leaveRepository.getAll(), null, dateDebut);
    if (balanceProjetee.disponible !== balance.disponible) {
      projeteLabel = ` (${formatDurationFR(balanceProjetee.disponible)} projeté au ${formatDate(dateDebut)})`;
    }
  }

  let nbJoursLabel = '';
  if (dateDebut && dateFin) {
    const demiJournee = demiField.style.display === 'block' ? document.getElementById('f-demiJournee').value : '';
    const demiJourneeDebut = demiFieldMulti.style.display === 'grid' ? document.getElementById('f-demiJourneeDebut').value : '';
    const demiJourneeFin = demiFieldMulti.style.display === 'grid' ? document.getElementById('f-demiJourneeFin').value : '';
    const nbJours = computeWorkingDays(dateDebut, dateFin, Boolean(demiJournee), employee, settingsRepository.getSettings(), type.uniteDecompte, demiJourneeDebut, demiJourneeFin);
    nbJoursLabel = ` · ${formatDurationFR(nbJours)} décomptés pour cette demande`;
  }

  // §correctif audit du 23/08/2026 (§7.8) : délai de prévenance — avertit systématiquement dans
  // l'aide à la saisie (utile même en mode "alerte", pas seulement "blocage") dès que la date de
  // début est connue et insuffisamment éloignée d'aujourd'hui.
  let delaiWarning = '';
  if (dateDebut && type.delaiPrevenanceJours) {
    const joursRestants = Math.round((parseISODateLocal(dateDebut) - parseISODateLocal(toISODate(new Date()))) / 86400000);
    if (joursRestants < type.delaiPrevenanceJours) {
      delaiWarning = ` · ⚠ Délai de prévenance de ${type.delaiPrevenanceJours} jour${type.delaiPrevenanceJours > 1 ? 's' : ''} non respecté${type.delaiPrevenanceMode === 'blocage' ? ' (bloquant pour ce type)' : ''}`;
    }
  }

  // §correctif audit du 23/08/2026 (§7.6) : quota d'absences simultanées — avertit (jamais ne
  // bloque, l'audit ne le demande pas ici) si accepter cette demande porterait le nombre de
  // salariés absents un jour donné du même périmètre à ou au-delà du maximum configuré. Une seule
  // journée suffit à déclencher l'alerte, pas la peine de lister tous les jours en conflit.
  let quotaWarning = '';
  if (dateDebut && dateFin) {
    const settings = settingsRepository.getSettings();
    const quotas = getQuotasForEmployee(employee, settings);
    for (const quota of quotas) {
      const cursor = parseISODateLocal(dateDebut);
      const end = parseISODateLocal(dateFin);
      while (cursor <= end) {
        const dateStr = toISODate(cursor);
        // §retour Betty du 14/09/2026 (Congés, "vue de l'équipe au moment de poser") : nommer QUI
        // est déjà absent ce jour-là, pas seulement dire que le quota est atteint — la personne qui
        // pose sa demande sait tout de suite si elle peut se coordonner avec un collègue plutôt que
        // de devoir aller chercher l'information ailleurs.
        const dejaAbsents = getAbsentsForQuota(quota, dateStr, employee.id);
        if (dejaAbsents.length + 1 >= quota.maxSimultane) {
          const noms = dejaAbsents.map(e => `${e.prenom} ${e.nom}`).join(', ');
          quotaWarning = ` · ⚠ Quota « ${quota.nom} » atteint le ${formatDate(dateStr)} (max ${quota.maxSimultane} absent${quota.maxSimultane > 1 ? 's' : ''} simultané${quota.maxSimultane > 1 ? 's' : ''}${noms ? ` : déjà absent${dejaAbsents.length > 1 ? 's' : ''} ce jour-là — ${noms}` : ''})`;
          break;
        }
        cursor.setDate(cursor.getDate() + 1);
      }
      if (quotaWarning) break;
    }
  }

  hint.textContent = `Solde disponible : ${disponibleLabel}${projeteLabel}${nbJoursLabel}${type.justificatifObligatoire ? ' · Justificatif obligatoire pour ce type' : ''}${delaiWarning}${quotaWarning}`;
}

async function submitLeaveRequestForm(evt) {
  evt.preventDefault();
  const form = evt.target;
  const formData = new FormData(form);
  const employeeId = formData.get('employeeId');
  const typeId = formData.get('typeId');
  const dateDebut = formData.get('dateDebut');
  const dateFin = formData.get('dateFin');
  const demiJournee = document.getElementById('field-demi-journee').style.display === 'block' ? (formData.get('demiJournee') || null) : null;
  const demiJourneeMultiActive = document.getElementById('field-demi-journee-multi').style.display === 'grid';
  const demiJourneeDebut = demiJourneeMultiActive ? (formData.get('demiJourneeDebut') || null) : null;
  const demiJourneeFin = demiJourneeMultiActive ? (formData.get('demiJourneeFin') || null) : null;

  if (!employeeId || !typeId) {
    showToast('Sélectionnez un salarié et un type de congé.', 'error');
    return;
  }

  if (dateDebut && dateFin && dateFin < dateDebut) {
    showToast('La date de fin ne peut pas être avant la date de début.', 'error');
    return;
  }

  // Sprint SIRH premium §1 : "Seuls RH/Manager/Propriétaire peuvent créer une absence dans le passé
  // [...] Les salariés ne peuvent jamais modifier une période antérieure à aujourd'hui." — la
  // création couvre aussi la saisie initiale, pas seulement la modification d'une demande existante
  // (déjà couverte par canManageRequestFor, qui exclut systématiquement le demandeur lui-même).
  if (authRepository.getCurrentUser().role === ROLES.SALARIE && dateDebut < toISODate(new Date())) {
    showToast('Vous ne pouvez pas saisir une absence dont la date de début est déjà passée.', 'error');
    return;
  }

  const employee = employeeRepository.getById(employeeId);
  const type = leaveTypeRepository.getLeaveTypeById(typeId);

  // §retour Betty du 18/09/2026 (point 8) : miroir client de has_module_license (0059), qui reste
  // le vrai verrou côté serveur (policy leave_requests_insert) — ce contrôle évite seulement une
  // erreur brute au moment de l'enregistrement, jamais un contournement possible depuis ici.
  if (!hasModuleLicense(employee, 'conges')) {
    showToast(`${employee.prenom} ${employee.nom} n'a pas d'accès au module Congés : demandez à un Propriétaire/RH de lui attribuer une licence (Paramètres > Abonnement > Gérer les accès).`, 'error');
    return;
  }

  // §correctif audit du 23/08/2026 (§7.8) : délai de prévenance en mode "blocage" — en mode
  // "alerte", updateLeaveRequestHints a déjà prévenu au moment de la saisie, la demande part quand
  // même (c'est tout le sens de la distinction entre les deux modes).
  if (dateDebut && type.delaiPrevenanceJours && type.delaiPrevenanceMode === 'blocage') {
    const joursRestants = Math.round((parseISODateLocal(dateDebut) - parseISODateLocal(toISODate(new Date()))) / 86400000);
    if (joursRestants < type.delaiPrevenanceJours) {
      showToast(`Ce type de congé exige un délai de prévenance de ${type.delaiPrevenanceJours} jour${type.delaiPrevenanceJours > 1 ? 's' : ''} minimum.`, 'error');
      return;
    }
  }

  // §15/§24 : ne fait pas confiance au seul filtrage du menu déroulant (contournable en modifiant
  // le DOM) — revérifie ici que l'utilisateur courant a le droit de saisir ce type restreint.
  if (!type.saisiParSalarie && !hasPermission(authRepository.getCurrentUser(), PERMISSIONS.SAISIR_MALADIE)) {
    showToast(`La saisie du type « ${type.nom} » est réservée aux RH.`, 'error');
    return;
  }

  // Sprint SIRH premium §1 : même principe — ne fait pas confiance au seul filtrage du menu
  // déroulant pour la liste blanche de types autorisés par salarié.
  const currentUser = authRepository.getCurrentUser();
  if (currentUser.role === ROLES.SALARIE && (currentUser.typesAbsenceDesactives || []).includes(typeId)) {
    showToast(`Le type « ${type.nom} » n'est pas autorisé pour votre profil.`, 'error');
    return;
  }

  // §3 sprint amélioration : règles d'éligibilité (ancienneté, catégorie de salarié, établissement,
  // type de contrat) — même principe défensif, ne fait pas confiance au seul filtrage de la liste
  // proposée dans le formulaire (qui ne connaît le salarié cible qu'en libre-service).
  if (!isLeaveTypeEligibleForEmployee(employee, type, categorieSalarieRepository.getAll())) {
    showToast(`« ${type.nom} » n'est pas disponible pour ce salarié (règles d'éligibilité du type).`, 'error');
    return;
  }

  // Une demande hors de la période d'emploi fausserait le solde : calculateAcquisition borne déjà
  // l'acquisition à [dateEmbauche, dateDepart], mais getLeaveBalance somme TOUTES les demandes
  // Validé/En attente sans cette même borne — un congé avant l'embauche (ou après le départ) se
  // déduirait d'un solde qui n'a jamais pu l'acquérir.
  if (employee.dateEmbauche && dateDebut < employee.dateEmbauche) {
    showToast(`La date de début ne peut pas être avant la date d'embauche (${formatDate(employee.dateEmbauche)}).`, 'error');
    return;
  }
  if (employee.dateDepart && dateFin > employee.dateDepart) {
    showToast(`La date de fin ne peut pas être après la date de départ (${formatDate(employee.dateDepart)}).`, 'error');
    return;
  }

  const nbJours = computeWorkingDays(dateDebut, dateFin, Boolean(demiJournee), employee, settingsRepository.getSettings(), type.uniteDecompte, demiJourneeDebut, demiJourneeFin);

  if (nbJours <= 0) {
    showToast('La période sélectionnée ne comporte aucun jour travaillé.', 'error');
    return;
  }

  if (type.justificatifObligatoire && !state.pendingAttachment) {
    showToast('Un justificatif est requis pour ce type de congé.', 'error');
    return;
  }

  if (!type.autoriserPlusieursDemandes) {
    const bothSingleDay = dateDebut === dateFin;
    const overlapping = leaveRepository.getAll().some(r => {
      if (r.employeeId !== employeeId || r.typeId !== typeId) return false;
      if (r.statut === 'Refusé' || r.statut === 'Annulé') return false;
      if (!(r.dateDebut <= dateFin && r.dateFin >= dateDebut)) return false;
      // Même exception que hasConflictingLeaveRequest : deux demi-journées complémentaires (matin +
      // après-midi) d'une même date isolée ne sont pas un vrai chevauchement.
      const sameSingleDay = bothSingleDay && r.dateDebut === r.dateFin;
      if (!sameSingleDay) return true;
      if (!demiJournee || !r.demiJournee) return true;
      return demiJournee === r.demiJournee;
    });
    if (overlapping) {
      showToast(`Une demande "${type.nom}" existe déjà sur une période qui chevauche ces dates.`, 'error');
      return;
    }
  }

  // On ne peut pas être sur deux congés/absences de TYPES DIFFÉRENTS en même temps (ex. RTT et congés
  // payés le même jour) — sauf demi-journées complémentaires, gérées par hasConflictingLeaveRequest.
  if (hasConflictingLeaveRequest(employeeId, typeId, dateDebut, dateFin, demiJournee)) {
    showToast('Ce salarié a déjà une autre demande de congé/absence active sur cette période.', 'error');
    return;
  }

  if (hasActiveRequestOverlap(teleworkRepository.getAll(), employeeId, dateDebut, dateFin)) {
    showToast('Ce salarié a déjà une demande de télétravail active sur cette période.', 'error');
    return;
  }

  // §correctif audit du 01/09/2026 : au-delà de ce point, plus aucune validation ne peut faire
  // échouer l'envoi (voir plus bas, toujours suivi de closeModal()) — désactiver seulement ici,
  // jamais plus tôt, pour ne jamais bloquer le bouton après un simple message d'erreur de saisie
  // (ex. "Sélectionnez un salarié...") qui laisse l'utilisateur corriger et renvoyer. Sans ce
  // garde-fou, un double-clic (ou un Entrée qui se déclenche deux fois) pendant l'appel réseau de
  // resolveWorkflowWithFallback créait deux demandes identiques.
  // §retour Betty du 11/09/2026 (point 4.1) : lu depuis le champ réel (jamais formData.get(), qui
  // renverrait une valeur même si field-arret-travail est masqué pour un type non concerné) — même
  // garde-fou défensif que demiJournee/demiJourneeDebut/demiJourneeFin ci-dessus.
  const arretTravail = isArretTravailType(type)
    ? { typeArret: formData.get('typeArret') || 'maladie', subrogation: document.getElementById('f-subrogation').checked }
    : null;

  const submitBtn = evt.target.querySelector('button[type="submit"]');
  if (submitBtn) submitBtn.disabled = true;
  const createdRequest = await leaveRepository.create({
    employeeId, typeId, dateDebut, dateFin, demiJournee, demiJourneeDebut, demiJourneeFin, nbJours,
    commentaire: formData.get('commentaire') || '',
    justificatif: state.pendingAttachment,
    arretTravail
  });

  uploadJustificatifBestEffort({
    uploader: window.SupabaseSync.uploadJustificatifFile,
    employeeId, recordId: createdRequest.id, file: state.pendingAttachmentFile,
    patcher: (justificatif) => leaveRepository.update(createdRequest.id, { justificatif })
  });

  finalizeDraftEdit();
  showToast('Demande envoyée.');
  // §correctif audit du 23/08/2026 (2.3) : la chaîne de validation a dû être réajustée (aucun
  // validateur "naturel" — ex. un autre manager désigné comme son supérieur — n'existe pour cette
  // demande) ; RH/Direction devra intervenir manuellement, mieux vaut le dire tout de suite plutôt
  // que de laisser une demande dormir sans personne pour la remarquer.
  if (createdRequest.workflowEscalated) {
    showToast('Aucun validateur direct n\'a été trouvé pour cette demande : un RH ou un membre de la Direction devra la valider manuellement.', 'error');
  }
  closeModal();
  // Ouverte depuis un clic sur le calendrier (§sprint calendrier interactif) : on y retourne au lieu
  // de filer vers la liste des demandes, pour que l'utilisateur voie tout de suite son jour rempli.
  if (state._leaveRequestReturnToCalendar) {
    state._leaveRequestReturnToCalendar = false;
    navigateTo('calendrier');
  } else if (type.categorie === 'conge') navigateTo('absences', { absencesHubTab: 'conges', congesTab: 'demandes' });
  else navigateTo('absences', { absencesHubTab: 'autres', congesTab: 'demandes' });
}

// ---- Sous-vue : Types de congés ----

function renderCongesTypes(categorie = 'conge') {
  const types = leaveTypeRepository.getLeaveTypes().filter(t => t.categorie === categorie);
  const noun = categorie === 'conge' ? 'de congé' : 'd\'absence';
  const plural = types.length > 1 ? 's' : '';

  return `
    <div class="view-header-row">
      <p class="view-subtitle">${types.length} type${plural} ${noun} configuré${plural}</p>
      <div class="detail-header-actions">
        <!-- §retour Betty du 18/09/2026 (point 5) : déplacé depuis l'écran Congés & absences —
             une opération de mise en service (à la création des types), pas un usage quotidien. -->
        <button class="btn btn-secondary btn-sm" id="btn-import-absences-historique">Importer l'historique</button>
        <button class="btn btn-primary btn-sm" id="btn-new-leave-type">+ Nouveau type</button>
      </div>
    </div>
    <div class="card table-card">
      <table class="table">
        <thead>
          <tr>
            <th>Type</th>
            <th>Acquisition</th>
            <th>Rémunération</th>
            <th>Validation</th>
            <th>Statut</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          ${types.map(renderLeaveTypeRow).join('')}
        </tbody>
      </table>
    </div>
  `;
}

/** Décrit une chaîne de workflow pour affichage, ex. ['manager','rh'] → "Manager puis RH". */
function describeWorkflow(workflow, overrides) {
  if (!workflow || workflow.length === 0) return 'Automatique';
  const ov = overrides || {};
  return workflow.map((role, i) => {
    const overrideIds = ov[String(i)];
    if (!Array.isArray(overrideIds) || !overrideIds.length) return ROLE_LABELS[role] || role;
    const names = overrideIds.map(eid => {
      const e = employeeRepository.getById(eid);
      return e ? `${e.prenom} ${e.nom}` : null;
    }).filter(Boolean);
    // §retour QA du 26/08/2026 (point 6.7) : signale qu'une étape n'est plus résolue par rôle —
    // sans ce libellé, un RH voit "Manager puis RH" sans se rendre compte que "Manager" a en
    // réalité été remplacé par une personne nommée précise.
    return names.length ? `${names.join(', ')} (nommé${names.length > 1 ? 's' : ''})` : ROLE_LABELS[role] || role;
  }).join(' puis ');
}

// Chaînes de validation proposées (ordre = ordre d'approbation). Un menu à préréglages plutôt
// qu'une sélection multiple : l'ORDRE des rôles est essentiel et une simple multi-sélection
// ne le garantirait pas.
const WORKFLOW_PRESETS_CONGES = [
  { value: '[]', label: 'Aucune validation requise' },
  { value: '["manager"]', label: 'Manager uniquement' },
  { value: '["rh"]', label: 'RH uniquement' },
  { value: '["manager","rh"]', label: 'Manager puis RH' },
  { value: '["manager","proprietaire"]', label: 'Manager puis Propriétaire' },
  { value: '["proprietaire"]', label: 'Propriétaire uniquement' }
];

const WORKFLOW_PRESETS_FRAIS = [
  { value: '[]', label: 'Aucune validation requise' },
  { value: '["manager"]', label: 'Manager uniquement' },
  { value: '["comptabilite"]', label: 'Comptabilité uniquement' },
  { value: '["manager","comptabilite"]', label: 'Manager puis Comptabilité' },
  { value: '["manager","proprietaire"]', label: 'Manager puis Propriétaire' }
];

function workflowSelectField(name, label, presets, currentWorkflow) {
  const currentValue = JSON.stringify(currentWorkflow || []);
  return `
    <div class="form-field">
      <label for="f-${name}">${escapeHtml(label)}</label>
      <select class="input" id="f-${name}" name="${name}">
        ${presets.map(p => `<option value='${p.value}' ${p.value === currentValue ? 'selected' : ''}>${escapeHtml(p.label)}</option>`).join('')}
      </select>
    </div>
  `;
}

function renderLeaveTypeRow(t) {
  const validationLabel = describeWorkflow(t.workflow, t.workflowValidatorOverrides);
  const acquisitionLabel = t.illimite ? 'Illimitée' : `${t.acquisition} · ${formatDurationFR(t.nombreAnnuel)}/an`;

  return `
    <tr>
      <td>
        <span class="type-swatch" style="background:${escapeHtml(t.couleur)}"></span>
        ${escapeHtml(t.icone)} <strong>${escapeHtml(t.nom)}</strong>
      </td>
      <td>${escapeHtml(acquisitionLabel)}</td>
      <td><span class="badge badge-${t.paye ? 'success' : 'muted'}">${t.paye ? 'Payé' : 'Non payé'}</span></td>
      <td>${escapeHtml(validationLabel)}</td>
      <td><span class="badge badge-${t.actif ? 'success' : 'muted'}">${t.actif ? 'Actif' : 'Inactif'}</span></td>
      <td class="table-actions">
        <button class="btn-link" data-reorder-up="${t.id}" title="Monter">↑</button>
        <button class="btn-link" data-reorder-down="${t.id}" title="Descendre">↓</button>
        <button class="btn-link" data-edit-type="${t.id}">Modifier</button>
        <button class="btn-link" data-duplicate-type="${t.id}">Dupliquer</button>
        <button class="btn-link" data-toggle-type="${t.id}">${t.actif ? 'Désactiver' : 'Activer'}</button>
        <button class="btn-link btn-link-danger" data-delete-type="${t.id}">Supprimer</button>
      </td>
    </tr>
  `;
}

function bindCongesTypesEvents(categorie = 'conge') {
  document.getElementById('btn-new-leave-type').addEventListener('click', () => openLeaveTypeModal(null, categorie));
  document.getElementById('btn-import-absences-historique').addEventListener('click', () => openImportAbsencesHistoriqueModal(categorie));

  document.querySelectorAll('[data-edit-type]').forEach(btn => btn.addEventListener('click', () => openLeaveTypeModal(btn.dataset.editType)));
  document.querySelectorAll('[data-duplicate-type]').forEach(btn => btn.addEventListener('click', () => {
    leaveTypeRepository.duplicateLeaveType(btn.dataset.duplicateType);
    showToast('Type de congé dupliqué.');
    render();
  }));
  document.querySelectorAll('[data-toggle-type]').forEach(btn => btn.addEventListener('click', () => {
    const t = leaveTypeRepository.getLeaveTypeById(btn.dataset.toggleType);
    leaveTypeRepository.updateLeaveType(t.id, { actif: !t.actif });
    render();
  }));
  document.querySelectorAll('[data-reorder-up]').forEach(btn => btn.addEventListener('click', () => {
    leaveTypeRepository.reorderLeaveType(btn.dataset.reorderUp, 'up');
    render();
  }));
  document.querySelectorAll('[data-reorder-down]').forEach(btn => btn.addEventListener('click', () => {
    leaveTypeRepository.reorderLeaveType(btn.dataset.reorderDown, 'down');
    render();
  }));
  document.querySelectorAll('[data-delete-type]').forEach(btn => btn.addEventListener('click', () => {
    const t = leaveTypeRepository.getLeaveTypeById(btn.dataset.deleteType);
    openConfirm({
      title: 'Supprimer ce type de congé ?',
      message: `"${t.nom}" et toutes ses demandes associées seront définitivement supprimés.`,
      confirmLabel: 'Supprimer',
      danger: true,
      onConfirm: () => {
        leaveTypeRepository.deleteLeaveType(t.id);
        showToast('Type de congé supprimé.');
        render();
      }
    });
  }));
}

// ---- Modale : Type de congé (création / édition) ----

function openLeaveTypeModal(id, categorie = 'conge') {
  const isEdit = Boolean(id);
  const type = isEdit ? leaveTypeRepository.getLeaveTypeById(id) : Object.assign(makeEmptyLeaveType(), { workflow: settingsRepository.getSettings().workflowCongesDefault, categorie });
  // En édition, la catégorie du type lui-même fait foi plutôt que le paramètre reçu — l'appelant
  // (bouton "Modifier") ne le passait pas toujours correctement, ce qui renvoyait vers le mauvais
  // écran ("Congés" au lieu d'"Autres absences") après enregistrement. Ne dépend plus du contexte
  // d'ouverture, seulement de la donnée réelle du type.
  const effectiveCategorie = isEdit ? type.categorie : categorie;

  // §3 sprint amélioration : liste des AUTRES types actifs, pour "Partager le compteur avec" —
  // jamais soi-même (un type ne peut pas partager son propre compteur).
  const autresTypes = leaveTypeRepository.getLeaveTypes().filter(t => t.id !== id);
  // État de travail des règles d'éligibilité, modifié en mémoire tant que la modale reste ouverte
  // (ajout/suppression de ligne) — re-rendu seulement dans son propre conteneur (#regles-rows), pas
  // toute la modale, pour ne jamais perdre les autres champs déjà saisis par l'utilisateur.
  let currentRegles = (type.regles || []).map(r => ({ ...r }));
  let currentPaliers = (type.paliersAnciennete || []).map(p => ({ ...p }));
  const [clotureMoisInit, clotureJourInit] = (type.dateClotureCompteur || '').split('-').map(Number);
  const [limiteReportMoisInit, limiteReportJourInit] = (type.dateLimiteReportMMJJ || '').split('-').map(Number);

  const html = `
    <div class="modal modal-large">
      <div class="modal-header">
        <h2>${isEdit ? 'Modifier le type de congé' : 'Nouveau type de congé'}</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="leave-type-form">
        <div class="modal-body">
          <fieldset class="form-section">
            <legend>Informations générales</legend>
            <div class="form-grid">
              ${textField('nom', 'Nom', type.nom, true)}
              ${textField('icone', 'Icône (emoji)', type.icone)}
              <div class="form-field">
                <label for="f-couleur">Couleur</label>
                <div style="display:flex; align-items:center; gap:8px;">
                  <input type="color" id="f-couleur" name="couleur" value="${escapeHtml(type.couleur)}" style="width:44px; height:36px; padding:2px; border:1px solid var(--color-border); border-radius:var(--radius-sm); cursor:pointer;">
                  <span id="couleur-preview-hex" class="text-muted" style="font-size:13px;">${escapeHtml(type.couleur)}</span>
                </div>
              </div>
              ${checkboxField('actif', 'Type actif', type.actif)}
            </div>
            <div class="form-field" style="margin-top:14px;">
              <label for="f-description">Description</label>
              <textarea class="input" id="f-description" name="description" rows="2">${escapeHtml(type.description)}</textarea>
            </div>
          </fieldset>

          <fieldset class="form-section">
            <legend>Acquisition des droits</legend>
            <div class="form-grid">
              ${selectField('acquisition', 'Mode d\'acquisition', ['Mensuelle', 'Annuelle', 'Illimitée'], type.acquisition)}
              <div class="form-field" id="field-nombre-annuel">
                <label for="f-nombreAnnuel" id="label-nombre-annuel">Nombre de jours par an</label>
                <input class="input" type="number" step="any" id="f-nombreAnnuel" name="nombreAnnuel" value="${escapeHtml(type.nombreAnnuel)}">
              </div>
              <div class="form-field">
                <label for="f-uniteDecompte">Unité de décompte</label>
                <select class="input" id="f-uniteDecompte" name="uniteDecompte">
                  <option value="ouvres" ${type.uniteDecompte !== 'ouvrables' ? 'selected' : ''}>Jours ouvrés (rythme réel du salarié)</option>
                  <option value="ouvrables" ${type.uniteDecompte === 'ouvrables' ? 'selected' : ''}>Jours ouvrables (tous les jours sauf dimanche)</option>
                </select>
                <p class="form-hint">Le Code du travail exprime les congés payés en jours ouvrables (30) ; la plupart des conventions comptent en jours ouvrés (25).</p>
              </div>
              <div class="form-field">
                <label for="f-proratisationTempsPartiel">Effet du temps partiel sur l'acquisition</label>
                <select class="input" id="f-proratisationTempsPartiel" name="proratisationTempsPartiel">
                  <option value="proportionnelle" ${resolveProratisationTempsPartiel(type) === 'proportionnelle' ? 'selected' : ''}>Réduite au pourcentage d'activité</option>
                  <option value="aucune" ${resolveProratisationTempsPartiel(type) === 'aucune' ? 'selected' : ''}>Jamais réduite (ex. congés payés)</option>
                  <option value="exclu" ${resolveProratisationTempsPartiel(type) === 'exclu' ? 'selected' : ''}>Nulle pour un temps partiel (ex. RTT)</option>
                </select>
                <p class="form-hint">Confirmé par votre expert-comptable pour Congés payés (jamais réduite) et RTT (nulle) — à vérifier avant de changer ce réglage pour un autre type.</p>
              </div>
              <div class="form-field form-field-checkbox" style="justify-content: flex-end;">
                <label><input type="checkbox" id="f-suspendAcquisitionAutresCompteurs" ${type.suspendAcquisitionAutresCompteurs ? 'checked' : ''}> Une absence validée de CE type suspend l'acquisition des autres compteurs (ex. CP)</label>
                <p class="form-hint">Ex. congé sabbatique. Décoché par défaut pour tous les types (y compris déjà existants) — votre expert-comptable n'a pas donné de liste type par type, à cocher au cas par cas selon ses réponses.</p>
              </div>
            </div>
            <div class="form-field" style="margin-top:14px;">
              <label>Paliers d'ancienneté (optionnel)</label>
              <p class="form-hint">Remplace "Nombre de jours par an" ci-dessus par le palier le plus haut atteint (non cumulatif) — évite de créer un type par tranche d'ancienneté.</p>
              <div id="paliers-anciennete-rows"></div>
              <button type="button" class="btn btn-secondary btn-sm" id="btn-add-palier" style="margin-top:8px;">+ Ajouter un palier</button>
            </div>
            <div class="form-grid" style="margin-top:14px;">
              <div class="form-field">
                <label>Clôture du compteur (optionnel)</label>
                <div style="display:flex; gap:8px;">
                  <select class="input" id="f-cloture-mois" style="flex:1;">
                    <option value="">Jamais (une seule période continue)</option>
                    ${MONTH_NAMES.map((m, i) => `<option value="${i + 1}" ${clotureMoisInit === i + 1 ? 'selected' : ''}>${m}</option>`).join('')}
                  </select>
                  <input class="input" type="number" id="f-cloture-jour" min="1" max="31" placeholder="Jour" value="${clotureJourInit || ''}" style="flex:0 0 80px;">
                </div>
                <p class="form-hint">Ex. mai / 31 pour un compteur CP calé sur l'année de référence française.</p>
              </div>
              <div class="form-field" id="field-report" style="display:${type.dateClotureCompteur ? 'flex' : 'none'};">
                <label for="f-reportCompteur">Report des jours non pris à la clôture</label>
                <select class="input" id="f-reportCompteur" name="reportCompteur">
                  <option value="aucun" ${type.reportCompteur === 'aucun' ? 'selected' : ''}>Aucun report (perdus)</option>
                  <option value="limite" ${type.reportCompteur === 'limite' ? 'selected' : ''}>Report plafonné</option>
                  <option value="illimite" ${type.reportCompteur === 'illimite' ? 'selected' : ''}>Report intégral</option>
                </select>
              </div>
              <div class="form-field" id="field-report-limite" style="display:${type.reportCompteur === 'limite' ? 'flex' : 'none'};">
                <label for="f-reportLimiteJours">Plafond de report (jours)</label>
                <input class="input" type="number" step="any" min="0" id="f-reportLimiteJours" name="reportLimiteJours" value="${escapeHtml(type.reportLimiteJours || '')}">
              </div>
              <div class="form-field" id="field-report-echeance" style="display:${type.reportCompteur !== 'aucun' ? 'flex' : 'none'};">
                <label>Date limite pour consommer le report (optionnel)</label>
                <div style="display:flex; gap:8px;">
                  <select class="input" id="f-limite-report-mois" style="flex:1;">
                    <option value="">Aucune échéance (report utilisable toute la période)</option>
                    ${MONTH_NAMES.map((m, i) => `<option value="${i + 1}" ${limiteReportMoisInit === i + 1 ? 'selected' : ''}>${m}</option>`).join('')}
                  </select>
                  <input class="input" type="number" id="f-limite-report-jour" min="1" max="31" placeholder="Jour" value="${limiteReportJourInit || ''}" style="flex:0 0 80px;">
                </div>
                <p class="form-hint">Passé cette date, la part du report pas encore consommée est perdue.</p>
              </div>
              <div class="form-field" id="field-fractionnement" style="display:${type.dateClotureCompteur ? 'flex' : 'none'};">
                <label style="display:flex; align-items:center; gap:8px; font-weight:400;">
                  <input type="checkbox" id="f-fractionnementActif" ${type.fractionnementActif ? 'checked' : ''}>
                  Jours de fractionnement
                </label>
                <p class="form-hint">Règle supplétive française : +1 jour si 3 à 5 jours de congé sont pris hors du 1er mai-31 octobre (période précédente), +2 jours si 6 ou plus. Beaucoup d'accords l'écartent. Désactivé par défaut.</p>
              </div>
            </div>
          </fieldset>

          <fieldset class="form-section">
            <legend>Chaîne de validation</legend>
            <div class="form-grid">
              ${workflowSelectField('workflow', 'Validation requise', WORKFLOW_PRESETS_CONGES, type.workflow)}
            </div>
            <!-- §retour QA du 26/08/2026 (point 6.7) : valideurs nommés, par étape — remplace la
                 résolution par rôle pour l'étape concernée quand au moins un salarié est sélectionné. -->
            <div id="workflow-overrides-container"></div>
          </fieldset>

          <fieldset class="form-section">
            <legend>Délai de prévenance (optionnel)</legend>
            <div class="form-grid">
              <div class="form-field">
                <label for="f-delaiPrevenanceJours">Nombre de jours minimum avant le départ</label>
                <input class="input" type="number" step="1" min="0" id="f-delaiPrevenanceJours" name="delaiPrevenanceJours" value="${escapeHtml(type.delaiPrevenanceJours || '')}" placeholder="Aucun délai">
              </div>
              <div class="form-field" id="field-delai-prevenance-mode" style="display:${type.delaiPrevenanceJours ? 'flex' : 'none'};">
                <label for="f-delaiPrevenanceMode">Si le délai n'est pas respecté</label>
                <select class="input" id="f-delaiPrevenanceMode" name="delaiPrevenanceMode">
                  <option value="alerte" ${type.delaiPrevenanceMode === 'alerte' ? 'selected' : ''}>Avertir, mais laisser envoyer</option>
                  <option value="blocage" ${type.delaiPrevenanceMode === 'blocage' ? 'selected' : ''}>Empêcher l'envoi</option>
                </select>
              </div>
            </div>
          </fieldset>

          <fieldset class="form-section">
            <legend>Règles</legend>
            <div class="form-grid checkbox-grid">
              ${checkboxField('paye', 'Congé payé', type.paye)}
              ${checkboxField('justificatifObligatoire', 'Justificatif obligatoire', type.justificatifObligatoire)}
              ${checkboxField('visibleSalarie', 'Visible par le salarié', type.visibleSalarie)}
              ${checkboxField('visibleRH', 'Visible par les RH', type.visibleRH)}
              ${checkboxField('saisiParSalarie', 'Le salarié peut créer lui-même une demande (§15)', type.saisiParSalarie)}
              ${checkboxField('autoriserDemiJournee', 'Autoriser la demi-journée', type.autoriserDemiJournee)}
              ${checkboxField('autoriserPlusieursDemandes', 'Autoriser plusieurs demandes simultanées', type.autoriserPlusieursDemandes)}
              ${checkboxField('exportPaie', 'Inclure dans l\'export paie', type.exportPaie)}
            </div>
            <div class="form-field" style="margin-top:14px;">
              ${selectField('compteurPartageAvecId', 'Partager le compteur avec (optionnel)', null, type.compteurPartageAvecId, autresTypes.map(t => ({ value: t.id, label: t.nom })))}
              <p class="form-hint">« — » = compteur propre à ce type (par défaut). Sinon, les demandes de CE type viennent en plus s'imputer sur le solde du type choisi (ex. un congé sans solde qui entame le compteur CP).</p>
            </div>
            <div class="form-field" style="margin-top:14px;">
              <label>Règles d'éligibilité (optionnel)</label>
              <p class="form-hint">Aucune règle = proposé à tous les salariés. Toutes les règles ajoutées doivent être vraies à la fois.</p>
              <div id="regles-rows"></div>
              <button type="button" class="btn btn-secondary btn-sm" id="btn-add-regle" style="margin-top:8px;">+ Ajouter une règle</button>
            </div>
          </fieldset>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="submit" class="btn btn-primary">${isEdit ? 'Enregistrer' : 'Créer le type'}</button>
        </div>
      </form>
    </div>
  `;

  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');

  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);

  // #1 : aperçu couleur en direct — pas de bouton de validation séparé (incohérent avec le reste du
  // formulaire, qui n'a qu'un seul bouton Enregistrer global) : juste un retour visuel immédiat.
  document.getElementById('f-couleur').addEventListener('input', (e) => {
    document.getElementById('couleur-preview-hex').textContent = e.target.value;
  });

  // #2 + #4 : libellé du nombre de jours adapté au mode, champ masqué entièrement si Illimitée
  // (aucun nombre ne doit être demandé dans ce cas).
  const updateAcquisitionUI = () => {
    const mode = document.getElementById('f-acquisition').value;
    const field = document.getElementById('field-nombre-annuel');
    const label = document.getElementById('label-nombre-annuel');
    if (mode === 'Illimitée' || currentPaliers.length) {
      field.style.display = 'none';
    } else {
      field.style.display = '';
      label.textContent = mode === 'Mensuelle' ? 'Nombre de jours par mois' : 'Nombre de jours par an';
    }
  };
  document.getElementById('f-acquisition').addEventListener('change', updateAcquisitionUI);
  updateAcquisitionUI();

  // §7.18 : mêmes principes que le constructeur de règles (#3 plus bas) — état local re-rendu dans
  // son propre conteneur, jamais toute la modale.
  function renderPaliersRows() {
    document.getElementById('paliers-anciennete-rows').innerHTML = currentPaliers.map((p, index) => `
      <div class="form-grid" style="grid-template-columns: 1fr 1fr auto; align-items:start; margin-top:8px;">
        <div style="display:flex; align-items:center; gap:6px;">
          <input class="input" type="number" min="0" step="any" data-palier-min="${index}" value="${escapeHtml(p.ancienneteMin ?? 0)}" placeholder="Ancienneté (ans)">
        </div>
        <div style="display:flex; align-items:center; gap:6px;">
          <input class="input" type="number" min="0" step="any" data-palier-jours="${index}" value="${escapeHtml(p.jours ?? 0)}" placeholder="Jours accordés">
        </div>
        <button type="button" class="btn-icon" data-remove-palier="${index}" aria-label="Retirer" title="Retirer">${icon(ICONS.close, 12)}</button>
      </div>
    `).join('');
    document.querySelectorAll('[data-palier-min]').forEach(el => el.addEventListener('change', (e) => {
      currentPaliers[Number(e.target.dataset.palierMin)].ancienneteMin = Number(e.target.value) || 0;
    }));
    document.querySelectorAll('[data-palier-jours]').forEach(el => el.addEventListener('change', (e) => {
      currentPaliers[Number(e.target.dataset.palierJours)].jours = Number(e.target.value) || 0;
    }));
    document.querySelectorAll('[data-remove-palier]').forEach(btn => btn.addEventListener('click', () => {
      currentPaliers.splice(Number(btn.dataset.removePalier), 1);
      renderPaliersRows();
      updateAcquisitionUI();
    }));
  }
  document.getElementById('btn-add-palier').addEventListener('click', () => {
    currentPaliers.push({ ancienneteMin: 0, jours: 0 });
    renderPaliersRows();
    updateAcquisitionUI();
  });
  renderPaliersRows();

  // #5 : le champ de report n'a de sens que si une clôture est définie ; le plafond n'a de sens que
  // si le report est "limite".
  const updateClotureUI = () => {
    const hasCloture = Boolean(document.getElementById('f-cloture-mois').value);
    document.getElementById('field-report').style.display = hasCloture ? 'flex' : 'none';
    document.getElementById('field-fractionnement').style.display = hasCloture ? 'flex' : 'none';
  };
  document.getElementById('f-cloture-mois').addEventListener('change', updateClotureUI);
  document.getElementById('f-reportCompteur').addEventListener('change', (e) => {
    document.getElementById('field-report-limite').style.display = e.target.value === 'limite' ? 'flex' : 'none';
    document.getElementById('field-report-echeance').style.display = e.target.value !== 'aucun' ? 'flex' : 'none';
  });
  document.getElementById('f-delaiPrevenanceJours').addEventListener('input', (e) => {
    document.getElementById('field-delai-prevenance-mode').style.display = e.target.value ? 'flex' : 'none';
  });

  // #3 : constructeur de règles générique — un critère du catalogue RULE_CRITERIA par ligne, avec
  // son opérateur et sa valeur (nombre, ou multi-sélection selon le type de critère). Re-rendu
  // localement (pas toute la modale) à chaque ajout/suppression pour préserver le reste du formulaire.
  const categoriesSalarieOptions = categorieSalarieRepository.getAll();
  const etablissementsOptions = etablissementRepository.getAll();
  function renderRegleValueInput(regle, index) {
    const criterion = RULE_CRITERIA[regle.critere];
    if (criterion.valueType === 'number') {
      return `<input class="input" type="number" step="any" data-regle-valeur="${index}" value="${escapeHtml(regle.valeur ?? '')}" style="flex:1;">`;
    }
    const options = criterion.valueType === 'categorieSalarie' ? categoriesSalarieOptions.map(c => ({ value: c.id, label: c.nom }))
      : criterion.valueType === 'etablissement' ? etablissementsOptions.map(e => ({ value: e.id, label: e.nom }))
      : settingsRepository.getSettings().typesContrat.map(v => ({ value: v, label: v }));
    const selected = new Set(regle.valeur || []);
    return `<select class="input" multiple data-regle-valeur="${index}" style="flex:1; min-height:70px;">
      ${options.map(o => `<option value="${escapeHtml(o.value)}" ${selected.has(o.value) ? 'selected' : ''}>${escapeHtml(o.label)}</option>`).join('')}
    </select>`;
  }
  function renderReglesRows() {
    document.getElementById('regles-rows').innerHTML = currentRegles.map((regle, index) => `
      <div class="form-grid" style="grid-template-columns: 1.2fr 0.8fr 1.4fr auto; align-items:start; margin-top:8px;" data-regle-row="${index}">
        <select class="input" data-regle-critere="${index}">
          ${Object.entries(RULE_CRITERIA).map(([key, c]) => `<option value="${key}" ${regle.critere === key ? 'selected' : ''}>${escapeHtml(c.label)}</option>`).join('')}
        </select>
        <select class="input" data-regle-operateur="${index}">
          ${RULE_CRITERIA[regle.critere].operators.map(op => `<option value="${op}" ${regle.operateur === op ? 'selected' : ''}>${op === '>=' ? 'au moins' : op === '<=' ? 'au plus' : 'parmi'}</option>`).join('')}
        </select>
        ${renderRegleValueInput(regle, index)}
        <button type="button" class="btn-icon" data-remove-regle="${index}" aria-label="Retirer" title="Retirer">${icon(ICONS.close, 12)}</button>
      </div>
    `).join('');
    bindReglesRowEvents();
  }
  function readCurrentRegleValue(index) {
    const regle = currentRegles[index];
    const criterion = RULE_CRITERIA[regle.critere];
    const el = document.querySelector(`[data-regle-valeur="${index}"]`);
    if (!el) return regle.valeur;
    return criterion.valueType === 'number' ? Number(el.value) || 0 : Array.from(el.selectedOptions).map(o => o.value);
  }
  function bindReglesRowEvents() {
    document.querySelectorAll('[data-regle-critere]').forEach(sel => sel.addEventListener('change', (e) => {
      const index = Number(e.target.dataset.regleCritere);
      currentRegles[index] = { critere: e.target.value, operateur: RULE_CRITERIA[e.target.value].operators[0], valeur: RULE_CRITERIA[e.target.value].valueType === 'number' ? 0 : [] };
      renderReglesRows();
    }));
    document.querySelectorAll('[data-regle-operateur]').forEach(sel => sel.addEventListener('change', (e) => {
      currentRegles[Number(e.target.dataset.regleOperateur)].valeur = readCurrentRegleValue(Number(e.target.dataset.regleOperateur));
      currentRegles[Number(e.target.dataset.regleOperateur)].operateur = e.target.value;
    }));
    document.querySelectorAll('[data-regle-valeur]').forEach(el => el.addEventListener('change', (e) => {
      const index = Number(e.target.dataset.regleValeur);
      currentRegles[index].valeur = readCurrentRegleValue(index);
    }));
    document.querySelectorAll('[data-remove-regle]').forEach(btn => btn.addEventListener('click', () => {
      currentRegles.splice(Number(btn.dataset.removeRegle), 1);
      renderReglesRows();
    }));
  }
  document.getElementById('btn-add-regle').addEventListener('click', () => {
    currentRegles.push({ critere: 'anciennete', operateur: '>=', valeur: 0 });
    renderReglesRows();
  });
  renderReglesRows();

  // §retour QA du 26/08/2026 (point 6.7) : valideurs nommés par étape — même patron que
  // renderReglesRows/renderPaliersRows ci-dessus (état local, re-rendu dans son propre conteneur).
  // Repart d'une sélection vide si le préréglage change : les étapes n'ont plus le même sens
  // ("Manager puis RH" -> "RH uniquement"), garder une sélection attachée au mauvais rôle serait
  // trompeur plutôt qu'utile.
  let currentOverrides = { ...(type.workflowValidatorOverrides || {}) };
  const overrideEmployeeChoices = employeeRepository.getAll().filter(e => !e.archive);
  function renderWorkflowOverridesRows() {
    const container = document.getElementById('workflow-overrides-container');
    let workflow = [];
    try { workflow = JSON.parse(document.getElementById('f-workflow').value || '[]'); } catch { workflow = []; }
    if (!workflow.length) { container.innerHTML = ''; return; }
    container.innerHTML = `
      <div class="form-field" style="margin-top: 14px;">
        <label>Valideurs nommés (optionnel)</label>
        <p class="form-hint">Laissez vide pour garder la résolution automatique par rôle. Sélectionner un ou plusieurs salariés désigne PRÉCISÉMENT qui valide cette étape, quel que soit son rôle réel.</p>
        ${workflow.map((role, i) => `
          <div class="form-field" style="margin-top: 8px;">
            <label for="f-workflow-override-${i}">Étape ${i + 1} : ${escapeHtml(ROLE_LABELS[role] || role)}</label>
            <select class="input" multiple data-workflow-override-step="${i}" id="f-workflow-override-${i}" style="min-height: 70px;">
              ${overrideEmployeeChoices.map(e => `<option value="${e.id}" ${(currentOverrides[String(i)] || []).includes(e.id) ? 'selected' : ''}>${personNameHtml(e)} (${escapeHtml(ROLE_LABELS[e.role] || e.role)})</option>`).join('')}
            </select>
          </div>
        `).join('')}
      </div>
    `;
    document.querySelectorAll('[data-workflow-override-step]').forEach(sel => sel.addEventListener('change', () => {
      currentOverrides[sel.dataset.workflowOverrideStep] = Array.from(sel.selectedOptions).map(o => o.value);
    }));
  }
  document.getElementById('f-workflow').addEventListener('change', () => {
    currentOverrides = {};
    renderWorkflowOverridesRows();
  });
  renderWorkflowOverridesRows();

  document.getElementById('leave-type-form').addEventListener('submit', (evt) => submitLeaveTypeForm(evt, id, effectiveCategorie, currentRegles, currentPaliers, currentOverrides));
}

function checkboxField(name, label, checked) {
  return `
    <div class="form-field form-field-checkbox">
      <label>
        <input type="checkbox" id="f-${name}" name="${name}" ${checked ? 'checked' : ''}>
        ${escapeHtml(label)}
      </label>
    </div>
  `;
}

function submitLeaveTypeForm(evt, id, categorie = 'conge', regles = [], paliersAnciennete = [], workflowValidatorOverrides = {}) {
  evt.preventDefault();
  const form = evt.target;
  const formData = new FormData(form);
  const checkboxNames = ['paye', 'justificatifObligatoire', 'visibleSalarie', 'visibleRH', 'saisiParSalarie', 'autoriserDemiJournee', 'autoriserPlusieursDemandes', 'exportPaie', 'actif'];

  const acquisition = formData.get('acquisition');
  const paliersConfigures = paliersAnciennete.some(p => p.ancienneteMin || p.jours);
  // #4 : Illimitée masque le champ mais un <input> masqué reste dans FormData — on force explicitement
  // à 0 plutôt que de conserver une valeur périmée qui n'a plus aucun effet sur le calcul mais
  // resterait trompeuse dans les exports/imports. §7.18 : même principe si des paliers d'ancienneté
  // remplacent nombreAnnuel.
  const nombreAnnuel = (acquisition === 'Illimitée' || paliersConfigures) ? 0 : Number(formData.get('nombreAnnuel')) || 0;
  if (nombreAnnuel < 0) {
    showToast('Le nombre de jours ne peut pas être négatif.', 'error');
    return;
  }

  // §5 : clôture de compteur optionnelle — 'MM-JJ' seulement si un mois ET un jour sont renseignés.
  const clotureMois = document.getElementById('f-cloture-mois').value;
  const clotureJour = document.getElementById('f-cloture-jour').value;
  const dateClotureCompteur = clotureMois && clotureJour ? `${String(clotureMois).padStart(2, '0')}-${String(clotureJour).padStart(2, '0')}` : null;
  const reportCompteur = dateClotureCompteur ? formData.get('reportCompteur') : 'aucun';
  const reportLimiteJours = reportCompteur === 'limite' ? Number(formData.get('reportLimiteJours')) || 0 : null;
  // §correctif audit du 23/08/2026 (§7.15) : même principe que dateClotureCompteur ci-dessus —
  // n'a de sens que si un report est effectivement possible.
  const limiteReportMois = document.getElementById('f-limite-report-mois').value;
  const limiteReportJour = document.getElementById('f-limite-report-jour').value;
  const dateLimiteReportMMJJ = reportCompteur !== 'aucun' && limiteReportMois && limiteReportJour
    ? `${String(limiteReportMois).padStart(2, '0')}-${String(limiteReportJour).padStart(2, '0')}` : null;
  // §correctif audit du 23/08/2026 (§7.8) : délai de prévenance optionnel par type.
  const delaiPrevenanceJours = Number(formData.get('delaiPrevenanceJours')) || null;
  const delaiPrevenanceMode = delaiPrevenanceJours ? (formData.get('delaiPrevenanceMode') || 'alerte') : 'alerte';

  const patch = {
    nom: formData.get('nom'),
    icone: formData.get('icone') || '🏖️',
    couleur: formData.get('couleur'),
    description: formData.get('description') || '',
    acquisition,
    nombreAnnuel,
    workflow: JSON.parse(formData.get('workflow') || '[]'),
    // §retour QA du 26/08/2026 (point 6.7) : ne garde que les étapes réellement configurées (au
    // moins un salarié choisi) — une entrée vide n'a pas le même sens qu'une entrée absente ailleurs
    // dans le moteur de résolution (voir resolveWorkflowWithFallback, data.js), autant ne jamais
    // l'écrire pour éviter toute ambiguïté.
    workflowValidatorOverrides: Object.fromEntries(
      Object.entries(workflowValidatorOverrides || {}).filter(([, ids]) => Array.isArray(ids) && ids.length > 0)
    ),
    compteurPartageAvecId: formData.get('compteurPartageAvecId') || null,
    regles: regles.filter(r => r.critere), // ligne ajoutée puis jamais configurée = ignorée plutôt que sauvegardée à moitié
    paliersAnciennete: paliersAnciennete.filter(p => p.ancienneteMin || p.jours).sort((a, b) => a.ancienneteMin - b.ancienneteMin),
    dateClotureCompteur,
    reportCompteur,
    reportLimiteJours,
    dateLimiteReportMMJJ,
    delaiPrevenanceJours,
    delaiPrevenanceMode,
    uniteDecompte: formData.get('uniteDecompte') === 'ouvrables' ? 'ouvrables' : 'ouvres',
    fractionnementActif: dateClotureCompteur ? document.getElementById('f-fractionnementActif').checked : false,
    // §correctif retour QA du 27/08/2026 (point 2.4) : un choix explicite ici prévaut désormais sur
    // l'inférence par nom (voir resolveProratisationTempsPartiel) — même pour un type nommé "RTT"/
    // "Congés payés" par coïncidence après avoir choisi volontairement un autre réglage.
    proratisationTempsPartiel: ['proportionnelle', 'aucune', 'exclu'].includes(formData.get('proratisationTempsPartiel'))
      ? formData.get('proratisationTempsPartiel') : 'proportionnelle',
    suspendAcquisitionAutresCompteurs: document.getElementById('f-suspendAcquisitionAutresCompteurs').checked
  };
  patch.illimite = patch.acquisition === 'Illimitée';
  checkboxNames.forEach(name => { patch[name] = form.querySelector(`#f-${name}`).checked; });
  patch.deduireCompteur = true;

  if (id) {
    leaveTypeRepository.updateLeaveType(id, patch);
    showToast('Type de congé mis à jour.');
  } else {
    patch.categorie = categorie;
    leaveTypeRepository.addLeaveType(patch);
    showToast('Type de congé créé.');
  }
  closeModal();
  // §sprint refonte UX §8 : la gestion des types ne vit plus que dans Paramètres (plus de sous-onglet
  // "Types" dans Congés & absences) — seul point d'entrée restant vers ce formulaire.
  navigateTo('parametres', { parametresTab: 'types-absences', parametresTypesCategorie: categorie });
}

// ---------------------------------------------------------------------------
// Vue : Calendrier
// ---------------------------------------------------------------------------

const MONTH_NAMES = ['Janvier', 'Février', 'Mars', 'Avril', 'Mai', 'Juin', 'Juillet', 'Août', 'Septembre', 'Octobre', 'Novembre', 'Décembre'];
const WEEKDAY_LABELS = ['Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam', 'Dim'];

/** Sprint SIRH premium §2 : "Calendrier des valideurs / Créer un calendrier spécifique pour RH/
 * Managers/Propriétaire. Ce calendrier affiche : leurs propres congés ; leurs événements personnels ;
 * leurs validations." — "Mon calendrier" couvre déjà les 2 premiers points pour tout le monde ;
 * cette carte ajoute le 3e (validations en attente), visible uniquement pour les rôles concernés en
 * vue personnelle. Mêmes navParams que le Centre d'action (§7)/les raccourcis sidebar (§5) — un seul
 * endroit où ces filtres sont définis (NAVPARAMS_*). */
function renderCalendrierValidationsCard(user) {
  // §tour de bugs du 07/09/2026 : liste de rôles codée en dur remplacée par les mêmes permissions
  // que canActOnRequestFor pour chaque domaine — un comptable avec validerNoteFrais accordée
  // individuellement (il n'a que controlerNoteFrais par défaut) ne voyait jamais cette carte, alors
  // qu'il peut basculer en vue "Moi" et devrait bien voir ses notes de frais à valider.
  const canValiderAbsences = user.role === ROLES.MANAGER || hasPermission(user, PERMISSIONS.VALIDER_ABSENCE);
  const canValiderFrais = hasPermission(user, PERMISSIONS.VALIDER_NOTE_FRAIS) || hasPermission(user, PERMISSIONS.CONTROLER_NOTE_FRAIS);
  if (!canValiderAbsences && !canValiderFrais) return '';
  const visibleIds = getVisibleEmployeeIdsForCurrentUser();
  const pendingFor = (repo) => {
    const list = repo.getAll().filter(r => r.statut === 'En attente');
    return visibleIds ? list.filter(r => visibleIds.includes(r.employeeId)) : list;
  };
  const congesEnAttente = canValiderAbsences ? pendingFor(leaveRepository).length : 0;
  const teletravailEnAttente = canValiderAbsences ? pendingFor(teleworkRepository).length : 0;
  const fraisEnAttente = canValiderFrais ? pendingFor(expenseRepository).length : 0;
  if (!congesEnAttente && !teletravailEnAttente && !fraisEnAttente) return '';

  const item = (count, label, nav, navParams) => !count ? '' : `
    <button type="button" class="action-center-item" data-nav="${nav}" data-nav-params='${escapeHtml(JSON.stringify(navParams))}'>
      <span class="action-center-icon">${icon(ICONS.checkCircle, 16)}</span>
      <span class="action-center-label">${count} ${label}${count > 1 ? 's' : ''} en attente de validation</span>
      <span class="action-center-arrow">→</span>
    </button>
  `;

  return `
    <div class="card action-center" style="margin-bottom: 16px;">
      <h2>Vos validations</h2>
      <div class="action-center-list">
        ${item(congesEnAttente, 'demande de congé', 'absences', NAVPARAMS_CONGES_A_VALIDER)}
        ${item(teletravailEnAttente, 'demande de télétravail', 'absences', NAVPARAMS_TELETRAVAIL_A_VALIDER)}
        ${item(fraisEnAttente, 'note de frais', 'frais', NAVPARAMS_FRAIS_A_VALIDER)}
      </div>
    </div>
  `;
}

/** Sprint SIRH premium §2 : factorisé hors de renderCalendrier() pour que openCalendarDayModal()
 * (§4, reprise) puisse recalculer le même `sharedData` pour une seule date sans dupliquer cette
 * logique de périmètre/scope. */
function buildCalendarSharedData(cells) {
  const settings = settingsRepository.getSettings();
  const user = authRepository.getCurrentUser();
  // Sprint SIRH premium §2 : "Créer un calendrier spécifique pour RH/Managers/Propriétaire [...] leurs
  // propres congés, leurs événements personnels, leurs validations" — un salarié voit déjà
  // uniquement son propre calendrier par défaut (getVisibleEmployeeIdsForCurrentUser), donc le
  // bascule n'a de sens que pour les rôles qui voient plus large (équipe pour un manager, toute
  // l'entreprise pour RH/Propriétaire/Comptabilité).
  const hasWiderView = user.role !== ROLES.SALARIE;
  const vuePersonnelle = hasWiderView && state.calendrierVue === 'personnel';

  // Récupérés une seule fois pour toute la grille plutôt qu'à chaque cellule (~35-42 fois) — mesuré : 128ms -> ~15ms pour 300 salariés.
  const visibleIds = vuePersonnelle ? [user.id] : getVisibleEmployeeIdsForCurrentUser();
  let employees = employeeRepository.getAll().filter(e => !e.archive);
  if (visibleIds !== null) employees = employees.filter(e => visibleIds.includes(e.id));
  const leaveTypes = leaveTypeRepository.getLeaveTypes();
  const leaveRequests = leaveRepository.getAll().filter(r => r.statut === 'Validé' || r.statut === 'En attente');
  // §retour Betty du 17/09/2026 (audit "millimètre par millimètre") : l'écran Calendrier ne dépend
  // QUE du module "congés" (NAV_ITEMS 'calendrier') — le télétravail est du module "planning" (voir
  // le même point déjà corrigé sur la fiche salarié). Coupé ici, à la source, plutôt que dans chaque
  // fonction de rendu qui lit sharedData.teleworkRequests (grille mensuelle personnelle ET tableau
  // équipe/entreprise, voir getCalendarDayInfo/renderAbsenceCalendarRow ci-dessous) : une entreprise
  // n'ayant souscrit qu'au module congés ne doit jamais voir de télétravail sur cet écran.
  const teleworkRequests = hasModule('planning') ? teleworkRepository.getAll().filter(r => r.statut === 'Validé' || r.statut === 'En attente') : [];
  const schoolHolidays = schoolHolidayRepository.getSchoolHolidays();
  const years = [...new Set(cells.map(c => c.date.getFullYear()))];
  const publicHolidays = years.flatMap(y => getAllPublicHolidays(y, settings));

  // §correctif audit du 31/08/2026 (efficiency) : employees/leaveTypes étaient déjà récupérés une
  // seule fois ici (voir commentaire ci-dessus), mais getCalendarDayInfo() les re-scanne ensuite en
  // O(n) (.find()) PAR salarié/type référencé, à CHAQUE cellule (~42/mois) — et anniversaires/
  // arrivées/départs re-scannaient les 300 salariés en entier, par cellule, alors que la date exacte
  // recherchée change à chaque cellule. Des Maps construites une seule fois ici transforment ces
  // lookups en O(1) par cellule au lieu de O(n).
  const employeesById = new Map(employees.map(e => [e.id, e]));
  const leaveTypesById = new Map(leaveTypes.map(t => [t.id, t]));
  const anniversairesByMonthDay = new Map();
  const arriveesByDate = new Map();
  const departsByDate = new Map();
  employees.forEach(e => {
    if (e.dateNaissance) {
      const key = e.dateNaissance.slice(5, 10);
      (anniversairesByMonthDay.get(key) || anniversairesByMonthDay.set(key, []).get(key)).push(e);
    }
    if (e.dateEmbauche) (arriveesByDate.get(e.dateEmbauche) || arriveesByDate.set(e.dateEmbauche, []).get(e.dateEmbauche)).push(e);
    if (e.dateDepart) (departsByDate.get(e.dateDepart) || departsByDate.set(e.dateDepart, []).get(e.dateDepart)).push(e);
  });

  return {
    employees, leaveTypes, leaveRequests, teleworkRequests, schoolHolidays, publicHolidays, schoolZone: settings.schoolZone,
    employeesById, leaveTypesById, anniversairesByMonthDay, arriveesByDate, departsByDate,
    // §sprint calendrier interactif : seule la vue personnelle (soi-même, jamais ambigu) autorise le
    // clic sur une case vide à créer une demande — voir renderCalendarCell/bindCalendrierEvents.
    vuePersonnelle: !hasWiderView || vuePersonnelle,
    currentUserId: user.id
  };
}

// ---------------------------------------------------------------------------
// Composant partagé "Moi / Équipe" (§sprint refonte UX §9) — Calendrier, Planning et Tickets
// restaurant utilisaient chacun leur propre bascule dupliquée ; un seul composant maintenant, même
// style/comportement partout. `stateKey` est le nom de la clé d'état ('calendrierVue',
// 'planningVue', 'ticketsRestaurantVue'), `teamValue`/`teamLabel` restent propres à chaque écran
// (ex. "Calendrier équipe" pour un manager, "Calendrier entreprise" pour RH/Propriétaire) pour ne pas
// avoir à renommer les valeurs d'état déjà lues ailleurs dans le code (buildCalendarSharedData...).
// ---------------------------------------------------------------------------

function renderMoiEquipeToggle(stateKey, teamValue, teamLabel) {
  const user = authRepository.getCurrentUser();
  if (user.role === ROLES.SALARIE) return '';
  const isPersonnel = state[stateKey] === 'personnel';
  return `
    <div class="tabs moi-equipe-toggle" style="margin-bottom: 12px;">
      <button class="tab ${!isPersonnel ? 'active' : ''}" data-moi-equipe="${stateKey}" data-moi-equipe-value="${teamValue}">${escapeHtml(teamLabel)}</button>
      <button class="tab ${isPersonnel ? 'active' : ''}" data-moi-equipe="${stateKey}" data-moi-equipe-value="personnel">Moi</button>
    </div>
  `;
}

function bindMoiEquipeToggleEvents() {
  document.querySelectorAll('[data-moi-equipe]').forEach(btn => {
    btn.addEventListener('click', () => {
      state[btn.dataset.moiEquipe] = btn.dataset.moiEquipeValue;
      render();
    });
  });
}

/** §demande Betty du 09/09/2026 : sur mobile, une barre de filtres à plusieurs champs (Salariés,
 * Congés & absences, Organigramme) s'empilait verticalement avant même de voir un résultat — repris
 * du même principe que le popover "Filtres" du Calendrier, mais plus simple ici (pas de contenu
 * distinct à régénérer : ce sont les mêmes champs qu'en desktop, juste repliés par défaut). En
 * desktop (au-dessus de 860px), ce bouton reste invisible (voir .filter-toggle-btn) et la barre de
 * filtres s'affiche normalement, comportement strictement inchangé. `targetId` doit être l'id du
 * conteneur `.toolbar.card.toolbar-collapsible` à replier/déplier ; `activeCount` (filtres non vides)
 * donne un repère sans avoir à ouvrir le panneau, même principe que "X filtres actifs" ailleurs.
 * `resetKey` (optionnel) affiche en plus un lien "Réinitialiser" — visible sur desktop ET mobile,
 * contrairement au bouton "Filtres" lui-même — qui vide tous les champs d'un coup (voir
 * FILTER_RESET_HANDLERS/bindResetFiltersButtons) plutôt que de les effacer un par un. */
function renderFilterToggleBar(targetId, activeCount, resetKey) {
  return `<button type="button" class="btn btn-secondary btn-sm filter-toggle-btn" data-toggle-filters="${targetId}">Filtres${activeCount ? ` (${activeCount})` : ''}</button>${activeCount && resetKey ? `<button type="button" class="btn-link filter-reset-link" data-reset-filters="${resetKey}">Réinitialiser les filtres</button>` : ''}`;
}

function bindFilterToggleButtons() {
  document.querySelectorAll('[data-toggle-filters]').forEach(btn => {
    btn.addEventListener('click', () => {
      const target = document.getElementById(btn.dataset.toggleFilters);
      if (target) target.classList.toggle('open');
    });
  });
  // §amélioration du 09/09/2026 : le lien "Réinitialiser les filtres" (voir renderFilterToggleBar)
  // vit toujours à côté du bouton "Filtres" — un seul binder suffit pour les deux, jamais désynchronisés.
  bindResetFiltersButtons();
}

/** Réinitialise TOUS les champs d'un coup plutôt qu'un par un — mêmes valeurs par défaut que
 * getInitialViewState (jamais dupliquées à la main pour ne pas risquer de diverger). */
const FILTER_RESET_HANDLERS = {
  employees: () => { state.search = ''; state.filters = { etablissementId: '', service: '', statutContrat: '', statut: '', favorisOnly: false }; state.employeesPage = 1; },
  conges: () => { state.congesFilters = { employeeId: '', typeId: '', statut: '', periode: '' }; state.congesPage = 1; },
  'autres-absences': () => { state.autresAbsencesFilters = { employeeId: '', typeId: '', statut: '', periode: '' }; state.autresAbsencesPage = 1; },
  teletravail: () => { state.teletravailFilters = { employeeId: '', statut: '' }; state.teletravailPage = 1; },
  frais: () => { state.fraisFilters = { employeeId: '', categorie: '', statut: '', periode: '' }; state.fraisPage = 1; },
  organigramme: () => { state.organigrammeFilters = { search: '', etablissementId: '', service: '', equipe: '' }; },
  entretiens: () => { state.entretiensSearch = ''; state.entretiensFilters = { type: '', statut: '', periode: '' }; state.entretiensPage = 1; },
  'tableau-compteurs': () => { state.tableauCompteursSearch = ''; state.tableauCompteursFilters = { service: '', etablissementId: '' }; state.tableauCompteursPage = 1; }
};

function bindResetFiltersButtons() {
  document.querySelectorAll('[data-reset-filters]').forEach(btn => {
    btn.addEventListener('click', () => {
      const handler = FILTER_RESET_HANDLERS[btn.dataset.resetFilters];
      if (handler) { handler(); render(); }
    });
  });
}

/** Catalogue des catégories filtrables du calendrier (légende + filtres cliquables, §sprint
 * calendrier légende/filtres) — une seule source de vérité pour le libellé, l'icône et la classe de
 * couleur, réutilisée à la fois par la légende et par les badges de case pour rester cohérentes. */
const CALENDAR_FILTER_CATEGORIES = [
  { key: 'conge', label: 'Congé', icon: ICONS.sun, swatchClass: 'legend-conge' },
  { key: 'anniversaire', label: 'Anniversaire', icon: ICONS.cake, swatchClass: 'legend-anniversaire' },
  { key: 'teletravail', label: 'Télétravail', icon: ICONS.laptop, swatchClass: 'legend-teletravail' },
  { key: 'arrivee', label: 'Arrivée', icon: ICONS.rocket, swatchClass: 'legend-arrivee' },
  { key: 'depart', label: 'Départ', icon: ICONS.exitDoor, swatchClass: 'legend-depart' },
  { key: 'ferie', label: 'Jour férié', icon: null, swatchClass: 'legend-holiday' },
  { key: 'vacances', label: 'Vacances scolaires', icon: null, swatchClass: 'legend-school' }
];

/** §retour Betty du 17/09/2026 (audit "millimètre par millimètre") : "Télétravail" fait partie du
 * module "planning", pas "congés" (voir NAV_ITEMS 'calendrier', module: 'conges' seul) — sans ce
 * filtre, un salarié sans le module planning voyait quand même la pastille/le filtre "Télétravail"
 * sur son propre Calendrier (toujours en vue personnelle, voir buildCalendarSharedData), même si
 * aucune demande de télétravail ne peut plus jamais y apparaître depuis ce même correctif. */
function visibleCalendarFilterCategories() {
  return CALENDAR_FILTER_CATEGORIES.filter(c => c.key !== 'teletravail' || hasModule('planning'));
}

/** Toutes les catégories actives par défaut — un filtre désactivé n'efface jamais la donnée sous-
 * jacente (getCalendarDayInfo ne change pas), seul l'affichage des badges/tags en tient compte. */
function getCalendarFilters() {
  if (!state.calendarFilters) {
    state.calendarFilters = {};
    CALENDAR_FILTER_CATEGORIES.forEach(c => { state.calendarFilters[c.key] = true; });
  }
  return state.calendarFilters;
}

/** §sprint refonte UX §3-4 : bande compacte toujours visible (pastilles seules) — le détail
 * (libellés + toggle) vit désormais dans le popover "Filtres" (`renderCalendarFiltersPanelContent`),
 * jamais affiché en permanence. Logique de filtrage inchangée (`state.calendarFilters`). */
function renderCalendarFilterBar() {
  const filters = getCalendarFilters();
  return `
    <div class="calendar-filter-bar">
      <div class="calendar-filter-dots">
        ${visibleCalendarFilterCategories().map(c => `<span class="calendar-filter-dot ${c.swatchClass}${filters[c.key] === false ? ' legend-item-inactive' : ''}" title="${escapeHtml(c.label)}"></span>`).join('')}
      </div>
      <div class="dropdown-wrapper">
        <button type="button" class="btn btn-secondary btn-sm" id="btn-calendar-filters">Filtres</button>
        <div class="dropdown-panel" id="calendar-filters-panel"></div>
      </div>
    </div>
  `;
}

function renderCalendarFiltersPanelContent(settings) {
  const filters = getCalendarFilters();
  return visibleCalendarFilterCategories().map(c => {
    const active = filters[c.key] !== false;
    const label = c.key === 'vacances' ? `Vacances scolaires (Zone ${escapeHtml(settings.schoolZone)})` : c.label;
    return `
      <button type="button" class="legend-item${active ? '' : ' legend-item-inactive'}" data-calendar-filter="${c.key}" aria-pressed="${active}" title="Afficher/masquer : ${escapeHtml(c.label)}">
        <span class="legend-swatch ${c.swatchClass}"></span>${c.icon ? ` ${c.icon}` : ''} ${label}
      </button>
    `;
  }).join('');
}

function renderCalendrier() {
  const cells = buildMonthGridCells(state.calendarYear, state.calendarMonth);
  const sharedData = buildCalendarSharedData(cells);
  const settings = settingsRepository.getSettings();
  const user = authRepository.getCurrentUser();
  const hasWiderView = user.role !== ROLES.SALARIE;
  // §sprint refonte UX §2 : signale un manque de couverture des vacances scolaires de façon
  // générale (n'importe quel mois hors couverture), jamais une correction figée pour "octobre".
  const schoolHolidays = schoolHolidayRepository.getSchoolHolidays();
  const coverageGap = isMonthBeyondSchoolYearCoverage(state.calendarYear, state.calendarMonth, schoolHolidays);

  return `
    <div class="view-header view-header-row">
      <div class="calendar-month-nav">
        <button type="button" class="calendar-month-nav-btn" id="btn-cal-prev" aria-label="Mois précédent" title="Mois précédent">‹</button>
        <div>
          <h1 style="margin: 0;">Calendrier</h1>
          <p class="view-subtitle">${MONTH_NAMES[state.calendarMonth]} ${state.calendarYear}</p>
        </div>
        <button type="button" class="calendar-month-nav-btn" id="btn-cal-next" aria-label="Mois suivant" title="Mois suivant">›</button>
      </div>
      <div class="calendar-nav">
        <!-- §demande Betty du 10/09/2026 : le filtre service et l'export Excel du calendrier
             entreprise remontent dans la barre dorée (avec Aujourd'hui) plutôt que dans leur propre
             ligne sous le bascule Moi/Équipe — gagne une ligne de hauteur sur l'écran, voir
             renderAbsenceCalendarBoard, où ce bloc figurait auparavant. §retour Betty du 10/09/2026
             ("le bouton filtres dans calendrier moi [...] tu le mets à droite") : même traitement
             pour la vue Moi — le bouton "Filtres" (renderCalendarFilterBar) remonte lui aussi dans
             cette barre plutôt que dans sa propre ligne sous la grille. -->
        ${!sharedData.vuePersonnelle ? `
          <select id="absence-cal-filter-service" class="input">
            <option value="">Tous les services</option>
            ${serviceRepository.getAll().map(s => `<option value="${escapeHtml(s.nom)}" ${state.calendarServiceFilter === s.nom ? 'selected' : ''}>${escapeHtml(s.nom)}</option>`).join('')}
          </select>
          <button type="button" class="btn btn-secondary btn-sm" id="btn-export-absence-calendar">Exporter Excel</button>
        ` : renderCalendarFilterBar()}
        <button class="btn btn-secondary btn-sm" id="btn-cal-today">Aujourd'hui</button>
      </div>
    </div>

    ${hasWiderView ? renderMoiEquipeToggle('calendrierVue', 'entreprise', user.role === ROLES.MANAGER ? 'Calendrier équipe' : 'Calendrier entreprise') : ''}

    ${hasWiderView && state.calendrierVue === 'personnel' ? renderCalendrierValidationsCard(user) : ''}

    ${!sharedData.vuePersonnelle ? renderAbsenceCalendarBoard(sharedData) : `
      <div class="card calendar-card">
        <div class="calendar-grid calendar-grid-header">
          ${WEEKDAY_LABELS.map(l => `<div class="calendar-weekday">${l}</div>`).join('')}
        </div>
        <div class="calendar-grid">
          ${cells.map(cell => renderCalendarCell(cell, sharedData)).join('')}
        </div>
      </div>

      ${coverageGap ? `<p class="text-muted" style="margin-top: 10px;">${icon(ICONS.calendar, 14)} Les vacances scolaires ne sont pas encore renseignées pour cette période. <button type="button" class="btn-link" id="btn-cal-goto-vacances-settings">Ajouter l'année scolaire suivante</button></p>` : ''}
    `}
  `;
}

/** §demande Betty du 09/09/2026 ("fais un calendrier dans ce style", capture d'un "Calendrier des
 * absences" : une ligne par salarié, une colonne par jour, des cases colorées par type de congé) :
 * remplace la grille mensuelle en vue équipe/entreprise (une grille de jours n'a de sens que pour UN
 * salarié à la fois — c'est justement pourquoi la vue personnelle la garde inchangée ci-dessus).
 * "Une couleur par congé" ne contrevient PAS à la règle bleu marine + or de l'appli : chaque type de
 * congé a déjà sa propre couleur configurable (Paramètres > Types d'absences, type.couleur, déjà
 * utilisée comme pastille dans la liste des demandes) — cet écran réutilise cette donnée existante,
 * il n'invente aucune nouvelle palette catégorielle. Le télétravail (pas un "congé", pas de couleur
 * configurable par type) garde l'accent marine déjà utilisé partout ailleurs pour lui. Une absence de
 * plusieurs jours reste plusieurs cases individuelles coloriées (jamais fusionnées en une seule
 * barre continue façon Gantt — un essai en ce sens a été rejeté par Betty, "juste les cases").
 * Regroupement par service : même bandeau que le Planning (renderPlanningGroupRows/.planning-service-header)
 * pour une identité visuelle cohérente entre les deux écrans. */
function renderAbsenceCalendarBoard(sharedData) {
  const year = state.calendarYear;
  const month = state.calendarMonth;
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const todayStr = toISODate(new Date());
  let employees = sharedData.employees;
  if (state.calendarServiceFilter) employees = employees.filter(e => e.service === state.calendarServiceFilter);
  const leaveRequests = sharedData.leaveRequests;
  const teleworkRequests = sharedData.teleworkRequests;
  const leaveTypesById = sharedData.leaveTypesById;

  const days = Array.from({ length: daysInMonth }, (_, i) => i + 1);
  const dayMeta = (day) => {
    const date = new Date(year, month, day);
    const dateStr = toISODate(date);
    return { dateStr, isWeekend: [0, 6].includes(date.getDay()), isToday: dateStr === todayStr };
  };

  return `
    <div class="absence-cal-legend">
      <!-- §retour Betty du 16/09/2026 : les 7 types d'événements familiaux regroupés sur la couleur
           d'"Exceptionnel" (voir DB.getLeaveTypes, data.js) n'apparaissent plus ICI individuellement
           — une entrée par couleur réellement distincte, pas une par type. Une absence de ce type
           garde bien sa case colorée dans la grille ci-dessous, seule la légende change. -->
      ${leaveTypeRepository.getLeaveTypes().filter(t => !NOMS_EVENEMENTS_FAMILIAUX_UNIFIES.some(nom => leaveTypeNameMatches(t.nom, nom))).map(t => `<span class="absence-cal-legend-item"><span class="absence-cal-legend-swatch" style="background:${escapeHtml(t.couleur)}"></span>${escapeHtml(t.nom)}</span>`).join('')}
      ${hasModule('planning') ? '<span class="absence-cal-legend-item"><span class="absence-cal-legend-swatch absence-cal-legend-telework"></span>Télétravail</span>' : ''}
    </div>
    <div class="card table-card planning-scroll-card">
      ${employees.length === 0 ? `<div class="empty-state"><div class="empty-icon">${ICONS.schedule}</div><p>Aucun salarié à afficher.</p></div>` : `
        <table class="table planning-table absence-cal-table">
          <thead>
            <tr>
              <th>Salarié</th>
              ${days.map(day => { const m = dayMeta(day); return `<th class="${m.isWeekend ? 'weekend' : ''}${m.isToday ? ' today' : ''}">${day}</th>`; }).join('')}
            </tr>
          </thead>
          <tbody>
            ${renderPlanningGroupRows(employees, days.length + 1, e => `
              <tr>
                <td>${personNameWithPosteHtml(e)}</td>
                ${renderAbsenceCalendarRow(e, days, dayMeta, leaveRequests, teleworkRequests, leaveTypesById)}
              </tr>
            `)}
          </tbody>
        </table>
      `}
    </div>
  `;
}

/** Découpe le mois en segments consécutifs (même congé/télétravail, ou "rien") pour un salarié —
 * un segment de plusieurs jours devient UNE cellule `colspan` avec une barre continue, plutôt qu'une
 * icône répétée jour par jour comme le Planning (ce qui serait illisible pour une absence de 2 semaines). */
/** §retour Betty du 09/09/2026, en deux temps : "ne fais pas une ligne remplie, juste les cases" a
 * d'abord fait passer chaque jour d'une absence en case individuelle (colonne par colonne), puis
 * "remets la ligne [...] mais fais des cases différentes pour mieux voir le début et la fin" —
 * l'absence redevient donc UNE seule barre continue (colspan, voir computeAbsenceCalendarSegments)
 * pour l'effet "ligne" demandé, mais son PREMIER et DERNIER jour affichent chacun le quantième
 * (ex. "8" / "11") en gras à l'extrémité correspondante de la barre, pour lever toute ambiguïté sur
 * la date exacte de début/fin sans avoir à compter les cases ni survoler au clavier/souris — un vrai
 * gain de lisibilité, pas juste un habillage. Le nom du type reste centré, tronqué si la barre est
 * trop étroite pour tout afficher (voir .absence-cal-bar-label, text-overflow). */
function computeAbsenceCalendarSegments(employee, dayNumbers, year, month, leaveRequests, teleworkRequests) {
  const segments = [];
  let current = null;
  dayNumbers.forEach(day => {
    const dateStr = toISODate(new Date(year, month, day));
    const leave = leaveRequests.find(r => r.employeeId === employee.id && dateStr >= r.dateDebut && dateStr <= r.dateFin);
    const telework = !leave && teleworkRequests.find(r => r.employeeId === employee.id && dateStr >= r.dateDebut && dateStr <= r.dateFin);
    const key = leave ? `leave:${leave.id}` : telework ? `telework:${telework.id}` : null;
    if (current && current.key === key) {
      current.days.push(day);
    } else {
      if (current) segments.push(current);
      current = { key, days: [day], leave, telework };
    }
  });
  if (current) segments.push(current);
  return segments;
}

function renderAbsenceCalendarRow(employee, dayNumbers, dayMeta, leaveRequests, teleworkRequests, leaveTypesById) {
  const year = state.calendarYear;
  const month = state.calendarMonth;
  const segments = computeAbsenceCalendarSegments(employee, dayNumbers, year, month, leaveRequests, teleworkRequests);

  return segments.map(seg => {
    if (!seg.key) {
      return seg.days.map(day => { const m = dayMeta(day); return `<td class="absence-cal-cell${m.isWeekend ? ' weekend' : ''}${m.isToday ? ' today' : ''}"></td>`; }).join('');
    }
    const startDay = seg.days[0];
    const endDay = seg.days[seg.days.length - 1];
    const multiDay = seg.days.length > 1;
    if (seg.leave) {
      const type = leaveTypesById.get(seg.leave.typeId);
      const pending = seg.leave.statut !== 'Validé';
      // §demande Betty du 10/09/2026 : la demi-journée concerne toujours le premier et/ou dernier
      // jour du segment (jamais un jour intermédiaire, voir getHalfDayForDate) — sur un segment d'un
      // seul jour, elle s'ajoute directement au libellé centré ; sur plusieurs jours, elle s'ajoute
      // au(x) quantième(s) d'extrémité concerné(s) plutôt que d'encombrer le libellé central.
      const startDateStr = toISODate(new Date(state.calendarYear, state.calendarMonth, startDay));
      const endDateStr = toISODate(new Date(state.calendarYear, state.calendarMonth, endDay));
      const startHalf = getHalfDayForDate(seg.leave, startDateStr);
      const endHalf = getHalfDayForDate(seg.leave, endDateStr);
      const halfDayLabel = (h) => h === 'matin' ? 'matin' : 'après-midi';
      const label = `${type ? type.nom : 'Congé'}${!multiDay && startHalf ? ` (${halfDayLabel(startHalf)})` : ''}`;
      const titleSuffix = multiDay
        ? `, du ${startDay}${startHalf ? ` (${halfDayLabel(startHalf)})` : ''} au ${endDay}${endHalf ? ` (${halfDayLabel(endHalf)})` : ''}`
        : startHalf ? `, ${halfDayLabel(startHalf)}` : '';
      return `<td colspan="${seg.days.length}" class="absence-cal-bar-cell"><div class="absence-cal-bar${pending ? ' absence-cal-bar-pending' : ''}" style="background:${escapeHtml(type ? type.couleur : 'var(--color-text-muted)')}" title="${escapeHtml(type ? type.nom : 'Congé')}${escapeHtml(titleSuffix)}${pending ? ' (en attente)' : ''}">
        ${multiDay ? `<span class="absence-cal-bar-edge">${startDay}${startHalf ? '<sup>½</sup>' : ''}</span>` : ''}
        <span class="absence-cal-bar-label">${escapeHtml(label)}</span>
        ${multiDay ? `<span class="absence-cal-bar-edge">${endDay}${endHalf ? '<sup>½</sup>' : ''}</span>` : ''}
      </div></td>`;
    }
    const pending = seg.telework.statut !== 'Validé';
    return `<td colspan="${seg.days.length}" class="absence-cal-bar-cell"><div class="absence-cal-bar absence-cal-bar-telework${pending ? ' absence-cal-bar-pending' : ''}" title="Télétravail, du ${startDay} au ${endDay}${pending ? ' (en attente)' : ''}">
      ${multiDay ? `<span class="absence-cal-bar-edge">${startDay}</span>` : ''}
      <span class="absence-cal-bar-label">Télétravail</span>
      ${multiDay ? `<span class="absence-cal-bar-edge">${endDay}</span>` : ''}
    </div></td>`;
  }).join('');
}

// §correctif audit du 31/08/2026 : bindCalendrierEvents() ré-attachait un listener 'click' sur
// `document` à CHAQUE rendu du calendrier (changement de mois, bascule Moi/Équipe, etc.), sans jamais
// retirer le précédent — une fuite mémoire qui accumule des closures mortes (capturant un
// filtersPanel détaché du DOM précédent) au fil de la navigation. Le drapeau ci-dessous pose ce
// listener une seule fois, plutôt qu'à chaque rendu.
let calendarFiltersOutsideCloseBound = false;
function bindCalendrierEvents() {
  document.getElementById('btn-cal-prev').addEventListener('click', () => shiftCalendarMonth(-1));
  document.getElementById('btn-cal-next').addEventListener('click', () => shiftCalendarMonth(1));
  document.getElementById('btn-cal-today').addEventListener('click', () => {
    const now = new Date();
    state.calendarYear = now.getFullYear();
    state.calendarMonth = now.getMonth();
    render();
  });
  bindMoiEquipeToggleEvents();

  const btnGotoVacances = document.getElementById('btn-cal-goto-vacances-settings');
  if (btnGotoVacances) {
    btnGotoVacances.addEventListener('click', () => navigateTo('parametres', { parametresTab: 'vacances' }));
  }

  const filtersBtn = document.getElementById('btn-calendar-filters');
  const filtersPanel = document.getElementById('calendar-filters-panel');
  if (filtersBtn && filtersPanel) {
    filtersBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      if (filtersPanel.classList.contains('open')) { filtersPanel.classList.remove('open'); return; }
      filtersPanel.innerHTML = renderCalendarFiltersPanelContent(settingsRepository.getSettings());
      bindCalendarFilterToggles();
      filtersPanel.classList.add('open');
    });
    if (!calendarFiltersOutsideCloseBound) {
      calendarFiltersOutsideCloseBound = true;
      // Ne capture jamais `filtersPanel` directement dans la closure : un rendu ultérieur du
      // calendrier remplace le DOM de #view-root, rendant ce nœud obsolète (détaché) — le listener
      // n'étant posé qu'une fois, il doit relire l'élément courant à chaque clic, pas celui du tout
      // premier rendu.
      document.addEventListener('click', (e) => {
        if (e.target.closest('.dropdown-wrapper')) return;
        const panel = document.getElementById('calendar-filters-panel');
        if (panel) panel.classList.remove('open');
      });
    }
  }

  document.querySelectorAll('[data-calendar-day]').forEach(cell => {
    cell.addEventListener('click', () => {
      const dateStr = cell.dataset.calendarDay;
      if (cell.dataset.calendarCreate) {
        openCalendarQuickAddModal(dateStr);
      } else {
        openCalendarDayModal(dateStr);
      }
    });
  });

  const serviceFilter = document.getElementById('absence-cal-filter-service');
  if (serviceFilter) {
    serviceFilter.addEventListener('change', (e) => {
      state.calendarServiceFilter = e.target.value;
      render();
    });
  }

  const exportBtn = document.getElementById('btn-export-absence-calendar');
  if (exportBtn) exportBtn.addEventListener('click', exportAbsenceCalendarExcel);
}

/** §demande Betty du 10/09/2026 ("mets un bouton exporter Excel dans le calendrier entreprise") :
 * un salarié par ligne, un jour du mois affiché par colonne (même mois/filtre service que ce qui est
 * à l'écran), la cellule reprenant le même libellé que la barre correspondante dans
 * renderAbsenceCalendarRow (nom du type de congé ou "Télétravail", "(en attente)" si non validé) —
 * pas le même regroupement par segments/colspan (qui n'a de sens qu'à l'affichage), une valeur par
 * jour, plus simple à exploiter dans un tableur.
 *
 * §retour Betty du 16/09/2026 ("il faut que le calendrier ressemble plus a un calendrier avec des
 * cases et plus jolie") : chaque en-tête de jour porte désormais aussi le jour de la semaine, et le
 * fichier est généré via buildCalendarExcelXmlWorkbook (bordures sur les 4 côtés de chaque cellule,
 * week-ends grisés) plutôt que XLSX.utils/SheetJS, qui ne permet aucune mise en forme en version
 * gratuite — plus besoin de charger la bibliothèque XLSX pour cet export. */
function exportAbsenceCalendarExcel() {
  const year = state.calendarYear;
  const month = state.calendarMonth;
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const cells = buildMonthGridCells(year, month);
  const sharedData = buildCalendarSharedData(cells);
  let employees = sharedData.employees;
  if (state.calendarServiceFilter) employees = employees.filter(e => e.service === state.calendarServiceFilter);
  const { leaveRequests, teleworkRequests, leaveTypesById } = sharedData;
  const days = Array.from({ length: daysInMonth }, (_, i) => i + 1);
  const weekendColumnIndexes = new Set();
  days.forEach((day, i) => {
    const weekday = new Date(year, month, day).getDay();
    if (weekday === 0 || weekday === 6) weekendColumnIndexes.add(2 + i);
  });

  const headers = ['Salarié', 'Service', ...days.map(day => `${day} ${WEEKDAY_LABELS[(new Date(year, month, day).getDay() + 6) % 7]}`)];
  const rows = [];
  groupEmployeesByServiceAndEquipe(employees).forEach(g => {
    g.equipes.forEach(eq => {
      eq.employees.forEach(e => {
        const row = [`${e.prenom} ${e.nom}`, e.service];
        days.forEach(day => {
          const dateStr = toISODate(new Date(year, month, day));
          const leave = leaveRequests.find(r => r.employeeId === e.id && dateStr >= r.dateDebut && dateStr <= r.dateFin);
          const telework = !leave && teleworkRequests.find(r => r.employeeId === e.id && dateStr >= r.dateDebut && dateStr <= r.dateFin);
          let label = '';
          if (leave) {
            const type = leaveTypesById.get(leave.typeId);
            label = type ? type.nom : 'Congé';
            if (leave.statut !== 'Validé') label += ' (en attente)';
          } else if (telework) {
            label = 'Télétravail';
            if (telework.statut !== 'Validé') label += ' (en attente)';
          }
          row.push(label);
        });
        rows.push(row);
      });
    });
  });

  const monthSlug = `${year}-${String(month + 1).padStart(2, '0')}`;
  const xml = buildCalendarExcelXmlWorkbook(headers, rows, 'Calendrier', weekendColumnIndexes);
  downloadExcelXmlFile(xml, `calendrier-absences-${monthSlug}.xls`);
  auditLogRepository.logAudit('Export', 'Calendrier des absences', `${MONTH_NAMES[month]} ${year}, ${employees.length} salarié${employees.length > 1 ? 's' : ''}`);
}

/** Extrait de bindCalendrierEvents : le contenu du popover Filtres est régénéré à chaque ouverture
 * (voir bindCalendrierEvents), donc ses propres écouteurs doivent être re-posés à chaque fois. */
function bindCalendarFilterToggles() {
  document.querySelectorAll('[data-calendar-filter]').forEach(btn => {
    btn.addEventListener('click', () => {
      const filters = getCalendarFilters();
      const key = btn.dataset.calendarFilter;
      filters[key] = filters[key] === false; // toggle : false -> true, sinon -> false
      render();
      // §correctif QA du 26/08/2026 : render() redessine tout le calendrier, y compris un nouveau
      // popover de filtres fermé par défaut — sans ça, cocher/décocher plusieurs catégories à la
      // suite obligeait à rouvrir "Filtres" après chaque clic, alors que ce popover est justement
      // pensé pour cocher plusieurs cases d'affilée (même patron de réouverture que le clic initial
      // sur le bouton "Filtres", voir bindCalendrierEvents).
      const panel = document.getElementById('calendar-filters-panel');
      if (panel) {
        panel.innerHTML = renderCalendarFiltersPanelContent(settingsRepository.getSettings());
        bindCalendarFilterToggles();
        panel.classList.add('open');
      }
    });
  });
}

/** §sprint refonte UX §6 : petit choix rapide (Congé/absence vs Télétravail) au clic sur un jour
 * vide, plutôt qu'ouvrir directement openLeaveRequestModal — réutilise le patron modal existant. */
function openCalendarQuickAddModal(dateStr) {
  const user = authRepository.getCurrentUser();
  const html = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>${escapeHtml(formatDate(dateStr))}</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <div class="modal-body">
        <p class="text-muted" style="margin-top: 0;">Que souhaitez-vous ajouter ?</p>
        <button type="button" class="legend-item" id="btn-quick-add-conge" style="margin-bottom: 8px;">
          ${icon(ICONS.sun, 15)} Congé / absence
        </button>
        <button type="button" class="legend-item" id="btn-quick-add-teletravail">
          ${icon(ICONS.laptop, 15)} Télétravail
        </button>
      </div>
    </div>
  `;
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');

  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-quick-add-conge').addEventListener('click', () => {
    state._leaveRequestReturnToCalendar = true;
    openLeaveRequestModal(user.id, undefined, undefined, dateStr);
  });
  document.getElementById('btn-quick-add-teletravail').addEventListener('click', () => {
    state._leaveRequestReturnToCalendar = true;
    openTeleworkRequestModal(user.id, undefined, dateStr);
  });
}

function shiftCalendarMonth(delta) {
  let month = state.calendarMonth + delta;
  let year = state.calendarYear;
  if (month < 0) { month = 11; year -= 1; }
  if (month > 11) { month = 0; year += 1; }
  state.calendarMonth = month;
  state.calendarYear = year;
  render();
}

/** Construit les cellules du mois affiché, en complétant les semaines avec les mois voisins. */
function buildMonthGridCells(year, month) {
  const firstOfMonth = new Date(year, month, 1);
  const startWeekday = (firstOfMonth.getDay() + 6) % 7; // 0 = Lundi
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const cells = [];

  for (let i = 0; i < startWeekday; i++) {
    cells.push({ date: new Date(year, month, 1 - (startWeekday - i)), inMonth: false });
  }
  for (let day = 1; day <= daysInMonth; day++) {
    cells.push({ date: new Date(year, month, day), inMonth: true });
  }
  while (cells.length % 7 !== 0) {
    const last = cells[cells.length - 1].date;
    cells.push({ date: new Date(last.getFullYear(), last.getMonth(), last.getDate() + 1), inMonth: false });
  }
  return cells;
}

/** Agrège toutes les informations RH réelles concernant une date donnée, restreintes au périmètre visible par l'utilisateur courant. */
function getCalendarDayInfo(dateStr, sharedData) {
  const { leaveRequests, teleworkRequests, schoolHolidays, publicHolidays, schoolZone,
    employeesById, leaveTypesById, anniversairesByMonthDay, arriveesByDate, departsByDate } = sharedData;

  const conges = leaveRequests
    .filter(r => dateStr >= r.dateDebut && dateStr <= r.dateFin)
    .map(r => {
      const emp = employeesById.get(r.employeeId);
      const type = leaveTypesById.get(r.typeId);
      return emp && type ? { emp, type, statut: r.statut, demiJournee: r.demiJournee || null } : null;
    })
    .filter(Boolean);

  const anniversaires = anniversairesByMonthDay.get(dateStr.slice(5, 10)) || [];
  const arrivees = arriveesByDate.get(dateStr) || [];
  const departs = departsByDate.get(dateStr) || [];

  const teletravail = teleworkRequests
    .filter(r => dateStr >= r.dateDebut && dateStr <= r.dateFin)
    .map(r => {
      const emp = employeesById.get(r.employeeId);
      return emp ? { emp, statut: r.statut } : null;
    })
    .filter(Boolean);

  const ferie = publicHolidays.find(h => h.date === dateStr) || null;
  const vacances = findSchoolHolidayPeriod(dateStr, schoolZone, schoolHolidays);

  return { conges, anniversaires, arrivees, departs, teletravail, ferie, vacances };
}

function renderCalendarCell(cell, sharedData) {
  const dateStr = toISODate(cell.date);
  const info = getCalendarDayInfo(dateStr, sharedData);
  const isToday = dateStr === toISODate(new Date());
  const isWeekend = [0, 6].includes(cell.date.getDay());
  // §sprint calendrier légende/filtres : un filtre désactivé ne touche jamais getCalendarDayInfo
  // (la donnée reste intacte) — il retire seulement l'affichage correspondant ci-dessous.
  const filters = getCalendarFilters();
  const ferieVisible = Boolean(info.ferie) && filters.ferie !== false;
  const vacancesVisible = Boolean(info.vacances) && filters.vacances !== false;

  const classes = ['calendar-cell'];
  if (!cell.inMonth) classes.push('out-month');
  if (isToday) classes.push('today');
  if (isWeekend) classes.push('weekend');
  if (ferieVisible) classes.push('holiday');
  if (vacancesVisible) classes.push('school-holiday');

  // Sprint SIRH premium §2 : "Les demandes non validées doivent être visibles [...] facilement
  // identifiables" — séparées des demandes validées dans un badge distinct, semi-transparent
  // (cf. .calendar-badge-pending), plutôt que mélangées sans distinction dans le même badge.
  const congesValides = info.conges.filter(c => c.statut === 'Validé');
  const congesEnAttente = info.conges.filter(c => c.statut !== 'Validé');
  const teletravailValide = info.teletravail.filter(t => t.statut === 'Validé');
  const teletravailEnAttente = info.teletravail.filter(t => t.statut !== 'Validé');

  const badges = [
    congesValides.length && filters.conge !== false ? calendarBadge('conge', ICONS.sun, congesValides.map(c => `${c.emp.prenom} ${c.emp.nom} · ${c.type.nom}${c.demiJournee ? ` (${c.demiJournee === 'matin' ? 'matin' : 'après-midi'})` : ''}`)) : '',
    congesEnAttente.length && filters.conge !== false ? calendarBadge('conge', ICONS.sun, congesEnAttente.map(c => `${c.emp.prenom} ${c.emp.nom} · ${c.type.nom}${c.demiJournee ? ` (${c.demiJournee === 'matin' ? 'matin' : 'après-midi'})` : ''} (en attente)`), true) : '',
    teletravailValide.length && filters.teletravail !== false ? calendarBadge('teletravail', ICONS.laptop, teletravailValide.map(t => `${t.emp.prenom} ${t.emp.nom}`)) : '',
    teletravailEnAttente.length && filters.teletravail !== false ? calendarBadge('teletravail', ICONS.laptop, teletravailEnAttente.map(t => `${t.emp.prenom} ${t.emp.nom} (en attente)`), true) : '',
    info.anniversaires.length && filters.anniversaire !== false ? calendarBadge('anniversaire', ICONS.cake, info.anniversaires.map(e => `${e.prenom} ${e.nom}`)) : '',
    info.arrivees.length && filters.arrivee !== false ? calendarBadge('arrivee', ICONS.rocket, info.arrivees.map(e => `${e.prenom} ${e.nom} (arrivée)`)) : '',
    info.departs.length && filters.depart !== false ? calendarBadge('depart', ICONS.exitDoor, info.departs.map(e => `${e.prenom} ${e.nom} (départ)`)) : ''
  ].join('');

  // §correctif audit du 23/08/2026 (§7.6) : "repère visible dans le calendrier" — uniquement en vue
  // équipe/entreprise (un quota compare plusieurs salariés entre eux, ça n'a pas de sens sur un
  // calendrier personnel d'un seul salarié). Un jour où un quota est ATTEINT (pas juste approché)
  // affiche un repère, sans nommer les salariés concernés ici (déjà visibles via les badges congé
  // ci-dessus) — juste le signal qu'un service/équipe est au maximum ce jour-là.
  const quotaAlerte = !sharedData.vuePersonnelle && (settingsRepository.getSettings().quotasSimultanes || [])
    .some(q => countAbsentsForQuota(q, dateStr, null) >= q.maxSimultane);

  // §4 (reprise) : le survol des badges (.calendar-tooltip) reste utile sur desktop mais est
  // inutilisable au tactile et cache vite plusieurs infos à la fois sur un jour chargé — une case
  // avec du contenu est en plus rendue cliquable (clavier/tactile inclus, cf. le gestionnaire
  // role="button" générique déjà en place) pour ouvrir le détail complet du jour dans une modale.
  const hasContent = Boolean(badges || info.ferie || info.vacances || quotaAlerte);
  const hasAbsence = Boolean(congesValides.length || congesEnAttente.length || teletravailValide.length || teletravailEnAttente.length);

  // §sprint calendrier interactif : un jour sans absence, en vue personnelle (jamais en vue
  // équipe/entreprise — une case y mélange plusieurs salariés, sans salarié cible évident), devient
  // cliquable pour CRÉER une demande plutôt que pour consulter — voir bindCalendrierEvents.
  // §demande Betty du 09/09/2026 : renderCalendarCell n'est plus appelée qu'en vue personnelle
  // (l'équipe/entreprise affiche désormais renderAbsenceCalendarBoard, le planning des absences en
  // cases, voir renderCalendrier) — sharedData.vuePersonnelle vaut donc toujours true ici.
  const isCreateTarget = sharedData.vuePersonnelle && cell.inMonth && !hasAbsence;
  const isClickable = hasContent || isCreateTarget;

  return `
    <div class="${classes.join(' ')}${isClickable ? ' calendar-cell-clickable' : ''}"
      ${isClickable ? `role="button" tabindex="0" data-calendar-day="${dateStr}" ${isCreateTarget ? 'data-calendar-create="1"' : ''} aria-label="${isCreateTarget ? 'Créer une demande le' : 'Détail du'} ${escapeHtml(formatDate(dateStr))}"` : ''}>
      <div class="calendar-cell-header">
        <span class="calendar-day-number">${cell.date.getDate()}</span>
      </div>
      ${ferieVisible ? `<div class="calendar-tag calendar-tag-holiday">${escapeHtml(info.ferie.label)}</div>` : ''}
      ${quotaAlerte ? `<div class="calendar-tag calendar-tag-quota" title="Un quota d'absences simultanées est atteint ce jour-là">${icon(ICONS.warningTriangle, 11)} Quota atteint</div>` : ''}
      <div class="calendar-badges">${badges}</div>
    </div>
  `;
}

function calendarBadge(category, icon, names, pending = false) {
  return `
    <span class="calendar-badge calendar-badge-${category}${pending ? ' calendar-badge-pending' : ''}" ${pending ? 'title="En attente de validation"' : ''}>
      ${icon}${names.length > 1 ? names.length : ''}
      <span class="calendar-tooltip">${names.map(escapeHtml).join('<br>')}</span>
    </span>
  `;
}

/** Sprint SIRH premium §4 (reprise) : détail complet d'un jour du calendrier, dans une modale plutôt
 * qu'au survol (.calendar-tooltip) — accessible au clavier/tactile, et lisible même quand plusieurs
 * catégories d'évènements se superposent le même jour (un badge par catégorie devient vite illisible
 * une fois qu'il y a beaucoup de monde). Recalcule son propre `sharedData` (une seule date, donc bon
 * marché) via buildCalendarSharedData plutôt que de dépendre d'un état capturé au rendu précédent.
 * §demande Betty du 09/09/2026 : n'est plus appelée qu'en vue personnelle — la vue équipe/entreprise
 * affiche désormais renderAbsenceCalendarBoard (le planning des absences en cases, toute l'équipe
 * déjà visible sans avoir à cliquer sur un jour), voir renderCalendrier. */
function openCalendarDayModal(dateStr) {
  // §correctif bug sweep 19/08/2026 : new Date(dateStr) traitait cette date pure comme un
  // horodatage UTC — dans un fuseau derrière UTC, le 1er janvier retombait sur le 31 décembre
  // (getFullYear() côté buildCalendarSharedData), chargeant la liste de jours fériés de la MAUVAISE
  // année et faisant disparaître le badge "Jour de l'an" ce jour précis.
  const sharedData = buildCalendarSharedData([{ date: parseISODateLocal(dateStr) }]);
  const info = getCalendarDayInfo(dateStr, sharedData);

  // §refonte identité 20/08/2026 : items porte désormais {icon, text} séparément plutôt qu'une
  // seule chaîne concaténée — text.icone (congé) peut être un emoji choisi librement par un RH
  // (donnée utilisateur, toujours échappée via escapeIcon), à ne jamais mélanger dans la même
  // chaîne qu'une icône ICONS.xxx de confiance (SVG, jamais échappée) sous peine de casser l'une
  // des deux en forçant un traitement unique.
  const sections = [
    { label: 'Congés / absences', items: info.conges.map(c => ({ icon: c.type.icone, text: `${c.emp.prenom} ${c.emp.nom} · ${c.type.nom}${c.demiJournee ? ` (${c.demiJournee === 'matin' ? 'matin' : 'après-midi'})` : ''}${c.statut !== 'Validé' ? ' (en attente)' : ''}` })) },
    { label: 'Télétravail', items: info.teletravail.map(t => ({ icon: ICONS.laptop, text: `${t.emp.prenom} ${t.emp.nom}${t.statut !== 'Validé' ? ' (en attente)' : ''}` })) },
    { label: 'Anniversaires', items: info.anniversaires.map(e => ({ icon: ICONS.cake, text: `${e.prenom} ${e.nom}` })) },
    { label: 'Arrivées', items: info.arrivees.map(e => ({ icon: ICONS.rocket, text: `${e.prenom} ${e.nom}` })) },
    { label: 'Départs', items: info.departs.map(e => ({ icon: ICONS.exitDoor, text: `${e.prenom} ${e.nom}` })) }
  ].filter(s => s.items.length);

  const html = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>${escapeHtml(formatDate(dateStr))}</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <div class="modal-body">
        ${info.ferie ? `<span class="badge badge-danger" style="margin-bottom: 10px;">${escapeHtml(info.ferie.label)}</span>` : ''}
        ${info.vacances ? `<span class="badge badge-info" style="margin-bottom: 10px;">${icon(ICONS.backpack, 14)} ${escapeHtml(info.vacances.nom)}</span>` : ''}
        ${sections.length === 0 ? '<p class="text-muted">Rien de particulier à signaler ce jour-là.</p>' : sections.map(s => `
          <div style="margin-bottom: 14px;">
            <div class="search-section-label" style="padding-left: 0;">${escapeHtml(s.label)}</div>
            <div class="mini-list">
              ${s.items.map(i => `<div class="mini-list-item"><span>${escapeIcon(i.icon)} ${escapeHtml(i.text)}</span></div>`).join('')}
            </div>
          </div>
        `).join('')}
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Fermer</button>
      </div>
    </div>
  `;
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');
  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
}

// ---------------------------------------------------------------------------
// Vue : Paramètres (listes de référence, vacances scolaires, jours fériés)
// ---------------------------------------------------------------------------

// §correctif audit du 23/08/2026 (§6.3) : categoriesFrais retirée d'ici — rendue séparément, sous
// son propre thème "module frais" dans renderParametresListes, pas dans le bloc "rh" toujours
// affiché. Renommée _RH (pas juste SETTINGS_LISTS) pour rendre ce périmètre explicite.
// §retour Betty du 19/09/2026 : "Statuts professionnels" retirée d'ici — plus aucun menu déroulant
// ne s'appuie sur settings.statutsPro (employee.statutPro est aujourd'hui recopié automatiquement
// depuis la catégorie de salarié choisie, voir submitEmployeeForm), la carte n'avait donc plus
// aucun effet réel. La donnée elle-même n'est PAS retirée (DEFAULT_SETTINGS.statutsPro sert encore
// de socle à deriveCategoriesSalarieFromStatutPro, data.js) : seule cette carte, devenue trompeuse
// dans Paramètres, disparaît.
const SETTINGS_LISTS_RH = [
  { key: 'conventionsCollectives', label: 'Conventions collectives' },
  { key: 'typesContrat', label: 'Types de contrat' },
  { key: 'forfaits', label: 'Forfaits' },
  { key: 'categoriesDocuments', label: 'Catégories de documents' },
  // Modèles de checklist (demande du 18/08/2026) : l'ordre d'ajout fait l'ordre d'affichage sur la
  // fiche salarié (renderChecklistCard) — pas de ré-ordonnancement, une liste courte suffit à
  // couvrir l'essentiel sans complexité de drag-and-drop pour un simple "ne rien oublier".
  { key: 'onboardingChecklistTemplate', label: 'Checklist d\'intégration (onboarding)' },
  { key: 'offboardingChecklistTemplate', label: 'Checklist de départ (offboarding)' }
];

/** Avant de retirer une valeur de ces listes de référence, vérifie qu'aucun enregistrement ne la
 * référence encore — sinon cet enregistrement se retrouve avec une valeur orpheline, invisible
 * dans tout futur select (même défaut déjà corrigé pour établissements/services/équipes). */
const SETTINGS_LIST_USAGE_CHECK = {
  postes: (value) => employeeRepository.getAll().some(e => e.poste === value),
  conventionsCollectives: (value) => employeeRepository.getAll().some(e => e.conventionCollective === value),
  typesContrat: (value) => employeeRepository.getAll().some(e => e.typeContrat === value),
  forfaits: (value) => employeeRepository.getAll().some(e => e.forfait === value),
  categoriesFrais: (value) => expenseRepository.getAll().some(n => n.categorie === value),
  categoriesDocuments: (value) => documentRepository.getAll().some(d => d.categorie === value)
};

/** §refonte QA du 26/08/2026 (point E.2, pilote) : un onglet de Paramètres avait sa condition de
 * module dupliquée à 4 endroits (bouton desktop, option mobile, content-switch, bindParametresEvents)
 * — exactement pourquoi le point A.2 a d'abord laissé passer une fuite, puis (une fois le rendu
 * corrigé) fait planter le dispatch d'évènements resté aiguillé sur un onglet devenu invisible. Un
 * seul tableau, une seule vérité : ajouter/retirer un onglet ou changer son module requis se fait
 * ICI et nulle part ailleurs. `isVisible` est un prédicat sans argument (comme hasModule()) — chaque
 * onglet lit lui-même ce dont il a besoin plutôt que de le recevoir en paramètre. */
// §retour Betty du 10/09/2026 ("dans les paramètres on puisse changer la photo de profil") : la vue
// "parametres" était jusqu'ici entièrement gated à RH/Propriétaire au niveau de NAV_ITEMS (seul rôle
// pouvant même l'atteindre) — les `isVisible` ci-dessous n'avaient donc jamais eu besoin de vérifier
// eux-mêmes gererParametres. Le nouvel onglet "Mon compte" ouvre désormais cette vue à TOUT rôle
// (voir NAV_ITEMS, l'entrée "Mon compte") : chaque AUTRE onglet doit donc vérifier cette permission
// EXPLICITEMENT ici, sinon un salarié qui atteint "Mon compte" verrait aussi les onglets
// d'administration de l'entreprise dans la liste (le "Référentiels"/"Entreprise" affichés, même sans
// bouton pour les modifier, resteraient une fuite d'information).
const canManageParametres = () => hasPermission(authRepository.getCurrentUser(), PERMISSIONS.GERER_PARAMETRES);

const PARAMETRES_TABS = [
  { key: 'entreprise', label: 'Entreprise', isVisible: canManageParametres, render: renderParametresEntreprise, bind: bindParametresEntrepriseEvents },
  { key: 'abonnement', label: 'Abonnement', isVisible: () => hasPermission(authRepository.getCurrentUser(), PERMISSIONS.GERER_ABONNEMENTS), render: renderParametresAbonnement, bind: bindParametresAbonnementEvents },
  { key: 'etablissements', label: 'Établissements', isVisible: canManageParametres, render: renderParametresEtablissements, bind: bindParametresEtablissementsEvents },
  { key: 'services', label: 'Services &amp; équipes', isVisible: canManageParametres, render: renderParametresServices, bind: bindParametresServicesEvents },
  { key: 'types-absences', label: "Types d'absences", isVisible: () => canManageParametres() && hasModule('conges'), render: renderParametresTypesAbsences, bind: bindParametresTypesAbsencesEvents },
  { key: 'listes', label: 'Référentiels', isVisible: canManageParametres, render: renderParametresListes, bind: bindParametresListesEvents },
  { key: 'vacances', label: 'Vacances scolaires', isVisible: () => canManageParametres() && hasModule('conges'), render: renderParametresVacances, bind: bindParametresVacancesEvents },
  { key: 'feries', label: 'Jours fériés', isVisible: canManageParametres, render: renderParametresFeries, bind: bindParametresFeriesEvents },
  { key: 'fermetures', label: 'Fermetures', isVisible: () => canManageParametres() && hasModule('conges'), render: renderParametresFermetures, bind: bindParametresFermeturesEvents },
  { key: 'integrations', label: 'Intégrations', isVisible: () => canManageParametres() && (hasModule('conges') || hasModule('planning') || hasModule('frais')), render: renderParametresIntegrations, bind: bindParametresIntegrationsEvents },
  { key: 'modeles-documents', label: 'Modèles de documents', isVisible: canManageParametres, render: renderParametresModelesDocuments, bind: bindParametresModelesDocumentsEvents },
  { key: 'registre-personnel', label: 'Registre du personnel', isVisible: () => canManageParametres() && hasModule('rh'), render: renderParametresRegistrePersonnel, bind: bindParametresRegistrePersonnelEvents },
  { key: 'audit', label: 'Audit', isVisible: canManageParametres, render: renderParametresAuditHub, bind: bindParametresAuditHubEvents },
  // Seul onglet accessible à TOUT rôle (voir le commentaire au-dessus) — photo de profil visible
  // ensuite dans le Planning et partout ailleurs où renderAvatar() est utilisé.
  { key: 'mon-compte', label: 'Mon compte', isVisible: () => true, render: renderParametresMonCompte, bind: bindParametresMonCompteEvents },
];

function renderParametres() {
  // §correctif audit du 23/08/2026 (§6.3) : l'onglet "Catégories de salariés" est retiré, replié
  // dans "Référentiels" (state.parametresTab reste 'listes' en interne, seul le libellé change) —
  // un lien profond vers l'ancien onglet retombe donc sur Référentiels plutôt qu'un écran vide.
  if (state.parametresTab === 'categories-salarie') state.parametresTab = 'listes';
  // §correctif audit du 23/08/2026 (§6.4) : "Qualité des données" et "Journal d'audit" fusionnent
  // en un seul onglet "audit" (sous-onglets internes, voir renderParametresAuditHub) — un lien
  // profond vers l'ancien onglet "qualite" retombe sur "audit", sous-onglet Contrôle des dossiers.
  if (state.parametresTab === 'qualite') { state.parametresTab = 'audit'; state.parametresAuditSousTab = 'controle'; }
  // §correctif audit du 23/08/2026 (§6.6) : "Comptes salariés" n'est plus un onglet séparé — la
  // gestion se fait depuis la fiche du salarié (carte "Compte"), avec un repère dans le Centre
  // d'action du tableau de bord à la place (voir renderDashboardActionCenter).
  if (state.parametresTab === 'comptes') state.parametresTab = 'listes';
  // §correctif QA du 26/08/2026 (point A.2, complément) : remplace les anciennes vérifications au
  // cas par cas (abonnement, puis 4 onglets liés aux modules) par UNE seule règle générique, valable
  // pour tout onglet présent dans PARAMETRES_TABS — un lien profond ou un changement de modules en
  // cours de session ne laisse donc jamais l'état pointer vers un onglet devenu invisible.
  // §retour Betty du 10/09/2026 : "listes" (le repli historique ci-dessus) n'est plus visible pour
  // qui n'a pas gererParametres (voir canManageParametres) — un salarié dont l'onglet demandé est
  // devenu invisible doit retomber sur "Mon compte" (toujours visible), jamais rester bloqué.
  if (!PARAMETRES_TABS.some(t => t.key === state.parametresTab && t.isVisible())) {
    const listes = PARAMETRES_TABS.find(t => t.key === 'listes');
    state.parametresTab = (listes && listes.isVisible()) ? 'listes' : 'mon-compte';
  }

  const visibleTabs = PARAMETRES_TABS.filter(t => t.isVisible());
  const activeTab = PARAMETRES_TABS.find(t => t.key === state.parametresTab) || PARAMETRES_TABS.find(t => t.key === 'mon-compte');

  return `
    <div class="view-header">
      <h1>Paramètres</h1>
      <p class="view-subtitle">${canManageParametres() ? "Entreprise, types d'absences, référentiels, vacances scolaires, jours fériés et journal d'audit" : 'Vos réglages personnels'}</p>
    </div>
    <div class="tabs parametres-tabs-desktop">
      ${visibleTabs.map(t => `<button class="tab ${state.parametresTab === t.key ? 'active' : ''}" data-parametres-tab="${t.key}">${t.label}</button>`).join('')}
    </div>
    <!-- §demande 18/08/2026 : 11+ onglets qui se repliaient en plusieurs lignes de boutons sur
         mobile ("un tas de bouton au même endroit") — un menu déroulant remplace la rangée
         d'onglets uniquement sous 860px (voir style.css), même sélection (state.parametresTab). -->
    <select class="input parametres-tab-select" id="parametres-tab-select">
      ${visibleTabs.map(t => `<option value="${t.key}" ${state.parametresTab === t.key ? 'selected' : ''}>${t.label}</option>`).join('')}
    </select>
    <div id="parametres-tab-content">
      ${activeTab.render()}
    </div>
  `;
}

// ---- Sous-vue : Mon compte (§retour Betty du 10/09/2026, ouverte à TOUT rôle) ----

/** Photo de profil (§retour Betty du 10/09/2026 : "dans les paramètres on puisse changer la photo
 * de profil pour qu'on puisse voir dans le planning") — employees.photo existe déjà et est déjà lu
 * par renderAvatar() partout dans l'app (Planning, listes de salariés...), il ne manquait qu'un
 * moyen de le renseigner. Même patron que le logo d'entreprise (renderParametresEntreprise) : aperçu
 * + bouton qui déclenche un input file caché. */
/** §retour Betty du 14/09/2026 (Planning point 4, "déclaration de disponibilités et de
 * contraintes") : chacun déclare SES PROPRES indisponibilités récurrentes ici (jamais un tiers,
 * même raisonnement que l'accusé de lecture ou la proposition d'échange de quart) — le planning les
 * signale (jamais un blocage, voir renderPlanningPostes/shiftChevaucheIndisponibilite). */
function renderIndisponibilitesCard(user) {
  if (!hasModule('planning')) return '';
  const indisponibilites = user.indisponibilitesRecurrentes || [];
  return `
    <div class="card" style="margin-top: 16px;">
      <div class="view-header-row">
        <h2>Disponibilités</h2>
        <button class="btn btn-secondary btn-sm" id="btn-add-indisponibilite">+ Déclarer une indisponibilité</button>
      </div>
      <p class="text-muted" style="margin: 0 0 8px;">Récurrent chaque semaine (pas une date précise) — le planning signale un quart posé dessus, sans jamais bloquer sa création.</p>
      ${indisponibilites.length === 0 ? '<p class="text-muted">Aucune indisponibilité déclarée.</p>' : indisponibilites.map(i => `
        <div class="mini-list-item">
          <span>${escapeHtml(i.weekday)} ${escapeHtml(i.heureDebut)}-${escapeHtml(i.heureFin)}${i.motif ? ` · ${escapeHtml(i.motif)}` : ''}</span>
          <button type="button" class="btn-link btn-link-danger" data-delete-indisponibilite="${i.id}">Supprimer</button>
        </div>
      `).join('')}
    </div>
  `;
}

/** §retour Betty du 14/09/2026 (Congés, "délégation de validation") : "3 semaines d'absence d'un
 * manager gèle l'équipe" — réservé au rôle manager, seul rôle dont l'autorité de validation repose
 * sur managerIds (RH/Propriétaire valident déjà via une permission globale, pas via une relation
 * d'équipe : les déléguer poserait un problème différent, une vraie extension de permission plutôt
 * qu'une simple relation d'équipe temporaire — hors périmètre ici). */
function renderDelegationCard(user) {
  if (user.role !== ROLES.MANAGER) return '';
  const delegations = user.delegations || [];
  const todayStr = toISODate(new Date());
  return `
    <div class="card" style="margin-top: 16px;">
      <div class="view-header-row">
        <h2>Délégation de validation</h2>
        <button class="btn btn-secondary btn-sm" id="btn-add-delegation">+ Déléguer temporairement</button>
      </div>
      <p class="text-muted" style="margin: 0 0 8px;">Pendant votre absence, la personne désignée peut valider les congés/notes de frais de votre équipe à votre place, avec les mêmes droits que vous sur cette équipe (rien en dehors).</p>
      ${delegations.length === 0 ? '<p class="text-muted">Aucune délégation en cours.</p>' : delegations.slice().sort((a, b) => b.dateFin.localeCompare(a.dateFin)).map(d => {
        const delegataire = employeeRepository.getById(d.delegataireId);
        const active = d.dateDebut <= todayStr && d.dateFin >= todayStr;
        return `
          <div class="mini-list-item">
            <span>${delegataire ? personNameHtml(delegataire) : '<span class="text-muted">Salarié supprimé</span>'} · ${formatDate(d.dateDebut)} → ${formatDate(d.dateFin)}${active ? ' <span class="badge badge-success">active</span>' : ''}</span>
            <button type="button" class="btn-link btn-link-danger" data-delete-delegation="${d.id}">Supprimer</button>
          </div>
        `;
      }).join('')}
    </div>
  `;
}

function openDelegationModal() {
  const user = authRepository.getCurrentUser();
  const collegues = employeeRepository.getAll().filter(e => !e.archive && e.id !== user.id);
  const html = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>Déléguer ma validation</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="delegation-form">
        <div class="modal-body">
          <div class="form-field">
            <label for="f-delegation-employee">À qui ? *</label>
            <select class="input" id="f-delegation-employee" required>
              <option value="">Sélectionner...</option>
              ${collegues.map(e => `<option value="${e.id}">${escapeHtml(e.prenom + ' ' + e.nom)}</option>`).join('')}
            </select>
          </div>
          <div class="form-grid" style="margin-top: 12px;">
            <div class="form-field"><label for="f-delegation-debut">Du *</label><input class="input" type="date" id="f-delegation-debut" required></div>
            <div class="form-field"><label for="f-delegation-fin">Au *</label><input class="input" type="date" id="f-delegation-fin" required></div>
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="submit" class="btn btn-primary">Déléguer</button>
        </div>
      </form>
    </div>
  `;
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');
  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('delegation-form').addEventListener('submit', (evt) => {
    evt.preventDefault();
    const delegataireId = document.getElementById('f-delegation-employee').value;
    const dateDebut = document.getElementById('f-delegation-debut').value;
    const dateFin = document.getElementById('f-delegation-fin').value;
    if (!delegataireId) { showToast('Choisissez un salarié.', 'error'); return; }
    if (!dateDebut || !dateFin || dateFin < dateDebut) { showToast('La date de fin doit être après la date de début.', 'error'); return; }
    const delegation = { id: generateId('deleg'), delegataireId, dateDebut, dateFin, dateCreation: new Date().toISOString() };
    employeeRepository.update(user.id, { delegations: [...(user.delegations || []), delegation] });
    showToast('Délégation enregistrée.');
    closeModal();
    render();
  });
}

function renderParametresMonCompte() {
  const user = authRepository.getCurrentUser();
  return `
    <div class="card">
      <h2>Photo de profil</h2>
      <p class="text-muted" style="margin: 0 0 8px;">Affichée à côté de votre nom partout dans l'application (Planning, listes de salariés, en haut à droite...).</p>
      <div style="display: flex; align-items: center; gap: 14px;">
        ${renderAvatar(user)}
        <div>
          <input type="file" id="f-photo-upload" accept="image/png,image/jpeg" style="display: none;">
          <button type="button" class="btn btn-secondary btn-sm" id="btn-upload-photo">Changer la photo</button>
        </div>
      </div>
    </div>
    ${renderIndisponibilitesCard(user)}
    ${renderDelegationCard(user)}
  `;
}

/** §retour Betty du 10/09/2026 ("qu'on puisse la recadrer quand on la met") : la photo choisie passe
 * par openPhotoCropModal (recadrage) AVANT l'upload — jamais le fichier brut tel que sélectionné.
 * renderUserMenuButton() est appelée en plus de render() : contrairement au reste de l'app, l'avatar
 * "en haut à droite" (bouton du menu utilisateur) n'est pas dans #view-root et ne se redessine donc
 * jamais tout seul via render() (voir showApp(), seul autre appelant de renderUserMenuButton). */
function bindParametresMonCompteEvents() {
  const user = authRepository.getCurrentUser();
  const photoUploadInput = document.getElementById('f-photo-upload');
  document.getElementById('btn-upload-photo').addEventListener('click', () => photoUploadInput.click());
  photoUploadInput.addEventListener('change', () => {
    const file = photoUploadInput.files[0];
    photoUploadInput.value = '';
    if (!file) return;
    openPhotoCropModal(file, async (croppedFile) => {
      try {
        await employeeRepository.uploadMyPhoto(user.id, croppedFile);
        showToast('Photo de profil mise à jour.');
        renderUserMenuButton();
        render();
      } catch (err) {
        showToast(err.message || 'Impossible de mettre à jour la photo.', 'error');
      }
    });
  });

  const addIndisponibiliteBtn = document.getElementById('btn-add-indisponibilite');
  if (addIndisponibiliteBtn) addIndisponibiliteBtn.addEventListener('click', () => openIndisponibiliteModal(user.id));
  // §retour Betty du 19/09/2026 (point 7, "cinq suppressions sans confirmation") : un clic sur
  // "Supprimer" agissait immédiatement, sans aucun rattrapage possible — même garde-fou que partout
  // ailleurs dans l'app (openConfirm), avec le détail (jour/horaire) plutôt qu'un "Voulez-vous
  // supprimer ?" muet.
  document.querySelectorAll('[data-delete-indisponibilite]').forEach(btn => {
    btn.addEventListener('click', () => {
      const indispo = (user.indisponibilitesRecurrentes || []).find(i => i.id === btn.dataset.deleteIndisponibilite);
      openConfirm({
        title: 'Supprimer cette indisponibilité ?',
        message: indispo ? `${indispo.weekday} ${indispo.heureDebut}-${indispo.heureFin}${indispo.motif ? ` (${indispo.motif})` : ''} ne sera plus signalée au planning.` : 'Cette indisponibilité ne sera plus signalée au planning.',
        confirmLabel: 'Supprimer',
        danger: true,
        onConfirm: () => {
          const liste = (user.indisponibilitesRecurrentes || []).filter(i => i.id !== btn.dataset.deleteIndisponibilite);
          employeeRepository.update(user.id, { indisponibilitesRecurrentes: liste });
          showToast('Indisponibilité supprimée.');
          render();
        }
      });
    });
  });

  const addDelegationBtn = document.getElementById('btn-add-delegation');
  if (addDelegationBtn) addDelegationBtn.addEventListener('click', openDelegationModal);
  document.querySelectorAll('[data-delete-delegation]').forEach(btn => {
    btn.addEventListener('click', () => {
      const delegation = (user.delegations || []).find(d => d.id === btn.dataset.deleteDelegation);
      const delegataire = delegation ? employeeRepository.getById(delegation.delegataireId) : null;
      openConfirm({
        title: 'Supprimer cette délégation ?',
        message: delegation
          ? `${delegataire ? `${delegataire.prenom} ${delegataire.nom}` : 'Cette personne'} ne pourra plus valider à votre place du ${formatDate(delegation.dateDebut)} au ${formatDate(delegation.dateFin)}.`
          : 'Cette délégation sera retirée.',
        confirmLabel: 'Supprimer',
        danger: true,
        onConfirm: () => {
          const liste = (user.delegations || []).filter(d => d.id !== btn.dataset.deleteDelegation);
          employeeRepository.update(user.id, { delegations: liste });
          showToast('Délégation supprimée.');
          render();
        }
      });
    });
  });
}

function openIndisponibiliteModal(employeeId) {
  const html = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>Déclarer une indisponibilité</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="indisponibilite-form">
        <div class="modal-body">
          <div class="form-grid">
            <div class="form-field">
              <label for="f-indispo-weekday">Jour</label>
              <select class="input" id="f-indispo-weekday">
                ${WEEKDAY_LABELS.map(w => `<option value="${w}">${w}</option>`).join('')}
              </select>
            </div>
            <div class="form-field"><label for="f-indispo-debut">Début</label><input class="input" type="time" id="f-indispo-debut" value="09:00" required></div>
            <div class="form-field"><label for="f-indispo-fin">Fin</label><input class="input" type="time" id="f-indispo-fin" value="12:00" required></div>
            <div class="form-field"><label for="f-indispo-motif">Motif (optionnel)</label><input class="input" type="text" id="f-indispo-motif" placeholder="Ex. cours du soir"></div>
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="submit" class="btn btn-primary">Ajouter</button>
        </div>
      </form>
    </div>
  `;
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');
  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('indisponibilite-form').addEventListener('submit', (evt) => {
    evt.preventDefault();
    const heureDebut = document.getElementById('f-indispo-debut').value;
    const heureFin = document.getElementById('f-indispo-fin').value;
    if (heureFin <= heureDebut) { showToast('L\'heure de fin doit être après l\'heure de début.', 'error'); return; }
    const employee = employeeRepository.getById(employeeId);
    const nouvelle = {
      id: generateId('indispo'), weekday: document.getElementById('f-indispo-weekday').value,
      heureDebut, heureFin, motif: document.getElementById('f-indispo-motif').value.trim()
    };
    employeeRepository.update(employeeId, { indisponibilitesRecurrentes: [...(employee.indisponibilitesRecurrentes || []), nouvelle] });
    closeModal();
    showToast('Indisponibilité déclarée.');
    render();
  });
}

/** §retour Betty du 10/09/2026 ("qu'on puisse la recadrer quand on la met") : recadrage simple avant
 * upload — zoom (molette/glissière) + déplacement (glisser-déposer) de la photo dans une fenêtre
 * carrée fixe, exactement comme la plupart des uploads d'avatar (Slack, GitHub...). Pas de
 * bibliothèque tierce : l'appli n'a aucune dépendance externe embarquée (voir qrcode.js, vendu
 * localement) — un simple <canvas> suffit pour ce besoin, jamais qu'un carré de sortie (la photo
 * s'affiche toujours en cercle, voir .avatar), pas de ratio à choisir. `onConfirm(croppedFile)`
 * reçoit un File JPEG déjà recadré, jamais le fichier brut sélectionné par l'utilisateur. */
function openPhotoCropModal(file, onConfirm) {
  const reader = new FileReader();
  reader.onload = () => {
    const stageSize = 280;
    const outputSize = 400;
    let zoom = 1;
    let panX = 0;
    let panY = 0;
    let baseScale = 1;
    let naturalWidth = 0;
    let naturalHeight = 0;
    let dragging = false;
    let dragStart = null;

    const html = `
      <div class="modal">
        <div class="modal-header">
          <h2>Recadrer la photo</h2>
          <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
        </div>
        <div class="modal-body">
          <div class="photo-crop-stage" id="photo-crop-stage" style="width: ${stageSize}px; height: ${stageSize}px;">
            <img id="photo-crop-img" src="${reader.result}" alt="" draggable="false">
          </div>
          <div class="form-field" style="margin-top: 14px;">
            <label for="photo-crop-zoom">Zoom</label>
            <input type="range" id="photo-crop-zoom" min="1" max="3" step="0.01" value="1">
          </div>
          <p class="text-muted">Faites glisser la photo pour la repositionner.</p>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="button" class="btn btn-primary" id="btn-confirm-crop">Valider</button>
        </div>
      </div>
    `;
    const modalRoot = document.getElementById('modal-root');
    modalRoot.innerHTML = html;
    modalRoot.classList.add('open');

    const imgEl = document.getElementById('photo-crop-img');
    const zoomInput = document.getElementById('photo-crop-zoom');

    // Recentre/clampe la position à chaque changement (zoom ou glisser) : l'image doit TOUJOURS
    // couvrir entièrement le carré de recadrage, jamais laisser un bord vide.
    const applyTransform = () => {
      const scale = baseScale * zoom;
      const dispW = naturalWidth * scale;
      const dispH = naturalHeight * scale;
      const minX = stageSize - dispW;
      const minY = stageSize - dispH;
      panX = Math.min(0, Math.max(minX, panX));
      panY = Math.min(0, Math.max(minY, panY));
      imgEl.style.width = `${dispW}px`;
      imgEl.style.height = `${dispH}px`;
      imgEl.style.left = `${panX}px`;
      imgEl.style.top = `${panY}px`;
    };

    // §retour Betty du 10/09/2026 ("c'est pas bien cadré [...] modifie ça") : deux correctifs.
    //   1. Une <img src="data:..."> peut déjà être `complete` (image décodée) à l'instant même où
    //      son attribut src est posé (voir l'insertion via modalRoot.innerHTML plus haut) — le
    //      handler `onload` posé APRÈS coup ne se déclenche alors jamais, et l'image reste à sa
    //      taille native non recadrée (aucun style.width/left/top appliqué) au lieu d'être centrée
    //      et mise à l'échelle. Filet de sécurité : si l'image est déjà chargée, on initialise tout
    //      de suite plutôt que d'attendre un évènement qui ne viendra pas.
    //   2. Centrage vertical strict par défaut : sur une photo portrait (visage dans le tiers
    //      supérieur, cas le plus courant d'une photo de profil), un centrage à 50 % coupait trop de
    //      la tête et laissait trop d'épaules/torse visible. Biais à 25 % (au lieu de 50 %) vers le
    //      haut de l'image quand elle déborde verticalement — sans effet sur une photo au format
    //      paysage (rien ne déborde alors verticalement, le calcul donne 0 dans les deux cas).
    const initCrop = () => {
      naturalWidth = imgEl.naturalWidth;
      naturalHeight = imgEl.naturalHeight;
      // "Cover" du carré de recadrage au zoom minimal (1x), comme un background-size:cover.
      baseScale = Math.max(stageSize / naturalWidth, stageSize / naturalHeight);
      const dispW = naturalWidth * baseScale;
      const dispH = naturalHeight * baseScale;
      panX = (stageSize - dispW) / 2;
      panY = (stageSize - dispH) * 0.25;
      applyTransform();
    };
    if (imgEl.complete && imgEl.naturalWidth > 0) initCrop();
    else imgEl.onload = initCrop;

    zoomInput.addEventListener('input', () => {
      zoom = Number(zoomInput.value);
      applyTransform();
    });

    imgEl.addEventListener('pointerdown', (e) => {
      dragging = true;
      dragStart = { x: e.clientX - panX, y: e.clientY - panY };
      imgEl.setPointerCapture(e.pointerId);
    });
    imgEl.addEventListener('pointermove', (e) => {
      if (!dragging) return;
      panX = e.clientX - dragStart.x;
      panY = e.clientY - dragStart.y;
      applyTransform();
    });
    imgEl.addEventListener('pointerup', () => { dragging = false; });
    imgEl.addEventListener('pointercancel', () => { dragging = false; });

    document.getElementById('btn-close-modal').addEventListener('click', closeModal);
    document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
    document.getElementById('btn-confirm-crop').addEventListener('click', () => {
      // Fenêtre visible du carré de recadrage, ramenée aux coordonnées pixel de l'image SOURCE
      // (avant mise à l'échelle) : c'est cette zone-là, et uniquement elle, qui doit être découpée.
      const scale = baseScale * zoom;
      const sourceX = -panX / scale;
      const sourceY = -panY / scale;
      const sourceSize = stageSize / scale;
      const canvas = document.createElement('canvas');
      canvas.width = outputSize;
      canvas.height = outputSize;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(imgEl, sourceX, sourceY, sourceSize, sourceSize, 0, 0, outputSize, outputSize);
      canvas.toBlob(blob => {
        if (!blob) { showToast('Impossible de recadrer cette image.', 'error'); return; }
        const croppedFile = new File([blob], 'photo.jpg', { type: 'image/jpeg' });
        closeModal();
        onConfirm(croppedFile);
      }, 'image/jpeg', 0.9);
    });
  };
  reader.onerror = () => showToast('Impossible de lire ce fichier.', 'error');
  reader.readAsDataURL(file);
}

/** Sprint SIRH premium §1 : le prompt d'origine demandait la gestion des types d'absences
 * "dans les paramètres RH" — jusqu'ici construite uniquement sous les onglets "Types" de Congés/
 * Autres absences (§1 déjà livré, fonctionnellement complet, mais au mauvais endroit). Corrigé en
 * réutilisant TEL QUEL renderCongesTypes()/bindCongesTypesEvents() (déjà génériques par catégorie)
 * comme nouveau point d'entrée sous Paramètres, sans dupliquer cette logique ni retirer les onglets
 * "Types" existants (qui restent un raccourci valide depuis l'écran Congés/Autres absences). */
function renderParametresTypesAbsences() {
  const categorie = state.parametresTypesCategorie || 'conge';
  return `
    <div class="tabs" style="margin-bottom: 14px;">
      <button class="tab ${categorie === 'conge' ? 'active' : ''}" data-parametres-types-categorie="conge">Congés payés / RTT</button>
      <button class="tab ${categorie === 'autre' ? 'active' : ''}" data-parametres-types-categorie="autre">Autres absences</button>
      <button class="tab ${categorie === 'quotas' ? 'active' : ''}" data-parametres-types-categorie="quotas">Quotas simultanés</button>
    </div>
    ${categorie === 'quotas' ? renderParametresQuotasSimultanes() : renderCongesTypes(categorie)}
  `;
}

function bindParametresTypesAbsencesEvents() {
  const categorie = state.parametresTypesCategorie || 'conge';
  document.querySelectorAll('[data-parametres-types-categorie]').forEach(btn => {
    btn.addEventListener('click', () => { state.parametresTypesCategorie = btn.dataset.parametresTypesCategorie; render(); });
  });
  if (categorie === 'quotas') bindParametresQuotasSimultanesEvents();
  else bindCongesTypesEvents(categorie);
}

// ---- Sous-vue : Quotas d'absences simultanées (§7.6) ----

/** §correctif audit du 23/08/2026 (§7.6) : "un maximum par service ou par équipe, avec alerte à la
 * saisie et repère visible dans le calendrier. Sans lui, un manager découvre le conflit par
 * hasard." — pas de blocage (l'audit ne le demande pas ici, contrairement à §7.8) : une alerte
 * dans l'aide à la saisie (updateLeaveRequestHints) et une pastille dans le calendrier équipe
 * (renderCalendrier) suffisent à rendre le conflit visible AVANT qu'il ne surprenne un manager. */
function renderParametresQuotasSimultanes() {
  const settings = settingsRepository.getSettings();
  const quotas = settings.quotasSimultanes || [];
  return `
    <div class="card table-card">
      <div class="view-header-row" style="padding: 20px 20px 0;">
        <div>
          <h2>Quotas d'absences simultanées</h2>
          <p class="text-muted">Nombre maximum de salariés d'un même service ou d'une même équipe absents en même temps ; alerte à la saisie d'une demande, sans jamais bloquer.</p>
        </div>
        <button class="btn btn-primary btn-sm" id="btn-add-quota">+ Ajouter un quota</button>
      </div>
      ${quotas.length === 0 ? `<div class="empty-state"><div class="empty-icon">${ICONS.people}</div><p>Aucun quota configuré.</p></div>` : `
        <table class="table">
          <thead><tr><th>Nom</th><th>Périmètre</th><th>Maximum simultané</th><th></th></tr></thead>
          <tbody>
            ${quotas.map(q => `
              <tr>
                <td>${escapeHtml(q.nom)}</td>
                <td>${q.scope === 'equipe' ? 'Équipe' : 'Service'} · ${escapeHtml(q.scopeValue)}</td>
                <td>${escapeHtml(q.maxSimultane)}</td>
                <td>
                  <button type="button" class="btn-link" data-edit-quota="${escapeHtml(q.id)}">Modifier</button>
                  <button type="button" class="btn-link" data-delete-quota="${escapeHtml(q.id)}" data-nom="${escapeHtml(q.nom)}">Supprimer</button>
                </td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      `}
    </div>
  `;
}

function bindParametresQuotasSimultanesEvents() {
  document.getElementById('btn-add-quota').addEventListener('click', () => openQuotaSimultaneModal());
  document.querySelectorAll('[data-edit-quota]').forEach(btn => {
    btn.addEventListener('click', () => {
      const settings = settingsRepository.getSettings();
      const quota = (settings.quotasSimultanes || []).find(q => q.id === btn.dataset.editQuota);
      openQuotaSimultaneModal(quota);
    });
  });
  document.querySelectorAll('[data-delete-quota]').forEach(btn => {
    btn.addEventListener('click', () => {
      openConfirm({
        title: 'Supprimer ce quota ?',
        message: `«${btn.dataset.nom}» ne sera plus pris en compte.`,
        confirmLabel: 'Supprimer',
        danger: true,
        onConfirm: () => {
          const settings = settingsRepository.getSettings();
          settings.quotasSimultanes = (settings.quotasSimultanes || []).filter(q => q.id !== btn.dataset.deleteQuota);
          settingsRepository.saveSettings(settings);
          showToast('Quota supprimé.');
          render();
        }
      });
    });
  });
}

function openQuotaSimultaneModal(existing) {
  const isEdit = Boolean(existing);
  const services = Array.from(new Set(employeeRepository.getAll().filter(e => !e.archive && e.service).map(e => e.service))).sort();
  const equipes = Array.from(new Set(employeeRepository.getAll().filter(e => !e.archive && e.equipe).map(e => e.equipe))).sort();
  const scopeInit = existing?.scope || 'service';
  const html = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>${isEdit ? 'Modifier le quota' : 'Nouveau quota'}</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="quota-form">
        <div class="modal-body">
          <div class="form-field">
            <label for="f-quota-nom">Nom *</label>
            <input class="input" type="text" id="f-quota-nom" value="${escapeHtml(existing?.nom || '')}" placeholder="Ex. Équipe support toujours couverte" required>
          </div>
          <div class="form-grid" style="margin-top:12px;">
            <div class="form-field">
              <label for="f-quota-scope">Périmètre</label>
              <select class="input" id="f-quota-scope">
                <option value="service" ${scopeInit === 'service' ? 'selected' : ''}>Service</option>
                <option value="equipe" ${scopeInit === 'equipe' ? 'selected' : ''}>Équipe</option>
              </select>
            </div>
            <div class="form-field">
              <label for="f-quota-scope-value">Valeur *</label>
              <select class="input" id="f-quota-scope-value" required></select>
            </div>
          </div>
          <div class="form-field" style="margin-top:12px;">
            <label for="f-quota-max">Maximum de salariés absents simultanément *</label>
            <input class="input" type="number" min="0" step="1" id="f-quota-max" value="${escapeHtml(existing?.maxSimultane ?? '')}" required>
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="submit" class="btn btn-primary">${isEdit ? 'Enregistrer' : 'Créer'}</button>
        </div>
      </form>
    </div>
  `;
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');
  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);

  const scopeValueSelect = document.getElementById('f-quota-scope-value');
  const populateScopeValues = () => {
    const scope = document.getElementById('f-quota-scope').value;
    const options = scope === 'equipe' ? equipes : services;
    scopeValueSelect.innerHTML = options.map(v => `<option value="${escapeHtml(v)}" ${existing?.scopeValue === v ? 'selected' : ''}>${escapeHtml(v)}</option>`).join('');
  };
  document.getElementById('f-quota-scope').addEventListener('change', populateScopeValues);
  populateScopeValues();

  document.getElementById('quota-form').addEventListener('submit', (evt) => {
    evt.preventDefault();
    const nom = document.getElementById('f-quota-nom').value.trim();
    const scope = document.getElementById('f-quota-scope').value;
    const scopeValue = scopeValueSelect.value;
    const maxSimultane = Number(document.getElementById('f-quota-max').value);
    if (!scopeValue) {
      showToast(`Aucun${scope === 'equipe' ? 'e équipe' : ' service'} disponible : renseignez-en un(e) d'abord.`, 'error');
      return;
    }
    if (!Number.isFinite(maxSimultane) || maxSimultane < 0) {
      showToast('Le maximum doit être un nombre positif.', 'error');
      return;
    }
    const settings = settingsRepository.getSettings();
    const quota = isEdit ? { ...existing, nom, scope, scopeValue, maxSimultane } : { id: generateId('quota'), nom, scope, scopeValue, maxSimultane };
    settings.quotasSimultanes = isEdit
      ? (settings.quotasSimultanes || []).map(q => q.id === existing.id ? quota : q)
      : [...(settings.quotasSimultanes || []), quota];
    settingsRepository.saveSettings(settings);
    closeModal();
    showToast(isEdit ? 'Quota mis à jour.' : 'Quota créé.');
    render();
  });
}

/** Salariés (actifs) déjà absents (congé/télétravail Validé ou En attente) sur dateStr et
 * appartenant au même périmètre qu'un quota — utilisé à la fois par l'alerte de saisie et par le
 * repère calendrier, jamais dupliqué entre les deux. `excludeEmployeeId` : ignore le salarié qui
 * dépose LUI-MÊME la demande (déjà compté par définition, ne doit pas se compter deux fois si son
 * propre calendrier affiche le repère du jour concerné). */
/** §retour Betty du 14/09/2026 (Congés point "vue de l'équipe au moment de poser") : le calcul
 * existait déjà (countAbsentsForQuota, ci-dessous, qui n'en gardait que la taille) — extrait ici en
 * fonction à part pour que l'aide à la saisie (updateLeaveRequestHints) puisse aussi afficher QUI
 * est concerné, pas seulement combien. */
function getAbsentsForQuota(quota, dateStr, excludeEmployeeId) {
  const employees = employeeRepository.getAll().filter(e => !e.archive
    && (quota.scope === 'equipe' ? e.equipe === quota.scopeValue : e.service === quota.scopeValue)
    && e.id !== excludeEmployeeId);
  if (!employees.length) return [];
  const employeeIds = new Set(employees.map(e => e.id));
  const isActive = (r) => r.statut === 'Validé' || r.statut === 'En attente';
  const overlaps = (r) => r.dateDebut <= dateStr && r.dateFin >= dateStr;
  // Télétravail délibérément exclu : ce n'est pas une absence physique, hors périmètre du quota.
  const absentIds = new Set();
  leaveRepository.getAll().forEach(r => { if (employeeIds.has(r.employeeId) && isActive(r) && overlaps(r)) absentIds.add(r.employeeId); });
  return employees.filter(e => absentIds.has(e.id));
}

function countAbsentsForQuota(quota, dateStr, excludeEmployeeId) {
  return getAbsentsForQuota(quota, dateStr, excludeEmployeeId).length;
}

/** Quotas dont le périmètre couvre ce salarié — un salarié peut apparaître dans un quota "service"
 * ET un quota "équipe" à la fois, les deux s'appliquent indépendamment. */
function getQuotasForEmployee(employee, settings) {
  return (settings.quotasSimultanes || []).filter(q =>
    q.scope === 'equipe' ? q.scopeValue === employee.equipe : q.scopeValue === employee.service);
}

/** Contrairement aux autres onglets Paramètres (données déjà dans le cache local), le webhook Slack
 * n'est jamais rapatrié à l'hydratation (secret protégé par RLS, voir integrationsRepository) — un
 * état de chargement bref est donc assumé ici, unique onglet de cet écran à en avoir besoin. */
// §correctif audit du 23/08/2026 (§6.9) : "Ajouter Microsoft Teams et Google Chat aux
// intégrations. Même principe que le webhook Slack existant." — même carte/formulaire répétée
// pour les 3 plateformes plutôt qu'une fonction par plateforme, un seul endroit à faire évoluer
// si une 4ᵉ s'ajoute un jour.
const CHAT_INTEGRATIONS = [
  { key: 'slack', field: 'slackWebhookUrl', label: 'Slack', placeholder: 'https://hooks.slack.com/services/...', hint: 'Créez un webhook entrant depuis les paramètres de votre espace Slack (Apps → Incoming Webhooks), puis collez son URL ici. Laissez vide pour désactiver.' },
  { key: 'teams', field: 'teamsWebhookUrl', label: 'Microsoft Teams', placeholder: 'https://.../workflows/...', hint: 'Dans le canal Teams visé : Workflows → "Recevoir un webhook quand un message est publié" → collez l\'URL générée ici. Laissez vide pour désactiver.' },
  { key: 'googlechat', field: 'googleChatWebhookUrl', label: 'Google Chat', placeholder: 'https://chat.googleapis.com/v1/spaces/...', hint: 'Dans l\'espace Google Chat visé : icône de l\'espace → Applications et intégrations → Ajouter un webhook → collez l\'URL ici. Laissez vide pour désactiver.' }
];

function renderParametresIntegrations() {
  if (state.integrationsCache === undefined) return renderSkeletonLines(3);
  if (state.integrationsCache === null) return '<p class="text-muted">Impossible de charger les intégrations pour le moment.</p>';
  return CHAT_INTEGRATIONS.map(integ => `
    <div class="card" style="max-width: 560px;">
      <h3 style="margin-top:0;">${escapeHtml(integ.label)}</h3>
      <p class="text-muted">Reçoit une notification dans ${integ.label === 'Slack' ? 'un canal Slack' : integ.label === 'Microsoft Teams' ? 'un canal Teams' : 'un espace Google Chat'} à chaque nouvelle demande de congé, de télétravail ou de note de frais nécessitant une validation.</p>
      <form class="integrations-webhook-form" data-integration-key="${integ.key}">
        <div class="form-field">
          <label for="f-webhook-${integ.key}">URL du webhook entrant</label>
          <input class="input" type="url" id="f-webhook-${integ.key}" placeholder="${escapeHtml(integ.placeholder)}" value="${escapeHtml(state.integrationsCache[integ.field] || '')}">
          <p class="form-hint">${integ.hint}</p>
        </div>
        <button type="submit" class="btn btn-primary" style="margin-top:12px;">Enregistrer</button>
      </form>
    </div>
  `).join('');
}

function bindParametresIntegrationsEvents() {
  if (state.integrationsCache === undefined) {
    integrationsRepository.get()
      .then(data => { state.integrationsCache = data; render(); })
      .catch(() => { state.integrationsCache = null; render(); });
    return;
  }
  document.querySelectorAll('.integrations-webhook-form').forEach(form => {
    form.addEventListener('submit', async (evt) => {
      evt.preventDefault();
      const integ = CHAT_INTEGRATIONS.find(i => i.key === form.dataset.integrationKey);
      const value = document.getElementById(`f-webhook-${integ.key}`).value.trim();
      const submitBtn = form.querySelector('button[type="submit"]');
      submitBtn.disabled = true;
      try {
        const updated = { ...state.integrationsCache, [integ.field]: value };
        await integrationsRepository.save(updated);
        state.integrationsCache = updated;
        showToast('Intégrations enregistrées.');
      } catch (err) {
        showToast('Erreur lors de l\'enregistrement.', 'error');
      }
      submitBtn.disabled = false;
    });
  });
}

/** §correctif retour QA du 27/08/2026 (point 4) : la rangée d'onglets Paramètres passait au menu
 * déroulant uniquement sous 860px (voir style.css) — entre 860px et la largeur réellement nécessaire
 * aux 11 onglets, la rangée débordait sans AUCUN moyen de l'atteindre à la souris (la barre de
 * défilement est volontairement masquée, .tabs, pour tout le reste de l'app — voir ce commentaire —
 * et le glissé tactile n'existe pas sur ordinateur). "Le seuil ne devrait pas être une largeur
 * d'écran mais le fait que les onglets tiennent ou non" : mesure réelle (scrollWidth > clientWidth)
 * plutôt qu'un second seuil de largeur à deviner — bascule vers le menu déroulant dès que ça déborde,
 * à N'IMPORTE QUELLE largeur d'écran, y compris desktop large avec beaucoup de modules souscrits. */
function checkParametresTabsOverflow() {
  const tabsRow = document.querySelector('.parametres-tabs-desktop');
  const select = document.getElementById('parametres-tab-select');
  if (!tabsRow || !select) return;
  // Mesure avec la rangée forcée visible (elle a pu être masquée par un précédent appel, ce qui
  // donnerait 0 débordement en boucle) — puis on retranche la largeur déjà prise par le sélecteur
  // caché (0 ici) : simplement remettre display:flex avant de mesurer.
  tabsRow.style.display = 'flex';
  select.style.display = 'none';
  const overflowing = tabsRow.scrollWidth > tabsRow.clientWidth + 1; // +1 : tolérance d'arrondi sub-pixel
  if (overflowing) {
    tabsRow.style.display = 'none';
    select.style.display = 'block';
  }
}

function bindParametresEvents() {
  checkParametresTabsOverflow();
  const tabSelect = document.getElementById('parametres-tab-select');
  if (tabSelect) tabSelect.addEventListener('change', () => { state.parametresTab = tabSelect.value; render(); renderSidebar(); });
  document.querySelectorAll('[data-parametres-tab]').forEach(btn => {
    // renderSidebar() en plus de render() : "Abonnement" a maintenant sa propre entrée de menu
    // (même vue "parametres", distinguée par navParams) — sans ça, passer d'un onglet à l'autre ne
    // met jamais à jour quel item du menu doit rester surligné.
    btn.addEventListener('click', () => { state.parametresTab = btn.dataset.parametresTab; render(); renderSidebar(); });
  });

  // §refonte QA du 26/08/2026 (point E.2, pilote) : dispatché depuis PARAMETRES_TABS — voir le
  // commentaire au-dessus de ce tableau (renderParametres) sur pourquoi cette liste séparée d'ifs
  // dupliquait exactement la même connaissance et a fini par diverger du content-switch.
  const activeTab = PARAMETRES_TABS.find(t => t.key === state.parametresTab) || PARAMETRES_TABS.find(t => t.key === 'listes');
  activeTab.bind();
}

// ---- Sous-vue : Entreprise (profil) ----

function renderParametresEntreprise() {
  const profile = companyRepository.getProfile();
  const settings = settingsRepository.getSettings();
  const user = authRepository.getCurrentUser();

  return `
    <div class="card">
      <h2>Profil de l'entreprise</h2>
      <div class="form-field" style="margin-bottom: 16px;">
        <label>Logo</label>
        <p class="text-muted" style="margin: 0 0 8px;">Affiché en haut de la page publique de candidature (voir Embauche), en plus du nom.</p>
        <div style="display: flex; align-items: center; gap: 14px;">
          ${profile.logo
            ? `<img src="${escapeHtml(profile.logo)}" alt="Logo" style="max-width: 80px; max-height: 80px; border-radius: var(--radius-md); border: 1px solid var(--color-border);">`
            : `<div style="width: 80px; height: 80px; border-radius: var(--radius-md); border: 1px dashed var(--color-border); display: flex; align-items: center; justify-content: center; color: var(--color-text-muted); font-size: 12px;">Aucun logo</div>`}
          <div>
            <input type="file" id="f-logo-upload" accept="image/png,image/jpeg,image/svg+xml" style="display: none;">
            <button type="button" class="btn btn-secondary btn-sm" id="btn-upload-logo">Changer le logo</button>
          </div>
        </div>
      </div>
      <form id="entreprise-form">
        <div class="form-grid">
          ${companyNameAutocompleteField('raisonSociale', 'Raison sociale', profile.raisonSociale, true, 'siret', 'adresse')}
          <div class="form-field">
            <label for="f-siret">SIRET</label>
            <input class="input" type="text" id="f-siret" name="siret" value="${escapeHtml(profile.siret || '')}"
              data-siret-autocomplete="true" data-fill-raison="f-raisonSociale" data-fill-adresse="f-adresse">
            <span class="field-hint-computed" id="f-siret-hint"></span>
          </div>
          ${textField('tva', 'N° TVA intracommunautaire', profile.tva)}
          ${textField('adresse', 'Adresse', profile.adresse)}
          ${textField('telephone', 'Téléphone', profile.telephone)}
          ${textField('email', 'Email', profile.email, true, 'email')}
          ${conventionCollectiveAutocompleteField('conventionCollective', 'Convention collective', profile.conventionCollective)}
        </div>
        <!-- §retour Betty du 18/09/2026 (point 4) : proposée automatiquement dès qu'un SIRET valide
             est saisi ci-dessus (voir la recherche déjà en place pour la raison sociale/l'adresse),
             mais JAMAIS appliquée sans confirmation explicite — un salarié qui saisit son SIRET ne
             s'attend pas à voir un champ légal changer sous ses yeux. -->
        <div id="convention-suggestion" class="field-warning" style="align-items: flex-start; flex-direction: column; gap: 8px;"></div>
        ${settings.conventionCollectiveLegifranceUrl ? `<p class="form-hint"><a href="${escapeHtml(settings.conventionCollectiveLegifranceUrl)}" target="_blank" rel="noopener noreferrer">Voir mes accords d'entreprise (Légifrance)</a></p>` : ''}
        <p class="form-hint">${icon(ICONS.info, 12)} Liste des conventions collectives non exhaustive (~180 les plus courantes) et pas automatiquement mise à jour : si la vôtre n'apparaît pas ou que le code IDCC vous semble dépassé, <a href="https://code.travail.gouv.fr/outils/convention-collective" target="_blank" rel="noopener noreferrer">vérifiez sur l'outil officiel du Ministère du Travail</a>.</p>
        <button type="submit" class="btn btn-primary" style="margin-top: 14px;">Enregistrer</button>
      </form>
    </div>
    ${renderExportDonneesCard(user)}
  `;
}

/** §retour Betty du 11/09/2026 (point 4.2, réversibilité) : "un acheteur sérieux pose cette question
 * avant de signer", et c'est aussi une obligation de portabilité. Export JSON complet (salariés,
 * congés, télétravail, notes de frais, documents, tickets, entretiens, idées, journal d'audit...),
 * SANS la fenêtre glissante de hydrateCurrentCompany (point 1 étape 2, voir
 * fetchFullCompanyExportData, supabase-client.js) : un export de réversibilité doit couvrir TOUT
 * l'historique, pas seulement les ~40 derniers mois affichés au quotidien. Réservé à qui gère déjà
 * les Paramètres (RH/Propriétaire) — même permission que le reste de cet écran.
 *
 * Scope volontairement réduit pour cette première version : JSON structuré uniquement (pas de
 * variante Excel/tableur pour l'instant — le JSON seul satisfait déjà l'exigence de portabilité,
 * "format structuré, couramment utilisé, lisible par machine"), et les documents (contrats,
 * justificatifs...) sont listés par leur RÉFÉRENCE (nom, catégorie, chemin de stockage) plutôt que
 * leur contenu réembarqué : générer une URL signée pour chaque fichier au moment de l'export
 * ralentirait l'opération pour peu de valeur (les fichiers restent téléchargeables individuellement
 * depuis les fiches salariés). À enrichir si Betty en a besoin. */
function renderExportDonneesCard(user) {
  if (!hasPermission(user, PERMISSIONS.GERER_PARAMETRES)) return '';
  return `
    <div class="card">
      <h2>Réversibilité des données</h2>
      <p class="text-muted">Exportez l'intégralité des données de votre entreprise (salariés, congés, télétravail, notes de frais, documents, tickets, entretiens, idées, journal d'audit) dans un fichier JSON structuré, indépendamment de Nexus RH.</p>
      <button type="button" class="btn btn-secondary" id="btn-export-toutes-donnees">Exporter toutes les données</button>
    </div>
  `;
}

/** Tarifs affichés (mensuel/annuel, remise ~2 mois offerts sur l'annuel) — doivent correspondre
 * exactement aux Price ID Stripe configurés dans supabase/functions/billing/index.ts. Offre "essai"
 * volontairement absente ici : gratuite, jamais "souscrite" via Stripe. */
const OFFRE_TARIFS = {
  essentiel: { label: 'Essentiel', mensuel: 29, annuel: 290 },
  professionnel: { label: 'Professionnel', mensuel: 79, annuel: 790 },
  premium: { label: 'Premium', mensuel: 149, annuel: 1490 }
};

/** Présentation (icône, accroche, mise en avant) — purement visuel, séparé de OFFRE_TARIFS/
 * OFFRES_BERTOLIS pour ne pas mélanger la donnée de facturation avec le texte marketing. Pas de
 * fonctionnalité listée par offre : le produit ne différencie réellement les offres que par le
 * nombre de salariés (voir le commentaire au-dessus de OFFRES_BERTOLIS, data.js) — toutes les
 * fonctionnalités du logiciel sont incluses dans les 3 offres payantes, inutile de le prétendre autrement. */
const OFFRE_PRESENTATION = {
  essentiel: { icon: ICONS.leaf, accroche: "Pour démarrer avec une petite équipe." },
  professionnel: { icon: ICONS.rocket, accroche: 'Pour une entreprise en croissance.', misEnAvant: true },
  // conditionLabel : nombreSalariesMax vaut null (illimité) pour Premium, mais "25 salariés et
  // plus" reflète mieux à qui l'offre s'adresse (au-delà du plafond Professionnel, fixé à 25) qu'un
  // vague "illimité" — voir renderParametresAbonnement, qui l'utilise à la place du texte générique.
  premium: { icon: ICONS.crown, accroche: 'Pour une grande structure, sans limite de salariés.', conditionLabel: '25 salariés et plus' }
};

/** Une seule carte d'offre, réutilisée par l'écran Paramètres > Abonnement ET par la page
 * d'accueil publique (renderLandingScreen) — même présentation partout, un seul endroit à modifier
 * si le contenu marketing change. `ctaHtml` diffère selon le contexte (bouton Souscrire vs badge
 * "Offre actuelle" vs simple lien vers la création de compte). */
function renderOffreCard(key, o, periodicite, ctaHtml, extraClass = '') {
  const presentation = OFFRE_PRESENTATION[key] || {};
  const plafondOffre = OFFRES_BERTOLIS[key] ? OFFRES_BERTOLIS[key].nombreSalariesMax : null;
  const mensualise = periodicite === 'annuel' ? `soit ${formatCurrencyFR(o.annuel / 12)}/mois` : '';
  return `
    <div class="offre-card ${extraClass} ${presentation.misEnAvant ? 'offre-card-recommandee' : ''}" data-offre-key="${key}">
      ${presentation.misEnAvant ? '<div class="offre-card-ribbon">Recommandée</div>' : ''}
      <div class="offre-card-match-badge">Pour votre équipe</div>
      <div class="offre-card-icon">${escapeIcon(presentation.icon || ICONS.card)}</div>
      <h3>${escapeHtml(o.label)}</h3>
      <p class="text-muted offre-card-accroche">${escapeHtml(presentation.accroche || '')}</p>
      <p class="offre-prix">${o[periodicite]} € <span class="text-muted">/ ${periodicite === 'annuel' ? 'an' : 'mois'}</span></p>
      ${mensualise ? `<p class="text-muted offre-card-mensualise">${mensualise}</p>` : ''}
      <div class="offre-card-condition">
        ${icon(ICONS.people, 14)} ${presentation.conditionLabel || (plafondOffre === null ? 'Salariés illimités' : `Jusqu'à ${plafondOffre} salariés`)}
      </div>
      ${ctaHtml}
    </div>
  `;
}

/** Paiement réel via Stripe (voir billingRepository/supabase/functions/billing). Depuis le
 * 17/08/2026, toute NOUVELLE souscription passe par la formule à la carte (même catalogue de
 * modules que la page publique, voir LANDING_ALACARTE_MODULES) plutôt que l'ancienne grille à 3
 * paliers — celle-ci reste affichée UNIQUEMENT pour une entreprise déjà abonnée sur l'ancien
 * système (aucune migration forcée). On ne propose jamais le compositeur à la carte à une
 * entreprise déjà sur l'ancien système : relancer un Checkout dessus créerait un second abonnement
 * Stripe en parallèle plutôt que de remplacer le premier (voir la note affichée dans ce cas). */
function renderParametresAbonnement() {
  const company = companyRepository.getCurrent();
  const abo = company.abonnement;
  if (!abo) return '<p class="text-muted">Abonnement indisponible.</p>';
  const nbSalaries = employeeRepository.getAll().filter(e => !e.archive).length;
  const statutBadge = { actif: 'success', impaye: 'warning', suspendu: 'warning', resilie: 'muted', non_souscrit: 'warning' }[abo.statut] || 'muted';
  const estAlaCarte = abo.offre === 'a_la_carte';
  const legacyActif = !estAlaCarte && abo.offre !== 'essai' && abo.statut !== 'resilie';

  if (estAlaCarte) {
    return state.abonnementEditingModules
      ? renderAbonnementAlaCarteComposer(nbSalaries, { mode: 'modifier' })
      : renderAbonnementAlaCarteActif(abo, nbSalaries, statutBadge);
  }
  if (legacyActif) return renderAbonnementLegacyActif(abo, statutBadge);
  return renderAbonnementAlaCarteComposer(nbSalaries);
}

function renderAbonnementAlaCarteActif(abo, nbSalaries, statutBadge) {
  const modules = (abo.modules || [])
    .map(m => Object.assign({}, m, { def: LANDING_ALACARTE_MODULES.find(d => d.key === m.key) }))
    .filter(m => m.def);
  const totalMensuel = modules.reduce((sum, m) => sum + m.def.prix * m.quantite, 0);
  const effectifDesaligne = modules.some(m => m.quantite > nbSalaries);

  return `
    <div class="card abonnement-summary-card">
      <div class="abonnement-summary-header">
        <div class="abonnement-summary-icon">${ICONS.puzzle}</div>
        <div>
          <h2 style="margin-bottom: 4px;">Abonnement à la carte</h2>
          <div class="badge-row">
            <span class="badge badge-${statutBadge}">${escapeHtml(ABONNEMENT_STATUT_LABELS[abo.statut] || abo.statut)}</span>
            <span class="badge badge-info">${abo.periodicite === 'annuel' ? 'Facturation annuelle' : 'Facturation mensuelle'}</span>
          </div>
        </div>
      </div>
      <div class="detail-grid" style="margin-top: 16px;">
        ${infoRow('Date de début', formatDate(abo.dateDebut))}
        ${infoRow('Prochain renouvellement', abo.dateRenouvellement ? formatDate(abo.dateRenouvellement) : '—')}
        ${infoRow('Nombre de salariés actifs', `${nbSalaries}`)}
        ${infoRow('Coût estimé', `${formatCurrencyFR(abo.periodicite === 'annuel' ? totalMensuel * 10 : totalMensuel)} / ${abo.periodicite === 'annuel' ? 'an' : 'mois'}`)}
      </div>
      <table class="table" style="margin-top: 16px;">
        <thead><tr><th>Module actif</th><th>Quantité facturée</th><th>Prix</th><th></th></tr></thead>
        <tbody>
          ${modules.map(m => {
            const licence = LICENSED_MODULE_KEYS.includes(m.key) ? licenseSummaryForModule(m.key, m.quantite) : null;
            return `
            <tr>
              <td>${escapeHtml(m.def.label)}</td>
              <td>
                ${m.quantite} ${escapeHtml(m.def.unite)}${m.quantite > 1 ? 's' : ''}
                <span style="display:inline-flex; align-items:center; gap:6px; margin-left:8px;">
                  <input type="number" class="input" id="abo-quantite-${m.key}" min="1" max="${nbSalaries}" value="${m.quantite}" style="width:70px;">
                  <button type="button" class="btn-link" data-update-module-quantite="${m.key}">Mettre à jour</button>
                </span>
              </td>
              <td>${formatCurrencyFR(m.def.prix)} / ${escapeHtml(m.def.unite)} / mois</td>
              <td>
                ${licence ? `
                  <span class="badge badge-${licence.assigned >= licence.quantite ? 'warning' : 'muted'}" style="margin-right:8px;">${licence.assigned}/${licence.quantite} attribuées</span>
                  <button type="button" class="btn-link" data-gerer-licences="${m.key}">Gérer les accès</button>
                ` : ''}
              </td>
            </tr>
          `;
          }).join('')}
        </tbody>
      </table>
      ${effectifDesaligne ? `
        <div style="margin-top: 16px; padding: 10px 14px; border-radius: var(--radius-md); background: var(--color-warning-soft); color: var(--color-warning); font-size: 14px;">
          ${icon(ICONS.warningTriangle, 14)} La facturation ne correspond plus à votre effectif actuel (${nbSalaries} salarié${nbSalaries > 1 ? 's' : ''} actif${nbSalaries > 1 ? 's' : ''}). Actualisez votre abonnement pour l'aligner.
        </div>
      ` : ''}
      <div class="detail-header-actions" style="margin-top: 16px;">
        <button class="btn btn-secondary" id="btn-resync-abonnement">Actualiser mon abonnement</button>
        <button class="btn btn-primary" id="btn-modifier-modules-alacarte">Modifier mes modules</button>
        <button class="btn btn-secondary" id="btn-gerer-abonnement">Gérer mon abonnement</button>
      </div>
      <p class="text-muted" style="margin-top: 8px;">Pour annuler complètement l'abonnement, utilisez "Gérer mon abonnement" (portail Stripe sécurisé).</p>
    </div>
  `;
}

function renderAbonnementLegacyActif(abo, statutBadge) {
  const offre = OFFRES_BERTOLIS[abo.offre] || OFFRES_BERTOLIS.essai;
  const nbSalaries = employeeRepository.getAll().filter(e => !e.archive).length;
  const plafondActuel = abo.nombreSalariesMax;
  const plafondLabel = plafondActuel === null ? `${nbSalaries} (illimité)` : `${nbSalaries} / ${plafondActuel}`;
  const jaugePct = plafondActuel === null ? 0 : Math.min(100, Math.round((nbSalaries / plafondActuel) * 100));

  return `
    <div class="card abonnement-summary-card">
      <div class="abonnement-summary-header">
        <div class="abonnement-summary-icon">${escapeIcon((OFFRE_PRESENTATION[abo.offre] || {}).icon || ICONS.card)}</div>
        <div>
          <h2 style="margin-bottom: 4px;">${escapeHtml(offre.label)}</h2>
          <div class="badge-row">
            <span class="badge badge-${statutBadge}">${escapeHtml(ABONNEMENT_STATUT_LABELS[abo.statut] || abo.statut)}</span>
            <span class="badge badge-info">${abo.periodicite === 'annuel' ? 'Facturation annuelle' : 'Facturation mensuelle'}</span>
          </div>
        </div>
      </div>
      <div class="detail-grid" style="margin-top: 16px;">
        ${infoRow('Date de début', formatDate(abo.dateDebut))}
        ${infoRow('Prochain renouvellement', abo.dateRenouvellement ? formatDate(abo.dateRenouvellement) : '—')}
      </div>
      <div class="abonnement-jauge">
        <div class="abonnement-jauge-label">
          <span>Salariés actifs</span>
          <strong>${plafondLabel}</strong>
        </div>
        ${plafondActuel !== null ? `<div class="abonnement-jauge-bar"><div class="abonnement-jauge-fill" style="width: ${jaugePct}%;"></div></div>` : ''}
      </div>
      <button class="btn btn-secondary" id="btn-gerer-abonnement" style="margin-top: 16px;">Gérer mon abonnement</button>
    </div>
    <div class="card">
      <h2>Passer à la formule à la carte</h2>
      <p class="text-muted">Nexus RH propose désormais une tarification à la carte, module par module. Pour basculer votre abonnement existant sans double facturation, contactez-nous : nous nous occupons du changement.</p>
    </div>
  `;
}

function renderAbonnementAlaCarteComposer(nbSalaries, options) {
  const editing = Boolean(options && options.mode === 'modifier');
  const periodicite = state.abonnementPeriodicite === 'annuel' ? 'annuel' : 'mensuel';
  return `
    <div class="card">
      <h2>${editing ? 'Modifier mes modules' : 'Composez votre abonnement'}</h2>
      <p class="text-muted">${editing
        ? 'Ajoutez, retirez un module ou changez de périodicité : le changement s\'applique immédiatement, avec un prorata sur la facture en cours.'
        : 'Choisissez uniquement les modules dont vous avez besoin, le prix s\'ajuste en direct. Paiement sécurisé par Stripe, résiliable à tout moment.'}</p>
      <p class="text-muted"><strong>${nbSalaries}</strong> salarié${nbSalaries > 1 ? 's' : ''} actif${nbSalaries > 1 ? 's' : ''} : point de départ de chaque module ci-dessous, ajustez librement le nombre de salariés concernés par chacun.</p>
      <div class="tabs" style="margin: 12px 0;">
        <button class="tab ${periodicite === 'mensuel' ? 'active' : ''}" data-abonnement-periodicite="mensuel">Mensuel</button>
        <button class="tab ${periodicite === 'annuel' ? 'active' : ''}" data-abonnement-periodicite="annuel">Annuel (2 mois offerts)</button>
      </div>
      <div class="alacarte-builder">
        <div class="alacarte-modules">
          ${LANDING_ALACARTE_MODULES.map(m => `
            <div class="alacarte-module">
              <label class="alacarte-module-main">
                <input type="checkbox" class="abo-alacarte-module-checkbox" data-module-key="${m.key}" data-module-price="${m.prix}" data-module-unite="${m.unite}" ${(state.abonnementAlacarteModules && state.abonnementAlacarteModules[m.key] === false) ? '' : 'checked'}>
                <span class="alacarte-module-name">${escapeHtml(m.label)}</span>
                <span class="alacarte-module-price">${formatCurrencyFR(m.prix)} <span class="text-muted">/ ${escapeHtml(m.unite)} / mois</span></span>
              </label>
              <div class="alacarte-module-unit-count">
                <label for="abo-alacarte-count-${m.key}">${m.unite === 'déclarant' ? 'Combien de salariés déposent des notes de frais ?' : `Combien de salariés auront "${escapeHtml(m.label)}" ?`}</label>
                <input type="number" id="abo-alacarte-count-${m.key}" class="input abo-alacarte-count-input" data-count-for="${m.key}" min="1" max="${nbSalaries}" value="${Math.min(nbSalaries, (state.abonnementAlacarteCounts && state.abonnementAlacarteCounts[m.key]) || nbSalaries)}">
              </div>
            </div>
          `).join('')}
        </div>
        <div class="alacarte-total-card">
          <span class="alacarte-total-label">${periodicite === 'annuel' ? 'Coût annuel estimé' : 'Coût mensuel estimé'}</span>
          <strong id="abo-alacarte-total">—</strong>
          <p class="alacarte-discount-note" id="abo-alacarte-discount-note"></p>
          <p class="landing-simulator-note">${editing ? 'Estimation : le montant exact (prorata) est confirmé par Stripe.' : 'Estimation : le montant exact est confirmé par Stripe avant tout paiement.'}</p>
          <button type="button" class="btn btn-primary" style="width: 100%; margin-top: 8px;" id="${editing ? 'btn-enregistrer-modules-alacarte' : 'btn-souscrire-alacarte'}">${editing ? 'Enregistrer les modifications' : 'Souscrire'}</button>
          ${editing ? `<button type="button" class="btn btn-secondary" style="width: 100%; margin-top: 8px;" id="btn-annuler-modification-modules">Annuler</button>` : ''}
        </div>
      </div>
    </div>
  `;
}

/** Même logique de remise que computeAlacarteTotal() (page publique) mais sur un effectif réel et
 * fixe (pas un curseur ajustable — la facturation réelle suit toujours l'effectif actuel, jamais
 * une valeur que le client pourrait librement taper). */
function computeAbonnementAlacarteTotal(nbSalaries) {
  const totalEl = document.getElementById('abo-alacarte-total');
  if (!totalEl) return;
  const periodicite = state.abonnementPeriodicite === 'annuel' ? 'annuel' : 'mensuel';
  let monthlyTotal = 0;
  document.querySelectorAll('.abo-alacarte-module-checkbox').forEach(cb => {
    if (!cb.checked) return;
    const prix = parseFloat(cb.dataset.modulePrice) || 0;
    const countInput = document.getElementById(`abo-alacarte-count-${cb.dataset.moduleKey}`);
    const count = Math.max(1, Math.min(nbSalaries, parseInt(countInput?.value, 10) || nbSalaries));
    monthlyTotal += prix * count;
  });

  const tier = getAlacarteVolumeDiscount(nbSalaries);
  const discounted = monthlyTotal * (1 - tier.rate);
  totalEl.textContent = formatCurrencyFR(periodicite === 'annuel' ? discounted * 10 : discounted);

  const discountNote = document.getElementById('abo-alacarte-discount-note');
  if (discountNote) {
    discountNote.innerHTML = tier.rate > 0
      ? `${icon(ICONS.percent, 13)} Remise volume de ${Math.round(tier.rate * 100)} % appliquée (${nbSalaries} salariés)`
      : '';
  }
}

function bindParametresAbonnementEvents() {
  document.querySelectorAll('[data-abonnement-periodicite]').forEach(btn => {
    btn.addEventListener('click', () => { state.abonnementPeriodicite = btn.dataset.abonnementPeriodicite; render(); });
  });

  const gererBtn = document.getElementById('btn-gerer-abonnement');
  if (gererBtn) gererBtn.addEventListener('click', async () => {
    gererBtn.disabled = true;
    gererBtn.textContent = 'Redirection...';
    const result = await billingRepository.portal();
    if (!result.success) {
      showToast(result.error || 'Impossible d\'ouvrir le portail de gestion.', 'error');
      gererBtn.disabled = false;
      gererBtn.textContent = 'Gérer mon abonnement';
      return;
    }
    window.location.href = result.url;
  });

  const resyncBtn = document.getElementById('btn-resync-abonnement');
  if (resyncBtn) resyncBtn.addEventListener('click', async () => {
    resyncBtn.disabled = true;
    resyncBtn.textContent = 'Actualisation...';
    const result = await billingRepository.resync();
    if (!result.success) {
      showToast(result.error || 'Impossible d\'actualiser l\'abonnement.', 'error');
      resyncBtn.disabled = false;
      resyncBtn.textContent = 'Actualiser mon abonnement';
      return;
    }
    const company = await window.SupabaseSync.hydrateCurrentCompany();
    if (company) DB._companiesCache = [company];
    showToast('Abonnement actualisé.');
    render();
  });

  document.querySelectorAll('[data-update-module-quantite]').forEach(btn => {
    btn.addEventListener('click', async () => {
      const key = btn.dataset.updateModuleQuantite;
      const input = document.getElementById(`abo-quantite-${key}`);
      const quantite = Math.max(1, parseInt(input?.value, 10) || 1);
      const poursuivre = await ensureLicenseCapacity(key, quantite);
      if (!poursuivre) return;
      btn.disabled = true;
      btn.textContent = '...';
      const result = await billingRepository.resync({ [key]: quantite });
      if (!result.success) {
        showToast(result.error || 'Impossible de mettre à jour ce module.', 'error');
        btn.disabled = false;
        btn.textContent = 'Mettre à jour';
        return;
      }
      const company = await window.SupabaseSync.hydrateCurrentCompany();
      if (company) DB._companiesCache = [company];
      showToast('Module mis à jour.');
      render();
    });
  });

  document.querySelectorAll('[data-gerer-licences]').forEach(btn => {
    btn.addEventListener('click', () => openGererLicencesModal(btn.dataset.gererLicences));
  });

  const nbSalaries = employeeRepository.getAll().filter(e => !e.archive).length;
  if (document.getElementById('abo-alacarte-total')) {
    computeAbonnementAlacarteTotal(nbSalaries);
    document.querySelectorAll('.abo-alacarte-module-checkbox').forEach(cb => {
      cb.addEventListener('change', () => {
        state.abonnementAlacarteModules = state.abonnementAlacarteModules || {};
        state.abonnementAlacarteModules[cb.dataset.moduleKey] = cb.checked;
        computeAbonnementAlacarteTotal(nbSalaries);
      });
    });
    document.querySelectorAll('.abo-alacarte-count-input').forEach(input => {
      input.addEventListener('input', () => {
        state.abonnementAlacarteCounts = state.abonnementAlacarteCounts || {};
        state.abonnementAlacarteCounts[input.dataset.countFor] = parseInt(input.value, 10) || 1;
        computeAbonnementAlacarteTotal(nbSalaries);
      });
    });
  }

  const modifierModulesBtn = document.getElementById('btn-modifier-modules-alacarte');
  if (modifierModulesBtn) modifierModulesBtn.addEventListener('click', () => {
    const abo = companyRepository.getCurrent().abonnement;
    // Pré-remplir le compositeur avec les modules réellement ACTIFS plutôt que l'état par défaut
    // (tout coché) — sinon "Modifier mes modules" repartirait toujours de zéro au lieu de refléter
    // l'abonnement en cours.
    state.abonnementPeriodicite = abo.periodicite === 'annuel' ? 'annuel' : 'mensuel';
    state.abonnementAlacarteModules = {};
    LANDING_ALACARTE_MODULES.forEach(m => {
      state.abonnementAlacarteModules[m.key] = (abo.modules || []).some(am => am.key === m.key);
    });
    state.abonnementAlacarteCounts = {};
    (abo.modules || []).forEach(am => { state.abonnementAlacarteCounts[am.key] = am.quantite; });
    state.abonnementEditingModules = true;
    render();
  });

  const annulerModifBtn = document.getElementById('btn-annuler-modification-modules');
  if (annulerModifBtn) annulerModifBtn.addEventListener('click', () => {
    state.abonnementEditingModules = false;
    render();
  });

  const enregistrerModulesBtn = document.getElementById('btn-enregistrer-modules-alacarte');
  if (enregistrerModulesBtn) enregistrerModulesBtn.addEventListener('click', async () => {
    const modules = [];
    document.querySelectorAll('.abo-alacarte-module-checkbox').forEach(cb => {
      if (!cb.checked) return;
      const key = cb.dataset.moduleKey;
      const countInput = document.getElementById(`abo-alacarte-count-${key}`);
      modules.push({ key, quantite: Math.max(1, parseInt(countInput?.value, 10) || 1) });
    });
    if (!modules.length) {
      showToast('Sélectionnez au moins un module. Pour tout annuler, utilisez "Gérer mon abonnement".', 'error');
      return;
    }
    // §retour Betty du 18/09/2026 : "jamais auto-choisir" qui perd son accès si la quantité baisse
    // (ou si le module est décoché, ce qui revient à une quantité de 0) — vérifier module par module
    // AVANT d'appeler Stripe, dans l'ordre où ils apparaissent dans le composeur.
    for (const key of LICENSED_MODULE_KEYS) {
      const cible = modules.find(m => m.key === key);
      const poursuivre = await ensureLicenseCapacity(key, cible ? cible.quantite : 0);
      if (!poursuivre) return;
    }
    enregistrerModulesBtn.disabled = true;
    enregistrerModulesBtn.textContent = 'Enregistrement...';
    const periodicite = state.abonnementPeriodicite === 'annuel' ? 'annuel' : 'mensuel';
    const result = await billingRepository.updateModules(modules, periodicite);
    if (!result.success) {
      showToast(result.error || 'Impossible de mettre à jour l\'abonnement.', 'error');
      enregistrerModulesBtn.disabled = false;
      enregistrerModulesBtn.textContent = 'Enregistrer les modifications';
      return;
    }
    const company = await window.SupabaseSync.hydrateCurrentCompany();
    if (company) DB._companiesCache = [company];
    state.abonnementEditingModules = false;
    showToast('Modules mis à jour.');
    // §retour Betty du 11/09/2026 ("le module ne s'affiche pas") : render() seul ne redessine QUE
    // #view-root (voir render()/renderInner) — la barre latérale (nouvelle entrée de menu du module
    // tout juste activé) a sa propre fonction, jamais appelée ici jusqu'à présent. Le premier
    // "checkout" (nouvel abonnement) l'appelait déjà correctement via navigateTo() côté retour de
    // Stripe (handleCheckoutReturn) — seul ce chemin "ajouter un module à un abonnement déjà actif"
    // l'oubliait.
    renderSidebar();
    render();
  });

  const souscrireBtn = document.getElementById('btn-souscrire-alacarte');
  if (souscrireBtn) souscrireBtn.addEventListener('click', async () => {
    const modules = [];
    document.querySelectorAll('.abo-alacarte-module-checkbox').forEach(cb => {
      if (!cb.checked) return;
      const key = cb.dataset.moduleKey;
      const countInput = document.getElementById(`abo-alacarte-count-${key}`);
      modules.push({ key, quantite: Math.max(1, parseInt(countInput?.value, 10) || 1) });
    });
    if (!modules.length) {
      showToast('Sélectionnez au moins un module.', 'error');
      return;
    }
    souscrireBtn.disabled = true;
    souscrireBtn.textContent = 'Redirection...';
    const periodicite = state.abonnementPeriodicite === 'annuel' ? 'annuel' : 'mensuel';
    const result = await billingRepository.checkout(modules, periodicite);
    if (!result.success) {
      showToast(result.error || 'Impossible de démarrer le paiement.', 'error');
      souscrireBtn.disabled = false;
      souscrireBtn.textContent = 'Souscrire';
      return;
    }
    window.location.href = result.url;
  });
}

function bindParametresEntrepriseEvents() {
  bindConventionCollectiveAutocomplete();

  // §retour Betty du 18/09/2026 (point 4) : le lien Légifrance ne doit pas attendre que quelqu'un
  // ressaisisse le SIRET (déjà en place pour toute entreprise existante) — un aller simple, une
  // seule fois par ouverture de cet écran si jamais encore récupéré, sans jamais toucher au champ
  // Convention collective lui-même (juste le lien, voir fetchConventionCollectiveFromSiret).
  const settingsInitiaux = settingsRepository.getSettings();
  const siretActuel = (companyRepository.getProfile().siret || '').replace(/\s/g, '');
  if (!settingsInitiaux.conventionCollectiveLegifranceUrl && /^\d{14}$/.test(siretActuel)) {
    fetchConventionCollectiveFromSiret(siretActuel).then(convention => {
      if (!convention || !convention.url) return;
      const settingsAJour = settingsRepository.getSettings();
      settingsAJour.conventionCollectiveLegifranceUrl = convention.url;
      settingsRepository.saveSettings(settingsAJour);
      // Jamais render() ici : un ré-rendu complet effacerait toute saisie en cours sur ce même
      // formulaire depuis l'ouverture de l'écran (le délai réseau n'est pas instantané). Le lien
      // est juste inséré directement s'il n'existe pas déjà, sans toucher au reste du formulaire.
      const form = document.getElementById('entreprise-form');
      if (form && !document.getElementById('lien-legifrance-accords')) {
        const p = document.createElement('p');
        p.className = 'form-hint';
        p.id = 'lien-legifrance-accords';
        p.innerHTML = `<a href="${escapeHtml(convention.url)}" target="_blank" rel="noopener noreferrer">Voir mes accords d'entreprise (Légifrance)</a>`;
        const suggestionEl = document.getElementById('convention-suggestion');
        if (suggestionEl) suggestionEl.insertAdjacentElement('afterend', p);
      }
    });
  }

  document.getElementById('entreprise-form').addEventListener('submit', (evt) => {
    evt.preventDefault();
    const formData = new FormData(evt.target);
    companyRepository.saveProfile({
      raisonSociale: formData.get('raisonSociale'),
      siret: formData.get('siret'),
      tva: formData.get('tva'),
      adresse: formData.get('adresse'),
      telephone: formData.get('telephone'),
      email: formData.get('email'),
      conventionCollective: formData.get('conventionCollective')
    });
    showToast('Profil de l\'entreprise mis à jour.');
    render();
  });

  const logoUploadInput = document.getElementById('f-logo-upload');
  document.getElementById('btn-upload-logo').addEventListener('click', () => logoUploadInput.click());
  logoUploadInput.addEventListener('change', async () => {
    const file = logoUploadInput.files[0];
    if (!file) return;
    try {
      await companyRepository.uploadLogo(file);
      showToast('Logo mis à jour.');
      render();
    } catch (err) {
      showToast(err.message || 'Impossible de mettre à jour le logo.', 'error');
    }
  });

  const exportBtn = document.getElementById('btn-export-toutes-donnees');
  if (exportBtn) exportBtn.addEventListener('click', handleExportToutesDonnees);
}

/** Voir renderExportDonneesCard ci-dessus pour le contexte/le scope de cet export. */
async function handleExportToutesDonnees() {
  const btn = document.getElementById('btn-export-toutes-donnees');
  const libelleInitial = btn.textContent;
  btn.disabled = true;
  btn.textContent = 'Export en cours...';
  try {
    const company = companyRepository.getCurrent();
    const data = await window.SupabaseSync.fetchFullCompanyExportData(company.id);
    const dateFichier = new Date().toISOString().slice(0, 10);
    downloadJSONFile(data, `export-${(company.raisonSociale || 'entreprise').toLowerCase().replace(/[^a-z0-9]+/g, '-')}-${dateFichier}.json`);
    auditLogRepository.logAudit('Export', 'Réversibilité', 'Export complet des données de l\'entreprise');
    showToast('Export généré.');
  } catch (err) {
    showToast(err.message || 'Impossible de générer l\'export.', 'error');
  } finally {
    btn.disabled = false;
    btn.textContent = libelleInitial;
  }
}

