function renderParametresAudit() {
  const filters = state.auditFilters;
  const total = auditLogRepository.getAuditLog().length;
  const log = getFilteredAuditLog();
  const { pageItems, totalPages, page, pageStart } = paginate(log, 'auditPage');

  return `
    <div class="card table-card">
      <div class="view-header-row" style="padding: 20px 20px 0;">
        <div>
          <h2>Journal d'audit</h2>
          <p class="text-muted">${log.length} événement${log.length > 1 ? 's' : ''} sur ${total} au total</p>
        </div>
        <button class="btn btn-secondary btn-sm" id="btn-export-audit">Exporter CSV</button>
      </div>
      <div class="toolbar card" style="margin: 12px 20px 0;">
        <input type="text" id="audit-filter-search" class="input" placeholder="Rechercher (entité, cible, détails)..." value="${escapeHtml(filters.search)}">
        <select id="audit-filter-action" class="input">
          <option value="">Toutes les actions</option>
          ${AUDIT_ACTIONS.map(a => `<option value="${a}" ${filters.action === a ? 'selected' : ''}>${a}</option>`).join('')}
        </select>
        <input type="date" id="audit-filter-date-debut" class="input" value="${escapeHtml(filters.dateDebut)}" title="Depuis le">
        <input type="date" id="audit-filter-date-fin" class="input" value="${escapeHtml(filters.dateFin)}" title="Jusqu'au">
      </div>
      ${log.length === 0 ? `<div class="empty-state"><div class="empty-icon">${ICONS.cabinet}</div><p>Aucun événement ne correspond à ces filtres.</p></div>` : `
        <table class="table">
          <thead><tr><th>Date</th><th>Action</th><th>Entité</th><th>Cible</th><th>Par</th><th>Détails</th></tr></thead>
          <tbody>
            ${pageItems.map(entry => `
              <tr>
                <td>${formatDateTime(entry.date)}</td>
                <td>${auditActionBadge(entry.action)}</td>
                <td>${escapeHtml(entry.entite)}</td>
                <td>${escapeHtml(entry.cible)}</td>
                <td class="text-muted">${escapeHtml(entry.auteur || '—')}</td>
                <td class="text-muted">${escapeHtml(entry.details || '—')}</td>
              </tr>
            `).join('')}
          </tbody>
        </table>
        ${renderPaginationControls(page, totalPages, pageStart, pageItems.length, log.length)}
      `}
    </div>
  `;
}

function auditActionBadge(action) {
  const map = { 'Création': 'success', 'Modification': 'info', 'Suppression': 'warning', 'Validation': 'success', 'Refus': 'muted', 'Annulation': 'muted', 'Export': 'info', 'Connexion': 'warning' };
  return `<span class="badge badge-${map[action] || 'muted'}">${escapeHtml(action)}</span>`;
}

function bindParametresAuditEvents() {
  document.getElementById('btn-export-audit').addEventListener('click', exportAuditLogCSV);

  document.getElementById('audit-filter-search').addEventListener('input', (e) => {
    state.auditFilters.search = e.target.value;
    state.auditPage = 1;
    render();
    document.getElementById('audit-filter-search').focus();
    const pos = e.target.selectionStart;
    document.getElementById('audit-filter-search').setSelectionRange(pos, pos);
  });
  document.getElementById('audit-filter-action').addEventListener('change', (e) => {
    state.auditFilters.action = e.target.value;
    state.auditPage = 1;
    render();
  });
  document.getElementById('audit-filter-date-debut').addEventListener('change', (e) => {
    state.auditFilters.dateDebut = e.target.value;
    state.auditPage = 1;
    render();
  });
  document.getElementById('audit-filter-date-fin').addEventListener('change', (e) => {
    state.auditFilters.dateFin = e.target.value;
    state.auditPage = 1;
    render();
  });

  const prevBtn = document.getElementById('btn-page-prev');
  if (prevBtn) prevBtn.addEventListener('click', () => { state.auditPage -= 1; render(); });
  const nextBtn = document.getElementById('btn-page-next');
  if (nextBtn) nextBtn.addEventListener('click', () => { state.auditPage += 1; render(); });
}

function exportAuditLogCSV() {
  const log = getFilteredAuditLog();
  const headers = ['Date', 'Action', 'Entité', 'Cible', 'Par', 'Détails'];
  const rows = log.map(e => [formatDateTime(e.date), e.action, e.entite, e.cible, e.auteur || '', e.details]);
  exportRowsToCSV(headers, rows, 'journal-audit.csv');
  auditLogRepository.logAudit('Export', 'Journal d\'audit', `${log.length} événements`);
}

// ---------------------------------------------------------------------------
// Vue : Planning des absences (semaine / mois / année, tous types confondus)
// ---------------------------------------------------------------------------

/** §demande Betty du 10/09/2026 ("que ce soit affiché dans le planning équipe et calendrier
 * entreprise") : une demi-journée de congé se pose déjà (openLeaveRequestModal, `demiJournee` pour
 * un jour isolé ou `demiJourneeDebut`/`demiJourneeFin` pour le premier/dernier jour d'une période),
 * mais rien ne le signalait sur ces deux écrans — seul le nom du type de congé y apparaissait, comme
 * pour une journée complète. Renvoie 'matin'/'apres-midi' pour LA date précise concernée (jamais pour
 * un jour intermédiaire d'une période à cheval sur plusieurs jours, qui reste bien une journée
 * complète), ou null sinon — réutilisé à la fois par le Planning (par jour) et le Calendrier des
 * absences (sur les jours de début/fin d'un segment). */
function getHalfDayForDate(request, dateStr) {
  if (!request) return null;
  if (request.demiJournee && request.dateDebut === request.dateFin && dateStr === request.dateDebut) return request.demiJournee;
  if (request.demiJourneeDebut === 'apres-midi' && dateStr === request.dateDebut) return 'apres-midi';
  if (request.demiJourneeFin === 'matin' && dateStr === request.dateFin) return 'matin';
  return null;
}

/** Statut d'un salarié à une date donnée, tous types d'absence confondus (congé ou télétravail).
 * Sprint SIRH premium §2 : `leaveRequests`/`teleworkRequests` peuvent désormais inclure des demandes
 * "En attente" (pas seulement "Validé") — `pending: true` permet à l'affichage de les distinguer
 * visuellement (semi-transparent) plutôt que de les rendre invisibles comme avant. */
function getStatusForDate(employee, dateStr, leaveRequests, teleworkRequests) {
  const weekday = WEEKDAY_LABELS[(parseISODateLocal(dateStr).getDay() + 6) % 7];
  if (!(employee.joursTravailles || []).includes(weekday)) {
    return { icon: '—', level: 'off', title: 'Non travaillé' };
  }

  const onLeave = leaveRequests.find(r => r.employeeId === employee.id && dateStr >= r.dateDebut && dateStr <= r.dateFin);
  if (onLeave) {
    const type = leaveTypeRepository.getLeaveTypeById(onLeave.typeId);
    const pending = onLeave.statut !== 'Validé';
    const halfDay = getHalfDayForDate(onLeave, dateStr);
    const halfDaySuffix = halfDay ? ` (${halfDay === 'matin' ? 'matin' : 'après-midi'})` : '';
    return { icon: type ? type.icone : ICONS.sun, level: 'leave', title: `${type ? type.nom : 'Congé'}${halfDaySuffix}${pending ? ' (en attente)' : ''}`, pending, requestId: onLeave.id, requestType: 'leave' };
  }

  const onTelework = teleworkRequests.find(r => r.employeeId === employee.id && dateStr >= r.dateDebut && dateStr <= r.dateFin);
  if (onTelework) {
    const pending = onTelework.statut !== 'Validé';
    return { icon: ICONS.laptop, level: 'remote', title: `Télétravail${pending ? ' (en attente)' : ''}`, pending, requestId: onTelework.id, requestType: 'telework' };
  }

  return { icon: ICONS.building, level: 'office', title: 'Présent' };
}

/** Un salarié a-t-il été en poste à un moment quelconque de [periodStart, periodEnd] (dates ISO) ?
 * Utilisé partout où l'on peut naviguer vers une période PASSÉE (export paie, tickets restaurant,
 * plannings) — filtrer sur le statut ACTUEL du salarié y ferait disparaître à tort quelqu'un parti
 * (ou pas encore arrivé) qui était pourtant bien présent durant la période affichée. */
function isEmployedDuringPeriod(employee, periodStart, periodEnd) {
  return Boolean(employee.dateEmbauche) && employee.dateEmbauche <= periodEnd &&
    (!employee.dateDepart || employee.dateDepart >= periodStart);
}

function getPlanningEmployees(periodStart, periodEnd) {
  const user = authRepository.getCurrentUser();
  // Sprint SIRH premium §5 : "Mon planning" (espace Personnel) restreint à l'utilisateur courant
  // seul, quel que soit son rôle — même principe que calendrierVue (§2).
  const visibleIds = (user.role !== ROLES.SALARIE && state.planningVue === 'personnel') ? [user.id] : getVisibleEmployeeIdsForCurrentUser();
  let employees = employeeRepository.getAll().filter(e => !e.archive && isEmployedDuringPeriod(e, periodStart, periodEnd));
  if (visibleIds !== null) employees = employees.filter(e => visibleIds.includes(e.id));
  if (state.planningFilters.service) employees = employees.filter(e => e.service === state.planningFilters.service);
  return employees;
}

/** §retour Betty du 10/09/2026, en plusieurs temps : "enlève tous les boutons (Semaine/Mois/Année/
 * Horaires...), tu mets juste un endroit avec le même planning" a d'abord fait de Postes une page à
 * part (NAV_ITEMS dédié) — mais "enlève le bouton poste, j'ai pas demandé ce bouton [...] les
 * boutons dans Planning équipe et Moi tu enlève pas, mais les autres" clarifie que la grille doit
 * plutôt REMPLACER le contenu de "Planning" lui-même : garde le bascule Planning équipe/Moi (déjà là
 * avant), retire les onglets Semaine/Mois/Année/Horaires/Astreintes et la barre d'outils (filtre
 * service) qui allaient avec.
 *
 * Les anciennes vues (renderPlanningSemaine/Mois/Annee/Horaires/Astreintes et leurs bindings)
 * restent dans le code, simplement plus reliées à aucun bouton — pas supprimées, au cas où ce
 * remplacement soit reconsidéré (une régression du même ordre que celle-ci ne se réécrit pas en 5
 * minutes si la décision change), mais aucun risque de code mort actif : elles ne sont plus jamais
 * appelées depuis cet écran. */
function renderPlanning() {
  return `
    <div class="view-header">
      <h1>Planning</h1>
      <p class="view-subtitle">Quarts de travail, par salarié.</p>
    </div>
    ${renderMoiEquipeToggle('planningVue', 'equipe', 'Planning équipe')}
    ${renderPlanningPostes()}
  `;
}

/** Sprint SIRH premium §2 : "Regrouper automatiquement les salariés par service" — le filtre
 * planning-filter-service permet toujours de se concentrer sur un seul service, mais la vue par
 * défaut ("Tous les services") doit regrouper visuellement plutôt que lister à plat. Tri
 * alphabétique par nom de service, "Sans service" en dernier. */
function groupEmployeesByService(employees) {
  const groups = {};
  employees.forEach(e => {
    const key = e.service || 'Sans service';
    (groups[key] = groups[key] || []).push(e);
  });
  return Object.keys(groups)
    .sort((a, b) => (a === 'Sans service') - (b === 'Sans service') || a.localeCompare(b))
    .map(service => ({ service, employees: groups[service] }));
}

/** §refonte planning du 04/09/2026 : même regroupement que groupEmployeesByService, avec un niveau de
 * sous-groupe par équipe au sein de chaque service — réutilisé par toutes les vues du planning
 * (Semaine/Mois/Année/Horaires) pour ne jamais diverger d'une vue à l'autre. Le sous-groupe "équipe"
 * n'est affiché que si le service compte réellement plusieurs équipes distinctes ; sinon (personne
 * n'a d'équipe renseignée dans ce service, ou une seule équipe couvre tout le monde) l'entête équipe
 * serait une simple redite du nom du service, donc on la masque (voir usage dans renderPlanningGroupRows). */
function groupEmployeesByServiceAndEquipe(employees) {
  return groupEmployeesByService(employees).map(g => {
    const equipeGroups = {};
    g.employees.forEach(e => {
      const key = e.equipe || 'Sans équipe';
      (equipeGroups[key] = equipeGroups[key] || []).push(e);
    });
    const equipes = Object.keys(equipeGroups)
      .sort((a, b) => (a === 'Sans équipe') - (b === 'Sans équipe') || a.localeCompare(b))
      .map(equipe => ({ equipe, employees: equipeGroups[equipe] }));
    return { service: g.service, employees: g.employees, equipes };
  });
}

/** Rendu générique des lignes d'un tableau du planning, service par service puis équipe par équipe
 * (voir groupEmployeesByServiceAndEquipe) : `renderRow(employee)` doit renvoyer le HTML complet d'une
 * ou plusieurs lignes <tr> pour ce salarié, `colspan` doit couvrir toutes les colonnes du tableau
 * (pour les lignes d'entête service/équipe), `renderServiceSummaryRow` est optionnel (ligne de total
 * par service, ex. Horaires Semaine). */
function renderPlanningGroupRows(employees, colspan, renderRow, renderServiceSummaryRow) {
  return groupEmployeesByServiceAndEquipe(employees).map(g => `
    <tr class="planning-service-header"><td colspan="${colspan}">${escapeHtml(g.service)} <span class="text-muted">(${g.employees.length})</span></td></tr>
    ${g.equipes.map(eq => `
      ${g.equipes.length > 1 ? `<tr class="planning-equipe-header"><td colspan="${colspan}">${escapeHtml(eq.equipe)} <span class="text-muted">(${eq.employees.length})</span></td></tr>` : ''}
      ${eq.employees.map(e => renderRow(e)).join('')}
    `).join('')}
    ${renderServiceSummaryRow ? renderServiceSummaryRow(g) : ''}
  `).join('');
}

/** Nom + poste (si renseigné), utilisé dans le planning équipe pour identifier rapidement qui fait
 * quoi (demande Betty du 04/09/2026) — pas utilisé partout (ex. listes de salariés) pour ne pas
 * alourdir les écrans où le poste est déjà visible ailleurs. */
function personNameWithPosteHtml(e) {
  const poste = getPosteAccorde(e, settingsRepository.getSettings());
  return `${personNameHtml(e)}${poste ? ` <span class="text-muted" style="font-size:12px;">${escapeHtml(poste)}</span>` : ''}`;
}

/** Sprint SIRH premium §3 : "modification par glisser-déposer" — une case de congé/télétravail
 * VALIDÉ (jamais une case en attente, ni "Présent"/"Non travaillé"/"Repos" : rien à déplacer) devient
 * la SOURCE d'un glisser ; TOUTE case du même salarié est une cible de dépôt valide (la case cible
 * n'a pas besoin d'avoir un statut particulier — la validation métier existante, réutilisée telle
 * quelle via bindPlanningDragEvents, refuse déjà les dates invalides avec un message clair).
 *
 * §retour Betty du 09/09/2026 (deux allers-retours) : d'abord "pas le nombre d'heures mais d'une
 * telle heure à une autre, qui est modifiable", puis "il faut qu'il y ait les horaires pour chaque
 * jour" — `showHoraires` affiche donc la vraie plage horaire (formatHorairesRange) sous l'icône de
 * CHAQUE jour travaillé, jamais un jour de congé ou non travaillé. Seule la vue Semaine l'active
 * (voir renderPlanningSemaine) : la vue Mois compte ~30 colonnes déjà étroites, y ajouter du texte
 * la rendrait illisible.
 *
 * §demande Betty du 09/09/2026 ("change le design du planning, style Agendrix") : chaque jour occupé
 * (congé/télétravail/présent) devient une petite carte (fond + accent de couleur à gauche + coins
 * arrondis) au lieu d'un simple aplat de couleur sur toute la cellule — mêmes trois couleurs
 * sémantiques qu'avant (jamais une couleur par service/poste, contrairement au modèle envoyé : la
 * palette bleu marine + or de l'appli reste la même, voir seven_rh_design_palette_rule). La légende
 * (icône + texte) tient dans la carte plutôt qu'à plat dans la cellule, pour un rendu plus proche
 * d'un vrai planning visuel. Un jour de congé affiche aussi son type en légende (ex. "Congés payés"),
 * pas seulement l'icône — la carte serait sinon vide de texte, contrairement aux jours travaillés. */
/** §retour Betty du 10/09/2026 ("tous pareil sauf les couleurs") : le titre déjà calculé par
 * getStatusForDate ("Présent", "Télétravail", nom du congé...) sert directement de légende en gras —
 * même format pour tous les statuts, plutôt qu'une légende différente selon le cas (avant : horaires
 * pour présent/télétravail, titre pour congé). Les horaires viennent en seconde ligne, plus petite,
 * uniquement pour présent/télétravail (un congé n'a pas d'horaires à afficher). */
function renderPlanningStatusCell(employee, dateStr, leaveRequests, teleworkRequests, showHoraires = false) {
  const status = getStatusForDate(employee, dateStr, leaveRequests, teleworkRequests);
  const draggable = (status.level === 'leave' || status.level === 'remote') && !status.pending;
  if (status.level === 'off') {
    // §retour Betty du 10/09/2026 : même case pleine que les autres statuts en vue Semaine (colonnes
    // assez larges) — reste un simple tiret en vue Mois (~30 colonnes déjà étroites, voir plus haut
    // dans l'historique de ce fichier pour ce choix).
    const card = showHoraires
      ? `<div class="planning-shift-card planning-shift-off"><div class="planning-shift-caption">Repos</div></div>`
      : `<span class="planning-off-dash">—</span>`;
    return `<td class="planning-cell" title="${escapeHtml(status.title)}">${card}</td>`;
  }
  // §correctif visuel du 14/09/2026 : "09:00-12:00 · 13:00-17:00" (matin + après-midi détaillés,
  // 25 caractères) se coupait en 4-5 fragments illisibles dans une colonne de jour, aussi étroite
  // que la grille de quarts (même correctif que .poste-shift-pointage — voir renderPlanningPostes).
  // La version courte (premier début → dernière fin) tient sur une ligne dans bien plus de cas ; le
  // détail matin/après-midi complet reste disponible au survol (title), jamais perdu.
  const subtext = showHoraires && (status.level === 'office' || status.level === 'remote') ? formatHorairesRangeCourt(employee) : '';
  const subtextTitle = subtext ? ` title="${escapeHtml(formatHorairesRange(employee))}"` : '';
  const card = showHoraires ? `
    <div class="planning-shift-card planning-shift-${status.level}${status.pending ? ' planning-shift-pending' : ''}">
      <div class="planning-shift-caption">${escapeHtml(status.title)}</div>
      ${subtext ? `<div class="planning-shift-subtext"${subtextTitle}>${escapeHtml(subtext)}</div>` : ''}
      <span class="planning-shift-corner-icon">${escapeIcon(status.icon)}</span>
    </div>
  ` : `
    <div class="planning-shift-card planning-shift-${status.level} planning-shift-icon-only${status.pending ? ' planning-shift-pending' : ''}">
      <div class="planning-shift-icon">${escapeIcon(status.icon)}</div>
    </div>
  `;
  return `<td class="planning-cell"
    title="${escapeHtml(status.title)}"
    data-drop-employee="${employee.id}" data-drop-date="${dateStr}"
    ${draggable ? `draggable="true" data-drag-request-id="${status.requestId}" data-drag-request-type="${status.requestType}" data-drag-employee="${employee.id}" data-drag-date="${dateStr}"` : ''}
  >${card}</td>`;
}

function formatHorairesRange(employee) {
  const matin = employee.horaireMatinDebut && employee.horaireMatinFin ? `${employee.horaireMatinDebut}-${employee.horaireMatinFin}` : null;
  const apresMidi = employee.horaireApresMidiDebut && employee.horaireApresMidiFin ? `${employee.horaireApresMidiDebut}-${employee.horaireApresMidiFin}` : null;
  return [matin, apresMidi].filter(Boolean).join(' · ');
}

/** Version courte de formatHorairesRange (premier début → dernière fin, sans le détail matin/
 * après-midi) — voir renderPlanningStatusCell : le détail complet reste au survol (title), jamais
 * perdu, seulement pas affiché en dur dans une case de planning trop étroite pour lui. */
function formatHorairesRangeCourt(employee) {
  const debut = employee.horaireMatinDebut || employee.horaireApresMidiDebut;
  const fin = employee.horaireApresMidiFin || employee.horaireMatinFin;
  return debut && fin ? `${debut}-${fin}` : '';
}

/** §demande Betty du 10/09/2026 ("même design que [référence Combo], mais les couleurs actuelles") :
 * la référence affiche sous chaque salarié des compteurs (heures contractuelles, solde d'heures,
 * repos compensateur...). Nexus n'a pas d'équivalent exact pour chacun (pas de "solde d'heures"
 * cumulé au sens de la référence) — plutôt que d'inventer une donnée qui n'existe nulle part
 * ailleurs dans l'appli (risqué dans un outil RH), seuls DEUX compteurs RÉELS et déjà existants
 * sont repris : les heures hebdomadaires contractuelles (employee.horairesHebdo, déjà affiché sur la
 * fiche salarié) et le solde de repos compensateur (getReposCompensateurSolde, déjà utilisé au
 * tableau de bord) — masqué si nul, pour ne pas afficher un badge vide à quasi tout le monde. */
function renderPlanningEmployeeBadges(employee) {
  const rcr = getReposCompensateurSolde(employee);
  return `
    <div class="planning-employee-badges">
      <span class="planning-employee-badge" title="Heures hebdomadaires contractuelles">${formatNumberFR(employee.horairesHebdo)} h</span>
      ${rcr.solde ? `<span class="planning-employee-badge planning-employee-badge-rcr" title="Solde de repos compensateur">RCR ${formatNumberFR(rcr.solde)} h</span>` : ''}
    </div>
  `;
}

/** §demande Betty du 10/09/2026 : sur la référence, un congé de plusieurs jours devient une seule
 * barre continue (même esprit que computeAbsenceCalendarSegments/renderAbsenceCalendarRow pour le
 * Calendrier des absences) plutôt qu'une carte répétée à l'identique chaque jour. Regroupe donc les
 * jours consécutifs relevant de LA MÊME demande de congé — le télétravail et la présence restent en
 * revanche case par case (non demandé, et un jour de télétravail isolé au milieu d'une semaine
 * travaillée n'a pas la même continuité "naturelle" qu'un congé). */
function computePlanningLeaveSegments(employee, dateStrs, leaveRequests) {
  const segments = [];
  let current = null;
  dateStrs.forEach(dateStr => {
    const leave = leaveRequests.find(r => r.employeeId === employee.id && dateStr >= r.dateDebut && dateStr <= r.dateFin);
    const key = leave ? leave.id : null;
    if (current && current.key === key) {
      current.dates.push(dateStr);
    } else {
      if (current) segments.push(current);
      current = { key, dates: [dateStr], leave };
    }
  });
  if (current) segments.push(current);
  return segments;
}

/** Rend les cellules d'une ligne de planning pour un salarié sur une liste de dates données —
 * cellule par cellule (renderPlanningStatusCell, inchangé) sauf pour un congé de PLUSIEURS jours
 * consécutifs, fusionné en une seule cellule `colspan`. Reste glissable (le glisser-déposer déplace
 * TOUTE la période d'un coup, cf. handlePlanningDrop qui décale dateDebut/dateFin ensemble via le
 * même deltaJours — aucune perte de fonctionnalité par rapport à l'ancien glisser case par case, tant
 * qu'aucune des cases ne le pointe individuellement) : la source du glisser reste le premier jour de
 * la barre, comme si on glissait sa toute première case. */
function renderPlanningDayCells(employee, dateStrs, leaveRequests, teleworkRequests, showHoraires) {
  const segments = computePlanningLeaveSegments(employee, dateStrs, leaveRequests);
  return segments.map(seg => {
    if (!seg.leave || seg.dates.length === 1) {
      return seg.dates.map(d => renderPlanningStatusCell(employee, d, leaveRequests, teleworkRequests, showHoraires)).join('');
    }
    const startDateStr = seg.dates[0];
    const status = getStatusForDate(employee, startDateStr, leaveRequests, []);
    return `<td colspan="${seg.dates.length}" class="planning-cell planning-leave-bar-cell"
      title="${escapeHtml(status.title)}"
      data-drop-employee="${employee.id}" data-drop-date="${startDateStr}"
      ${!status.pending ? `draggable="true" data-drag-request-id="${status.requestId}" data-drag-request-type="${status.requestType}" data-drag-employee="${employee.id}" data-drag-date="${startDateStr}"` : ''}
    >
      <div class="planning-shift-card planning-shift-leave planning-shift-bar${status.pending ? ' planning-shift-pending' : ''}">
        <div class="planning-shift-caption">${escapeHtml(status.title)}</div>
      </div>
    </td>`;
  }).join('');
}

function renderPlanningSemaine() {
  const weekDates = getWeekDates(state.planningWeekOffset);
  const employees = getPlanningEmployees(toISODate(weekDates[0]), toISODate(weekDates[6]));
  // Sprint SIRH premium §2 : les demandes en attente doivent rester visibles (semi-transparentes,
  // cf. getStatusForDate/renderPlanningStatusCell), pas totalement absentes du planning.
  const leaveRequests = leaveRepository.getAll().filter(r => r.statut === 'Validé' || r.statut === 'En attente');
  const teleworkRequests = teleworkRepository.getAll().filter(r => r.statut === 'Validé' || r.statut === 'En attente');

  return `
    <div class="view-header-row">
      <p class="view-subtitle">Semaine du ${formatDate(toISODate(weekDates[0]))} au ${formatDate(toISODate(weekDates[6]))}</p>
      <div class="calendar-nav">
        <button class="btn btn-secondary btn-sm" id="btn-planning-week-prev">← Précédente</button>
        <button class="btn btn-secondary btn-sm" id="btn-planning-week-today">Cette semaine</button>
        <button class="btn btn-secondary btn-sm" id="btn-planning-week-next">Suivante →</button>
      </div>
    </div>
    <div class="card table-card planning-scroll-card">
      ${employees.length === 0 ? `<div class="empty-state"><div class="empty-icon">${ICONS.schedule}</div><p>Aucun salarié à afficher.</p></div>` : `
        <table class="table planning-table planning-table-cards">
          <thead><tr><th>Salarié</th>${weekDates.map(d => `<th>${WEEKDAY_LABELS[(d.getDay() + 6) % 7]} ${d.getDate()}</th>`).join('')}<th>Total</th></tr></thead>
          <tbody>
            ${renderPlanningGroupRows(employees, weekDates.length + 2, e => `
              <tr>
                <td class="planning-employee-cell">
                  ${renderAvatar(e)}
                  <div class="planning-employee-info">
                    ${personNameWithPosteHtml(e)}
                    <button type="button" class="btn-link" data-edit-horaires="${e.id}" title="Modifier les horaires">${icon(ICONS.pencil, 12)}</button>
                    ${renderPlanningEmployeeBadges(e)}
                  </div>
                </td>
                ${renderPlanningDayCells(e, weekDates.map(toISODate), leaveRequests, teleworkRequests, true)}
                <td class="planning-total-cell"><strong>${formatNumberFR(weekDates.reduce((sum, d) => sum + computeDailyHours(e, toISODate(d), leaveRequests, teleworkRequests).heures, 0))} h</strong></td>
              </tr>
            `)}
          </tbody>
        </table>
      `}
    </div>
  `;
}

function renderPlanningMois() {
  const year = state.planningYear;
  const month = state.planningMonth;
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const employees = getPlanningEmployees(`${year}-${String(month + 1).padStart(2, '0')}-01`, toISODate(new Date(year, month, daysInMonth)));
  const leaveRequests = leaveRepository.getAll().filter(r => r.statut === 'Validé' || r.statut === 'En attente');
  const teleworkRequests = teleworkRepository.getAll().filter(r => r.statut === 'Validé' || r.statut === 'En attente');

  return `
    <div class="view-header-row">
      <p class="view-subtitle">${MONTH_NAMES[month]} ${year}</p>
      <div class="calendar-nav">
        <button class="btn btn-secondary btn-sm" id="btn-planning-month-prev">← Précédent</button>
        <button class="btn btn-secondary btn-sm" id="btn-planning-month-today">Ce mois-ci</button>
        <button class="btn btn-secondary btn-sm" id="btn-planning-month-next">Suivant →</button>
      </div>
    </div>
    <div class="card table-card planning-scroll-card">
      ${employees.length === 0 ? `<div class="empty-state"><div class="empty-icon">${ICONS.schedule}</div><p>Aucun salarié à afficher.</p></div>` : `
        <table class="table planning-table">
          <thead><tr><th>Salarié</th>${Array.from({ length: daysInMonth }, (_, i) => `<th>${i + 1}</th>`).join('')}</tr></thead>
          <tbody>
            ${renderPlanningGroupRows(employees, daysInMonth + 1, e => `
              <tr>
                <td>
                  ${personNameWithPosteHtml(e)}
                  ${renderPlanningEmployeeBadges(e)}
                </td>
                ${renderPlanningDayCells(e, Array.from({ length: daysInMonth }, (_, i) => toISODate(new Date(year, month, i + 1))), leaveRequests, teleworkRequests, false)}
              </tr>
            `)}
          </tbody>
        </table>
      `}
    </div>
  `;
}

/** Vue année : nombre de jours de congé validés par mois (le détail jour par jour n'a pas de sens sur 365 colonnes). */
function renderPlanningAnnee() {
  const year = state.planningYear;
  const employees = getPlanningEmployees(`${year}-01-01`, `${year}-12-31`);
  const leaveRequests = leaveRepository.getAll().filter(r => r.statut === 'Validé');
  const settings = settingsRepository.getSettings();
  const leaveTypes = leaveTypeRepository.getLeaveTypes();

  return `
    <div class="view-header-row">
      <p class="view-subtitle">Jours de congé validés par mois — ${year}</p>
      <div class="calendar-nav">
        <button class="btn btn-secondary btn-sm" id="btn-planning-year-prev">← ${year - 1}</button>
        <button class="btn btn-secondary btn-sm" id="btn-planning-year-next">${year + 1} →</button>
      </div>
    </div>
    <div class="card table-card planning-scroll-card">
      ${employees.length === 0 ? `<div class="empty-state"><div class="empty-icon">${ICONS.schedule}</div><p>Aucun salarié à afficher.</p></div>` : `
        <table class="table planning-table">
          <thead><tr><th>Salarié</th>${MONTH_NAMES.map(m => `<th>${m.slice(0, 3)}</th>`).join('')}<th>Total</th></tr></thead>
          <tbody>
            ${renderPlanningGroupRows(employees, MONTH_NAMES.length + 2, e => {
              const monthCounts = MONTH_NAMES.map((_, monthIndex) =>
                leaveRequests
                  .filter(r => r.employeeId === e.id)
                  .reduce((sum, r) => sum + countRequestDaysInMonth(r.dateDebut, r.dateFin, r.demiJournee, year, monthIndex, e, settings, (leaveTypes.find(t => t.id === r.typeId) || {}).uniteDecompte), 0)
              );
              const total = monthCounts.reduce((a, b) => a + b, 0);
              return `
                <tr>
                  <td>${personNameWithPosteHtml(e)}</td>
                  ${monthCounts.map(c => `<td>${c || ''}</td>`).join('')}
                  <td><strong>${total}</strong></td>
                </tr>
              `;
            })}
          </tbody>
        </table>
      `}
    </div>
  `;
}

/** Sprint SIRH premium §3 : différence en heures entre deux horaires "HH:MM". */
function timeRangeToHours(debut, fin) {
  if (!debut || !fin) return 0;
  const [dh, dm] = debut.split(':').map(Number);
  const [fh, fm] = fin.split(':').map(Number);
  return Math.max(0, (fh * 60 + fm - (dh * 60 + dm)) / 60);
}

/** Heures planifiées d'un salarié pour une date donnée : 0 si jour non travaillé ou congé validé,
 * sinon somme des horaires matin+après-midi (identiques chaque jour travaillé, cf.
 * employee.horaireMatinDebut etc.) — le télétravail reste travaillé (mêmes horaires), juste signalé
 * différemment à l'affichage. */
function computeDailyHours(employee, dateStr, leaveRequests, teleworkRequests) {
  const weekday = WEEKDAY_LABELS[(parseISODateLocal(dateStr).getDay() + 6) % 7];
  if (!(employee.joursTravailles || []).includes(weekday)) return { heures: 0, label: '—', level: 'off' };

  const leaveToday = leaveRequests.find(r => r.employeeId === employee.id && dateStr >= r.dateDebut && dateStr <= r.dateFin);
  // Une demi-journée (matin OU après-midi, sur une date isolée) ne doit faire disparaître que la
  // moitié concernée des heures, pas la journée entière.
  const isHalfDayLeave = Boolean(leaveToday && leaveToday.demiJournee && leaveToday.dateDebut === leaveToday.dateFin);
  if (leaveToday && !isHalfDayLeave) return { heures: 0, label: icon(ICONS.sun, 14), level: 'leave' };

  const matinHeures = timeRangeToHours(employee.horaireMatinDebut, employee.horaireMatinFin);
  const apremHeures = timeRangeToHours(employee.horaireApresMidiDebut, employee.horaireApresMidiFin);
  const heures = round2(isHalfDayLeave
    ? (leaveToday.demiJournee === 'matin' ? apremHeures : matinHeures)
    : matinHeures + apremHeures);
  const onTelework = teleworkRequests.some(r => r.employeeId === employee.id && dateStr >= r.dateDebut && dateStr <= r.dateFin);
  const label = `${formatNumberFR(heures)} h${isHalfDayLeave ? ' ' + icon(ICONS.sun, 13) : ''}${onTelework ? ' ' + icon(ICONS.laptop, 13) : ''}`;
  return { heures, label, level: isHalfDayLeave ? 'leave' : (onTelework ? 'remote' : 'office') };
}

/** Sprint SIRH premium §3 : "Créer trois vues : Jour / Semaine / Mois" pour le planning d'horaires
 * — sous-onglets propres au planning Horaires (indépendants des onglets Semaine/Mois/Année du
 * planning d'absences, qui restent inchangés). */
function renderPlanningHoraires() {
  return `
    <div class="tabs tabs-sub" style="margin-bottom: 12px;">
      <button class="tab ${state.horairesView === 'jour' ? 'active' : ''}" data-horaires-view="jour">Jour</button>
      <button class="tab ${state.horairesView === 'mois' ? 'active' : ''}" data-horaires-view="mois">Mois</button>
      <button class="tab ${state.horairesView !== 'jour' && state.horairesView !== 'mois' ? 'active' : ''}" data-horaires-view="semaine">Semaine</button>
    </div>
    ${state.horairesView === 'jour' ? renderHorairesJour() : state.horairesView === 'mois' ? renderHorairesMois() : renderHorairesSemaine()}
  `;
}

function renderHorairesSemaine() {
  const weekDates = getWeekDates(state.planningWeekOffset);
  const employees = getPlanningEmployees(toISODate(weekDates[0]), toISODate(weekDates[6]));
  const leaveRequests = leaveRepository.getAll().filter(r => r.statut === 'Validé');
  const teleworkRequests = teleworkRepository.getAll().filter(r => r.statut === 'Validé');
  const totalSemaine = (e) => weekDates.reduce((sum, d) => sum + computeDailyHours(e, toISODate(d), leaveRequests, teleworkRequests).heures, 0);

  return `
    <div class="view-header-row">
      <p class="view-subtitle">Semaine du ${formatDate(toISODate(weekDates[0]))} au ${formatDate(toISODate(weekDates[6]))} — total automatique des heures</p>
      <div class="calendar-nav">
        <button class="btn btn-secondary btn-sm" id="btn-planning-week-prev">← Précédente</button>
        <button class="btn btn-secondary btn-sm" id="btn-planning-week-today">Cette semaine</button>
        <button class="btn btn-secondary btn-sm" id="btn-planning-week-next">Suivante →</button>
      </div>
    </div>
    <div class="card table-card planning-scroll-card">
      ${employees.length === 0 ? `<div class="empty-state"><div class="empty-icon">${ICONS.schedule}</div><p>Aucun salarié à afficher.</p></div>` : `
        <table class="table planning-table">
          <thead><tr><th>Salarié</th>${weekDates.map(d => `<th>${WEEKDAY_LABELS[(d.getDay() + 6) % 7]} ${d.getDate()}</th>`).join('')}<th>Total</th></tr></thead>
          <tbody>
            ${renderPlanningGroupRows(employees, weekDates.length + 2, e => `
              <tr>
                <td>${personNameWithPosteHtml(e)} <button type="button" class="btn-link" data-edit-horaires="${e.id}" title="Modifier les horaires">${icon(ICONS.pencil, 13)}</button></td>
                ${weekDates.map(d => {
                  const info = computeDailyHours(e, toISODate(d), leaveRequests, teleworkRequests);
                  return `<td class="planning-cell planning-${info.level}">${info.label}</td>`;
                }).join('')}
                <td><strong>${formatNumberFR(totalSemaine(e))} h</strong></td>
              </tr>
            `, g => `
              <tr class="planning-summary-row">
                <td>Total ${escapeHtml(g.service)}</td>
                ${weekDates.map(d => `<td>${formatNumberFR(g.employees.reduce((sum, e) => sum + computeDailyHours(e, toISODate(d), leaveRequests, teleworkRequests).heures, 0))} h</td>`).join('')}
                <td><strong>${formatNumberFR(g.employees.reduce((sum, e) => sum + totalSemaine(e), 0))} h</strong></td>
              </tr>
            `)}
          </tbody>
        </table>
      `}
    </div>
  `;
}

/** Vue Jour : le détail heure par heure (matin/après-midi) n'a de sens que sur UNE seule date à la
 * fois — la vue Semaine ne montre qu'un total agrégé par jour, celle-ci montre les vraies plages
 * horaires. */
function renderHorairesJour() {
  const dateStr = state.horairesDay;
  const date = parseISODateLocal(dateStr);
  const weekday = WEEKDAY_LABELS[(date.getDay() + 6) % 7];
  const employees = getPlanningEmployees(dateStr, dateStr);
  const leaveRequests = leaveRepository.getAll().filter(r => r.statut === 'Validé');
  const teleworkRequests = teleworkRepository.getAll().filter(r => r.statut === 'Validé');

  return `
    <div class="view-header-row">
      <p class="view-subtitle">${formatDate(dateStr)}</p>
      <div class="calendar-nav">
        <button class="btn btn-secondary btn-sm" id="btn-horaires-day-prev">← Précédent</button>
        <button class="btn btn-secondary btn-sm" id="btn-horaires-day-today">Aujourd'hui</button>
        <button class="btn btn-secondary btn-sm" id="btn-horaires-day-next">Suivant →</button>
      </div>
    </div>
    <div class="card table-card planning-scroll-card">
      ${employees.length === 0 ? `<div class="empty-state"><div class="empty-icon">${ICONS.schedule}</div><p>Aucun salarié à afficher.</p></div>` : `
        <table class="table planning-table">
          <thead><tr><th>Salarié</th><th>Matin</th><th>Après-midi</th><th>Total</th></tr></thead>
          <tbody>
            ${renderPlanningGroupRows(employees, 4, e => {
              const travaille = (e.joursTravailles || []).includes(weekday);
              if (!travaille) return `<tr><td>${personNameWithPosteHtml(e)}</td><td colspan="3" class="text-muted">Non travaillé</td></tr>`;
              const info = computeDailyHours(e, dateStr, leaveRequests, teleworkRequests);
              if (info.level === 'leave') return `<tr><td>${personNameWithPosteHtml(e)}</td><td colspan="3">${icon(ICONS.sun, 14)} Congé</td></tr>`;
              return `
                <tr>
                  <td>${personNameWithPosteHtml(e)}${info.level === 'remote' ? ' ' + icon(ICONS.laptop, 13) : ''} <button type="button" class="btn-link" data-edit-horaires="${e.id}" title="Modifier les horaires">${icon(ICONS.pencil, 13)}</button></td>
                  <td>${escapeHtml(e.horaireMatinDebut || '—')} – ${escapeHtml(e.horaireMatinFin || '—')}</td>
                  <td>${escapeHtml(e.horaireApresMidiDebut || '—')} – ${escapeHtml(e.horaireApresMidiFin || '—')}</td>
                  <td><strong>${formatNumberFR(info.heures)} h</strong></td>
                </tr>
              `;
            })}
          </tbody>
        </table>
      `}
    </div>
  `;
}

/** Vue Mois : même principe que le planning d'absences Mois, mais les cellules montrent des heures
 * (ou l'icône congé/non-travaillé) plutôt qu'un statut, avec un total mensuel par salarié. */
function renderHorairesMois() {
  const year = state.planningYear;
  const month = state.planningMonth;
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const employees = getPlanningEmployees(`${year}-${String(month + 1).padStart(2, '0')}-01`, toISODate(new Date(year, month, daysInMonth)));
  const leaveRequests = leaveRepository.getAll().filter(r => r.statut === 'Validé');
  const teleworkRequests = teleworkRepository.getAll().filter(r => r.statut === 'Validé');
  const totalMois = (e) => Array.from({ length: daysInMonth }, (_, i) =>
    computeDailyHours(e, toISODate(new Date(year, month, i + 1)), leaveRequests, teleworkRequests).heures).reduce((a, b) => a + b, 0);

  return `
    <div class="view-header-row">
      <p class="view-subtitle">${MONTH_NAMES[month]} ${year} — total automatique des heures</p>
      <div class="calendar-nav">
        <button class="btn btn-secondary btn-sm" id="btn-planning-month-prev">← Précédent</button>
        <button class="btn btn-secondary btn-sm" id="btn-planning-month-today">Ce mois-ci</button>
        <button class="btn btn-secondary btn-sm" id="btn-planning-month-next">Suivant →</button>
      </div>
    </div>
    <div class="card table-card planning-scroll-card">
      ${employees.length === 0 ? `<div class="empty-state"><div class="empty-icon">${ICONS.schedule}</div><p>Aucun salarié à afficher.</p></div>` : `
        <table class="table planning-table">
          <thead><tr><th>Salarié</th>${Array.from({ length: daysInMonth }, (_, i) => `<th>${i + 1}</th>`).join('')}<th>Total</th></tr></thead>
          <tbody>
            ${renderPlanningGroupRows(employees, daysInMonth + 2, e => `
              <tr>
                <td>${personNameWithPosteHtml(e)} <button type="button" class="btn-link" data-edit-horaires="${e.id}" title="Modifier les horaires">${icon(ICONS.pencil, 13)}</button></td>
                ${Array.from({ length: daysInMonth }, (_, i) => {
                  const info = computeDailyHours(e, toISODate(new Date(year, month, i + 1)), leaveRequests, teleworkRequests);
                  return `<td class="planning-cell planning-${info.level}" style="font-size:11px;">${info.level === 'off' ? '—' : info.level === 'leave' ? icon(ICONS.sun, 12) : formatNumberFR(info.heures)}</td>`;
                }).join('')}
                <td><strong>${formatNumberFR(totalMois(e))} h</strong></td>
              </tr>
            `)}
          </tbody>
        </table>
      `}
    </div>
  `;
}

function openHorairesModal(employeeId) {
  const employee = employeeRepository.getById(employeeId);
  if (!employee) { showToast('Ce salarié n\'est plus disponible.', 'error'); return; }
  const html = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>Horaires — ${personNameHtml(employee)}</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="horaires-form">
        <div class="modal-body">
          <div class="form-grid">
            ${textField('horaireMatinDebut', 'Matin, début', employee.horaireMatinDebut || '09:00', true, 'time')}
            ${textField('horaireMatinFin', 'Matin, fin', employee.horaireMatinFin || '12:00', true, 'time')}
            ${textField('horaireApresMidiDebut', 'Après-midi, début', employee.horaireApresMidiDebut || '13:00', true, 'time')}
            ${textField('horaireApresMidiFin', 'Après-midi, fin', employee.horaireApresMidiFin || '17:00', true, 'time')}
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="submit" class="btn btn-primary">Enregistrer</button>
        </div>
      </form>
    </div>
  `;

  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');

  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('horaires-form').addEventListener('submit', (evt) => {
    evt.preventDefault();
    const patch = {
      horaireMatinDebut: document.getElementById('f-horaireMatinDebut').value,
      horaireMatinFin: document.getElementById('f-horaireMatinFin').value,
      horaireApresMidiDebut: document.getElementById('f-horaireApresMidiDebut').value,
      horaireApresMidiFin: document.getElementById('f-horaireApresMidiFin').value
    };
    if (timeRangeToHours(patch.horaireMatinDebut, patch.horaireMatinFin) <= 0 && timeRangeToHours(patch.horaireApresMidiDebut, patch.horaireApresMidiFin) <= 0) {
      showToast('Les horaires doivent représenter au moins une plage valide.', 'error');
      return;
    }
    employeeRepository.update(employeeId, patch);
    auditLogRepository.logAudit('Modification', 'Horaires', `${employee.prenom} ${employee.nom}`);
    showToast('Horaires mis à jour.');
    closeModal();
    render();
  });
}

/** §retour Betty du 10/09/2026 (voir le commentaire au-dessus de renderPlanning) : Planning ne
 * rend plus que le bascule Planning équipe/Moi et la grille de postes — plus aucun des boutons
 * Semaine/Mois/Année/Horaires/Astreintes ni la barre d'outils qui allait avec, donc plus aucune des
 * anciennes liaisons (glisser-déposer, navigation semaine/mois/année, crayon horaires...) : les
 * garder aurait planté au premier rendu (document.getElementById sur un bouton qui n'existe plus). */
function bindPlanningEvents() {
  bindMoiEquipeToggleEvents();
  bindPlanningPostesEvents();
}

/** §7.21 : liste des astreintes (toutes entreprises visibles pour l'utilisateur, via
 * getVisibleEmployeeIdsForCurrentUser — même portée que le reste de Planning), la planification
 * elle-même reste réservée à MODIFIER_SALARIE (RH/Propriétaire, pas Manager) : décider qui est
 * d'astreinte est une décision de même niveau que modifier un salarié, pas une lecture d'équipe. */
function renderPlanningAstreintes() {
  const user = authRepository.getCurrentUser();
  const canManage = hasPermission(user, PERMISSIONS.MODIFIER_SALARIE);
  const visibleIds = getVisibleEmployeeIdsForCurrentUser();
  let employees = employeeRepository.getAll().filter(e => !e.archive);
  if (visibleIds !== null) employees = employees.filter(e => visibleIds.includes(e.id));

  const rows = employees
    .flatMap(e => (e.astreintes || []).map(a => ({ employee: e, astreinte: a })))
    .sort((a, b) => b.astreinte.dateDebut.localeCompare(a.astreinte.dateDebut));

  return `
    <div class="view-header-row">
      <p class="view-subtitle">${rows.length} période${rows.length > 1 ? 's' : ''} d'astreinte</p>
      ${canManage ? '<button type="button" class="btn btn-primary btn-sm" id="btn-add-astreinte">+ Ajouter une astreinte</button>' : ''}
    </div>
    <div class="card table-card">
      ${rows.length === 0 ? `<div class="empty-state"><div class="empty-icon">${icon(ICONS.schedule, 22)}</div><p>Aucune astreinte enregistrée pour l'instant.</p>${canManage ? '<p class="text-muted">Ajoutez-en une pour suivre les périodes et les indemnités associées.</p>' : ''}</div>` : `
        <table class="table">
          <thead><tr><th>Salarié</th><th>Période</th><th>Indemnité</th><th>Interventions</th><th></th></tr></thead>
          <tbody>
            ${rows.map(({ employee, astreinte }) => `
              <tr>
                <td>${personNameHtml(employee)}</td>
                <td>${formatDate(astreinte.dateDebut)} → ${formatDate(astreinte.dateFin)}</td>
                <td>${formatCurrencyFR(astreinte.indemniteMontant || 0)}</td>
                <td>${(astreinte.interventions || []).length}</td>
                <td class="detail-header-actions">
                  <button type="button" class="btn-link" data-view-astreinte="${employee.id}:${astreinte.id}">Détails</button>
                  ${canManage ? `<button type="button" class="btn-link" data-delete-astreinte="${employee.id}:${astreinte.id}">Supprimer</button>` : ''}
                </td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      `}
    </div>
  `;
}

function bindPlanningAstreintesEvents() {
  const addBtn = document.getElementById('btn-add-astreinte');
  if (addBtn) addBtn.addEventListener('click', openAjouterAstreinteModal);

  document.querySelectorAll('[data-view-astreinte]').forEach(btn => {
    btn.addEventListener('click', () => {
      const [employeeId, astreinteId] = btn.dataset.viewAstreinte.split(':');
      openAstreinteDetailModal(employeeId, astreinteId);
    });
  });

  document.querySelectorAll('[data-delete-astreinte]').forEach(btn => {
    btn.addEventListener('click', () => {
      const [employeeId, astreinteId] = btn.dataset.deleteAstreinte.split(':');
      openConfirm({
        title: 'Supprimer cette astreinte ?',
        message: 'Les interventions déjà déclarées seront perdues.',
        confirmLabel: 'Supprimer',
        danger: true,
        onConfirm: () => {
          const employee = employeeRepository.getById(employeeId);
          const astreintes = (employee.astreintes || []).filter(a => a.id !== astreinteId);
          employeeRepository.update(employeeId, { astreintes });
          showToast('Astreinte supprimée.');
          render();
        }
      });
    });
  });
}

function openAjouterAstreinteModal() {
  const employees = employeeRepository.getAll().filter(e => !e.archive).sort((a, b) => a.nom.localeCompare(b.nom));
  const html = `
    <div class="modal">
      <div class="modal-header">
        <h2>Ajouter une astreinte</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="add-astreinte-form">
        <div class="modal-body">
          <div class="form-field">
            <label>Salarié</label>
            <select class="input" id="f-astreinte-employee" required>
              <option value="">Sélectionner...</option>
              ${employees.map(e => `<option value="${e.id}">${personNameHtml(e)}</option>`).join('')}
            </select>
          </div>
          <div class="form-grid">
            <div class="form-field"><label>Date de début</label><input type="date" class="input" id="f-astreinte-debut" required></div>
            <div class="form-field"><label>Date de fin</label><input type="date" class="input" id="f-astreinte-fin" required></div>
          </div>
          <div class="form-field"><label>Indemnité (€)</label><input type="number" min="0" step="0.01" class="input" id="f-astreinte-indemnite" value="0"></div>
          <div class="form-field"><label>Commentaire (optionnel)</label><textarea class="input" id="f-astreinte-commentaire" rows="2"></textarea></div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="submit" class="btn btn-primary">Ajouter</button>
        </div>
      </form>
    </div>
  `;
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');
  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('add-astreinte-form').addEventListener('submit', (evt) => {
    evt.preventDefault();
    const employeeId = document.getElementById('f-astreinte-employee').value;
    const dateDebut = document.getElementById('f-astreinte-debut').value;
    const dateFin = document.getElementById('f-astreinte-fin').value;
    if (!employeeId) { showToast('Sélectionnez un salarié.', 'error'); return; }
    if (dateFin < dateDebut) { showToast('La date de fin doit être après la date de début.', 'error'); return; }
    const employee = employeeRepository.getById(employeeId);
    const astreinte = Object.assign(makeEmptyAstreinte(), {
      dateDebut, dateFin,
      indemniteMontant: parseFloat(document.getElementById('f-astreinte-indemnite').value) || 0,
      commentaire: document.getElementById('f-astreinte-commentaire').value.trim()
    });
    employeeRepository.update(employeeId, { astreintes: [...(employee.astreintes || []), astreinte] });
    closeModal();
    showToast('Astreinte ajoutée.');
    render();
  });
}

function openAstreinteDetailModal(employeeId, astreinteId) {
  const employee = employeeRepository.getById(employeeId);
  const astreinte = (employee.astreintes || []).find(a => a.id === astreinteId);
  if (!astreinte) return;
  const interventions = astreinte.interventions || [];
  const html = `
    <div class="modal">
      <div class="modal-header">
        <h2>Astreinte — ${personNameHtml(employee)}</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <div class="modal-body">
        ${infoRow('Période', `${formatDate(astreinte.dateDebut)} → ${formatDate(astreinte.dateFin)}`)}
        ${infoRow('Indemnité', formatCurrencyFR(astreinte.indemniteMontant || 0))}
        ${astreinte.commentaire ? infoRow('Commentaire', astreinte.commentaire) : ''}
        <h3 style="margin-top: 16px;">Interventions</h3>
        ${interventions.length === 0 ? '<p class="text-muted">Aucune intervention déclarée.</p>' : `
          <div class="timeline">
            ${interventions.map(i => `
              <div class="timeline-item">
                <div class="timeline-date text-muted">${formatDate(i.date)} · ${escapeHtml(i.heureDebut)}–${escapeHtml(i.heureFin)}</div>
                <div class="timeline-label">${escapeHtml(i.description || 'Intervention')}</div>
              </div>
            `).join('')}
          </div>
        `}
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" id="btn-close-modal-footer">Fermer</button>
      </div>
    </div>
  `;
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');
  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-close-modal-footer').addEventListener('click', closeModal);
}

// ---------------------------------------------------------------------------
// Planning par postes (§demande Betty du 10/09/2026) — écran distinct, inspiré d'une maquette envoyée
// (structure fonctionnelle : quarts récurrents hebdomadaires, regroupement par service) mais avec
// l'identité visuelle de Nexus (bleu marine + or), jamais la palette/le branding de la référence
// elle-même (confirmé avec Betty avant de commencer) — voir shiftRepository (data.js) et
// seven_rh_design_palette_rule.
//
// §correctif du 10/09/2026 : le premier jet regroupait les quarts par "Position" (Caisse, Commis...),
// un concept créé spécifiquement pour cet écran en s'inspirant de la référence externe. Betty a
// demandé à ce que le regroupement affiché ("Caisse") utilise à la place le SERVICE du salarié — un
// champ déjà existant sur sa fiche (voir employee.service), le même que sur les autres écrans
// (Salariés, Calendrier...). Le concept "Position" est donc entièrement retiré (plus de gestion
// dédiée, plus de champ sur le quart) : chaque quart n'est plus rattaché qu'à un salarié, dont le
// service déjà connu pilote à la fois le regroupement ET l'étiquette affichée sur la carte du quart.
//
// Simplifications volontaires par rapport à la maquette, à signaler explicitement (Betty a demandé à
// être prévenue de tout écart) :
//   - Pas de vue "Jour" (seule "Semaine" existe) : la référence en propose une, hors périmètre d'un
//     premier jet fonctionnel.
//   - Pas de bouton "Publier"/badge associé : la référence suppose un état brouillon/publié, qui
//     n'existe nulle part dans le modèle de données de Nexus — l'inventer aurait été une vraie
//     fonctionnalité de workflow, pas un simple habillage. Remplacé par un compteur simple de quarts
//     affichés.
//   - Pas de "Copier/Partager/Imprimer" (hors périmètre).
//   - Pas de couleur par service (la maquette en propose une par position) : bleu marine + or
//     partout, confirmé par Betty.
// ---------------------------------------------------------------------------

/** Salariés visibles pour cet écran (portée manager déjà appliquée), avant application des filtres
 * propres à l'écran Postes (établissement, recherche, congés, "avec quart seulement"). */
function getPlanningPostesEmployees(f, weekStartStr, weekEndStr) {
  // §retour Betty du 10/09/2026 : la grille de postes remplace désormais le contenu de Planning
  // (voir renderPlanning) — le bascule Planning équipe/Moi, resté en place, doit donc continuer à
  // limiter la grille au seul utilisateur courant en "Moi", même principe que l'ancien
  // getPlanningEmployees (Semaine/Mois, retiré de l'écran mais toujours dans le fichier).
  const user = authRepository.getCurrentUser();
  const visibleIds = (user.role !== ROLES.SALARIE && state.planningVue === 'personnel') ? [user.id] : getVisibleEmployeeIdsForCurrentUser();
  let employees = employeeRepository.getAll().filter(e => !e.archive);
  if (visibleIds !== null) employees = employees.filter(e => visibleIds.includes(e.id));
  if (f.etablissementId) employees = employees.filter(e => e.etablissementId === f.etablissementId);
  if (f.search.trim()) {
    const q = f.search.trim().toLowerCase();
    employees = employees.filter(e => `${e.prenom} ${e.nom}`.toLowerCase().includes(q));
  }
  if (f.congesFiltre === 'masquer') {
    const onLeaveIds = new Set(
      leaveRepository.getAll()
        .filter(r => r.statut === 'Validé' && r.dateDebut <= weekEndStr && r.dateFin >= weekStartStr)
        .map(r => r.employeeId)
    );
    employees = employees.filter(e => !onLeaveIds.has(e.id));
  }
  return employees;
}

function renderPlanningPostes() {
  const user = authRepository.getCurrentUser();
  const canManage = hasPermission(user, PERMISSIONS.MODIFIER_SALARIE);
  const f = state.planningPostesFilters;
  const weekDates = getWeekDates(state.planningPostesWeekOffset);
  const weekStartStr = toISODate(weekDates[0]);
  const weekEndStr = toISODate(weekDates[6]);

  const allShifts = shiftRepository.getAll();
  const shiftsFor = (employeeId, weekday) => allShifts.find(s => s.employeeId === employeeId && s.weekday === weekday);
  const employeeShifts = (employeeId) => allShifts.filter(s => s.employeeId === employeeId);
  const employeeWeekHeures = (employeeId) => round2(employeeShifts(employeeId).reduce((sum, s) => sum + computeShiftHeures(s), 0));

  let employees = getPlanningPostesEmployees(f, weekStartStr, weekEndStr);
  if (f.employesFiltre === 'avecQuart') employees = employees.filter(e => employeeShifts(e.id).length > 0);
  const sortEmployees = (list) => list.slice().sort((a, b) =>
    state.planningPostesSortDir === 'desc' ? b.prenom.localeCompare(a.prenom) : a.prenom.localeCompare(b.prenom)
  );

  // §demande Betty du 11/09/2026 (Pointeuse QR, "dire dans le planning que l'employé est bien
  // présent") : un pointage réel (voir pointageRepository) ne peut exister QUE pour aujourd'hui —
  // calculé une seule fois ici plutôt que dans renderCell, jamais comparé à un autre jour de la
  // semaine affichée. Masqué si le module n'est pas souscrit (aucun pointage ne peut alors exister
  // de toute façon, mais évite un accès superflu au repository).
  const todayStr = toISODate(new Date());
  /** §correctif visuel du 14/09/2026 : une case de jour est étroite (7 jours + la colonne du nom
   * sur la même largeur), avec une hauteur de ligne FIXE (déterminée par la colonne du nom, jamais
   * par le contenu de .poste-shift-card lui-même — carte en position:absolute, donc hors du flux
   * normal). Un quart déjà affiché (horaire + service, 2 lignes) n'a quasiment plus de marge :
   * ajouter la confirmation de pointage en 3e ligne texte ("Pointé 08:52 → 17:03") débordait
   * carrément de la carte, la seconde heure se retrouvant visuellement affichée par-dessus la ligne
   * suivante du tableau — exactement le repère envoyé par Betty. Un simple point vert au survol
   * (title, jamais de texte en dur) n'ajoute AUCUNE ligne : ne peut plus jamais déborder, quelle que
   * soit la hauteur réellement disponible. Seule la carte SANS quart planifié (rien d'autre à
   * montrer, donc bien plus de place) garde l'affichage complet en toutes lettres. */
  const getDernierPointage = (employeeId, dateStr) => {
    if (!hasModule('pointage') || dateStr !== todayStr) return null;
    const pointages = pointageRepository.getForEmployeeOnDate(employeeId, dateStr);
    return pointages.length ? pointages[pointages.length - 1] : null;
  };
  const pointageTexte = (dernier) => dernier.heureDepart ? `${dernier.heureArrivee} → ${dernier.heureDepart}` : `arrivée ${dernier.heureArrivee}`;

  // §retour Betty du 10/09/2026 ("exactement ça sauf en bleu et doré") : carte flottante avec
  // marge/ombre/accent gauche (voir .poste-shift-card, style.css) plutôt que le remplissage bord à
  // bord du Planning principal (.planning-shift-card) — les deux écrans suivent chacun leur propre
  // référence visuelle, ils n'ont pas à se ressembler entre eux.
  const renderCell = (employee, weekday, dateStr) => {
    const shift = shiftsFor(employee.id, weekday);
    const dernierPointage = getDernierPointage(employee.id, dateStr);
    if (shift && !f.masquerQuartsConfirmes) {
      // §retour Betty du 13/09/2026 : la pause n'apparaît plus sur la carte (allégée à horaire +
      // service) — retiré uniquement de cet affichage, shift.pauseMinutes reste saisi dans la
      // modale (openShiftModal) et continue de compter dans le calcul des heures travaillées
      // (computeShiftHeures, data.js), jamais touché ici.
      // §retour Betty du 14/09/2026 (Planning point 4) : signale (jamais un blocage) un quart posé
      // sur une indisponibilité déclarée par CE salarié (voir Mon compte > Disponibilités).
      const conflitIndisponibilite = shiftChevaucheIndisponibilite(shift, employee.indisponibilitesRecurrentes);
      const pointageDot = dernierPointage ? `<span class="poste-shift-pointage-dot" title="Pointé : ${escapeHtml(pointageTexte(dernierPointage))}">${icon(ICONS.checkCircle, 10)}</span>` : '';
      return `<td class="planning-cell">
        <div class="poste-shift-card" data-edit-shift="${shift.id}" ${conflitIndisponibilite ? 'style="border-left-color: var(--color-danger);"' : ''} title="${conflitIndisponibilite ? 'Chevauche une indisponibilité déclarée' : ''}">
          <div class="poste-shift-time">${escapeHtml(shift.heureDebut)}-${escapeHtml(shift.heureFin)}</div>
          <div class="poste-shift-position">${escapeHtml(employee.service || '')}${pointageDot}</div>
          ${conflitIndisponibilite ? `<div class="text-danger" style="font-size: 11px;">${icon(ICONS.warningTriangle, 10)} Indisponible</div>` : ''}
        </div>
      </td>`;
    }
    if (dernierPointage) {
      // Un pointage réel existe aujourd'hui même sans quart programmé (ex. quart non renseigné) —
      // reste visible plutôt que masqué derrière un "+" ou une case vide. Rien d'autre à afficher
      // dans cette carte : la place ne manque pas pour l'heure en toutes lettres, sur sa propre ligne.
      return `<td class="planning-cell"><div class="poste-shift-card poste-shift-pointage-only">
        <div class="poste-shift-pointage">${icon(ICONS.checkCircle, 10)} Pointé</div>
        <div class="poste-shift-pointage-heures">${escapeHtml(pointageTexte(dernierPointage))}</div>
      </div></td>`;
    }
    if (f.afficherQuartsACombler && canManage) {
      return `<td class="planning-cell"><button type="button" class="poste-shift-add" data-add-shift="${employee.id}|${weekday}" title="Ajouter un quart">+</button></td>`;
    }
    return `<td class="planning-cell"></td>`;
  };

  // §retour Betty du 14/09/2026 (Planning point 1, "le planning doit refuser ou au moins signaler
  // en rouge") : calculé une seule fois par salarié affiché, jamais par cellule (les règles portent
  // sur la semaine entière du salarié, pas sur un jour isolé) — voir verifierControlesLegauxPlanning,
  // data.js. Jamais bloquant : un badge d'alerte, jamais un empêchement d'enregistrer un quart.
  const violationsFor = (employeeId) => verifierControlesLegauxPlanning(employeeId, allShifts);

  const renderEmployeeRow = (employee) => {
    const violations = violationsFor(employee.id);
    return `
    <tr>
      <td class="planning-employee-cell">
        ${renderAvatar(employee)}
        <div class="planning-employee-info">
          <div>${personNameHtml(employee)} ${violations.length ? `<span class="badge badge-danger" title="${escapeHtml(violations.map(v => v.message).join(' · '))}">${icon(ICONS.warningTriangle, 11)} ${violations.length}</span>` : ''}</div>
          <div class="poste-employee-hours">${formatNumberFR(employeeWeekHeures(employee.id))} h</div>
        </div>
      </td>
      ${weekDates.map(d => renderCell(employee, WEEKDAY_LABELS[(d.getDay() + 6) % 7], toISODate(d))).join('')}
      <td class="planning-total-cell"><strong>${formatNumberFR(employeeWeekHeures(employee.id))} h</strong></td>
    </tr>
  `;
  };

  // §retour Betty du 10/09/2026 ("il faut que ce soit le service à cet endroit") : regroupement par
  // SERVICE (champ déjà existant sur la fiche salarié), plus par Position (concept retiré). Un
  // salarié sans service assigné est regroupé à part, toujours en dernier — l'ordre des autres
  // groupes suit celui des services déclarés dans Paramètres (pas un tri alphabétique arbitraire).
  const serviceOrder = serviceRepository.getAll().map(s => s.nom);
  const serviceOf = (employee) => employee.service && employee.service.trim() ? employee.service : null;
  const groupNames = [...new Set(employees.map(serviceOf))];
  groupNames.sort((a, b) => {
    if (a === null) return 1;
    if (b === null) return -1;
    return serviceOrder.indexOf(a) - serviceOrder.indexOf(b);
  });

  const bodyHtml = groupNames.map(nom => {
    const groupEmployees = sortEmployees(employees.filter(e => serviceOf(e) === nom));
    if (groupEmployees.length === 0) return '';
    return `
      <tr class="planning-service-header"><td colspan="${weekDates.length + 2}">
        <div class="poste-group-header-row">
          <span>${escapeHtml(nom || 'Sans service')} <span class="text-muted">(${groupEmployees.length})</span></span>
        </div>
      </td></tr>
      ${groupEmployees.map(e => renderEmployeeRow(e)).join('')}
    `;
  }).join('');

  // §retour Betty du 14/09/2026 (Planning point 2, "voir le coût de la semaine se cumuler pendant
  // qu'on place les créneaux") : afficherBudget restait toujours à false depuis le retrait du
  // panneau de filtres qui seul pouvait l'activer (§retour Betty du 10/09/2026) — cette ligne
  // "heures planifiées" était donc devenue invisible pour de bon. Toujours affichée maintenant ;
  // une seconde ligne "coût" s'ajoute si la masse salariale est suivie.
  const shiftsVisibles = allShifts.filter(s => employees.some(e => e.id === s.employeeId));
  const settings = settingsRepository.getSettings();
  const coutSemaine = settings.masseSalarialeActivee ? calculerCoutShifts(shiftsVisibles, employees) : null;
  const budgetFixe = settings.budgetHebdomadairePlanningEuros || 0;
  const budgetRow = `
    <tr class="poste-budget-row">
      <td><strong>Heures planifiées</strong></td>
      ${weekDates.map(d => {
        const weekday = WEEKDAY_LABELS[(d.getDay() + 6) % 7];
        const total = allShifts.filter(s => s.weekday === weekday && employees.some(e => e.id === s.employeeId)).reduce((sum, s) => sum + computeShiftHeures(s), 0);
        return `<td><strong>${formatNumberFR(round2(total))} h</strong></td>`;
      }).join('')}
      <td><strong>${formatNumberFR(round2(shiftsVisibles.reduce((sum, s) => sum + computeShiftHeures(s), 0)))} h</strong></td>
    </tr>
    ${coutSemaine !== null ? `
      <tr class="poste-budget-row">
        <td><strong>Coût de la semaine</strong></td>
        <td colspan="${weekDates.length}" class="${budgetFixe > 0 && coutSemaine > budgetFixe ? 'text-danger' : ''}">
          <strong>${formatCurrencyFR(coutSemaine)}${budgetFixe > 0 ? ` / ${formatCurrencyFR(budgetFixe)} budgété` : ''}</strong>
        </td>
        <td class="${budgetFixe > 0 && coutSemaine > budgetFixe ? 'text-danger' : ''}"><strong>${formatCurrencyFR(coutSemaine)}</strong></td>
      </tr>
    ` : ''}
  `;

  // §retour Betty du 10/09/2026 ("enlève tous les boutons, fais juste le design du planning [...],
  // pas ce qu'il y a autour") : plus de panneau de filtres, plus de barre d'outils (recherche,
  // navigation semaine, sélecteur Semaine/Jour, icônes, pilules) — uniquement la grille elle-même,
  // telle que dessinée dans la référence (en-tête triable, bandeaux de groupe avec "⋯", cartes de
  // quart, total). Les réglages qu'affichait le panneau retiré gardent leurs valeurs par défaut
  // (state.planningPostesFilters), simplement plus modifiables depuis cet écran.
  return `
    <div class="card table-card planning-scroll-card poste-grid-card">
      ${canManage ? `
        <div class="view-header-row" style="padding: 14px 20px 0;">
          <div></div>
          <div class="detail-header-actions">
            <button class="btn btn-secondary btn-sm" id="btn-enregistrer-modele-semaine">Enregistrer comme modèle</button>
            ${weekTemplateRepository.getAll().length ? `<button class="btn btn-secondary btn-sm" id="btn-appliquer-modele-semaine">Appliquer un modèle</button>` : ''}
          </div>
        </div>
      ` : ''}
      ${employees.length === 0 ? `<div class="empty-state"><div class="empty-icon">${ICONS.schedule}</div><p>Aucun salarié à afficher.</p></div>` : `
        <table class="table planning-table">
          <thead>
            <tr>
              <th id="btn-poste-sort-name" style="cursor: pointer;">↕ Prénom (${state.planningPostesSortDir === 'desc' ? 'Z-A' : 'A-Z'}) <span style="opacity:0.6;">▾</span></th>
              ${weekDates.map(d => `<th>${WEEKDAY_LABELS[(d.getDay() + 6) % 7]}. ${d.getDate()}</th>`).join('')}
              <th>Total</th>
            </tr>
          </thead>
          <tbody>
            ${bodyHtml}
            ${budgetRow}
          </tbody>
        </table>
      `}
    </div>

    ${renderShiftSwapCard(user, employees)}

    ${hasModule('pointage') ? renderComparaisonPrevuRealiseCard(employees, weekDates, weekStartStr, weekEndStr) : ''}
  `;
}

/** §retour Betty du 14/09/2026 (Planning point 3, "échange de créneaux entre salariés") : un
 * salarié propose l'un de SES quarts (voir le bouton dans openShiftModal), n'importe quel autre
 * salarié visible peut le prendre, le manager valide (réaffectation réelle) ou refuse. Jamais de
 * réaffectation avant la validation manager — voir DB.traiterEchangeShift. */
function renderShiftSwapCard(user, employeesVisibles) {
  const canManage = hasPermission(user, PERMISSIONS.MODIFIER_SALARIE);
  // §correctif audit du 16/09/2026 : employeesVisibles était reçu mais jamais utilisé — un manager
  // dont la portée est restreinte à sa propre équipe (getVisibleEmployeeIdsForCurrentUser) voyait ET
  // pouvait valider/refuser des échanges de créneaux entre salariés d'AUTRES équipes, hors de son
  // autorité (peutTraiter ne vérifie qu'une permission globale, jamais la portée d'équipe).
  const visibleIds = new Set(employeesVisibles.map(e => e.id));
  const requests = shiftSwapRepository.getAll().filter(r => r.statut !== 'refusé' && r.statut !== 'validé' && visibleIds.has(r.employeeId));
  if (!requests.length) return '';
  const nomDe = (id) => { const e = employeeRepository.getById(id); return e ? `${e.prenom} ${e.nom}` : '—'; };
  const describeShift = (shiftId) => {
    const shift = shiftRepository.getById(shiftId);
    return shift ? `${shift.weekday} ${shift.heureDebut}-${shift.heureFin}` : 'Quart supprimé';
  };

  const rows = requests.map(r => {
    const estProposant = r.employeeId === user.id;
    const peutAccepter = r.statut === 'proposé' && !estProposant;
    const peutTraiter = r.statut === 'accepté' && canManage;
    return `
      <div class="mini-list-item">
        <span>${describeShift(r.shiftId)} · proposé par ${escapeHtml(nomDe(r.employeeId))}${r.destinataireId ? ` → repris par ${escapeHtml(nomDe(r.destinataireId))}` : ''}</span>
        <span class="detail-header-actions">
          <span class="badge badge-${r.statut === 'proposé' ? 'info' : 'warning'}">${r.statut === 'proposé' ? 'Ouvert' : 'En attente de validation'}</span>
          ${peutAccepter ? `<button type="button" class="btn btn-secondary btn-sm" data-accepter-echange="${r.id}">Prendre ce créneau</button>` : ''}
          ${peutTraiter ? `<button type="button" class="btn btn-secondary btn-sm" data-valider-echange="${r.id}">Valider</button><button type="button" class="btn-link btn-link-danger" data-refuser-echange="${r.id}">Refuser</button>` : ''}
        </span>
      </div>
    `;
  }).join('');

  return `
    <div class="card" style="margin-top: 16px;">
      <h2>Échanges de créneaux</h2>
      <div id="shift-swap-list">${rows}</div>
    </div>
  `;
}

function bindShiftSwapCardEvents() {
  const user = authRepository.getCurrentUser();
  document.querySelectorAll('[data-accepter-echange]').forEach(btn => {
    btn.addEventListener('click', () => {
      shiftSwapRepository.accepter(btn.dataset.accepterEchange, user.id);
      showToast('Créneau pris, en attente de validation par le manager.');
      render();
    });
  });
  document.querySelectorAll('[data-valider-echange]').forEach(btn => {
    btn.addEventListener('click', () => {
      shiftSwapRepository.traiter(btn.dataset.validerEchange, true);
      showToast('Échange validé, le quart a été réaffecté.');
      render();
    });
  });
  document.querySelectorAll('[data-refuser-echange]').forEach(btn => {
    btn.addEventListener('click', () => {
      shiftSwapRepository.traiter(btn.dataset.refuserEchange, false);
      showToast('Échange refusé.');
      render();
    });
  });
}

/** §retour Betty du 14/09/2026 (Planning point 6, "comparaison prévu et réalisé") : heures
 * PLANIFIÉES (shifts, modèle récurrent appliqué aux dates de la semaine affichée) contre heures
 * RÉELLEMENT POINTÉES (pointageRepository) — seulement pour les jours déjà passés (ou aujourd'hui),
 * jamais un jour futur qui n'a logiquement aucun pointage encore. Masquée si le module Pointeuse
 * n'est pas souscrit (voir l'appelant, renderPlanningPostes). */
function renderComparaisonPrevuRealiseCard(employees, weekDates, weekStartStr, weekEndStr) {
  const todayStr = toISODate(new Date());
  const joursPasses = weekDates.filter(d => toISODate(d) <= todayStr);
  if (!joursPasses.length) return '';
  const allShifts = shiftRepository.getAll();

  const rows = employees.map(employee => {
    let planifieMinutes = 0;
    let realiseMinutes = 0;
    joursPasses.forEach(d => {
      const weekday = WEEKDAY_LABELS[(d.getDay() + 6) % 7];
      const shift = allShifts.find(s => s.employeeId === employee.id && s.weekday === weekday);
      if (shift) planifieMinutes += Math.round(computeShiftHeures(shift) * 60);
      const pointages = pointageRepository.getForEmployeeOnDate(employee.id, toISODate(d));
      realiseMinutes += pointages.reduce((sum, p) => sum + computeDureeTravailleeMinutes(p), 0);
    });
    if (planifieMinutes === 0 && realiseMinutes === 0) return '';
    const ecartMinutes = realiseMinutes - planifieMinutes;
    const ecartSignificatif = Math.abs(ecartMinutes) >= 15;
    return `
      <tr>
        <td>${personNameHtml(employee)}</td>
        <td>${formatNumberFR(round2(planifieMinutes / 60))} h</td>
        <td>${formatNumberFR(round2(realiseMinutes / 60))} h</td>
        <td class="${ecartSignificatif ? 'text-danger' : ''}">${ecartMinutes >= 0 ? '+' : ''}${formatNumberFR(round2(ecartMinutes / 60))} h</td>
      </tr>
    `;
  }).filter(Boolean).join('');

  if (!rows) return '';
  // §correctif visuel du 14/09/2026 : .card seul (sans .table-card, sans overflow-x:auto) laissait
  // ce tableau déborder de sa carte sur un écran étroit — la carte elle-même débordait alors de la
  // page entière (aucun overflow:hidden), forçant TOUTE la page à défiler horizontalement. Même
  // classe .table-card que tous les autres tableaux de l'appli, jamais un cas particulier.
  return `
    <div class="card table-card" style="margin-top: 16px;">
      <h2 style="padding: 18px 22px 0;">Prévu / réalisé (jusqu'à aujourd'hui)</h2>
      <table class="table">
        <thead><tr><th>Salarié</th><th>Planifié</th><th>Pointé</th><th>Écart</th></tr></thead>
        <tbody>${rows}</tbody>
      </table>
    </div>
  `;
}

/** §retour Betty du 10/09/2026 ("enlève tous les boutons, fais juste le design du planning [...],
 * pas ce qu'il y a autour") : plus de panneau de filtres, plus de barre d'outils — seuls les
 * comportements dessinés DANS la grille elle-même restent interactifs (trier par prénom, cliquer une
 * carte pour la modifier, cliquer une case vide pour ajouter un quart). Le "⋯" du bandeau de groupe
 * (options de la position) a disparu avec la position elle-même — un groupe est désormais un Service,
 * qui se gère déjà depuis Paramètres > Services. */
function bindPlanningPostesEvents() {
  const sortBtn = document.getElementById('btn-poste-sort-name');
  if (sortBtn) sortBtn.addEventListener('click', () => {
    state.planningPostesSortDir = state.planningPostesSortDir === 'desc' ? 'asc' : 'desc';
    render();
  });

  document.querySelectorAll('[data-edit-shift]').forEach(card => {
    card.addEventListener('click', () => openShiftModal(shiftRepository.getById(card.dataset.editShift)));
  });
  document.querySelectorAll('[data-add-shift]').forEach(btn => {
    btn.addEventListener('click', () => {
      const [employeeId, weekday] = btn.dataset.addShift.split('|');
      openShiftModal(null, { employeeId, weekday });
    });
  });

  const enregistrerModeleBtn = document.getElementById('btn-enregistrer-modele-semaine');
  if (enregistrerModeleBtn) enregistrerModeleBtn.addEventListener('click', openEnregistrerModeleSemaineModal);
  const appliquerModeleBtn = document.getElementById('btn-appliquer-modele-semaine');
  if (appliquerModeleBtn) appliquerModeleBtn.addEventListener('click', openAppliquerModeleSemaineModal);

  bindShiftSwapCardEvents();
}

function openEnregistrerModeleSemaineModal() {
  const html = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>Enregistrer comme modèle</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="modele-semaine-form">
        <div class="modal-body">
          <div class="form-field">
            <label for="f-nom-modele">Nom du modèle</label>
            <input type="text" class="input" id="f-nom-modele" required placeholder="Ex. Semaine type été">
          </div>
          <p class="text-muted">Enregistre TOUS les quarts actuellement définis (tous salariés confondus), pas seulement ceux affichés à l'écran.</p>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="submit" class="btn btn-primary">Enregistrer</button>
        </div>
      </form>
    </div>
  `;
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');
  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('modele-semaine-form').addEventListener('submit', (evt) => {
    evt.preventDefault();
    const nom = document.getElementById('f-nom-modele').value.trim();
    if (!nom) { showToast('Le nom du modèle est obligatoire.', 'error'); return; }
    weekTemplateRepository.enregistrer(nom, shiftRepository.getAll());
    closeModal();
    showToast('Modèle enregistré.');
    render();
  });
}

function openAppliquerModeleSemaineModal() {
  const templates = weekTemplateRepository.getAll();
  const html = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>Appliquer un modèle</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <div class="modal-body">
        <p class="text-muted">Remplace les quarts des salariés concernés par le modèle choisi, les autres salariés (absents du modèle) gardent leurs quarts actuels.</p>
        <div id="modele-semaine-list">
          ${templates.map(t => `
            <div class="mini-list-item">
              <span>${escapeHtml(t.nom)} <span class="text-muted">(${t.shifts.length} quart${t.shifts.length > 1 ? 's' : ''})</span></span>
              <span class="detail-header-actions">
                <button type="button" class="btn btn-secondary btn-sm" data-appliquer-modele="${t.id}">Appliquer</button>
                <button type="button" class="btn-link btn-link-danger" data-delete-modele-semaine="${t.id}">Supprimer</button>
              </span>
            </div>
          `).join('')}
        </div>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Fermer</button>
      </div>
    </div>
  `;
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');
  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.querySelectorAll('[data-appliquer-modele]').forEach(btn => {
    btn.addEventListener('click', () => {
      const template = weekTemplateRepository.getById(btn.dataset.appliquerModele);
      openConfirm({
        title: 'Appliquer ce modèle ?',
        message: `Les quarts actuels des salariés concernés par "${template.nom}" seront remplacés.`,
        confirmLabel: 'Appliquer',
        danger: true,
        onConfirm: () => {
          weekTemplateRepository.appliquer(template.id);
          closeModal();
          showToast('Modèle appliqué.');
          render();
        }
      });
    });
  });
  // §retour Betty du 19/09/2026 (point 7, "cinq suppressions sans confirmation") : même garde-fou
  // que le bouton "Appliquer" juste au-dessus (openConfirm) — un clic supprimait le modèle
  // immédiatement, sans rattrapage.
  document.querySelectorAll('[data-delete-modele-semaine]').forEach(btn => {
    btn.addEventListener('click', () => {
      const template = weekTemplateRepository.getById(btn.dataset.deleteModeleSemaine);
      openConfirm({
        title: 'Supprimer ce modèle ?',
        message: template ? `"${template.nom}" (${template.shifts.length} quart${template.shifts.length > 1 ? 's' : ''}) sera définitivement supprimé.` : 'Ce modèle sera définitivement supprimé.',
        confirmLabel: 'Supprimer',
        danger: true,
        onConfirm: () => {
          weekTemplateRepository.delete(btn.dataset.deleteModeleSemaine);
          showToast('Modèle supprimé.');
          openAppliquerModeleSemaineModal();
        }
      });
    });
  });
}

/** `shift` = quart existant à modifier (null pour une création) ; `preset` = valeurs initiales pour
 * une création lancée depuis une case "+" précise (employé/jour déjà connus). */
function openShiftModal(shift, preset) {
  const visibleIds = getVisibleEmployeeIdsForCurrentUser();
  let employees = employeeRepository.getAll().filter(e => !e.archive);
  if (visibleIds !== null) employees = employees.filter(e => visibleIds.includes(e.id));
  const values = shift || Object.assign(makeEmptyShiftDraft(), preset || {});
  // §retour Betty du 14/09/2026 (Planning point 3, "échange de créneaux") : seul LE SALARIÉ
  // CONCERNÉ par ce quart peut en proposer l'échange, jamais un tiers (même raisonnement que
  // l'accusé de lecture, Module RH point 4) — et seulement s'il n'y a pas déjà une proposition en
  // cours pour ce même quart.
  const user = authRepository.getCurrentUser();
  const echangeDejaPropose = shift && shiftSwapRepository.getAll().some(r => r.shiftId === shift.id && r.statut !== 'refusé' && r.statut !== 'validé');
  const peutProposerEchange = shift && user.id === shift.employeeId && !echangeDejaPropose;

  const html = `
    <div class="modal modal-medium">
      <div class="modal-header">
        <h2>${shift ? 'Modifier le quart' : 'Ajouter un quart'}</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="shift-form">
        <div class="modal-body">
          <div class="form-grid">
            <div class="form-field">
              <label for="f-shift-employee">Salarié</label>
              <select class="input" id="f-shift-employee" required>
                <option value="">Sélectionner...</option>
                ${employees.map(e => `<option value="${e.id}" ${values.employeeId === e.id ? 'selected' : ''}>${personNameHtml(e)}</option>`).join('')}
              </select>
            </div>
            <div class="form-field">
              <label for="f-shift-weekday">Jour</label>
              <select class="input" id="f-shift-weekday">
                ${WEEKDAY_LABELS.map(w => `<option value="${w}" ${values.weekday === w ? 'selected' : ''}>${w}</option>`).join('')}
              </select>
            </div>
            <div class="form-field"><label for="f-shift-debut">Heure de début</label><input class="input" type="time" id="f-shift-debut" value="${escapeHtml(values.heureDebut)}" required></div>
            <div class="form-field"><label for="f-shift-fin">Heure de fin</label><input class="input" type="time" id="f-shift-fin" value="${escapeHtml(values.heureFin)}" required></div>
            <div class="form-field"><label for="f-shift-pause">Pause (minutes)</label><input class="input" type="number" min="0" step="5" id="f-shift-pause" value="${values.pauseMinutes != null ? values.pauseMinutes : 30}"></div>
          </div>
          <p class="text-muted">Quart récurrent chaque semaine, tant qu'il n'est pas modifié ou supprimé (pas rattaché à une date précise).</p>
        </div>
        <div class="modal-footer">
          ${shift ? `<button type="button" class="btn btn-secondary" id="btn-delete-shift" style="margin-right: auto;">Supprimer</button>` : ''}
          ${peutProposerEchange ? `<button type="button" class="btn btn-secondary" id="btn-proposer-echange-shift">Proposer l'échange</button>` : ''}
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="submit" class="btn btn-primary">${shift ? 'Enregistrer' : 'Ajouter'}</button>
        </div>
      </form>
    </div>
  `;
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');
  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  const proposerEchangeBtn = document.getElementById('btn-proposer-echange-shift');
  if (proposerEchangeBtn) proposerEchangeBtn.addEventListener('click', () => {
    shiftSwapRepository.proposer(shift.id, user.id);
    closeModal();
    showToast('Échange proposé, visible par vos collègues.');
    render();
  });
  const deleteBtn = document.getElementById('btn-delete-shift');
  if (deleteBtn) deleteBtn.addEventListener('click', () => {
    openConfirm({
      title: 'Supprimer ce quart ?',
      message: 'Cette action est irréversible.',
      confirmLabel: 'Supprimer',
      danger: true,
      onConfirm: () => {
        shiftRepository.delete(shift.id);
        closeModal();
        showToast('Quart supprimé.');
        render();
      }
    });
  });
  document.getElementById('shift-form').addEventListener('submit', (evt) => {
    evt.preventDefault();
    const data = {
      employeeId: document.getElementById('f-shift-employee').value,
      weekday: document.getElementById('f-shift-weekday').value,
      heureDebut: document.getElementById('f-shift-debut').value,
      heureFin: document.getElementById('f-shift-fin').value,
      pauseMinutes: Number(document.getElementById('f-shift-pause').value) || 0
    };
    if (!data.employeeId) { showToast('Sélectionnez un salarié.', 'error'); return; }
    if (data.heureFin <= data.heureDebut) { showToast('L\'heure de fin doit être après l\'heure de début.', 'error'); return; }
    const savedShift = shift ? shiftRepository.update(shift.id, data) : shiftRepository.create(data);
    closeModal();
    showToast(shift ? 'Quart modifié.' : 'Quart ajouté.');
    // §retour Betty du 14/09/2026 (Planning point 1, "signaler en rouge au moment où on le
    // construit, pas après") : contrôles légaux + indisponibilité déclarée, vérifiés dès la
    // sauvegarde de CE quart, jamais un blocage (le quart est déjà enregistré ci-dessus).
    const employeeConcerne = employeeRepository.getById(data.employeeId);
    const violations = verifierControlesLegauxPlanning(data.employeeId, shiftRepository.getAll());
    if (violations.length) {
      const suffixe = violations.length > 1 ? ` (+${violations.length - 1} autre${violations.length > 2 ? 's' : ''} contrôle${violations.length > 2 ? 's' : ''})` : '';
      showToast(`Attention, ${employeeConcerne.prenom} ${employeeConcerne.nom} : ${violations[0].message}${suffixe}`, 'error');
    } else if (shiftChevaucheIndisponibilite(savedShift, employeeConcerne.indisponibilitesRecurrentes)) {
      showToast(`Attention : ce quart chevauche une indisponibilité déclarée par ${employeeConcerne.prenom} ${employeeConcerne.nom}.`, 'error');
    }
    render();
  });
}

function makeEmptyShiftDraft() {
  return { employeeId: '', weekday: 'Lun', heureDebut: '09:00', heureFin: '17:00', pauseMinutes: 30 };
}

/** Sprint SIRH premium §3 : glisser une case de congé/télétravail VALIDÉ (renderPlanningStatusCell
 * ne rend draggable que celles-là) vers une autre case du MÊME salarié déplace toute la période
 * (en conservant sa durée) de "delta" jours, où delta = date cible - date de la case source. Réutilise
 * leaveRepository.regulariser (déjà validé/testé, §régularisation) pour les congés et
 * moveTeleworkRequest (même niveau de validation, écrit pour cette fonctionnalité) pour le
 * télétravail — aucune nouvelle règle métier inventée, juste un nouveau point d'entrée vers les
 * règles existantes. */
function bindPlanningDragEvents() {
  let dragData = null;

  document.querySelectorAll('.planning-cell[data-drag-request-id]').forEach(cell => {
    cell.addEventListener('dragstart', (e) => {
      dragData = {
        requestId: cell.dataset.dragRequestId,
        requestType: cell.dataset.dragRequestType,
        employeeId: cell.dataset.dragEmployee,
        dateStr: cell.dataset.dragDate
      };
      e.dataTransfer.effectAllowed = 'move';
      cell.classList.add('planning-cell-dragging');
    });
    cell.addEventListener('dragend', () => cell.classList.remove('planning-cell-dragging'));
  });

  document.querySelectorAll('.planning-cell[data-drop-employee]').forEach(cell => {
    cell.addEventListener('dragover', (e) => {
      if (!dragData || cell.dataset.dropEmployee !== dragData.employeeId) return;
      e.preventDefault();
      cell.classList.add('planning-cell-drop-target');
    });
    cell.addEventListener('dragleave', () => cell.classList.remove('planning-cell-drop-target'));
    cell.addEventListener('drop', (e) => {
      e.preventDefault();
      cell.classList.remove('planning-cell-drop-target');
      if (!dragData || cell.dataset.dropEmployee !== dragData.employeeId) return;
      const targetDate = cell.dataset.dropDate;
      if (targetDate === dragData.dateStr) return;
      handlePlanningDrop(dragData, targetDate);
      dragData = null;
    });
  });
}

function handlePlanningDrop(dragData, targetDate) {
  // parseISODateLocal (pas `new Date(string)`, qui parse en UTC alors que getDate()/setDate()
  // lisent/écrivent en heure locale — décalage d'un jour possible selon le fuseau) : voir data.js.
  const deltaJours = daysBetween(parseISODateLocal(dragData.dateStr), parseISODateLocal(targetDate));

  if (dragData.requestType === 'leave') {
    const request = leaveRepository.getById(dragData.requestId);
    if (!request) return;
    // Même règle que le bouton "Régulariser" (canManageRequestFor exclut déjà le demandeur
    // lui-même) — sans ce contrôle, glisser-déposer sur "Mon planning" laissait n'importe qui
    // déplacer sa PROPRE demande déjà validée, contournant la séparation des tâches.
    if (!canManageRequestFor(request.employeeId)) { showToast('Action non autorisée.', 'error'); return; }
    const nouvelleDateDebut = toISODate(addDays(parseISODateLocal(request.dateDebut), deltaJours));
    const nouvelleDateFin = toISODate(addDays(parseISODateLocal(request.dateFin), deltaJours));
    const result = leaveRepository.regulariser(dragData.requestId, {
      typeId: request.typeId, dateDebut: nouvelleDateDebut, dateFin: nouvelleDateFin,
      demiJournee: request.demiJournee, motif: 'Déplacé par glisser-déposer (Planning)'
    });
    if (!result.success) { showToast(result.error, 'error'); return; }
    showToast('Demande déplacée.');
    render();
  } else if (dragData.requestType === 'telework') {
    const request = teleworkRepository.getById(dragData.requestId);
    if (!request) return;
    if (!canManageRequestFor(request.employeeId)) { showToast('Action non autorisée.', 'error'); return; }
    const nouvelleDateDebut = toISODate(addDays(parseISODateLocal(request.dateDebut), deltaJours));
    const nouvelleDateFin = toISODate(addDays(parseISODateLocal(request.dateFin), deltaJours));
    const result = moveTeleworkRequest(dragData.requestId, nouvelleDateDebut, nouvelleDateFin);
    if (!result.success) { showToast(result.error, 'error'); return; }
    showToast('Télétravail déplacé.');
    render();
  }
}

function shiftPlanningMonth(delta) {
  let month = state.planningMonth + delta;
  let year = state.planningYear;
  if (month < 0) { month = 11; year -= 1; }
  if (month > 11) { month = 0; year += 1; }
  state.planningMonth = month;
  state.planningYear = year;
  render();
}

// ---------------------------------------------------------------------------
// Vue : Télétravail (demandes + planning)
// ---------------------------------------------------------------------------

// ---- Sous-vue : Demandes ----

function getFilteredTeleworkRequests() {
  return applyStateFilters(scopeToVisibleEmployees(teleworkRepository.getAll()), state.teletravailFilters,
    [['employeeId', 'employeeId'], ['statut', 'statut']]);
}

function renderTeletravailDemandes() {
  const employees = getScopedEmployeesForFilters();
  const requests = getFilteredTeleworkRequests();
  const { pageItems, totalPages, page, pageStart } = paginate(requests, 'teletravailPage');
  // §amélioration du 09/09/2026 : même distinction que Congés (voir renderCongesDemandes) — "aucune
  // demande de télétravail" prêtait déjà à confusion, laissant croire que le module n'a jamais servi
  // même quand un filtre écarte simplement tout le monde.
  const emptyStateMessage = Object.values(state.teletravailFilters).some(Boolean)
    ? 'Aucune demande ne correspond à ces filtres.'
    : 'Aucune demande de télétravail pour l\'instant. Utilisez le bouton "+ Nouvelle demande" ci-dessus pour créer la première.';

  return `
    <div class="view-header-row">
      <p class="view-subtitle">${requests.length} demande${requests.length > 1 ? 's' : ''}</p>
      <button class="btn btn-primary" id="btn-new-telework-request">+ Nouvelle demande</button>
    </div>

    ${renderDraftsCard('teletravail')}

    ${renderFilterToggleBar('teletravail-filters', [state.teletravailFilters.employeeId, state.teletravailFilters.statut].filter(Boolean).length, 'teletravail')}
    <div class="toolbar card toolbar-collapsible" id="teletravail-filters">
      <select id="tt-filter-employee" class="input">
        <option value="">Tous les salariés</option>
        ${employees.map(e => `<option value="${e.id}" ${state.teletravailFilters.employeeId === e.id ? 'selected' : ''}>${personNameHtml(e)}</option>`).join('')}
      </select>
      <select id="tt-filter-statut" class="input">
        <option value="">Tous les statuts</option>
        ${['En attente', 'Validé', 'Refusé', 'Annulé'].map(s => `<option value="${s}" ${state.teletravailFilters.statut === s ? 'selected' : ''}>${s}</option>`).join('')}
      </select>
    </div>

    <div class="card table-card">
      ${requests.length === 0 ? `<div class="empty-state"><div class="empty-icon">${ICONS.laptop}</div><p>${escapeHtml(emptyStateMessage)}</p></div>` : `
        <table class="table mobile-cards">
          <thead><tr><th>Salarié</th><th>Période</th><th>Jours</th><th>Statut</th><th></th></tr></thead>
          <tbody>${pageItems.map(renderTeleworkRequestRow).join('')}</tbody>
        </table>
        ${renderPaginationControls(page, totalPages, pageStart, pageItems.length, requests.length)}
      `}
    </div>
  `;
}

function renderTeleworkRequestRow(r) {
  const employee = employeeRepository.getById(r.employeeId);
  if (!employee) return '';
  const user = authRepository.getCurrentUser();

  const periode = r.dateDebut === r.dateFin ? formatDate(r.dateDebut) : `${formatDate(r.dateDebut)} → ${formatDate(r.dateFin)}`;
  const actions = r.statut === 'En attente'
    // §tour de bugs du 07/09/2026 (point 5) : même correctif que Notes de frais — le demandeur peut
    // corriger/annuler sa propre demande tant qu'aucun valideur n'a encore agi dessus.
    ? `${canSelfCancelPendingRequest(r, user) ? `<button class="btn-link" data-edit-tt="${r.id}">Modifier</button><button class="btn-link btn-link-danger" data-self-cancel-tt="${r.id}">Annuler</button>` : ''}${canActOnRequestFor(r) ? `<button class="btn-link" data-approve-tt="${r.id}">Valider</button>` : ''}${canRefuserRequestFor(r) ? `<button class="btn-link btn-link-danger" data-refuse-tt="${r.id}">Refuser</button>` : ''}`
    : r.statut === 'Validé' && canManageRequestFor(r.employeeId) ? `<button class="btn-link btn-link-danger" data-cancel-tt="${r.id}">Annuler</button>` : '';

  return `
    <tr>
      <td class="row-title" data-label="Salarié">${personNameHtml(employee)}</td>
      <td data-label="Période">${periode}</td>
      <td data-label="Jours">${formatDurationFR(r.nbJours)}</td>
      <td data-label="Statut">${renderRequestStatutBadge(r)}</td>
      <td class="table-actions">
        <button class="btn-link" data-history="${r.id}">Historique</button>
        ${actions}
      </td>
    </tr>
  `;
}

function bindTeletravailDemandesEvents() {
  bindFilterToggleButtons();
  document.getElementById('btn-new-telework-request').addEventListener('click', () => openTeleworkRequestModal());
  bindDraftsCardEvents((draft) => openTeleworkRequestModal(undefined, draft));

  document.getElementById('tt-filter-employee').addEventListener('change', (e) => {
    state.teletravailFilters.employeeId = e.target.value;
    state.teletravailPage = 1;
    render();
  });
  document.getElementById('tt-filter-statut').addEventListener('change', (e) => {
    state.teletravailFilters.statut = e.target.value;
    state.teletravailPage = 1;
    render();
  });

  const ttPrevBtn = document.getElementById('btn-page-prev');
  if (ttPrevBtn) ttPrevBtn.addEventListener('click', () => { state.teletravailPage -= 1; render(); });
  const ttNextBtn = document.getElementById('btn-page-next');
  if (ttNextBtn) ttNextBtn.addEventListener('click', () => { state.teletravailPage += 1; render(); });

  document.querySelectorAll('[data-approve-tt]').forEach(btn => btn.addEventListener('click', () => handleApproveTelework(btn.dataset.approveTt)));
  document.querySelectorAll('[data-refuse-tt]').forEach(btn => btn.addEventListener('click', () => handleRefuseTelework(btn.dataset.refuseTt)));
  document.querySelectorAll('[data-cancel-tt]').forEach(btn => btn.addEventListener('click', () => handleCancelTelework(btn.dataset.cancelTt)));
  document.querySelectorAll('[data-edit-tt]').forEach(btn => btn.addEventListener('click', () => handleEditTelework(btn.dataset.editTt)));
  document.querySelectorAll('[data-self-cancel-tt]').forEach(btn => btn.addEventListener('click', () => handleSelfCancelTelework(btn.dataset.selfCancelTt)));
  bindHistoryButtons(teleworkRepository);
}

function handleEditTelework(id) {
  const request = teleworkRepository.getById(id);
  const user = authRepository.getCurrentUser();
  if (!request || !canSelfCancelPendingRequest(request, user)) { showToast('Action non autorisée.', 'error'); return; }
  openTeleworkRequestModal(undefined, undefined, undefined, request);
}

function handleSelfCancelTelework(id) {
  const request = teleworkRepository.getById(id);
  const user = authRepository.getCurrentUser();
  if (!request || !canSelfCancelPendingRequest(request, user)) { showToast('Action non autorisée.', 'error'); return; }
  openConfirm({
    title: 'Annuler votre demande de télétravail ?',
    message: 'Cette demande n\'a encore été validée par personne : elle sera annulée sans repasser par un refus.',
    confirmLabel: 'Annuler la demande',
    danger: true,
    onConfirm: () => {
      teleworkRepository.update(id, cancelRequest(request));
      auditLogRepository.logAudit('Annulation', 'Demande de télétravail', auditLabelForEmployee(request.employeeId), auditDetailsForActor());
      showToast('Demande annulée.');
      render();
    }
  });
}

function handleApproveTelework(id) {
  const request = teleworkRepository.getById(id);
  if (!request || !canActOnRequestFor(request)) { showToast('Action non autorisée.', 'error'); return; }
  const patch = advanceWorkflow(request, 'Validé', currentActorRoleLabel());
  teleworkRepository.update(id, patch);
  auditLogRepository.logAudit('Validation', 'Demande de télétravail', auditLabelForEmployee(request.employeeId), auditDetailsForActor());
  if (patch.statut !== 'En attente') {
    notifyRequesterEmail(request.id, 'teletravail', 'validee');
  }
  showToast('Télétravail validé.');
  render();
}

function handleRefuseTelework(id) {
  const request = teleworkRepository.getById(id);
  if (!request || !canRefuserRequestFor(request)) { showToast('Action non autorisée.', 'error'); return; }
  openRefuseModal({
    title: 'Refuser cette demande ?',
    message: 'Le salarié sera informé du refus.',
    onConfirm: (motif) => {
      teleworkRepository.update(id, refuseRequest(request, motif));
      auditLogRepository.logAudit('Refus', 'Demande de télétravail', `${auditLabelForEmployee(request.employeeId)} : ${motif}`, auditDetailsForActor());
      notifyRequesterEmail(request.id, 'teletravail', 'refusee', motif);
      showToast('Demande refusée.');
      render();
    }
  });
}

function handleCancelTelework(id) {
  const request = teleworkRepository.getById(id);
  if (!request || !canManageRequestFor(request.employeeId)) { showToast('Action non autorisée.', 'error'); return; }
  openConfirm({
    title: 'Annuler ce télétravail ?',
    message: 'Ce jour redeviendra un jour de présence au bureau.',
    confirmLabel: 'Annuler',
    danger: true,
    onConfirm: () => {
      teleworkRepository.update(id, cancelRequest(request));
      auditLogRepository.logAudit('Annulation', 'Demande de télétravail', auditLabelForEmployee(request.employeeId), auditDetailsForActor());
      showToast('Demande annulée.');
      render();
    }
  });
}

// ---- Modale : Nouvelle demande de télétravail ----

/** presetDate : préremplit début ET fin (choix rapide "Télétravail" depuis une case du calendrier,
 * §sprint refonte UX) — ignoré si un brouillon fournit déjà ses propres dates. Contrairement aux
 * congés/absences, une demande de télétravail n'a pas de notion de demi-journée dans ce modèle
 * (champ absent de makeEmptyTeleworkRequest) — pas ajouté ici pour ne pas étendre le modèle de
 * données au-delà de ce qui est demandé. */
function openTeleworkRequestModal(presetEmployeeId, draft, presetDate, editingRequest) {
  const employees = employeeRepository.getAll().filter(e => !e.archive);
  // §tour de bugs du 07/09/2026 (point 5, même famille que Notes de frais) : en modification, les
  // champs repartent de la demande existante, jamais d'un brouillon (les deux mécanismes ne se
  // recoupent jamais, une demande déjà envoyée n'est plus un brouillon).
  const champs = editingRequest
    ? { employeeId: editingRequest.employeeId, dateDebut: editingRequest.dateDebut, dateFin: editingRequest.dateFin, commentaire: editingRequest.commentaire }
    : (draft && draft.champs) || {};
  if (!draft && !editingRequest && presetDate) {
    champs.dateDebut = presetDate;
    champs.dateFin = presetDate;
  }
  state.editingTeleworkRequestId = editingRequest ? editingRequest.id : null;
  if (!editingRequest) beginDraftEdit(draft);

  const employeeField = editingRequest
    // Modification toujours restreinte à SA PROPRE demande (canSelfCancelPendingRequest côté
    // autorisation) — jamais de sélecteur, la réattribuer à quelqu'un d'autre n'aurait pas de sens.
    ? `<input type="hidden" id="f-employeeId" name="employeeId" value="${escapeHtml(champs.employeeId)}">
       <div class="form-field"><label>Salarié</label><input class="input" type="text" value="${personNameHtml(authRepository.getCurrentUser())}" disabled></div>`
    : employeeFieldForRequest(presetEmployeeId || champs.employeeId, employees);

  const html = `
    <div class="modal">
      <div class="modal-header">
        <h2>${editingRequest ? 'Modifier la demande de télétravail' : 'Nouvelle demande de télétravail'}</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="telework-request-form">
        <div class="modal-body">
          <div class="form-grid">
            ${employeeField}
            ${textField('dateDebut', 'Date de début', champs.dateDebut || '', true, 'date')}
            ${textField('dateFin', 'Date de fin', champs.dateFin || '', true, 'date')}
          </div>
          <div class="form-field" style="margin-top: 14px;">
            <label for="f-commentaire">Commentaire</label>
            <textarea class="input" id="f-commentaire" name="commentaire" rows="2">${escapeHtml(champs.commentaire || '')}</textarea>
          </div>
          <p class="text-muted" id="telework-quota-hint" style="margin-top: 12px;"></p>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          ${editingRequest ? '' : '<button type="button" class="btn btn-secondary" id="btn-save-draft">Enregistrer comme brouillon</button>'}
          <button type="submit" class="btn btn-primary">${editingRequest ? 'Enregistrer les modifications' : 'Envoyer la demande'}</button>
        </div>
      </form>
    </div>
  `;

  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');

  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('telework-request-form').addEventListener('submit', submitTeleworkRequestForm);
  const saveDraftBtn = document.getElementById('btn-save-draft');
  if (saveDraftBtn) saveDraftBtn.addEventListener('click', () => {
    saveDraftFromForm(document.getElementById('telework-request-form'), 'teletravail');
  });

  ['f-employeeId', 'f-dateDebut', 'f-dateFin'].forEach(fieldId => {
    document.getElementById(fieldId).addEventListener('change', updateTeleworkQuotaHint);
  });
  updateTeleworkQuotaHint();
}

function updateTeleworkQuotaHint() {
  const employeeId = document.getElementById('f-employeeId').value;
  const dateDebut = document.getElementById('f-dateDebut').value;
  const dateFin = document.getElementById('f-dateFin').value;
  const hint = document.getElementById('telework-quota-hint');
  if (!employeeId || !dateDebut) { hint.textContent = ''; return; }

  const employee = employeeRepository.getById(employeeId);
  const quota = settingsRepository.getSettings().teletravailQuotaSemaine;
  const weekDates = getWeekDatesContaining(dateDebut);
  const weekStart = toISODate(weekDates[0]);
  const weekEnd = toISODate(weekDates[6]);

  const activeRequests = teleworkRepository.getAll().filter(r => r.employeeId === employeeId && (r.statut === 'Validé' || r.statut === 'En attente'));
  let usedThisWeek = 0;
  activeRequests.forEach(r => {
    for (let cursor = parseISODateLocal(r.dateDebut); toISODate(cursor) <= r.dateFin; cursor.setDate(cursor.getDate() + 1)) {
      const ds = toISODate(cursor);
      if (ds >= weekStart && ds <= weekEnd) usedThisWeek += 1;
    }
  });

  let nbJoursLabel = '';
  if (dateFin) {
    const nbJours = computeWorkingDays(dateDebut, dateFin, false, employee, settingsRepository.getSettings());
    nbJoursLabel = ` · ${formatDurationFR(nbJours)} décomptés pour cette demande`;
  }

  hint.textContent = `Quota hebdomadaire : ${formatDurationFR(quota)}/semaine · déjà ${formatDurationFR(usedThisWeek)} utilisés cette semaine${nbJoursLabel}`;
}

/** Chevauchement actif (statut Validé ou En attente, comme le contrôle autoriserPlusieursDemandes)
 * entre [dateDebut, dateFin] et une demande existante d'un AUTRE domaine (congé/absence <-> télétravail)
 * pour le même salarié — on ne peut pas être à la fois en congé/absence et en télétravail le même jour.
 * Le télétravail n'a pas de notion de demi-journée : la présence d'un congé ce jour-là, même en
 * demi-journée, suffit à bloquer un télétravail (forcément journée entière) sur cette même date, et
 * réciproquement. Utilisé par submitLeaveRequestForm et submitTeleworkRequestForm. */
function hasActiveRequestOverlap(requests, employeeId, dateDebut, dateFin, excludeRequestId) {
  return requests.some(r =>
    r.id !== excludeRequestId && r.employeeId === employeeId && r.statut !== 'Refusé' && r.statut !== 'Annulé' &&
    r.dateDebut <= dateFin && r.dateFin >= dateDebut);
}

/** Chevauchement entre DEUX congés/absences de TYPES DIFFÉRENTS pour le même salarié — distinct du
 * contrôle autoriserPlusieursDemandes (qui ne compare que les demandes du MÊME type, et dont le
 * réglage par type doit rester seul maître sur ce cas : exclu ici via `typeId !== r.typeId`, sinon
 * on écraserait un autoriserPlusieursDemandes=true explicitement configuré par l'admin). On ne peut
 * pas être à la fois en RTT et en congés payés le même jour, sauf sur des demi-journées
 * complémentaires (matin + après-midi) d'une même date isolée — cas réel qu'un blocage brut
 * casserait. Toute demande qui s'étend sur plusieurs jours, ou une demi-journée qui chevauche une
 * journée entière, reste un conflit direct. */
function hasConflictingLeaveRequest(employeeId, typeId, dateDebut, dateFin, demiJournee, excludeRequestId) {
  return leaveRepository.getAll().some(r => {
    if (r.id === excludeRequestId) return false;
    if (r.employeeId !== employeeId) return false;
    if (r.typeId === typeId) return false;
    if (r.statut === 'Refusé' || r.statut === 'Annulé') return false;
    if (!(r.dateDebut <= dateFin && r.dateFin >= dateDebut)) return false;
    const bothSingleDay = r.dateDebut === r.dateFin && dateDebut === dateFin;
    if (!bothSingleDay) return true;
    if (!demiJournee || !r.demiJournee) return true;
    return demiJournee === r.demiJournee;
  });
}

/** Semaine (lundi ISO) où la demande [dateDebut, dateFin] ferait dépasser le quota hebdomadaire, en tenant
 * compte des demandes déjà actives (Validé/En attente) ; ne compte que les jours travaillés de l'employé,
 * comme nbJours. Retourne null si aucun dépassement. */
function findTeleworkWeekOverQuota(employeeId, dateDebut, dateFin, employee, quota, excludeRequestId) {
  const workedDays = employee.joursTravailles && employee.joursTravailles.length ? employee.joursTravailles : ['Lun', 'Mar', 'Mer', 'Jeu', 'Ven'];
  const dayLabels = ['Dim', 'Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam'];
  const usageByWeek = {};

  const tally = (start, end) => {
    for (let cursor = parseISODateLocal(start); toISODate(cursor) <= end; cursor.setDate(cursor.getDate() + 1)) {
      if (!workedDays.includes(dayLabels[cursor.getDay()])) continue;
      const weekStart = toISODate(getWeekDatesContaining(toISODate(cursor))[0]);
      usageByWeek[weekStart] = (usageByWeek[weekStart] || 0) + 1;
    }
  };

  // excludeRequestId : la demande qu'on est en train de déplacer (§3, glisser-déposer) ne doit pas
  // se compter elle-même deux fois (une fois à son ancienne date via getAll(), une fois à sa nouvelle
  // date via l'appel tally(dateDebut, dateFin) ci-dessous).
  teleworkRepository.getAll()
    .filter(r => r.employeeId === employeeId && r.id !== excludeRequestId && (r.statut === 'Validé' || r.statut === 'En attente'))
    .forEach(r => tally(r.dateDebut, r.dateFin));
  tally(dateDebut, dateFin);

  const overWeek = Object.entries(usageByWeek).find(([, count]) => count > quota);
  return overWeek ? { weekStart: overWeek[0], used: overWeek[1] } : null;
}

/** Sprint SIRH premium §3 : déplace une demande de télétravail validée par glisser-déposer (Planning
 * Semaine/Mois) — mêmes règles de validation que submitTeleworkRequestForm (période d'emploi, jour
 * travaillé, chevauchement congé/autre télétravail, quota hebdomadaire), pas de raccourci. Pas
 * d'équivalent "régulariser" pour le télétravail (contrairement aux congés, §régularisation) : cette
 * fonction en tient lieu, sous une forme bornée au strict nécessaire pour le déplacement. */
function moveTeleworkRequest(id, nouvelleDateDebut, nouvelleDateFin) {
  const request = teleworkRepository.getById(id);
  if (!request) return { success: false, error: 'Demande introuvable.' };
  const employee = employeeRepository.getById(request.employeeId);
  if (!employee) return { success: false, error: 'Salarié introuvable.' };

  if (nouvelleDateFin < nouvelleDateDebut) {
    return { success: false, error: 'La date de fin ne peut pas être avant la date de début.' };
  }
  if (employee.dateEmbauche && nouvelleDateDebut < employee.dateEmbauche) {
    return { success: false, error: `La date de début ne peut pas être avant la date d'embauche (${formatDate(employee.dateEmbauche)}).` };
  }
  if (employee.dateDepart && nouvelleDateFin > employee.dateDepart) {
    return { success: false, error: `La date de fin ne peut pas être après la date de départ (${formatDate(employee.dateDepart)}).` };
  }

  const nbJours = computeWorkingDays(nouvelleDateDebut, nouvelleDateFin, false, employee, settingsRepository.getSettings());
  if (nbJours <= 0) {
    return { success: false, error: 'La période cible ne comporte aucun jour travaillé.' };
  }

  const quota = settingsRepository.getSettings().teletravailQuotaSemaine;
  const overQuota = findTeleworkWeekOverQuota(request.employeeId, nouvelleDateDebut, nouvelleDateFin, employee, quota, id);
  if (overQuota) {
    return { success: false, error: `Quota de télétravail dépassé pour la semaine du ${formatDate(overQuota.weekStart)} (${formatDurationFR(overQuota.used)}/${formatDurationFR(quota)}).` };
  }

  if (hasActiveRequestOverlap(leaveRepository.getAll(), request.employeeId, nouvelleDateDebut, nouvelleDateFin)) {
    return { success: false, error: 'Ce salarié a déjà une demande de congé/absence active sur cette période.' };
  }
  if (hasActiveRequestOverlap(teleworkRepository.getAll(), request.employeeId, nouvelleDateDebut, nouvelleDateFin, id)) {
    return { success: false, error: 'Ce salarié a déjà une autre demande de télétravail active sur cette période.' };
  }

  const historique = (request.historique || []).concat([{
    date: new Date().toISOString(),
    action: `Déplacé (glisser-déposer) : ${formatDate(request.dateDebut)}${request.dateDebut !== request.dateFin ? ' → ' + formatDate(request.dateFin) : ''} devient ${formatDate(nouvelleDateDebut)}${nouvelleDateDebut !== nouvelleDateFin ? ' → ' + formatDate(nouvelleDateFin) : ''}`
  }]);
  teleworkRepository.update(id, { dateDebut: nouvelleDateDebut, dateFin: nouvelleDateFin, nbJours, historique });
  auditLogRepository.logAudit('Modification', 'Télétravail déplacé (glisser-déposer)', `${employee.prenom} ${employee.nom} · ${formatDate(nouvelleDateDebut)}${nouvelleDateDebut !== nouvelleDateFin ? ' au ' + formatDate(nouvelleDateFin) : ''}`);
  return { success: true };
}

async function submitTeleworkRequestForm(evt) {
  evt.preventDefault();
  const form = evt.target;
  const formData = new FormData(form);
  const employeeId = formData.get('employeeId');
  const dateDebut = formData.get('dateDebut');
  const dateFin = formData.get('dateFin');

  if (!employeeId) {
    showToast('Sélectionnez un salarié.', 'error');
    return;
  }

  if (dateDebut && dateFin && dateFin < dateDebut) {
    showToast('La date de fin ne peut pas être avant la date de début.', 'error');
    return;
  }

  // §tour de bugs du 07/09/2026 : mêmes contrôles que submitLeaveRequestForm, absents ici jusqu'à
  // présent — un salarié pouvait poser du télétravail dans le passé, ou en dehors de sa période
  // d'emploi (avant son embauche, après son départ). Le déplacement par glisser-déposer d'une
  // demande déjà validée (moveTeleworkRequest) applique déjà cette règle ; la création initiale ne
  // l'appliquait pas, malgré un commentaire affirmant à tort qu'elles partageaient les mêmes règles.
  if (authRepository.getCurrentUser().role === ROLES.SALARIE && dateDebut < toISODate(new Date())) {
    showToast('Vous ne pouvez pas saisir une absence dont la date de début est déjà passée.', 'error');
    return;
  }

  const employee = employeeRepository.getById(employeeId);
  if (employee.dateEmbauche && dateDebut < employee.dateEmbauche) {
    showToast(`La date de début ne peut pas être avant la date d'embauche (${formatDate(employee.dateEmbauche)}).`, 'error');
    return;
  }
  if (employee.dateDepart && dateFin > employee.dateDepart) {
    showToast(`La date de fin ne peut pas être après la date de départ (${formatDate(employee.dateDepart)}).`, 'error');
    return;
  }

  // §retour Betty du 18/09/2026 (point 8) : voir le même contrôle dans submitLeaveRequestForm.
  if (!hasModuleLicense(employee, 'planning')) {
    showToast(`${employee.prenom} ${employee.nom} n'a pas d'accès au module Planning : demandez à un Propriétaire/RH de lui attribuer une licence (Paramètres > Abonnement > Gérer les accès).`, 'error');
    return;
  }

  const nbJours = computeWorkingDays(dateDebut, dateFin, false, employee, settingsRepository.getSettings());

  if (nbJours <= 0) {
    showToast('La période sélectionnée ne comporte aucun jour travaillé.', 'error');
    return;
  }

  const quota = settingsRepository.getSettings().teletravailQuotaSemaine;
  const overQuota = findTeleworkWeekOverQuota(employeeId, dateDebut, dateFin, employee, quota);
  if (overQuota) {
    showToast(`Quota de télétravail dépassé pour la semaine du ${formatDate(overQuota.weekStart)} (${formatDurationFR(overQuota.used)}/${formatDurationFR(quota)}).`, 'error');
    return;
  }

  if (hasActiveRequestOverlap(leaveRepository.getAll(), employeeId, dateDebut, dateFin)) {
    showToast('Ce salarié a déjà une demande de congé/absence active sur cette période.', 'error');
    return;
  }
  // §tour de bugs du 07/09/2026 (point 5) : exclut la demande elle-même en modification, sinon elle
  // se signalerait comme son propre chevauchement — même principe que moveTeleworkRequest ci-dessus.
  if (hasActiveRequestOverlap(teleworkRepository.getAll(), employeeId, dateDebut, dateFin, state.editingTeleworkRequestId)) {
    showToast('Ce salarié a déjà une autre demande de télétravail active sur cette période.', 'error');
    return;
  }

  const submitBtn = evt.target.querySelector('button[type="submit"]');
  if (submitBtn) submitBtn.disabled = true;

  if (state.editingTeleworkRequestId) {
    const id = state.editingTeleworkRequestId;
    const original = teleworkRepository.getById(id);
    const historique = ((original && original.historique) || []).slice();
    historique.push({ date: new Date().toISOString(), action: 'Modifiée par le demandeur' });
    teleworkRepository.update(id, { dateDebut, dateFin, nbJours, commentaire: formData.get('commentaire') || '', historique });
    auditLogRepository.logAudit('Modification', 'Demande de télétravail', auditLabelForEmployee(employeeId), auditDetailsForActor());
    showToast('Demande de télétravail modifiée.');
    state.editingTeleworkRequestId = null;
    closeModal();
    navigateTo('absences', { absencesHubTab: 'teletravail', teletravailTab: 'demandes' });
    return;
  }

  const createdRequest = await teleworkRepository.create({ employeeId, dateDebut, dateFin, nbJours, commentaire: formData.get('commentaire') || '' });

  finalizeDraftEdit();
  showToast('Demande de télétravail envoyée.');
  // §correctif audit du 23/08/2026 (2.3), même mécanisme que openLeaveRequestModal.
  if (createdRequest.workflowEscalated) {
    showToast('Aucun validateur direct n\'a été trouvé pour cette demande : un RH ou un membre de la Direction devra la valider manuellement.', 'error');
  }
  closeModal();
  // Ouverte depuis un clic sur le calendrier : on y retourne (même logique que openLeaveRequestModal).
  if (state._leaveRequestReturnToCalendar) {
    state._leaveRequestReturnToCalendar = false;
    navigateTo('calendrier');
  } else {
    navigateTo('absences', { absencesHubTab: 'teletravail', teletravailTab: 'demandes' });
  }
}

// ---- Sous-vue : Planning hebdomadaire ----

function getWeekDates(weekOffset) {
  return getWeekDatesContaining(toISODate(addDays(new Date(), weekOffset * 7)));
}

/** §retour Betty du 10/09/2026 ("fais le même planning pour le planning télétravail dans congés et
 * absences") : reprend la STRUCTURE de la grille de quarts de Planning (renderPlanningPostes) —
 * en-tête "Prénom" triable, regroupement par SERVICE uniquement (groupEmployeesByService, plus de
 * sous-groupe équipe), cartes de statut en carte flottante (accent gauche, ombre, coins arrondis,
 * voir .teletravail-planning-card dans style.css) au lieu du remplissage bord à bord d'avant. Betty a
 * explicitement demandé de GARDER les trois couleurs sémantiques par statut (bureau/télétravail/
 * congé, voir .planning-shift-office/-remote/-leave) — seule la carte change de FORME, jamais la
 * couleur en une teinte unique comme sur la grille de quarts (qui n'a qu'un seul statut possible,
 * contrairement à ce planning-ci). La ligne de synthèse "Présents au bureau" (propre à cet écran)
 * reste inchangée en bas de tableau. */
function renderTeletravailPlanning() {
  const weekDates = getWeekDates(state.teletravailWeekOffset);
  const visibleIds = getVisibleEmployeeIdsForCurrentUser();
  let employees = employeeRepository.getAll().filter(e => !e.archive && isEmployedDuringPeriod(e, toISODate(weekDates[0]), toISODate(weekDates[6])));
  if (visibleIds !== null) employees = employees.filter(e => visibleIds.includes(e.id));
  const teleworkRequests = teleworkRepository.getAll().filter(r => r.statut === 'Validé' || r.statut === 'En attente');
  const leaveRequests = leaveRepository.getAll().filter(r => r.statut === 'Validé' || r.statut === 'En attente');

  const sortEmployees = (list) => list.slice().sort((a, b) =>
    state.teletravailSortDir === 'desc' ? b.prenom.localeCompare(a.prenom) : a.prenom.localeCompare(b.prenom)
  );

  const bodyHtml = groupEmployeesByService(employees).map(g => {
    const groupEmployees = sortEmployees(g.employees);
    return `
      <tr class="planning-service-header"><td colspan="${weekDates.length + 1}">
        <div class="poste-group-header-row">
          <span>${escapeHtml(g.service)} <span class="text-muted">(${groupEmployees.length})</span></span>
        </div>
      </td></tr>
      ${groupEmployees.map(e => `
        <tr>
          <td class="planning-employee-cell">
            ${renderAvatar(e)}
            <div class="planning-employee-info">
              ${personNameWithPosteHtml(e)}
              ${renderPlanningEmployeeBadges(e)}
            </div>
          </td>
          ${renderPlanningDayCells(e, weekDates.map(toISODate), leaveRequests, teleworkRequests, true)}
        </tr>
      `).join('')}
    `;
  }).join('');

  return `
    <div class="view-header-row">
      <p class="view-subtitle">Semaine du ${formatDate(toISODate(weekDates[0]))} au ${formatDate(toISODate(weekDates[6]))}</p>
      <div class="calendar-nav">
        <button class="btn btn-secondary btn-sm" id="btn-week-prev">← Précédente</button>
        <button class="btn btn-secondary btn-sm" id="btn-week-today">Cette semaine</button>
        <button class="btn btn-secondary btn-sm" id="btn-week-next">Suivante →</button>
      </div>
    </div>
    <div class="card table-card planning-scroll-card teletravail-planning-card">
      ${employees.length === 0 ? `<div class="empty-state"><div class="empty-icon">${ICONS.schedule}</div><p>Aucun salarié à afficher.</p></div>` : `
        <table class="table planning-table">
          <thead>
            <tr>
              <th id="btn-teletravail-sort-name" style="cursor: pointer;">↕ Prénom (${state.teletravailSortDir === 'desc' ? 'Z-A' : 'A-Z'}) <span style="opacity:0.6;">▾</span></th>
              ${weekDates.map(d => `<th>${WEEKDAY_LABELS[(d.getDay() + 6) % 7]} ${d.getDate()}</th>`).join('')}
            </tr>
          </thead>
          <tbody>
            ${bodyHtml}
            <tr class="planning-summary-row">
              <td><strong>Présents au bureau</strong></td>
              ${weekDates.map(d => `<td>${countPresentOnDate(d, employees, teleworkRequests, leaveRequests)}</td>`).join('')}
            </tr>
          </tbody>
        </table>
      `}
    </div>
  `;
}

function countPresentOnDate(date, employees, teleworkRequests, leaveRequests) {
  const dateStr = toISODate(date);
  const weekday = WEEKDAY_LABELS[(date.getDay() + 6) % 7];
  return employees.filter(e => {
    if (!(e.joursTravailles || []).includes(weekday)) return false;
    const onLeave = leaveRequests.some(r => r.employeeId === e.id && dateStr >= r.dateDebut && dateStr <= r.dateFin);
    if (onLeave) return false;
    const remote = teleworkRequests.some(r => r.employeeId === e.id && dateStr >= r.dateDebut && dateStr <= r.dateFin);
    return !remote;
  }).length;
}

function bindTeletravailPlanningEvents() {
  document.getElementById('btn-week-prev').addEventListener('click', () => { state.teletravailWeekOffset -= 1; render(); });
  document.getElementById('btn-week-next').addEventListener('click', () => { state.teletravailWeekOffset += 1; render(); });
  document.getElementById('btn-week-today').addEventListener('click', () => { state.teletravailWeekOffset = 0; render(); });
  // §retour Betty du 10/09/2026 : même en-tête triable que la grille de quarts de Planning.
  const sortBtn = document.getElementById('btn-teletravail-sort-name');
  if (sortBtn) sortBtn.addEventListener('click', () => {
    state.teletravailSortDir = state.teletravailSortDir === 'desc' ? 'asc' : 'desc';
    render();
  });
}

// ---------------------------------------------------------------------------
// Pointeuse QR (§demande Betty du 11/09/2026) — un salarié pointe son arrivée puis son départ en
// scannant, depuis SON téléphone (caméra, voir openPointageScanModal), le QR fixe affiché à
// l'accueil de son établissement (généré depuis Paramètres > Établissements, voir
// renderEtablissementCard/openPointageQrModal). Lecture QR 100% locale via jsQR (vendu localement,
// jsqr.js, même patron que qrcode.js pour la génération) : aucune image envoyée à un serveur.
// ---------------------------------------------------------------------------

/** §retour Betty du 14/09/2026 ("il faut que pour la pointeuse sur la page on voit qui a pointé") :
 * qui peut voir l'équipe ailleurs dans l'app (Congés, Notes de frais...) peut désormais voir qui a
 * pointé aujourd'hui, ici — même portée que scopeToVisibleEmployees (soi-même exclu, un manager ne
 * voit que son équipe, RH/Propriétaire/Comptabilité voient tout le monde). Retourne '' (pas de
 * carte) pour un salarié sans personne à voir, plutôt qu'une carte vide sans intérêt. */
/** §retour Betty du 14/09/2026 (Pointeuse QR point 2, "régularisation par le manager") : même
 * critère que qui affiche/régénère le QR (manager/rh/propriétaire) — un salarié ne corrige jamais
 * le pointage d'un tiers, encore moins le sien. */
function canRegulariserPointages() {
  const user = authRepository.getCurrentUser();
  return ['manager', 'rh', 'proprietaire'].includes(user.role);
}

function renderPointeuseEquipe() {
  const user = authRepository.getCurrentUser();
  const visibleIds = getVisibleEmployeeIdsForCurrentUser();
  const employees = employeeRepository.getAll()
    .filter(e => e.id !== user.id && !e.archive && (visibleIds === null || visibleIds.includes(e.id)))
    .sort((a, b) => a.nom.localeCompare(b.nom));
  if (!employees.length) return '';

  const canRegulariser = canRegulariserPointages();
  const today = toISODate(new Date());
  const rows = employees.map(e => {
    const pointagesDuJour = pointageRepository.getForEmployeeOnDate(e.id, today);
    const dernierDuJour = pointagesDuJour[pointagesDuJour.length - 1];
    const statutHtml = !dernierDuJour
      ? `<span class="badge badge-muted">Non pointé</span>`
      : !dernierDuJour.heureDepart
        ? `<span class="badge badge-success">${icon(ICONS.checkCircle, 12)} Arrivé à ${escapeHtml(dernierDuJour.heureArrivee)}</span>`
        : `<span class="badge badge-muted">Départ à ${escapeHtml(dernierDuJour.heureDepart)}</span>`;
    return `<tr><td>${personNameHtml(e)}</td><td>${statutHtml}</td><td>${canRegulariser ? `<button type="button" class="btn-link" data-regulariser-pointage="${e.id}">Régulariser</button>` : ''}</td></tr>`;
  }).join('');

  return `
    <div class="card" style="margin-top: 16px;">
      <h2>Qui a pointé aujourd'hui</h2>
      <table class="table">
        <thead><tr><th>Salarié</th><th>Statut</th><th></th></tr></thead>
        <tbody>${rows}</tbody>
      </table>
    </div>
    ${canRegulariser ? renderEcartsPointageCard(employees) : ''}
  `;
}

/** §retour Betty du 14/09/2026 (Pointeuse QR point 5, "écarts et alertes") : constats des 7
 * derniers jours (hier inclus, jamais aujourd'hui — une journée en cours n'a pas encore de "départ"
 * à comparer). Purement informatif, jamais un blocage ni une notation du salarié. */
function renderEcartsPointageCard(employees) {
  const allShifts = shiftRepository.getAll();
  const constats = [];
  for (let i = 1; i <= 7; i++) {
    const date = addDays(new Date(), -i);
    const dateStr = toISODate(date);
    const weekday = WEEKDAY_LABELS[(date.getDay() + 6) % 7];
    employees.forEach(e => {
      const ecarts = calculerEcartsPointageJour(e.id, dateStr, weekday, allShifts, pointageRepository.getForEmployeeOnDate(e.id, dateStr));
      ecarts.forEach(ecart => constats.push({ employee: e, date: dateStr, ecart }));
    });
  }
  if (!constats.length) return '';
  constats.sort((a, b) => b.date.localeCompare(a.date));
  return `
    <div class="card" style="margin-top: 16px;">
      <h2>Écarts constatés (7 derniers jours)</h2>
      ${constats.slice(0, 20).map(c => `
        <div class="mini-list-item">
          <span>${formatDate(c.date)} · ${personNameHtml(c.employee)} · ${escapeHtml(c.ecart.message)}</span>
          <span class="badge badge-${c.ecart.type === 'oubli' ? 'muted' : 'warning'}">${c.ecart.type === 'oubli' ? 'Oubli' : c.ecart.type === 'retard' ? 'Retard' : 'Dépassement'}</span>
        </div>
      `).join('')}
    </div>
  `;
}

function openRegulariserPointageModal(employeeId, dateStr) {
  const employee = employeeRepository.getById(employeeId);
  if (!employee) return;
  const date = dateStr || toISODate(new Date());
  const pointagesDuJour = pointageRepository.getForEmployeeOnDate(employeeId, date);
  const dernier = pointagesDuJour[pointagesDuJour.length - 1];
  const etablissements = etablissementRepository.getAll();

  const html = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>Régulariser le pointage</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="regulariser-pointage-form">
        <div class="modal-body">
          <p class="text-muted">${personNameHtml(employee)} — ${formatDate(date)}</p>
          ${!dernier ? `<p class="text-muted">Aucun pointage ce jour-là : cette action en crée un.</p>
            <div class="form-field"><label for="f-etablissement">Établissement</label>
              <select class="input" id="f-etablissement">${etablissements.map(et => `<option value="${et.id}">${escapeHtml(et.nom)}</option>`).join('')}</select>
            </div>` : ''}
          <div class="form-grid">
            <div class="form-field"><label for="f-heure-arrivee">Arrivée</label><input class="input" type="time" id="f-heure-arrivee" value="${dernier ? escapeHtml(dernier.heureArrivee || '') : ''}" required></div>
            <div class="form-field"><label for="f-heure-depart">Départ</label><input class="input" type="time" id="f-heure-depart" value="${dernier ? escapeHtml(dernier.heureDepart || '') : ''}"></div>
          </div>
          <div class="form-field" style="margin-top: 12px;">
            <label for="f-motif-regularisation">Motif *</label>
            <input class="input" type="text" id="f-motif-regularisation" placeholder="Ex. oubli de pointage" required>
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="submit" class="btn btn-primary">Enregistrer</button>
        </div>
      </form>
    </div>
  `;
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');
  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('regulariser-pointage-form').addEventListener('submit', (evt) => {
    evt.preventDefault();
    const motif = document.getElementById('f-motif-regularisation').value.trim();
    if (!motif) { showToast('Indiquez un motif.', 'error'); return; }
    const heureArrivee = document.getElementById('f-heure-arrivee').value;
    const heureDepart = document.getElementById('f-heure-depart').value || null;
    const auteurId = authRepository.getCurrentUser().id;
    const result = dernier
      ? pointageRepository.regulariser(dernier.id, { heureArrivee, heureDepart }, motif, auteurId)
      : pointageRepository.ajouterOublie(employeeId, document.getElementById('f-etablissement').value, date, heureArrivee, heureDepart, motif, auteurId);
    if (!result.success) { showToast(result.error, 'error'); return; }
    showToast('Pointage régularisé.');
    closeModal();
    render();
  });
}

/** §retour Betty du 19/09/2026 (blocage 5.2, "la pointeuse est plafonnée à sept jours") : "pour
 * vérifier un pointage contesté du mois dernier au moment de la paie, c'est impossible depuis cet
 * écran" — remplacé le plafond dur de 7 jours par un sélecteur de mois (state.pointeuseHistoriqueYear/
 * Month, même patron que ticketsYear/Month, voir shiftTicketsMonth). "Suivant" reste désactivé au-delà
 * du mois en cours : un pointage futur n'existe par définition jamais, un mois vide y serait juste
 * déroutant. */
function joursDuMoisPointeuse(user, year, month) {
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const historique = [];
  for (let day = 1; day <= daysInMonth; day++) {
    const date = toISODate(new Date(year, month, day));
    if (date > toISODate(new Date())) break; // jamais un jour futur, même à l'intérieur du mois en cours
    const pointages = pointageRepository.getForEmployeeOnDate(user.id, date);
    if (pointages.length) historique.push({ date, pointages });
  }
  return historique.reverse(); // le plus récent en premier, comme l'ancien historique 7 jours
}

function renderPointeuse() {
  const user = authRepository.getCurrentUser();
  const today = toISODate(new Date());
  const todaysPointages = pointageRepository.getForEmployeeOnDate(user.id, today);
  const dernier = todaysPointages[todaysPointages.length - 1];
  const enCours = dernier && !dernier.heureDepart;

  const now = new Date();
  const estMoisEnCours = state.pointeuseHistoriqueYear === now.getFullYear() && state.pointeuseHistoriqueMonth === now.getMonth();
  const historique = joursDuMoisPointeuse(user, state.pointeuseHistoriqueYear, state.pointeuseHistoriqueMonth);

  return `
    <div class="view-header">
      <h1>Pointeuse</h1>
      <p class="view-subtitle">Pointez votre arrivée puis votre départ en scannant le QR affiché sur votre lieu de travail.</p>
    </div>

    <div class="card pointage-today-card">
      ${enCours
        ? `<p class="pointage-today-status">${icon(ICONS.checkCircle, 16)} Arrivée enregistrée à <strong>${escapeHtml(dernier.heureArrivee)}</strong> — en cours.</p>`
        : dernier
          ? `<p class="pointage-today-status">${icon(ICONS.checkCircle, 16)} Aujourd'hui : ${escapeHtml(dernier.heureArrivee)} → ${escapeHtml(dernier.heureDepart)} (${formatNumberFR(round2(todaysPointages.reduce((sum, p) => sum + computeDureeTravailleeMinutes(p), 0) / 60))} h travaillées).</p>`
          : `<p class="text-muted pointage-today-status">Aucun pointage aujourd'hui.</p>`}
      <button type="button" class="btn btn-primary" id="btn-open-scan-pointage">${icon(ICONS.scanFrame, 16)} Scanner le QR</button>
    </div>

    ${['manager', 'proprietaire'].includes(user.role) ? `
      <div class="card" style="margin-top: 16px;">
        <h2>QR de pointage</h2>
        <p class="text-muted" style="margin: 0 0 12px;">À afficher en direct sur un écran à l'accueil (jamais imprimé, voir la fenêtre du QR), jusqu'ici accessible uniquement depuis Paramètres &gt; Établissements (RH/Propriétaire).</p>
        <div class="badge-row" style="gap: 10px;">
          ${etablissementRepository.getAll().map(etab => `
            <button type="button" class="btn btn-secondary btn-sm" data-pointage-qr-etablissement="${etab.id}">${icon(ICONS.scanFrame, 13)} ${escapeHtml(etab.nom)}</button>
          `).join('')}
        </div>
      </div>
    ` : ''}

    ${renderPointeuseEquipe()}

    <div class="card" style="margin-top: 16px;">
      <div style="display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap;">
        <h2>Historique — ${MONTH_NAMES[state.pointeuseHistoriqueMonth]} ${state.pointeuseHistoriqueYear}</h2>
        <div class="detail-header-actions">
          <button class="btn btn-secondary btn-sm" id="btn-pointeuse-historique-prev">← Précédent</button>
          <button class="btn btn-secondary btn-sm" id="btn-pointeuse-historique-today">Ce mois-ci</button>
          <button class="btn btn-secondary btn-sm" id="btn-pointeuse-historique-next" ${estMoisEnCours ? 'disabled' : ''}>Suivant →</button>
        </div>
      </div>
      ${historique.length ? `
        <table class="table">
          <thead><tr><th>Date</th><th>Arrivée</th><th>Départ</th><th>Durée</th></tr></thead>
          <tbody>
            ${historique.map(h => h.pointages.map(p => `
              <tr>
                <td>${formatDate(h.date)}</td>
                <td>${escapeHtml(p.heureArrivee || '—')}</td>
                <td>${escapeHtml(p.heureDepart || '—')}</td>
                <td>${p.heureDepart ? formatNumberFR(round2(computeDureeTravailleeMinutes(p) / 60)) + ' h' : '—'}</td>
              </tr>
            `).join('')).join('')}
          </tbody>
        </table>
      ` : `
        <div class="empty-state">
          <div class="empty-icon">${icon(ICONS.schedule, 26)}</div>
          <p>Aucun pointage ${estMoisEnCours ? 'ce mois-ci' : `en ${MONTH_NAMES[state.pointeuseHistoriqueMonth]} ${state.pointeuseHistoriqueYear}`}.</p>
        </div>
      `}
    </div>

    ${renderRapportMensuelPointageCard(user)}
  `;
}

/** §retour Betty du 14/09/2026 (Pointeuse QR point 4, "rapport mensuel validé par le salarié") :
 * proposé pour le mois PRÉCÉDENT une fois celui-ci terminé (jamais le mois en cours, encore
 * incomplet) — le salarié confirme ("c'est exact") ou conteste (avec un commentaire obligatoire).
 * C'est cette confirmation explicite qui donne sa valeur probante au décompte en cas de litige. */
function renderRapportMensuelPointageCard(user) {
  const now = new Date();
  const moisPrecedent = new Date(now.getFullYear(), now.getMonth() - 1, 1);
  const year = moisPrecedent.getFullYear();
  const month = moisPrecedent.getMonth();
  const monthKey = ticketsMonthKey(year, month);
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const pointagesDuMois = [];
  for (let day = 1; day <= daysInMonth; day++) {
    const dateStr = toISODate(new Date(year, month, day));
    pointageRepository.getForEmployeeOnDate(user.id, dateStr).forEach(p => pointagesDuMois.push(p));
  }
  if (!pointagesDuMois.length) return '';
  const totalHeures = round2(pointagesDuMois.reduce((sum, p) => sum + computeDureeTravailleeMinutes(p), 0) / 60);
  const validation = (user.pointageValidationsMensuelles || {})[monthKey];

  return `
    <div class="card" style="margin-top: 16px;">
      <h2>Rapport mensuel — ${MONTH_NAMES[month]} ${year}</h2>
      <p class="text-muted">${pointagesDuMois.length} pointage${pointagesDuMois.length > 1 ? 's' : ''} · ${formatNumberFR(totalHeures)} h travaillées au total.</p>
      ${validation
        ? `<p class="${validation.statut === 'valide' ? '' : 'text-danger'}">${icon(validation.statut === 'valide' ? ICONS.checkCircle : ICONS.warningTriangle, 14)} ${validation.statut === 'valide' ? 'Validé' : 'Contesté'} le ${formatDate(validation.date.slice(0, 10))}${validation.commentaire ? ` · ${escapeHtml(validation.commentaire)}` : ''}</p>`
        : `<div class="detail-header-actions">
            <button type="button" class="btn btn-primary btn-sm" id="btn-valider-pointage-mensuel">C'est exact</button>
            <button type="button" class="btn btn-secondary btn-sm" id="btn-contester-pointage-mensuel">Contester</button>
          </div>`}
    </div>
  `;
}

/** Même patron que shiftTicketsMonth (Tickets restaurant) — jamais au-delà du mois en cours (voir
 * estMoisEnCours, renderPointeuse) : un mois futur n'aurait jamais de pointage à afficher. */
function shiftPointeuseHistoriqueMonth(delta) {
  let month = state.pointeuseHistoriqueMonth + delta;
  let year = state.pointeuseHistoriqueYear;
  if (month < 0) { month = 11; year -= 1; }
  if (month > 11) { month = 0; year += 1; }
  const now = new Date();
  if (year > now.getFullYear() || (year === now.getFullYear() && month > now.getMonth())) return;
  state.pointeuseHistoriqueMonth = month;
  state.pointeuseHistoriqueYear = year;
  render();
}

function bindPointeuseEvents() {
  document.getElementById('btn-open-scan-pointage').addEventListener('click', openPointageScanModal);
  document.getElementById('btn-pointeuse-historique-prev').addEventListener('click', () => shiftPointeuseHistoriqueMonth(-1));
  document.getElementById('btn-pointeuse-historique-next').addEventListener('click', () => shiftPointeuseHistoriqueMonth(1));
  document.getElementById('btn-pointeuse-historique-today').addEventListener('click', () => {
    const now = new Date();
    state.pointeuseHistoriqueYear = now.getFullYear();
    state.pointeuseHistoriqueMonth = now.getMonth();
    render();
  });
  // §retour Betty du 11/09/2026 ("pour le directeur et les manageurs un bouton qr code") : jusqu'ici
  // seul Paramètres > Établissements (RH/Propriétaire, voir renderEtablissementCard) permettait
  // d'afficher/régénérer ce QR — un manager n'a pas accès à Paramètres du tout. Réutilise la même
  // modale (openPointageQrModal) plutôt que d'en dupliquer une.
  document.querySelectorAll('[data-pointage-qr-etablissement]').forEach(btn => btn.addEventListener('click', () => openPointageQrModal(btn.dataset.pointageQrEtablissement)));
  document.querySelectorAll('[data-regulariser-pointage]').forEach(btn => btn.addEventListener('click', () => openRegulariserPointageModal(btn.dataset.regulariserPointage)));

  const validerBtn = document.getElementById('btn-valider-pointage-mensuel');
  if (validerBtn) validerBtn.addEventListener('click', () => {
    const now = new Date();
    const moisPrecedent = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    const user = authRepository.getCurrentUser();
    const result = DB.validerPointagesMensuels(user.id, moisPrecedent.getFullYear(), moisPrecedent.getMonth(), 'valide', '');
    if (!result.success) { showToast(result.error, 'error'); return; }
    showToast('Rapport validé.');
    render();
  });
  const contesterBtn = document.getElementById('btn-contester-pointage-mensuel');
  if (contesterBtn) contesterBtn.addEventListener('click', openContesterPointageMensuelModal);
}

function openContesterPointageMensuelModal() {
  const html = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>Contester le rapport mensuel</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="contester-pointage-form">
        <div class="modal-body">
          <div class="form-field">
            <label for="f-commentaire-contestation">Ce qui vous semble incorrect *</label>
            <textarea class="input" id="f-commentaire-contestation" rows="4" required></textarea>
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="submit" class="btn btn-primary">Envoyer</button>
        </div>
      </form>
    </div>
  `;
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');
  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('contester-pointage-form').addEventListener('submit', (evt) => {
    evt.preventDefault();
    const commentaire = document.getElementById('f-commentaire-contestation').value.trim();
    if (!commentaire) { showToast('Indiquez ce qui vous semble incorrect.', 'error'); return; }
    const now = new Date();
    const moisPrecedent = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    const user = authRepository.getCurrentUser();
    const result = DB.validerPointagesMensuels(user.id, moisPrecedent.getFullYear(), moisPrecedent.getMonth(), 'conteste', commentaire);
    if (!result.success) { showToast(result.error, 'error'); return; }
    showToast('Contestation envoyée.');
    closeModal();
    render();
  });
}

/** Lecture caméra en local (jsQR) — chaque frame vidéo est dessinée dans un <canvas> hors-écran
 * puis passée à jsQR, en boucle via requestAnimationFrame jusqu'à détection d'un QR reconnu (préfixe
 * "nexusrh-pointage:") ou fermeture de la modale. getUserMedia peut échouer (refus, HTTP non
 * sécurisé, pas de caméra) : message clair affiché dans la modale plutôt qu'un écran bloqué en
 * silence sans explication. */
function openPointageScanModal() {
  const user = authRepository.getCurrentUser();
  const html = `
    <div class="modal">
      <div class="modal-header">
        <h2>Scanner le QR de pointage</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <div class="modal-body">
        <div class="pointage-scan-stage" id="pointage-scan-stage">
          <video id="pointage-scan-video" autoplay playsinline muted></video>
        </div>
        <p class="text-muted" id="pointage-scan-status" style="text-align: center; margin-top: 10px;">Visez le QR affiché à l'accueil.</p>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
      </div>
    </div>
  `;
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');

  const video = document.getElementById('pointage-scan-video');
  const statusEl = document.getElementById('pointage-scan-status');
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d', { willReadFrequently: true });
  let stream = null;
  let rafId = null;
  let stopped = false;

  const stop = () => {
    stopped = true;
    if (rafId) cancelAnimationFrame(rafId);
    if (stream) stream.getTracks().forEach(t => t.stop());
  };
  const finishClose = () => { stop(); closeModal(); };
  document.getElementById('btn-close-modal').addEventListener('click', finishClose);
  document.getElementById('btn-cancel-modal').addEventListener('click', finishClose);

  const handleDecodedText = async (text) => {
    const match = /^nexusrh-pointage:([^:]+):(.+)$/.exec(text.trim());
    if (!match) return; // pas notre format (ex. un QR affiché par erreur) : on continue de scanner
    stop();
    statusEl.textContent = 'Vérification...';
    const [, etablissementId, token] = match;
    // §retour Betty du 13/09/2026 : enregistrer() vérifie désormais le jeton en ligne (voir son
    // commentaire, data.js) — devenu async pour ça, jamais instantané comme avant.
    const result = await pointageRepository.enregistrer(user.id, etablissementId, token);
    if (!result.success) {
      // §retour Betty du 13/09/2026 : un toast s'efface après ~3s, trop court pour lire/capturer un
      // message de diagnostic (voir enregistrerPointage, data.js) — remplacé temporairement par une
      // modale qui reste ouverte le temps nécessaire, jamais un simple toast fugace pour ce cas précis.
      // Transmis aussi à client_error_reports (reportClientError, voir 0047_client_error_reports.sql) :
      // Betty teste depuis son téléphone où copier/coller le message est peu pratique — elle peut
      // interroger cette table en SQL depuis son ordinateur au lieu de retaper le diagnostic.
      reportClientError(new Error(result.error), 'pointage-scan');
      modalRoot.innerHTML = `
        <div class="modal modal-small">
          <div class="modal-header"><h2>Pointage refusé</h2></div>
          <div class="modal-body"><p style="word-break: break-word;">${escapeHtml(result.error)}</p></div>
          <div class="modal-footer"><button type="button" class="btn btn-primary" id="btn-close-modal-footer">Fermer</button></div>
        </div>
      `;
      document.getElementById('btn-close-modal-footer').addEventListener('click', closeModal);
      return;
    }
    if (result.type === 'arrivee') {
      showToast(`Arrivée enregistrée à ${result.heure}.`);
    } else {
      showToast(`Départ enregistré à ${result.heure} (${formatNumberFR(round2(result.dureeMinutes / 60))} h travaillées aujourd'hui).`);
    }
    closeModal();
    render();
  };

  const tick = () => {
    if (stopped) return;
    if (video.readyState === video.HAVE_ENOUGH_DATA) {
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
      const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const code = jsQR(imageData.data, imageData.width, imageData.height);
      if (code && code.data) { handleDecodedText(code.data); return; }
    }
    rafId = requestAnimationFrame(tick);
  };

  navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } }).then(s => {
    if (stopped) { s.getTracks().forEach(t => t.stop()); return; }
    stream = s;
    video.srcObject = s;
    rafId = requestAnimationFrame(tick);
  }).catch(() => {
    statusEl.textContent = "Impossible d'accéder à la caméra (autorisation refusée, ou connexion non sécurisée).";
  });
}

// ---------------------------------------------------------------------------
// Export CSV — utilitaire générique réutilisé par Congés et Notes de frais
// ---------------------------------------------------------------------------

/** Neutralise l'injection de formule CSV (D15, audit fiabilité du 19/08/2026, recommandation OWASP)
 * : un libellé saisi par un salarié (ex. note de frais) commençant par =, +, -, @, tabulation ou
 * retour chariot s'exécuterait comme une formule chez le destinataire du fichier (comptable,
 * cabinet de paie) qui l'ouvre dans Excel/LibreOffice. Un guillemet simple en préfixe force
 * l'interprétation en texte — invisible à l'affichage, appliqué avant l'échappement CSV normal
 * (guillemets/délimiteur) par les deux fonctions d'export du projet.
 *
 * Le "-" demande une exception (revue de code du 23/08/2026) : préfixer sans discernement
 * transformait TOUT MONTANT NÉGATIF en texte dans l'export paie — or une retenue sur salaire
 * (ajusterVariablesPaie n'exige qu'un nombre fini, le négatif est un cas normal) ou un ajustement
 * négatif de tickets restaurant en produisent légitimement. Le gestionnaire de paie recevait alors
 * "'-150,50" : visuellement correct, mais ignoré par toute somme. Un nombre négatif bien formé —
 * chiffres, séparateurs de milliers et décimale française comprises — est donc laissé intact ; il
 * ne peut de toute façon pas être interprété comme une formule. */
function neutralizeCsvFormulaInjection(str) {
  if (!/^[=+\-@\t\r]/.test(str)) return str;
  // Les séparateurs de milliers sont écrits en \u… et JAMAIS en caractère littéral :
  // toLocaleString('fr-FR') ne produit pas une espace ordinaire mais, selon la version d'ICU, une
  // espace fine insécable (U+202F, cas actuel) ou une espace insécable (U+00A0). La première
  // version de ce correctif ne contenait qu'une espace ordinaire, indiscernable des autres à la
  // relecture : elle laissait bien passer "-150,50" mais transformait "-1 250,50" en texte, si
  // bien que le bug n'était corrigé qu'en dessous de 1 000 €. Tabulation et retour chariot restent
  // hors de cette classe : ils ne peuvent pas apparaître dans un nombre, et les exempter
  // affaiblirait la protection sans rien apporter.
  if (/^-\d[\d.,\u0020\u00a0\u2009\u202f]*$/.test(str)) return str;
  return "'" + str;
}



// §correctif audit du 31/08/2026 (reuse) : csvEscape/exportRowsToCSV étaient une quasi-copie de
// csvEscapeWithDelimiter/exportRowsToCSVWithDelimiter (~1400 lignes plus bas), avec une condition
// d'échappement réécrite indépendamment (/[;"\n]/.test(str) ici vs .includes() là-bas) — déjà
// fonctionnellement identique pour le délimiteur ';' mais deux implémentations qui pouvaient diverger
// silencieusement à la prochaine évolution de la règle d'échappement CSV. Route désormais vers
// l'unique implémentation paramétrée.
function csvEscape(value) {
  return csvEscapeWithDelimiter(value, ';');
}

function downloadTextFile(content, filename, mimeType) {
  const blob = new Blob(['﻿' + content], { type: mimeType });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

/** Comme downloadTextFile, mais SANS le BOM qu'elle pose (utile pour Excel/CSV, mais un JSON qui
 * commence par un BOM échoue au JSON.parse() strict de nombreux outils — un export de réversibilité
 * doit rester lisible par n'importe quel outil externe sans bidouille). */
function downloadJSONFile(data, filename) {
  const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

/** §retour Betty du 16/09/2026 : "fais des tableaux plus propre bien espacé" — un CSV brut ouvert
 * dans Excel garde les colonnes à leur largeur par défaut (texte tronqué/collé), sans distinguer
 * l'en-tête des données. Ces exports n'ayant vocation qu'à être lus/imprimés dans Excel (jamais
 * réimportés dans un logiciel tiers, à la différence de l'export paie — voir EXPORT_PAIE_MODELES,
 * exportRowsToCSVWithDelimiter, qui reste un vrai CSV délimité), on génère à la place un classeur au
 * format XML natif Excel (SpreadsheetML, .xls) : colonnes déjà larges, en-tête mis en évidence,
 * bordures légères — sans dépendance externe (juste du XML texte, aucune bibliothèque de zip/xlsx
 * nécessaire, à la différence du format .xlsx moderne). */
function excelXmlEscape(value) {
  return String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

/** §retour Betty du 18/09/2026 (point 7, exports Excel) : un vrai nombre JS (jamais un montant/une
 * durée déjà mis en texte par formatCurrencyFR/formatNumberFR AVANT d'arriver ici, voir les appelants
 * d'exportRowsToCSV) déclenche automatiquement l'alignement à droite ('cell-number'/'cell-zebra-
 * number', voir buildExcelXmlWorkbook/buildMultiSheetExcelXmlWorkbook) — jamais à coder au cas par
 * cas par l'appelant, qui ne fait que passer la valeur brute. */
function excelXmlCell(value, styleId = 'cell') {
  const isNumber = typeof value === 'number' && Number.isFinite(value);
  const text = neutralizeCsvFormulaInjection(value === null || value === undefined ? '' : String(value));
  const resolvedStyleId = isNumber && (styleId === 'cell' || styleId === 'cell-zebra') ? `${styleId}-number` : styleId;
  if (!text) return `<Cell ss:StyleID="${resolvedStyleId}"/>`;
  return `<Cell ss:StyleID="${resolvedStyleId}"><Data ss:Type="${isNumber ? 'Number' : 'String'}">${excelXmlEscape(text)}</Data></Cell>`;
}

function excelColumnWidths(headers, rows) {
  return headers.map((header, colIndex) => {
    let maxLen = String(header).length;
    rows.forEach(row => {
      const value = row[colIndex];
      const len = String(value === null || value === undefined ? '' : value).length;
      if (len > maxLen) maxLen = len;
    });
    return Math.min(320, Math.max(70, (maxLen + 2) * 7));
  });
}

/** §retour Betty du 16/09/2026 ("rajoute de la couleurs sur le exporter excel des salariés") :
 * `options.zebra` alterne un fond crème sur une ligne sur deux, pour un tableau plus lisible et plus
 * habillé — jamais une couleur différente par colonne/valeur, uniquement les couleurs de marque
 * (bleu marine + or, voir --landing-navy-700/--landing-gold-500, style.css), comme partout ailleurs
 * dans l'app (§règle de palette). Header et bordure dorée déjà appliqués à tous les exports Excel. */
function buildExcelXmlWorkbook(headers, rows, sheetName, options) {
  const zebra = Boolean(options && options.zebra);
  const columnsXml = excelColumnWidths(headers, rows).map(w => `<Column ss:Width="${w}"/>`).join('');
  const headerRowXml = `<Row ss:Height="20">${headers.map(h => `<Cell ss:StyleID="header"><Data ss:Type="String">${excelXmlEscape(neutralizeCsvFormulaInjection(String(h)))}</Data></Cell>`).join('')}</Row>`;
  const dataRowsXml = rows.map((row, rowIndex) => `<Row>${headers.map((_, i) => excelXmlCell(row[i], zebra && rowIndex % 2 === 1 ? 'cell-zebra' : 'cell')).join('')}</Row>`).join('');
  return `<?xml version="1.0" encoding="UTF-8"?>
<?mso-application progid="Excel.Sheet"?>
<Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet">
 <Styles>
  <Style ss:ID="header">
   <Font ss:Bold="1" ss:Color="#FFFFFF"/>
   <Interior ss:Color="#17284D" ss:Pattern="Solid"/>
   <Alignment ss:Vertical="Center"/>
   <Borders><Border ss:Position="Bottom" ss:LineStyle="Continuous" ss:Weight="2" ss:Color="#C99A54"/></Borders>
  </Style>
  <Style ss:ID="cell">
   <Alignment ss:Vertical="Center"/>
   <Borders><Border ss:Position="Bottom" ss:LineStyle="Continuous" ss:Weight="1" ss:Color="#DCE1E6"/></Borders>
  </Style>
  <Style ss:ID="cell-zebra">
   <Interior ss:Color="#F8EFE0" ss:Pattern="Solid"/>
   <Alignment ss:Vertical="Center"/>
   <Borders><Border ss:Position="Bottom" ss:LineStyle="Continuous" ss:Weight="1" ss:Color="#DCE1E6"/></Borders>
  </Style>
  <Style ss:ID="cell-number">
   <Alignment ss:Vertical="Center" ss:Horizontal="Right"/>
   <Borders><Border ss:Position="Bottom" ss:LineStyle="Continuous" ss:Weight="1" ss:Color="#DCE1E6"/></Borders>
  </Style>
  <Style ss:ID="cell-zebra-number">
   <Interior ss:Color="#F8EFE0" ss:Pattern="Solid"/>
   <Alignment ss:Vertical="Center" ss:Horizontal="Right"/>
   <Borders><Border ss:Position="Bottom" ss:LineStyle="Continuous" ss:Weight="1" ss:Color="#DCE1E6"/></Borders>
  </Style>
 </Styles>
 <Worksheet ss:Name="${excelXmlEscape(sheetName)}">
  <Table>${columnsXml}${headerRowXml}${dataRowsXml}</Table>
  <WorksheetOptions xmlns="urn:schemas-microsoft-com:office:excel">
   <FreezePanes/><FrozenNoSplit/><SplitHorizontal>1</SplitHorizontal><TopRowBottomPane>1</TopRowBottomPane><ActivePane>2</ActivePane>
  </WorksheetOptions>
 </Worksheet>
</Workbook>`;
}

/** Variante de buildExcelXmlWorkbook pour l'export du calendrier des absences (§retour Betty du
 * 16/09/2026 : "il faut que le calendrier ressemble plus a un calendrier avec des cases et plus
 * jolie") : bordures sur les 4 côtés de chaque cellule (de vraies "cases", pas juste un filet sous
 * chaque ligne) et colonnes week-end distinguées par un fond grisé, comme sur un vrai calendrier
 * mural. `weekendColumnIndexes` est l'ensemble des index de colonnes (0-based, dans `headers`)
 * correspondant à un samedi/dimanche. */
function buildCalendarExcelXmlWorkbook(headers, rows, sheetName, weekendColumnIndexes) {
  const columnsXml = excelColumnWidths(headers, rows).map(w => `<Column ss:Width="${w}"/>`).join('');
  const headerRowXml = `<Row ss:Height="20">${headers.map((h, i) => {
    const styleId = weekendColumnIndexes.has(i) ? 'header-weekend' : 'header';
    return `<Cell ss:StyleID="${styleId}"><Data ss:Type="String">${excelXmlEscape(neutralizeCsvFormulaInjection(String(h)))}</Data></Cell>`;
  }).join('')}</Row>`;
  const dataRowsXml = rows.map(row => `<Row>${headers.map((_, i) => excelXmlCell(row[i], weekendColumnIndexes.has(i) ? 'cell-weekend' : 'cell')).join('')}</Row>`).join('');
  return `<?xml version="1.0" encoding="UTF-8"?>
<?mso-application progid="Excel.Sheet"?>
<Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet">
 <Styles>
  <Style ss:ID="header">
   <Font ss:Bold="1" ss:Color="#FFFFFF"/>
   <Interior ss:Color="#1F3B57" ss:Pattern="Solid"/>
   <Alignment ss:Vertical="Center" ss:Horizontal="Center"/>
   <Borders>
    <Border ss:Position="Top" ss:LineStyle="Continuous" ss:Weight="1" ss:Color="#0F2438"/>
    <Border ss:Position="Bottom" ss:LineStyle="Continuous" ss:Weight="1" ss:Color="#0F2438"/>
    <Border ss:Position="Left" ss:LineStyle="Continuous" ss:Weight="1" ss:Color="#0F2438"/>
    <Border ss:Position="Right" ss:LineStyle="Continuous" ss:Weight="1" ss:Color="#0F2438"/>
   </Borders>
  </Style>
  <Style ss:ID="header-weekend">
   <Font ss:Bold="1" ss:Color="#FFFFFF"/>
   <Interior ss:Color="#8A5A2B" ss:Pattern="Solid"/>
   <Alignment ss:Vertical="Center" ss:Horizontal="Center"/>
   <Borders>
    <Border ss:Position="Top" ss:LineStyle="Continuous" ss:Weight="1" ss:Color="#0F2438"/>
    <Border ss:Position="Bottom" ss:LineStyle="Continuous" ss:Weight="1" ss:Color="#0F2438"/>
    <Border ss:Position="Left" ss:LineStyle="Continuous" ss:Weight="1" ss:Color="#0F2438"/>
    <Border ss:Position="Right" ss:LineStyle="Continuous" ss:Weight="1" ss:Color="#0F2438"/>
   </Borders>
  </Style>
  <Style ss:ID="cell">
   <Alignment ss:Vertical="Center" ss:Horizontal="Center" ss:WrapText="1"/>
   <Borders>
    <Border ss:Position="Top" ss:LineStyle="Continuous" ss:Weight="1" ss:Color="#DCE1E6"/>
    <Border ss:Position="Bottom" ss:LineStyle="Continuous" ss:Weight="1" ss:Color="#DCE1E6"/>
    <Border ss:Position="Left" ss:LineStyle="Continuous" ss:Weight="1" ss:Color="#DCE1E6"/>
    <Border ss:Position="Right" ss:LineStyle="Continuous" ss:Weight="1" ss:Color="#DCE1E6"/>
   </Borders>
  </Style>
  <Style ss:ID="cell-weekend">
   <Interior ss:Color="#F0F1F3" ss:Pattern="Solid"/>
   <Alignment ss:Vertical="Center" ss:Horizontal="Center" ss:WrapText="1"/>
   <Borders>
    <Border ss:Position="Top" ss:LineStyle="Continuous" ss:Weight="1" ss:Color="#DCE1E6"/>
    <Border ss:Position="Bottom" ss:LineStyle="Continuous" ss:Weight="1" ss:Color="#DCE1E6"/>
    <Border ss:Position="Left" ss:LineStyle="Continuous" ss:Weight="1" ss:Color="#DCE1E6"/>
    <Border ss:Position="Right" ss:LineStyle="Continuous" ss:Weight="1" ss:Color="#DCE1E6"/>
   </Borders>
  </Style>
 </Styles>
 <Worksheet ss:Name="${excelXmlEscape(sheetName)}">
  <Table>${columnsXml}${headerRowXml}${dataRowsXml}</Table>
  <WorksheetOptions xmlns="urn:schemas-microsoft-com:office:excel">
   <FreezePanes/><FrozenNoSplit/><SplitHorizontal>1</SplitHorizontal><TopRowBottomPane>1</TopRowBottomPane><ActivePane>2</ActivePane>
  </WorksheetOptions>
 </Worksheet>
</Workbook>`;
}

/** §retour Betty du 18/09/2026 (import historique, points 2-3) : modèle téléchargeable à plusieurs
 * onglets — le premier à remplir, les suivants purement des listes de référence (salariés avec
 * matricule, types de congés existants) recopiées depuis l'entreprise au moment du téléchargement,
 * pour que tout ce dont on a besoin soit dans le fichier, sans aller-retour avec l'application.
 * Même Styles que buildExcelXmlWorkbook (un seul bloc, partagé par tous les onglets — SpreadsheetML
 * ne le redéfinit qu'une fois par classeur). `sheets` : [{ name, headers, rows }, ...].
 *
 * Pas de menu déroulant Excel réel ici (contrairement à ce qui était demandé) : la validation de
 * liste en SpreadsheetML (le format XML utilisé, pas le .xlsx moderne) n'est pas documentée de façon
 * fiable, et je préfère un fichier sûrement valide à un menu déroulant hasardeux qui risquerait de
 * corrompre l'ouverture. À la place, la ligne d'exemple du premier onglet montre déjà les deux seules
 * valeurs valides ("Après-midi"/"Matin") telles qu'à écrire, et l'import reste insensible aux accents/
 * majuscules — voir buildAbsencesPreviewRows. */
function buildMultiSheetExcelXmlWorkbook(sheets) {
  const worksheetsXml = sheets.map(sheet => {
    const columnsXml = excelColumnWidths(sheet.headers, sheet.rows).map(w => `<Column ss:Width="${w}"/>`).join('');
    const headerRowXml = `<Row ss:Height="20">${sheet.headers.map(h => `<Cell ss:StyleID="header"><Data ss:Type="String">${excelXmlEscape(neutralizeCsvFormulaInjection(String(h)))}</Data></Cell>`).join('')}</Row>`;
    const dataRowsXml = sheet.rows.map(row => `<Row>${sheet.headers.map((_, i) => excelXmlCell(row[i])).join('')}</Row>`).join('');
    return `<Worksheet ss:Name="${excelXmlEscape(sheet.name)}">
  <Table>${columnsXml}${headerRowXml}${dataRowsXml}</Table>
  <WorksheetOptions xmlns="urn:schemas-microsoft-com:office:excel">
   <FreezePanes/><FrozenNoSplit/><SplitHorizontal>1</SplitHorizontal><TopRowBottomPane>1</TopRowBottomPane><ActivePane>2</ActivePane>
  </WorksheetOptions>
 </Worksheet>`;
  }).join('\n ');
  return `<?xml version="1.0" encoding="UTF-8"?>
<?mso-application progid="Excel.Sheet"?>
<Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet">
 <Styles>
  <Style ss:ID="header">
   <Font ss:Bold="1" ss:Color="#FFFFFF"/>
   <Interior ss:Color="#17284D" ss:Pattern="Solid"/>
   <Alignment ss:Vertical="Center"/>
   <Borders><Border ss:Position="Bottom" ss:LineStyle="Continuous" ss:Weight="2" ss:Color="#C99A54"/></Borders>
  </Style>
  <Style ss:ID="cell">
   <Alignment ss:Vertical="Center"/>
   <Borders><Border ss:Position="Bottom" ss:LineStyle="Continuous" ss:Weight="1" ss:Color="#DCE1E6"/></Borders>
  </Style>
  <Style ss:ID="cell-number">
   <Alignment ss:Vertical="Center" ss:Horizontal="Right"/>
   <Borders><Border ss:Position="Bottom" ss:LineStyle="Continuous" ss:Weight="1" ss:Color="#DCE1E6"/></Borders>
  </Style>
 </Styles>
 ${worksheetsXml}
</Workbook>`;
}

/** Comme downloadJSONFile : sans le BOM de downloadTextFile, inutile ici (l'encodage est déclaré
 * dans la déclaration XML elle-même) et risqué avant une déclaration <?xml ...?> qui doit rester en
 * tout premier caractère du fichier. */
function downloadExcelXmlFile(xml, filename) {
  const blob = new Blob([xml], { type: 'application/vnd.ms-excel;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

function exportRowsToCSV(headers, rows, filename) {
  const xlsFilename = filename.replace(/\.csv$/i, '.xls');
  const sheetName = xlsFilename.replace(/\.xls$/i, '').replace(/[:\\/?*[\]]/g, ' ').slice(0, 31) || 'Feuille1';
  downloadExcelXmlFile(buildExcelXmlWorkbook(headers, rows, sheetName), xlsFilename);
}

// ---------------------------------------------------------------------------
// Vue : Notes de frais
// ---------------------------------------------------------------------------

/** Doit rester en phase avec HYDRATION_WINDOW_MONTHS (supabase-client.js) — dupliqué ici plutôt que
 * lu via window.SupabaseSync (asynchrone dans le vrai client, et les tests existants simulent
 * SupabaseSync par un Proxy générique qui renvoie des fonctions async pour tout : un appel
 * synchrone depuis une fonction de RENDU comme renderFrais() casserait cette convention partagée
 * par toute la suite de tests). Purement indicatif (un message d'aide), jamais utilisé pour une
 * vraie requête — une dérive de quelques jours entre les deux copies serait sans conséquence. */
const HYDRATION_WINDOW_MONTHS = 40;
function hydrationWindowCutoffDateISO() {
  const now = new Date();
  return new Date(now.getFullYear(), now.getMonth() - HYDRATION_WINDOW_MONTHS, now.getDate()).toISOString().slice(0, 10);
}

function getFilteredExpenses() {
  const filtered = applyStateFilters(scopeToVisibleEmployees(expenseRepository.getAll()), state.fraisFilters,
    [['employeeId', 'employeeId'], ['categorie', 'categorie'], ['statut', 'statut']]);
  // §retour Betty du 19/09/2026 (socle commun, point 6) : matchesPeriodeFilter (une seule
  // implémentation, désormais partagée avec Congés/Entretiens) plutôt qu'un startsWith réécrit ici.
  return filtered.filter(n => matchesPeriodeFilter(n.date, state.fraisFilters.periode));
}

function renderFrais() {
  const employees = getScopedEmployeesForFilters();
  const settings = settingsRepository.getSettings();
  const expenses = getFilteredExpenses();
  // §retour Betty du 07/09/2026 (point 6) : additionner aussi les notes Refusé/Annulé rendait ce
  // total inexploitable ("12 notes, 2 340 € TTC" ne voulait rien dire dès qu'un refus était mélangé
  // dedans) — seul ce qui reste réellement dû (en attente ou déjà remboursé) doit compter ici.
  const total = expenses.filter(n => n.statut !== 'Refusé' && n.statut !== 'Annulé').reduce((sum, n) => sum + n.montantTTC, 0);
  // §retour Betty du 07/09/2026 (point 13) : voir séparément ce qui est en attente/remboursé/refusé,
  // plutôt qu'un total unique qui mélange tout (voir aussi le correctif du point 6 juste au-dessus).
  const STATUT_BADGE_CLASS = { 'En attente': 'warning', 'Remboursé': 'success', 'Refusé': 'muted', 'Annulé': 'muted' };
  const totauxParStatut = ['En attente', 'Remboursé', 'Refusé', 'Annulé']
    .map(statut => ({ statut, notes: expenses.filter(n => n.statut === statut) }))
    .filter(t => t.notes.length > 0)
    .map(t => ({ ...t, montant: t.notes.reduce((sum, n) => sum + n.montantTTC, 0) }));
  const { pageItems, totalPages, page, pageStart } = paginate(expenses, 'fraisPage');
  const user = authRepository.getCurrentUser();
  // §retour Betty du 07/09/2026 (point 8) : liste de rôles codée en dur remplacée par les mêmes
  // permissions que canActOnRequestFor/canRefuserRequestFor (VALIDER_NOTE_FRAIS pour RH/Propriétaire,
  // CONTROLER_NOTE_FRAIS pour Manager/Comptabilité) — une permission accordée individuellement à un
  // salarié qui n'a normalement pas ce droit lui affiche désormais bien le bouton, comme partout
  // ailleurs dans l'application.
  const canValider = hasPermission(user, PERMISSIONS.VALIDER_NOTE_FRAIS) || hasPermission(user, PERMISSIONS.CONTROLER_NOTE_FRAIS);
  // §amélioration du 09/09/2026 : même distinction que Congés/Télétravail (voir renderCongesDemandes)
  // — "aucune note ne correspond à ces filtres" prêtait à confusion quand il n'y a simplement AUCUNE
  // note créée pour l'instant.
  //
  // §retour Betty du 11/09/2026 (point 1, étape 2) : le filtre "période" ci-dessous (input type=
  // month, valeur libre) peut désormais pointer vers un mois antérieur à la fenêtre glissante
  // rapatriée à la connexion (~40 mois, voir HYDRATION_WINDOW_MONTHS, supabase-client.js) — sans ce
  // message dédié, "0 note" pour une vieille période ressemblerait à un bug plutôt qu'à une limite
  // connue (les notes existent peut-être bien côté serveur, juste hors du cache local).
  const periodeAvantFenetre = Boolean(state.fraisFilters.periode && `${state.fraisFilters.periode}-01` < hydrationWindowCutoffDateISO());
  const emptyStateMessage = periodeAvantFenetre
    ? 'Aucune note dans le cache local pour cette période (plus de 40 mois) : contactez BERTOLIS si vous avez besoin de cet historique.'
    : Object.values(state.fraisFilters).some(Boolean)
      ? 'Aucune note de frais ne correspond à ces filtres.'
      : 'Aucune note de frais pour l\'instant. Utilisez le bouton "+ Nouvelle note" ci-dessus pour créer la première.';

  return `
    <div class="view-header view-header-row">
      <div>
        <h1>Notes de frais</h1>
        <p class="view-subtitle">
          ${expenses.length} note${expenses.length > 1 ? 's' : ''} · ${formatCurrencyFR(total)} TTC dû (en attente + remboursé)
          ${totauxParStatut.map(t => ` · <span class="badge badge-${STATUT_BADGE_CLASS[t.statut]}">${escapeHtml(t.statut)} : ${t.notes.length} (${formatCurrencyFR(t.montant)})</span>`).join('')}
        </p>
      </div>
      <div class="detail-header-actions">
        ${canValider ? `<button type="button" class="btn btn-secondary" id="btn-frais-a-valider">Voir les notes à valider</button>` : ''}
        ${canExportCongesFraisMoisLeger(user) ? `<button type="button" class="btn btn-secondary" id="btn-export-conges-frais-leger" title="Congés payés, RTT et notes de frais remboursées du mois en cours, sans le module RH">Exporter congés + frais du mois</button>` : ''}
        <button class="btn btn-secondary" id="btn-export-frais">Exporter CSV</button>
        ${bulkSelection.frais.size >= 2 ? `<button type="button" class="btn btn-secondary" id="btn-regrouper-dossier-frais">Regrouper en dossier (${bulkSelection.frais.size})</button>` : ''}
        <button class="btn btn-primary" id="btn-new-expense">+ Nouvelle note</button>
      </div>
    </div>

    ${renderDraftsCard('frais')}
    ${renderExpenseDossiersCard()}
    ${canValider ? renderRapprochementBancaireCard() : ''}

    <div class="toolbar card">
      <select id="frais-filter-employee" class="input">
        <option value="">Tous les salariés</option>
        ${employees.map(e => `<option value="${e.id}" ${state.fraisFilters.employeeId === e.id ? 'selected' : ''}>${personNameHtml(e)}</option>`).join('')}
      </select>
      <select id="frais-filter-categorie" class="input">
        <option value="">Toutes les catégories</option>
        ${settings.categoriesFrais.map(c => `<option value="${escapeHtml(c)}" ${state.fraisFilters.categorie === c ? 'selected' : ''}>${escapeHtml(c)}</option>`).join('')}
      </select>
      <select id="frais-filter-statut" class="input">
        <option value="">Tous les statuts</option>
        ${['En attente', 'Remboursé', 'Refusé', 'Annulé'].map(s => `<option value="${s}" ${state.fraisFilters.statut === s ? 'selected' : ''}>${s}</option>`).join('')}
      </select>
      <input class="input" type="month" id="frais-filter-periode" value="${escapeHtml(state.fraisFilters.periode)}" title="Filtrer par mois de la dépense">
    </div>

    <div class="card table-card">
      ${expenses.length === 0 ? `<div class="empty-state"><div class="empty-icon">${ICONS.receipt}</div><p>${escapeHtml(emptyStateMessage)}</p></div>` : `
        <table class="table mobile-cards">
          <thead>
            <tr><th></th><th>Salarié</th><th>Date</th><th>Catégorie</th><th>Libellé</th><th class="cell-numeric">Montant TTC</th><th>Statut</th><th></th></tr>
          </thead>
          <tbody>${pageItems.map(renderExpenseRow).join('')}</tbody>
        </table>
        ${renderPaginationControls(page, totalPages, pageStart, pageItems.length, expenses.length)}
      `}
    </div>
  `;
}

/** §retour Betty du 07/09/2026 (point 5) : un salarié ne pouvait ni corriger ni annuler sa propre
 * note — il fallait attendre qu'un valideur la refuse, puis tout ressaisir, pour une simple erreur
 * de montant. Restreint à AVANT toute validation (etapeIndex === 0, personne n'a encore agi dessus)
 * pour ne jamais laisser un salarié modifier une note après qu'un valideur se soit déjà prononcé
 * dessus — cette limite protège la validation déjà donnée, pas seulement l'auteur de la note. */
function canSelfManagePendingExpense(expense, user) {
  return Boolean(user) && expense.employeeId === user.id && expense.statut === 'En attente' && expense.etapeIndex === 0;
}

function renderExpenseRow(n) {
  const employee = employeeRepository.getById(n.employeeId);
  if (!employee) return '';
  const user = authRepository.getCurrentUser();
  const canSelfManage = canSelfManagePendingExpense(n, user);

  const actions = n.statut === 'En attente'
    ? `${canSelfManage ? `<button class="btn-link" data-edit-nf="${n.id}">Modifier</button><button class="btn-link btn-link-danger" data-self-cancel-nf="${n.id}">Annuler</button>` : ''}${canActOnRequestFor(n, 'frais') ? `<button class="btn-link" data-approve-nf="${n.id}">Valider</button>` : ''}${canRefuserRequestFor(n, 'frais') ? `<button class="btn-link btn-link-danger" data-refuse-nf="${n.id}">Refuser</button>` : ''}`
    // §retour Betty du 07/09/2026 (point 7) : "Marquer comme payé" tant que le paiement réel n'a pas
    // été confirmé — réservé à MARQUER_NOTE_REMBOURSEE, distinct de VALIDER_NOTE_FRAIS (qui a déjà
    // fait son travail en amenant la note ici).
    : n.statut === 'Remboursé' ? `
        ${!n.datePaiement && hasPermission(user, PERMISSIONS.MARQUER_NOTE_REMBOURSEE) ? `<button class="btn-link" data-mark-paid-nf="${n.id}">Marquer comme payé</button>` : ''}
        ${canManageRequestFor(n.employeeId, 'frais') ? `<button class="btn-link btn-link-danger" data-cancel-nf="${n.id}">Annuler</button>` : ''}
      ` : '';

  // §retour Betty du 14/09/2026 (Notes de frais point 5, "note de frais groupée") : la case de
  // sélection n'apparaît que pour une note qu'on peut encore regrouper (en attente, pas déjà dans un
  // dossier, et modifiable par la personne qui regarde — même portée que "Modifier"/"Annuler").
  const dossier = n.dossierId ? expenseDossierRepository.getById(n.dossierId) : null;
  const peutSelectionner = n.statut === 'En attente' && !n.dossierId && canSelfManage;
  const selection = bulkSelection.frais;

  return `
    <tr>
      <td>${peutSelectionner ? `<input type="checkbox" data-select-frais="${n.id}" data-select-frais-employee="${n.employeeId}" ${selection.has(n.id) ? 'checked' : ''}>` : ''}</td>
      <td class="row-title" data-label="Salarié">${personNameHtml(employee)}</td>
      <td data-label="Date">${formatDate(n.date)}</td>
      <td data-label="Catégorie">${escapeHtml(n.categorie)}</td>
      <td data-label="Libellé">${escapeHtml(n.libelle)}${dossier ? ` <span class="badge badge-info" title="Fait partie du dossier">${icon(ICONS.folder, 10)} ${escapeHtml(dossier.motif)}</span>` : ''}</td>
      <td class="cell-numeric" data-label="Montant TTC">${formatCurrencyFR(n.montantTTC)}</td>
      <td data-label="Statut">${renderRequestStatutBadge(n)}${n.statut === 'Remboursé' ? (n.datePaiement ? ` <span class="text-muted" style="font-size:12px;">payé le ${formatDate(n.datePaiement)}</span>` : ` <span class="badge badge-muted">à payer</span>`) : ''}${releveBancaireRepository.getAll().some(l => l.expenseId === n.id) ? ` <span class="badge badge-success" title="Un mouvement du relevé bancaire importé correspond à cette note">${icon(ICONS.checkCircle, 10)} Rapproché</span>` : ''}</td>
      <td class="table-actions">
        <button class="btn-link" data-view-nf="${n.id}">Détail</button>
        <button class="btn-link" data-history="${n.id}">Historique</button>
        ${actions}
      </td>
    </tr>
  `;
}

/** §retour Betty du 14/09/2026 (Notes de frais point 5) : un dossier avec AU MOINS UNE note déjà
 * traitée (validée/refusée/annulée) ne propose plus d'action groupée — jamais une double
 * validation, jamais une action qui écraserait un statut déjà décidé individuellement. */
function renderExpenseDossiersCard() {
  const dossiers = expenseDossierRepository.getAll();
  if (!dossiers.length) return '';
  const user = authRepository.getCurrentUser();
  const rows = dossiers.map(d => {
    const notes = expenseRepository.getAll().filter(n => n.dossierId === d.id);
    if (!notes.length) return '';
    const toutesEnAttente = notes.every(n => n.statut === 'En attente');
    const peutValiderTout = toutesEnAttente && notes.every(n => canActOnRequestFor(n, 'frais'));
    const peutRefuserTout = toutesEnAttente && notes.every(n => canRefuserRequestFor(n, 'frais'));
    const total = notes.reduce((sum, n) => sum + n.montantTTC, 0);
    return `
      <div class="mini-list-item">
        <span>${icon(ICONS.folder, 12)} ${escapeHtml(d.motif)} · ${notes.length} note${notes.length > 1 ? 's' : ''} · ${formatCurrencyFR(total)}${!toutesEnAttente ? ' <span class="text-muted">(déjà traité en partie)</span>' : ''}</span>
        <span class="detail-header-actions">
          ${peutValiderTout ? `<button type="button" class="btn-link" data-valider-dossier="${d.id}">Valider tout le dossier</button>` : ''}
          ${peutRefuserTout ? `<button type="button" class="btn-link btn-link-danger" data-refuser-dossier="${d.id}">Refuser tout le dossier</button>` : ''}
        </span>
      </div>
    `;
  }).filter(Boolean).join('');
  if (!rows) return '';
  return `<div class="card" style="margin-top: 0; margin-bottom: 16px;"><h2>Dossiers de frais</h2>${rows}</div>`;
}

/** §retour Betty du 14/09/2026 (Notes de frais point 2, "rapprochement bancaire") — import manuel
 * d'un relevé plutôt qu'un flux automatique payant (Bridge/Budget Insight), voir
 * DB.importerReleveBancaire (data.js) pour le détail du choix. Toujours affichée (même sans relevé
 * importé) pour que l'action "Importer" reste trouvable, contrairement à renderExpenseDossiersCard
 * qui se masque tant qu'il n'y a rien à montrer. */
function renderRapprochementBancaireCard() {
  const releves = releveBancaireRepository.getAll();
  const expenseIdsDejaRapproches = new Set(releves.filter(l => l.expenseId).map(l => l.expenseId));
  const candidatsCommuns = expenseRepository.getAll().filter(n => !expenseIdsDejaRapproches.has(n.id) && (n.statut === 'Remboursé' || n.statut === 'En attente'));
  const lignesTriees = releves.slice().sort((a, b) => (a.statut === 'rapproche') - (b.statut === 'rapproche'));

  return `
    <div class="card" style="margin-top: 0; margin-bottom: 16px;">
      <div class="view-header-row">
        <div>
          <h2>Rapprochement bancaire</h2>
          <p class="text-muted" style="margin: 4px 0 0;">Importez un relevé bancaire (fichier .csv : date, libellé, montant) pour vérifier que chaque remboursement a bien été payé. Sans compte externe (à la différence d'un flux bancaire automatique type Bridge) : à réimporter manuellement chaque mois.</p>
        </div>
        <div class="detail-header-actions">
          <label class="btn btn-secondary btn-sm" style="cursor: pointer; margin: 0;">Importer un relevé (.csv)<input type="file" id="releve-bancaire-file" accept=".csv,text/csv" style="display: none;"></label>
          ${releves.some(l => l.statut !== 'rapproche') ? `<button type="button" class="btn btn-secondary btn-sm" id="btn-rapprocher-auto">Rapprocher automatiquement</button>` : ''}
        </div>
      </div>
      ${!releves.length ? '<p class="text-muted" style="margin: 12px 0 0;">Aucun relevé importé pour l\'instant.</p>' : `
        <div class="mini-list" style="margin-top: 12px;">
          ${lignesTriees.map(l => {
            const expense = l.expenseId ? expenseRepository.getById(l.expenseId) : null;
            const employee = expense ? employeeRepository.getById(expense.employeeId) : null;
            return `
              <div class="mini-list-item" style="align-items: flex-start;">
                <span>
                  ${formatDate(l.date)} · ${escapeHtml(l.libelle || '—')} · ${formatCurrencyFR(l.montant)}
                  ${l.statut === 'rapproche' ? `<br><span class="text-muted">↳ ${expense ? `${escapeHtml(expense.libelle)}${employee ? ' · ' + escapeHtml(employee.prenom + ' ' + employee.nom) : ''}` : 'note introuvable (supprimée depuis)'}</span>` : ''}
                </span>
                <span style="display: flex; align-items: center; gap: 8px;">
                  ${l.statut === 'rapproche'
                    ? `<button type="button" class="btn-link" data-annuler-rapprochement="${l.id}">Annuler</button>`
                    : `<select class="input" style="width: auto;" data-rapprocher-select="${l.id}">
                        <option value="">Associer à une note...</option>
                        ${candidatsCommuns.map(n => `<option value="${n.id}">${escapeHtml(n.libelle)} · ${formatCurrencyFR(n.montantTTC)}${employeeRepository.getById(n.employeeId) ? ' · ' + escapeHtml(employeeRepository.getById(n.employeeId).prenom) : ''}</option>`).join('')}
                      </select>
                      <button type="button" class="btn-link btn-link-danger" data-supprimer-ligne-releve="${l.id}" title="Retirer cette ligne">Retirer</button>`}
                </span>
              </div>
            `;
          }).join('')}
        </div>
      `}
    </div>
  `;
}

function bindRapprochementBancaireEvents() {
  const fileInput = document.getElementById('releve-bancaire-file');
  if (fileInput) fileInput.addEventListener('change', (evt) => {
    const file = evt.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      const result = releveBancaireRepository.importer(String(reader.result || ''));
      if (!result.success) { showToast('Impossible de lire ce fichier.', 'error'); return; }
      showToast(`${result.ajoutees} ligne(s) importée(s)${result.ignorees ? `, ${result.ignorees} ignorée(s) (format non reconnu)` : ''}.`);
      render();
    };
    reader.onerror = () => showToast('Impossible de lire ce fichier.', 'error');
    reader.readAsText(file);
  });

  const autoBtn = document.getElementById('btn-rapprocher-auto');
  if (autoBtn) autoBtn.addEventListener('click', () => {
    const result = releveBancaireRepository.rapprocherAuto();
    showToast(result.rapprochees > 0 ? `${result.rapprochees} ligne(s) rapprochée(s) automatiquement.` : 'Aucune correspondance évidente trouvée : associez manuellement les lignes restantes.');
    render();
  });

  document.querySelectorAll('[data-rapprocher-select]').forEach(select => {
    select.addEventListener('change', () => {
      if (!select.value) return;
      const result = releveBancaireRepository.rapprocherManuel(select.dataset.rapprocherSelect, select.value);
      if (!result.success) { showToast(result.error, 'error'); return; }
      showToast('Ligne rapprochée.');
      render();
    });
  });

  document.querySelectorAll('[data-annuler-rapprochement]').forEach(btn => {
    btn.addEventListener('click', () => {
      releveBancaireRepository.annuler(btn.dataset.annulerRapprochement);
      showToast('Rapprochement annulé.');
      render();
    });
  });

  document.querySelectorAll('[data-supprimer-ligne-releve]').forEach(btn => {
    btn.addEventListener('click', () => {
      releveBancaireRepository.supprimer(btn.dataset.supprimerLigneReleve);
      showToast('Ligne retirée.');
      render();
    });
  });
}

function openRegrouperDossierModal() {
  const employeeId = [...bulkSelection.frais].map(id => expenseRepository.getById(id)).find(Boolean).employeeId;
  const html = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>Regrouper en dossier</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="dossier-frais-form">
        <div class="modal-body">
          <p class="text-muted">${bulkSelection.frais.size} notes sélectionnées seront regroupées et validées en une fois.</p>
          <div class="form-field">
            <label for="f-motif-dossier">Motif du dossier *</label>
            <input class="input" type="text" id="f-motif-dossier" placeholder="Ex. Déplacement client Lyon 12-14 sept." required>
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="submit" class="btn btn-primary">Regrouper</button>
        </div>
      </form>
    </div>
  `;
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');
  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('dossier-frais-form').addEventListener('submit', (evt) => {
    evt.preventDefault();
    const motif = document.getElementById('f-motif-dossier').value.trim();
    if (!motif) { showToast('Indiquez un motif.', 'error'); return; }
    const result = expenseDossierRepository.creer(employeeId, motif, [...bulkSelection.frais]);
    if (!result.success) { showToast(result.error, 'error'); return; }
    bulkSelection.frais.clear();
    showToast('Dossier créé.');
    closeModal();
    render();
  });
}

function bindFraisEvents() {
  document.getElementById('btn-new-expense').addEventListener('click', () => openExpenseModal());
  document.getElementById('btn-export-frais').addEventListener('click', exportExpensesCSV);
  bindRapprochementBancaireEvents();

  document.querySelectorAll('[data-select-frais]').forEach(cb => cb.addEventListener('change', (e) => {
    const id = cb.dataset.selectFrais;
    const employeeId = cb.dataset.selectFraisEmployee;
    // §retour Betty du 14/09/2026 : un dossier ne peut regrouper que les notes d'UN SEUL salarié
    // (voir DB.creerDossierFrais) — cocher une note d'un autre salarié viderait la sélection en
    // cours plutôt que de créer une sélection mixte qui échouerait silencieusement à la validation.
    if (bulkSelection.frais.size > 0) {
      const premiereId = [...bulkSelection.frais][0];
      const premiereNote = expenseRepository.getById(premiereId);
      if (premiereNote && premiereNote.employeeId !== employeeId) {
        showToast('Un dossier ne peut regrouper que les notes d\'un même salarié : sélection réinitialisée.', 'error');
        bulkSelection.frais.clear();
      }
    }
    if (e.target.checked) bulkSelection.frais.add(id); else bulkSelection.frais.delete(id);
    render();
  }));
  const regrouperBtn = document.getElementById('btn-regrouper-dossier-frais');
  if (regrouperBtn) regrouperBtn.addEventListener('click', openRegrouperDossierModal);
  document.querySelectorAll('[data-valider-dossier]').forEach(btn => btn.addEventListener('click', () => {
    const notes = expenseRepository.getAll().filter(n => n.dossierId === btn.dataset.validerDossier && n.statut === 'En attente');
    notes.forEach(n => handleApproveExpense(n.id));
  }));
  document.querySelectorAll('[data-refuser-dossier]').forEach(btn => btn.addEventListener('click', () => {
    const notes = expenseRepository.getAll().filter(n => n.dossierId === btn.dataset.refuserDossier && n.statut === 'En attente');
    openRefuseModal({
      title: 'Refuser tout le dossier ?',
      message: `${notes.length} note(s) seront refusées, le salarié sera informé.`,
      onConfirm: (motif) => {
        notes.forEach(n => {
          expenseRepository.update(n.id, refuseRequest(n, motif));
          // §correctif audit du 16/09/2026 : ce chemin groupé contournait handleRefuseExpense (le
          // seul qui recalculait jusqu'ici), oubliant le recalcul du barème kilométrique sur les
          // notes du dossier — même correctif que handleRefuseExpense/handleCancelExpense
          // ("vrai défaut de paiement", 07-11/09/2026).
          if (n.categorie === 'Kilométrique') expenseRepository.recalculerIndemnitesKilometriques(n.employeeId, (n.date || '').slice(0, 4));
        });
        auditLogRepository.logAudit('Refus', 'Dossier de frais', `${notes.length} notes`, auditDetailsForActor());
        showToast('Dossier refusé.');
        render();
      }
    });
  }));
  const btnExportLeger = document.getElementById('btn-export-conges-frais-leger');
  if (btnExportLeger) btnExportLeger.addEventListener('click', exportCongesFraisMoisCSV);
  bindDraftsCardEvents((draft) => openExpenseModal(undefined, draft));

  const btnAValider = document.getElementById('btn-frais-a-valider');
  if (btnAValider) {
    btnAValider.addEventListener('click', () => {
      Object.assign(state, NAVPARAMS_FRAIS_A_VALIDER);
      state.fraisPage = 1;
      render();
    });
  }

  document.getElementById('frais-filter-employee').addEventListener('change', (e) => {
    state.fraisFilters.employeeId = e.target.value;
    state.fraisPage = 1;
    render();
  });
  document.getElementById('frais-filter-categorie').addEventListener('change', (e) => {
    state.fraisFilters.categorie = e.target.value;
    state.fraisPage = 1;
    render();
  });
  document.getElementById('frais-filter-statut').addEventListener('change', (e) => {
    state.fraisFilters.statut = e.target.value;
    state.fraisPage = 1;
    render();
  });
  document.getElementById('frais-filter-periode').addEventListener('change', (e) => {
    state.fraisFilters.periode = e.target.value;
    state.fraisPage = 1;
    render();
  });

  const fraisPrevBtn = document.getElementById('btn-page-prev');
  if (fraisPrevBtn) fraisPrevBtn.addEventListener('click', () => { state.fraisPage -= 1; render(); });
  const fraisNextBtn = document.getElementById('btn-page-next');
  if (fraisNextBtn) fraisNextBtn.addEventListener('click', () => { state.fraisPage += 1; render(); });

  document.querySelectorAll('[data-view-nf]').forEach(btn => btn.addEventListener('click', () => openExpenseDetailModal(btn.dataset.viewNf)));
  document.querySelectorAll('[data-approve-nf]').forEach(btn => btn.addEventListener('click', () => handleApproveExpense(btn.dataset.approveNf)));
  document.querySelectorAll('[data-refuse-nf]').forEach(btn => btn.addEventListener('click', () => handleRefuseExpense(btn.dataset.refuseNf)));
  document.querySelectorAll('[data-cancel-nf]').forEach(btn => btn.addEventListener('click', () => handleCancelExpense(btn.dataset.cancelNf)));
  document.querySelectorAll('[data-edit-nf]').forEach(btn => btn.addEventListener('click', () => handleEditExpense(btn.dataset.editNf)));
  document.querySelectorAll('[data-self-cancel-nf]').forEach(btn => btn.addEventListener('click', () => handleSelfCancelExpense(btn.dataset.selfCancelNf)));
  document.querySelectorAll('[data-mark-paid-nf]').forEach(btn => btn.addEventListener('click', () => handleMarkExpensePaid(btn.dataset.markPaidNf)));
  bindHistoryButtons(expenseRepository);
}

function handleEditExpense(id) {
  const expense = expenseRepository.getById(id);
  const user = authRepository.getCurrentUser();
  if (!expense || !canSelfManagePendingExpense(expense, user)) { showToast('Action non autorisée.', 'error'); return; }
  openExpenseModal(undefined, undefined, expense);
}

function handleSelfCancelExpense(id) {
  const expense = expenseRepository.getById(id);
  const user = authRepository.getCurrentUser();
  if (!expense || !canSelfManagePendingExpense(expense, user)) { showToast('Action non autorisée.', 'error'); return; }
  openConfirm({
    title: 'Annuler votre note de frais ?',
    message: 'Cette note n\'a encore été validée par personne : elle sera annulée sans repasser par un refus.',
    confirmLabel: 'Annuler la note',
    danger: true,
    onConfirm: () => {
      expenseRepository.update(id, cancelRequest(expense));
      // §retour Betty du 07/09/2026, revenu le 11/09/2026 ("vrai défaut de paiement") : une note
      // Kilométrique annulée ne doit plus compter dans le cumul annuel des AUTRES notes déjà
      // enregistrées — voir recalculerIndemnitesKilometriquesAnnee (data.js).
      if (expense.categorie === 'Kilométrique') expenseRepository.recalculerIndemnitesKilometriques(expense.employeeId, (expense.date || '').slice(0, 4));
      auditLogRepository.logAudit('Annulation', 'Note de frais', auditLabelForEmployee(expense.employeeId), auditDetailsForActor());
      showToast('Note de frais annulée.');
      render();
    }
  });
}

function handleMarkExpensePaid(id) {
  const expense = expenseRepository.getById(id);
  const user = authRepository.getCurrentUser();
  if (!expense || expense.statut !== 'Remboursé' || expense.datePaiement || !hasPermission(user, PERMISSIONS.MARQUER_NOTE_REMBOURSEE)) {
    showToast('Action non autorisée.', 'error');
    return;
  }
  expenseRepository.update(id, markExpensePaid(expense));
  auditLogRepository.logAudit('Paiement', 'Note de frais', auditLabelForEmployee(expense.employeeId), auditDetailsForActor());
  showToast('Note de frais marquée comme payée.');
  render();
}

function handleApproveExpense(id) {
  const expense = expenseRepository.getById(id);
  if (!expense || !canActOnRequestFor(expense, 'frais')) { showToast('Action non autorisée.', 'error'); return; }
  const patch = advanceWorkflow(expense, 'Remboursé', currentActorRoleLabel());
  expenseRepository.update(id, patch);
  auditLogRepository.logAudit('Validation', 'Note de frais', auditLabelForEmployee(expense.employeeId), auditDetailsForActor());
  if (patch.statut !== 'En attente') {
    notifyRequesterEmail(expense.id, 'frais', 'validee');
  }
  showToast(patch.statut === 'Remboursé' ? 'Note de frais remboursée.' : 'Étape de validation suivante en attente.');
  render();
}

function handleRefuseExpense(id) {
  const expense = expenseRepository.getById(id);
  if (!expense || !canRefuserRequestFor(expense, 'frais')) { showToast('Action non autorisée.', 'error'); return; }
  openRefuseModal({
    title: 'Refuser cette note de frais ?',
    message: 'Le salarié sera informé du refus.',
    onConfirm: (motif) => {
      expenseRepository.update(id, refuseRequest(expense, motif));
      // §retour Betty du 07/09/2026, revenu le 11/09/2026 ("vrai défaut de paiement") : voir le
      // commentaire identique sur handleCancelExpense/handleSelfCancelExpense ci-dessous.
      if (expense.categorie === 'Kilométrique') expenseRepository.recalculerIndemnitesKilometriques(expense.employeeId, (expense.date || '').slice(0, 4));
      auditLogRepository.logAudit('Refus', 'Note de frais', `${auditLabelForEmployee(expense.employeeId)} : ${motif}`, auditDetailsForActor());
      notifyRequesterEmail(expense.id, 'frais', 'refusee', motif);
      showToast('Note de frais refusée.');
      render();
    }
  });
}

function handleCancelExpense(id) {
  const expense = expenseRepository.getById(id);
  if (!expense || !canManageRequestFor(expense.employeeId, 'frais')) { showToast('Action non autorisée.', 'error'); return; }
  openConfirm({
    title: 'Annuler cette note de frais ?',
    message: 'La validation sera annulée.',
    confirmLabel: 'Annuler',
    danger: true,
    onConfirm: () => {
      expenseRepository.update(id, cancelRequest(expense));
      // §retour Betty du 07/09/2026, revenu le 11/09/2026 ("vrai défaut de paiement") : une note
      // Kilométrique annulée/refusée ne doit plus compter dans le cumul annuel des AUTRES notes déjà
      // enregistrées pour ce salarié cette année-là — sans ce recalcul, elles restent surévaluées ou
      // sous-évaluées sur un cumul qui n'existe plus (voir recalculerIndemnitesKilometriquesAnnee,
      // data.js). Motif du choix `expense.date` (date du trajet) plutôt qu'aujourd'hui pour l'année :
      // une note peut être refusée bien après l'année où le trajet a eu lieu.
      if (expense.categorie === 'Kilométrique') expenseRepository.recalculerIndemnitesKilometriques(expense.employeeId, (expense.date || '').slice(0, 4));
      auditLogRepository.logAudit('Annulation', 'Note de frais', auditLabelForEmployee(expense.employeeId), auditDetailsForActor());
      showToast('Note de frais annulée.');
      render();
    }
  });
}

function exportExpensesCSV() {
  const expenses = getFilteredExpenses();
  // §retour Betty du 07/09/2026 (point 9) : ni matricule ni date de remboursement — même remarque
  // que pour l'export des congés, le matricule est la clé de rapprochement avec la paie, sans lui
  // le fichier n'est utilisable qu'à l'œil. La date de remboursement (vide tant que non remboursée)
  // réutilise getExpenseRembourseDate (data.js), la même donnée qui rattache désormais la note au
  // bon mois de paie (voir getPaieRows, point 2).
  // §retour Betty du 07/09/2026 (point 12) : indicateur de déductibilité par catégorie (simple
  // indicateur, pas une règle fiscale complète — voir categoriesFraisConfig, data.js) séparé en
  // colonne pour que le comptable distingue la TVA récupérable du reste sans recalculer à la main.
  const settings = settingsRepository.getSettings();
  const headers = ['Matricule', 'Salarié', 'Date', 'Catégorie', 'Libellé', 'Montant HT', 'TVA', 'TVA déductible', 'Montant TTC', 'Statut', 'Date de remboursement'];
  const rows = expenses.map(n => {
    const employee = employeeRepository.getById(n.employeeId);
    const categorieConfig = (settings.categoriesFraisConfig || {})[n.categorie];
    const tvaDeductible = !categorieConfig || categorieConfig.tvaDeductible !== false;
    return [
      employee ? employee.matricule : '—',
      employee ? `${employee.prenom} ${employee.nom}` : '—',
      // §retour Betty du 18/09/2026 (point 7) : date au format français, montants en vrai nombre
      // (jamais formatNumberFR, un texte qui s'alignerait à gauche) — voir excelXmlCell.
      formatDate(n.date),
      n.categorie,
      n.libelle,
      computeMontantHT(n.montantTTC, n.tauxTVA),
      computeMontantTVA(n.montantTTC, n.tauxTVA),
      tvaDeductible ? 'Oui' : 'Non',
      n.montantTTC,
      n.statut,
      n.statut === 'Remboursé' ? formatDate(getExpenseRembourseDate(n)) : ''
    ];
  });
  exportRowsToCSV(headers, rows, 'notes-de-frais.csv');
  auditLogRepository.logAudit('Export', 'Notes de frais', `${expenses.length} ligne${expenses.length > 1 ? 's' : ''}`);
}

/** Justificatif requis pour cette catégorie/montant — §retour Betty du 07/09/2026 (point 4).
 * Absent de categoriesFraisConfig = jamais obligatoire, comme avant ce correctif. */
function isJustificatifObligatoireForExpense(categorie, montantTTC, settings) {
  const config = (settings.categoriesFraisConfig || {})[categorie];
  if (!config) return false;
  if (config.justificatifObligatoire) return true;
  return config.seuilJustificatif != null && Number(montantTTC) > Number(config.seuilJustificatif);
}

// ---- Modale : Nouvelle note de frais / modification d'une note en attente (point 5) ----

function openExpenseModal(presetEmployeeId, draft, editingExpense) {
  const employees = employeeRepository.getAll().filter(e => !e.archive);
  const settings = settingsRepository.getSettings();
  // §retour Betty du 07/09/2026 (point 5) : en modification, les champs repartent de la note
  // existante — jamais d'un brouillon (les deux mécanismes ne se recoupent jamais, une note déjà
  // envoyée n'est plus un brouillon).
  const champs = editingExpense
    ? { employeeId: editingExpense.employeeId, categorie: editingExpense.categorie, date: editingExpense.date,
        libelle: editingExpense.libelle, montantTTC: editingExpense.montantTTC, tauxTVA: editingExpense.tauxTVA,
        distanceKm: editingExpense.kilometrage && editingExpense.kilometrage.distanceKm,
        puissanceFiscale: editingExpense.kilometrage && editingExpense.kilometrage.puissanceFiscale,
        typeVehicule: (editingExpense.kilometrage && editingExpense.kilometrage.typeVehicule) || 'voiture',
        electrique: Boolean(editingExpense.kilometrage && editingExpense.kilometrage.electrique),
        commentaire: editingExpense.commentaire, justificatif: editingExpense.justificatif }
    : (draft && draft.champs) || {};
  state.pendingAttachment = champs.justificatif || null;
  state.editingExpenseId = editingExpense ? editingExpense.id : null;
  if (!editingExpense) beginDraftEdit(draft);

  const employeeField = editingExpense
    // Modification toujours restreinte à SA PROPRE note (canSelfManagePendingExpense) — jamais de
    // sélecteur ici, la réattribuer à quelqu'un d'autre lors d'une modification n'aurait pas de sens.
    ? `<input type="hidden" id="f-employeeId" name="employeeId" value="${escapeHtml(champs.employeeId)}">
       <div class="form-field"><label>Salarié</label><input class="input" type="text" value="${personNameHtml(authRepository.getCurrentUser())}" disabled></div>`
    : employeeFieldForRequest(presetEmployeeId || champs.employeeId, employees, 'frais');
  const justificatifObligatoire = isJustificatifObligatoireForExpense(champs.categorie || settings.categoriesFrais[0], champs.montantTTC, settings);

  const html = `
    <div class="modal modal-large">
      <div class="modal-header">
        <h2>${editingExpense ? 'Modifier la note de frais' : 'Nouvelle note de frais'}</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="expense-form">
        <div class="modal-body">
          <div class="form-grid">
            ${employeeField}
            ${selectField('categorie', 'Catégorie', settings.categoriesFrais, champs.categorie || settings.categoriesFrais[0], null, undefined, 'categoriesFrais')}
            ${textField('date', 'Date de la dépense', champs.date || '', true, 'date')}
            ${textField('libelle', 'Libellé', champs.libelle || '', true)}
          </div>

          <div class="form-grid" id="expense-standard-fields" style="margin-top: 14px;">
            <!-- §correctif audit du 16/09/2026 : un repli sur chaîne vide effaçait un montant
                 existant valant explicitement 0 (note à 0€), 0 étant falsy — ce champ vide
                 déclenchait ensuite le pré-remplissage forfaitaire (voir updateExpenseCategoryFields)
                 qui écrasait silencieusement le vrai 0 saisi par l'utilisateur. -->
            ${textField('montantTTC', 'Montant TTC (€)', champs.montantTTC != null ? champs.montantTTC : '', false, 'number')}
            <div class="form-field">
              <label for="f-tauxTVA">Taux de TVA</label>
              <select class="input" id="f-tauxTVA" name="tauxTVA">
                ${TVA_RATES.map(t => `<option value="${t}" ${champs.tauxTVA !== undefined && Number(champs.tauxTVA) === t ? 'selected' : ''}>${formatPercentFR(t)}</option>`).join('')}
              </select>
            </div>
          </div>
          <!-- §retour Betty du 14/09/2026 (Notes de frais point 3, "forfaits journaliers") : montant
               pré-rempli automatiquement quand la catégorie a un forfait configuré (Paramètres),
               reste modifiable — jamais imposé si le réel diffère légèrement du forfait. -->
          <p class="text-muted" id="expense-forfait-hint" style="margin-top: 6px;"></p>

          <!-- §retour Betty du 11/09/2026 (point 5, "barème paramétrable par motorisation") : la
               puissance fiscale n'a de sens que pour voiture/moto (les cyclomoteurs < 50 cm3 n'ont
               pas de CV au sens fiscal habituel, voir BAREMES_KILOMETRIQUES.cyclomoteur) — masquée
               via updateExpenseCategoryFields/f-typeVehicule ci-dessous plutôt que rendue
               optionnelle partout, pour ne jamais laisser un salarié en voiture/moto la sauter par
               erreur. -->
          <div class="form-grid" id="expense-km-fields" style="margin-top: 14px; display: none;">
            ${textField('distanceKm', 'Distance (km, aller-retour inclus)', champs.distanceKm || '', false, 'number')}
            <div class="form-field">
              <label for="f-typeVehicule">Type de véhicule</label>
              <select class="input" id="f-typeVehicule" name="typeVehicule">
                <option value="voiture" ${(champs.typeVehicule || 'voiture') === 'voiture' ? 'selected' : ''}>Voiture</option>
                <option value="moto" ${champs.typeVehicule === 'moto' ? 'selected' : ''}>Moto</option>
                <option value="cyclomoteur" ${champs.typeVehicule === 'cyclomoteur' ? 'selected' : ''}>Cyclomoteur (&lt; 50 cm³)</option>
              </select>
            </div>
            <div class="form-field" id="field-puissance-fiscale">
              ${textField('puissanceFiscale', 'Puissance fiscale (CV)', champs.puissanceFiscale || '', false, 'number')}
            </div>
            <div class="form-field form-field-checkbox" style="align-items: flex-end;">
              <label><input type="checkbox" id="f-vehiculeElectrique" ${champs.electrique ? 'checked' : ''}> Véhicule électrique (majoration de 20 %)</label>
            </div>
          </div>
          <p class="text-muted" id="expense-km-hint" style="margin-top: 8px;"></p>

          <div class="form-field" style="margin-top: 14px;">
            <label for="f-commentaire">Commentaire</label>
            <textarea class="input" id="f-commentaire" name="commentaire" rows="2">${escapeHtml(champs.commentaire || '')}</textarea>
          </div>
          <div class="form-field" style="margin-top: 14px;">
            <label for="f-justificatif" id="expense-justificatif-label">Justificatif${justificatifObligatoire ? ' (obligatoire pour cette catégorie)' : ' (optionnel)'}</label>
            <input class="input" type="file" id="f-justificatif">
            ${champs.justificatif ? `<p class="text-muted" style="margin-top:4px;">Fichier déjà associé : ${escapeHtml(champs.justificatif.nom)}</p>` : ''}
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          ${editingExpense ? '' : '<button type="button" class="btn btn-secondary" id="btn-save-draft">Enregistrer comme brouillon</button>'}
          <button type="submit" class="btn btn-primary">${editingExpense ? 'Enregistrer les modifications' : 'Envoyer la note'}</button>
        </div>
      </form>
    </div>
  `;

  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');

  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('f-justificatif').addEventListener('change', handleAttachmentChange);
  document.getElementById('f-categorie').addEventListener('change', () => { updateExpenseCategoryFields(); updateExpenseJustificatifLabel(); });
  document.getElementById('f-distanceKm').addEventListener('input', updateExpenseKmHint);
  document.getElementById('f-puissanceFiscale').addEventListener('input', updateExpenseKmHint);
  document.getElementById('f-typeVehicule').addEventListener('change', () => { updateExpensePuissanceFiscaleVisibility(); updateExpenseKmHint(); });
  document.getElementById('f-vehiculeElectrique').addEventListener('change', updateExpenseKmHint);
  updateExpensePuissanceFiscaleVisibility();
  // §retour Betty du 07/09/2026 : le cumul annuel dépend de l'année de la dépense — sans ce
  // listener, changer la date après avoir déjà saisi distance/puissance laissait l'aperçu affiché
  // sur le cumul de la mauvaise année.
  document.getElementById('f-date').addEventListener('change', updateExpenseKmHint);
  // §retour Betty du 07/09/2026 (point 4) : le seuil de justificatif dépend du montant saisi — le
  // libellé doit se mettre à jour en direct, pas seulement au chargement de la modale.
  document.getElementById('f-montantTTC').addEventListener('input', updateExpenseJustificatifLabel);
  document.getElementById('expense-form').addEventListener('submit', submitExpenseForm);
  const saveDraftBtn = document.getElementById('btn-save-draft');
  if (saveDraftBtn) saveDraftBtn.addEventListener('click', () => {
    saveDraftFromForm(document.getElementById('expense-form'), 'frais', { justificatif: state.pendingAttachment });
  });

  updateExpenseCategoryFields();
}

function updateExpenseJustificatifLabel() {
  const label = document.getElementById('expense-justificatif-label');
  if (!label) return;
  const categorie = document.getElementById('f-categorie').value;
  const montantTTC = document.getElementById('f-montantTTC') ? document.getElementById('f-montantTTC').value : 0;
  const obligatoire = isJustificatifObligatoireForExpense(categorie, montantTTC, settingsRepository.getSettings());
  label.textContent = `Justificatif${obligatoire ? ' (obligatoire pour cette catégorie)' : ' (optionnel)'}`;
}

function updateExpenseCategoryFields() {
  const categorie = document.getElementById('f-categorie').value;
  const isKm = categorie === 'Kilométrique';
  document.getElementById('expense-standard-fields').style.display = isKm ? 'none' : 'grid';
  document.getElementById('expense-km-fields').style.display = isKm ? 'grid' : 'none';
  if (isKm) { updateExpensePuissanceFiscaleVisibility(); updateExpenseKmHint(); } else document.getElementById('expense-km-hint').textContent = '';

  // §retour Betty du 14/09/2026 (Notes de frais point 3, "forfaits journaliers, appliqués
  // automatiquement") : ne remplace jamais une valeur déjà tapée par l'utilisateur, seulement le
  // champ encore vide — changer de catégorie par erreur après avoir déjà saisi un montant réel ne
  // doit jamais l'effacer silencieusement.
  const forfaitHint = document.getElementById('expense-forfait-hint');
  const settings = settingsRepository.getSettings();
  const config = (settings.categoriesFraisConfig || {})[categorie];
  if (!isKm && config && config.montantForfaitaire != null) {
    const montantField = document.getElementById('f-montantTTC');
    if (!montantField.value) montantField.value = config.montantForfaitaire;
    forfaitHint.textContent = `Forfait "${categorie}" : ${formatCurrencyFR(config.montantForfaitaire)} (modifiable si le montant réel diffère).`;
  } else if (forfaitHint) {
    forfaitHint.textContent = '';
  }
}

/** §retour Betty du 11/09/2026 (point 5, barème paramétrable par motorisation) : un cyclomoteur
 * (< 50 cm3) n'a pas de puissance fiscale au sens habituel — BAREMES_KILOMETRIQUES.cyclomoteur n'a
 * d'ailleurs qu'une seule tranche, n'importe quelle valeur y correspondrait de toute façon. Masqué
 * plutôt que laissé optionnel, pour ne jamais laisser un salarié en voiture/moto le sauter par erreur. */
function updateExpensePuissanceFiscaleVisibility() {
  const typeVehicule = document.getElementById('f-typeVehicule').value;
  document.getElementById('field-puissance-fiscale').style.display = typeVehicule === 'cyclomoteur' ? 'none' : 'block';
}

function updateExpenseKmHint() {
  const distanceKm = Number(document.getElementById('f-distanceKm').value) || 0;
  const typeVehicule = document.getElementById('f-typeVehicule').value;
  const puissanceFiscale = typeVehicule === 'cyclomoteur' ? 0 : (Number(document.getElementById('f-puissanceFiscale').value) || 0);
  const electrique = document.getElementById('f-vehiculeElectrique').checked;
  const hint = document.getElementById('expense-km-hint');
  if (!distanceKm || (typeVehicule !== 'cyclomoteur' && !puissanceFiscale)) {
    hint.textContent = typeVehicule === 'cyclomoteur'
      ? 'Renseignez la distance pour calculer l\'indemnité.'
      : 'Renseignez la distance et la puissance fiscale pour calculer l\'indemnité.';
    return;
  }
  // §retour Betty du 07/09/2026 : l'aperçu affiché pendant la saisie doit refléter le VRAI montant
  // qui sera enregistré (calcul cumulatif annuel), pas un montant par trajet qui induirait le
  // salarié en erreur avant même l'envoi — voir calculateIndemniteKilometrique/submitExpenseForm.
  // Exclut la note elle-même du cumul en mode modification (point 5), sinon elle se compterait deux fois.
  const employeeId = document.getElementById('f-employeeId').value;
  const dateStr = document.getElementById('f-date').value || toISODate(new Date());
  const kmDejaDeclares = getKilometrageDejaDeclareAnnee(employeeId, dateStr, expenseRepository.getAll(), state.editingExpenseId, typeVehicule);
  const montant = calculateIndemniteKilometrique(distanceKm, puissanceFiscale, kmDejaDeclares, { typeVehicule, electrique });
  hint.textContent = kmDejaDeclares > 0
    ? `Indemnité kilométrique calculée automatiquement : ${formatCurrencyFR(montant)} (${formatNumberFR(kmDejaDeclares)} km déjà déclarés cette année pour ce type de véhicule, avant cette note).`
    : `Indemnité kilométrique calculée automatiquement : ${formatCurrencyFR(montant)}`;
}

async function submitExpenseForm(evt) {
  evt.preventDefault();
  const formData = new FormData(evt.target);
  const employeeId = formData.get('employeeId');
  const categorie = formData.get('categorie');
  const isEditing = Boolean(state.editingExpenseId);

  if (!employeeId || !categorie) {
    showToast('Sélectionnez un salarié et une catégorie.', 'error');
    return;
  }

  // §retour Betty du 07/09/2026 (point 3) : aucun contrôle n'existait sur la date de la dépense —
  // une dépense datée dans le futur ou antérieure à l'embauche du salarié était acceptée telle
  // quelle, alors que le module Congés vérifie déjà ce genre de choses sur ses propres dates.
  const dateDepense = formData.get('date');
  const employeeForDate = employeeRepository.getById(employeeId);
  if (dateDepense > toISODate(new Date())) {
    showToast('La date de la dépense ne peut pas être dans le futur.', 'error');
    return;
  }
  if (employeeForDate && employeeForDate.dateEmbauche && dateDepense < employeeForDate.dateEmbauche) {
    showToast(`La date de la dépense ne peut pas être antérieure à la date d'embauche (${formatDate(employeeForDate.dateEmbauche)}).`, 'error');
    return;
  }

  // §retour Betty du 18/09/2026 (point 8) : voir le même contrôle dans submitLeaveRequestForm ;
  // uniquement à la création (expenses_insert, 0059), jamais sur la modification d'une note déjà
  // enregistrée, qui reste possible même si l'accès a été retiré depuis.
  if (!isEditing && !hasModuleLicense(employeeForDate, 'frais')) {
    showToast(`${employeeForDate.prenom} ${employeeForDate.nom} n'a pas d'accès au module Notes de frais : demandez à un Propriétaire/RH de lui attribuer une licence (Paramètres > Abonnement > Gérer les accès).`, 'error');
    return;
  }

  let montantTTC, tauxTVA, kilometrage = null;

  if (categorie === 'Kilométrique') {
    const distanceKm = Number(formData.get('distanceKm')) || 0;
    // §retour Betty du 11/09/2026 (barème paramétrable par motorisation) : un cyclomoteur (<50cm3)
    // n'a pas de puissance fiscale au sens habituel (champ masqué, voir
    // updateExpensePuissanceFiscaleVisibility) — n'exige donc pas cette valeur, contrairement à
    // voiture/moto.
    const typeVehicule = formData.get('typeVehicule') || 'voiture';
    const puissanceFiscale = typeVehicule === 'cyclomoteur' ? 0 : (Number(formData.get('puissanceFiscale')) || 0);
    const electrique = document.getElementById('f-vehiculeElectrique').checked;
    if (distanceKm <= 0 || (typeVehicule !== 'cyclomoteur' && puissanceFiscale <= 0)) {
      showToast(typeVehicule === 'cyclomoteur' ? 'Renseignez une distance valide (supérieure à 0).' : 'Renseignez une distance et une puissance fiscale valides (supérieures à 0).', 'error');
      return;
    }
    // §retour Betty du 07/09/2026 (point 1) : recalculé ici plutôt que de faire confiance au
    // montant affiché à l'écran au moment de la saisie — une autre note kilométrique a pu être
    // envoyée entre-temps (ex. deux onglets ouverts), le cumul doit être celui à l'instant de l'envoi.
    // Exclut la note elle-même en modification (point 5), sinon elle se compterait deux fois. Le
    // cumul est scopé au type de véhicule (point 5, 11/09/2026) : voiture et moto ne se mélangent
    // jamais dans le même compteur annuel.
    const kmDejaDeclares = getKilometrageDejaDeclareAnnee(employeeId, formData.get('date'), expenseRepository.getAll(), state.editingExpenseId, typeVehicule);
    montantTTC = calculateIndemniteKilometrique(distanceKm, puissanceFiscale, kmDejaDeclares, { typeVehicule, electrique });
    tauxTVA = 0;
    kilometrage = { distanceKm, puissanceFiscale, typeVehicule, electrique };
  } else {
    montantTTC = Number(formData.get('montantTTC')) || 0;
    tauxTVA = Number(formData.get('tauxTVA'));
    if (montantTTC <= 0) {
      showToast('Indiquez un montant valide.', 'error');
      return;
    }
  }

  const settings = settingsRepository.getSettings();
  // §retour Betty du 07/09/2026 (point 4) : premier contrôle qu'attend un comptable — sans
  // justificatif, la TVA n'est pas déductible.
  if (isJustificatifObligatoireForExpense(categorie, montantTTC, settings) && !state.pendingAttachment) {
    showToast(`Un justificatif est obligatoire pour la catégorie "${categorie}".`, 'error');
    return;
  }

  const data = {
    employeeId, categorie, kilometrage, montantTTC, tauxTVA,
    date: dateDepense,
    libelle: formData.get('libelle'),
    commentaire: formData.get('commentaire') || '',
    justificatif: state.pendingAttachment
  };
  const submitBtn = evt.target.querySelector('button[type="submit"]');
  // §retour Betty du 07/09/2026 (point 5) : capturé AVANT tout appel à openConfirm/closeModal, qui
  // remet state.editingExpenseId à null (voir closeModal) avant même que onConfirm ne s'exécute —
  // sans cette capture, confirmer un avertissement (doublon/plafond) sur une note en cours de
  // modification l'aurait recréée comme une note NEUVE au lieu de la mettre à jour.
  const editingExpenseId = state.editingExpenseId;

  // §retour Betty du 07/09/2026 (points 10 et 11) : deux vérifications en AVERTISSEMENT, jamais en
  // blocage — un doublon ou un dépassement de plafond restent parfois légitimes, mais ne doivent
  // plus passer sans un mot. Exclut la note elle-même en modification.
  const doublon = findDuplicateExpense(employeeId, categorie, dateDepense, montantTTC, expenseRepository.getAll(), editingExpenseId);
  const categorieConfig = (settings.categoriesFraisConfig || {})[categorie];
  const plafondDepasse = categorieConfig && categorieConfig.plafond != null && montantTTC > Number(categorieConfig.plafond);

  if (doublon || plafondDepasse) {
    const messages = [];
    if (doublon) messages.push('Une note très similaire (même salarié, même date, même montant, même catégorie) existe déjà.');
    if (plafondDepasse) messages.push(`Ce montant dépasse le plafond habituel de ${formatCurrencyFR(categorieConfig.plafond)} pour "${categorie}".`);
    openConfirm({
      title: isEditing ? 'Confirmer la modification ?' : 'Confirmer l\'envoi de cette note ?',
      message: messages.join(' '),
      confirmLabel: isEditing ? 'Enregistrer quand même' : 'Envoyer quand même',
      onConfirm: () => finalizeExpenseSubmit(data, submitBtn, editingExpenseId)
    });
    return;
  }

  await finalizeExpenseSubmit(data, submitBtn, editingExpenseId);
}

/** Création OU modification (point 5) selon editingExpenseId — séparé de submitExpenseForm pour
 * pouvoir être rappelé depuis la confirmation d'avertissement (doublon/plafond) sans reprendre la
 * saisie depuis zéro. editingExpenseId est un PARAMÈTRE explicite, jamais relu depuis
 * state.editingExpenseId ici : openConfirm ferme déjà la modale (donc remet ce state à null, voir
 * closeModal) avant d'appeler onConfirm. */
async function finalizeExpenseSubmit(data, submitBtn, editingExpenseId) {
  // §correctif audit du 01/09/2026 : voir le même garde-fou dans submitLeaveRequestForm.
  if (submitBtn) submitBtn.disabled = true;

  if (editingExpenseId) {
    const id = editingExpenseId;
    const original = expenseRepository.getById(id);
    const historique = ((original && original.historique) || []).slice();
    historique.push({ date: new Date().toISOString(), action: 'Modifiée par le demandeur' });
    expenseRepository.update(id, {
      categorie: data.categorie, kilometrage: data.kilometrage, montantTTC: data.montantTTC, tauxTVA: data.tauxTVA,
      date: data.date, libelle: data.libelle, commentaire: data.commentaire, justificatif: data.justificatif, historique
    });
    uploadJustificatifBestEffort({
      uploader: window.SupabaseSync.uploadJustificatifFile,
      employeeId: data.employeeId, recordId: id, file: state.pendingAttachmentFile,
      patcher: (justificatif) => expenseRepository.update(id, { justificatif })
    });
    auditLogRepository.logAudit('Modification', 'Note de frais', auditLabelForEmployee(data.employeeId), auditDetailsForActor());
    showToast('Note de frais modifiée.');
    state.editingExpenseId = null;
    closeModal();
    navigateTo('frais');
    return;
  }

  const createdExpense = await expenseRepository.create(data);

  uploadJustificatifBestEffort({
    uploader: window.SupabaseSync.uploadJustificatifFile,
    employeeId: data.employeeId, recordId: createdExpense.id, file: state.pendingAttachmentFile,
    patcher: (justificatif) => expenseRepository.update(createdExpense.id, { justificatif })
  });

  finalizeDraftEdit();
  showToast('Note de frais envoyée.');
  // §correctif audit du 23/08/2026 (2.3), même mécanisme que openLeaveRequestModal.
  if (createdExpense.workflowEscalated) {
    showToast('Aucun validateur direct n\'a été trouvé pour cette demande : un RH ou un membre de la Direction devra la valider manuellement.', 'error');
  }
  closeModal();
  navigateTo('frais');
}

// ---- Modale : Détail / impression d'une note de frais ----

function openExpenseDetailModal(id) {
  const n = expenseRepository.getById(id);
  if (!n) { showToast('Cette note de frais n\'est plus disponible.', 'error'); return; }
  const employee = employeeRepository.getById(n.employeeId);
  if (!employee) { showToast('Ce salarié n\'est plus disponible.', 'error'); return; }
  const ht = computeMontantHT(n.montantTTC, n.tauxTVA);
  const tva = computeMontantTVA(n.montantTTC, n.tauxTVA);

  const html = `
    <div class="modal">
      <div class="modal-header">
        <h2>Note de frais</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <div class="modal-body">
        <div class="print-area">
          <h2>${personNameHtml(employee)}</h2>
          ${infoRow('Date', formatDate(n.date))}
          ${infoRow('Catégorie', n.categorie)}
          ${infoRow('Libellé', n.libelle)}
          ${n.kilometrage ? infoRow('Distance', `${n.kilometrage.distanceKm} km · ${n.kilometrage.puissanceFiscale} CV`) : ''}
          ${infoRow('Montant HT', formatCurrencyFR(ht))}
          ${infoRow(`TVA (${formatPercentFR(n.tauxTVA)})`, formatCurrencyFR(tva))}
          ${infoRow('Montant TTC', formatCurrencyFR(n.montantTTC))}
          ${infoRow('Statut', n.statut)}
          ${n.commentaire ? infoRow('Commentaire', n.commentaire) : ''}
          ${n.justificatif ? `<div id="expense-justificatif-preview" style="margin-top: 12px;"></div>` : ''}
        </div>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Fermer</button>
        <button type="button" class="btn btn-primary" id="btn-print-expense">Imprimer / Export PDF</button>
      </div>
    </div>
  `;

  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');

  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('btn-print-expense').addEventListener('click', () => window.print());
  if (n.justificatif) renderJustificatifPreview('expense-justificatif-preview', n.justificatif);
}

/** Affiche l'aperçu d'un justificatif (congé/note de frais) dans un conteneur déjà présent dans le
 * DOM — asynchrone car un fichier réel (Storage, `path`) nécessite une URL signée récupérée à la
 * demande ; un dataUrl local (pas encore uploadé, ou données antérieures à cette migration) reste
 * affiché immédiatement, sans aller-retour réseau. */
async function renderJustificatifPreview(containerId, justificatif) {
  const container = document.getElementById(containerId);
  if (!container) return;
  if (justificatif.dataUrl) {
    container.innerHTML = `<img src="${escapeHtml(justificatif.dataUrl)}" alt="Justificatif" style="max-width: 100%; border-radius: 8px;">`;
    return;
  }
  if (justificatif.path) {
    container.innerHTML = renderSkeletonLines(1);
    try {
      const url = await window.SupabaseSync.getJustificatifFileUrl(justificatif.path);
      container.innerHTML = `<a href="${escapeHtml(url)}" target="_blank" rel="noopener" class="btn btn-secondary btn-sm">Voir le justificatif</a>`;
    } catch {
      container.innerHTML = '<p class="text-muted">Justificatif indisponible pour le moment.</p>';
    }
  }
}

// ---------------------------------------------------------------------------
// Vue : Tickets restaurant (calcul automatique, aucune saisie)
// ---------------------------------------------------------------------------

/** §sprint refonte UX §9-10 : point d'entrée unique du nav "tickets" — RH/Comptabilité/Propriétaire
 * gardent la vue équipe historique via la bascule Moi/Équipe partagée ; tous les autres (et ces
 * mêmes rôles en "Moi") tombent sur la nouvelle vue personnelle ci-dessous. Avant ce sprint, un
 * salarié sans la permission CALCULER_TICKETS_RESTAURANT n'avait accès à AUCUNE vue de ses tickets. */
function renderTicketsHub() {
  const user = authRepository.getCurrentUser();
  const canVoirEquipe = hasPermission(user, PERMISSIONS.CALCULER_TICKETS_RESTAURANT);
  const vueEquipe = canVoirEquipe && state.ticketsRestaurantVue !== 'personnel';
  return `
    ${canVoirEquipe ? renderMoiEquipeToggle('ticketsRestaurantVue', 'equipe', 'Tickets restaurant équipe') : ''}
    ${vueEquipe ? renderTicketsEquipe() : renderMesTicketsRestaurant()}
  `;
}

function bindTicketsHubEvents() {
  const user = authRepository.getCurrentUser();
  const canVoirEquipe = hasPermission(user, PERMISSIONS.CALCULER_TICKETS_RESTAURANT);
  if (canVoirEquipe) bindMoiEquipeToggleEvents();
  const vueEquipe = canVoirEquipe && state.ticketsRestaurantVue !== 'personnel';
  if (vueEquipe) bindTicketsEquipeEvents();
  else bindMesTicketsRestaurantEvents();
}

/** Vue salarié : historique mensuel de ses propres tickets restaurant. Réutilise directement
 * calculateTicketsRestaurant() (aucun nouveau calcul) et le journal d'audit existant pour le motif
 * d'une éventuelle régularisation — DB.ajusterTicketsRestaurant() y écrit déjà ce motif en texte,
 * pas besoin d'un nouveau champ structuré pour l'exposer ici. */
function renderMesTicketsRestaurant() {
  const user = authRepository.getCurrentUser();
  const employee = employeeRepository.getById(user.id);
  if (!employee) return '<p class="text-muted">Fiche salarié introuvable.</p>';
  const settings = settingsRepository.getSettings();
  const leaveRequests = leaveRepository.getAll();
  const teleworkRequests = teleworkRepository.getAll();
  const year = state.mesTicketsYear;
  const month = state.mesTicketsMonth;
  const result = calculateTicketsRestaurant(employee, year, month, leaveRequests, teleworkRequests, settings);
  const regularisation = result.ajustement ? findTicketsRegularisationMotif(employee, year, month) : null;

  const historique = [];
  for (let i = 1; i <= 6; i++) {
    const d = new Date(year, month - i, 1);
    historique.push({
      year: d.getFullYear(),
      month: d.getMonth(),
      result: calculateTicketsRestaurant(employee, d.getFullYear(), d.getMonth(), leaveRequests, teleworkRequests, settings)
    });
  }

  return `
    <div class="view-header view-header-row">
      <div>
        <h1>Mes tickets restaurant</h1>
        <p class="view-subtitle">${MONTH_NAMES[month]} ${year} · valeur faciale ${formatCurrencyFR(settings.ticketsValeurFaciale)} (${formatPercentFR(settings.ticketsPartEmployeurPct)} employeur)</p>
      </div>
      <div class="detail-header-actions">
        <button class="btn btn-secondary btn-sm" id="btn-mes-tickets-prev">← Précédent</button>
        <button class="btn btn-secondary btn-sm" id="btn-mes-tickets-today">Ce mois-ci</button>
        <button class="btn btn-secondary btn-sm" id="btn-mes-tickets-next">Suivant →</button>
      </div>
    </div>

    <div class="kpi-grid">
      ${kpiCard('Jours éligibles', result.nbTickets, ICONS.calendar)}
      ${kpiCard('Tickets attribués', result.nbTickets, ICONS.utensils)}
      ${kpiCard('Valeur unitaire', formatCurrencyFR(settings.ticketsValeurFaciale), ICONS.coin)}
      ${kpiCard('Montant total', formatCurrencyFR(result.montantTotal), ICONS.coin)}
      ${kpiCard('Part employeur', formatCurrencyFR(result.partEmployeur), ICONS.building)}
      ${kpiCard('Part salarié', formatCurrencyFR(result.partSalarie), ICONS.person)}
    </div>

    ${result.ajustement ? `
      <div class="card" style="margin-top: 12px;">
        <p style="margin: 0;">${icon(ICONS.scale, 14)} Régularisation appliquée ce mois : <strong>${result.ajustement >= 0 ? '+' : ''}${result.ajustement} ticket${Math.abs(result.ajustement) > 1 ? 's' : ''}</strong>${regularisation ? ` — ${escapeHtml(regularisation)}` : ''}</p>
      </div>
    ` : ''}

    <div class="card table-card" style="margin-top: 16px;">
      <div class="view-header-row" style="padding: 16px 20px 0;">
        <h2>Historique</h2>
      </div>
      <table class="table">
        <thead><tr><th>Mois</th><th class="cell-numeric">Tickets</th><th class="cell-numeric">Montant total</th><th class="cell-numeric">Part salarié</th></tr></thead>
        <tbody>
          ${historique.map(h => `
            <tr class="table-row" data-mes-tickets-month="${h.year}-${h.month}">
              <td>${MONTH_NAMES[h.month]} ${h.year}</td>
              <td class="cell-numeric">${h.result.nbTickets}${h.result.ajustement ? ` <span class="text-muted">(correction ${h.result.ajustement >= 0 ? '+' : ''}${h.result.ajustement})</span>` : ''}</td>
              <td class="cell-numeric">${formatCurrencyFR(h.result.montantTotal)}</td>
              <td class="cell-numeric">${formatCurrencyFR(h.result.partSalarie)}</td>
            </tr>
          `).join('')}
        </tbody>
      </table>
    </div>
  `;
}

function findTicketsRegularisationMotif(employee, year, month) {
  const monthKey = ticketsMonthKey(year, month);
  const entry = DB.getAuditLog().find(e =>
    e.entite === 'Tickets restaurant' &&
    e.cible.startsWith(`${employee.prenom} ${employee.nom}`) &&
    e.cible.includes(monthKey));
  if (!entry) return null;
  // cible = "Prénom Nom · AAAA-MM · correction ±N[ · motif]" (voir DB.ajusterTicketsRestaurant) —
  // le motif éventuel est tout ce qui suit le segment technique "correction ±N", jamais celui-ci.
  const parts = entry.cible.split(' · ');
  return parts.length > 3 ? parts.slice(3).join(' · ') : null;
}

function bindMesTicketsRestaurantEvents() {
  document.getElementById('btn-mes-tickets-prev').addEventListener('click', () => shiftMesTicketsMonth(-1));
  document.getElementById('btn-mes-tickets-next').addEventListener('click', () => shiftMesTicketsMonth(1));
  document.getElementById('btn-mes-tickets-today').addEventListener('click', () => {
    const now = new Date();
    state.mesTicketsYear = now.getFullYear();
    state.mesTicketsMonth = now.getMonth();
    render();
  });
  document.querySelectorAll('[data-mes-tickets-month]').forEach(row => {
    row.addEventListener('click', () => {
      const [y, m] = row.dataset.mesTicketsMonth.split('-').map(Number);
      state.mesTicketsYear = y;
      state.mesTicketsMonth = m;
      render();
    });
  });
}

function shiftMesTicketsMonth(delta) {
  let month = state.mesTicketsMonth + delta;
  let year = state.mesTicketsYear;
  if (month < 0) { month = 11; year -= 1; }
  if (month > 11) { month = 0; year += 1; }
  state.mesTicketsMonth = month;
  state.mesTicketsYear = year;
  render();
}

function getTicketsRows() {
  const year = state.ticketsYear;
  const month = state.ticketsMonth;
  const monthStart = `${year}-${String(month + 1).padStart(2, '0')}-01`;
  const monthEnd = toISODate(new Date(year, month + 1, 0));
  // Même bug que l'export paie (cf. getPaieRows) : on peut naviguer vers un mois passé, donc filtrer
  // sur le statut ACTUEL du salarié lui ferait perdre tous ses tickets d'un mois où il était encore
  // présent — calculateTicketsRestaurant borne déjà correctement le calcul lui-même, mais encore
  // faut-il que le salarié atteigne cette fonction.
  const employees = employeeRepository.getAll().filter(e => !e.archive && isEmployedDuringPeriod(e, monthStart, monthEnd));
  const settings = settingsRepository.getSettings();
  const leaveRequests = leaveRepository.getAll();
  const teleworkRequests = teleworkRepository.getAll();

  return employees.map(e => ({
    employee: e,
    result: calculateTicketsRestaurant(e, year, month, leaveRequests, teleworkRequests, settings),
    // §retour Betty du 14/09/2026 (point 3, "régularisation automatique") : null si rien à régulariser.
    ecartRegularisation: calculerEcartRegularisationTickets(e, year, month, leaveRequests, teleworkRequests, settings),
    // §retour Betty du 14/09/2026 (point 2, "suivi des bénéficiaires") : entrée/sortie DANS le mois affiché.
    entreeDansLeMois: e.dateEmbauche >= monthStart && e.dateEmbauche <= monthEnd ? e.dateEmbauche : null,
    sortieDansLeMois: e.dateDepart && e.dateDepart >= monthStart && e.dateDepart <= monthEnd ? e.dateDepart : null
  }));
}

/** §sprint refonte UX §9-10 : vue équipe historique de Tickets restaurant (RH/Comptabilité/
 * Propriétaire), désormais atteinte via la bascule Moi/Équipe (renderTicketsHub) plutôt qu'une entrée
 * de menu séparée. Corps inchangé. */
function renderTicketsEquipe() {
  const settings = settingsRepository.getSettings();
  const rows = getTicketsRows();
  const canCorriger = hasPermission(authRepository.getCurrentUser(), PERMISSIONS.CORRIGER_TICKETS_RESTAURANT);
  const totals = rows.reduce((acc, r) => ({
    nbTickets: acc.nbTickets + r.result.nbTickets,
    montantTotal: acc.montantTotal + r.result.montantTotal,
    partEmployeur: acc.partEmployeur + r.result.partEmployeur,
    partSalarie: acc.partSalarie + r.result.partSalarie
  }), { nbTickets: 0, montantTotal: 0, partEmployeur: 0, partSalarie: 0 });

  // §retour Betty du 14/09/2026 (point 4, "contrôle du plafond d'exonération") : le contrôle
  // existait déjà (PLAFOND_EXONERATION_URSSAF_2026), mais seulement dans le formulaire de Paramètres
  // au moment de CONFIGURER les valeurs — jamais rappelé ensuite sur l'écran mensuel où RH regarde
  // vraiment le résultat. Même constante, jamais une seconde valeur à maintenir séparément.
  const partEmployeurParTitre = round2(settings.ticketsValeurFaciale * settings.ticketsPartEmployeurPct / 100);
  const depassePlafond = partEmployeurParTitre > PLAFOND_EXONERATION_URSSAF_2026;

  return `
    <div class="view-header view-header-row">
      <div>
        <h1>Tickets restaurant</h1>
        <p class="view-subtitle">${MONTH_NAMES[state.ticketsMonth]} ${state.ticketsYear} · valeur faciale ${formatCurrencyFR(settings.ticketsValeurFaciale)} (${formatPercentFR(settings.ticketsPartEmployeurPct)} employeur)</p>
      </div>
      <div class="detail-header-actions">
        <button class="btn btn-secondary btn-sm" id="btn-tickets-prev">← Précédent</button>
        <button class="btn btn-secondary btn-sm" id="btn-tickets-today">Ce mois-ci</button>
        <button class="btn btn-secondary btn-sm" id="btn-tickets-next">Suivant →</button>
        <button class="btn btn-secondary" id="btn-export-tickets">Exporter CSV</button>
        <button class="btn btn-primary" id="btn-fichier-commande-tickets">Fichier de commande</button>
      </div>
    </div>

    ${depassePlafond ? `
      <div class="card" style="border-left: 3px solid var(--color-danger); margin-bottom: 16px;">
        <p class="text-danger" style="margin: 0;">${icon(ICONS.warningTriangle, 13)} La part employeur par titre (${formatCurrencyFR(partEmployeurParTitre)}) dépasse le plafond d'exonération URSSAF 2026 (${formatCurrencyFR(PLAFOND_EXONERATION_URSSAF_2026)}) : l'excédent devient un avantage en nature à réintégrer. Ajustez la valeur faciale ou la part employeur dans Paramètres.</p>
      </div>
    ` : ''}

    <div class="kpi-grid">
      ${kpiCard('Tickets à émettre', totals.nbTickets, ICONS.utensils)}
      ${kpiCard('Montant total', formatCurrencyFR(totals.montantTotal), ICONS.coin)}
      ${kpiCard('Part employeur', formatCurrencyFR(totals.partEmployeur), ICONS.building)}
      ${kpiCard('Part salarié', formatCurrencyFR(totals.partSalarie), ICONS.person)}
    </div>

    <div class="card table-card">
      <table class="table mobile-cards">
        <thead><tr><th>Salarié</th><th class="cell-numeric">Tickets</th><th class="cell-numeric">Montant total</th><th class="cell-numeric">Part employeur</th><th class="cell-numeric">Part salarié</th><th></th>${canCorriger ? '<th></th>' : ''}</tr></thead>
        <tbody>
          ${rows.map(r => `
            <tr>
              <td class="row-title" data-label="Salarié">${personNameHtml(r.employee)}${r.entreeDansLeMois ? ` <span class="badge badge-info">Entrée ${formatDate(r.entreeDansLeMois)}</span>` : ''}${r.sortieDansLeMois ? ` <span class="badge badge-muted">Sortie ${formatDate(r.sortieDansLeMois)}</span>` : ''}</td>
              <td class="cell-numeric" data-label="Tickets">${r.result.nbTickets}${r.result.ajustement ? ` <span class="text-muted">(correction ${r.result.ajustement >= 0 ? '+' : ''}${r.result.ajustement})</span>` : ''}</td>
              <td class="cell-numeric" data-label="Montant total">${formatCurrencyFR(r.result.montantTotal)}</td>
              <td class="cell-numeric" data-label="Part employeur">${formatCurrencyFR(r.result.partEmployeur)}</td>
              <td class="cell-numeric" data-label="Part salarié">${formatCurrencyFR(r.result.partSalarie)}</td>
              <td>${r.ecartRegularisation && canCorriger ? `<button class="btn-link" data-regulariser-auto-tickets="${r.employee.id}" data-ecart="${r.ecartRegularisation.ecart}" title="Une absence déclarée après la commande change le calcul : ${r.ecartRegularisation.commande} commandés, ${r.ecartRegularisation.actuel} calculés maintenant.">${icon(ICONS.warningTriangle, 12)} Régulariser (${r.ecartRegularisation.ecart >= 0 ? '+' : ''}${r.ecartRegularisation.ecart})</button>` : ''}</td>
              ${canCorriger ? `<td class="table-actions"><button class="btn-link" data-corriger-tickets="${r.employee.id}">Corriger</button></td>` : ''}
            </tr>
          `).join('')}
        </tbody>
      </table>
    </div>
  `;
}

/** `deltaSuggere` (§retour Betty du 14/09/2026, point 3, "régularisation automatique... proposée")
 * : pré-remplit le champ avec l'écart détecté par calculerEcartRegularisationTickets plutôt que la
 * correction actuelle — RH garde la main (motif toujours obligatoire, formulaire inchangé), jamais
 * une écriture silencieuse. Sans ce paramètre, comportement identique à avant ce correctif. */
function openCorrigerTicketsModal(employeeId, deltaSuggere) {
  const employee = employeeRepository.getById(employeeId);
  if (!employee) { showToast('Ce salarié n\'est plus disponible.', 'error'); return; }
  const year = state.ticketsYear;
  const month = state.ticketsMonth;
  const monthKey = `${year}-${String(month + 1).padStart(2, '0')}`;
  const current = deltaSuggere != null ? deltaSuggere : ((employee.ticketsAjustements && employee.ticketsAjustements[monthKey]) || 0);

  const html = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>Corriger les tickets — ${MONTH_NAMES[month]} ${year}</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="corriger-tickets-form">
        <div class="modal-body">
          <p class="text-muted">${personNameHtml(employee)} — cette correction s'ajoute (ou se retranche, si négative) au calcul automatique pour ce mois. Elle remplace la correction précédente pour ce même mois.${deltaSuggere != null ? ' Valeur pré-remplie suggérée automatiquement (absence déclarée après la génération du fichier de commande) : vérifiez avant de valider.' : ''}</p>
          <div class="form-field">
            <label for="f-delta">Correction (tickets, nombre entier, + ou -) *</label>
            <input class="input" type="number" id="f-delta" name="delta" step="1" value="${current}" required>
          </div>
          <!-- §tour de bugs du 07/09/2026 : motif rendu obligatoire — cette correction touche
               directement la paie (calculateTicketsRestaurant) et était jusqu'ici enregistrable
               sans aucune justification textuelle, alors que qui/quand l'étaient déjà (logAudit). -->
          <div class="form-field" style="margin-top: 12px;">
            <label for="f-motif">Motif *</label>
            <input class="input" type="text" id="f-motif" name="motif" placeholder="Ex. jour férié local non reconnu" required>
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="submit" class="btn btn-primary">Enregistrer</button>
        </div>
      </form>
    </div>
  `;

  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');

  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('corriger-tickets-form').addEventListener('submit', (evt) => {
    evt.preventDefault();
    const delta = document.getElementById('f-delta').value;
    const motif = document.getElementById('f-motif').value.trim();
    // §tour de bugs du 07/09/2026 : ne fait pas confiance au seul `required` HTML (contournable en
    // modifiant le DOM), même principe défensif qu'ailleurs dans le fichier.
    if (!motif) { showToast('Indiquez un motif pour cette correction.', 'error'); return; }
    const result = employeeRepository.ajusterTickets(employeeId, year, month, delta, motif);
    if (!result.success) { showToast(result.error, 'error'); return; }
    showToast('Correction enregistrée.');
    closeModal();
    render();
  });
}

function bindTicketsEquipeEvents() {
  document.getElementById('btn-tickets-prev').addEventListener('click', () => shiftTicketsMonth(-1));
  document.getElementById('btn-tickets-next').addEventListener('click', () => shiftTicketsMonth(1));
  document.getElementById('btn-tickets-today').addEventListener('click', () => {
    const now = new Date();
    state.ticketsYear = now.getFullYear();
    state.ticketsMonth = now.getMonth();
    render();
  });
  document.getElementById('btn-export-tickets').addEventListener('click', exportTicketsCSV);
  document.getElementById('btn-fichier-commande-tickets').addEventListener('click', genererFichierCommandeTickets);

  document.querySelectorAll('[data-corriger-tickets]').forEach(btn => {
    btn.addEventListener('click', () => openCorrigerTicketsModal(btn.dataset.corrigerTickets));
  });
  document.querySelectorAll('[data-regulariser-auto-tickets]').forEach(btn => {
    btn.addEventListener('click', () => openCorrigerTicketsModal(btn.dataset.regulariserAutoTickets, Number(btn.dataset.ecart)));
  });
}

/** §retour Betty du 14/09/2026 (point 1, "fichier de commande mensuel") : export allégé, aux seuls
 * champs utiles pour déposer une commande chez un émetteur (Swile/Edenred/Up...) — contrairement à
 * exportTicketsCSV (comptabilité, tous les montants). Chaque émetteur a son propre format exact de
 * dépôt ; ce fichier couvre le socle commun (identité + nombre de titres), à adapter si besoin.
 * Enregistre aussi le nombre commandé pour CE mois (voir DB.enregistrerCommandeTickets) : c'est ce
 * qui permet ensuite de proposer une régularisation automatique si une absence est déclarée après. */
function genererFichierCommandeTickets() {
  const rows = getTicketsRows();
  const headers = ['Matricule', 'Nom', 'Prénom', 'Email', 'Nombre de titres'];
  const data = rows.map(r => [r.employee.matricule, r.employee.nom, r.employee.prenom, r.employee.email, r.result.nbTickets]);
  exportRowsToCSV(headers, data, `commande-tickets-restaurant-${state.ticketsYear}-${String(state.ticketsMonth + 1).padStart(2, '0')}.csv`);
  DB.enregistrerCommandeTickets(state.ticketsYear, state.ticketsMonth, leaveRepository.getAll(), teleworkRepository.getAll());
  showToast('Fichier de commande généré.');
  render();
}

function shiftTicketsMonth(delta) {
  let month = state.ticketsMonth + delta;
  let year = state.ticketsYear;
  if (month < 0) { month = 11; year -= 1; }
  if (month > 11) { month = 0; year += 1; }
  state.ticketsMonth = month;
  state.ticketsYear = year;
  render();
}

function exportTicketsCSV() {
  const rows = getTicketsRows();
  // §tour de bugs du 07/09/2026 : matricule manquant, même remarque que pour l'export Notes de
  // frais déjà corrigé — sans lui, un rapprochement comptable ne se fait qu'à l'œil par nom (risque
  // d'homonymes/changement de nom).
  const headers = ['Matricule', 'Salarié', 'Tickets', 'Montant total', 'Part employeur', 'Part salarié'];
  // §retour Betty du 18/09/2026 (point 7) : montants en vrai nombre, jamais formatNumberFR (un texte
  // aligné à gauche) — voir excelXmlCell.
  const data = rows.map(r => [
    r.employee.matricule,
    `${r.employee.prenom} ${r.employee.nom}`,
    r.result.nbTickets,
    r.result.montantTotal,
    r.result.partEmployeur,
    r.result.partSalarie
  ]);
  exportRowsToCSV(headers, data, `tickets-restaurant-${state.ticketsYear}-${String(state.ticketsMonth + 1).padStart(2, '0')}.csv`);
  auditLogRepository.logAudit('Export', 'Tickets restaurant', `${MONTH_NAMES[state.ticketsMonth]} ${state.ticketsYear}`);
}

// ---------------------------------------------------------------------------
// Vue : Export paie — consolidation mensuelle congés / télétravail / tickets / frais
// ---------------------------------------------------------------------------

// Valeur neutre pour la colonne "Tickets restaurant" quand le module n'est pas souscrit — mêmes
// champs que calculateTicketsRestaurant (data.js), pour que l'appelant n'ait jamais besoin de
// distinguer les deux cas.
const ZERO_TICKETS_RESULT = { nbTickets: 0, montantTotal: 0, partEmployeur: 0, partSalarie: 0, ajustement: 0 };

function getPaieRows(year, month) {
  const monthStr = `${year}-${String(month + 1).padStart(2, '0')}`;
  const monthStart = `${monthStr}-01`;
  const monthEnd = toISODate(new Date(year, month + 1, 0));
  // Filtre sur la période d'emploi DU MOIS EXPORTÉ, pas sur le statut actuel du salarié : un export
  // paie peut porter sur un mois passé, où un salarié aujourd'hui "Inactif"/déjà parti était encore
  // présent — le filtrer sur son statut live lui aurait fait perdre toutes ses données de ce mois-là
  // (congés, télétravail, notes de frais), pas seulement les jours après son départ.
  const employees = employeeRepository.getAll().filter(e => !e.archive && isEmployedDuringPeriod(e, monthStart, monthEnd));
  const leaveTypes = leaveTypeRepository.getLeaveTypes();
  // §retour Betty du 17/09/2026 (audit "millimètre par millimètre") : "Préparation de paie" n'exige
  // que le module RH (NAV_ITEMS 'export-paie') — sans ce cloisonnement, une entreprise abonnée à RH
  // seul (sans congés/planning/frais/tickets) voyait ici de VRAIES données personnelles de ces
  // modules jamais souscrits (jours de congé réels, montants de notes de frais...), pas seulement des
  // boutons ou libellés d'aperçu comme dans les autres correctifs de cet audit. Coupé à la source,
  // comme pour buildCalendarSharedData : chaque champ redevient 0/vide plutôt que d'être recalculé
  // avec de vraies données, aussi bien ici que dans getPaieAnomalies juste plus bas.
  const leaveTypesExportables = hasModule('conges') ? leaveTypes.filter(t => t.exportPaie) : [];
  // Sprint SIRH premium §6 (Préparation de paie) : buckets fixes par nom de type, indépendants du
  // réglage "export paie" par type — le récapitulatif doit montrer les vraies données de congés/RTT/
  // maladie même si RH n'a pas coché ces types pour la colonne CSV (même principe que
  // calculateAbsenteeismRate, qui identifie déjà "Maladie" par son nom).
  const congesPayesTypeIds = getLeaveTypeIdsByName(leaveTypes, 'Congés payés');
  const rttTypeIds = getLeaveTypeIdsByName(leaveTypes, 'RTT');
  const maladieTypeIds = getLeaveTypeIdsByName(leaveTypes, 'Maladie');
  const leaveRequests = hasModule('conges') ? leaveRepository.getAll().filter(r => r.statut === 'Validé') : [];
  const teleworkRequests = hasModule('planning') ? teleworkRepository.getAll().filter(r => r.statut === 'Validé') : [];
  const expenses = hasModule('frais') ? expenseRepository.getAll().filter(n => n.statut === 'Remboursé') : [];
  const settings = settingsRepository.getSettings();

  return employees.map(e => {
    // §7.9 : chaque demande recompte selon l'unité DE SON PROPRE TYPE (pas forcément la même pour
    // toutes les typeIds passées ici, ex. congesPayesTypeIds pourrait couvrir plusieurs types du
    // même nom avec des réglages différents).
    const sumTypeIdsInMonth = (typeIds) => leaveRequests
      .filter(r => r.employeeId === e.id && typeIds.includes(r.typeId))
      .reduce((sum, r) => sum + countRequestDaysInMonth(r.dateDebut, r.dateFin, r.demiJournee, year, month, e, settings, (leaveTypes.find(t => t.id === r.typeId) || {}).uniteDecompte), 0);

    const congesParType = leaveTypesExportables.map(t => sumTypeIdsInMonth([t.id]));

    const teletravailJours = teleworkRequests
      .filter(r => r.employeeId === e.id)
      .reduce((sum, r) => sum + countRequestDaysInMonth(r.dateDebut, r.dateFin, false, year, month, e, settings), 0);

    const notesRembourser = expenses
      .filter(n => n.employeeId === e.id && getExpensePayableMonthKey(n) === monthStr)
      .reduce((sum, n) => sum + n.montantTTC, 0);

    return {
      employee: e,
      congesParType,
      teletravailJours,
      tickets: hasModule('tickets') ? calculateTicketsRestaurant(e, year, month, leaveRequests, teleworkRequests, settings) : ZERO_TICKETS_RESULT,
      notesRembourser,
      congesPayesJours: sumTypeIdsInMonth(congesPayesTypeIds),
      rttJours: sumTypeIdsInMonth(rttTypeIds),
      maladieJours: sumTypeIdsInMonth(maladieTypeIds),
      // Sprint SIRH premium §6 : "Variables" du récapitulatif — saisie manuelle par mois (aucun
      // module ne les calcule automatiquement, cf. DB.ajusterVariablesPaie), même principe que
      // ticketsAjustements.
      variablesMontant: (e.variablesPaie && e.variablesPaie[`${year}-${String(month + 1).padStart(2, '0')}`]) || 0,
      // Heures supplémentaires du mois — même principe, aucun module de pointage ne les détecte
      // automatiquement (voir DB.ajusterHeuresSupplementaires).
      heuresSupHeures: (e.heuresSupplementaires && e.heuresSupplementaires[monthStr]) || 0,
      // §retour QA du 26/08/2026 (point 7.21) : heures de repos compensateur prises ce mois, même
      // principe (voir DB.ajusterReposCompensateurPris).
      reposCompensateurPrisHeures: (e.reposCompensateurPris && e.reposCompensateurPris[monthStr]) || 0
    };
  });
}

/** §retour Betty du 07/09/2026 (point 14) : verrou commercial signalé — un client abonné à Congés ET
 * Notes de frais produit déjà cette donnée chez nous mais doit payer le module RH pour la sortir
 * vers sa paie. Plutôt que de retirer la restriction sur "Préparation de paie" (qui agrège AUSSI des
 * données propres au module RH — salaire, heures sup, indemnités, complétude du dossier), cet export
 * séparé et volontairement léger réutilise getPaieRows (mêmes calculs, aucune duplication) mais
 * n'expose QUE les colonnes congés/frais — jamais les colonnes RH — et n'exige donc jamais le module
 * RH. Gated sur voirSalaries (vision entreprise) plutôt que le rôle : cohérent avec le reste du
 * fichier, qui ne code plus de rôle en dur (voir le correctif du point 8 juste au-dessus).
 */
function canExportCongesFraisMoisLeger(user) {
  return hasPermission(user, PERMISSIONS.VOIR_SALARIES) && !hasModule('rh') && (hasModule('conges') || hasModule('frais'));
}

function exportCongesFraisMoisCSV() {
  const now = new Date();
  const year = now.getFullYear();
  const month = now.getMonth();
  const rows = getPaieRows(year, month);
  const headers = ['Matricule', 'Nom', 'Prénom', 'Congés payés (jours)', 'RTT (jours)', 'Notes de frais remboursées (€)'];
  // §retour Betty du 18/09/2026 (point 7) : vrais nombres, jamais formatNumberFR — voir excelXmlCell.
  const data = rows.map(r => [
    r.employee.matricule, r.employee.nom, r.employee.prenom,
    r.congesPayesJours, r.rttJours, r.notesRembourser
  ]);
  exportRowsToCSV(headers, data, `conges-frais-${MONTH_NAMES[month]}-${year}.csv`);
  auditLogRepository.logAudit('Export', 'Congés + Notes de frais (export léger)', `${rows.length} ligne${rows.length > 1 ? 's' : ''} — ${MONTH_NAMES[month]} ${year}`);
  showToast('Export téléchargé.');
}

/** Sprint SIRH premium §6 : anomalies à vérifier avant de lancer l'export paie du mois — Bloquantes
 * (fausserait un calcul de paie : solde négatif, dates hors période contractuelle), Avertissements
 * (risque qualité/légal mais qui ne fausse rien : justificatif manquant, données administratives
 * incomplètes), Informations (à connaître, pas une erreur : contrat qui se termine ce mois-ci). */
function getPaieAnomalies(year, month) {
  const monthStr = `${year}-${String(month + 1).padStart(2, '0')}`;
  const monthStart = `${monthStr}-01`;
  const monthEnd = toISODate(new Date(year, month + 1, 0));
  const employees = employeeRepository.getAll().filter(e => !e.archive && isEmployedDuringPeriod(e, monthStart, monthEnd));
  const leaveTypes = leaveTypeRepository.getLeaveTypes();
  // §retour Betty du 17/09/2026 (audit "millimètre par millimètre") : mêmes correctif et raison que
  // dans getPaieRows juste au-dessus — "Préparation de paie" n'exige que le module RH, mais ces
  // anomalies (solde négatif, absence incohérente, justificatif manquant) portent sur de VRAIES
  // données congés/planning, jamais vérifiées avant. Coupé à la source.
  const allLeaveRequests = hasModule('conges') ? leaveRepository.getAll() : [];
  const validLeaveRequests = allLeaveRequests.filter(r => r.statut === 'Validé');
  const validTeleworkRequests = hasModule('planning') ? teleworkRepository.getAll().filter(r => r.statut === 'Validé') : [];

  const isWithinEmploymentPeriod = (e, dateDebut, dateFin) =>
    Boolean(e.dateEmbauche) && dateDebut >= e.dateEmbauche && (!e.dateDepart || dateFin <= e.dateDepart);
  // "Absence incohérente"/"justificatif manquant" ne portent que sur les demandes qui chevauchent le
  // mois affiché : sans ça, une vieille donnée jamais corrigée resterait signalée indéfiniment sur
  // TOUS les mois futurs, noyant l'écran de préparation dans du bruit sans rapport avec la paie en cours.
  const overlapsMonth = (dateDebut, dateFin) => dateDebut <= monthEnd && dateFin >= monthStart;
  // Hoistés hors de la boucle par salarié : ne dépendent pas de `e`, recalculer/reconcaténer à
  // chaque itération serait du travail identique refait pour rien.
  const congeTypesFinis = leaveTypes.filter(t => t.categorie === 'conge' && t.acquisition !== 'Illimitée');
  const validLeaveAndTeleworkRequests = validLeaveRequests.concat(validTeleworkRequests);

  // §correctif audit du 31/08/2026 (efficiency) : les 3 lignes ci-dessous étaient chacune un
  // .filter(r => r.employeeId === e.id) sur la liste COMPLÈTE de l'entreprise, refait à CHAQUE
  // salarié (getLeaveBalance en plus rescanne pareil en interne, voir son commentaire) — un
  // regroupement par employeeId une seule fois ici transforme ces scans répétés en lookups directs.
  const groupByEmployeeId = (list) => {
    const map = new Map();
    list.forEach(r => {
      if (!map.has(r.employeeId)) map.set(r.employeeId, []);
      map.get(r.employeeId).push(r);
    });
    return map;
  };
  const allLeaveRequestsByEmployeeId = groupByEmployeeId(allLeaveRequests);
  const validLeaveAndTeleworkRequestsByEmployeeId = groupByEmployeeId(validLeaveAndTeleworkRequests);
  const validLeaveRequestsByEmployeeId = groupByEmployeeId(validLeaveRequests);

  const anomalies = [];
  employees.forEach(e => {
    const employeeLeaveRequests = allLeaveRequestsByEmployeeId.get(e.id) || [];
    congeTypesFinis.forEach(t => {
      const balance = getLeaveBalance(e, t, employeeLeaveRequests, leaveTypes, monthEnd);
      if (balance.disponible < 0) {
        anomalies.push({ severity: 'bloquante', type: 'compteur_negatif', employee: e, message: `Solde "${t.nom}" négatif : ${formatDurationFR(balance.disponible)}` });
      }
    });

    (validLeaveAndTeleworkRequestsByEmployeeId.get(e.id) || []).filter(r => overlapsMonth(r.dateDebut, r.dateFin)).forEach(r => {
      if (!isWithinEmploymentPeriod(e, r.dateDebut, r.dateFin)) {
        anomalies.push({ severity: 'bloquante', type: 'absence_incoherente', employee: e, message: `Demande du ${formatDate(r.dateDebut)} au ${formatDate(r.dateFin)} en dehors de la période contractuelle` });
      }
    });

    (validLeaveRequestsByEmployeeId.get(e.id) || []).filter(r => overlapsMonth(r.dateDebut, r.dateFin)).forEach(r => {
      const type = leaveTypes.find(t => t.id === r.typeId);
      if (type && type.justificatifObligatoire && !r.justificatif) {
        anomalies.push({ severity: 'avertissement', type: 'justificatif_manquant', employee: e, message: `Justificatif manquant pour "${type.nom}" du ${formatDate(r.dateDebut)}` });
      }
    });

    const champsManquants = [];
    if (!e.numeroSecu) champsManquants.push('n° sécurité sociale');
    if (!e.salaireBrutMensuel) champsManquants.push('salaire brut mensuel');
    if (!e.matricule) champsManquants.push('matricule');
    if (champsManquants.length) {
      anomalies.push({ severity: 'avertissement', type: 'donnees_incompletes', employee: e, message: `Données manquantes : ${champsManquants.join(', ')}` });
    }

    if (e.dateDepart && e.dateDepart >= monthStart && e.dateDepart <= monthEnd) {
      anomalies.push({ severity: 'information', type: 'contrat_termine', employee: e, message: `Contrat terminé le ${formatDate(e.dateDepart)} — dernier mois de paie` });
      // §correctif audit du 23/08/2026 (§7.20) : signale l'indemnité compensatrice ESTIMÉE ici aussi
      // (pas seulement dans la fiche salarié) — la Préparation de paie est l'écran où ce montant a
      // le plus de chances d'être effectivement vu au bon moment, le mois du départ.
      const { montant, joursRestants } = calculateIndemniteCompensatrice(e, e.dateDepart);
      if (joursRestants > 0) {
        anomalies.push({ severity: 'information', type: 'indemnite_compensatrice', employee: e, message: `Indemnité compensatrice de congés payés estimée : ${formatCurrencyFR(montant)} (${formatDurationFR(joursRestants)} non pris) — à valider avec votre expert-comptable` });
      }
    }

    // §correctif audit du 23/08/2026 (§7.21) : indemnité d'astreinte due sur le mois affiché, pour
    // qu'elle soit vue au bon moment plutôt que de dépendre de quelqu'un qui consulte la fiche du
    // salarié un par un — montant somme des périodes qui chevauchent le mois (une période à cheval
    // sur deux mois compte sur les deux, elle n'est pas prorata-temporisée : le montant saisi est
    // celui de la période entière, à charge du gestionnaire de paie de répartir si besoin).
    const astreintesDuMois = getAstreintesOverlapping(e, monthStart, monthEnd);
    const indemniteAstreinte = astreintesDuMois.reduce((sum, a) => sum + (a.indemniteMontant || 0), 0);
    if (indemniteAstreinte > 0) {
      anomalies.push({ severity: 'information', type: 'indemnite_astreinte', employee: e, message: `Indemnité d'astreinte à verser : ${formatCurrencyFR(indemniteAstreinte)} (${astreintesDuMois.length} période${astreintesDuMois.length > 1 ? 's' : ''})` });
    }
  });

  return anomalies;
}

/** Sprint SIRH premium §6 : "Préparation de paie" — étape de relecture des anomalies avant
 * l'export, désormais un onglet de l'écran existant (state.paieTab) plutôt qu'un nouvel écran, pour
 * rester sur le même point d'entrée sidebar/permission (EXPORTER_PAIE) déjà en place. Le bouton
 * "Exporter CSV" de l'onglet Export reste volontairement TOUJOURS actif même s'il existe des
 * anomalies bloquantes : un blocage technique dur serait risqué en production (faux positif un jour
 * de paie) — la relecture est mise en avant (onglet par défaut, bannière), pas mécaniquement forcée. */
function renderExportPaie() {
  const rows = getPaieRows(state.paieYear, state.paieMonth);
  const tab = state.paieTab || 'preparation';

  return `
    <div class="view-header view-header-row">
      <div>
        <h1>Préparation de paie</h1>
        <p class="view-subtitle">${MONTH_NAMES[state.paieMonth]} ${state.paieYear} · ${rows.length} salarié${rows.length > 1 ? 's' : ''}</p>
      </div>
      <div class="detail-header-actions">
        <button class="btn btn-secondary btn-sm" id="btn-paie-prev">← Précédent</button>
        <button class="btn btn-secondary btn-sm" id="btn-paie-today">Ce mois-ci</button>
        <button class="btn btn-secondary btn-sm" id="btn-paie-next">Suivant →</button>
        ${tab === 'export' ? '<button class="btn btn-secondary" id="btn-export-paie">Exporter CSV</button>' : ''}
      </div>
    </div>
    <div class="tabs" style="margin-bottom: 10px;">
      <button class="tab ${tab === 'preparation' ? 'active' : ''}" data-paie-tab="preparation">Préparation &amp; anomalies</button>
      <button class="tab ${tab === 'export' ? 'active' : ''}" data-paie-tab="export">Export CSV</button>
    </div>
    ${tab === 'export' ? renderExportPaieExportTab(rows) : renderExportPaiePreparationTab(rows)}
  `;
}

function renderPaieAnomalyBadges(anomaliesForEmployee) {
  if (!anomaliesForEmployee.length) return '<span class="text-muted">—</span>';
  const counts = { bloquante: 0, avertissement: 0, information: 0 };
  anomaliesForEmployee.forEach(a => counts[a.severity]++);
  return [
    counts.bloquante ? `<span class="badge badge-danger">${counts.bloquante} bloquante${counts.bloquante > 1 ? 's' : ''}</span>` : '',
    counts.avertissement ? `<span class="badge badge-warning">${counts.avertissement} avert.</span>` : '',
    counts.information ? `<span class="badge badge-info">${counts.information} info</span>` : ''
  ].filter(Boolean).join(' ');
}

function renderExportPaiePreparationTab(rows) {
  const anomalies = getPaieAnomalies(state.paieYear, state.paieMonth);
  const bloquantes = anomalies.filter(a => a.severity === 'bloquante');
  const avertissements = anomalies.filter(a => a.severity === 'avertissement');
  const informations = anomalies.filter(a => a.severity === 'information');

  const anomalySection = (title, list, badgeClass) => !list.length ? '' : `
    <div class="card" style="margin-bottom: 12px;">
      <h3 style="margin-bottom: 8px;">${title} <span class="badge ${badgeClass}">${list.length}</span></h3>
      <ul class="anomaly-list">
        ${list.map(a => `<li><strong>${personNameHtml(a.employee)}</strong> — ${escapeHtml(a.message)}</li>`).join('')}
      </ul>
    </div>
  `;

  return `
    ${!anomalies.length ? `
      <div class="card" style="text-align: center; padding: 24px;">
        <div style="font-size: 32px; display: flex; align-items: center; justify-content: center;">${icon(ICONS.checkCircle, 32)}</div>
        <p>Aucune anomalie détectée pour ${MONTH_NAMES[state.paieMonth]} ${state.paieYear}. Prêt pour l'export.</p>
      </div>
    ` : `
      ${anomalySection(`${icon(ICONS.block, 15)} Bloquantes, à corriger avant export`, bloquantes, 'badge-danger')}
      ${anomalySection(`${icon(ICONS.warningTriangle, 15)} Avertissements`, avertissements, 'badge-warning')}
      ${anomalySection(`${icon(ICONS.info, 15)} Informations`, informations, 'badge-info')}
    `}

    <div class="card table-card">
      <h3 style="padding: 14px 14px 0;">Récapitulatif par salarié</h3>
      ${!rows.length ? `<div class="empty-state"><div class="empty-icon">${ICONS.receipt}</div><p>Aucun salarié pour ce mois.</p></div>` : `
        <table class="table table-nowrap">
          <thead>
            <tr>
              <th>Salarié</th>
              ${hasModule('conges') ? '<th class="cell-numeric">Congés payés</th><th class="cell-numeric">RTT</th><th class="cell-numeric">Maladie</th>' : ''}
              ${hasModule('planning') ? '<th class="cell-numeric">Télétravail</th>' : ''}
              ${hasModule('frais') ? '<th class="cell-numeric">Notes de frais</th>' : ''}
              <th class="cell-numeric">Variables</th>
              <th class="cell-numeric">Heures sup</th>
              <th class="cell-numeric">Repos comp. pris</th>
              ${hasModule('tickets') ? '<th class="cell-numeric">Tickets restaurant</th>' : ''}
              <th>Anomalies</th>
            </tr>
          </thead>
          <tbody>
            ${rows.map(r => `
              <tr>
                <td>${personNameHtml(r.employee)}</td>
                ${hasModule('conges') ? `<td class="cell-numeric">${formatDurationFR(r.congesPayesJours)}</td><td class="cell-numeric">${formatDurationFR(r.rttJours)}</td><td class="cell-numeric">${formatDurationFR(r.maladieJours)}</td>` : ''}
                ${hasModule('planning') ? `<td class="cell-numeric">${formatDurationFR(r.teletravailJours)}</td>` : ''}
                ${hasModule('frais') ? `<td class="cell-numeric">${formatCurrencyFR(r.notesRembourser)}</td>` : ''}
                <td class="cell-numeric">${formatCurrencyFR(r.variablesMontant)} <button type="button" class="btn-link" data-adjust-variables="${r.employee.id}" title="Ajuster les variables de paie">${icon(ICONS.pencil, 13)}</button></td>
                <td class="cell-numeric">${formatNumberFR(r.heuresSupHeures)} h <button type="button" class="btn-link" data-adjust-heures-sup="${r.employee.id}" title="Ajuster les heures supplémentaires">${icon(ICONS.pencil, 13)}</button></td>
                <td class="cell-numeric">${formatNumberFR(r.reposCompensateurPrisHeures)} h <button type="button" class="btn-link" data-adjust-repos-compensateur="${r.employee.id}" title="Ajuster le repos compensateur pris">${icon(ICONS.pencil, 13)}</button></td>
                ${hasModule('tickets') ? `<td class="cell-numeric">${r.tickets.nbTickets}</td>` : ''}
                <td>${renderPaieAnomalyBadges(anomalies.filter(a => a.employee.id === r.employee.id))}</td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      `}
    </div>
  `;
}

function renderExportPaieExportTab(rows) {
  const settings = settingsRepository.getSettings();
  const modele = settings.exportPaieModele || 'generique';
  const colonnes = settings.exportPaieColonnes || { conges: true, teletravail: true, tickets: true, frais: true };
  // §retour Betty du 17/09/2026 (audit "millimètre par millimètre") : le module reste prioritaire sur
  // la personnalisation — un module non souscrit n'a jamais de vraie donnée à exporter (voir
  // getPaieRows, déjà coupé à la source), inutile de laisser la case "personnalisé" la faire
  // réapparaître dans le fichier envoyé au logiciel de paie.
  const COLONNE_MODULE = { conges: 'conges', teletravail: 'planning', tickets: 'tickets', frais: 'frais' };
  const showColonne = (key) => hasModule(COLONNE_MODULE[key]) && (modele !== 'personnalise' || colonnes[key]);
  const leaveTypesExportables = showColonne('conges') ? leaveTypeRepository.getLeaveTypes().filter(t => t.exportPaie) : [];

  return `
    <div class="card">
      <p class="text-muted">Consolide, pour la paie du mois, les congés marqués « export paie » (paramétrable dans Congés → Types), le télétravail, les tickets restaurant et les notes de frais validées à rembourser.</p>
      <div class="form-grid" style="margin-top: 10px;">
        <div class="form-field">
          <label for="f-export-paie-modele">Modèle d'export (§34)</label>
          <select class="input" id="f-export-paie-modele">
            ${Object.entries(EXPORT_PAIE_MODELES).map(([key, m]) => `<option value="${key}" ${modele === key ? 'selected' : ''}>${escapeHtml(m.label)}</option>`).join('')}
          </select>
        </div>
      </div>
      <p class="text-muted" style="margin-top: 8px;">${icon(ICONS.warningTriangle, 14)} Ces modèles fixent une convention de délimiteur courante mais ne garantissent pas une compatibilité exacte avec votre paramétrage réel : les formats d'import Sage/Silae/Cegid/ADP/PayFit sont propres à chaque client et à chaque version. Vérifiez et adaptez avant toute utilisation en production.</p>
      ${modele === 'personnalise' ? `
        <div class="form-grid" style="margin-top: 12px;">
          ${hasModule('conges') ? checkboxField('paieCol.conges', 'Congés', colonnes.conges) : ''}
          ${hasModule('planning') ? checkboxField('paieCol.teletravail', 'Télétravail', colonnes.teletravail) : ''}
          ${hasModule('tickets') ? checkboxField('paieCol.tickets', 'Tickets restaurant', colonnes.tickets) : ''}
          ${hasModule('frais') ? checkboxField('paieCol.frais', 'Notes de frais', colonnes.frais) : ''}
        </div>
      ` : ''}
    </div>

    <div class="card table-card">
      ${rows.length === 0 ? `<div class="empty-state"><div class="empty-icon">${ICONS.upload}</div><p>Aucun salarié à exporter pour ce mois.</p></div>` : `
        <table class="table">
          <thead>
            <tr>
              <th>Matricule</th>
              <th>Salarié</th>
              ${leaveTypesExportables.map(t => `<th>${escapeHtml(t.nom)}</th>`).join('')}
              ${showColonne('teletravail') ? '<th>Télétravail</th>' : ''}
              ${showColonne('tickets') ? '<th>Tickets resto</th><th>Part salarié tickets</th>' : ''}
              ${showColonne('frais') ? '<th>Frais à rembourser</th>' : ''}
              <th>Variables</th>
              <th>Heures sup</th>
              <th>Repos comp. pris</th>
            </tr>
          </thead>
          <tbody>
            ${rows.map(r => `
              <tr>
                <td>${escapeHtml(r.employee.matricule)}</td>
                <td>${personNameHtml(r.employee)}</td>
                ${showColonne('conges') ? r.congesParType.map(j => `<td>${formatDurationFR(j)}</td>`).join('') : ''}
                ${showColonne('teletravail') ? `<td>${formatDurationFR(r.teletravailJours)}</td>` : ''}
                ${showColonne('tickets') ? `<td>${r.tickets.nbTickets}</td><td>${formatCurrencyFR(r.tickets.partSalarie)}</td>` : ''}
                ${showColonne('frais') ? `<td>${formatCurrencyFR(r.notesRembourser)}</td>` : ''}
                <td>${formatCurrencyFR(r.variablesMontant)}</td>
                <td>${formatNumberFR(r.heuresSupHeures)} h</td>
                <td>${formatNumberFR(r.reposCompensateurPrisHeures)} h</td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      `}
    </div>
  `;
}

function bindExportPaieEvents() {
  document.getElementById('btn-paie-prev').addEventListener('click', () => shiftPaieMonth(-1));
  document.getElementById('btn-paie-next').addEventListener('click', () => shiftPaieMonth(1));
  document.getElementById('btn-paie-today').addEventListener('click', () => {
    const now = new Date();
    state.paieYear = now.getFullYear();
    state.paieMonth = now.getMonth();
    render();
  });

  document.querySelectorAll('[data-paie-tab]').forEach(btn => {
    btn.addEventListener('click', () => { state.paieTab = btn.dataset.paieTab; render(); });
  });

  const exportBtn = document.getElementById('btn-export-paie');
  if (exportBtn) exportBtn.addEventListener('click', handleExportPaieClick);

  const modeleSelect = document.getElementById('f-export-paie-modele');
  if (modeleSelect) modeleSelect.addEventListener('change', (e) => {
    const settings = settingsRepository.getSettings();
    settings.exportPaieModele = e.target.value;
    settingsRepository.saveSettings(settings);
    render();
  });

  ['conges', 'teletravail', 'tickets', 'frais'].forEach(key => {
    const checkbox = document.getElementById(`f-paieCol.${key}`);
    if (checkbox) checkbox.addEventListener('change', (e) => {
      const settings = settingsRepository.getSettings();
      settings.exportPaieColonnes = Object.assign({}, settings.exportPaieColonnes, { [key]: e.target.checked });
      settingsRepository.saveSettings(settings);
      render();
    });
  });

  document.querySelectorAll('[data-adjust-variables]').forEach(btn => {
    btn.addEventListener('click', () => openVariablesPaieModal(btn.dataset.adjustVariables));
  });

  document.querySelectorAll('[data-adjust-heures-sup]').forEach(btn => {
    btn.addEventListener('click', () => openHeuresSupModal(btn.dataset.adjustHeuresSup));
  });

  document.querySelectorAll('[data-adjust-repos-compensateur]').forEach(btn => {
    btn.addEventListener('click', () => openReposCompensateurPrisModal(btn.dataset.adjustReposCompensateur));
  });
}

/** Nouvel écran dédié (module "Rémunération" du compositeur à la carte de la landing, 14/08/2026) —
 * réutilise settings.masseSalarialeActivee/employee.salaireBrutMensuel, jusqu'ici affichés
 * uniquement comme un seul chiffre agrégé sur le tableau de bord Direction (renderDashboard) : le
 * réglage/la donnée existaient déjà, seul un vrai écran dédié manquait. */
// §"Radar Trésorerie RH" (roadmap différenciation #4, 01/09/2026) : les 90 jours englobent déjà les
// 60 et les 30 (horizons cumulatifs, pas des tranches disjointes) — la liste d'évènements n'est donc
// affichée qu'une fois, à partir de l'horizon le plus large, pour ne jamais dupliquer une même
// embauche/un même départ dans 2 ou 3 lignes identiques.
const RADAR_TRESORERIE_EVENT_LABELS = { embauche: 'Embauche prévue', depart: 'Départ prévu', indemnite_compensatrice: 'Indemnité compensatrice de CP' };

function renderRadarTresorerieCard(radar) {
  const dernierHorizon = radar.horizons[radar.horizons.length - 1];
  return `
    <div class="card">
      <h2>${icon(ICONS.trendingUp, 16)} Radar trésorerie RH</h2>
      <p class="text-muted" style="margin-top:-6px;">Impact prévisionnel des embauches/départs déjà planifiés sur la masse salariale mensuelle (coût actuel : ${formatCurrencyFR(radar.coutMensuelActuel)}).</p>
      <div class="kpi-grid" style="margin-top:12px;">
        ${radar.horizons.map(h => kpiCard(`Coût mensuel à ${h.jours} jours`, formatCurrencyFR(h.coutMensuelProjete), ICONS.coin)).join('')}
      </div>
      ${dernierHorizon.evenements.length ? `
        <div class="mini-list" style="margin-top:12px;">
          ${dernierHorizon.evenements.map(ev => `
            <div class="mini-list-item">
              <span>${escapeHtml(RADAR_TRESORERIE_EVENT_LABELS[ev.type] || ev.type)} · ${escapeHtml(ev.employee)} · ${formatDate(ev.date)}</span>
              <span class="text-muted">${ev.impactMensuel !== undefined ? `${ev.impactMensuel > 0 ? '+' : ''}${formatCurrencyFR(ev.impactMensuel)}/mois` : `${formatCurrencyFR(ev.montantUnique)} (sortie ponctuelle)`}</span>
            </div>
          `).join('')}
        </div>
      ` : `<p class="text-muted" style="margin-top:12px;">Aucune embauche ni départ planifié dans les 90 prochains jours.</p>`}
      <p class="form-hint" style="margin-top:10px;">Estimation à partir des salaires bruts mensuels renseignés (hors charges patronales, primes, variables de paie). Les congés payés ordinaires n'ont volontairement aucun effet ici : le salaire mensuel reste le même, présent ou en congé. À affiner avec votre expert-comptable pour un vrai pilotage de trésorerie.</p>
    </div>
  `;
}

function renderRemuneration() {
  const settings = settingsRepository.getSettings();
  if (!settings.masseSalarialeActivee) {
    return `
      <div class="view-header">
        <h1>Rémunération</h1>
      </div>
      <div class="empty-state">
        <p>Le suivi de la masse salariale n'est pas activé pour votre entreprise.</p>
        <button type="button" class="btn btn-primary" id="btn-activer-masse-salariale">Activer dans les paramètres</button>
      </div>
    `;
  }

  const employees = employeeRepository.getAll().filter(e => !e.archive);
  const renseignes = employees.filter(e => e.salaireBrutMensuel > 0).sort((a, b) => b.salaireBrutMensuel - a.salaireBrutMensuel);
  const nonRenseignes = employees.filter(e => !(e.salaireBrutMensuel > 0));
  const total = renseignes.reduce((sum, e) => sum + e.salaireBrutMensuel, 0);
  const moyenne = renseignes.length ? total / renseignes.length : 0;
  // §correctif audit du 16/09/2026 : sur un effectif pair, la médiane est la MOYENNE des deux
  // valeurs centrales, jamais l'une des deux prise seule (renseignes[n/2] sur un tri descendant
  // pointait systématiquement vers la plus basse des deux, sous-évaluant le KPI).
  const mediane = (() => {
    const n = renseignes.length;
    if (!n) return 0;
    const mid = Math.floor(n / 2);
    return n % 2 === 0
      ? round2((renseignes[mid - 1].salaireBrutMensuel + renseignes[mid].salaireBrutMensuel) / 2)
      : renseignes[mid].salaireBrutMensuel;
  })();

  return `
    <div class="view-header">
      <h1>Rémunération</h1>
      <p class="view-subtitle">${renseignes.length} salarié${renseignes.length > 1 ? 's' : ''} avec un salaire renseigné sur ${employees.length}</p>
      <div class="detail-header-actions">
        <button type="button" class="btn btn-secondary" id="btn-index-egalite-remuneration">${icon(ICONS.scale, 14)} Index égalité pro</button>
        <button type="button" class="btn btn-primary" id="btn-lancer-revision-salariale">Lancer une campagne de révision</button>
      </div>
    </div>
    <div class="kpi-grid">
      ${kpiCard('Masse salariale mensuelle', formatCurrencyFR(total), ICONS.coin)}
      ${kpiCard('Coût employeur complet (estimé)', formatCurrencyFR(calculerCoutEmployeurComplet(total, settings.tauxChargesPatronalesEstime)), ICONS.coin)}
      ${kpiCard('Salaire brut moyen', formatCurrencyFR(moyenne), ICONS.chart)}
      ${kpiCard('Salaire brut médian', formatCurrencyFR(mediane), ICONS.trendingUp)}
    </div>
    <p class="form-hint">Coût employeur estimé avec un taux de charges patronales de ${Math.round(settings.tauxChargesPatronalesEstime * 100)}% (Paramètres > Entreprise) — un ordre de grandeur, à affiner avec votre gestionnaire de paie. <button type="button" class="btn-link" id="btn-variables-paie-remuneration">Éléments variables du mois →</button></p>
    ${renderRevisionSalarialeCard()}
    ${renderRadarTresorerieCard(getRadarTresorerieRH(employees, new Date()))}
    <div class="card table-card">
      <table class="table">
        <thead>
          <tr><th>Salarié</th><th>Service</th><th>Salaire brut mensuel</th></tr>
        </thead>
        <tbody>
          ${renseignes.map(e => `
            <tr class="table-row" data-open-employee="${e.id}">
              <td>${escapeHtml(e.prenom + ' ' + e.nom)}</td>
              <td>${escapeHtml(e.service || '—')}</td>
              <td>${formatCurrencyFR(e.salaireBrutMensuel)}</td>
            </tr>
          `).join('')}
          ${nonRenseignes.map(e => `
            <tr class="table-row" data-open-employee="${e.id}">
              <td>${escapeHtml(e.prenom + ' ' + e.nom)}</td>
              <td>${escapeHtml(e.service || '—')}</td>
              <td class="text-muted">Non renseigné</td>
            </tr>
          `).join('')}
        </tbody>
      </table>
    </div>
  `;
}

/** §retour Betty du 14/09/2026 (Rémunération point 2, "campagne de révision annuelle") : une
 * proposition par salarié concerné, jamais appliquée au salaire tant qu'elle n'est pas validée
 * individuellement — voir DB.validerRevisionSalariale (data.js). */
function renderRevisionSalarialeCard() {
  const campagnes = revisionSalarialeRepository.getAll().filter(c => c.statut === 'active');
  if (!campagnes.length) return '';
  const employees = employeeRepository.getAll();
  return campagnes.map(c => {
    const total = (c.propositions || []).length;
    const validees = c.propositions.filter(p => p.statut === 'validee').length;
    const propositionsHtml = c.propositions.map(p => {
      const employee = employees.find(e => e.id === p.employeeId);
      if (!employee) return '';
      // §retour Betty du 14/09/2026 (Rémunération point 6, "lien avec les entretiens") : simple
      // rappel de contexte au moment de la décision — jamais une automatisation qui déciderait du
      // montant à la place du manager/RH.
      const dernierEntretien = entretienRepository.getForEmployee(p.employeeId)[0];
      return `
        <div class="mini-list-item" style="align-items:flex-start;">
          <span>
            <strong>${escapeHtml(employee.prenom + ' ' + employee.nom)}</strong>
            <span class="badge badge-${REVISION_STATUT_BADGE_CLASS[p.statut]}">${escapeHtml(REVISION_STATUT_LABELS[p.statut])}</span><br>
            ${formatCurrencyFR(p.salaireActuel)} → ${p.salairePropose != null ? formatCurrencyFR(p.salairePropose) : '<span class="text-muted">à proposer</span>'}
            ${p.motif ? `· ${escapeHtml(p.motif)}` : ''}
            ${dernierEntretien ? `<br><button type="button" class="btn-link" data-open-entretien="${dernierEntretien.id}">Dernier entretien du ${formatDate(dernierEntretien.datePrevue)}${dernierEntretien.besoinsFormation ? ' · besoin de formation identifié' : ''}</button>` : ''}
          </span>
          <span>
            ${p.statut !== 'validee' ? `<button type="button" class="btn-link" data-revision-action="proposer" data-campagne="${c.id}" data-employee="${p.employeeId}">${p.statut === 'en_attente' ? 'Proposer' : 'Modifier'}</button>` : ''}
            ${p.statut === 'proposee' ? `<button type="button" class="btn-link" data-revision-action="valider" data-campagne="${c.id}" data-employee="${p.employeeId}">Valider</button> <button type="button" class="btn-link" data-revision-action="refuser" data-campagne="${c.id}" data-employee="${p.employeeId}">Refuser</button>` : ''}
          </span>
        </div>
      `;
    }).join('');
    return `
      <div class="card" style="margin-bottom:16px;">
        <h2>${escapeHtml(c.nom)} <span class="text-muted" style="font-weight:400;">· ${validees}/${total} validées · échéance ${formatDate(c.dateLimite)}</span></h2>
        ${propositionsHtml}
      </div>
    `;
  }).join('');
}

function bindRemunerationEvents() {
  const activerBtn = document.getElementById('btn-activer-masse-salariale');
  if (activerBtn) activerBtn.addEventListener('click', () => navigateTo('parametres', { parametresTab: 'entreprise' }));
  const indexEgaliteBtn = document.getElementById('btn-index-egalite-remuneration');
  if (indexEgaliteBtn) indexEgaliteBtn.addEventListener('click', openIndexEgaliteModal);
  const variablesBtn = document.getElementById('btn-variables-paie-remuneration');
  if (variablesBtn) variablesBtn.addEventListener('click', () => navigateTo('export-paie', { paieTab: 'preparation' }));
  const lancerRevisionBtn = document.getElementById('btn-lancer-revision-salariale');
  if (lancerRevisionBtn) lancerRevisionBtn.addEventListener('click', openLancerRevisionSalarialeModal);
  document.querySelectorAll('[data-open-employee]').forEach(row => {
    row.addEventListener('click', () => navigateTo('employee-detail', { currentEmployeeId: row.dataset.openEmployee }));
  });
  document.querySelectorAll('[data-open-entretien]').forEach(el => {
    el.addEventListener('click', () => navigateTo('entretien-detail', { currentEntretienId: el.dataset.openEntretien }));
  });
  document.querySelectorAll('[data-revision-action]').forEach(btn => {
    btn.addEventListener('click', () => {
      const campagneId = btn.dataset.campagne;
      const employeeId = btn.dataset.employee;
      const action = btn.dataset.revisionAction;
      if (action === 'proposer') { openProposerRevisionModal(campagneId, employeeId); return; }
      if (action === 'valider') {
        openConfirm({
          title: 'Valider cette révision salariale ?',
          message: 'Le nouveau salaire brut mensuel sera appliqué immédiatement à la fiche du salarié et tracé dans son historique des salaires.',
          confirmLabel: 'Valider',
          onConfirm: () => {
            const result = revisionSalarialeRepository.valider(campagneId, employeeId);
            if (!result.success) { showToast(result.error, 'error'); return; }
            showToast('Révision validée et appliquée.');
            render();
          }
        });
        return;
      }
      if (action === 'refuser') {
        openConfirm({
          title: 'Refuser cette proposition ?',
          message: 'Le salaire du salarié restera inchangé.',
          confirmLabel: 'Refuser',
          danger: true,
          onConfirm: () => {
            revisionSalarialeRepository.refuser(campagneId, employeeId);
            showToast('Proposition refusée.');
            render();
          }
        });
      }
    });
  });
}

/** Modal de proposition/modification de montant — réutilisée tant que la proposition n'est pas
 * validée (voir DB.proposerRevisionSalariale, qui refuse toute modification après validation). */
function openProposerRevisionModal(campagneId, employeeId) {
  const campagne = revisionSalarialeRepository.getAll().find(c => c.id === campagneId);
  const proposition = campagne && (campagne.propositions || []).find(p => p.employeeId === employeeId);
  if (!campagne || !proposition) { showToast('Cette proposition n\'est plus disponible.', 'error'); return; }
  const employee = employeeRepository.getById(employeeId);
  const dernierEntretien = entretienRepository.getForEmployee(employeeId)[0];
  const html = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>Révision salariale — ${escapeHtml(employee ? employee.prenom + ' ' + employee.nom : '')}</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="revision-form">
        <div class="modal-body">
          <p class="text-muted">Salaire brut mensuel actuel : ${formatCurrencyFR(proposition.salaireActuel)}.</p>
          ${dernierEntretien ? `<p class="text-muted">Dernier entretien le ${formatDate(dernierEntretien.datePrevue)}${dernierEntretien.besoinsFormation ? ` — besoin de formation identifié : ${escapeHtml(dernierEntretien.besoinsFormation)}` : ''}.</p>` : ''}
          <div class="form-field">
            <label for="f-revision-montant">Nouveau salaire brut mensuel (€) *</label>
            <input class="input" type="number" step="0.01" id="f-revision-montant" value="${proposition.salairePropose != null ? proposition.salairePropose : proposition.salaireActuel}" required>
          </div>
          <div class="form-field" style="margin-top:12px;">
            <label for="f-revision-motif">Motif</label>
            <input class="input" type="text" id="f-revision-motif" value="${escapeHtml(proposition.motif || '')}" placeholder="Ex. atteinte des objectifs, alignement marché...">
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="submit" class="btn btn-primary">Enregistrer la proposition</button>
        </div>
      </form>
    </div>
  `;
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');
  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('revision-form').addEventListener('submit', (evt) => {
    evt.preventDefault();
    const montant = document.getElementById('f-revision-montant').value;
    const motif = document.getElementById('f-revision-motif').value.trim();
    const result = revisionSalarialeRepository.proposer(campagneId, employeeId, montant, motif);
    if (!result.success) { showToast(result.error, 'error'); return; }
    showToast('Proposition enregistrée.');
    closeModal();
    render();
  });
}

/** Population = tous les salariés actifs avec un salaire déjà renseigné (une révision sans salaire
 * de départ n'aurait pas de sens) — pas de découpage cadres/managers ici, contrairement aux
 * campagnes d'entretiens : une révision salariale annuelle est typiquement lancée pour tout le
 * monde à la fois, chaque proposition individuelle permettant déjà d'ajuster ou de refuser au cas
 * par cas. */
function openLancerRevisionSalarialeModal() {
  const renseignes = employeeRepository.getAll().filter(e => !e.archive && e.salaireBrutMensuel > 0);
  const html = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>Lancer une campagne de révision salariale</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="revision-campagne-form">
        <div class="modal-body">
          <p class="text-muted">${renseignes.length} salarié${renseignes.length > 1 ? 's' : ''} avec un salaire renseigné seront concerné${renseignes.length > 1 ? 's' : ''}.</p>
          <div class="form-field"><label for="f-revision-campagne-nom">Nom de la campagne</label><input class="input" type="text" id="f-revision-campagne-nom" placeholder="Ex. Révision annuelle 2026" required></div>
          <div class="form-grid" style="margin-top:12px;">
            <div class="form-field"><label for="f-revision-campagne-annee">Année de référence</label><input class="input" type="number" id="f-revision-campagne-annee" value="${new Date().getFullYear()}" required></div>
            <div class="form-field"><label for="f-revision-campagne-date">Échéance</label><input class="input" type="date" id="f-revision-campagne-date" required></div>
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="submit" class="btn btn-primary">Lancer</button>
        </div>
      </form>
    </div>
  `;
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');
  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('revision-campagne-form').addEventListener('submit', (evt) => {
    evt.preventDefault();
    const nom = document.getElementById('f-revision-campagne-nom').value.trim();
    if (!nom) { showToast('Indiquez un nom.', 'error'); return; }
    const anneeReference = document.getElementById('f-revision-campagne-annee').value;
    const dateLimite = document.getElementById('f-revision-campagne-date').value;
    if (!dateLimite) { showToast('Indiquez une échéance.', 'error'); return; }
    const employeeIds = renseignes.map(e => e.id);
    const result = revisionSalarialeRepository.lancer(nom, anneeReference, dateLimite, employeeIds);
    if (!result.success) { showToast(result.error, 'error'); return; }
    closeModal();
    showToast(`Campagne lancée : ${employeeIds.length} salarié(s) concerné(s).`);
    render();
  });
}

/** Sprint SIRH premium §6 : "Variables" du récapitulatif de paie — aucun module ne les calcule
 * (primes/heures sup ponctuelles), saisie manuelle par mois, même modale que "Corriger les tickets"
 * (openCorrigerTicketsModal) mais un montant en euros plutôt qu'un nombre entier de tickets. */
function openVariablesPaieModal(employeeId) {
  const employee = employeeRepository.getById(employeeId);
  if (!employee) { showToast('Ce salarié n\'est plus disponible.', 'error'); return; }
  const year = state.paieYear;
  const month = state.paieMonth;
  const monthKey = `${year}-${String(month + 1).padStart(2, '0')}`;
  const current = (employee.variablesPaie && employee.variablesPaie[monthKey]) || 0;

  const html = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>Variables de paie — ${MONTH_NAMES[month]} ${year}</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="variables-paie-form">
        <div class="modal-body">
          <p class="text-muted">${personNameHtml(employee)} — primes, heures supplémentaires ou autre élément variable ponctuel pour ce mois (€). Remplace le montant précédemment saisi pour ce même mois.</p>
          <div class="form-field">
            <label for="f-montant">Montant (€) *</label>
            <input class="input" type="number" id="f-montant" name="montant" step="0.01" value="${current}" required>
          </div>
          <div class="form-field" style="margin-top: 12px;">
            <label for="f-motif">Motif</label>
            <input class="input" type="text" id="f-motif" name="motif" placeholder="Ex. prime exceptionnelle">
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="submit" class="btn btn-primary">Enregistrer</button>
        </div>
      </form>
    </div>
  `;

  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');

  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('variables-paie-form').addEventListener('submit', (evt) => {
    evt.preventDefault();
    const montant = document.getElementById('f-montant').value;
    const motif = document.getElementById('f-motif').value;
    const result = employeeRepository.ajusterVariables(employeeId, year, month, montant, motif);
    if (!result.success) { showToast(result.error, 'error'); return; }
    showToast('Variables de paie enregistrées.');
    closeModal();
    render();
  });
}

