// §retour Betty du 14/09/2026 (Embauche point 1, "suivi par étapes réel") : deux étapes
// intermédiaires ajoutées entre le dépôt et la décision finale (voir set_candidature_statut,
// 0055_embauche_pipeline_retention.sql) — reste volontairement un pipeline SIMPLE, pas un ATS
// complet (scoring, entretiens multiples...), cohérent avec l'analyse concurrentielle du 14/08/2026.
const CANDIDATURE_STATUT_LABELS = { nouvelle: 'Nouvelle', entretien: 'Entretien', offre: 'Offre', embauchee: 'Embauchée', archivee: 'Archivée' };
const CANDIDATURE_STATUT_BADGE_CLASS = { nouvelle: 'badge-info', entretien: 'badge-warning', offre: 'badge-warning', embauchee: 'badge-success', archivee: 'badge-muted' };
// nouvelle → entretien → offre : un simple changement de statut, réversible en un clic. offre →
// embauchee/archivee n'apparaît jamais ici : ces deux transitions ont une vraie conséquence
// (création de la fiche salarié, email au candidat) et passent par leurs propres boutons dédiés
// dans le détail de la candidature (Embaucher / Pas intéressé), jamais un simple "avancer".
const CANDIDATURE_STATUT_NEXT = { nouvelle: 'entretien', entretien: 'offre' };

/** URL publique de candidature pour cette entreprise — ?candidature=<companyId>, détecté tout en
 * haut de DOMContentLoaded (avant même DB.init()) pour router vers renderCandidatureForm(). */
function candidatureUrlForCompany(companyId) {
  return `${window.location.origin}${window.location.pathname.replace(/[^/]*$/, '')}?candidature=${encodeURIComponent(companyId)}`;
}

/** §retour Betty du 14/09/2026 (Embauche point 2, "page carrière publique") : jusqu'ici, aucune
 * page ne listait les postes ouverts — seul le formulaire de candidature existait (avec les postes
 * en simples cases à cocher). Cette page liste les postes un par un et renvoie vers ce même
 * formulaire, avec le poste déjà présélectionné (voir ?poste= ci-dessous et renderCandidatureForm). */
function carriereUrlForCompany(companyId) {
  return `${window.location.origin}${window.location.pathname.replace(/[^/]*$/, '')}?carriere=${encodeURIComponent(companyId)}`;
}

/** §demande 18/08/2026 : chaque poste ouvert porte désormais un nombre de places disponibles, pas
 * juste un nom — remplace le renderSettingsListCard générique (simples chaînes) par une carte
 * dédiée, pour ne pas alourdir ce composant partagé (utilisé ailleurs par de vraies listes de
 * chaînes, ex. Paramètres → "Postes"/"Types de contrat"...) avec un champ quantité qui ne concerne
 * que celle-ci. normalizePoste() absorbe l'ancien format (simple chaîne) déjà en base. */
function renderPostesOuvertsCard(postesOuverts) {
  const postes = (postesOuverts || []).map(normalizePoste);
  return `
    <div class="card">
      <h2>Postes ouverts au recrutement</h2>
      <div class="chip-list" style="flex-direction: column; align-items: stretch;">
        ${postes.map((poste, i) => `
          <div class="poste-ouvert-row">
            <span class="poste-ouvert-nom">${escapeHtml(poste.nom)}</span>
            <label class="poste-ouvert-qty-label">
              <span class="text-muted" style="font-size: 12px;">Places</span>
              <input type="number" class="input poste-ouvert-qty" min="1" step="1" value="${poste.quantite}" data-index="${i}">
            </label>
            <button type="button" class="chip-remove" data-index="${i}" title="Retirer">${icon(ICONS.close, 12)}</button>
          </div>
        `).join('')}
      </div>
      <form class="chip-add-form" id="form-add-poste-ouvert">
        <input type="text" class="input" id="input-poste-ouvert-nom" placeholder="Nom du poste..." required>
        <input type="number" class="input" id="input-poste-ouvert-qty" placeholder="Places" min="1" step="1" value="1" style="max-width: 90px;">
        <button type="submit" class="btn btn-secondary btn-sm">Ajouter</button>
      </form>
    </div>
  `;
}

/** §retour Betty du 18/09/2026 (point 5) : chaque poste porte 3 formes (masculin/féminin/neutre au
 * point médian, voir DEFAULT_SETTINGS.postes/parsePosteGenre, data.js) — remplace le
 * renderSettingsListCard générique (simples chaînes) pour cette liste précise, même raisonnement que
 * renderPostesOuvertsCard ci-dessus (un champ propre à cette liste, pas la peine d'alourdir le
 * composant partagé). La forme neutre reste la seule valeur stockée sur un salarié (employee.poste,
 * jamais changée) : masculin/féminin ne servent qu'à l'affichage (getPosteAccorde, data.js). */
function renderPostesCard(postes) {
  return `
    <div class="card">
      <h2>Postes</h2>
      <p class="text-muted" style="font-size:12px; margin-top:-6px;">Les formes masculine/féminine sont proposées automatiquement à partir de l'intitulé neutre (meilleur effort, jamais une grammaire française parfaite) : corrigez-les si besoin, ci-dessous.</p>
      <div class="chip-list" style="flex-direction: column; align-items: stretch;">
        ${(postes || []).map((poste, i) => `
          <div class="poste-genre-row">
            <span class="poste-genre-neutre">${escapeHtml(poste.neutre)}</span>
            <label class="poste-genre-field">
              <span class="text-muted" style="font-size: 11px;">Masculin</span>
              <input type="text" class="input poste-genre-input" data-champ="masculin" data-index="${i}" value="${escapeHtml(poste.masculin)}">
            </label>
            <label class="poste-genre-field">
              <span class="text-muted" style="font-size: 11px;">Féminin</span>
              <input type="text" class="input poste-genre-input" data-champ="feminin" data-index="${i}" value="${escapeHtml(poste.feminin)}">
            </label>
            <button type="button" class="chip-remove" data-index="${i}" title="Retirer">${icon(ICONS.close, 12)}</button>
          </div>
        `).join('')}
      </div>
      <form class="chip-add-form" id="form-add-poste">
        <input type="text" class="input" id="input-poste-neutre" placeholder="Intitulé neutre (ex. Commercial·e)..." required>
        <button type="submit" class="btn btn-secondary btn-sm">Ajouter</button>
      </form>
    </div>
  `;
}

function bindPostesCardEvents() {
  document.querySelectorAll('.poste-genre-input').forEach(input => {
    input.addEventListener('change', () => {
      const settings = settingsRepository.getSettings();
      const postes = settings.postes || [];
      const index = Number(input.dataset.index);
      postes[index][input.dataset.champ] = input.value.trim() || postes[index].neutre;
      settingsRepository.saveSettings(settings);
      showToast('Poste mis à jour.');
    });
  });

  document.querySelectorAll('.poste-genre-row .chip-remove').forEach(btn => {
    btn.addEventListener('click', () => {
      const settings = settingsRepository.getSettings();
      const postes = settings.postes || [];
      const index = Number(btn.dataset.index);
      const poste = postes[index];
      if (poste && SETTINGS_LIST_USAGE_CHECK.postes(poste.neutre)) {
        showToast(`Impossible de retirer "${poste.neutre}" : au moins un salarié a encore ce poste.`, 'error');
        return;
      }
      settings.postes = postes.filter((_, i) => i !== index);
      settingsRepository.saveSettings(settings);
      showToast('Poste retiré.');
      render();
    });
  });

  const formAjouterPoste = document.getElementById('form-add-poste');
  if (formAjouterPoste) formAjouterPoste.addEventListener('submit', (evt) => {
    evt.preventDefault();
    const input = document.getElementById('input-poste-neutre');
    const neutre = input.value.trim();
    if (!neutre) return;
    const settings = settingsRepository.getSettings();
    const postes = settings.postes || [];
    if (postes.some(p => p.neutre === neutre)) {
      showToast('Ce poste existe déjà.', 'error');
      return;
    }
    settings.postes = [...postes, { neutre, ...parsePosteGenre(neutre) }];
    settingsRepository.saveSettings(settings);
    showToast('Poste ajouté.');
    render();
  });
}

function bindPostesOuvertsEvents() {
  document.querySelectorAll('.poste-ouvert-qty').forEach(input => {
    input.addEventListener('change', () => {
      const settings = settingsRepository.getSettings();
      const postes = (settings.postesOuverts || []).map(normalizePoste);
      const index = Number(input.dataset.index);
      const quantite = Number(input.value);
      postes[index].quantite = quantite > 0 ? quantite : 1;
      settings.postesOuverts = postes;
      settingsRepository.saveSettings(settings);
      showToast('Nombre de places mis à jour.');
    });
  });

  document.querySelectorAll('.poste-ouvert-row .chip-remove').forEach(btn => {
    btn.addEventListener('click', () => {
      const settings = settingsRepository.getSettings();
      const postes = (settings.postesOuverts || []).map(normalizePoste);
      settings.postesOuverts = postes.filter((_, i) => i !== Number(btn.dataset.index));
      settingsRepository.saveSettings(settings);
      showToast('Poste retiré.');
      render();
    });
  });

  const addForm = document.getElementById('form-add-poste-ouvert');
  if (addForm) addForm.addEventListener('submit', (evt) => {
    evt.preventDefault();
    const nomInput = document.getElementById('input-poste-ouvert-nom');
    const qtyInput = document.getElementById('input-poste-ouvert-qty');
    const nom = nomInput.value.trim();
    if (!nom) return;
    const settings = settingsRepository.getSettings();
    const postes = (settings.postesOuverts || []).map(normalizePoste);
    if (postes.some(p => p.nom === nom)) {
      showToast('Ce poste existe déjà.', 'error');
      return;
    }
    const quantite = Number(qtyInput.value);
    postes.push({ nom, quantite: quantite > 0 ? quantite : 1 });
    settings.postesOuverts = postes;
    settingsRepository.saveSettings(settings);
    showToast('Poste ajouté.');
    render();
  });
}

function renderEmbauche() {
  const company = companyRepository.getCurrent();
  const settings = settingsRepository.getSettings();
  const url = candidatureUrlForCompany(company.id);
  const carriereUrl = carriereUrlForCompany(company.id);
  const qr = qrcode(0, 'M');
  qr.addData(url);
  qr.make();
  const qrSvg = qr.createSvgTag({ cellSize: 4, margin: 8, alt: 'QR code de candidature', title: 'Candidature Nexus RH' });

  return `
    <div class="view-header">
      <h1>Embauche</h1>
      <p class="view-subtitle">Affichez ce QR code (poster, page carrière...) pour recevoir des candidatures directement : CV et lettre de motivation compris, sans compte à créer.</p>
    </div>
    <div class="card" style="display: flex; gap: 24px; align-items: center; flex-wrap: wrap;">
      <div style="flex-shrink: 0; line-height: 0;">${qrSvg}</div>
      <div style="flex: 1; min-width: 240px;">
        <p class="text-muted" style="margin-bottom: 8px;">Lien de candidature directe (un seul poste, ou libre)</p>
        <div style="display: flex; gap: 8px; flex-wrap: wrap;">
          <input type="text" class="input" id="embauche-link" value="${escapeHtml(url)}" readonly style="flex: 1; min-width: 0;">
          <button type="button" class="btn btn-secondary btn-sm" id="btn-share-embauche-link">${icon(ICONS.link, 13)} Partager</button>
          <button type="button" class="btn btn-secondary btn-sm" id="btn-copy-embauche-link">Copier</button>
        </div>
        <!-- §retour Betty du 14/09/2026 (Embauche point 2, "page carrière publique") : lien distinct
             du précédent — celui-ci liste les postes un par un (voir renderCarrierePage), pensé pour
             être partagé sur un site web/réseau social plutôt qu'affiché en QR à l'accueil. -->
        <p class="text-muted" style="margin: 12px 0 8px;">Page carrière publique (liste des postes ouverts)</p>
        <div style="display: flex; gap: 8px; flex-wrap: wrap;">
          <input type="text" class="input" id="carriere-link" value="${escapeHtml(carriereUrl)}" readonly style="flex: 1; min-width: 0;">
          <button type="button" class="btn btn-secondary btn-sm" id="btn-copy-carriere-link">Copier</button>
        </div>
      </div>
    </div>
    ${renderPostesOuvertsCard(settings.postesOuverts)}
    <!-- §correctif visuel du 14/09/2026 : .table-card (padding:0, pensé pour un <table> qui a déjà
         son propre padding par cellule) laissait le titre et le message vide coller aux bords de la
         carte, sans la moindre marge — .idees-board (le tableau par étapes ci-dessous) a de toute
         façon déjà son propre overflow-x:auto (voir style.css), .table-card n'apportait donc rien
         ici. Simple .card, comme la Boîte à idées qui suit exactement le même patron. -->
    <div class="card" style="margin-top: 16px;">
      <h2>Candidatures reçues</h2>
      <div id="embauche-candidatures-list">${renderSkeletonLines(4)}</div>
    </div>
  `;
}

/** Une colonne par étape (même patron que renderIdees/idees-board) — le clic sur la carte ouvre le
 * détail complet (CV, message...), le bouton "→ étape suivante" évite cet aller-retour pour le cas
 * courant d'un simple changement de statut. */
function renderCandidatureCard(c) {
  const nextStatut = CANDIDATURE_STATUT_NEXT[c.statut];
  return `
    <div class="idee-card" data-open-candidature="${escapeHtml(c.id)}">
      <div class="idee-card-title">${personNameHtml(c)}</div>
      <div class="idee-card-meta">
        <span class="text-muted">${(c.postes || []).length ? escapeHtml(c.postes.join(', ')) : '—'} · ${formatDate(c.dateSoumission)}</span>
      </div>
      ${nextStatut ? `<button type="button" class="btn btn-secondary btn-sm" style="margin-top:8px;" data-avancer-candidature="${escapeHtml(c.id)}" data-next-statut="${nextStatut}">→ ${escapeHtml(CANDIDATURE_STATUT_LABELS[nextStatut])}</button>` : ''}
    </div>
  `;
}

function renderCandidaturesBoard(candidatures) {
  if (!candidatures.length) return '<p class="text-muted">Aucune candidature reçue pour le moment.</p>';
  const columns = Object.keys(CANDIDATURE_STATUT_LABELS).map(statut => ({
    statut,
    label: CANDIDATURE_STATUT_LABELS[statut],
    items: candidatures.filter(c => c.statut === statut)
  }));
  return `
    <div class="idees-board">
      ${columns.map(col => `
        <div class="idees-column">
          <div class="idees-column-header">
            <span>${escapeHtml(col.label)}</span>
            <span class="badge ${CANDIDATURE_STATUT_BADGE_CLASS[col.statut] || 'badge-muted'}">${col.items.length}</span>
          </div>
          ${col.items.length === 0 ? '<p class="text-muted" style="font-size:13px; margin:0;">Aucune candidature</p>' : col.items.map(renderCandidatureCard).join('')}
        </div>
      `).join('')}
    </div>
  `;
}

async function refreshEmbaucheCandidaturesList() {
  const listEl = document.getElementById('embauche-candidatures-list');
  if (!listEl) return;
  try {
    const candidatures = await candidatureRepository.getAll();
    listEl.innerHTML = renderCandidaturesBoard(candidatures);
    document.querySelectorAll('[data-open-candidature]').forEach(card => {
      card.addEventListener('click', (evt) => {
        if (evt.target.closest('[data-avancer-candidature]')) return;
        navigateTo('candidature-detail', { currentCandidatureId: card.dataset.openCandidature });
      });
    });
    document.querySelectorAll('[data-avancer-candidature]').forEach(btn => {
      btn.addEventListener('click', async (evt) => {
        evt.stopPropagation();
        btn.disabled = true;
        try {
          await candidatureRepository.avancerStatut(btn.dataset.avancerCandidature, btn.dataset.nextStatut);
          refreshEmbaucheCandidaturesList();
        } catch (err) {
          showToast(err.message || 'Impossible de changer le statut.', 'error');
          btn.disabled = false;
        }
      });
    });
  } catch (err) {
    listEl.innerHTML = '<p class="text-muted">Impossible de charger les candidatures.</p>';
  }
}

function bindEmbaucheEvents() {
  const copyBtn = document.getElementById('btn-copy-embauche-link');
  if (copyBtn) copyBtn.addEventListener('click', async () => {
    const link = document.getElementById('embauche-link');
    try {
      await navigator.clipboard.writeText(link.value);
      showToast('Lien copié.');
    } catch {
      link.select();
      showToast('Sélectionnez et copiez le lien manuellement.', 'error');
    }
  });
  // §demande 18/08/2026 : "un bouton partager normal comme sur tous les sites" — Web Share API
  // native (menu de partage du système, apps installées comprises) quand le navigateur la propose ;
  // repli sur le même copier-coller que btn-copy-embauche-link sinon (Web Share n'existe pas sur
  // tous les navigateurs desktop).
  const shareBtn = document.getElementById('btn-share-embauche-link');
  if (shareBtn) shareBtn.addEventListener('click', async () => {
    const link = document.getElementById('embauche-link').value;
    if (navigator.share) {
      try {
        await navigator.share({ title: 'Rejoignez-nous', text: 'Déposez votre candidature :', url: link });
      } catch {
        // Annulé par l'utilisateur (bouton "Annuler" du menu de partage) — pas une erreur à signaler.
      }
      return;
    }
    try {
      await navigator.clipboard.writeText(link);
      showToast('Lien copié.');
    } catch {
      showToast('Impossible de partager automatiquement, copiez le lien manuellement.', 'error');
    }
  });
  const copyCarriereBtn = document.getElementById('btn-copy-carriere-link');
  if (copyCarriereBtn) copyCarriereBtn.addEventListener('click', async () => {
    const link = document.getElementById('carriere-link');
    try {
      await navigator.clipboard.writeText(link.value);
      showToast('Lien copié.');
    } catch {
      link.select();
      showToast('Sélectionnez et copiez le lien manuellement.', 'error');
    }
  });
  bindPostesOuvertsEvents();
  refreshEmbaucheCandidaturesList();
}

// ---- Sous-vue : détail d'une candidature ----

/** "Voir tout d'un coup" (demande du 17/08/2026) : remplace les petits boutons CV/Lettre/Message
 * de la liste par une vraie page dédiée, même patron que renderTicketDetail/renderEntretienDetail
 * — un aller-retour réseau de plus (on ne garde pas les candidatures dans un state local, voir
 * candidatureRepository) mais une seule vue à maintenir pour "tout voir proprement". */
function renderCandidatureDetail(id) {
  return `
    <div class="view-header">
      <button type="button" class="btn-link" id="btn-back-embauche">← Retour aux candidatures</button>
    </div>
    <div id="candidature-detail-body">${renderSkeletonLines(5)}</div>
  `;
}

async function bindCandidatureDetailEvents(id) {
  document.getElementById('btn-back-embauche').addEventListener('click', () => navigateTo('embauche'));

  const body = document.getElementById('candidature-detail-body');
  let candidature;
  try {
    const candidatures = await candidatureRepository.getAll();
    candidature = candidatures.find(c => c.id === id);
  } catch {
    body.innerHTML = '<p class="text-muted">Impossible de charger cette candidature.</p>';
    return;
  }
  if (!candidature) {
    body.innerHTML = '<p class="text-muted">Candidature introuvable.</p>';
    return;
  }

  let cvUrl = null, lettreUrl = null;
  if (candidature.cvPath) {
    try { cvUrl = await candidatureRepository.getFileUrl(candidature.cvPath); } catch { /* affiché sans lien ci-dessous */ }
  }
  if (candidature.lettrePath) {
    try { lettreUrl = await candidatureRepository.getFileUrl(candidature.lettrePath); } catch { /* idem */ }
  }

  body.innerHTML = `
    <div class="card">
      <div class="view-header-row">
        <div>
          <h2 style="margin-bottom: 4px;">${personNameHtml(candidature)}</h2>
          <span class="badge ${CANDIDATURE_STATUT_BADGE_CLASS[candidature.statut] || 'badge-muted'}">${escapeHtml(CANDIDATURE_STATUT_LABELS[candidature.statut] || candidature.statut)}</span>
        </div>
      </div>
      <div class="detail-grid" style="margin-top: 16px;">
        ${infoRow('Email', candidature.email)}
        ${infoRow('Téléphone', candidature.telephone || '—')}
        ${infoRow('Poste(s) souhaité(s)', (candidature.postes || []).length ? candidature.postes.join(', ') : '—')}
        ${infoRow('Reçue le', formatDate(candidature.dateSoumission))}
      </div>
      <div class="detail-grid" style="margin-top: 16px;">
        <div class="form-field">
          <label>CV</label>
          ${cvUrl ? `<button type="button" class="btn btn-secondary btn-sm" onclick="window.open('${cvUrl}', '_blank', 'noopener')">Ouvrir le CV</button>` : '<p class="text-muted">Aucun CV.</p>'}
        </div>
        <div class="form-field">
          <label>Lettre de motivation</label>
          ${lettreUrl ? `<button type="button" class="btn btn-secondary btn-sm" onclick="window.open('${lettreUrl}', '_blank', 'noopener')">Ouvrir la lettre</button>` : '<p class="text-muted">Aucun fichier joint.</p>'}
        </div>
      </div>
      ${candidature.lettreTexte ? `
        <div class="form-field" style="margin-top: 16px;">
          <label>Message</label>
          <p style="white-space: pre-wrap;">${escapeHtml(candidature.lettreTexte)}</p>
        </div>
      ` : ''}
      ${['nouvelle', 'entretien', 'offre'].includes(candidature.statut) ? `
        <div class="detail-header-actions" style="margin-top: 20px;">
          <button type="button" class="btn btn-primary" id="btn-embaucher-candidature">Embaucher</button>
          <button type="button" class="btn btn-secondary" id="btn-pas-interesse-candidature">Pas intéressé</button>
        </div>
      ` : ''}
    </div>
    ${renderCandidatureCreneauxCard(candidature)}
    ${renderCandidatureEvaluationsCard(candidature)}
  `;

  const btnProposerCreneaux = document.getElementById('btn-proposer-creneaux');
  if (btnProposerCreneaux) btnProposerCreneaux.addEventListener('click', () => openProposerCreneauxModal(candidature));
  document.querySelectorAll('[data-choisir-creneau]').forEach(btn => {
    btn.addEventListener('click', async () => {
      try {
        await candidatureRepository.choisirCreneau(candidature.id, btn.dataset.choisirCreneau);
      } catch {
        showToast('Impossible d\'enregistrer la confirmation.', 'error');
        return;
      }
      showToast('Créneau marqué confirmé.');
      bindCandidatureDetailEvents(candidature.id);
    });
  });
  const btnAjouterEvaluation = document.getElementById('btn-ajouter-evaluation');
  if (btnAjouterEvaluation) btnAjouterEvaluation.addEventListener('click', () => openAjouterEvaluationModal(candidature));

  const embaucherBtn = document.getElementById('btn-embaucher-candidature');
  if (embaucherBtn) embaucherBtn.addEventListener('click', () => {
    // cvUrl n'est PAS un champ du formulaire salarié : juste transmis pour afficher un accès rapide
    // au CV pendant la saisie, sans devoir rouvrir cet onglet en parallèle.
    openEmployeeModal(null, candidatureToEmployeePrefill(candidature), candidature.id, cvUrl);
  });

  const pasInteresseBtn = document.getElementById('btn-pas-interesse-candidature');
  if (pasInteresseBtn) pasInteresseBtn.addEventListener('click', () => openRejectCandidatureModal(candidature));
}

/** Message par défaut modifiable — l'envoi réel passe par candidature-reject (Edge Function,
 * Resend) : jamais d'archivage silencieux, le candidat reçoit toujours une explication. */
function openRejectCandidatureModal(candidature) {
  const company = companyRepository.getCurrent();
  const defaultMessage = `Bonjour ${candidature.prenom || ''},\n\nNous vous remercions pour votre candidature chez ${company.raisonSociale}. Après étude de votre profil, nous avons décidé de ne pas y donner suite pour le moment.\n\nNous vous souhaitons une belle continuation dans vos recherches.\n\nCordialement,\nL'équipe ${company.raisonSociale}`;

  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>Répondre à ${personNameHtml(candidature)}</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="reject-candidature-form">
        <div class="modal-body">
          <p class="text-muted">Ce message sera envoyé par email à ${escapeHtml(candidature.email)}, puis la candidature sera archivée.</p>
          <div class="form-field">
            <label for="f-reject-message">Message</label>
            <textarea class="input" id="f-reject-message" rows="8" required>${escapeHtml(defaultMessage)}</textarea>
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="submit" class="btn btn-primary" id="btn-send-reject">Envoyer et archiver</button>
        </div>
      </form>
    </div>
  `;
  modalRoot.classList.add('open');
  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('reject-candidature-form').addEventListener('submit', async (evt) => {
    evt.preventDefault();
    const message = document.getElementById('f-reject-message').value.trim();
    if (!message) return;
    const submitBtn = document.getElementById('btn-send-reject');
    submitBtn.disabled = true;
    submitBtn.textContent = 'Envoi...';
    const result = await candidatureRepository.reject(candidature.id, message);
    if (!result.success) {
      showToast(result.error || 'Impossible d\'envoyer la réponse.', 'error');
      submitBtn.disabled = false;
      submitBtn.textContent = 'Envoyer et archiver';
      return;
    }
    closeModal();
    showToast('Réponse envoyée, candidature archivée.');
    navigateTo('embauche');
  });
}

/** §demande Betty du 09/09/2026 : le formulaire salarié (4-5 sections) reste un seul long
 * défilement — sans le redécouper en étapes (perdrait la vue d'ensemble et la possibilité de
 * corriger un champ d'une section précédente sans revenir en arrière), un sommaire cliquable en
 * haut de la modale permet de sauter directement à une section plutôt que de tout dérouler à la
 * main. `hasConfidentiel` : la section "Confidentiel" n'existe pas pour tout le monde (voir
 * renderConfidentialEmployeeFieldset) — inutile de proposer un lien mort vers une section absente. */
/** §retour Betty du 18/09/2026 (points 1+2+3+5, "vrais onglets, pas des ancres de défilement") :
 * remplace le sommaire cliquable (qui ne faisait que scroller vers une section toujours visible,
 * §demande du 09/09/2026) par de VRAIS onglets, un seul panneau affiché à la fois. Le formulaire
 * reste un <form> unique (un seul submit, une seule validation native) : seule la VISIBILITÉ des
 * fieldsets change (attribut hidden), jamais un ré-rendu de la modale (qui effacerait la saisie en
 * cours dans les autres onglets). data-employee-tab-panel sur chaque <fieldset> sert d'ancre, voir
 * bindEmployeeFormTabs/updateEmployeeFormTabErrors ci-dessous. */
const EMPLOYEE_FORM_TABS = [
  { key: 'identite', label: 'Identité' },
  { key: 'contrat', label: 'Contrat & poste' },
  { key: 'temps', label: 'Temps de travail' },
  { key: 'statut', label: 'Statut' }
];

function employeeFormTabsList(hasConfidentiel) {
  return hasConfidentiel ? [...EMPLOYEE_FORM_TABS, { key: 'confidentiel', label: 'Confidentiel' }] : EMPLOYEE_FORM_TABS;
}

function renderEmployeeFormTabs(hasConfidentiel) {
  const tabs = employeeFormTabsList(hasConfidentiel);
  return `
    <div class="tabs" role="tablist">
      ${tabs.map((t, i) => `
        <button type="button" class="tab ${i === 0 ? 'active' : ''}" data-employee-tab="${t.key}">
          ${escapeHtml(t.label)}
          <span class="tab-error-dot" id="tab-error-${t.key}" hidden title="Champ obligatoire manquant dans cet onglet"></span>
        </button>
      `).join('')}
    </div>
  `;
}

/** Un seul panneau visible à la fois (le premier par défaut) ; les autres restent dans le DOM
 * (leurs valeurs de saisie ne sont jamais perdues), simplement masqués via [hidden]. */
function bindEmployeeFormTabs() {
  const tabBtns = Array.from(document.querySelectorAll('[data-employee-tab]'));
  const panels = Array.from(document.querySelectorAll('[data-employee-tab-panel]'));
  tabBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      tabBtns.forEach(b => b.classList.toggle('active', b === btn));
      panels.forEach(p => { p.hidden = p.dataset.employeeTabPanel !== btn.dataset.employeeTab; });
    });
  });
  const form = document.getElementById('employee-form');
  form.addEventListener('input', updateEmployeeFormTabErrors);
  form.addEventListener('change', updateEmployeeFormTabErrors);
  updateEmployeeFormTabErrors();
}

/** Un point rouge sur l'onglet dès qu'un champ obligatoire y est manquant/invalide, même si cet
 * onglet n'est pas celui affiché : sans ça, un champ requis oublié dans un AUTRE onglet que celui
 * ouvert au moment du submit échouerait silencieusement (la validation native du navigateur scrolle
 * vers le premier champ invalide, mais rien ne dit qu'il n'est pas caché dans un onglet fermé). */
function updateEmployeeFormTabErrors() {
  document.querySelectorAll('[data-employee-tab-panel]').forEach(panel => {
    const invalide = Array.from(panel.querySelectorAll('[required]')).some(el => !el.checkValidity());
    const dot = document.getElementById(`tab-error-${panel.dataset.employeeTabPanel}`);
    if (dot) dot.hidden = !invalide;
  });
}

/** §retour Betty du 14/09/2026 (Embauche point 4, "candidat → salarié sans ressaisie") : le poste
 * souhaité par le candidat pré-remplit directement le poste de la fiche salarié (premier poste
 * choisi s'il y en a plusieurs — un seul poste par salarié dans Nexus). Extraite en fonction pure
 * (plutôt qu'un objet construit inline dans le handler de clic) pour rester testable sans DOM, même
 * principe que getObjectifsReconduits. */
function candidatureToEmployeePrefill(candidature) {
  return {
    nom: candidature.nom,
    prenom: candidature.prenom,
    email: candidature.email,
    telephone: candidature.telephone,
    poste: (candidature.postes || [])[0] || ''
  };
}

/** §retour Betty du 14/09/2026 ("embauche tu peux augmenté") : les deux derniers points écartés par
 * choix de conception (voir Feuille de route modules) — limités ici au suivi CÔTÉ RH, jamais un
 * vrai self-service candidat (aucun compte candidat dans Nexus, ça resterait un chantier à part
 * avec sa propre fonction Edge publique). Voir 0056_candidature_creneaux_evaluations.sql.
 *
 * Proposer de nouveaux créneaux repart toujours d'une liste vide côté serveur (voir
 * candidatureRepository.proposerCreneaux) : un id généré ici n'a donc jamais besoin d'être stable
 * entre deux propositions successives. */
function buildCreneauPropose(date, heureDebut, heureFin) {
  return { id: generateId('cr'), date, heureDebut, heureFin };
}

const EVALUATION_CANDIDATURE_CRITERES = ['Compétences techniques', 'Communication', 'Motivation', 'Adéquation avec le poste'];

function buildEvaluationRecord(evaluateurId, evaluateurNom, criteres, commentaire) {
  return {
    id: generateId('ev'),
    evaluateurId,
    evaluateurNom,
    date: new Date().toISOString(),
    criteres,
    commentaire: (commentaire || '').trim()
  };
}

/** Moyenne sur les seuls critères réellement notés (0 = "non renseigné", jamais compté) — une
 * évaluation partielle ne doit jamais fausser la moyenne vers le bas. */
function computeEvaluationMoyenne(evaluation) {
  const notes = (evaluation.criteres || []).map(c => Number(c.note)).filter(n => Number.isFinite(n) && n > 0);
  if (!notes.length) return null;
  return round2(notes.reduce((a, b) => a + b, 0) / notes.length);
}

function renderCandidatureCreneauxCard(candidature) {
  const creneaux = candidature.creneauxProposes || [];
  return `
    <div class="card" style="margin-top: 16px;">
      <div class="view-header-row">
        <h2>Créneaux d'entretien</h2>
        <button type="button" class="btn btn-secondary btn-sm" id="btn-proposer-creneaux">${creneaux.length ? 'Proposer d\'autres créneaux' : '+ Proposer des créneaux'}</button>
      </div>
      <p class="text-muted" style="margin: 0 0 8px;">À communiquer au candidat par téléphone ou email (aucun compte candidat dans Nexus) — cochez ensuite celui qu'il confirme.</p>
      ${creneaux.length === 0 ? '<p class="text-muted">Aucun créneau proposé pour l\'instant.</p>' : creneaux.map(c => {
        const choisi = candidature.creneauChoisiId === c.id;
        return `
          <div class="mini-list-item">
            <span>${formatDate(c.date)} · ${escapeHtml(c.heureDebut)}–${escapeHtml(c.heureFin)}${choisi ? ' <span class="badge badge-success">Confirmé par le candidat</span>' : ''}</span>
            ${choisi ? '' : `<button type="button" class="btn-link" data-choisir-creneau="${c.id}">Marquer confirmé</button>`}
          </div>
        `;
      }).join('')}
    </div>
  `;
}

function renderCandidatureEvaluationsCard(candidature) {
  const evaluations = candidature.evaluations || [];
  return `
    <div class="card" style="margin-top: 16px;">
      <div class="view-header-row">
        <h2>Évaluation de l'entretien</h2>
        <button type="button" class="btn btn-secondary btn-sm" id="btn-ajouter-evaluation">+ Ajouter une évaluation</button>
      </div>
      ${evaluations.length === 0 ? '<p class="text-muted">Aucune évaluation pour l\'instant.</p>' : evaluations.map(ev => {
        const moyenne = computeEvaluationMoyenne(ev);
        return `
          <div class="mini-list-item" style="align-items: flex-start; flex-direction: column; gap: 4px;">
            <div style="display: flex; justify-content: space-between; width: 100%;">
              <strong>${escapeHtml(ev.evaluateurNom || '—')}</strong>
              <span class="text-muted">${formatDate(ev.date)}${moyenne !== null ? ` · ${moyenne}/5` : ''}</span>
            </div>
            <p class="text-muted" style="margin: 0;">${(ev.criteres || []).map(c => `${escapeHtml(c.label)} : ${escapeHtml(String(c.note))}/5`).join(' · ')}</p>
            ${ev.commentaire ? `<p style="margin: 0; white-space: pre-wrap;">${escapeHtml(ev.commentaire)}</p>` : ''}
          </div>
        `;
      }).join('')}
    </div>
  `;
}

function openProposerCreneauxModal(candidature) {
  const lignes = [0, 1, 2];
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = `
    <div class="modal modal-large">
      <div class="modal-header">
        <h2>Proposer des créneaux</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="proposer-creneaux-form">
        <div class="modal-body">
          <p class="text-muted">Jusqu'à 3 créneaux, au moins un complet (date + heure de début + heure de fin).</p>
          ${lignes.map(i => `
            <div class="detail-grid" style="margin-top: 12px;">
              <div class="form-field"><label for="f-creneau-date-${i}">Date</label><input type="date" class="input" id="f-creneau-date-${i}"></div>
              <div class="form-field"><label for="f-creneau-debut-${i}">De</label><input type="time" class="input" id="f-creneau-debut-${i}"></div>
              <div class="form-field"><label for="f-creneau-fin-${i}">À</label><input type="time" class="input" id="f-creneau-fin-${i}"></div>
            </div>
          `).join('')}
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="submit" class="btn btn-primary">Enregistrer</button>
        </div>
      </form>
    </div>
  `;
  modalRoot.classList.add('open');
  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('proposer-creneaux-form').addEventListener('submit', async (evt) => {
    evt.preventDefault();
    const lignesCompletes = lignes
      .map(i => ({
        date: document.getElementById(`f-creneau-date-${i}`).value,
        heureDebut: document.getElementById(`f-creneau-debut-${i}`).value,
        heureFin: document.getElementById(`f-creneau-fin-${i}`).value
      }))
      .filter(l => l.date && l.heureDebut && l.heureFin);
    if (!lignesCompletes.length) { showToast('Renseignez au moins un créneau complet.', 'error'); return; }
    // §correctif audit du 16/09/2026 : aucun contrôle jusqu'ici sur une date déjà passée ou une
    // heure de fin avant l'heure de début — un créneau invalide partait tel quel vers le candidat.
    const today = toISODate(new Date());
    if (lignesCompletes.some(l => l.date < today)) { showToast('Un créneau ne peut pas être proposé à une date déjà passée.', 'error'); return; }
    if (lignesCompletes.some(l => l.heureFin <= l.heureDebut)) { showToast('L\'heure de fin doit être après l\'heure de début.', 'error'); return; }
    const creneaux = lignesCompletes.map(l => buildCreneauPropose(l.date, l.heureDebut, l.heureFin));
    try {
      await candidatureRepository.proposerCreneaux(candidature.id, creneaux);
    } catch {
      showToast('Impossible d\'enregistrer les créneaux.', 'error');
      return;
    }
    closeModal();
    showToast('Créneaux enregistrés.');
    bindCandidatureDetailEvents(candidature.id);
  });
}

function openAjouterEvaluationModal(candidature) {
  const user = authRepository.getCurrentUser();
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = `
    <div class="modal modal-large">
      <div class="modal-header">
        <h2>Évaluer l'entretien</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="ajouter-evaluation-form">
        <div class="modal-body">
          ${EVALUATION_CANDIDATURE_CRITERES.map((label, i) => `
            <div class="form-field" style="margin-top: 12px;">
              <label for="f-critere-${i}">${escapeHtml(label)}</label>
              <select class="input" id="f-critere-${i}">
                <option value="">Non noté</option>
                ${[1, 2, 3, 4, 5].map(n => `<option value="${n}">${n}/5</option>`).join('')}
              </select>
            </div>
          `).join('')}
          <div class="form-field" style="margin-top: 12px;">
            <label for="f-evaluation-commentaire">Commentaire</label>
            <textarea class="input" id="f-evaluation-commentaire" rows="4"></textarea>
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="submit" class="btn btn-primary">Enregistrer l'évaluation</button>
        </div>
      </form>
    </div>
  `;
  modalRoot.classList.add('open');
  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  document.getElementById('ajouter-evaluation-form').addEventListener('submit', async (evt) => {
    evt.preventDefault();
    const criteres = EVALUATION_CANDIDATURE_CRITERES
      .map((label, i) => ({ label, note: Number(document.getElementById(`f-critere-${i}`).value) || 0 }))
      .filter(c => c.note > 0);
    if (!criteres.length) { showToast('Notez au moins un critère.', 'error'); return; }
    const commentaire = document.getElementById('f-evaluation-commentaire').value;
    const nouvelle = buildEvaluationRecord(user.id, `${user.prenom} ${user.nom}`, criteres, commentaire);
    try {
      await candidatureRepository.ajouterEvaluation(candidature.id, [...(candidature.evaluations || []), nouvelle]);
    } catch {
      showToast('Impossible d\'enregistrer l\'évaluation.', 'error');
      return;
    }
    closeModal();
    showToast('Évaluation enregistrée.');
    bindCandidatureDetailEvents(candidature.id);
  });
}

/** prefill/candidatureId (voir bindEmbaucheEvents) : pré-remplit un NOUVEAU salarié depuis une
 * candidature reçue par QR code — jamais utilisé en édition (isEdit). candidatureId est juste
 * transmis jusqu'à submitEmployeeForm pour marquer la candidature "embauchée" une fois le salarié
 * réellement créé, sans dupliquer la logique de création elle-même. */
function openEmployeeModal(id, prefill, candidatureId, cvUrl) {
  const isEdit = Boolean(id);
  const employee = isEdit ? employeeRepository.getById(id) : makeEmptyEmployee();
  if (isEdit && !employee) { showToast('Ce salarié n\'est plus disponible.', 'error'); return; }
  if (!isEdit && prefill) Object.assign(employee, prefill);
  const settings = settingsRepository.getSettings();
  // §retour Betty du 18/09/2026 (point 2.2) : makeEmptyEmployee() (data.js) reste une fonction pure,
  // sans accès aux réglages de l'entreprise — 35h y est un simple repli, jamais la vraie source de
  // vérité. Une NOUVELLE fiche préremplit désormais depuis le réglage réel de l'entreprise, même
  // principe que etablissementId juste en dessous.
  if (!isEdit) employee.horairesHebdo = settings.dureeHebdomadaireReferenceHeures;
  const tempsTravailAffichage = computeTempsTravailAffichage(employee.tempsTravail, employee.forfait, employee.horairesHebdo, settings.dureeHebdomadaireReferenceHeures);
  const managers = employeeRepository.getAll().filter(e => e.id !== id && !e.archive);
  const categoriesSalarie = categorieSalarieRepository.getAll();
  const etablissements = etablissementRepository.getAll();
  const etablissementsActifs = etablissements.filter(e => e.actif);
  if (!isEdit && !employee.etablissementId) {
    employee.etablissementId = (etablissementsActifs.find(e => e.principal) || etablissementsActifs[0] || {}).id || '';
  }
  // Un établissement désactivé ne doit plus être proposable pour un NOUVEAU rattachement — mais un
  // salarié déjà rattaché à un établissement entre-temps désactivé garde son affectation visible,
  // avec son vrai nom (pas le fallback générique "valeur actuelle absente de la liste" de selectField,
  // qui échouerait ici à afficher autre chose que l'id brut).
  const etablissementsSelectables = etablissements.filter(e => e.actif || e.id === employee.etablissementId);

  const html = `
    <div class="modal modal-xlarge">
      <div class="modal-header">
        <h2>${isEdit ? 'Modifier le salarié' : 'Nouveau salarié'}</h2>
        <button class="btn-icon" id="btn-close-modal" aria-label="Fermer" title="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <form id="employee-form">
        <div class="modal-body">
          ${candidatureId && cvUrl ? `<p class="text-muted" style="margin-top:0;">Créé depuis une candidature — <button type="button" class="btn-link" onclick="window.open('${cvUrl}', '_blank', 'noopener')">voir le CV</button> pendant la saisie.</p>` : ''}
          ${renderEmployeeFormTabs(renderConfidentialEmployeeFieldset(employee, settings) !== '')}
          <fieldset class="form-section" id="employee-form-section-identite" data-employee-tab-panel="identite">
            <legend>Identité</legend>
            <div class="form-grid">
              <div class="form-field">
                <label for="f-sexe">Sexe (état civil) *</label>
                <select class="input" id="f-sexe" name="sexe" required>
                  <option value="" ${!employee.sexe ? 'selected' : ''}>—</option>
                  <option value="Homme" ${employee.sexe === 'Homme' ? 'selected' : ''}>Homme</option>
                  <option value="Femme" ${employee.sexe === 'Femme' ? 'selected' : ''}>Femme</option>
                </select>
                <p class="form-hint">Obligatoire : alimente le registre unique du personnel, la DSN et l'index de l'égalité professionnelle.</p>
              </div>
              ${selectField('civilite', 'Civilité d\'usage', null, employee.civilite, [{ value: 'Madame', label: 'Madame' }, { value: 'Monsieur', label: 'Monsieur' }, { value: 'ne_pas_accorder', label: 'Ne pas accorder' }], 'Optionnelle : accorde l\'affichage et les documents (attestations, certificat de travail...). Sans choix, déduite du sexe à l\'état civil ci-contre.')}
              ${textField('prenom', 'Prénom', employee.prenom, true)}
              ${textField('nom', 'Nom', employee.nom, true)}
              ${textField('nomUsage', 'Nom d\'usage', employee.nomUsage, false, 'text', 'any', 'Nom sous lequel le salarié souhaite être identifié au quotidien (mariage, usage personnel...), distinct du nom légal ci-dessus. Jamais utilisé sur un document officiel (registre, paie, DSN).')}
              <div class="form-field">
                <label for="f-email">Email *</label>
                <input class="input" type="email" id="f-email" name="email" value="${escapeHtml(employee.email || '')}" required
                  data-check-duplicate-email="true" data-exclude-id="${escapeHtml(employee.id || '')}">
                <span class="field-warning" id="f-email-duplicate-warning">${icon(ICONS.warningTriangle, 13)} Cet email est déjà utilisé par un autre salarié de l'entreprise.</span>
              </div>
              ${!isEdit && hasPermission(authRepository.getCurrentUser(), PERMISSIONS.GERER_UTILISATEURS) ? `
                <div class="form-field">
                  <label for="f-role">Rôle *</label>
                  <select class="input" id="f-role" name="role" required>
                    ${Object.values(ROLES).filter(r => r !== ROLES.PROPRIETAIRE).map(r => `<option value="${r}" ${r === 'salarie' ? 'selected' : ''}>${escapeHtml(ROLE_LABELS[r])}</option>`).join('')}
                  </select>
                  <p class="form-hint">Détermine ses droits dans l'application ("Poste" ci-dessous n'est qu'un intitulé, sans effet sur les accès). Modifiable ensuite depuis sa fiche, carte "Compte".</p>
                </div>
              ` : ''}
              ${textField('telephone', 'Téléphone', employee.telephone)}
              ${addressAutocompleteField('adresse.rue', 'Adresse', employee.adresse.rue, 'adresse.codePostal', 'adresse.ville')}
              ${textField('adresse.codePostal', 'Code postal', employee.adresse.codePostal)}
              ${textField('adresse.ville', 'Ville', employee.adresse.ville)}
              <div class="form-field">
                <label for="f-dateNaissance">Date de naissance</label>
                <input class="input" type="date" id="f-dateNaissance" name="dateNaissance" value="${escapeHtml(employee.dateNaissance || '')}" data-live-age="true">
                <span class="field-hint-computed" id="f-dateNaissance-age"></span>
              </div>
              ${textField('lieuNaissance', 'Lieu de naissance', employee.lieuNaissance)}
              ${textField('nationalite', 'Nationalité', employee.nationalite)}
              ${textField('numeroSecu', 'N° sécurité sociale', employee.numeroSecu)}
            </div>
          </fieldset>

          <fieldset class="form-section" id="employee-form-section-contrat" data-employee-tab-panel="contrat" hidden>
            <legend>Contrat &amp; poste</legend>
            <div class="form-grid">
              ${selectField('etablissementId', 'Établissement', null, employee.etablissementId, etablissementsSelectables.map(e => ({ value: e.id, label: e.actif ? e.nom : `${e.nom} (désactivé)` })), undefined, undefined, 'etablissements')}
              ${selectField('service', 'Service', serviceRepository.getAll().map(s => s.nom), employee.service, null, undefined, undefined, 'services')}
              ${equipeSelectField(employee.service, employee.equipe)}
              ${selectField('poste', 'Poste', null, employee.poste, (settings.postes || []).map(p => ({ value: p.neutre, label: p.neutre })), 'Intitulé neutre (point médian) : l\'affichage s\'accorde automatiquement selon le sexe du salarié (voir Paramètres &gt; Référentiels &gt; Postes pour ajuster les formes masculine/féminine).', 'postes')}
              ${multiSelectField('managerIds', 'Manager(s)', managers.map(m => ({ value: m.id, label: `${m.prenom} ${m.nom}` })), employee.managerIds)}
              ${conventionCollectiveAutocompleteField('conventionCollective', 'Convention collective', employee.conventionCollective)}
              ${selectField('categorieSalarieId', 'Catégorie de salarié', null, getEffectiveCategorieSalarieId(employee, categoriesSalarie), categoriesSalarie.map(c => ({ value: c.id, label: c.nom })), undefined, undefined, 'categoriesSalarie')}
              ${selectField('typeContrat', 'Type de contrat', settings.typesContrat, employee.typeContrat, null, undefined, 'typesContrat')}
              <div class="form-field">
                <label for="f-dateEmbauche">Date d'embauche *</label>
                <input class="input" type="date" id="f-dateEmbauche" name="dateEmbauche" value="${escapeHtml(employee.dateEmbauche || '')}" required data-live-anciennete="true">
                <span class="field-hint-computed" id="f-dateEmbauche-anciennete"></span>
              </div>
              ${textField('dateFinPeriodeEssai', 'Fin de période d\'essai', employee.dateFinPeriodeEssai, false, 'date')}
              ${textField('dateDernierEntretienProfessionnel', 'Dernier entretien professionnel', employee.dateDernierEntretienProfessionnel, false, 'date')}
              ${selectField('suiviMedicalType', 'Type de suivi médical', null, employee.suiviMedicalType || 'simple', Object.entries(SUIVI_MEDICAL_RULES).map(([key, r]) => ({ value: key, label: r.label })))}
            </div>
          </fieldset>

          <fieldset class="form-section" id="employee-form-section-temps" data-employee-tab-panel="temps" hidden>
            <legend>Temps de travail</legend>
            <div class="form-grid">
              ${selectField('tempsTravail', 'Temps de travail', ['Temps plein', 'Temps partiel'], employee.tempsTravail)}
              <div class="form-field" id="field-pourcentage-activite" ${tempsTravailAffichage.pourcentageVisible ? '' : 'hidden'}>
                <label for="f-pourcentageActivite">Pourcentage d'activité</label>
                <input class="input" type="number" id="f-pourcentageActivite" name="pourcentageActivite" value="${escapeHtml(tempsTravailAffichage.pourcentage)}" readonly>
                <p class="form-hint">Calculé automatiquement à partir des heures hebdomadaires ci-contre et de la durée de référence de l'entreprise (Paramètres &gt; Listes &gt; Salariés).</p>
              </div>
              <div class="form-field" id="field-horaires-hebdo" ${tempsTravailAffichage.horairesVisible ? '' : 'hidden'}>
                <!-- §retour QA du 27/08/2026 ("pouvoir mettre un chiffre à virgule") : un <input
                     type="number"> refuse la virgule décimale française au clavier (même avec
                     step="any", la locale du champ number reste le point, jamais la virgule) — un
                     salarié à 35h30 (35,5h) ne pouvait pas être saisi. Texte + inputmode="decimal"
                     (clavier numérique adapté sur mobile) plutôt qu'un number, avec normalisation
                     virgule/point à l'enregistrement (voir submitEmployeeForm) et à l'affichage
                     (formatNumberFR, déjà utilisé partout ailleurs pour ce champ, affiche déjà la
                     virgule française en lecture — seule la SAISIE posait problème). -->
                <label for="f-horairesHebdo">Heures hebdomadaires</label>
                <input class="input" type="text" inputmode="decimal" id="f-horairesHebdo" name="horairesHebdo" value="${escapeHtml(employee.horairesHebdo != null ? String(employee.horairesHebdo).replace('.', ',') : '')}" placeholder="35 ou 35,5">
                <p class="field-warning ${tempsTravailAffichage.avertissementL3123 ? 'visible' : ''}" id="temps-partiel-l3123-warning">${icon(ICONS.warningTriangle, 13)} Moins de 24h/semaine : la durée minimale légale d'un temps partiel est de 24h/semaine (L3123-7), sauf dérogation (étudiant, demande du salarié, accord de branche...).</p>
              </div>
              <div class="form-field" id="field-nombre-jours-forfait" ${tempsTravailAffichage.joursForfaitVisible ? '' : 'hidden'}>
                <label for="f-nombreJoursForfait">Nombre de jours par an (forfait jours)</label>
                <input class="input" type="number" id="f-nombreJoursForfait" name="nombreJoursForfait" min="1" max="218" value="${escapeHtml(employee.nombreJoursForfait || 218)}">
                <p class="form-hint">218 jours = plafond légal par défaut (L3121-64), sauf accord collectif fixant un plafond différent.</p>
              </div>
              ${selectField('forfait', 'Forfait', settings.forfaits, employee.forfait, null, 'Mode de décompte du temps de travail, distinct du Temps plein/partiel ci-dessus : "Forfait jours" compte en jours travaillés dans l\'année (cadres autonomes, pas d\'horaire précis à suivre), "Forfait heures" en heures sur une période donnée.', 'forfaits')}
              ${selectField('regimeRTT', 'Régime RTT', null, employee.regimeRTT || 'aucun', REGIME_RTT_OPTIONS, 'Jours de repos accordés en compensation d\'un temps de travail au-delà de la durée de référence. "Acquisition au réel" utilise le compteur RTT standard (Paramètres &gt; Types de congés) ; les deux autres options sont propres à ce salarié.')}
              <div class="form-field" id="field-nombre-jours-rtt-annuel" ${employee.regimeRTT === 'forfait_annuel' ? '' : 'hidden'}>
                <label for="f-nombreJoursRTTAnnuel">Nombre de jours RTT par an</label>
                <input class="input" type="number" id="f-nombreJoursRTTAnnuel" name="nombreJoursRTTAnnuel" min="0" value="${escapeHtml(employee.nombreJoursRTTAnnuel != null ? employee.nombreJoursRTTAnnuel : '')}">
              </div>
              <div class="form-field" id="field-rtt-calcul-auto" ${employee.regimeRTT === 'calcul_auto_forfait_jours' ? '' : 'hidden'}>
                <label>Estimation RTT calculée</label>
                <p class="form-hint" id="rtt-calcul-auto-resultat">${escapeHtml(libelleRegimeRTTAutoCalcul(employee, new Date().getFullYear()))}</p>
              </div>
            </div>
            <p class="form-hint" id="rtt-calcul-auto-disclaimer" ${employee.regimeRTT === 'calcul_auto_forfait_jours' ? '' : 'hidden'}>${icon(ICONS.warningTriangle, 13)} Estimation à titre indicatif (365 jours moins week-ends, 25 jours de CP, jours fériés en semaine et jours du forfait) : aucun accord d'entreprise n'encadre encore le forfait jours dans Nexus RH. Ne remplace pas une confirmation par votre expert-comptable/juriste avant d'attribuer ce nombre de jours réellement.</p>
            <div class="form-hint-block" id="forfait-jours-rappels-legaux" ${tempsTravailAffichage.joursForfaitVisible ? '' : 'hidden'}>
              <strong>Forfait jours : rappels légaux</strong>
              <ul>
                <li>L3121-58 : réservé aux cadres autonomes dans l'organisation de leur temps, ou aux salariés dont la durée ne peut être prédéterminée.</li>
                <li>L3121-63 : nécessite un accord collectif (branche ou entreprise) déterminant les modalités, pas une simple mention au contrat.</li>
                <li>L3121-55 : le forfait doit résulter d'une convention individuelle écrite avec le salarié.</li>
                <li>L3121-64 : garanties obligatoires (repos quotidien/hebdomadaire, suivi de la charge de travail, entretien annuel dédié) à la charge de l'employeur.</li>
              </ul>
            </div>
            <p class="form-subsection-title">Horaires (identiques chaque jour travaillé), utilisés par le Planning (§3).</p>
            <div class="form-grid">
              ${textField('horaireMatinDebut', 'Matin, début', employee.horaireMatinDebut || '09:00', false, 'time')}
              ${textField('horaireMatinFin', 'Matin, fin', employee.horaireMatinFin || '12:00', false, 'time')}
              ${textField('horaireApresMidiDebut', 'Après-midi, début', employee.horaireApresMidiDebut || '13:00', false, 'time')}
              ${textField('horaireApresMidiFin', 'Après-midi, fin', employee.horaireApresMidiFin || '17:00', false, 'time')}
            </div>
          </fieldset>

          <fieldset class="form-section" id="employee-form-section-statut" data-employee-tab-panel="statut" hidden>
            <legend>Statut</legend>
            <div class="form-grid">
              ${selectField('statut', 'Statut', ['Actif', 'Inactif'], employee.statut)}
            </div>
            <!-- §retour Betty du 19/09/2026 (point 1.1) : les deux dates réunies dans le même bloc,
                 après avoir constaté qu'un CDD terminé sans "date de départ" saisie (réflexe naturel :
                 seule la "date de fin de contrat", dans un AUTRE onglet, était remplie) restait compté
                 présent indéfiniment — SEULE dateDepart retire un salarié du planning/paie/tickets
                 restaurant/effectif légal (voir isEmployedDuringPeriod, getEffectifActifAt), jamais
                 dateFinContrat à elle seule. Voir aussi ensureContratsTermineDateDepartAutoDeduite
                 (data.js, reporte automatiquement à la connexion) et getDataQualityIssues (alerte
                 tant que ce n'est pas fait). -->
            <p class="form-subsection-title">Fin de contrat</p>
            <div class="form-grid">
              ${textField('dateFinContrat', 'Date de fin de contrat', employee.dateFinContrat, false, 'date', undefined, 'Date PRÉVUE au contrat (CDD, intérim, stage) — jamais la date de sortie réelle. Seule, elle ne retire le salarié de rien : ni planning, ni paie, ni effectif.')}
              ${textField('dateDepart', 'Date de départ', employee.dateDepart, false, 'date', undefined, 'Date de SORTIE RÉELLE, pour tout type de contrat, CDI compris. C\'est cette date, et elle seule, qui retire le salarié du planning, de la paie, des tickets restaurant et de l\'effectif légal (seuils à 11/50/250 salariés).')}
            </div>
            <p class="field-warning ${employee.dateFinContrat && employee.dateFinContrat <= toISODate(new Date()) && !employee.dateDepart ? 'visible' : ''}" id="fin-contrat-sans-depart-warning">
              ${icon(ICONS.warningTriangle, 13)} Date de fin de contrat passée sans date de départ : ce salarié est peut-être encore compté présent alors qu'il ne devrait plus l'être.
              <button type="button" class="btn-link" id="btn-reporter-date-depart">Reporter cette date sur le départ</button>
            </p>
            ${employee.departAutoDeduit ? `
              <div class="form-hint-block">
                ${icon(ICONS.info, 13)} Cette date de départ a été déduite automatiquement de la fin de contrat (contrat arrivé à échéance). Si le contrat a en réalité été renouvelé, effacez-la et mettez à jour le type/la date de fin de contrat ci-dessus avant d'enregistrer : enregistrer la fiche telle quelle confirmera ce départ.
              </div>
            ` : ''}
            <p class="text-muted" id="indemnite-compensatrice-hint" style="margin-top: 8px;"></p>
          </fieldset>

          ${renderConfidentialEmployeeFieldset(employee, settings)}
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" id="btn-cancel-modal">Annuler</button>
          <button type="submit" class="btn btn-primary">${isEdit ? 'Enregistrer' : 'Créer le salarié'}</button>
        </div>
      </form>
    </div>
  `;

  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = html;
  modalRoot.classList.add('open');

  document.getElementById('btn-close-modal').addEventListener('click', closeModal);
  document.getElementById('btn-cancel-modal').addEventListener('click', closeModal);
  bindEmployeeFormTabs();
  bindConventionCollectiveAutocomplete();
  document.getElementById('f-service').addEventListener('change', updateEquipeOptionsForSelectedService);
  document.getElementById('employee-form').addEventListener('submit', (evt) => submitEmployeeForm(evt, id, candidatureId));

  bindTempsTravailFields(settings);
  bindRegimeRTTFields();
  bindSexeCiviliteDefault();

  // §correctif audit du 23/08/2026 (§7.20) : "rien ne calcule ce montant ni ne le signale au moment
  // où l'on renseigne une date de départ" — mis à jour dès la saisie, pas seulement après
  // enregistrement, pour que ce soit visible AU MOMENT de la décision plutôt qu'une surprise ensuite.
  const dateDepartInput = document.getElementById('f-dateDepart');
  const updateIndemniteHint = () => {
    const hint = document.getElementById('indemnite-compensatrice-hint');
    if (!dateDepartInput.value || !isEdit || !settings.masseSalarialeActivee || !employee.salaireBrutMensuel) { hint.textContent = ''; return; }
    const { montant, joursRestants } = calculateIndemniteCompensatrice(employee, dateDepartInput.value);
    hint.textContent = joursRestants > 0
      ? `Estimation indemnité compensatrice de congés payés non pris à cette date : ${formatCurrencyFR(montant)} (${formatDurationFR(joursRestants)}) — à valider avec votre expert-comptable avant tout virement.`
      : '';
  };
  dateDepartInput.addEventListener('change', updateIndemniteHint);
  updateIndemniteHint();

  bindFinContratFields();
}

/** §retour Betty du 19/09/2026 (point 1.1) : tient à jour l'avertissement "fin de contrat passée
 * sans date de départ" en direct pendant la saisie (pas seulement au chargement de la fiche, sinon
 * corriger l'un des deux champs laisserait l'avertissement affiché ou caché à tort jusqu'au prochain
 * enregistrement). Le bouton "Reporter cette date sur le départ" ne fait que copier la valeur déjà
 * saisie dans le champ visible — l'enregistrement effectif reste le clic sur "Enregistrer", comme
 * pour toute autre modification du formulaire. */
function bindFinContratFields() {
  const dateFinContratInput = document.getElementById('f-dateFinContrat');
  const dateDepartInput = document.getElementById('f-dateDepart');
  const warning = document.getElementById('fin-contrat-sans-depart-warning');
  if (!dateFinContratInput || !dateDepartInput || !warning) return;

  const updateWarning = () => {
    const concerne = dateFinContratInput.value && dateFinContratInput.value <= toISODate(new Date()) && !dateDepartInput.value;
    warning.classList.toggle('visible', concerne);
  };
  dateFinContratInput.addEventListener('input', updateWarning);
  dateDepartInput.addEventListener('input', updateWarning);

  const reporterBtn = document.getElementById('btn-reporter-date-depart');
  if (reporterBtn) reporterBtn.addEventListener('click', () => {
    dateDepartInput.value = dateFinContratInput.value;
    dateDepartInput.dispatchEvent(new Event('change', { bubbles: true })); // recalcule l'indemnité compensatrice (voir updateIndemniteHint ci-dessus)
    updateWarning();
  });
}

/** §retour Betty du 18/09/2026 (point 3, "régime RTT structuré") : remplace l'ancien champ libre
 * "Régime RTT" (décoratif, jamais relié à rien) par un choix fermé. "acquisition_reelle" s'appuie
 * sur le compteur RTT générique déjà existant (un type de congé "RTT" comme un autre, voir
 * getLeaveBalance) ; les deux autres valeurs sont propres à CE salarié (forfait annuel fixe, ou
 * estimation calculée pour un forfait jours). Betty n'a pas encore d'accord d'entreprise encadrant
 * le forfait jours : ce champ construit le choix structuré et l'estimation, SANS jamais l'injecter
 * automatiquement dans un vrai compteur RTT (voir calculerJoursRTTAutoForfaitJours, data.js) — une
 * décision métier qui lui revient, pas un blocage technique.
 */
const REGIME_RTT_OPTIONS = [
  { value: 'aucun', label: 'Aucun' },
  { value: 'forfait_annuel', label: 'Forfait annuel avec jours' },
  { value: 'acquisition_reelle', label: 'Acquisition au réel' },
  { value: 'calcul_auto_forfait_jours', label: 'Calcul automatique (forfait jours)' }
];

function libelleRegimeRTTAutoCalcul(employee, annee) {
  if (employee.regimeRTT !== 'calcul_auto_forfait_jours') return '';
  const jours = calculerJoursRTTAutoForfaitJours(annee, employee.nombreJoursForfait || 218);
  return `${jours} jour${Math.abs(jours) > 1 ? 's' : ''} de RTT estimés pour ${annee} (forfait de ${employee.nombreJoursForfait || 218} jours).`;
}

/** Bascule le sous-champ pertinent (jours/an fixes, ou estimation calculée) selon le régime RTT
 * choisi, et recalcule l'estimation en direct si le nombre de jours du forfait change à côté. */
function bindRegimeRTTFields() {
  const regimeInput = document.getElementById('f-regimeRTT');
  const forfaitJoursInput = document.getElementById('f-nombreJoursForfait');
  const champJoursAnnuel = document.getElementById('field-nombre-jours-rtt-annuel');
  const champCalculAuto = document.getElementById('field-rtt-calcul-auto');
  const resultatCalculAuto = document.getElementById('rtt-calcul-auto-resultat');
  const disclaimer = document.getElementById('rtt-calcul-auto-disclaimer');

  const update = () => {
    const regime = regimeInput.value;
    champJoursAnnuel.hidden = regime !== 'forfait_annuel';
    const enCalculAuto = regime === 'calcul_auto_forfait_jours';
    champCalculAuto.hidden = !enCalculAuto;
    disclaimer.hidden = !enCalculAuto;
    if (enCalculAuto) {
      const nombreJoursForfait = Number(forfaitJoursInput.value) || 218;
      resultatCalculAuto.textContent = libelleRegimeRTTAutoCalcul({ regimeRTT: regime, nombreJoursForfait }, new Date().getFullYear());
    }
  };

  regimeInput.addEventListener('change', update);
  forfaitJoursInput.addEventListener('input', update);
  update();
}

/** §retour Betty du 18/09/2026 (point 5) : "civilité d'usage... défaut depuis l'état civil" — un
 * premier choix de sexe (état civil) propose une civilité d'usage cohérente, jamais une valeur
 * imposée ("M." par défaut, l'ancien comportement) : seulement une SUGGESTION au moment du premier
 * choix, jamais réécrite si la civilité a déjà été touchée (à la main, ou par ce même mécanisme). */
function bindSexeCiviliteDefault() {
  const sexeInput = document.getElementById('f-sexe');
  const civiliteInput = document.getElementById('f-civilite');
  sexeInput.addEventListener('change', () => {
    if (civiliteInput.value) return;
    if (sexeInput.value === 'Homme') civiliteInput.value = 'Monsieur';
    else if (sexeInput.value === 'Femme') civiliteInput.value = 'Madame';
  });
}

/** §retour Betty du 18/09/2026 (points 2.1/2.3) : fonction pure (testable sans DOM) déterminant
 * quels champs afficher/cacher et la valeur calculée du pourcentage d'activité, à partir de
 * Temps plein-partiel/Forfait/heures hebdomadaires/durée de référence de l'entreprise — réutilisée à
 * la fois pour le rendu initial (openEmployeeModal) et pour la mise à jour en direct
 * (bindTempsTravailFields), pour ne jamais avoir deux implémentations de la même règle. */
function computeTempsTravailAffichage(tempsTravail, forfait, horairesHebdo, dureeReference) {
  const tempsPartiel = tempsTravail === 'Temps partiel';
  const enForfaitJours = forfait === 'Forfait jours';
  const horaires = Number(horairesHebdo) || 0;
  const reference = Number(dureeReference) || 35;
  const pourcentage = tempsPartiel ? (reference > 0 ? Math.round((horaires / reference) * 1000) / 10 : 0) : 100;
  return {
    pourcentageVisible: tempsPartiel,
    horairesVisible: !enForfaitJours,
    joursForfaitVisible: enForfaitJours,
    pourcentage,
    // Sans horaire renseigné (0), rien à avertir : ce n'est pas encore "moins de 24h", c'est juste vide.
    avertissementL3123: tempsPartiel && !enForfaitJours && horaires > 0 && horaires < 24
  };
}

/** Bascule l'affichage entre pourcentage d'activité (calculé, jamais saisi directement) / heures
 * hebdomadaires / nombre de jours par an selon Temps plein-partiel et Forfait, plutôt que d'afficher
 * les 3 en permanence sans distinction — voir computeTempsTravailAffichage ci-dessus pour la règle. */
function bindTempsTravailFields(settings) {
  const tempsTravailInput = document.getElementById('f-tempsTravail');
  const horairesInput = document.getElementById('f-horairesHebdo');
  const forfaitInput = document.getElementById('f-forfait');
  const pourcentageInput = document.getElementById('f-pourcentageActivite');
  const pourcentageField = document.getElementById('field-pourcentage-activite');
  const horairesField = document.getElementById('field-horaires-hebdo');
  const joursForfaitField = document.getElementById('field-nombre-jours-forfait');
  const rappelsForfait = document.getElementById('forfait-jours-rappels-legaux');
  const warningL3123 = document.getElementById('temps-partiel-l3123-warning');

  const update = () => {
    const affichage = computeTempsTravailAffichage(tempsTravailInput.value, forfaitInput.value, horairesInput.value, settings.dureeHebdomadaireReferenceHeures);
    pourcentageField.hidden = !affichage.pourcentageVisible;
    horairesField.hidden = !affichage.horairesVisible;
    joursForfaitField.hidden = !affichage.joursForfaitVisible;
    rappelsForfait.hidden = !affichage.joursForfaitVisible;
    pourcentageInput.value = String(affichage.pourcentage);
    warningL3123.classList.toggle('visible', affichage.avertissementL3123);
  };

  tempsTravailInput.addEventListener('change', update);
  horairesInput.addEventListener('input', update);
  forfaitInput.addEventListener('change', update);
  update();
}

/** Champ "Adresse" avec suggestions en direct (API Adresse gouv.fr, gratuite/sans clé) — remplace
 * un textField() simple là où une adresse française complète est saisie : sélectionner une
 * suggestion remplit aussi automatiquement le code postal et la ville, en évitant les fautes de
 * frappe/incohérences (ex. code postal qui ne correspond pas à la ville tapée à côté). */
function addressAutocompleteField(name, label, value, codePostalName, villeName) {
  return `
    <div class="form-field address-autocomplete-field">
      <label for="f-${name}">${escapeHtml(label)}</label>
      <input class="input" type="text" id="f-${name}" name="${name}" value="${escapeHtml(value != null ? value : '')}"
        autocomplete="off" data-address-autocomplete="true"
        data-fill-codepostal="f-${codePostalName}" data-fill-ville="f-${villeName}">
      <div class="address-suggestions" id="f-${name}-suggestions"></div>
    </div>
  `;
}

/** Champ "Raison sociale" avec suggestions en direct (même API que le SIRET ci-dessus, cherchée
 * cette fois par nom plutôt que par numéro — la plupart des gens connaissent le nom de leur
 * entreprise, pas leur SIRET par cœur) : choisir une suggestion remplit aussi le SIRET et l'adresse. */
function companyNameAutocompleteField(name, label, value, required, siretName, adresseName) {
  return `
    <div class="form-field address-autocomplete-field">
      <label for="f-${name}">${escapeHtml(label)}${required ? ' *' : ''}</label>
      <input class="input" type="text" id="f-${name}" name="${name}" value="${escapeHtml(value != null ? value : '')}" ${required ? 'required' : ''}
        autocomplete="off" data-company-autocomplete="true"
        data-fill-siret="f-${siretName}" data-fill-adresse="f-${adresseName}">
      <div class="address-suggestions" id="f-${name}-suggestions"></div>
    </div>
  `;
}

/** §retour Betty du 18/09/2026 (point 4) : remplace la liste déroulante native (~180 entrées, pas
 * facile à parcourir) par une recherche texte insensible aux accents/casse (même idiome que
 * companyNameAutocompleteField/addressAutocompleteField ci-dessus : suggestions sous le champ,
 * clic pour choisir, saisie manuelle toujours possible si aucune suggestion ne convient). La
 * convention déjà retenue par l'entreprise (pinnedFirst) apparaît toujours en tête des résultats. */
function conventionCollectiveAutocompleteField(name, label, value) {
  return `
    <div class="form-field address-autocomplete-field">
      <label for="f-${name}">${escapeHtml(label)}</label>
      <input class="input" type="text" id="f-${name}" name="${name}" value="${escapeHtml(value || '')}" autocomplete="off" data-convention-autocomplete="true">
      <div class="address-suggestions" id="f-${name}-suggestions"></div>
    </div>
  `;
}

/** Secteur affiché à côté de chaque suggestion (voir IDCC_CONVENTIONS) — extrait du libellé
 * "Nom (IDCC XXXX)" déjà stocké dans settings.conventionsCollectives, jamais une seconde source de
 * vérité à maintenir en synchronisation. null pour une convention ajoutée automatiquement depuis
 * l'API (hors des ~180 courantes du catalogue statique) : pas grave, juste pas de secteur affiché. */
function secteurForConventionLabel(label) {
  const m = /\(IDCC (\d+)\)/.exec(label || '');
  if (!m) return null;
  const conv = IDCC_CONVENTIONS.find(c => c.code === m[1]);
  return conv ? conv.secteur : null;
}

/** §retour Betty du 18/09/2026 (point 4) : vérifiée moi-même (navigateur, plusieurs SIRET réels,
 * dont un sous convention Syntec confirmée : IDCC 1486) avant de choisir cette API plutôt que
 * l'autre candidate (recherche-entreprises.api.gouv.fr, déjà utilisée pour la raison sociale/
 * l'adresse ci-dessus) :
 *   - gratuite, sans clé, CORS ouvert depuis nexus-rh.com (testé en direct) ;
 *   - renvoie directement le libellé OFFICIEL de la convention ET un lien Légifrance pointant sur
 *     LE TEXTE PRÉCIS de cette convention (un identifiant Légifrance opaque, "KALICONT...", que
 *     seule cette API donne — impossible à reconstruire soi-même à partir du seul numéro IDCC) ;
 *   - "conventions": [] quand aucune convention n'est déterminée pour ce SIRET — l'autre API renvoie
 *     alors le code sentinelle "9999" ("aucune convention déterminée"), à traiter à la main.
 * Retourne null (jamais une exception) sur tout échec réseau/SIRET inconnu : une simple absence de
 * suggestion, jamais bloquant pour la saisie manuelle. */
async function fetchConventionCollectiveFromSiret(siret) {
  try {
    const res = await fetch(`https://api.recherche-entreprises.fabrique.social.gouv.fr/api/v1/etablissement/${siret}`);
    if (!res.ok) return null;
    const data = await res.json();
    const convention = (data.conventions || [])[0];
    if (!convention) return null;
    return { idcc: String(convention.idcc), label: convention.shortTitle || convention.title, url: convention.url || null };
  } catch {
    return null;
  }
}

function bindConventionCollectiveAutocomplete() {
  document.querySelectorAll('[data-convention-autocomplete]').forEach(input => {
    const suggestionsEl = document.getElementById(input.id + '-suggestions');
    if (!suggestionsEl) return;
    const showSuggestions = () => {
      const settings = settingsRepository.getSettings();
      const profile = companyRepository.getProfile();
      const q = normalizeForSearch(input.value.trim());
      let list = settings.conventionsCollectives || [];
      if (q) list = list.filter(c => normalizeForSearch(c).includes(q));
      if (profile.conventionCollective && list.includes(profile.conventionCollective)) {
        list = [profile.conventionCollective, ...list.filter(c => c !== profile.conventionCollective)];
      }
      list = list.slice(0, 30);
      if (!list.length) { suggestionsEl.style.display = 'none'; suggestionsEl.innerHTML = ''; return; }
      suggestionsEl.innerHTML = list.map(c => {
        const secteur = secteurForConventionLabel(c);
        return `<div class="address-suggestion-item" data-convention-value="${escapeHtml(c)}">${escapeHtml(c)}${secteur ? ` <span class="text-muted" style="font-size:11px;">· ${escapeHtml(secteur)}</span>` : ''}</div>`;
      }).join('');
      suggestionsEl.style.display = 'block';
    };
    input.addEventListener('input', showSuggestions);
    input.addEventListener('focus', showSuggestions);
  });

  document.addEventListener('click', (e) => {
    const item = e.target.closest('[data-convention-value]');
    if (!item) return;
    const suggestionsEl = item.closest('.address-suggestions');
    const input = suggestionsEl && document.getElementById(suggestionsEl.id.replace(/-suggestions$/, ''));
    if (input) input.value = item.dataset.conventionValue;
    if (suggestionsEl) { suggestionsEl.style.display = 'none'; suggestionsEl.innerHTML = ''; }
  });
}

/** type='number' sans step : le navigateur applique step="1" par défaut et rejette silencieusement
 * toute décimale (aucun message d'erreur applicatif, juste un blocage natif facile à manquer) — donc
 * "any" par défaut ici, jamais 1, puisqu'aucun des champs numériques du formulaire (montants,
 * pourcentages, heures...) n'a de raison métier d'interdire les décimales. */
/** §refonte "aide contextuelle" du 01/09/2026 : un "?" au survol (title natif, sans JS) plutôt qu'un
 * <p class="form-hint"> permanent sous le champ — réservé aux champs dont le libellé seul ne suffit
 * pas à comprendre l'effet (jargon RH/paie, ex. Forfait jours, Régime RTT), jamais systématique. */
function fieldHelpIcon(text) {
  return text ? `<span class="field-help" tabindex="0" title="${escapeHtml(text)}">?</span>` : '';
}

function textField(name, label, value, required, type = 'text', step = 'any', help) {
  return `
    <div class="form-field">
      <label for="f-${name}">${escapeHtml(label)}${required ? ' *' : ''}${fieldHelpIcon(help)}</label>
      <input class="input" type="${type}" id="f-${name}" name="${name}" value="${escapeHtml(value != null ? value : '')}" ${type === 'number' ? `step="${step}"` : ''} ${required ? 'required' : ''}>
    </div>
  `;
}

/** §retour Betty du 19/09/2026 ("ajouter une valeur sur place") : catalogue des listes de référence
 * simples éligibles à l'ajout rapide depuis un <select> (voir selectField ci-dessous et la
 * délégation globale dans bindGlobalEvents). `formesGenre` = la liste porte 3 formes (masculin/
 * féminin/neutre, voir parsePosteGenre) plutôt qu'une simple chaîne — seul le cas des postes aujourd'hui.
 * `sansReglage` = un message le rappelle après l'ajout (catégories de notes de frais : les réglages
 * par catégorie, justificatif obligatoire/plafond, restent à faire dans Paramètres). Étendre cette
 * liste ne suffit PAS à activer l'ajout rapide ailleurs : il faut aussi passer la 7e clé à
 * selectField() à l'endroit où le champ est rendu (voir openEmployeeModal, l'upload de document,
 * la note de frais — les seuls appelants aujourd'hui à représenter une VRAIE saisie, jamais un
 * simple filtre, où ajouter une valeur n'aurait pas de sens). */
const QUICK_ADD_LISTS = {
  // formesGenre : la liste porte 3 formes (masculin/féminin/neutre, voir parsePosteGenre) plutôt
  // qu'une simple chaîne — seul le cas des postes aujourd'hui. feminin : accord grammatical du
  // message de confirmation ("ajoutée" vs "ajouté") — rien à voir avec formesGenre ci-dessus.
  postes: { label: 'un poste', champLabel: 'Intitulé', formesGenre: true },
  typesContrat: { label: 'un type de contrat', champLabel: 'Type de contrat' },
  forfaits: { label: 'un forfait', champLabel: 'Forfait' },
  categoriesDocuments: { label: 'une catégorie de documents', champLabel: 'Catégorie de documents', feminin: true },
  categoriesFrais: { label: 'une catégorie de notes de frais', champLabel: 'Catégorie de notes de frais', feminin: true, sansReglage: true }
};

/** §retour Betty du 19/09/2026 ("ajouter une valeur sur place"), famille 2 : établissements,
 * services, équipes, catégories de salarié. Contrairement à QUICK_ADD_LISTS, ces types portent plus
 * qu'un nom (voir openQuickCreateWindow) : une PETITE FENÊTRE séparée (#quick-create-root, sibling
 * de #modal-root — jamais imbriquée dans une modale déjà ouverte, sous peine d'écraser son contenu)
 * plutôt qu'un simple champ inline. Réglages fins (adresse, description, managers d'une équipe...)
 * volontairement absents d'ici : ils restent à faire dans Paramètres. `equipes` n'a que son
 * titre/libellé ici : la logique de création elle-même reste à part (confirmQuickCreate,
 * equipeSelectField/updateEquipeOptionsForSelectedService plus haut), car une équipe a besoin du
 * service déjà choisi comme contexte, pas juste d'une clé de settings comme les 3 autres. */
const QUICK_CREATE_TYPES = {
  etablissements: { label: 'un établissement', titre: 'Créer un établissement' },
  services: { label: 'un service', titre: 'Créer un service' },
  // La LOGIQUE de création d'une équipe reste à part (confirmQuickCreate, elle a besoin du service
  // choisi comme contexte) — mais son titre/libellé viennent bien d'ici, comme les 3 autres types,
  // sinon openQuickCreateWindow (def = QUICK_CREATE_TYPES[type]) ne trouverait rien et abandonnerait
  // silencieusement à l'ouverture.
  equipes: { label: 'une équipe', titre: 'Créer une équipe', feminin: true },
  categoriesSalarie: { label: 'une catégorie de salarié', titre: 'Créer une catégorie de salarié', feminin: true }
};

/** Si la valeur actuellement enregistrée ne correspond à aucune option (ex. la liste
 * paramétrable a été renommée depuis), on l'ajoute quand même comme option sélectionnée
 * plutôt que de la laisser disparaître silencieusement — sinon un simple "Enregistrer"
 * sans toucher au champ écrase la donnée d'origine par une valeur vide.
 * quickAddListKey (optionnel) : voir QUICK_ADD_LISTS ci-dessus — ajoute une option "+ Ajouter..."
 * en fin de liste, réservée à qui gère les paramètres (écrire une liste de référence en est une
 * facette, même droit que le reste de Paramètres > Référentiels).
 * quickCreateType (optionnel, mutuellement exclusif avec quickAddListKey) : voir QUICK_CREATE_TYPES
 * plus bas — même idée, mais pour un type qui porte plus qu'un nom (établissement, catégorie de
 * salarié) : ouvre une petite fenêtre séparée (#quick-create-root) plutôt qu'un simple champ inline,
 * elle-même réservée à gererParametres. */
function selectField(name, label, options, selectedValue, customOptions, help, quickAddListKey, quickCreateType) {
  const opts = customOptions || (options || []).map(o => ({ value: o, label: o }));
  const hasValue = selectedValue !== undefined && selectedValue !== null && selectedValue !== '';
  const matchesOption = opts.some(o => String(o.value) === String(selectedValue));
  const staleOption = hasValue && !matchesOption
    ? `<option value="${escapeHtml(selectedValue)}" selected>${escapeHtml(selectedValue)} (valeur actuelle, absente de la liste)</option>`
    : '';
  const quickAddDef = quickAddListKey && QUICK_ADD_LISTS[quickAddListKey];
  const canQuickAdd = quickAddDef && hasPermission(authRepository.getCurrentUser(), PERMISSIONS.GERER_PARAMETRES);
  const quickCreateDef = quickCreateType && QUICK_CREATE_TYPES[quickCreateType];
  const canQuickCreate = quickCreateDef && hasPermission(authRepository.getCurrentUser(), PERMISSIONS.GERER_PARAMETRES);
  const quickAttrs = canQuickAdd
    ? `data-quick-add-list="${escapeHtml(quickAddListKey)}" data-quick-add-previous="${escapeHtml(hasValue ? selectedValue : '')}"`
    : canQuickCreate
      ? `data-quick-create-type="${escapeHtml(quickCreateType)}" data-quick-create-previous="${escapeHtml(hasValue ? selectedValue : '')}"`
      : '';
  return `
    <div class="form-field">
      <label for="f-${name}">${escapeHtml(label)}${fieldHelpIcon(help)}</label>
      <select class="input" id="f-${name}" name="${name}" ${quickAttrs}>
        <option value="">—</option>
        ${staleOption}
        ${opts.map(o => `<option value="${escapeHtml(o.value)}" ${String(selectedValue) === String(o.value) ? 'selected' : ''}>${escapeHtml(o.label)}</option>`).join('')}
        ${canQuickAdd ? `<option value="__quick_add__">+ Ajouter ${escapeHtml(quickAddDef.label)}...</option>` : ''}
        ${canQuickCreate ? `<option value="__quick_create__">+ Créer ${escapeHtml(quickCreateDef.label)}...</option>` : ''}
      </select>
      ${canQuickAdd ? `<div class="quick-add-inline" id="f-${name}-quick-add" hidden></div>` : ''}
    </div>
  `;
}

function multiSelectField(name, label, customOptions, selectedValues) {
  const selected = new Set((selectedValues || []).map(String));
  return `
    <div class="form-field">
      <label for="f-${name}">${escapeHtml(label)}</label>
      <select class="input" id="f-${name}" name="${name}" multiple size="4">
        ${customOptions.map(o => `<option value="${escapeHtml(o.value)}" ${selected.has(String(o.value)) ? 'selected' : ''}>${escapeHtml(o.label)}</option>`).join('')}
      </select>
      <p class="text-muted" style="margin-top: 4px; font-size: 12px;">Ctrl/Cmd + clic pour sélectionner plusieurs managers.</p>
    </div>
  `;
}

function submitEmployeeForm(evt, id, candidatureId) {
  evt.preventDefault();
  const form = evt.target;
  const formData = new FormData(form);
  const patch = { adresse: {} };

  formData.forEach((value, key) => {
    if (key === 'managerIds') return; // géré séparément : un <select multiple> répète la même clé
    if (key.startsWith('adresse.')) {
      patch.adresse[key.split('.')[1]] = value;
    } else {
      patch[key] = value;
    }
  });

  // statutPro (texte libre) reste rempli en synchronisation avec la catégorie choisie, pour que les
  // exports/documents existants qui le lisent encore restent cohérents — categorieSalarieId (ci-
  // dessus, déjà dans patch via le name du select) est désormais la source de vérité pour les règles.
  if (patch.categorieSalarieId) {
    const categorie = categorieSalarieRepository.getById(patch.categorieSalarieId);
    if (categorie) patch.statutPro = categorie.nom;
  }

  // §correctif audit du 31/08/2026 : `Number(patch.pourcentageActivite) || 100` coerce un '0' saisi
  // explicitement (Number('0') === 0, falsy) en 100 AVANT même que la validation ci-dessous ne
  // s'exécute — son branchement "<= 0" devenait donc inatteignable, et une saisie invalide (0, ou du
  // texte non numérique) était silencieusement remplacée par 100 au lieu d'être rejetée. Seul un champ
  // réellement vide (non renseigné, cas normal puisque le champ est optionnel) doit retomber sur 100.
  const pourcentageActiviteRaw = patch.pourcentageActivite;
  const pourcentageActivite = (pourcentageActiviteRaw === '' || pourcentageActiviteRaw == null) ? 100 : Number(pourcentageActiviteRaw);
  if (Number.isNaN(pourcentageActivite) || pourcentageActivite <= 0 || pourcentageActivite > 100) {
    showToast('Le pourcentage d\'activité doit être compris entre 1 et 100.', 'error');
    return;
  }
  patch.pourcentageActivite = pourcentageActivite;
  // §retour QA du 27/08/2026 : champ texte (voir openEmployeeModal), pas un <input type="number">
  // qui refusait la virgule décimale française — normalise avant conversion, un point saisi
  // directement (ou collé depuis ailleurs) reste accepté tel quel.
  patch.horairesHebdo = Number(String(patch.horairesHebdo || '').replace(',', '.')) || settingsRepository.getSettings().dureeHebdomadaireReferenceHeures;
  if ('nombreJoursForfait' in patch) patch.nombreJoursForfait = Number(patch.nombreJoursForfait) || 218;
  if ('nombreJoursRTTAnnuel' in patch) patch.nombreJoursRTTAnnuel = patch.nombreJoursRTTAnnuel === '' ? null : Number(patch.nombreJoursRTTAnnuel) || 0;
  patch.managerIds = formData.getAll('managerIds');
  if ('salaireBrutMensuel' in patch) patch.salaireBrutMensuel = Number(patch.salaireBrutMensuel) || 0;

  const emailTaken = employeeRepository.getAll().some(e =>
    e.id !== id && (e.email || '').toLowerCase().trim() === (patch.email || '').toLowerCase().trim());
  if (emailTaken) {
    showToast('Cet email est déjà utilisé par un autre salarié : la connexion serait ambiguë.', 'error');
    return;
  }

  if (patch.dateDepart && patch.dateEmbauche && patch.dateDepart < patch.dateEmbauche) {
    showToast('La date de départ ne peut pas être avant la date d\'embauche.', 'error');
    return;
  }
  if (patch.dateFinContrat && patch.dateEmbauche && patch.dateFinContrat < patch.dateEmbauche) {
    showToast('La date de fin de contrat ne peut pas être avant la date d\'embauche.', 'error');
    return;
  }

  if (id) {
    // §retour Betty du 19/09/2026 (point 1.1) : réenregistrer la fiche vaut relecture humaine du
    // report automatique de dateDepart depuis dateFinContrat (voir ensureContratsTermineDateDepartAutoDeduite,
    // data.js) — que ce report soit confirmé (la fiche est enregistrée telle quelle) ou corrigé (la
    // personne a effacé la date de départ après avoir constaté un renouvellement). Dans les deux cas,
    // l'avertissement ("à vérifier", voir getDataQualityIssues) n'a plus lieu d'être une fois la
    // fiche relue et réenregistrée.
    patch.departAutoDeduit = false;
    // §retour Betty du 18/09/2026 (point 8) : capturé AVANT update, sinon plus aucun moyen de savoir
    // si cette date de départ vient d'être renseignée (par opposition à déjà présente, resaisie
    // sans changement) une fois le patch appliqué.
    const avaitDejaDateDepart = Boolean(employeeRepository.getById(id).dateDepart);
    employeeRepository.update(id, patch);
    if (patch.dateDepart && !avaitDejaDateDepart) releaseModuleLicensesForDeparture(employeeRepository.getById(id));
    showToast('Salarié mis à jour.');
    closeModal();
    navigateTo('employee-detail', { currentEmployeeId: id });
  } else {
    // §36 : plafond de salariés de l'offre BERTOLIS — ne s'applique qu'à la création, pas à
    // l'édition (modifier un salarié existant ne change pas l'effectif).
    const abonnement = companyRepository.getCurrent().abonnement;
    const offre = (abonnement && OFFRES_BERTOLIS[abonnement.offre]) || OFFRES_BERTOLIS.essai;
    // Le plafond réel vient de abonnement.nombreSalariesMax (vraie colonne de subscriptions, mise
    // à jour par le webhook Stripe) — PAS du catalogue statique OFFRES_BERTOLIS, qui ne reflète pas
    // le cas d'une entreprise pas encore souscrite (plafond à 1 en attendant, voir migration 0012).
    const plafond = abonnement ? abonnement.nombreSalariesMax : offre.nombreSalariesMax;
    const nbActifs = employeeRepository.getAll().filter(e => !e.archive).length;
    if (plafond !== null && nbActifs >= plafond) {
      showToast(`Plafond de l'offre « ${offre.label} » atteint (${plafond} salarié${plafond > 1 ? 's' : ''}). ${abonnement && abonnement.statut === 'non_souscrit' ? 'Souscrivez une offre pour ajouter d\'autres salariés.' : 'Contactez BERTOLIS pour changer d\'offre.'}`, 'error');
      return;
    }
    const finalizeEmployeeCreation = async () => {
      // §correctif retour QA du 27/08/2026 : employeeRepository.create est désormais async — le
      // matricule est attribué par le serveur (voir DB.assignMatricule, data.js), jamais calculé
      // localement. Un échec (hors ligne, serveur injoignable) bloque volontairement la création
      // plutôt que de risquer un matricule dupliqué — voir le commentaire de DB.assignMatricule.
      const submitBtn = form.querySelector('button[type="submit"]');
      if (submitBtn) submitBtn.disabled = true;
      let created;
      try {
        created = await employeeRepository.create(patch);
      } catch (err) {
        showToast(err.message || 'Impossible de créer le salarié (connexion au serveur requise). Réessayez.', 'error');
        if (submitBtn) submitBtn.disabled = false;
        return;
      }
      if (candidatureId) {
        candidatureRepository.marquerEmbauchee(candidatureId, created.id)
          .catch(() => showToast('Salarié créé, mais la candidature n\'a pas pu être mise à jour.', 'error'));
      }
      showToast('Salarié créé.');
      closeModal();
      navigateTo('employee-detail', { currentEmployeeId: created.id });
      // §demande 19/08/2026 : enchaîne directement sur la création des identifiants de connexion —
      // jusqu'ici il fallait remarquer la carte "Compte" de la fiche salarié pour y penser. Seulement
      // si le créateur a lui-même la permission (sinon la carte "Compte" ne s'affiche pas non plus) et
      // si le salarié a un email (toujours vrai ici, le champ est obligatoire, mais gardé par sécurité).
      if (created.email && hasPermission(authRepository.getCurrentUser(), PERMISSIONS.GERER_UTILISATEURS)) {
        openCreerCompteConnexionModal(created.id);
      }
    };

    if (candidatureId) {
      // §correctif bug sweep 19/08/2026 : revérifie l'état RÉEL de la candidature (fetch direct
      // Supabase, pas le cache local) juste avant de créer le salarié — jusqu'ici la création du
      // salarié était inconditionnelle, seule la mise à jour du statut de la candidature était
      // protégée contre un double "Embaucher" (migration 0028_candidature_statut_guard.sql). Si deux
      // RH cliquaient sur la même candidature au même moment, DEUX salariés étaient créés (un seul
      // employee_id gagnait la course sur la candidature). Ferme presque toute la fenêtre (il en
      // reste une, minime, entre cette vérification et la création elle-même) sans exiger une
      // refonte serveur pour un cas volontairement traité en atténuation, pas en garantie absolue.
      candidatureRepository.getAll().then(list => {
        const fresh = list.find(c => c.id === candidatureId);
        if (fresh && fresh.statut !== 'nouvelle') {
          showToast('Cette candidature a déjà été traitée (probablement par quelqu\'un d\'autre).', 'error');
          return;
        }
        finalizeEmployeeCreation();
      }).catch(() => finalizeEmployeeCreation()); // Supabase injoignable : on ne bloque pas l'embauche pour ça.
    } else {
      finalizeEmployeeCreation();
    }
  }
}

function closeModal() {
  const modalRoot = document.getElementById('modal-root');
  modalRoot.classList.remove('open');
  modalRoot.innerHTML = '';
  if (lastFocusedBeforeModal && document.contains(lastFocusedBeforeModal)) lastFocusedBeforeModal.focus();
  lastFocusedBeforeModal = null;
  // §correctif audit du 01/09/2026 : chaque ouvreur de modale avec pièce jointe (openDocumentModal,
  // openExpenseModal, openLeaveRequestModal, openProlongerModal...) réinitialise pendingAttachment à
  // l'OUVERTURE, mais aucun ne le faisait à la fermeture — fermer une modale sans envoyer (croix,
  // clic extérieur, Échap) laissait le fichier brut de pendingAttachmentFile en mémoire. La PROCHAINE
  // modale à champ fichier facultatif, si son propre champ restait vide, uploadait alors ce fichier
  // resté en mémoire et l'attachait à un tout autre enregistrement. Un seul point de remise à zéro ici
  // couvre tous les ouvreurs, présents et futurs, plutôt que de dupliquer le reset dans chacun.
  state.pendingAttachment = null;
  state.pendingAttachmentFile = null;
  // §retour Betty du 07/09/2026 (point 5) : même raisonnement que pendingAttachment ci-dessus —
  // fermer la modale d'édition d'une note (croix, Échap) sans envoyer ne doit jamais laisser la
  // PROCHAINE ouverture de "Nouvelle note" repartir en mode modification par erreur.
  state.editingExpenseId = null;
  state.editingTeleworkRequestId = null;
}

// ---------------------------------------------------------------------------
// Boîte de confirmation réutilisable
// ---------------------------------------------------------------------------

function openConfirm({ title, message, confirmLabel, onConfirm, danger }) {
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>${escapeHtml(title)}</h2>
      </div>
      <div class="modal-body">
        <p>${escapeHtml(message)}</p>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" id="btn-confirm-cancel">Annuler</button>
        <button type="button" class="btn ${danger ? 'btn-danger' : 'btn-primary'}" id="btn-confirm-ok">${escapeHtml(confirmLabel)}</button>
      </div>
    </div>
  `;
  modalRoot.classList.add('open');
  document.getElementById('btn-confirm-cancel').addEventListener('click', closeModal);
  document.getElementById('btn-confirm-ok').addEventListener('click', () => {
    closeModal();
    onConfirm();
  });
}

/** §correctif audit du 23/08/2026 (§7.7) : variante d'openConfirm pour un refus — le motif est
 * obligatoire (bouton désactivé tant que le champ est vide), onConfirm reçoit le texte saisi.
 * Modale dédiée plutôt qu'un paramètre optionnel sur openConfirm : celui-ci reste utilisé pour des
 * confirmations sans motif (annulation...), pas la peine d'y ajouter une branche conditionnelle. */
function openRefuseModal({ title, message, onConfirm }) {
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>${escapeHtml(title)}</h2>
      </div>
      <div class="modal-body">
        <p>${escapeHtml(message)}</p>
        <div class="form-field" style="margin-top: 12px;">
          <label for="f-motif-refus">Motif du refus *</label>
          <textarea class="input" id="f-motif-refus" rows="3" required placeholder="Communiqué au salarié"></textarea>
        </div>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" id="btn-confirm-cancel">Annuler</button>
        <button type="button" class="btn btn-danger" id="btn-confirm-ok" disabled>Refuser</button>
      </div>
    </div>
  `;
  modalRoot.classList.add('open');
  const textarea = document.getElementById('f-motif-refus');
  const okBtn = document.getElementById('btn-confirm-ok');
  textarea.addEventListener('input', () => { okBtn.disabled = !textarea.value.trim(); });
  document.getElementById('btn-confirm-cancel').addEventListener('click', closeModal);
  okBtn.addEventListener('click', () => {
    const motif = textarea.value.trim();
    if (!motif) return;
    closeModal();
    onConfirm(motif);
  });
}

/** §retour Betty du 18/09/2026 (point 9) : la confirmation générique ("Cette action est
 * irréversible") ne rappelait ni que l'archivage est le chemin normal pour un départ, ni
 * l'obligation légale de conservation du registre unique du personnel (5 ans) que la suppression
 * définitive contourne. Saisie du nom en toutes lettres plutôt qu'un simple bouton "Supprimer" :
 * la friction est volontaire pour une action qui, contrairement à l'archivage, ne se rattrape pas. */
function openConfirmerSuppressionSalarieModal(employee, onConfirm) {
  const nomAttendu = `${employee.prenom} ${employee.nom}`;
  const modalRoot = document.getElementById('modal-root');
  modalRoot.innerHTML = `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>Supprimer définitivement ${escapeHtml(nomAttendu)} ?</h2>
      </div>
      <div class="modal-body">
        <p>Pour un salarié qui quitte l'entreprise, <strong>archiver</strong> est le chemin normal : ses données restent conservées, comme l'exige le registre unique du personnel (obligation légale de conservation de 5 ans après le départ).</p>
        <p>La suppression définitive efface la fiche ET ses congés, notes de frais et documents associés, de façon irréversible : à réserver à une fiche créée par erreur, jamais à un départ.</p>
        <div class="form-field" style="margin-top: 12px;">
          <label for="f-confirmation-suppression">Pour confirmer, tapez le nom du salarié : « ${escapeHtml(nomAttendu)} »</label>
          <input type="text" class="input" id="f-confirmation-suppression" autocomplete="off">
        </div>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" id="btn-confirm-cancel">Annuler</button>
        <button type="button" class="btn btn-danger" id="btn-confirm-ok" disabled>Supprimer définitivement</button>
      </div>
    </div>
  `;
  modalRoot.classList.add('open');
  const input = document.getElementById('f-confirmation-suppression');
  const okBtn = document.getElementById('btn-confirm-ok');
  input.addEventListener('input', () => { okBtn.disabled = input.value.trim() !== nomAttendu; });
  document.getElementById('btn-confirm-cancel').addEventListener('click', closeModal);
  okBtn.addEventListener('click', () => {
    if (input.value.trim() !== nomAttendu) return;
    closeModal();
    onConfirm();
  });
}

// ---------------------------------------------------------------------------
// Toasts
// ---------------------------------------------------------------------------

function showToast(message, type = 'success') {
  const container = document.getElementById('toast-root');
  const toast = document.createElement('div');
  toast.className = `toast toast-${type}`;
  toast.textContent = message;
  container.appendChild(toast);
  setTimeout(() => toast.classList.add('visible'), 10);
  setTimeout(() => {
    toast.classList.remove('visible');
    setTimeout(() => toast.remove(), 300);
  }, 3000);
}

// ---------------------------------------------------------------------------
// Délégation des liens de navigation internes (data-nav)
// ---------------------------------------------------------------------------

document.addEventListener('click', (e) => {
  const navBtn = e.target.closest('[data-nav]');
  if (navBtn) navigateTo(navBtn.dataset.nav, navBtn.dataset.navParams ? JSON.parse(navBtn.dataset.navParams) : {});
});

// ---------------------------------------------------------------------------
// Utilitaire de sécurité : échappement HTML avant injection dans le DOM
// ---------------------------------------------------------------------------

/** Minuscule + suppression des diacritiques ("Müller"/"Périgueux" → "muller"/"perigueux") — utilisé
 * partout où une recherche compare une saisie utilisateur à des données réelles, pour que la casse
 * et les accents ne fassent jamais échouer un résultat qui devrait matcher. */
function normalizeForSearch(value) {
  return (value || '').toString().normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
}

/** §retour Betty du 19/09/2026 ("ajouter une valeur sur place") : normalisation DÉDIÉE à la
 * détection de doublon dans une liste de référence — plus agressive que normalizeForSearch (la
 * recherche ne doit jamais ignorer la ponctuation, sous peine d'être trop permissive), ici on veut
 * au contraire que "CDD" et "C.D.D." soient détectés comme la même valeur : espaces, points,
 * apostrophes et points médians retirés en plus des accents/de la casse déjà gérés ci-dessus. */
function normalizeForDuplicateCheck(value) {
  return normalizeForSearch(value).replace(/[\s.’'·-]/g, '');
}

/** Cherche dans `list` (chaînes, ou objets si `field` est fourni) une valeur déjà "la même" que
 * `value` au sens de normalizeForDuplicateCheck ci-dessus. Retourne l'élément existant (jamais
 * juste un booléen) : l'appelant en a besoin pour proposer "utiliser cette valeur" plutôt qu'en
 * créer une seconde. */
function findDuplicateInList(list, value, field) {
  const target = normalizeForDuplicateCheck(value);
  if (!target) return null;
  return (list || []).find(item => normalizeForDuplicateCheck(field ? item[field] : item) === target) || null;
}

/** §retour Betty du 19/09/2026 ("ajouter une valeur sur place") : révèle un mini-formulaire JUSTE
 * SOUS le <select>, jamais une navigation ni un ré-rendu complet — le formulaire en cours (souvent
 * lui-même une modale, ex. "Modifier le salarié") ne doit jamais être perdu, exactement ce qu'elle a
 * demandé. select.value repart sur la dernière vraie valeur choisie (dataset.quickAddPrevious,
 * maintenu par la délégation globale dans bindGlobalEvents) tant que l'ajout n'est pas confirmé — l'option "+ Ajouter..."
 * elle-même ne doit jamais rester sélectionnée visuellement pendant la saisie. */
function openQuickAddInline(select) {
  const listKey = select.dataset.quickAddList;
  const def = QUICK_ADD_LISTS[listKey];
  const container = document.getElementById(select.id + '-quick-add');
  if (!def || !container) return;
  select.value = select.dataset.quickAddPrevious || '';

  const champsSaisie = def.formesGenre ? `
    <div class="form-grid">
      <div class="form-field">
        <label for="${select.id}-qa-neutre">Intitulé neutre (point médian, ex. Commercial·e)</label>
        <input class="input" type="text" id="${select.id}-qa-neutre" placeholder="Commercial·e">
      </div>
      <div class="form-field">
        <label for="${select.id}-qa-masculin">Masculin</label>
        <input class="input" type="text" id="${select.id}-qa-masculin">
      </div>
      <div class="form-field">
        <label for="${select.id}-qa-feminin">Féminin</label>
        <input class="input" type="text" id="${select.id}-qa-feminin">
      </div>
    </div>
  ` : `
    <div class="form-field">
      <label for="${select.id}-qa-value">${escapeHtml(def.champLabel)}</label>
      <input class="input" type="text" id="${select.id}-qa-value">
    </div>
  `;
  container.innerHTML = `
    <div class="quick-add-panel">
      ${champsSaisie}
      <p class="text-muted" id="${select.id}-qa-message" style="font-size: 12px; margin: 6px 0 0;"></p>
      <div class="quick-add-actions">
        <button type="button" class="btn btn-secondary btn-sm" id="${select.id}-qa-cancel">Annuler</button>
        <button type="button" class="btn btn-primary btn-sm" id="${select.id}-qa-confirm">Ajouter</button>
      </div>
    </div>
  `;
  container.hidden = false;

  if (def.formesGenre) {
    // §dépendance notée par Betty avec les postes accordés en genre (retour du 18/09/2026) :
    // masculin/féminin sont pré-remplis automatiquement (même heuristique que renderPostesCard,
    // Paramètres > Référentiels) tant que la personne ne les a pas retouchés à la main.
    const neutreInput = document.getElementById(`${select.id}-qa-neutre`);
    const masculinInput = document.getElementById(`${select.id}-qa-masculin`);
    const femininInput = document.getElementById(`${select.id}-qa-feminin`);
    let genreTouche = false;
    masculinInput.addEventListener('input', () => { genreTouche = true; });
    femininInput.addEventListener('input', () => { genreTouche = true; });
    neutreInput.addEventListener('input', () => {
      if (genreTouche) return;
      const propose = parsePosteGenre(neutreInput.value);
      masculinInput.value = propose.masculin;
      femininInput.value = propose.feminin;
    });
  }

  document.getElementById(`${select.id}-qa-cancel`).addEventListener('click', () => closeQuickAddInline(select));
  document.getElementById(`${select.id}-qa-confirm`).addEventListener('click', () => confirmQuickAdd(select, false));
  container.querySelectorAll('input').forEach(input => input.addEventListener('keydown', (e) => {
    if (e.key !== 'Enter') return;
    e.preventDefault();
    confirmQuickAdd(select, false);
  }));
  const firstInput = container.querySelector('input');
  if (firstInput) firstInput.focus();
}

function closeQuickAddInline(select) {
  const container = document.getElementById(select.id + '-quick-add');
  if (container) { container.hidden = true; container.innerHTML = ''; }
  select.value = select.dataset.quickAddPrevious || '';
}

/** forcer=true : passe outre un doublon détecté ("Ajouter quand même", voir le message affiché par
 * findDuplicateInList ci-dessous) — jamais le comportement par défaut, seulement une échappatoire
 * explicite si la personne est certaine que ce n'est PAS la même valeur malgré la normalisation. */
function confirmQuickAdd(select, forcer) {
  const listKey = select.dataset.quickAddList;
  const def = QUICK_ADD_LISTS[listKey];
  const messageEl = document.getElementById(`${select.id}-qa-message`);
  const settings = settingsRepository.getSettings();
  const list = settings[listKey] || [];

  let nouvelleValeur;
  if (def.formesGenre) {
    const neutre = document.getElementById(`${select.id}-qa-neutre`).value.trim();
    if (!neutre) { messageEl.textContent = 'L\'intitulé neutre est obligatoire.'; return; }
    const masculin = document.getElementById(`${select.id}-qa-masculin`).value.trim() || neutre;
    const feminin = document.getElementById(`${select.id}-qa-feminin`).value.trim() || neutre;
    nouvelleValeur = { neutre, masculin, feminin };
  } else {
    const valeur = document.getElementById(`${select.id}-qa-value`).value.trim();
    if (!valeur) { messageEl.textContent = 'Cette valeur ne peut pas être vide.'; return; }
    nouvelleValeur = valeur;
  }

  const compareField = def.formesGenre ? 'neutre' : null;
  const compareValue = def.formesGenre ? nouvelleValeur.neutre : nouvelleValeur;
  if (!forcer) {
    const doublon = findDuplicateInList(list, compareValue, compareField);
    if (doublon) {
      const doublonLabel = compareField ? doublon[compareField] : doublon;
      messageEl.innerHTML = `« ${escapeHtml(doublonLabel)} » existe déjà. <button type="button" class="btn-link" id="${select.id}-qa-use-existing">Utiliser cette valeur</button> · <button type="button" class="btn-link" id="${select.id}-qa-force">Ajouter quand même</button>`;
      document.getElementById(`${select.id}-qa-use-existing`).addEventListener('click', () => applyQuickAddValue(select, doublon, false));
      document.getElementById(`${select.id}-qa-force`).addEventListener('click', () => confirmQuickAdd(select, true));
      return;
    }
  }

  settings[listKey] = [...list, nouvelleValeur];
  settingsRepository.saveSettings(settings); // journalise déjà l'action (voir DB.saveSettings) : qui, quand.
  applyQuickAddValue(select, nouvelleValeur, true);
  if (def.sansReglage) {
    showToast('Configurez cette catégorie (justificatif obligatoire, plafond...) dans Paramètres > Référentiels si besoin.');
  }
}

/** Sélectionne la valeur (nouvelle ou déjà existante) dans LE select d'origine, ET synchronise
 * discrètement tous les AUTRES <select> de la même liste déjà affichés sur la page (ajoute l'option
 * si elle manque, sans jamais changer leur propre valeur choisie) — "doit apparaître tout de suite
 * dans les autres menus... sans recharger la page", exactement ce qui est demandé, sans un seul
 * appel à render(). */
function applyQuickAddValue(select, value, estNouvelle) {
  const listKey = select.dataset.quickAddList;
  const def = QUICK_ADD_LISTS[listKey];
  const optionValue = def.formesGenre ? value.neutre : value;

  document.querySelectorAll(`[data-quick-add-list="${listKey}"]`).forEach(autreSelect => {
    const existingOption = Array.from(autreSelect.options).find(o => o.value === optionValue);
    if (!existingOption) {
      const quickAddOption = Array.from(autreSelect.options).find(o => o.value === '__quick_add__');
      const opt = document.createElement('option');
      opt.value = optionValue;
      opt.textContent = optionValue;
      if (quickAddOption) autreSelect.insertBefore(opt, quickAddOption); else autreSelect.appendChild(opt);
    }
    if (autreSelect === select) autreSelect.dataset.quickAddPrevious = optionValue;
  });

  closeQuickAddInline(select); // lit dataset.quickAddPrevious, déjà mis à jour juste au-dessus.
  showToast(estNouvelle ? `« ${escapeHtml(optionValue)} » ajouté${def.feminin ? 'e' : ''}.` : 'Valeur déjà existante, sélectionnée.');
}

// ---------------------------------------------------------------------------
// Ajout rapide, famille 2 (établissements/services/équipes/catégories de salarié) — §retour Betty
// du 19/09/2026. Contrairement à la famille 1 ci-dessus (simple champ inline), ces types portent
// plus qu'un nom : une petite fenêtre séparée (#quick-create-root, sibling de #modal-root dans
// index.html, jamais imbriquée dans une modale déjà ouverte, sous peine d'écraser son contenu par
// une réassignation d'innerHTML) — voir QUICK_CREATE_TYPES plus haut.
// ---------------------------------------------------------------------------

function openQuickCreateWindow(select) {
  const type = select.dataset.quickCreateType;
  const def = QUICK_CREATE_TYPES[type];
  if (!def) return;
  select.value = select.dataset.quickCreatePrevious || '';
  quickCreateTargetSelect = select;

  const root = document.getElementById('quick-create-root');
  root.innerHTML = renderQuickCreateForm(type);
  root.classList.add('open');
  bindQuickCreateForm(type);

  const firstInput = document.getElementById('quick-create-nom');
  if (firstInput) firstInput.focus();
}

/** Champs volontairement réduits au strict indispensable (demande explicite : "les quelques champs
 * indispensables" — réglages fins laissés à Paramètres). Équipe : a besoin du service déjà choisi
 * dans le formulaire d'origine (#f-service) comme contexte, jamais un service à sélectionner ici en
 * plus — si aucun n'est encore choisi, le bouton "Créer" reste désactivé plutôt que de permettre une
 * équipe orpheline. IDs volontairement préfixés "quick-create-" (jamais "f-", déjà utilisé par les
 * champs du formulaire potentiellement ouvert derrière, dans l'AUTRE arbre DOM #modal-root) : deux
 * éléments #f-nom simultanés dans la page auraient fait pointer document.getElementById('f-nom') sur
 * le premier trouvé, presque certainement pas celui voulu ici. */
function renderQuickCreateForm(type) {
  const def = QUICK_CREATE_TYPES[type];
  let bodyHtml;
  let disableConfirm = false;

  if (type === 'equipes') {
    const serviceSelect = document.getElementById('f-service');
    const serviceNom = serviceSelect ? serviceSelect.value : '';
    const service = serviceRepository.getAll().find(s => s.nom === serviceNom);
    if (!service) {
      bodyHtml = `<p class="text-muted">Choisissez d'abord un service : une équipe se rattache toujours à un service.</p>`;
      disableConfirm = true;
    } else {
      bodyHtml = `
        <p class="text-muted" style="margin: 0 0 12px;">Service : <strong>${escapeHtml(service.nom)}</strong></p>
        <div class="form-field">
          <label for="quick-create-nom">Nom</label>
          <input class="input" type="text" id="quick-create-nom">
        </div>
      `;
    }
  } else {
    bodyHtml = `
      <div class="form-field">
        <label for="quick-create-nom">Nom</label>
        <input class="input" type="text" id="quick-create-nom">
      </div>
    `;
    if (type === 'etablissements') {
      bodyHtml += `
        <div class="form-field form-field-checkbox" style="margin-top: 10px;">
          <label><input type="checkbox" id="quick-create-actif" checked> Actif</label>
        </div>
        <div class="form-field form-field-checkbox">
          <label><input type="checkbox" id="quick-create-principal"> Établissement principal</label>
        </div>
      `;
    }
  }

  return `
    <div class="modal modal-small">
      <div class="modal-header">
        <h2>${escapeHtml(def.titre)}</h2>
        <button type="button" class="btn-icon" id="btn-quick-create-close" aria-label="Fermer">${icon(ICONS.close, 14)}</button>
      </div>
      <div class="modal-body">
        ${bodyHtml}
        <p class="text-muted" id="quick-create-message" style="font-size: 12px; margin-top: 8px;"></p>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" id="btn-quick-create-cancel">Annuler</button>
        <button type="button" class="btn btn-primary" id="btn-quick-create-confirm" ${disableConfirm ? 'disabled' : ''}>Créer</button>
      </div>
    </div>
  `;
}

function bindQuickCreateForm(type) {
  document.getElementById('btn-quick-create-close').addEventListener('click', closeQuickCreateWindow);
  document.getElementById('btn-quick-create-cancel').addEventListener('click', closeQuickCreateWindow);
  document.getElementById('btn-quick-create-confirm').addEventListener('click', () => confirmQuickCreate(type, false));
  const nomInput = document.getElementById('quick-create-nom');
  if (nomInput) {
    nomInput.addEventListener('keydown', (e) => {
      if (e.key !== 'Enter') return;
      e.preventDefault();
      confirmQuickCreate(type, false);
    });
  }
}

/** forcer=true : passe outre un doublon détecté ("Créer quand même") — jamais le comportement par
 * défaut, seulement une échappatoire explicite (même garde-fou, même mécanisme que confirmQuickAdd
 * ci-dessus pour la famille 1). */
function confirmQuickCreate(type, forcer) {
  const messageEl = document.getElementById('quick-create-message');
  const nomInput = document.getElementById('quick-create-nom');
  if (!nomInput) return; // équipe sans service choisi : pas de champ nom, rien à confirmer (bouton déjà désactivé).
  const nom = nomInput.value.trim();
  if (!nom) { messageEl.textContent = 'Le nom est obligatoire.'; return; }

  let existingList = [];
  let service = null;
  if (type === 'etablissements') existingList = etablissementRepository.getAll();
  else if (type === 'services') existingList = serviceRepository.getAll();
  else if (type === 'categoriesSalarie') existingList = categorieSalarieRepository.getAll();
  else if (type === 'equipes') {
    const serviceNom = document.getElementById('f-service').value;
    service = serviceRepository.getAll().find(s => s.nom === serviceNom);
    if (!service) { messageEl.textContent = 'Choisissez d\'abord un service.'; return; }
    existingList = service.equipes; // doublon vérifié DANS ce service seulement : le même nom d'équipe dans deux services différents n'est pas un doublon.
  }

  if (!forcer) {
    const doublon = findDuplicateInList(existingList, nom, 'nom');
    if (doublon) {
      messageEl.innerHTML = `« ${escapeHtml(doublon.nom)} » existe déjà. <button type="button" class="btn-link" id="btn-quick-create-use-existing">Utiliser cette valeur</button> · <button type="button" class="btn-link" id="btn-quick-create-force">Créer quand même</button>`;
      document.getElementById('btn-quick-create-use-existing').addEventListener('click', () => applyQuickCreateValue(type, doublon, false));
      document.getElementById('btn-quick-create-force').addEventListener('click', () => confirmQuickCreate(type, true));
      return;
    }
  }

  let created;
  if (type === 'etablissements') {
    created = etablissementRepository.create({
      nom,
      actif: document.getElementById('quick-create-actif').checked,
      principal: document.getElementById('quick-create-principal').checked
    });
  } else if (type === 'services') {
    created = serviceRepository.create(nom);
  } else if (type === 'categoriesSalarie') {
    created = categorieSalarieRepository.create({ nom });
  } else if (type === 'equipes') {
    created = DB.addEquipe(service.id, nom); // journalise déjà l'action (voir DB.addEquipe) : qui, quand.
  }

  applyQuickCreateValue(type, created, true);
}

/** Sélectionne l'objet créé (ou déjà existant, si "Utiliser cette valeur") dans LE <select> d'origine
 * (quickCreateTargetSelect), synchronise les autres <select> du même type déjà affichés sur la page,
 * puis referme la petite fenêtre — jamais un appel à render(), pour ne perdre aucun autre champ du
 * formulaire en cours (même principe qu'applyQuickAddValue ci-dessus pour la famille 1). Le 'change'
 * réellement déclenché sur le select réutilise la logique déjà existante qui en dépend (ex.
 * updateEquipeOptionsForSelectedService sur #f-service, qui rafraîchit alors #f-equipe pour le
 * nouveau service, vide d'équipes) plutôt que de la dupliquer ici. */
function applyQuickCreateValue(type, obj, estNouvelle) {
  const def = QUICK_CREATE_TYPES[type];
  const optionValue = (type === 'services' || type === 'equipes') ? obj.nom : obj.id;
  const optionLabel = type === 'etablissements' && !obj.actif ? `${obj.nom} (désactivé)` : obj.nom;
  const select = quickCreateTargetSelect;

  document.querySelectorAll(`[data-quick-create-type="${type}"]`).forEach(autreSelect => {
    const existingOption = Array.from(autreSelect.options).find(o => o.value === optionValue);
    if (!existingOption) {
      const quickCreateOption = Array.from(autreSelect.options).find(o => o.value === '__quick_create__');
      const opt = document.createElement('option');
      opt.value = optionValue;
      opt.textContent = optionLabel;
      if (quickCreateOption) autreSelect.insertBefore(opt, quickCreateOption); else autreSelect.appendChild(opt);
    }
    if (autreSelect === select) {
      autreSelect.value = optionValue;
      autreSelect.dataset.quickCreatePrevious = optionValue;
      autreSelect.dispatchEvent(new Event('change', { bubbles: true }));
    }
  });

  closeQuickCreateWindow();
  showToast(estNouvelle ? `« ${escapeHtml(obj.nom)} » créé${def.feminin ? 'e' : ''}.` : 'Valeur déjà existante, sélectionnée.');
}

function closeQuickCreateWindow() {
  const root = document.getElementById('quick-create-root');
  root.classList.remove('open');
  root.innerHTML = '';
  if (quickCreateTargetSelect) quickCreateTargetSelect.value = quickCreateTargetSelect.dataset.quickCreatePrevious || '';
  quickCreateTargetSelect = null;
}

function escapeHtml(value) {
  const str = value === null || value === undefined ? '' : String(value);
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// §correctif audit du 31/08/2026 (reuse) : "${escapeHtml(x.prenom)} ${escapeHtml(x.nom)}" était
// réécrit à la main une soixantaine de fois dans ce fichier (salarié, candidature, compte admin...),
// contrairement aux autres formatages (dates, devises, pourcentages) qui passent déjà par un helper
// central. Fonctionne pour toute entité {prenom, nom} — pas seulement un salarié.
function personNameHtml(p) {
  return `${escapeHtml(p.prenom)} ${escapeHtml(p.nom)}`;
}

